_available_regs = [
    find_reg_by_name(n)
    for n in [f't{i}' for i in range(7)] + \
             [f'a{i}' for i in range(8)] + \
             [f's{i}' for i in range(12)]
]
_saved_special_regs = [
    find_reg_by_name(n)
    for n in ['ra', 'gp', 'tp']
]
_remap_candidate_regs = _available_regs + _saved_special_regs

STACK_RANGE = 0x1000
INIT_ACCESS_ALIGN = 8
INIT_ACCESS_SLOT_WIDTH = 8
TEMP_REG = 't6'
TEMP_REG2 = 's11'
REG_PREFIX = 'rvmca_reg_'
CONCRETE_REPLAY_SP = 0x7fff00000000
CONCRETE_REPLAY_ALT_SPS = [
    CONCRETE_REPLAY_SP,
    CONCRETE_REPLAY_SP - 0x1000000000,
    0x7fff12345000,
]
MAX_INIT_SOLVE_RETRIES = 8
INIT_PTR_MIN_OFFSET = 16
LIVEIN_STORE_LOW_GUARD_OFFSET = 0x400
MAX_SP_REL_OFFSET = 1 << 40
STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD = 6
STATIC_SYMBOLIC_MUL_NODE_LIMIT = 24
GLOBAL_NO_OVERLAP_LOAD_THRESHOLD = 16
GLOBAL_NO_OVERLAP_STORE_THRESHOLD = 12
EAGER_POINTER_CONSTRAINT_LOAD_THRESHOLD = 64
MEMORY_DATAFLOW_FORCED_ALIAS_PAIR_BUDGET = 12000
LONG_BLOCK_ANCHOR_CANDIDATE_LIMIT = 4
LOAD_SLOT_PRUNE_THRESHOLD = 64
HEURISTIC_SOLVER_TIMEOUT_MS = 500
ENABLE_POINTER_LOAD_ANCHORS = False
RUNTIME_SP_ALIGNMENT = 16
MAX_AFFINE_QUOTIENT_SCALE = STACK_RANGE


def _scaled_stack_transform_for_value(
    value: int,
    sp_value: int = CONCRETE_REPLAY_SP,
    max_offset: int = STACK_RANGE,
):
    """Return the runtime-SP recipe whose shifted value matches ``value``."""
    value &= (1 << 64) - 1
    for shift in range(1, 5):
        shifted = (value << shift) & ((1 << 64) - 1)
        offset = (sp_value - shifted) & ((1 << 64) - 1)
        if offset <= max_offset and ((sp_value - offset) & ((1 << 64) - 1)) == shifted:
            return offset, shift
        offset = (shifted - sp_value) & ((1 << 64) - 1)
        if offset <= max_offset and ((sp_value + offset) & ((1 << 64) - 1)) == shifted:
            return -offset, shift
    return None


def _remap_sp_affine_mem_value(value: int, sp_value: int, recipe) -> int:
    """Materialize a memory value from its runtime-SP dependency recipe."""
    mask = (1 << 64) - 1
    value &= mask
    if (
        isinstance(recipe, (tuple, list))
        and len(recipe) == 3
        and recipe[0] == 'affine_quotient'
    ):
        return _affine_quotient_value(sp_value, recipe)
    if (
        isinstance(recipe, (tuple, list))
        and len(recipe) == 3
        and recipe[0] == 'scaled'
    ):
        offset, shift = int(recipe[1]), int(recipe[2])
        shifted = (sp_value - offset) & mask
        return shifted >> shift
    if recipe == 'inverse':
        return (value + ((CONCRETE_REPLAY_SP - sp_value) & mask)) & mask
    return (sp_value + ((value - CONCRETE_REPLAY_SP) & mask)) & mask


def _affine_quotient_value(sp_value: int, recipe) -> int:
    """Evaluate ``(sp - offset) / scale`` for a proven runtime recipe."""
    if (
        not isinstance(recipe, (tuple, list))
        or len(recipe) != 3
        or recipe[0] != 'affine_quotient'
    ):
        raise ValueError(f"invalid affine quotient recipe: {recipe!r}")
    offset, scale = int(recipe[1]), int(recipe[2])
    if scale <= 1:
        raise ValueError(f"invalid affine quotient scale: {scale}")
    return ((sp_value - offset) & ((1 << 64) - 1)) // scale


def _runtime_reg_recipe_value(sp_value: int, recipe) -> int:
    """Evaluate a proven runtime-SP register materialization recipe."""
    if (
        isinstance(recipe, (tuple, list))
        and len(recipe) == 3
        and recipe[0] == 'affine_linear'
    ):
        _, anchor_value, coefficient = recipe
        coefficient = int(coefficient)
        if coefficient == 0:
            raise ValueError(f"invalid affine linear coefficient: {coefficient}")
        sp_delta = (sp_value - CONCRETE_REPLAY_SP) & ((1 << 64) - 1)
        return (
            int(anchor_value) + coefficient * sp_delta
        ) & ((1 << 64) - 1)
    if (
        isinstance(recipe, (tuple, list))
        and len(recipe) == 3
        and recipe[0] == 'affine_quotient'
    ):
        return _affine_quotient_value(sp_value, recipe)
    if (
        isinstance(recipe, (tuple, list))
        and len(recipe) == 4
        and recipe[0] == 'affine_scaled_quotient'
    ):
        _, offset, divisor, multiplier = recipe
        if divisor <= 0 or multiplier <= 0:
            raise ValueError(f"invalid affine scaled quotient recipe: {recipe!r}")
        quotient = (
            (sp_value - int(offset)) & ((1 << 64) - 1)
        ) // int(divisor)
        return (quotient * int(multiplier)) & ((1 << 64) - 1)
    raise ValueError(f"invalid runtime register recipe: {recipe!r}")


def _runtime_recipe_address(sp_value: int, recipe, addr_const: int) -> int:
    """Evaluate the address driven by a quotient-based register recipe."""
    if not isinstance(recipe, (tuple, list)) or len(recipe) not in {3, 4}:
        raise ValueError(f"invalid runtime address recipe: {recipe!r}")
    if recipe[0] not in {'affine_quotient', 'affine_scaled_quotient'}:
        raise ValueError(f"invalid runtime address recipe: {recipe!r}")
    _, offset, divisor, *_ = recipe
    if divisor <= 0:
        raise ValueError(f"invalid runtime address divisor: {divisor}")
    quotient = (
        (sp_value - int(offset)) & ((1 << 64) - 1)
    ) // int(divisor)
    return (quotient * int(divisor) + int(addr_const)) & ((1 << 64) - 1)


def _affine_quotient_remainders(
    offset: int,
    scale: int,
    sp_alignment: int = RUNTIME_SP_ALIGNMENT,
):
    """Return all division remainders possible for aligned runtime SP values."""
    if scale <= 1 or sp_alignment <= 0:
        return ()
    period = math.lcm(scale, sp_alignment)
    return tuple(sorted({
        (sp_residue - offset) % scale
        for sp_residue in range(0, period, sp_alignment)
    }))


class UnsupportedBlockError(RuntimeError):
    """Raised for blocks outside the current sp-relative init strategy."""


class ConcreteReplayFailure(AssertionError):
    """Raised when the solver model cannot be replayed concretely."""

    def __init__(self, message: str, candidate_init=None):
        super().__init__(message)
        self.candidate_init = candidate_init


def _stage_file_for_name(name: str) -> Path:
    return Path(str(OUTPUT_PATH / name) + ".stage.json")


def _write_profile_stage(name: str, stage: str, **extra):
    data = {
        "name": name,
        "stage": stage,
        "time": time.time(),
    }
    data.update(extra)
    _stage_file_for_name(name).write_text(json.dumps(data, sort_keys=True), encoding="utf-8")


def _align_up(value: int, align: int) -> int:
    return ((value + align - 1) // align) * align


def _signed_u64(value: int) -> int:
    value &= (1 << 64) - 1
    if value & (1 << 63):
        return value - (1 << 64)
    return value


def find_regs_no_def(prog: Program) -> List[Reg]:
    """find undefined registers"""
    check_block_validity(prog)

    regs_defined = set()
    regs_defined.add(XREG[0])

    regs_no_def = set()

    for inst in prog.insts:
        for r in inst.get_uses():
            if r not in regs_defined:
                regs_no_def.add(r)
        r = inst.get_def()
        if r:
            regs_defined.add(r)
    return list(regs_no_def)


def find_addr_regs(prog: Program) -> List[Tuple[int, Reg]]:
    """find address registers"""
    check_block_validity(prog)

    addr_regs = []

    for i, inst in enumerate(prog.insts):
        inst = prog.insts[i]
        addr = inst.get_addr()
        if addr:
            addr_regs.append((i, addr))
    return addr_regs


def remap_regs_for_block(prog: Program, candidate_regs=None) -> Program:
    """Remap registers for a block"""
    if candidate_regs is None:
        candidate_regs = _remap_candidate_regs
    check_block_validity(prog)

    prog = copy.deepcopy(prog)

    regs = set()
    for inst in prog.insts:
        for reg in inst.get_regs():
            # FIXME: we only consider xregs for now
            if reg in XREG:
                regs.add(reg)
    need_remap = [r for r in regs if r not in candidate_regs]

    if XREG[0] in need_remap:
        need_remap.remove(XREG[0])

    available_regs = [r for r in candidate_regs if r not in regs]
    if len(need_remap) > len(available_regs):
        raise UnsupportedBlockError("not enough safe registers for remapping")

    x_need_remap, f_need_remap = [], []
    for reg in need_remap:
        if reg in XREG:
            x_need_remap.append(reg)
        elif reg in FREG:
            f_need_remap.append(reg)
        else:
            raise ValueError(f'Unsupported reg type: {reg.type}')

    x_available, f_available = [], []
    for reg in available_regs:
        if reg in XREG:
            x_available.append(reg)
        elif reg in FREG:
            f_available.append(reg)
        else:
            raise ValueError(f'Unsupported reg type: {reg.type}')

    if Reg(0) in x_available:
        x_available.remove(Reg(0))

    if len(x_need_remap) > len(x_available):
        raise UnsupportedBlockError("not enough safe x-registers for remapping")
    if len(f_need_remap) > len(f_available):
        raise UnsupportedBlockError("not enough safe f-registers for remapping")

    def map_regs(srcs, tgts):
        map_table = {
            srcs[i]: tgts[i]
            for i in range(len(srcs))
        }
        for inst in prog.insts:
            r = inst.get_def()
            if r and r in srcs:
                inst.set_def(map_table[r])
            new_uses = []
            for r in inst.get_uses():
                if r in srcs:
                    new_uses.append(map_table[r])
                else:
                    new_uses.append(r)
            inst.set_uses(new_uses)

    map_regs(x_need_remap, x_available)
    map_regs(f_need_remap, f_available)

    return prog


def add_undef_reg_checking(prog: Program, undefined_regs: List) -> Program:
    prog = copy.deepcopy(prog)
    insts = [
        BFmtInst('blt', reg.name, 'x0', label='fail')
        for reg in undefined_regs
    ]
    prog.insts = insts + prog.insts
    return prog


def choose_addr_check_temp_reg(prog: Program) -> str:
    used_regs = set()
    for inst in prog.insts:
        used_regs.update(r for r in inst.get_regs() if r in XREG)

    candidates = []
    for reg_name in [TEMP_REG, TEMP_REG2]:
        reg = find_reg_by_name(reg_name)
        if reg not in candidates:
            candidates.append(reg)
    for reg in _available_regs:
        if reg not in candidates:
            candidates.append(reg)

    for reg in candidates:
        if reg not in used_regs and reg not in [XREG[0], XREG[2]]:
            return reg.name

    raise UnsupportedBlockError("no free register for address-check instrumentation")


def append_addi_chunks(insts: List[Inst], reg: str, value: int):
    while value:
        chunk = min(2047, value) if value > 0 else max(-2048, value)
        insts.append(IFmtInst('addi', reg, reg, chunk))
        value -= chunk


def add_addr_range_checking(prog: Program, temp_reg: str = None) -> Program:
    """Add address checking for a block"""

    if temp_reg is None:
        try:
            temp = choose_addr_check_temp_reg(prog)
        except UnsupportedBlockError:
            # Some long blocks use every candidate GPR.  The range checks are
            # only a symbolic-execution guard; the materialized init path still
            # constrains every concrete memory access into the synthetic stack.
            return copy.deepcopy(prog)
    else:
        temp = temp_reg
    check_block_validity(prog)

    prog = copy.deepcopy(prog)
    insts = []
    for inst in prog.insts:
        if inst.type in [IType.Load, IType.Store, IType.Amo]:
            addr = inst.get_addr()
            imm = _signed_u64(inst.imm)
            # temp = base + offset
            insts.append(UFmtInst('li', temp, abs(imm)))
            if imm >= 0:
                insts.append(RFmtInst('add', temp, str(addr), temp))  # 计算实际地址
            else:
                insts.append(RFmtInst('sub', temp, str(addr), temp))
            # temp < sp
            insts.append(BFmtInst('bge', temp, 'sp', label='fail'))
            # temp >= sp - STACK_RANGE
            append_addi_chunks(insts, temp, STACK_RANGE)
            insts.append(BFmtInst('blt', temp, 'sp', label='fail'))
            if inst.width > 1:
                # check address alignment
                mask = inst.width - 1
                append_addi_chunks(insts, temp, -STACK_RANGE)  # 还原回实际地址
                insts.append(IFmtInst('andi', temp, temp, mask))  # 检查地址对齐
                insts.append(BFmtInst('bne', temp, 'x0', label='fail'))
        # if inst.type in [IType.Load, IType.Store, IType.Amo]:
        #     addr = inst.get_addr()
        #     imm = inst.imm

        #     insts.append(UFmtInst('li', temp, imm))
        #     insts.append(RFmtInst('add', temp, str(addr), temp)) # temp = 实际地址

        #     # A. 检查对齐 (在 temp 被加 STACK_RANGE 之前)
        #     if inst.width > 1:
        #         mask = inst.width - 1
        #         # 技巧：如果我们只有一个 temp，可以先算对齐，不合规则直接 fail
        #         # 如果合规，对齐位必然是0，这时 temp 其实没变（或者说变了也没关系，因为后面可以靠 addi 补回来）
        #         # 但最稳妥的是如果有 TEMP_REG2 (如 t1)，直接：
        #         # insts.append(IFmtInst('andi', TEMP_REG2, temp, mask))
        #         # insts.append(BFmtInst('bne', TEMP_REG2, 'x0', label='fail'))

        #     # B. 检查上限：temp < sp
        #     insts.append(BFmtInst('bge', temp, 'sp', label='fail'))

        #     # C. 检查下限：temp >= sp - STACK_RANGE
        #     # 这里不可避免要修改 temp
        #     insts.append(IFmtInst('addi', temp, temp, STACK_RANGE))
        #     insts.append(BFmtInst('blt', temp, 'sp', label='fail'))

        #     # 此时不需要 addi temp, temp, -STACK_RANGE 了，
        #     # 因为原始指令 inst 会使用原来的 rs1+imm，不依赖 temp 里的值

        insts.append(inst)
    prog.insts = insts
    return prog


def _riscv_u_format_value(imm: int) -> int:
    """Return the sign-extended value produced by a RISC-V U immediate."""
    imm &= (1 << 20) - 1
    if imm & (1 << 19):
        imm -= 1 << 20
    return imm << 12


def fix_lui_auipc_imm(prog: Program) -> Program:
    """Rebase related lui/auipc immediates without destroying differences.

    U-format values that contribute to the same memory address form one
    address family.  Subtracting one shared reference inside each family keeps
    its relative offsets while allowing unrelated constants to be zeroed
    independently.

    Args:
        prog: The program to modify

    Returns:
        Modified program
    """
    prog = copy.deepcopy(prog)
    u_insts = [
        inst
        for inst in prog.insts
        if isinstance(inst, UFmtInst) and inst.name in {'lui', 'auipc'}
    ]
    if not u_insts:
        return prog

    imm_bits = 20
    imm_mask = (1 << imm_bits) - 1
    imm_sign = 1 << (imm_bits - 1)

    def signed_imm(imm):
        imm &= imm_mask
        return imm - (1 << imm_bits) if imm & imm_sign else imm

    inst_to_idx = {id(inst): idx for idx, inst in enumerate(u_insts)}
    lui_source_indices = {
        idx for idx, inst in enumerate(u_insts) if inst.name == 'lui'
    }
    parents = list(range(len(u_insts)))

    def find(idx):
        while parents[idx] != idx:
            parents[idx] = parents[parents[idx]]
            idx = parents[idx]
        return idx

    def union(indices):
        indices = list(indices)
        for idx in indices[1:]:
            lhs = find(indices[0])
            rhs = find(idx)
            if lhs != rhs:
                parents[rhs] = lhs

    reg_sources = {}
    reg_dynamic = {XREG[0]: False}
    arithmetic_literal_sources = set()

    def is_dynamic(reg):
        # A register read before its first definition is a live-in.
        return reg_dynamic.get(reg, reg != XREG[0])

    for inst in prog.insts:
        if id(inst) in inst_to_idx:
            reg_sources[inst.rd] = {inst_to_idx[id(inst)]}
            reg_dynamic[inst.rd] = False
            continue

        if inst.type in {IType.Load, IType.Store, IType.Amo}:
            union(
                reg_sources.get(inst.rs1, set())
                - arithmetic_literal_sources
            )
            defined = inst.get_def()
            if defined is not None:
                reg_sources[defined] = set()
                reg_dynamic[defined] = True
            continue

        if isinstance(inst, RFmtInst):
            rs1_sources = set(reg_sources.get(inst.rs1, set()))
            rs2_sources = set(reg_sources.get(inst.rs2, set()))
            if inst.name in {'mulh', 'mulhsu', 'mulhu'}:
                if rs1_sources and not is_dynamic(inst.rs1) and is_dynamic(inst.rs2):
                    arithmetic_literal_sources.update(rs1_sources & lui_source_indices)
                if rs2_sources and not is_dynamic(inst.rs2) and is_dynamic(inst.rs1):
                    arithmetic_literal_sources.update(rs2_sources & lui_source_indices)
            reg_sources[inst.rd] = (
                rs1_sources | rs2_sources
            )
            reg_dynamic[inst.rd] = is_dynamic(inst.rs1) or is_dynamic(inst.rs2)
            continue

        if isinstance(inst, IFmtInst):
            reg_sources[inst.rd] = set(reg_sources.get(inst.rs1, set()))
            reg_dynamic[inst.rd] = is_dynamic(inst.rs1)
            continue

        defined = inst.get_def()
        if defined is not None:
            reg_sources[defined] = set()
            reg_dynamic[defined] = True

    groups = {}
    for idx, inst in enumerate(u_insts):
        if idx in arithmetic_literal_sources:
            continue
        groups.setdefault(find(idx), []).append(inst)

    for group in groups.values():
        signed_imms = [signed_imm(inst.imm) for inst in group]
        min_imm = min(signed_imms)
        max_imm = max(signed_imms)
        # The symbolic U-format model treats its immediate as non-negative,
        # while real RISC-V execution sign-extends bit 19.  Keep normalized
        # immediates in their common non-negative range so replay and QEMU see
        # the same value.
        reference = min_imm if max_imm - min_imm < imm_sign else None

        for inst, imm in zip(group, signed_imms):
            inst.imm = 0 if reference is None else imm - reference
    return prog


def has_lui_auipc(prog: Program) -> bool:
    return any(isinstance(inst, UFmtInst) and inst.name in ['lui', 'auipc'] for inst in prog.insts)


def find_unmappable_fixed_address_access(prog: Program):
    """Find memory accesses rooted only in a fixed lui/auipc address.

    The profiler can synthesize stack-relative values for unknown registers or
    load-produced pointers, and it can also absorb small lui constants when they
    are added to sp.  A direct global/GOT/static access such as

        auipc a5, imm
        ld    a5, off(a5)

    is different: the accessed address is fixed by PC/global layout, not by the
    block input context, so rewriting it into the synthetic stack would no
    longer measure the original block semantics.
    """

    def const_expr(value):
        return ('const', value & ((1 << 64) - 1))

    def sign_extend(value, bits):
        sign_bit = 1 << (bits - 1)
        mask = (1 << bits) - 1
        value &= mask
        return value - (1 << bits) if value & sign_bit else value

    def load_range(inst):
        bits = inst.width * 8
        if inst.name in {'lb', 'lh', 'lw'}:
            return (-(1 << (bits - 1)), (1 << (bits - 1)) - 1)
        if inst.name in {'lbu', 'lhu', 'lwu'}:
            return (0, (1 << bits) - 1)
        return None

    def fixed_expr(inst):
        return ('fixed', inst.name, inst.imm, inst.pc)

    def reg_expr(reg):
        if reg == XREG[0]:
            return const_expr(0)
        if reg == XREG[2]:
            return ('sp',)
        return env.get(reg, ('reg', reg))

    def op_expr(op, *args):
        return (op, *args)

    def expr_has(expr, kind):
        if not isinstance(expr, tuple):
            return False
        if expr and expr[0] == kind:
            return True
        return any(expr_has(arg, kind) for arg in expr[1:] if isinstance(arg, tuple))

    def is_dynamic(expr):
        return any(expr_has(expr, kind) for kind in ('sp', 'reg', 'load', 'unknown'))

    def is_fixed_only_address(expr):
        return expr_has(expr, 'fixed') and not is_dynamic(expr)

    def is_unmappable_fixed_address(expr):
        return (
            expr_has(expr, 'fixed_spill')
            and not expr_has(expr, 'sp')
            and not expr_has(expr, 'load')
        )

    def interval(expr):
        if not isinstance(expr, tuple) or not expr:
            return None
        kind = expr[0]
        if kind == 'const':
            value = _signed_u64(expr[1])
            return (value, value)
        if kind == 'fixed':
            _, op, imm, pc = expr
            high = sign_extend(imm << 12, 32)
            value = high if op == 'lui' else pc + high
            return (value, value)
        if kind == 'load':
            return expr[3]
        if kind == 'fixed_spill':
            return interval(expr[1])
        if kind == 'sext32':
            child = interval(expr[1])
            if child is None:
                return None
            lo, hi = child
            if lo < -(1 << 31) or hi > (1 << 31) - 1:
                return (-(1 << 31), (1 << 31) - 1)
            return child
        if kind in {'add', 'sub'}:
            lhs = interval(expr[1])
            rhs = interval(expr[2])
            if lhs is None or rhs is None:
                return None
            if kind == 'add':
                return (lhs[0] + rhs[0], lhs[1] + rhs[1])
            return (lhs[0] - rhs[1], lhs[1] - rhs[0])
        if kind in {'slli', 'mul'}:
            lhs = interval(expr[1])
            rhs = interval(expr[2])
            if lhs is None or rhs is None or rhs[0] != rhs[1]:
                return None
            factor = (1 << rhs[0]) if kind == 'slli' else rhs[0]
            products = (lhs[0] * factor, lhs[1] * factor)
            return (min(products), max(products))
        return None

    def is_bounded_fixed_address_outside_stack(expr, access_width):
        if not expr_has(expr, 'fixed'):
            return False
        if any(expr_has(expr, kind) for kind in ('sp', 'reg', 'unknown')):
            return False
        addr_range = interval(expr)
        if addr_range is None:
            return False
        lo, hi = addr_range
        hi += max(access_width, 1) - 1
        stack_lo = CONCRETE_REPLAY_SP - STACK_RANGE
        stack_hi = CONCRETE_REPLAY_SP - 1
        return hi < stack_lo or lo > stack_hi

    def sign_extend_32(expr):
        return op_expr('sext32', expr)

    def eval_r(inst):
        lhs, rhs = reg_expr(inst.rs1), reg_expr(inst.rs2)
        if inst.name in {'add', 'addw'}:
            value = op_expr('add', lhs, rhs)
        elif inst.name in {'sub', 'subw'}:
            value = op_expr('sub', lhs, rhs)
        elif inst.name in {'mul', 'mulw'}:
            value = op_expr('mul', lhs, rhs)
        elif inst.name == 'and':
            value = op_expr('and', lhs, rhs)
        elif inst.name == 'or':
            value = op_expr('or', lhs, rhs)
        elif inst.name == 'xor':
            value = op_expr('xor', lhs, rhs)
        else:
            return ('unknown', inst.pc, inst.name)
        if inst.name.endswith('w'):
            return sign_extend_32(value)
        return value

    def eval_i(inst):
        lhs = reg_expr(inst.rs1)
        if inst.name in {'addi', 'addiw'}:
            value = op_expr('add', lhs, const_expr(inst.imm))
        elif inst.name == 'andi':
            value = op_expr('and', lhs, const_expr(inst.imm))
        elif inst.name == 'ori':
            value = op_expr('or', lhs, const_expr(inst.imm))
        elif inst.name == 'xori':
            value = op_expr('xor', lhs, const_expr(inst.imm))
        elif inst.name in {'slli', 'slliw'}:
            value = op_expr('slli', lhs, const_expr(inst.imm))
        elif inst.name in {'srli', 'srai', 'srliw', 'sraiw'}:
            value = op_expr(inst.name, lhs, const_expr(inst.imm))
        else:
            return ('unknown', inst.pc, inst.name)
        if inst.name in {'addiw', 'slliw', 'srliw', 'sraiw'}:
            return sign_extend_32(value)
        return value

    env = {XREG[0]: const_expr(0), XREG[2]: ('sp',)}
    memory = {}
    for inst in prog.insts:
        if inst.type in [IType.Load, IType.Store, IType.Amo]:
            addr_expr = op_expr('add', reg_expr(inst.rs1), const_expr(inst.imm))
            if (
                is_fixed_only_address(addr_expr)
                or is_unmappable_fixed_address(addr_expr)
                or is_bounded_fixed_address_outside_stack(addr_expr, inst.width)
            ):
                return inst
            addr_key = str(addr_expr)
            if inst.type in [IType.Store, IType.Amo]:
                memory[addr_key] = reg_expr(inst.rs2)
            if inst.type == IType.Load:
                stored_expr = memory.get(addr_key)
                if stored_expr is not None and expr_has(stored_expr, 'fixed'):
                    env[inst.rd] = ('fixed_spill', stored_expr)
                else:
                    env[inst.rd] = (
                        stored_expr
                        if stored_expr is not None
                        else ('load', inst.pc, inst.name, load_range(inst))
                    )
            continue

        if isinstance(inst, RFmtInst):
            env[inst.rd] = eval_r(inst)
            continue

        if isinstance(inst, IFmtInst):
            env[inst.rd] = eval_i(inst)
            continue

        if isinstance(inst, UFmtInst):
            if inst.name in {'lui', 'auipc'}:
                env[inst.rd] = fixed_expr(inst)
            elif inst.name == 'li':
                env[inst.rd] = const_expr(inst.imm)
            continue

        rd = inst.get_def()
        if rd:
            env[rd] = ('unknown', inst.pc, inst.name)

    return None


def find_constant_nonstack_address_access(prog: Program):
    mask = (1 << 64) - 1
    stack_lo = CONCRETE_REPLAY_SP - STACK_RANGE
    stack_hi = CONCRETE_REPLAY_SP - 1

    def u64(value):
        return value & mask

    def reg_value(reg):
        if reg == XREG[0]:
            return 0
        if reg == XREG[2]:
            return None
        return env.get(reg)

    def set_reg(reg, value):
        if reg != XREG[0]:
            env[reg] = None if value is None else u64(value)

    def binary(inst, op):
        lhs = reg_value(inst.rs1)
        rhs = reg_value(inst.rs2)
        if lhs is None or rhs is None:
            return None
        if op == 'add':
            return lhs + rhs
        if op == 'sub':
            return lhs - rhs
        if op == 'and':
            return lhs & rhs
        if op == 'or':
            return lhs | rhs
        if op == 'xor':
            return lhs ^ rhs
        return None

    env = {XREG[0]: 0}
    for inst in prog.insts:
        if inst.type in [IType.Load, IType.Store, IType.Amo]:
            base = reg_value(inst.rs1)
            if base is not None:
                addr = u64(base + inst.imm)
                if not (stack_lo <= addr <= stack_hi):
                    return inst
            if inst.type == IType.Load:
                set_reg(inst.rd, None)
            continue

        if isinstance(inst, IFmtInst):
            lhs = reg_value(inst.rs1)
            if inst.name in {'addi', 'addiw'}:
                set_reg(inst.rd, None if lhs is None else lhs + inst.imm)
            elif inst.name in {'andi', 'ori', 'xori'}:
                if lhs is None:
                    set_reg(inst.rd, None)
                elif inst.name == 'andi':
                    set_reg(inst.rd, lhs & inst.imm)
                elif inst.name == 'ori':
                    set_reg(inst.rd, lhs | inst.imm)
                else:
                    set_reg(inst.rd, lhs ^ inst.imm)
            elif inst.name in {'slli', 'slliw'}:
                set_reg(inst.rd, None if lhs is None else lhs << inst.imm)
            elif inst.name in {'srli', 'srliw'}:
                set_reg(inst.rd, None if lhs is None else lhs >> inst.imm)
            else:
                set_reg(inst.rd, None)
            continue

        if isinstance(inst, RFmtInst):
            if inst.name in {'add', 'addw'}:
                set_reg(inst.rd, binary(inst, 'add'))
            elif inst.name in {'sub', 'subw'}:
                set_reg(inst.rd, binary(inst, 'sub'))
            elif inst.name == 'and':
                set_reg(inst.rd, binary(inst, 'and'))
            elif inst.name == 'or':
                set_reg(inst.rd, binary(inst, 'or'))
            elif inst.name == 'xor':
                set_reg(inst.rd, binary(inst, 'xor'))
            else:
                set_reg(inst.rd, None)
            continue

        if isinstance(inst, UFmtInst):
            if inst.name == 'li':
                set_reg(inst.rd, inst.imm)
            else:
                set_reg(inst.rd, None)
            continue

        rd = inst.get_def()
        if rd:
            set_reg(rd, None)

    return None


def init_states_for_block(prog: Program, name: str, verbose: bool) -> List[Inst]:
    """generate init code for a block"""
    _write_profile_stage(name, "init:collect_undefined_regs")
    regs_defined = {XREG[0], XREG[2]}  # x0, sp
    init_code = []

    def compile_block(program: Program, bin_name: str):
        _write_profile_stage(name, "init:compile_symbolic_wrapper")
        wrapper_path = PROJECT_PATH / 'src' / 'rvmca' / 'trans' / 'template' / 'block_wrapper.S'
        wrapper = read_file(wrapper_path)
        wrapper = wrapper.replace('#CODE#', program.code)
        write_to_file(f'{OUTPUT_PATH / bin_name}.S', wrapper, append=False)
        run_cmd(f'{RISCV_GCC} {OUTPUT_PATH / bin_name}.S -o {OUTPUT_PATH / bin_name}.exe')

    # compile and load binary
    # add address range checking for symbolic execution
    prog2se = add_addr_range_checking(prog)

    # collect undefined registers
    from rvmca.analysis import CFG, path_to_ssa
    cfg = CFG(prog.insts)
    ssas = path_to_ssa(cfg.edges)
    if verbose:
        print('ssas:', ssas)
    rvfg = RVFG(ssas)
    # rvfg.plot(OUTPUT_PATH / 'fail')
    # # FIXME: we only consider xregs for now
    # regs_undefined = list({r for r in rvfg.find_undef_regs()
    #                        if r in XREG and r not in regs_defined})

    # Find undefined registers from SSA instructions:
    # In SSA form, a register with index 0 (e.g., a5_0) that appears in use_regs
    # is undefined (except x0_0 which is the zero register).
    regs_undefined = []
    for ssa_inst in ssas:
        for reg_bitvec in ssa_inst.get_uses():
            # Extract register name and index (e.g., "a5_0" -> name="a5", index=0)
            reg_str = str(reg_bitvec)
            if '_' not in reg_str:
                continue
            reg_name = reg_str.split('_')[0]
            try:
                reg_idx = int(reg_str.split('_')[1])
            except (ValueError, IndexError):
                continue

            # Register with index 0 is undefined (except x0)
            if reg_idx == 0 and reg_name != 'x0':
                from rvmca.prog.reg import find_reg_by_name
                reg = find_reg_by_name(reg_name)
                # Handle both XREG and FREG
                if reg in XREG and reg not in regs_defined and reg not in regs_undefined:
                    regs_undefined.append(reg)

    runtime_recipe_temp_regs = (
        find_reg_by_name(TEMP_REG),
        find_reg_by_name(TEMP_REG2),
    )

    def runtime_recipe_scratch_unavailable():
        return all(reg in regs_undefined for reg in runtime_recipe_temp_regs)

    # add dummy checking for undefined registers to avoid unconstrained symbol(regs_undefined>0)
    prog2se = add_undef_reg_checking(prog2se, list(regs_undefined))
    # print("prog2se",prog2se)
    last_inst = prog2se.insts[-1]
    if isinstance(last_inst, BFmtInst):
        last_inst.label = 'rvmca_block_end'
        last_inst.imm = None

    if verbose:
        INFO('\n<New Block with address range checking>:')
        INFO(prog2se.code)
    compile_block(prog2se, name)
    _write_profile_stage(name, "init:load_symbolic_project")
    proj = angr.Project(f'{OUTPUT_PATH / name}.exe', auto_load_libs=False)
    begin_addr = proj.loader.main_object.get_symbol('rvmca_block_begin').rebased_addr
    end_addr = proj.loader.main_object.get_symbol('rvmca_block_end').rebased_addr
    fail_symbol = proj.loader.main_object.get_symbol('fail')
    fail_addr = fail_symbol.rebased_addr if fail_symbol is not None else None
    # print(f'begin_addr: {begin_addr:#x}, end_addr: {end_addr:#x}')
    init_state = proj.factory.blank_state(addr=begin_addr,
                                          mode='symbolic',
                                          add_options={
                                              angr.options.SYMBOL_FILL_UNCONSTRAINED_MEMORY,  # 用符号填充未约束的内存
                                              angr.options.SYMBOL_FILL_UNCONSTRAINED_REGISTERS,  # 用符号填充未约束的寄存器
                                              angr.options.CONSERVATIVE_WRITE_STRATEGY,  # 保守的写策略
                                              angr.options.CONSERVATIVE_READ_STRATEGY,  # 保守的读策略
                                          },
                                          )
    from rvmca.prog import UFmtInst
    init_state.options.discard(angr.options.ZERO_FILL_UNCONSTRAINED_REGISTERS)  # 未约束的寄存器会被符号填充而不是零填充
    if verbose:
        DEBUG(init_state.options.tally())

    # init_state.options.remove(angr.options.SYMBOL_FILL_UNCONSTRAINED_REGISTERS)
    # block = proj.factory.block(begin_addr)
    # INFO("<Block>")
    # for inst in block.capstone.insns:
    #     INFO(f"{inst.address:#x}: {inst.mnemonic} {inst.op_str}")
    # end_addr = block.instruction_addrs[-1]

    def concrete_bvv(value: int):
        return claripy.BVV(value & ((1 << 64) - 1), 64)

    def write_stage(stage: str, **extra):
        data = {
            "name": name,
            "stage": stage,
            "time": time.time(),
        }
        data.update(extra)
        _stage_file_for_name(name).write_text(json.dumps(data, sort_keys=True), encoding="utf-8")

    def concrete_stack_addr(offset: int, sp_value: int = CONCRETE_REPLAY_SP) -> int:
        return (sp_value - offset) & ((1 << 64) - 1)

    def stack_offset_for_value(value: int):
        offset = (CONCRETE_REPLAY_SP - value) & ((1 << 64) - 1)
        if offset <= MAX_SP_REL_OFFSET and concrete_stack_addr(offset) == (value & ((1 << 64) - 1)):
            return offset
        return None

    def concrete_expr_value(expr):
        if isinstance(expr, int):
            return expr & ((1 << 64) - 1)
        try:
            if getattr(expr, 'variables', set()):
                return None
        except Exception:
            return None
        try:
            expr = claripy.simplify(expr)
            if getattr(expr, 'variables', set()):
                return None
        except Exception:
            pass
        try:
            value = expr.concrete_value
            if isinstance(value, int):
                return value & ((1 << 64) - 1)
            nested_value = getattr(value, 'concrete_value', None)
            if isinstance(nested_value, int):
                return nested_value & ((1 << 64) - 1)
            return int(value) & ((1 << 64) - 1)
        except Exception:
            return None

    def signed_stack_offset_for_value(value: int):
        value &= (1 << 64) - 1
        down_offset = (CONCRETE_REPLAY_SP - value) & ((1 << 64) - 1)
        if down_offset <= MAX_SP_REL_OFFSET and concrete_stack_addr(down_offset) == value:
            return down_offset

        up_offset = (value - CONCRETE_REPLAY_SP) & ((1 << 64) - 1)
        if up_offset <= MAX_SP_REL_OFFSET and ((CONCRETE_REPLAY_SP + up_offset) & ((1 << 64) - 1)) == value:
            return -up_offset

        return None

    def scaled_stack_transform_for_value(
        value: int,
        sp_value: int = CONCRETE_REPLAY_SP,
        max_offset: int = STACK_RANGE,
    ):
        return _scaled_stack_transform_for_value(value, sp_value, max_offset)

    def remap_sp_relative_value(value: int, from_sp: int, to_sp: int, allow_scaled_stack: bool = False) -> int:
        value &= (1 << 64) - 1
        offset = (from_sp - value) & ((1 << 64) - 1)
        if offset <= MAX_SP_REL_OFFSET and ((from_sp - offset) & ((1 << 64) - 1)) == value:
            return (to_sp - offset) & ((1 << 64) - 1)
        offset = (value - from_sp) & ((1 << 64) - 1)
        if offset <= MAX_SP_REL_OFFSET and ((from_sp + offset) & ((1 << 64) - 1)) == value:
            return (to_sp + offset) & ((1 << 64) - 1)
        if allow_scaled_stack:
            scaled = scaled_stack_transform_for_value(value, from_sp)
            if scaled is not None:
                stack_offset, shift = scaled
                if stack_offset < 0:
                    shifted = (to_sp + (-stack_offset)) & ((1 << 64) - 1)
                else:
                    shifted = (to_sp - stack_offset) & ((1 << 64) - 1)
                if shifted & ((1 << shift) - 1) == 0:
                    return shifted >> shift
        return value

    def sp_affine_mode(sp_affine_mem_offsets, addr_offset):
        if not sp_affine_mem_offsets:
            return None
        if isinstance(sp_affine_mem_offsets, dict):
            return sp_affine_mem_offsets.get(addr_offset)
        if addr_offset in sp_affine_mem_offsets:
            return 'direct'
        return None

    def remap_sp_affine_mem_value(value: int, sp_value: int, mode) -> int:
        return _remap_sp_affine_mem_value(value, sp_value, mode)

    def sp_affine_cache_items(sp_affine_mem_offsets):
        if not sp_affine_mem_offsets:
            return ()
        if isinstance(sp_affine_mem_offsets, dict):
            return tuple(sorted((offset, mode) for offset, mode in sp_affine_mem_offsets.items()))
        return tuple(sorted((offset, 'direct') for offset in sp_affine_mem_offsets))

    def runtime_reg_value(reg, value, sp_value, reg_runtime_recipes=None):
        recipe = (reg_runtime_recipes or {}).get(reg)
        if recipe is not None:
            return _runtime_reg_recipe_value(sp_value, recipe)
        return remap_sp_relative_value(
            value,
            CONCRETE_REPLAY_SP,
            sp_value,
            allow_scaled_stack=True,
        )

    def runtime_dynamic_mem_addr(sp_value, entry):
        recipe, addr_const, _, _, _ = entry
        return _runtime_recipe_address(sp_value, recipe, addr_const)

    def runtime_dynamic_mem_value(sp_value, entry):
        _, _, _, raw_value, value_recipe = entry
        if value_recipe is not None:
            return remap_sp_affine_mem_value(raw_value, sp_value, value_recipe)
        return remap_sp_relative_value(
            raw_value,
            CONCRETE_REPLAY_SP,
            sp_value,
        )

    def set_concrete_state(
        state,
        reg_values,
        mem_values,
        sp_value=CONCRETE_REPLAY_SP,
        sp_affine_mem_offsets=None,
        reg_runtime_recipes=None,
        dynamic_mem_inits=None,
    ):
        for i in range(32):
            setattr(state.regs, f'x{i}', claripy.BVV(0, 64))
        state.regs.sp = concrete_bvv(sp_value)
        state.regs.x0 = claripy.BVV(0, 64)
        for reg, value in reg_values.items():
            setattr(
                state.regs,
                reg.name,
                concrete_bvv(runtime_reg_value(reg, value, sp_value, reg_runtime_recipes)),
            )
        for addr_offset, value in mem_values.items():
            mode = sp_affine_mode(sp_affine_mem_offsets, addr_offset)
            if mode is not None:
                stored_value = remap_sp_affine_mem_value(value, sp_value, mode)
            else:
                stored_value = remap_sp_relative_value(value, CONCRETE_REPLAY_SP, sp_value)
            state.memory.store(
                concrete_stack_addr(addr_offset, sp_value),
                concrete_bvv(stored_value),
                endness=proj.arch.memory_endness,
            )
        for entry in dynamic_mem_inits or ():
            _, _, width, _, _ = entry
            stored_value = runtime_dynamic_mem_value(sp_value, entry)
            state.memory.store(
                runtime_dynamic_mem_addr(sp_value, entry),
                claripy.BVV(stored_value & ((1 << (width * 8)) - 1), width * 8),
                endness=proj.arch.memory_endness,
            )

    last_prefix_fail_info = {}

    def replay_concrete_init(
        reg_values,
        mem_values,
        debug=False,
        sp_value=CONCRETE_REPLAY_SP,
        sp_affine_mem_offsets=None,
        reg_runtime_recipes=None,
        dynamic_mem_inits=None,
    ):
        _write_profile_stage(name, "init:concrete_replay")
        prefix_states = replay_prefix_states(
            reg_values,
            mem_values,
            sp_value=sp_value,
            sp_affine_mem_offsets=sp_affine_mem_offsets,
            reg_runtime_recipes=reg_runtime_recipes,
            dynamic_mem_inits=dynamic_mem_inits,
        )
        if prefix_states is not None:
            if fail_addr is not None and fail_addr in prefix_states:
                if debug:
                    if last_prefix_fail_info:
                        print("prefix_fail", last_prefix_fail_info)
                    print("prefix_reg_values", {
                        reg.name: hex(runtime_reg_value(reg, value, sp_value, reg_runtime_recipes))
                        for reg, value in reg_values.items()
                    })
                    prefix_mem_values = {}
                    for offset, value in mem_values.items():
                        mode = sp_affine_mode(sp_affine_mem_offsets, offset)
                        if mode is not None:
                            prefix_mem_values[offset] = hex(remap_sp_affine_mem_value(value, sp_value, mode))
                        else:
                            prefix_mem_values[offset] = hex(
                                remap_sp_relative_value(value, CONCRETE_REPLAY_SP, sp_value)
                            )
                    print("prefix_mem_values", prefix_mem_values)
                return None
            if end_addr in prefix_states:
                return prefix_states[end_addr]
        replay_state = proj.factory.blank_state(
            addr=begin_addr,
            mode='symbolic',
            add_options={
                angr.options.ZERO_FILL_UNCONSTRAINED_MEMORY,
                angr.options.ZERO_FILL_UNCONSTRAINED_REGISTERS,
            },
        )
        set_concrete_state(
            replay_state,
            reg_values,
            mem_values,
            sp_value=sp_value,
            sp_affine_mem_offsets=sp_affine_mem_offsets,
            reg_runtime_recipes=reg_runtime_recipes,
            dynamic_mem_inits=dynamic_mem_inits,
        )
        replay_mgr = proj.factory.simulation_manager(replay_state)
        replay_mgr.explore(find=end_addr)
        if replay_mgr.found:
            return replay_mgr.found[0]
        if debug:
            print(f"replay failed for {name}")
            print("sp_value", hex(sp_value))
            print("reg_values", {
                reg.name: hex(runtime_reg_value(reg, value, sp_value, reg_runtime_recipes))
                for reg, value in reg_values.items()
            })
            debug_mem_values = {}
            for offset, value in mem_values.items():
                mode = sp_affine_mode(sp_affine_mem_offsets, offset)
                if mode is not None:
                    debug_mem_values[offset] = hex(remap_sp_affine_mem_value(value, sp_value, mode))
                else:
                    debug_mem_values[offset] = hex(remap_sp_relative_value(value, CONCRETE_REPLAY_SP, sp_value))
            print("mem_values", debug_mem_values)
            if fail_addr is not None:
                fail_state = proj.factory.blank_state(
                    addr=begin_addr,
                    mode='symbolic',
                    add_options={
                        angr.options.ZERO_FILL_UNCONSTRAINED_MEMORY,
                        angr.options.ZERO_FILL_UNCONSTRAINED_REGISTERS,
                    },
                )
                set_concrete_state(
                    fail_state,
                    reg_values,
                    mem_values,
                    sp_value=sp_value,
                    sp_affine_mem_offsets=sp_affine_mem_offsets,
                    reg_runtime_recipes=reg_runtime_recipes,
                    dynamic_mem_inits=dynamic_mem_inits,
                )
                fail_mgr = proj.factory.simulation_manager(fail_state)
                fail_mgr.explore(find=fail_addr)
                if fail_mgr.found:
                    state = fail_mgr.found[0]
                    regs = {}
                    for reg_name in ['x5', 'x6', 'x10', 'x12', 'x13', 'x14', 'x15', 'x16', 'x17', 'x24', 'x26', 'x31', 'sp']:
                        regs[reg_name] = hex(state.solver.eval(getattr(state.regs, reg_name)))
                    print("fail_regs", regs)
                    try:
                        recent = list(state.history.bbl_addrs.hardcopy)[-12:]
                        print("fail_recent_bbls", [hex(addr) for addr in recent])
                    except Exception:
                        pass
            for stash_name in ["active", "deadended", "errored", "unconstrained"]:
                stash = getattr(replay_mgr, stash_name, [])
                print(f"replay {stash_name}: {len(stash)}")
                for item in list(stash)[:4]:
                    if stash_name == "errored":
                        print("  error", item.error)
                        state = item.state
                    else:
                        state = item
                    try:
                        ip = state.solver.eval(state.ip)
                        marker = " fail" if fail_addr is not None and ip == fail_addr else ""
                        print(f"  ip={ip:#x}{marker}")
                    except Exception as exc:
                        print(f"  ip=<unknown: {exc}>")
                    try:
                        recent = list(state.history.bbl_addrs.hardcopy)[-8:]
                        print("  recent_bbls", [hex(addr) for addr in recent])
                    except Exception:
                        pass
        return None

    replay_prefix_state_cache = {}
    replay_prefix_context = {}

    class ConcretePrefixSolver:
        @staticmethod
        def eval(value):
            return value & ((1 << 64) - 1)

    class ConcretePrefixRegs:
        def __init__(self, values):
            self._values = values

        def __getattr__(self, reg_name):
            if reg_name == 'sp':
                reg_name = 'x2'
            return self._values.get(reg_name, 0)

    class ConcretePrefixState:
        solver = ConcretePrefixSolver()

        def __init__(self, values):
            self.regs = ConcretePrefixRegs(values)

    def concrete_prefix_states(
        reg_values,
        mem_values,
        sp_value=CONCRETE_REPLAY_SP,
        sp_affine_mem_offsets=None,
        reg_runtime_recipes=None,
        dynamic_mem_inits=None,
    ):
        mask = (1 << 64) - 1
        prefix_prog = prog2se
        debug_concrete_prefix = os.environ.get("RVMCA_DEBUG_CONCRETE_PREFIX") == "1"

        def unsupported(inst_idx, inst, reason):
            if verbose:
                print('concrete_prefix_unsupported', inst_idx, getattr(inst, 'code', str(inst)), reason)
            return None

        def u64(value):
            return value & mask

        def sext(value, bits):
            value &= (1 << bits) - 1
            sign_bit = 1 << (bits - 1)
            if value & sign_bit:
                value -= 1 << bits
            return u64(value)

        def signed(value):
            value &= mask
            if value & (1 << 63):
                return value - (1 << 64)
            return value

        def trunc_div(lhs, rhs):
            assert rhs != 0
            quotient = abs(lhs) // abs(rhs)
            if (lhs < 0) ^ (rhs < 0):
                quotient = -quotient
            return quotient

        def trunc_rem(lhs, rhs):
            assert rhs != 0
            return lhs - trunc_div(lhs, rhs) * rhs

        regs = {f'x{i}': 0 for i in range(32)}
        regs['x2'] = u64(sp_value)
        for reg, value in reg_values.items():
            if reg not in XREG:
                return unsupported(-1, reg, 'non_xreg_init')
            regs[reg.name] = u64(
                runtime_reg_value(reg, value, sp_value, reg_runtime_recipes)
            )
        regs['x0'] = 0

        mem_words = {}
        for addr_offset, value in mem_values.items():
            mode = sp_affine_mode(sp_affine_mem_offsets, addr_offset)
            if mode is not None:
                stored_value = remap_sp_affine_mem_value(value, sp_value, mode)
            else:
                stored_value = remap_sp_relative_value(value, CONCRETE_REPLAY_SP, sp_value)
            mem_words[addr_offset] = u64(stored_value)

        def reg_value(reg):
            if reg not in XREG:
                return None
            return regs.get(reg.name, 0)

        def set_reg(reg, value):
            if reg not in XREG:
                return False
            if reg != XREG[0]:
                regs[reg.name] = u64(value)
            regs['x0'] = 0
            return True

        def stack_offset_for_addr(addr):
            return (sp_value - addr) & mask

        def stack_access_ok(addr, width):
            offset = stack_offset_for_addr(addr)
            if addr >= sp_value or offset <= 0 or offset > STACK_RANGE:
                return False
            if width > 1 and addr % width:
                return False
            return True

        def mark_fail_state():
            if fail_addr is None:
                return False
            states_by_addr[fail_addr] = ConcretePrefixState(regs.copy())
            return True

        def protected_memory_access_for_check(branch_idx, branch_inst):
            """Return the real memory access guarded by a failed range check."""
            branch_name = getattr(branch_inst, 'name', '')
            branch_rs2 = getattr(branch_inst, 'rs2', None)
            is_range_check = branch_name in {'bge', 'blt'} and branch_rs2 == XREG[2]
            is_align_check = False
            if branch_name == 'bne' and branch_rs2 == XREG[0] and branch_idx > 0:
                prev_inst = prefix_prog.insts[branch_idx - 1]
                is_align_check = getattr(prev_inst, 'name', '') == 'andi'
            if not (is_range_check or is_align_check):
                return None

            for next_idx in range(branch_idx + 1, min(len(prefix_prog.insts), branch_idx + 13)):
                next_inst = prefix_prog.insts[next_idx]
                if next_inst.type in [IType.Load, IType.Store, IType.Amo]:
                    return next_idx, next_inst, 'align' if is_align_check else 'range'
            return None

        def record_access_fail(inst_idx, inst, access_addr):
            recent = []
            for recent_idx in range(max(0, inst_idx - 6), inst_idx + 1):
                recent_inst = prefix_prog.insts[recent_idx]
                recent.append((recent_idx, getattr(recent_inst, 'code', str(recent_inst))))
            offset = stack_offset_for_addr(access_addr)
            last_prefix_fail_info.clear()
            last_prefix_fail_info.update({
                'sp_value': hex(sp_value),
                'inst_idx': inst_idx,
                'inst': getattr(inst, 'code', str(inst)),
                'access_addr': hex(access_addr),
                'offset': hex(offset),
                'rs1': str(getattr(inst, 'rs1', '')),
                'rs1_value': hex(reg_value(getattr(inst, 'rs1', XREG[0])) or 0),
                'recent': recent,
            })
            if os.environ.get("RVMCA_DEBUG_PREFIX_FAIL") == "1":
                last_prefix_fail_info['regs'] = {
                    reg_name: hex(regs.get(reg_name, 0))
                    for reg_name in ['x5', 'x6', 'x7', 'x8', 'x10', 'x11', 'x12', 'x15', 'x18', 'x27', 'x30']
                }

        def load_mem(addr, width, name):
            offset = stack_offset_for_addr(addr)
            word_offset = ((offset + 7) // 8) * 8
            byte_offset = word_offset - offset
            if byte_offset < 0 or byte_offset + width > 8:
                return 0
            word = mem_words.get(word_offset, 0)
            raw = (word >> (byte_offset * 8)) & ((1 << (width * 8)) - 1)
            if name in {'lb', 'lh', 'lw'}:
                return sext(raw, width * 8)
            return raw

        def store_mem(addr, width, value):
            offset = stack_offset_for_addr(addr)
            word_offset = ((offset + 7) // 8) * 8
            byte_offset = word_offset - offset
            if byte_offset < 0 or byte_offset + width > 8:
                return
            lo = byte_offset * 8
            field_mask = ((1 << (width * 8)) - 1) << lo
            word = mem_words.get(word_offset, 0)
            mem_words[word_offset] = u64((word & ~field_mask) | ((value << lo) & field_mask))

        for entry in dynamic_mem_inits or ():
            _, _, width, _, _ = entry
            store_mem(
                runtime_dynamic_mem_addr(sp_value, entry),
                width,
                runtime_dynamic_mem_value(sp_value, entry),
            )

        def eval_r(inst):
            lhs = reg_value(inst.rs1)
            rhs = reg_value(inst.rs2)
            if lhs is None or rhs is None:
                return None
            sh64 = rhs & 0x3f
            sh32 = rhs & 0x1f
            if inst.name == 'add':
                return u64(lhs + rhs)
            if inst.name == 'sub':
                return u64(lhs - rhs)
            if inst.name == 'mul':
                return u64(lhs * rhs)
            if inst.name == 'mulh':
                return u64((signed(lhs) * signed(rhs)) >> 64)
            if inst.name == 'mulhu':
                return u64((lhs * rhs) >> 64)
            if inst.name == 'mulhsu':
                return u64((signed(lhs) * rhs) >> 64)
            if inst.name == 'div':
                lhs_s, rhs_s = signed(lhs), signed(rhs)
                if rhs_s == 0:
                    return mask
                if lhs_s == -(1 << 63) and rhs_s == -1:
                    return lhs
                return u64(trunc_div(lhs_s, rhs_s))
            if inst.name == 'divu':
                if rhs == 0:
                    return mask
                return u64(lhs // rhs)
            if inst.name == 'rem':
                lhs_s, rhs_s = signed(lhs), signed(rhs)
                if rhs_s == 0:
                    return lhs
                if lhs_s == -(1 << 63) and rhs_s == -1:
                    return 0
                return u64(trunc_rem(lhs_s, rhs_s))
            if inst.name == 'remu':
                if rhs == 0:
                    return lhs
                return u64(lhs % rhs)
            if inst.name == 'and':
                return u64(lhs & rhs)
            if inst.name == 'or':
                return u64(lhs | rhs)
            if inst.name == 'xor':
                return u64(lhs ^ rhs)
            if inst.name == 'sll':
                return u64(lhs << sh64)
            if inst.name == 'srl':
                return u64(lhs >> sh64)
            if inst.name == 'sra':
                return u64(signed(lhs) >> sh64)
            if inst.name == 'slt':
                return 1 if signed(lhs) < signed(rhs) else 0
            if inst.name == 'sltu':
                return 1 if lhs < rhs else 0
            lhs32, rhs32 = sext(lhs, 32), sext(rhs, 32)
            if inst.name == 'addw':
                return sext(lhs32 + rhs32, 32)
            if inst.name == 'subw':
                return sext(lhs32 - rhs32, 32)
            if inst.name == 'mulw':
                return sext(lhs32 * rhs32, 32)
            if inst.name == 'divw':
                if rhs32 == 0:
                    return mask
                if lhs32 == -(1 << 31) and rhs32 == -1:
                    return sext(lhs32, 32)
                return sext(trunc_div(lhs32, rhs32), 32)
            if inst.name == 'divuw':
                lhs_u32, rhs_u32 = lhs & 0xffffffff, rhs & 0xffffffff
                if rhs_u32 == 0:
                    return mask
                return sext(lhs_u32 // rhs_u32, 32)
            if inst.name == 'remw':
                if rhs32 == 0:
                    return sext(lhs32, 32)
                if lhs32 == -(1 << 31) and rhs32 == -1:
                    return 0
                return sext(trunc_rem(lhs32, rhs32), 32)
            if inst.name == 'remuw':
                lhs_u32, rhs_u32 = lhs & 0xffffffff, rhs & 0xffffffff
                if rhs_u32 == 0:
                    return sext(lhs_u32, 32)
                return sext(lhs_u32 % rhs_u32, 32)
            if inst.name == 'sllw':
                return sext((lhs & 0xffffffff) << sh32, 32)
            if inst.name == 'srlw':
                return sext((lhs & 0xffffffff) >> sh32, 32)
            if inst.name == 'sraw':
                return sext(sext(lhs, 32) >> sh32, 32)
            return None

        def eval_i(inst):
            lhs = reg_value(inst.rs1)
            if lhs is None:
                return None
            imm = inst.imm
            sh64 = imm & 0x3f
            sh32 = imm & 0x1f
            if inst.name == 'addi':
                return u64(lhs + imm)
            if inst.name == 'addiw':
                return sext(lhs + imm, 32)
            if inst.name == 'andi':
                return u64(lhs & imm)
            if inst.name == 'ori':
                return u64(lhs | imm)
            if inst.name == 'xori':
                return u64(lhs ^ imm)
            if inst.name == 'slli':
                return u64(lhs << sh64)
            if inst.name == 'srli':
                return u64(lhs >> sh64)
            if inst.name == 'srai':
                return u64(signed(lhs) >> sh64)
            if inst.name == 'slliw':
                return sext((lhs & 0xffffffff) << sh32, 32)
            if inst.name == 'srliw':
                return sext((lhs & 0xffffffff) >> sh32, 32)
            if inst.name == 'sraiw':
                return sext(sext(lhs, 32) >> sh32, 32)
            if inst.name == 'slti':
                return 1 if signed(lhs) < imm else 0
            if inst.name == 'sltiu':
                return 1 if lhs < (imm & mask) else 0
            return None

        def eval_branch(inst):
            lhs = reg_value(inst.rs1)
            rhs = reg_value(inst.rs2)
            if lhs is None or rhs is None:
                return None
            if inst.name == 'beq':
                return lhs == rhs
            if inst.name == 'bne':
                return lhs != rhs
            if inst.name == 'blt':
                return signed(lhs) < signed(rhs)
            if inst.name == 'bge':
                return signed(lhs) >= signed(rhs)
            if inst.name == 'bltu':
                return lhs < rhs
            if inst.name == 'bgeu':
                return lhs >= rhs
            if inst.name == 'bgt':
                return signed(lhs) > signed(rhs)
            if inst.name == 'ble':
                return signed(lhs) <= signed(rhs)
            if inst.name == 'bgtu':
                return lhs > rhs
            if inst.name == 'bleu':
                return lhs <= rhs
            return None

        states_by_addr = {}
        completed = True
        for inst_idx, inst in enumerate(prefix_prog.insts):
            if debug_concrete_prefix and (inst_idx % 10 == 0 or inst_idx + 8 >= len(prefix_prog.insts)):
                write_stage(
                    "init:concrete_replay_prefix:concrete",
                    inst_idx=inst_idx,
                    inst=getattr(inst, 'code', str(inst)),
                )
            states_by_addr[begin_addr + inst_idx * 4] = ConcretePrefixState(regs.copy())
            if isinstance(inst, RFmtInst):
                value = eval_r(inst)
                if value is None or not set_reg(inst.rd, value):
                    return unsupported(inst_idx, inst, 'rfmt')
            elif isinstance(inst, IFmtInst):
                value = eval_i(inst)
                if value is None or not set_reg(inst.rd, value):
                    return unsupported(inst_idx, inst, 'ifmt')
            elif isinstance(inst, UFmtInst):
                if inst.name == 'lui':
                    value = _riscv_u_format_value(inst.imm)
                elif inst.name == 'auipc':
                    value = begin_addr + inst_idx * 4 + _riscv_u_format_value(inst.imm)
                elif inst.name == 'li':
                    value = inst.imm
                else:
                    return unsupported(inst_idx, inst, 'ufmt')
                if not set_reg(inst.rd, value):
                    return unsupported(inst_idx, inst, 'ufmt_set_reg')
            elif inst.type == IType.Load:
                if inst.rd not in XREG:
                    return unsupported(inst_idx, inst, 'load_non_xreg')
                base = reg_value(inst.rs1)
                if base is None:
                    return unsupported(inst_idx, inst, 'load_base')
                access_addr = u64(base + inst.imm)
                if not stack_access_ok(access_addr, inst.width):
                    record_access_fail(inst_idx, inst, access_addr)
                    mark_fail_state()
                    completed = False
                    break
                set_reg(inst.rd, load_mem(access_addr, inst.width, inst.name))
            elif inst.type == IType.Store:
                base = reg_value(inst.rs1)
                value = reg_value(inst.rs2)
                if base is None or value is None:
                    return unsupported(inst_idx, inst, 'store_operand')
                access_addr = u64(base + inst.imm)
                if not stack_access_ok(access_addr, inst.width):
                    record_access_fail(inst_idx, inst, access_addr)
                    mark_fail_state()
                    completed = False
                    break
                store_mem(access_addr, inst.width, value)
            elif inst.type == IType.Branch:
                taken = eval_branch(inst)
                if taken is None:
                    return unsupported(inst_idx, inst, 'branch')
                if taken:
                    label = getattr(inst, 'label', None)
                    if label == 'fail' and fail_addr is not None:
                        recent = []
                        for recent_idx in range(max(0, inst_idx - 6), inst_idx + 1):
                            recent_inst = prefix_prog.insts[recent_idx]
                            recent.append((recent_idx, getattr(recent_inst, 'code', str(recent_inst))))
                        last_prefix_fail_info.clear()
                        last_prefix_fail_info.update({
                            'sp_value': hex(sp_value),
                            'inst_idx': inst_idx,
                            'inst': getattr(inst, 'code', str(inst)),
                            'rs1': str(getattr(inst, 'rs1', '')),
                            'rs1_value': hex(reg_value(getattr(inst, 'rs1', XREG[0])) or 0),
                            'rs2': str(getattr(inst, 'rs2', '')),
                            'rs2_value': hex(reg_value(getattr(inst, 'rs2', XREG[0])) or 0),
                            'recent': recent,
                        })
                        protected_access = protected_memory_access_for_check(inst_idx, inst)
                        if protected_access is not None:
                            protected_idx, protected_inst, protected_kind = protected_access
                            protected_addr = None
                            protected_offset = None
                            protected_base = reg_value(getattr(protected_inst, 'rs1', XREG[0]))
                            if protected_base is not None:
                                protected_addr = u64(protected_base + getattr(protected_inst, 'imm', 0))
                                protected_offset = stack_offset_for_addr(protected_addr)
                            last_prefix_fail_info.update({
                                'protected_access_idx': protected_idx,
                                'protected_access_inst': getattr(protected_inst, 'code', str(protected_inst)),
                                'protected_access_width': getattr(protected_inst, 'width', 0),
                                'protected_access_kind': protected_kind,
                            })
                            if protected_addr is not None:
                                last_prefix_fail_info['protected_access_addr'] = hex(protected_addr)
                            if protected_offset is not None:
                                last_prefix_fail_info['protected_access_offset'] = hex(protected_offset)
                        if os.environ.get("RVMCA_DEBUG_PREFIX_FAIL") == "1":
                            debug_regs = [
                                'x5', 'x6', 'x7', 'x8', 'x10', 'x15',
                                'x21', 'x26', 'x31',
                            ]
                            last_prefix_fail_info['regs'] = {
                                reg_name: hex(regs.get(reg_name, 0))
                                for reg_name in debug_regs
                            }
                            last_prefix_fail_info['mem_words'] = {
                                offset: hex(value)
                                for offset, value in sorted(mem_words.items())
                            }
                        states_by_addr[fail_addr] = ConcretePrefixState(regs.copy())
                    elif label == 'rvmca_block_end':
                        states_by_addr[end_addr] = ConcretePrefixState(regs.copy())
                    else:
                        target_idx = inst_idx + ((inst.imm or 0) // 4)
                        states_by_addr[begin_addr + target_idx * 4] = ConcretePrefixState(regs.copy())
                    completed = False
                    break
            elif inst.type == IType.Jump:
                completed = False
                break
            else:
                return unsupported(inst_idx, inst, 'type')
        if completed:
            states_by_addr[begin_addr + len(prefix_prog.insts) * 4] = ConcretePrefixState(regs.copy())
            states_by_addr[end_addr] = ConcretePrefixState(regs.copy())
        return states_by_addr

    def replay_prefix_cache_key(
        reg_values,
        mem_values,
        sp_value,
        sp_affine_mem_offsets,
        reg_runtime_recipes,
        dynamic_mem_inits,
    ):
        mask = (1 << 64) - 1
        return (
            sp_value & mask,
            tuple(sorted((reg.name, value & mask) for reg, value in reg_values.items())),
            tuple(sorted((offset, value & mask) for offset, value in mem_values.items())),
            sp_affine_cache_items(sp_affine_mem_offsets),
            tuple(sorted(
                (reg.name, tuple(recipe))
                for reg, recipe in (reg_runtime_recipes or {}).items()
            )),
            tuple(tuple(entry) for entry in (dynamic_mem_inits or ())),
        )

    def replay_prefix_states(
        reg_values,
        mem_values,
        sp_value=CONCRETE_REPLAY_SP,
        sp_affine_mem_offsets=None,
        reg_runtime_recipes=None,
        dynamic_mem_inits=None,
    ):
        _write_profile_stage(
            name,
            "init:concrete_replay_prefix",
            sp=hex(sp_value),
            **replay_prefix_context,
        )
        cache_key = replay_prefix_cache_key(
            reg_values,
            mem_values,
            sp_value,
            sp_affine_mem_offsets,
            reg_runtime_recipes,
            dynamic_mem_inits,
        )
        if cache_key in replay_prefix_state_cache:
            _write_profile_stage(
                name,
                "init:concrete_replay_prefix:cache_hit",
                sp=hex(sp_value),
                **replay_prefix_context,
            )
            return replay_prefix_state_cache[cache_key]

        states_by_addr = concrete_prefix_states(
            reg_values,
            mem_values,
            sp_value=sp_value,
            sp_affine_mem_offsets=sp_affine_mem_offsets,
            reg_runtime_recipes=reg_runtime_recipes,
            dynamic_mem_inits=dynamic_mem_inits,
        )
        if states_by_addr is not None:
            replay_prefix_state_cache[cache_key] = states_by_addr
            _write_profile_stage(
                name,
                "init:concrete_replay_prefix:done",
                sp=hex(sp_value),
                states=len(states_by_addr),
                **replay_prefix_context,
            )
            return states_by_addr
        replay_state = proj.factory.blank_state(
            addr=begin_addr,
            mode='symbolic',
            add_options={
                angr.options.ZERO_FILL_UNCONSTRAINED_MEMORY,
                angr.options.ZERO_FILL_UNCONSTRAINED_REGISTERS,
            },
        )
        set_concrete_state(
            replay_state,
            reg_values,
            mem_values,
            sp_value=sp_value,
            sp_affine_mem_offsets=sp_affine_mem_offsets,
            reg_runtime_recipes=reg_runtime_recipes,
            dynamic_mem_inits=dynamic_mem_inits,
        )
        replay_mgr = proj.factory.simulation_manager(replay_state)
        states_by_addr = {}
        max_steps = max(1, len(prog.insts) + 8)
        for step_idx in range(max_steps):
            if os.environ.get("RVMCA_DEBUG_CONCRETE_PREFIX") == "1":
                write_stage(
                    "init:concrete_replay_prefix:angr",
                    step=step_idx,
                    active=len(replay_mgr.active),
                )
            for state in list(replay_mgr.active):
                try:
                    ip = state.solver.eval(state.ip)
                except Exception:
                    continue
                states_by_addr.setdefault(ip, state)
            if not replay_mgr.active:
                replay_prefix_state_cache[cache_key] = states_by_addr
                return states_by_addr
            replay_mgr.step()
        replay_prefix_state_cache[cache_key] = states_by_addr
        return states_by_addr

    def replay_prefix_state(
        reg_values,
        mem_values,
        target_addr,
        sp_value=CONCRETE_REPLAY_SP,
        sp_affine_mem_offsets=None,
        reg_runtime_recipes=None,
        dynamic_mem_inits=None,
    ):
        states_by_addr = replay_prefix_states(
            reg_values,
            mem_values,
            sp_value=sp_value,
            sp_affine_mem_offsets=sp_affine_mem_offsets,
            reg_runtime_recipes=reg_runtime_recipes,
            dynamic_mem_inits=dynamic_mem_inits,
        )
        if states_by_addr is None:
            return None
        return states_by_addr.get(target_addr)

    def concrete_ranges_overlap(addr1, width1, addr2, width2):
        lo1, hi1 = addr1 - width1 + 1, addr1
        lo2, hi2 = addr2 - width2 + 1, addr2
        return max(lo1, lo2) <= min(hi1, hi2)

    def symbolic_no_overlap(addr_symbol, width, mem_offset):
        offset_symbol = init_sp - addr_symbol
        store_lo = offset_symbol - (width - 1)
        mem_lo = claripy.BVV(mem_offset - 7, 64)
        mem_hi = claripy.BVV(mem_offset, 64)
        return claripy.Or(
            claripy.ULT(offset_symbol, mem_lo),
            claripy.ULT(mem_hi, store_lo),
        )

    def symbolic_word_slot_no_overlap(addr_symbol, width, slot_addr_symbol):
        offset_symbol = init_sp - addr_symbol
        slot_offset = init_sp - slot_addr_symbol
        slot_hi = (slot_offset + 7) & claripy.BVV(~7 & ((1 << 64) - 1), 64)
        slot_lo = slot_hi - (INIT_ACCESS_SLOT_WIDTH - 1)
        access_lo = offset_symbol - (width - 1)
        return claripy.Or(
            claripy.ULT(offset_symbol, slot_lo),
            claripy.ULT(slot_hi, access_lo),
        )

    def symbolic_init_slots_no_overlap(addr_symbol_a, addr_symbol_b):
        offset_a = init_sp - addr_symbol_a
        offset_b = init_sp - addr_symbol_b
        slot_hi_a = (offset_a + 7) & claripy.BVV(~7 & ((1 << 64) - 1), 64)
        slot_hi_b = (offset_b + 7) & claripy.BVV(~7 & ((1 << 64) - 1), 64)
        slot_lo_a = slot_hi_a - (INIT_ACCESS_SLOT_WIDTH - 1)
        slot_lo_b = slot_hi_b - (INIT_ACCESS_SLOT_WIDTH - 1)
        return claripy.Or(
            claripy.ULT(slot_hi_a, slot_lo_b),
            claripy.ULT(slot_hi_b, slot_lo_a),
        )

    def symbolic_access_no_overlap(addr_symbol_a, width_a, addr_symbol_b, width_b):
        offset_a = init_sp - addr_symbol_a
        offset_b = init_sp - addr_symbol_b
        return claripy.Or(
            claripy.ULT(offset_a, offset_b - (width_b - 1)),
            claripy.ULT(offset_b, offset_a - (width_a - 1)),
        )

    def init_slot_width(width):
        return max(width, INIT_ACCESS_SLOT_WIDTH)

    def find_base_addr(ssa_inst):  # 找到构造该访存地址的源头
        assert ssa_inst.is_ldst()
        addr_reg = ssa_inst.get_addr()
        tgt_node = rvfg.find_node_by_value(addr_reg)

        clean_insts = ['add', 'addi', 'addw', 'addiw',
                       'sub', 'subw',
                       'mul', 'mulw',
                       'and', 'andi',
                       'slli', 'srli', 'srai'
                       ]

        # 查找来自未定义寄存器的路径
        undef_paths = rvfg.find_clean_paths(rvfg.undef, tgt_node, clean_insts)
        # 查找来自内存加载的路径
        mem_clean_insts = clean_insts + ['ld', 'lw', 'lh', 'lb', 'lwu', 'lhu', 'lbu']
        mem_paths = rvfg.find_clean_paths(rvfg.mem, tgt_node, mem_clean_insts)

        undef_results = []
        for path in undef_paths:
            src = path[0].tgt.value
            if not any(src is item for item in undef_results):
                undef_results.append(src)

        mem_results = []
        for path in mem_paths:
            inst = path[0].attr.inst
            if inst not in mem_results:
                mem_results.append(inst)

        return undef_results + mem_results

    # map ssa inst to its addr base reg
    undef_base_regs = []
    mem_base_insts = []
    for inst in [i for i in ssas if i.is_ldst()]:
        for source in find_base_addr(inst):
            if isinstance(source, BitVecRef):
                source_reg = bitvec_to_reg(source)
                if source_reg not in undef_base_regs:
                    undef_base_regs.append(source_reg)
            elif isinstance(source, Inst):
                if any(m.pc == source.pc for m in mem_base_insts):
                    continue
                for prog_inst in prog2se.insts:
                    if prog_inst.pc == source.pc:
                        mem_base_insts.append(prog_inst)
                        break
    if verbose:
        print("undef_base_regs", undef_base_regs)
        print("mem_base_insts", mem_base_insts)

    # 穿透内存 Store 的追踪逻辑：处理内存作为中转站的情况
    extra_undef = []
    for load_inst in mem_base_insts:
        # 找到在该 Load 之前、且地址相同的最近一次 Store
        try:
            idx = load_inst.idx
            for i in range(idx - 1, -1, -1):
                prev = ssas[i]
                if prev.is_store() and prev.inst.addr == load_inst.addr:
                    # 找到了对应的 Store，追踪它的数据来源 (rs2)
                    data_reg = prev.inst.rs2
                    data_node = rvfg.find_node_by_value(data_reg)
                    if data_node:
                        clean_insts = ['add', 'addi', 'addw', 'addiw',
                                       'sub', 'subw',
                                       'mul', 'mulw',
                                       'and', 'andi',
                                       'slli', 'srli', 'srai'
                                       ]
                        # 查找数据来源的原始路径
                        added_undef_paths = rvfg.find_clean_paths(rvfg.undef, data_node, clean_insts)
                        for p in added_undef_paths:
                            src = p[0].tgt.value
                            if not any(src is item for item in extra_undef):
                                extra_undef.append(src)
                    else:
                        extra_undef.append(data_reg)
                    break  # 找到最近的一次 Store 即可停止
        except (ValueError, AttributeError):
            continue
    if verbose:
        print("extra_undef", extra_undef)

    # zero fill integer registers
    for i in range(32):
        setattr(init_state.regs, f'x{i}', claripy.BVV(0, 64))

    init_sp = claripy.BVS(REG_PREFIX + 'sp', 64)
    init_state.regs.sp = init_sp

    # create variables for undefined registers
    reg_to_symbol = {}
    for r in regs_undefined:
        var = claripy.BVS(f'{REG_PREFIX + r.name}', 64)
        setattr(init_state.regs, r.name, var)
        reg_to_symbol[r] = var

    if verbose:
        DEBUG(f'{reg_to_symbol =}')

    # init_state.add_constraints(init_sp == claripy.BVV(0x7fff0000, 64))
    init_state.add_constraints(init_state.regs.x0 == 0)

    # create a simulation manager
    simgr = proj.factory.simulation_manager(init_state)

    # mapping unconstrained symbol to undefined registers
    _write_profile_stage(name, "init:symbolic_reg_mapping")
    simgr.explore(
        find=begin_addr + len(regs_undefined) * 4,
        avoid=fail_addr,
    )  # 确保符号执行能够执行完所有的寄存器检查指令
    history_events = simgr.found[0].history.events.hardcopy
    history_events = [e for e in history_events if isinstance(e, SimActionConstraint)]
    if verbose:
        DEBUG(f'{history_events = }')
    undef_check_idx = 0
    for event in history_events:
        constraint = event.constraint
        ast = constraint.ast
        if ast.op not in {'SGE', 'SLE', 'SGT', 'SLT'}:
            continue
        args = [arg for arg in ast.args if hasattr(arg, 'variables')]
        symbolic_args = [arg for arg in args if getattr(arg, 'variables', set())]
        zero_args = [
            arg for arg in args
            if not getattr(arg, 'variables', set())
            and getattr(arg, 'concrete_value', None) == 0
        ]
        if len(symbolic_args) != 1 or not zero_args:
            continue
        if undef_check_idx >= len(regs_undefined):
            continue
        reg_symbol = symbolic_args[0]  # 当前引擎真正正在使用的那个符号 AST 对象，符号执行引擎内部用来代表那个未定义寄存器的“符号变量对象”
        if not str(reg_symbol).startswith(f'<BV64 {REG_PREFIX}'):
            r = regs_undefined[undef_check_idx]
            reg_to_symbol[r] = reg_symbol
            if verbose:
                WARNING(f'unconstrained register: {str(reg_symbol)} for {r}')
        undef_check_idx += 1
    if verbose:
        print("reg_to_symbol", reg_to_symbol)

    undef_reg_check_constraints = []
    for r in regs_undefined:
        symbol = reg_to_symbol.get(r)
        if symbol is not None:
            undef_reg_check_constraints.append(symbol.SGE(claripy.BVV(0, 64)))

    # capture unconstrained load value and symbolic memory addresses
    mem_base_insts = list(mem_base_insts)
    mem_base_insts.sort(key=lambda i: prog2se.insts.index(i))
    mem_base_ids = {id(i) for i in mem_base_insts}
    mem_base_map = {}
    load_accesses = []
    mem_accesses = []
    store_accesses = []
    access_insts = []
    for inst_idx, inst in enumerate(prog2se.insts):
        if inst.type in [IType.Load, IType.Store, IType.Amo]:
            access_insts.append((inst_idx, inst))

    def access_match_key(inst):
        return (inst.pc, inst.type, inst.name, getattr(inst, 'code', str(inst)))

    original_access_indices_by_key = {}
    original_access_order = []
    for original_idx, original_inst in enumerate(prog.insts):
        if original_inst.type not in [IType.Load, IType.Store, IType.Amo]:
            continue
        original_access_order.append(original_idx)
        original_access_indices_by_key.setdefault(access_match_key(original_inst), []).append(original_idx)

    original_access_idx_by_inst_idx = {}
    used_original_accesses_by_key = {}
    for access_ordinal, (inst_idx, inst) in enumerate(access_insts):
        key = access_match_key(inst)
        candidates = original_access_indices_by_key.get(key, [])
        used_count = used_original_accesses_by_key.get(key, 0)
        if used_count < len(candidates):
            original_idx = candidates[used_count]
            used_original_accesses_by_key[key] = used_count + 1
        elif access_ordinal < len(original_access_order):
            original_idx = original_access_order[access_ordinal]
        else:
            original_idx = inst_idx
        original_access_idx_by_inst_idx[inst_idx] = original_idx

    def original_access_addr(inst_idx):
        return begin_addr + inst_idx * 4

    has_symbolic_mul = any(
        inst.name in {'mul', 'mulw', 'mulh', 'mulhsu', 'mulhu'}
        for inst in prog2se.insts
    )
    use_static_memory_collection = (
        len(access_insts) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
        or (has_symbolic_mul and len(access_insts) >= 2)
    )
    static_mul_zero_constraints = []
    static_mul_zero_constraint_keys = set()

    def static_collect_memory_accesses():
        complex_static_collection = True

        def maybe_simplify(expr):
            return expr if complex_static_collection else claripy.simplify(expr)

        def bvv(value, bits=64):
            return claripy.BVV(value & ((1 << bits) - 1), bits)

        def reg_value(reg):
            if reg == XREG[0]:
                return bvv(0)
            return env.get(reg, reg_to_symbol.get(reg, bvv(0)))

        def set_reg(reg, value):
            if reg != XREG[0]:
                env[reg] = maybe_simplify(value)

        def symbolic_expr(expr):
            return bool(getattr(expr, 'variables', set()))

        def record_static_mul_zero_constraint(expr, args=None):
            if not symbolic_expr(expr):
                return
            symbolic_args = [
                arg for arg in (args or ())
                if hasattr(arg, 'op') and symbolic_expr(arg)
            ]
            livein_args = [
                arg for arg in symbolic_args
                if static_ast_vars(arg) and static_ast_vars(arg) <= livein_symbol_vars
            ]
            target = (livein_args or symbolic_args or [expr])[0]
            try:
                constraint = target == bvv(0, target.size())
            except Exception:
                constraint = target == bvv(0)
            key = str(claripy.simplify(constraint))
            if key in static_mul_zero_constraint_keys:
                return
            static_mul_zero_constraint_keys.add(key)
            static_mul_zero_constraints.append(constraint)

        def static_ast_node_count(expr):
            seen = set()
            stack = [expr]
            count = 0
            while stack:
                node = stack.pop()
                key = id(node)
                if key in seen:
                    continue
                seen.add(key)
                count += 1
                for arg in getattr(node, 'args', ()):
                    if hasattr(arg, 'op'):
                        stack.append(arg)
            return count

        def should_preserve_symbolic_mul(lhs, rhs):
            if not complex_static_collection:
                return True
            if not (symbolic_expr(lhs) or symbolic_expr(rhs)):
                return True
            return (
                static_ast_node_count(lhs) + static_ast_node_count(rhs)
                <= STATIC_SYMBOLIC_MUL_NODE_LIMIT
            )

        livein_symbol_vars = set()
        for symbol in reg_to_symbol.values():
            livein_symbol_vars.update(getattr(symbol, 'variables', set()))

        def static_ast_vars(expr):
            return getattr(expr, 'variables', set())

        def static_iter_ast_nodes(expr):
            seen = set()
            stack = [expr]
            while stack:
                node = stack.pop()
                key = id(node)
                if key in seen:
                    continue
                seen.add(key)
                yield node
                for arg in getattr(node, 'args', ()):
                    if hasattr(arg, 'op'):
                        stack.append(arg)

        def static_replace_ast(node, target, replacement):
            if node is target:
                return replacement
            if not hasattr(node, 'op'):
                return node
            changed = False
            new_args = []
            for arg in getattr(node, 'args', ()):
                if hasattr(arg, 'op'):
                    new_arg = static_replace_ast(arg, target, replacement)
                else:
                    new_arg = arg
                if new_arg is not arg:
                    changed = True
                new_args.append(new_arg)
            if not changed:
                return node
            return claripy.simplify(node.make_like(node.op, tuple(new_args)))

        def zero_base_plus_mul_residuals(expr):
            result = expr
            for node in list(static_iter_ast_nodes(expr)):
                if getattr(node, 'op', None) not in {'__mul__', 'Mul'}:
                    continue
                if node.size() != result.size():
                    continue
                node_vars = static_ast_vars(node)
                if not node_vars:
                    continue
                residual = claripy.simplify(result - node)
                residual_vars = static_ast_vars(residual)
                if residual_vars & node_vars:
                    continue
                if not (residual_vars & livein_symbol_vars):
                    continue
                record_static_mul_zero_constraint(node, getattr(node, 'args', ()))
                result = static_replace_ast(result, node, bvv(0))
            return maybe_simplify(result)

        def sign_extend_32(expr):
            return claripy.SignExt(32, expr[31:0])

        def zero_extend_32(expr):
            return claripy.ZeroExt(32, expr[31:0])

        def high_mul(lhs, rhs, lhs_signed, rhs_signed):
            lhs_ext = (
                claripy.SignExt(64, lhs)
                if lhs_signed
                else claripy.ZeroExt(64, lhs)
            )
            rhs_ext = (
                claripy.SignExt(64, rhs)
                if rhs_signed
                else claripy.ZeroExt(64, rhs)
            )
            return (lhs_ext * rhs_ext)[127:64]

        def load_value(inst, inst_idx):
            if inst.name == 'ld':
                return claripy.BVS(f'symbolic_read_static_{len(load_accesses)}_{inst_idx}_64', 64)
            value = claripy.BVS(f'symbolic_read_static_{len(load_accesses)}_{inst_idx}_{inst.width * 8}', inst.width * 8)
            if inst.name == 'lw':
                return claripy.SignExt(32, value)
            if inst.name == 'lwu':
                return claripy.ZeroExt(32, value)
            if inst.name == 'lh':
                return claripy.SignExt(48, value)
            if inst.name == 'lhu':
                return claripy.ZeroExt(48, value)
            if inst.name == 'lb':
                return claripy.SignExt(56, value)
            if inst.name == 'lbu':
                return claripy.ZeroExt(56, value)
            return claripy.BVS(f'symbolic_read_static_{len(load_accesses)}_{inst_idx}_64', 64)

        def eval_r(inst):
            lhs, rhs = reg_value(inst.rs1), reg_value(inst.rs2)
            if inst.name == 'add':
                return lhs + rhs
            if inst.name == 'addw':
                return sign_extend_32(lhs + rhs)
            if inst.name == 'sub':
                return lhs - rhs
            if inst.name == 'subw':
                return sign_extend_32(lhs - rhs)
            if inst.name == 'mul':
                if not should_preserve_symbolic_mul(lhs, rhs):
                    record_static_mul_zero_constraint(lhs * rhs, (lhs, rhs))
                    return bvv(0)
                return lhs * rhs
            if inst.name == 'mulw':
                if not should_preserve_symbolic_mul(lhs, rhs):
                    record_static_mul_zero_constraint(sign_extend_32(lhs * rhs), (lhs, rhs))
                    return bvv(0)
                return sign_extend_32(lhs * rhs)
            if inst.name == 'mulh':
                return high_mul(lhs, rhs, lhs_signed=True, rhs_signed=True)
            if inst.name == 'mulhsu':
                return high_mul(lhs, rhs, lhs_signed=True, rhs_signed=False)
            if inst.name == 'mulhu':
                return high_mul(lhs, rhs, lhs_signed=False, rhs_signed=False)
            if inst.name == 'and':
                return lhs & rhs
            if inst.name == 'or':
                return lhs | rhs
            if inst.name == 'xor':
                return lhs ^ rhs
            return None

        def eval_i(inst):
            lhs = reg_value(inst.rs1)
            imm = inst.imm
            if inst.name == 'addi':
                return lhs + bvv(imm)
            if inst.name == 'addiw':
                return sign_extend_32(lhs + bvv(imm))
            if inst.name == 'andi':
                return lhs & bvv(imm)
            if inst.name == 'ori':
                return lhs | bvv(imm)
            if inst.name == 'xori':
                return lhs ^ bvv(imm)
            if inst.name == 'slli':
                return lhs << imm
            if inst.name == 'srli':
                return claripy.LShR(lhs, imm)
            if inst.name == 'srai':
                return lhs >> imm
            if inst.name == 'slliw':
                return sign_extend_32(lhs[31:0] << imm)
            if inst.name == 'srliw':
                return sign_extend_32(claripy.LShR(lhs[31:0], imm))
            if inst.name == 'sraiw':
                return sign_extend_32(lhs[31:0] >> imm)
            return None

        env = {XREG[0]: bvv(0), XREG[2]: init_sp}
        env.update(reg_to_symbol)
        access_ids = {id(inst): inst_idx for inst_idx, inst in access_insts}

        for inst_idx, inst in enumerate(prog2se.insts):
            _write_profile_stage(
                name,
                "init:symbolic_memory_access_collection",
            )
            if inst.type in [IType.Load, IType.Store, IType.Amo]:
                base_symbol = reg_value(inst.rs1)
                addr_symbol = maybe_simplify(base_symbol + bvv(inst.imm))
                addr_symbol = zero_base_plus_mul_residuals(addr_symbol)
                mem_accesses.append((inst, addr_symbol, inst_idx, inst.width))
                if inst.type in [IType.Store, IType.Amo]:
                    data_symbol = reg_value(inst.rs2)
                    store_accesses.append((inst, addr_symbol, inst_idx, inst.width, data_symbol))
                if inst.type == IType.Load:
                    rd_symbol = load_value(inst, inst_idx)
                    set_reg(inst.rd, rd_symbol)
                    load_entry = (inst, rd_symbol, addr_symbol, inst_idx)
                    load_accesses.append(load_entry)
                    if id(inst) in mem_base_ids:
                        mem_base_map[inst] = load_entry
                        if verbose:
                            DEBUG(f'memory unconstrained symbol {name}: rd_symbol = {rd_symbol} addr_symbol = {addr_symbol}')
                continue

            if isinstance(inst, RFmtInst):
                value = eval_r(inst)
                if value is not None:
                    set_reg(inst.rd, value)
                continue

            if isinstance(inst, IFmtInst):
                value = eval_i(inst)
                if value is not None:
                    set_reg(inst.rd, value)
                continue

            if isinstance(inst, UFmtInst):
                if inst.name == 'li':
                    set_reg(inst.rd, bvv(inst.imm))
                elif inst.name == 'lui':
                    set_reg(inst.rd, bvv(_riscv_u_format_value(inst.imm)))

        _write_profile_stage(name, "init:symbolic_memory_access_collection:done")
        return claripy.Solver()

    if use_static_memory_collection:
        if verbose:
            print("static_memory_access_collection", {
                "accesses": len(access_insts),
                "threshold": STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD,
            })
        solver = static_collect_memory_accesses()
    else:
        dynamic_address_load_incomplete = False
        for inst_idx, inst in access_insts:
            _write_profile_stage(name, "init:symbolic_memory_access_collection")
            target_addr = begin_addr + inst_idx * 4  # 模拟执行，停在指令即将执行的那一刻
            pc = simgr.found[0].ip.concrete_value
            assert pc <= target_addr
            if pc < target_addr:
                simgr = proj.factory.simulation_manager(simgr.found[0])
                simgr.explore(find=target_addr, avoid=fail_addr)
                assert simgr.found
            # when rd == rs1 in a load instruction, the state of rs1 will be overwritten
            # we get the state of rs1 before the execution of the load inst
            base_symbol = getattr(simgr.found[0].regs, str(inst.rs1))

            addr_symbol = base_symbol + inst.imm
            mem_accesses.append((inst, addr_symbol, inst_idx, inst.width))
            if inst.type in [IType.Store, IType.Amo]:
                data_symbol = getattr(simgr.found[0].regs, str(inst.rs2))
                store_accesses.append((inst, addr_symbol, inst_idx, inst.width, data_symbol))

            if inst.type != IType.Load:
                continue

            old_rd_symbol = getattr(simgr.found[0].regs, str(inst.rd))
            load_end_addr = target_addr + 4
            simgr = proj.factory.simulation_manager(simgr.found[0])
            simgr.explore(find=load_end_addr, avoid=fail_addr)  ## 执行这条 ld 指令
            assert simgr.found

            rd_symbol = getattr(simgr.found[0].regs, str(inst.rd))
            old_rd_key = str(claripy.simplify(old_rd_symbol))
            rd_key = str(claripy.simplify(rd_symbol))
            if getattr(addr_symbol, 'variables', set()) and (
                not getattr(rd_symbol, 'variables', set()) or old_rd_key == rd_key
            ):
                if id(inst) in mem_base_ids:
                    dynamic_address_load_incomplete = True
                rd_symbol = claripy.BVS(f'symbolic_read_forced_{len(load_accesses)}_{inst_idx}', 64)
                reg_offset, reg_size = proj.arch.registers[inst.rd.name]
                simgr.found[0].registers.store(reg_offset, rd_symbol, size=reg_size)
                setattr(simgr.found[0].regs, inst.rd.name, rd_symbol)
                setattr(simgr.found[0].regs, f'x{inst.rd.id}', rd_symbol)
            load_entry = (inst, rd_symbol, addr_symbol, inst_idx)
            load_accesses.append(load_entry)
            if id(inst) in mem_base_ids:
                mem_base_map[inst] = load_entry
            if verbose and id(inst) in mem_base_ids:
                DEBUG(f'memory unconstrained symbol {name}: {rd_symbol = } {addr_symbol = }')

        if dynamic_address_load_incomplete:
            # Angr occasionally leaves rd unchanged for a symbolic load and
            # later creates a different unconstrained symbol when rd is used
            # as an address.  The two symbols then cannot describe one legal
            # initial-memory value.  Recollect this small block with the
            # existing instruction-level model, which gives each load one
            # stable symbol throughout its downstream address dataflow.
            mem_accesses.clear()
            load_accesses.clear()
            store_accesses.clear()
            mem_base_map.clear()
            solver = static_collect_memory_accesses()
            use_static_memory_collection = True

    if verbose:
        print('load_accesses', [
            (idx, getattr(inst, 'code', str(inst)), str(addr_symbol), str(rd_symbol), sorted(getattr(rd_symbol, 'variables', set())))
            for inst, rd_symbol, addr_symbol, idx in load_accesses
        ])
        print('mem_accesses', [
            (idx, getattr(inst, 'code', str(inst)), str(addr_symbol), width, sorted(getattr(addr_symbol, 'variables', set())))
            for inst, addr_symbol, idx, width in mem_accesses
        ])

    if use_static_memory_collection:
        if verbose:
            DEBUG(f'{solver.constraints = }')
    else:
        # create a simulation manager
        simgr = proj.factory.simulation_manager(simgr.found[0])
        _write_profile_stage(name, "init:symbolic_execution_to_end")
        simgr.explore(find=end_addr, avoid=fail_addr)

        assert simgr.found, f'simulation fails at {end_addr:#x}'
        final_state = simgr.found[0]

        if verbose:
            DEBUG(f'{final_state.solver.constraints = }')
            DEBUG(f'{final_state.history.events.hardcopy = }')
        solver = final_state.solver
        solver.add(final_state.regs.x0 == 0)

    for constraint in undef_reg_check_constraints:
        solver.add(constraint)
    for constraint in static_mul_zero_constraints:
        solver.add(constraint)

    _write_profile_stage(name, "init:constraint_satisfiability")
    if len(mem_accesses) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD:
        satisfiable_result = None
        try:
            satisfiable_solver = solver.branch()
            satisfiable_solver.timeout = HEURISTIC_SOLVER_TIMEOUT_MS
            satisfiable_result = satisfiable_solver.satisfiable()
        except Exception:
            pass
        assert satisfiable_result is not False, f"[ERROR]: {name} is not satisfiable"
    else:
        assert solver.satisfiable(), f"[ERROR]: {name} is not satisfiable"

    solver.add(init_sp & 7 == 0)  # stack pointer alignment
    # solver.add(final_state.regs.sp == claripy.BVV(0x70a4a7bff690, 64))
    base_solver = claripy.Solver()
    base_solver.add(solver.constraints)
    concrete_sp_solver = base_solver.branch()
    concrete_sp_solver.timeout = HEURISTIC_SOLVER_TIMEOUT_MS
    concrete_sp_solver.add(init_sp == CONCRETE_REPLAY_SP)
    concrete_sp_result = None
    try:
        concrete_sp_result = concrete_sp_solver.satisfiable()
    except Exception:
        pass
    if concrete_sp_result is not False:
        base_solver.add(init_sp == CONCRETE_REPLAY_SP)
    else:
        raise UnsupportedBlockError(f"fixed replay sp is unsatisfiable for {name}")

    extra_undef_vars = []
    for reg in extra_undef:
        if isinstance(reg, BitVecRef):
            reg = bitvec_to_reg(reg)
        if reg in regs_undefined and reg in reg_to_symbol and reg not in extra_undef_vars:
            extra_undef_vars.append(reg)

    mem_entries = list(load_accesses)

    undef_base_vars = set()
    for base_reg in undef_base_regs:
        if base_reg in reg_to_symbol:
            undef_base_vars.update(getattr(reg_to_symbol[base_reg], 'variables', set()))

    pointer_value_varsets = []
    pointer_source_loads = []
    address_source_loads = []
    address_narrow_source_loads = []
    non_additive_addr_value_varsets = []
    pointer_source_keys = set()
    sp_affine_source_load_keys = set()
    mem_base_pcs = {inst.pc for inst in mem_base_insts}

    def pointer_anchor_score(candidate):
        load_idx, load_inst, rd_symbol, _ = candidate
        rd_vars = set(getattr(rd_symbol, 'variables', set()))
        later_address_use_count = sum(
            1
            for _, other_addr_symbol, other_access_idx, _ in mem_accesses
            if other_access_idx > load_idx
            and (getattr(other_addr_symbol, 'variables', set()) & rd_vars)
        )
        return (
            later_address_use_count,
            1 if load_inst.pc in mem_base_pcs else 0,
            load_idx,
        )

    def stored_value_for_load_expr(store_data_symbol, store_width, load_inst):
        if store_width < load_inst.width:
            return None
        if load_inst.name == 'ld':
            return store_data_symbol
        if load_inst.name == 'lw':
            return claripy.SignExt(32, store_data_symbol[31:0])
        if load_inst.name == 'lwu':
            return claripy.ZeroExt(32, store_data_symbol[31:0])
        if load_inst.name == 'lh':
            return claripy.SignExt(48, store_data_symbol[15:0])
        if load_inst.name == 'lhu':
            return claripy.ZeroExt(48, store_data_symbol[15:0])
        if load_inst.name == 'lb':
            return claripy.SignExt(56, store_data_symbol[7:0])
        if load_inst.name == 'lbu':
            return claripy.ZeroExt(56, store_data_symbol[7:0])
        return None

    def forwarded_load_cancels_pointer_residual(
        load_inst,
        rd_symbol,
        load_addr_symbol,
        load_idx,
        consumer_addr,
    ):
        load_addr_key = str(claripy.simplify(load_addr_symbol))
        prior_store = None
        for store_entry in reversed(store_accesses):
            _, store_addr_symbol, store_idx, _, _ = store_entry
            if store_idx >= load_idx:
                continue
            if str(claripy.simplify(store_addr_symbol)) == load_addr_key:
                prior_store = store_entry
                break
        if prior_store is None:
            return False
        _, _, prior_store_idx, store_width, store_data_symbol = prior_store
        stored_expr = stored_value_for_load_expr(
            store_data_symbol,
            store_width,
            load_inst,
        )
        if stored_expr is None:
            return False

        rd_vars = set(getattr(rd_symbol, 'variables', set()))
        residual = claripy.simplify(consumer_addr - rd_symbol)
        residual_vars = set(getattr(residual, 'variables', set()))
        stored_vars = set(getattr(stored_expr, 'variables', set()))
        shared_vars = stored_vars & residual_vars
        if not shared_vars:
            return False
        combined_addr = claripy.simplify(
            claripy.replace_dict(
                consumer_addr,
                {rd_symbol.hash(): stored_expr},
            )
        )
        combined_vars = set(getattr(combined_addr, 'variables', set()))
        if combined_vars & (rd_vars | shared_vars):
            return False

        for _, other_store_addr, other_store_idx, other_store_width, _ in store_accesses:
            if not (prior_store_idx < other_store_idx < load_idx):
                continue
            address_delta = concrete_expr_value(
                claripy.simplify(other_store_addr - load_addr_symbol)
            )
            if address_delta is not None:
                signed_delta = _signed_u64(address_delta)
                if (
                    signed_delta >= load_inst.width
                    or signed_delta + other_store_width <= 0
                ):
                    continue
                return False

            overlap_solver = base_solver.branch()
            overlap_solver.timeout = HEURISTIC_SOLVER_TIMEOUT_MS
            overlap_conditions = [
                other_store_addr + store_byte == load_addr_symbol + load_byte
                for store_byte in range(other_store_width)
                for load_byte in range(load_inst.width)
            ]
            try:
                overlap_solver.add(claripy.Or(*overlap_conditions))
                if overlap_solver.satisfiable():
                    return False
            except Exception:
                return False

        for carrier_reg in regs_undefined:
            carrier_symbol = reg_to_symbol.get(carrier_reg)
            carrier_vars = set(getattr(carrier_symbol, 'variables', set()))
            if not carrier_vars or not (combined_vars & carrier_vars):
                continue
            carrier_residual = claripy.simplify(
                combined_addr - carrier_symbol
            )
            if set(getattr(carrier_residual, 'variables', set())) & carrier_vars:
                continue
            has_independent_direct_use = any(
                getattr(other_inst, 'rs1', None) == carrier_reg
                and not (
                    set(getattr(other_addr, 'variables', set())) & rd_vars
                )
                and concrete_expr_value(
                    claripy.simplify(other_addr - carrier_symbol)
                )
                is not None
                for other_inst, other_addr, _, _ in mem_accesses
            )
            if has_independent_direct_use:
                return True
        return False

    # For every later memory address that depends on loaded data, choose one
    # additive 64-bit load as the stack-relative anchor.  This keeps composite
    # addresses position-independent instead of letting scalar operands encode
    # the fixed replay SP as an absolute constant.
    for _, addr_symbol, access_idx, _ in mem_accesses:
        addr_vars = getattr(addr_symbol, 'variables', set())
        anchor_candidates = []
        sp_affine_candidates = []
        for load_inst, rd_symbol, load_addr_symbol, load_idx in load_accesses:
            if load_idx >= access_idx or load_inst.width != 8:
                continue
            rd_vars = getattr(rd_symbol, 'variables', set())
            if not rd_vars or not (addr_vars & rd_vars):
                continue
            if forwarded_load_cancels_pointer_residual(
                load_inst,
                rd_symbol,
                load_addr_symbol,
                load_idx,
                addr_symbol,
            ):
                sp_affine_candidates.append(
                    (load_idx, load_inst, rd_symbol, load_addr_symbol)
                )
                continue
            residual = claripy.simplify(addr_symbol - rd_symbol)
            if getattr(residual, 'variables', set()) & rd_vars:
                continue
            residual_vars = getattr(residual, 'variables', set())
            if residual_vars:
                residual_zero_solver = base_solver.branch()
                residual_zero_solver.timeout = HEURISTIC_SOLVER_TIMEOUT_MS
                try:
                    residual_zero_solver.add(residual == 0)
                    residual_zero_sat = residual_zero_solver.satisfiable()
                except Exception:
                    residual_zero_sat = False
                if not residual_zero_sat:
                    sp_affine_candidates.append((load_idx, load_inst, rd_symbol, load_addr_symbol))
                    continue
            anchor_candidates.append((load_idx, load_inst, rd_symbol, load_addr_symbol))
        if anchor_candidates:
            _, load_inst, rd_symbol, load_addr_symbol = max(anchor_candidates, key=pointer_anchor_score)
            pointer_source_keys.add((id(load_inst), str(rd_symbol), str(load_addr_symbol)))
        elif sp_affine_candidates:
            load_idx, _, rd_symbol, _ = max(sp_affine_candidates, key=pointer_anchor_score)
            sp_affine_source_load_keys.add((load_idx, str(rd_symbol)))

    for load_inst, rd_symbol, load_addr_symbol, load_idx in load_accesses:
        rd_vars = getattr(rd_symbol, 'variables', set())
        if not rd_vars:
            continue
        used_in_later_addr = any(
            access_idx > load_idx and (getattr(addr_symbol, 'variables', set()) & rd_vars)
            for _, addr_symbol, access_idx, _ in mem_accesses
        )
        if not used_in_later_addr:
            continue

        address_source_loads.append((load_inst, rd_symbol, load_addr_symbol, load_idx))
        pointer_key = (id(load_inst), str(rd_symbol), str(load_addr_symbol))
        if pointer_key in pointer_source_keys:
            pointer_value_varsets.append(frozenset(rd_vars))
            pointer_source_loads.append((load_inst, rd_symbol, load_addr_symbol, load_idx))
        else:
            non_additive_addr_value_varsets.append(frozenset(rd_vars))
            address_narrow_source_loads.append((load_addr_symbol, load_idx))
    if verbose:
        print('mem_base_map', mem_base_map)
        print('pointer_source_loads', [
            (load_idx, getattr(load_inst, 'code', str(load_inst)), str(load_addr_symbol), str(rd_symbol))
            for load_inst, rd_symbol, load_addr_symbol, load_idx in pointer_source_loads
        ])
        print('non_additive_addr_value_varsets', [sorted(v) for v in non_additive_addr_value_varsets])

    def load_value_identity_key(load_idx, rd_symbol, load_addr_symbol):
        return (load_idx, id(rd_symbol), id(load_addr_symbol))

    required_load_value_keys = {
        load_value_identity_key(load_idx, rd_symbol, load_addr_symbol)
        for load_inst, rd_symbol, load_addr_symbol, load_idx in address_source_loads
    }

    pointer_loaded_addr_vars = set()
    for varset in pointer_value_varsets:
        pointer_loaded_addr_vars.update(varset)
    address_loaded_addr_vars = set()
    for _, rd_symbol, _, _ in address_source_loads:
        address_loaded_addr_vars.update(getattr(rd_symbol, 'variables', set()))

    def min_pointer_offset_for_vars(pointer_vars, producer_idx, avoid_ranges=None):
        avoid_ranges = [] if avoid_ranges is None else avoid_ranges
        min_offset = 0
        for inst, addr_symbol, access_idx, width in mem_accesses:
            if access_idx <= producer_idx:
                continue
            addr_vars = getattr(addr_symbol, 'variables', set())
            if not (addr_vars & pointer_vars):
                continue
            imm = _signed_u64(inst.imm)
            if imm >= 0:
                min_offset = max(min_offset, imm + width)
        if not avoid_ranges:
            return min_offset

        def derived_access_ranges(base_offset):
            ranges = [(base_offset, 8, False)]
            for access_inst, access_addr_symbol, access_idx, access_width in mem_accesses:
                if access_idx <= producer_idx:
                    continue
                if not (getattr(access_addr_symbol, 'variables', set()) & pointer_vars):
                    continue
                imm = _signed_u64(access_inst.imm)
                access_offset = base_offset - imm
                if access_offset <= 0 or access_offset > STACK_RANGE:
                    return None
                if access_width > 1 and access_offset % access_width:
                    return None
                ranges.append((
                    access_offset,
                    access_width,
                    access_inst.type == IType.Load,
                ))
            return ranges

        for offset in range(max(0, min_offset), STACK_RANGE + 1):
            ranges = derived_access_ranges(offset)
            if ranges is None:
                continue
            if any(
                concrete_ranges_overlap(access_offset, access_width, avoid_offset, avoid_width)
                and not (
                    read_only
                    and access_offset == avoid_offset
                    and access_width == avoid_width
                )
                for access_offset, access_width, read_only in ranges
                for avoid_offset, avoid_width in avoid_ranges
            ):
                continue
            return offset
        return min_offset

    def forced_same_address(addr_a, addr_b, solver):
        if str(addr_a) == str(addr_b):
            return True
        test_solver = solver.branch()
        test_solver.timeout = HEURISTIC_SOLVER_TIMEOUT_MS
        try:
            test_solver.add(addr_a != addr_b)
            return not test_solver.satisfiable()
        except Exception:
            return False

    def has_forced_prior_same_addr_store(addr_symbol, inst_idx, solver):
        for _, store_addr_symbol, store_idx, _, _ in reversed(store_accesses):
            if store_idx < inst_idx and forced_same_address(store_addr_symbol, addr_symbol, solver):
                return True
        return False

    store_pointer_required_varsets = []
    store_pointer_required_min_offsets = []
    store_pointer_required_exprs = []
    seen_store_pointer_required_varsets = set()
    seen_store_pointer_required_exprs = set()
    pending_store_pointer_required_varsets = []

    def load_value_directly_feeds_pointer_access(load_inst, rd_symbol, load_idx):
        if load_inst.width != 8:
            return False
        rd_vars = set(getattr(rd_symbol, 'variables', set()))
        if not rd_vars:
            return False
        for _, addr_symbol, access_idx, _ in mem_accesses:
            if access_idx <= load_idx:
                continue
            if not (set(getattr(addr_symbol, 'variables', set())) & rd_vars):
                continue
            residual = claripy.simplify(addr_symbol - rd_symbol)
            residual_vars = set(getattr(residual, 'variables', set()))
            if residual_vars & rd_vars:
                continue
            if concrete_expr_value(residual) is not None:
                return True
        return False

    pointer_required_loads = []
    seen_pointer_required_loads = set()
    for entry in pointer_source_loads:
        load_inst, rd_symbol, load_addr_symbol, load_idx = entry
        key = (load_idx, str(rd_symbol), str(load_addr_symbol))
        if key in seen_pointer_required_loads:
            continue
        seen_pointer_required_loads.add(key)
        pointer_required_loads.append(entry)
    for load_inst, rd_symbol, load_addr_symbol, load_idx in load_accesses:
        if not load_value_directly_feeds_pointer_access(load_inst, rd_symbol, load_idx):
            continue
        key = (load_idx, str(rd_symbol), str(load_addr_symbol))
        if key in seen_pointer_required_loads:
            continue
        seen_pointer_required_loads.add(key)
        pointer_required_loads.append((load_inst, rd_symbol, load_addr_symbol, load_idx))

    def add_store_pointer_required_varset(required_varset, required_min_offset):
        required_varset = frozenset(required_varset)
        if not required_varset:
            return
        required_min_offset = _align_up(
            max(INIT_PTR_MIN_OFFSET, required_min_offset),
            INIT_ACCESS_ALIGN,
        )
        key = (required_varset, required_min_offset)
        if key in seen_store_pointer_required_varsets:
            return
        seen_store_pointer_required_varsets.add(key)
        store_pointer_required_varsets.append(required_varset)
        store_pointer_required_min_offsets.append((
            required_varset,
            required_min_offset,
        ))
        pending_store_pointer_required_varsets.append((
            required_varset,
            required_min_offset,
        ))

    def store_pointer_required_carrier_varsets(stored_expr, stored_vars, consumer_idx):
        stored_vars = set(stored_vars)
        if len(stored_vars) == 1:
            return [frozenset(stored_vars)]

        carrier_candidates = []
        for carrier_inst, carrier_rd_symbol, _, carrier_idx in load_accesses:
            if carrier_idx >= consumer_idx or carrier_inst.width != 8:
                continue
            carrier_vars = set(getattr(carrier_rd_symbol, 'variables', set()))
            if not carrier_vars or not (stored_vars & carrier_vars):
                continue
            residual = claripy.simplify(stored_expr - carrier_rd_symbol)
            residual_vars = set(getattr(residual, 'variables', set()))
            if residual_vars & carrier_vars:
                continue
            residual_zero_solver = base_solver.branch()
            residual_zero_solver.timeout = HEURISTIC_SOLVER_TIMEOUT_MS
            try:
                residual_zero_solver.add(residual == 0)
                residual_zero_sat = residual_zero_solver.satisfiable()
            except Exception:
                residual_zero_sat = False
            if residual_zero_sat:
                carrier_candidates.append((carrier_idx, frozenset(carrier_vars)))
        if carrier_candidates:
            _, carrier_varset = max(carrier_candidates, key=lambda item: item[0])
            return [carrier_varset]
        return [frozenset(stored_vars)]

    def add_store_pointer_required_expr(stored_expr, required_min_offset, consumer_idx):
        stored_vars = set(getattr(stored_expr, 'variables', set()))
        if not stored_vars:
            return
        required_min_offset = _align_up(
            max(INIT_PTR_MIN_OFFSET, required_min_offset),
            INIT_ACCESS_ALIGN,
        )
        expr_key_for_required = (str(claripy.simplify(stored_expr)), required_min_offset)
        if expr_key_for_required not in seen_store_pointer_required_exprs:
            seen_store_pointer_required_exprs.add(expr_key_for_required)
            store_pointer_required_exprs.append((stored_expr, required_min_offset))
        for required_varset in store_pointer_required_carrier_varsets(
            stored_expr,
            stored_vars,
            consumer_idx,
        ):
            add_store_pointer_required_varset(required_varset, required_min_offset)

    required_prior_store_cache = {}

    def prior_store_for_required_load(load_addr_symbol, load_idx):
        addr_key = str(claripy.simplify(load_addr_symbol))
        cache_key = (addr_key, load_idx)
        if cache_key in required_prior_store_cache:
            return required_prior_store_cache[cache_key]
        load_vars = set(getattr(load_addr_symbol, 'variables', set()))
        for store_inst, store_addr_symbol, store_idx, store_width, store_data_symbol in reversed(store_accesses):
            if store_idx >= load_idx:
                continue
            same_store_load_addr = (
                str(claripy.simplify(store_addr_symbol))
                == addr_key
            )
            if (
                not same_store_load_addr
                and set(getattr(store_addr_symbol, 'variables', set()))
                & load_vars
            ):
                same_store_load_addr = forced_same_address(
                    store_addr_symbol,
                    load_addr_symbol,
                    base_solver,
                )
            if not same_store_load_addr:
                continue
            result = store_inst, store_addr_symbol, store_idx, store_width, store_data_symbol
            required_prior_store_cache[cache_key] = result
            return result
        required_prior_store_cache[cache_key] = None
        return None

    for load_inst, rd_symbol, load_addr_symbol, load_idx in pointer_required_loads:
        prior_store = prior_store_for_required_load(load_addr_symbol, load_idx)
        if prior_store is not None:
            _, _, _, store_width, store_data_symbol = prior_store
            stored_expr = stored_value_for_load_expr(store_data_symbol, store_width, load_inst)
            if stored_expr is not None:
                add_store_pointer_required_expr(
                    stored_expr,
                    min_pointer_offset_for_vars(getattr(rd_symbol, 'variables', set()), load_idx),
                    load_idx,
                )

    processed_required_pointer_loads = set()
    while pending_store_pointer_required_varsets:
        required_vars, required_min_offset = pending_store_pointer_required_varsets.pop(0)
        for load_inst, rd_symbol, load_addr_symbol, load_idx in load_accesses:
            rd_vars = set(getattr(rd_symbol, 'variables', set()))
            if not rd_vars or not (rd_vars & required_vars):
                continue
            required_load_value_keys.add(
                load_value_identity_key(load_idx, rd_symbol, load_addr_symbol)
            )
            process_key = (load_idx, required_vars, required_min_offset)
            if process_key in processed_required_pointer_loads:
                continue
            processed_required_pointer_loads.add(process_key)
            prior_store = prior_store_for_required_load(load_addr_symbol, load_idx)
            if prior_store is None:
                continue
            _, _, _, store_width, store_data_symbol = prior_store
            stored_expr = stored_value_for_load_expr(store_data_symbol, store_width, load_inst)
            if stored_expr is None:
                continue
            add_store_pointer_required_expr(
                stored_expr,
                required_min_offset,
                load_idx,
            )

    for load_inst, rd_symbol, load_addr_symbol, load_idx in load_accesses:
        rd_vars = set(getattr(rd_symbol, 'variables', set()))
        if not rd_vars:
            continue
        if any(rd_vars & required_vars for required_vars in store_pointer_required_varsets):
            required_load_value_keys.add(
                load_value_identity_key(load_idx, rd_symbol, load_addr_symbol)
            )

    def stack_pointer_constraints_for_expr(expr, min_offset=INIT_PTR_MIN_OFFSET):
        offset_expr = init_sp - expr
        return [
            claripy.UGE(expr, init_sp - claripy.BVV(STACK_RANGE, 64)),
            claripy.ULE(expr, init_sp - claripy.BVV(min_offset, 64)),
            (offset_expr & (INIT_ACCESS_ALIGN - 1)) == 0,
        ]

    for required_expr, required_min_offset in store_pointer_required_exprs:
        for constraint in stack_pointer_constraints_for_expr(
            required_expr,
            required_min_offset,
        ):
            base_solver.add(constraint)

    def stack_pointer_constraints_for_access_base(expr, min_offset, access_width, residual_imm):
        offset_expr = init_sp - expr
        min_offset = max(1, min_offset)
        constraints = [
            claripy.UGE(expr, init_sp - claripy.BVV(STACK_RANGE, 64)),
            claripy.ULE(expr, init_sp - claripy.BVV(min_offset, 64)),
        ]
        if access_width > 1:
            mask = access_width - 1
            constraints.append(
                (offset_expr & mask) == claripy.BVV(residual_imm & mask, offset_expr.size())
            )
        return constraints

    def livein_memory_base_regs(instructions):
        regs = set()
        defined = {XREG[0]}
        for inst in instructions:
            if inst.type in [IType.Load, IType.Store, IType.Amo]:
                rs1 = getattr(inst, 'rs1', None)
                if rs1 in XREG and rs1 not in defined:
                    regs.add(rs1)
            rd = inst.get_def()
            if rd in XREG and rd != XREG[0]:
                defined.add(rd)
        return regs

    def build_arithmetic_address_hints():
        env = {}
        load_value_hints = {}
        load_pointer_hints = {}
        reg_pointer_hints = {}
        reg_value_hints = {}
        load_nonzero_hints = set()
        reg_nonzero_hints = set()

        def const_expr(value):
            return ('const', value & ((1 << 64) - 1))

        def reg_expr(reg):
            return env.get(reg, ('reg', reg))

        def unknown_expr(inst):
            return ('unknown', getattr(inst, 'pc', id(inst)), getattr(inst, 'name', 'unknown'))

        def op_expr(op, *args, preferred=None):
            if preferred is None:
                return (op, *args)
            return (op, *args, {'preferred': preferred})

        def expr_args(expr):
            if not isinstance(expr, tuple):
                return []
            return [arg for arg in expr[1:] if isinstance(arg, tuple)]

        def preferred_arg(expr):
            if not isinstance(expr, tuple) or not expr:
                return None
            marker = expr[-1]
            if isinstance(marker, dict):
                return marker.get('preferred')
            return None

        def has_kind(expr, kind):
            if not isinstance(expr, tuple):
                return False
            if expr[0] == kind:
                return True
            return any(has_kind(arg, kind) for arg in expr_args(expr))

        def contains(expr, target):
            if expr == target:
                return True
            if not isinstance(expr, tuple):
                return False
            return any(contains(arg, target) for arg in expr_args(expr))

        def collect_loads(expr, out=None):
            out = [] if out is None else out
            if not isinstance(expr, tuple):
                return out
            if expr[0] == 'load':
                out.append(expr)
            for arg in expr_args(expr):
                collect_loads(arg, out)
            return out

        def collect_regs(expr, out=None):
            out = [] if out is None else out
            if not isinstance(expr, tuple):
                return out
            if expr[0] == 'reg':
                out.append(expr)
            for arg in expr_args(expr):
                collect_regs(arg, out)
            return out

        def collect_narrow_index_terms(expr, out=None):
            out = [] if out is None else out
            if not isinstance(expr, tuple):
                return out
            if expr[0] == 'narrow':
                out.extend(collect_loads(expr))
                out.extend(collect_regs(expr))
                return out
            for arg in expr_args(expr):
                collect_narrow_index_terms(arg, out)
            return out

        def collect_narrow_exprs(expr, out=None):
            out = [] if out is None else out
            if not isinstance(expr, tuple):
                return out
            if expr[0] == 'narrow':
                out.append(expr)
            for arg in expr_args(expr):
                collect_narrow_exprs(arg, out)
            return out

        def append_reg_value_hint(reg, value):
            if reg not in reg_to_symbol:
                return False
            value &= 0xffffffff
            existing = {v & 0xffffffff for v in reg_value_hints.get(reg, [])}
            if existing and existing != {value}:
                return False
            reg_value_hints.setdefault(reg, []).append(value)
            return True

        def word_affine(expr):
            mask = (1 << 32) - 1

            def normalize(const, coeffs):
                return (
                    const & mask,
                    {reg: coeff & mask for reg, coeff in coeffs.items() if coeff & mask},
                )

            def add_affine(lhs, rhs, sign=1):
                const = lhs[0] + sign * rhs[0]
                coeffs = dict(lhs[1])
                for reg, coeff in rhs[1].items():
                    coeffs[reg] = coeffs.get(reg, 0) + sign * coeff
                return normalize(const, coeffs)

            def scale_affine(affine, factor):
                const, coeffs = affine
                return normalize(
                    const * factor,
                    {reg: coeff * factor for reg, coeff in coeffs.items()},
                )

            if not isinstance(expr, tuple) or not expr:
                return None
            if expr[0] == 'const':
                return normalize(expr[1], {})
            if expr[0] == 'reg':
                reg = expr[1]
                if reg not in reg_to_symbol:
                    return None
                return normalize(0, {reg: 1})
            if expr[0] == 'narrow':
                args = expr_args(expr)
                return word_affine(args[0]) if args else None

            op = expr[0]
            args = expr_args(expr)
            if op == 'add':
                result = normalize(0, {})
                for arg in args:
                    aff = word_affine(arg)
                    if aff is None:
                        return None
                    result = add_affine(result, aff)
                return result
            if op == 'sub':
                if not args:
                    return None
                result = word_affine(args[0])
                if result is None:
                    return None
                for arg in args[1:]:
                    aff = word_affine(arg)
                    if aff is None:
                        return None
                    result = add_affine(result, aff, sign=-1)
                return result
            if op == 'mul' and len(args) == 2:
                lhs, rhs = args
                if is_const_expr(lhs):
                    rhs_aff = word_affine(rhs)
                    return None if rhs_aff is None else scale_affine(rhs_aff, lhs[1])
                if is_const_expr(rhs):
                    lhs_aff = word_affine(lhs)
                    return None if lhs_aff is None else scale_affine(lhs_aff, rhs[1])
            return None

        def add_word_affine_zero_hint(expr):
            affine = word_affine(expr)
            if affine is None:
                return set()
            const, coeffs = affine
            if not coeffs:
                return set()

            regs_by_use = []
            seen_regs = set()
            for reg_expr_item in collect_regs(expr):
                reg = reg_expr_item[1]
                if reg in coeffs and reg not in seen_regs:
                    regs_by_use.append(reg)
                    seen_regs.add(reg)

            target_reg = None
            target_coeff = None
            for reg in reversed(regs_by_use):
                coeff = coeffs.get(reg, 0) & 0xffffffff
                if coeff & 1:
                    target_reg = reg
                    target_coeff = coeff
                    break
            if target_reg is None:
                return set()

            target_value = ((-const) * pow(target_coeff, -1, 1 << 32)) & 0xffffffff
            planned = {}
            for reg in coeffs:
                planned[reg] = 0
            planned[target_reg] = target_value

            for reg, value in planned.items():
                existing = {v & 0xffffffff for v in reg_value_hints.get(reg, [])}
                if existing and existing != {value}:
                    return set()
            for reg, value in planned.items():
                append_reg_value_hint(reg, value)
            return set(planned)

        def mul_depth(expr, target, depth=0):
            if expr == target:
                return depth
            if not isinstance(expr, tuple):
                return -1
            next_depth = depth + 1 if expr[0] == 'mul' else depth
            return max(
                [mul_depth(arg, target, next_depth) for arg in expr_args(expr)] or [-1]
            )

        def carrier_hint_score(expr, target):
            if not contains(expr, target):
                return -1
            if expr == target:
                return 0
            score = 0
            preferred = preferred_arg(expr)
            if preferred is not None and contains(preferred, target):
                score = max(score, 1 + carrier_hint_score(preferred, target))
            for arg in expr_args(expr):
                if arg is preferred:
                    continue
                score = max(score, carrier_hint_score(arg, target))
            return score

        def add_value_hint(expr, value, allow_word_value=False):
            if not isinstance(expr, tuple):
                return False
            value &= ((1 << 64) - 1)
            if expr[0] == 'const':
                return expr[1] == value
            if expr[0] == 'load':
                pc = expr[1]
                load_value_hints.setdefault(pc, []).append(value)
                return True
            if expr[0] == 'reg':
                reg = expr[1]
                if reg not in reg_to_symbol:
                    return False
                if value & (1 << 63):
                    if not allow_word_value:
                        return False
                    value &= 0xffffffff
                reg_value_hints.setdefault(reg, []).append(value)
                return True
            if expr[0] == 'unknown':
                return False
            op = expr[0]
            args = expr_args(expr)
            if op == 'narrow' and args:
                return add_value_hint(args[0], value, allow_word_value=True)
            if value == 0 and op in {'add', 'sub'}:
                signed_terms = []
                concrete_total = 0
                for i, arg in enumerate(args):
                    sign = 1 if op == 'add' or i == 0 else -1
                    if arg[0] == 'const':
                        concrete_total = (concrete_total + sign * arg[1]) & ((1 << 64) - 1)
                    else:
                        signed_terms.append((sign, arg))
                if not signed_terms:
                    return concrete_total == value
                target = (value - concrete_total) & ((1 << 64) - 1)
                for sign, arg in signed_terms[:-1]:
                    if not add_value_hint(arg, 0, allow_word_value=allow_word_value):
                        return False
                sign, arg = signed_terms[-1]
                arg_target = target if sign > 0 else (-target) & ((1 << 64) - 1)
                return add_value_hint(arg, arg_target, allow_word_value=allow_word_value)
            if value == 1 and op == 'mul':
                return all(add_value_hint(arg, 1, allow_word_value=allow_word_value) for arg in args)
            if op == 'mul' and len(args) == 2:
                lhs, rhs = args
                if is_const_expr(lhs) and lhs[1] != 0 and value % lhs[1] == 0:
                    return add_value_hint(rhs, value // lhs[1], allow_word_value=allow_word_value)
                if is_const_expr(rhs) and rhs[1] != 0 and value % rhs[1] == 0:
                    return add_value_hint(lhs, value // rhs[1], allow_word_value=allow_word_value)
            if value == 0 and op == 'mul':
                def zero_mul_arg_key(arg):
                    if isinstance(arg, tuple) and arg and arg[0] == 'reg':
                        return (0, 0)
                    if isinstance(arg, tuple) and arg and arg[0] == 'load':
                        return (0, 1)
                    return (1, len(str(arg)))
                return any(add_value_hint(arg, 0, allow_word_value=allow_word_value) for arg in sorted(args, key=zero_mul_arg_key))
            if value == 0 and op == 'shift' and args:
                return add_value_hint(args[0], 0, allow_word_value=allow_word_value)
            return False

        def constrain_to_carrier(expr, carrier):
            if expr == carrier:
                return True
            if not isinstance(expr, tuple):
                return False
            op = expr[0]
            args = expr_args(expr)
            carrier_args = [arg for arg in args if contains(arg, carrier)]
            if len(carrier_args) != 1:
                return False
            carrier_arg = carrier_args[0]
            if op == 'add':
                return constrain_to_carrier(carrier_arg, carrier) and all(
                    add_value_hint(arg, 0)
                    for arg in args
                    if arg is not carrier_arg
                )
            if op == 'sub':
                if not args or carrier_arg is not args[0]:
                    return False
                return constrain_to_carrier(carrier_arg, carrier) and all(
                    add_value_hint(arg, 0)
                    for arg in args[1:]
                )
            if op == 'mul':
                return constrain_to_carrier(carrier_arg, carrier) and all(
                    add_value_hint(arg, 1)
                    for arg in args
                    if arg is not carrier_arg
                )
            return False

        def carrier_base_score(carrier):
            if carrier[0] == 'load':
                return 1 if carrier[1] in mem_base_pcs else 0
            if carrier[0] == 'reg':
                return 1 if carrier[1] in undef_base_regs else 0
            return 0

        def carrier_order_key(expr, carrier):
            return (
                carrier_hint_score(expr, carrier),
                carrier_base_score(carrier),
                1 if carrier[0] == 'reg' else 0,
                -mul_depth(expr, carrier),
            )

        def choose_carrier(expr):
            loads = collect_loads(expr)
            loads = [load for load in loads if load[2].width == 8]
            regs = collect_regs(expr)
            carriers = loads + regs
            if not carriers:
                return None
            return max(carriers, key=lambda item: carrier_order_key(expr, item))

        def is_const_expr(expr):
            return isinstance(expr, tuple) and expr and expr[0] == 'const'

        def add_pointer_hint(expr, min_offset):
            carrier = expr
            if not (isinstance(carrier, tuple) and carrier and carrier[0] in {'load', 'reg'}):
                carrier = choose_carrier(expr)
            if carrier is None:
                return False
            if carrier[0] == 'load':
                load_pc, load_inst = carrier[1], carrier[2]
                if load_inst.width != 8:
                    return False
                load_pointer_hints[load_pc] = max(
                    load_pointer_hints.get(load_pc, 0),
                    min_offset,
                )
                return True
            if carrier[0] == 'reg':
                reg = carrier[1]
                if reg not in reg_to_symbol:
                    return False
                reg_pointer_hints[reg] = max(
                    reg_pointer_hints.get(reg, 0),
                    min_offset,
                )
                return True
            return False

        def add_nonzero_hint(expr):
            if not isinstance(expr, tuple):
                return False
            if expr[0] == 'load':
                load_nonzero_hints.add(expr[1])
                return True
            if expr[0] == 'reg':
                reg = expr[1]
                if reg in reg_to_symbol:
                    reg_nonzero_hints.add(reg)
                    return True
            return False

        def zero_additive_mul_index(expr, width):
            if not isinstance(expr, tuple):
                return False
            op = expr[0]
            args = expr_args(expr)
            if op in {'add', 'sub'}:
                signed_args = [
                    (1 if op == 'add' or i == 0 else -1, arg)
                    for i, arg in enumerate(args)
                ]
                mul_args = [arg for _, arg in signed_args if has_kind(arg, 'mul')]
                non_mul_carriers = [
                    arg for sign, arg in signed_args
                    if sign > 0
                    if not has_kind(arg, 'mul') and not is_const_expr(arg)
                ]
                if mul_args and non_mul_carriers:
                    def additive_index_leaf_carrier(item):
                        loads = [load for load in collect_loads(item) if load[2].width == 8]
                        if loads:
                            return loads[-1]
                        return choose_carrier(item) or item

                    def additive_index_carrier_key(item):
                        carrier = additive_index_leaf_carrier(item)
                        base_key = carrier_order_key(expr, carrier)
                        is_load_carrier = (
                            isinstance(carrier, tuple)
                            and carrier
                            and carrier[0] == 'load'
                        )
                        return base_key + (1 if is_load_carrier else 0,)

                    carriers = sorted(
                        non_mul_carriers,
                        key=additive_index_carrier_key,
                        reverse=True,
                    )
                    selected_carrier = None
                    selected_carrier_expr = None
                    for carrier_expr in carriers:
                        carrier = additive_index_leaf_carrier(carrier_expr)
                        if add_pointer_hint(carrier, 0):
                            selected_carrier = carrier
                            selected_carrier_expr = carrier_expr
                            break
                    if selected_carrier is None:
                        return False
                    if selected_carrier_expr != selected_carrier:
                        constrain_to_carrier(selected_carrier_expr, selected_carrier)

                    expr_mask = (1 << 64) - 1
                    concrete_total = 0
                    residual_terms = []
                    for sign, arg in signed_args:
                        if arg == selected_carrier_expr or arg == selected_carrier:
                            continue
                        if is_const_expr(arg):
                            concrete_total = (concrete_total + sign * arg[1]) & expr_mask
                        else:
                            residual_terms.append((sign, arg))
                    if residual_terms:
                        target = (-concrete_total) & expr_mask
                        residual_terms.sort(
                            key=lambda item: (
                                1 if has_kind(item[1], 'mul') else 0,
                                len(collect_loads(item[1])),
                                len(collect_regs(item[1])),
                                len(str(item[1])),
                            )
                        )
                        for sign, arg in residual_terms[:-1]:
                            if not add_value_hint(arg, 0):
                                return False
                        sign, arg = residual_terms[-1]
                        arg_target = target if sign > 0 else (-target) & expr_mask
                        if not add_value_hint(arg, arg_target):
                            return False
                    return True
                changed = False
                for arg in args:
                    if has_kind(arg, 'mul') and zero_additive_mul_index(arg, width):
                        changed = True
                return changed
            return False

        def collect_signed_add_terms(expr, sign=1, out=None):
            out = [] if out is None else out
            if not isinstance(expr, tuple):
                return out
            op = expr[0]
            args = expr_args(expr)
            if op == 'add':
                for arg in args:
                    collect_signed_add_terms(arg, sign, out)
                return out
            if op == 'sub' and args:
                collect_signed_add_terms(args[0], sign, out)
                for arg in args[1:]:
                    collect_signed_add_terms(arg, -sign, out)
                return out
            out.append((sign, expr))
            return out

        def add_linear_address_hint(addr_expr, width):
            terms = collect_signed_add_terms(addr_expr)
            def is_pointer_capable_linear_term(term):
                if not (isinstance(term, tuple) and term):
                    return False
                if term[0] == 'reg':
                    return True
                if term[0] == 'load':
                    return term[2].width == 8
                return False

            carrier_terms = [
                term for sign, term in terms
                if sign > 0
                and is_pointer_capable_linear_term(term)
            ]
            if not carrier_terms:
                return False

            carrier = max(
                enumerate(carrier_terms),
                key=lambda item: (
                    carrier_base_score(item[1]),
                    carrier_order_key(addr_expr, item[1]),
                    item[0],
                ),
            )[1]
            changed = add_pointer_hint(carrier, 0)
            const_total = 0
            for sign, term in terms:
                if is_const_expr(term):
                    const_total += sign * _signed_u64(term[1])
            align_target = 0
            if width and width > 1:
                align_target = (-const_total) % width
            adjustable_positive_terms = [
                term for sign, term in terms
                if sign > 0
                and term != carrier
                and isinstance(term, tuple)
                and term
                and term[0] in {'load', 'reg'}
            ]
            adjusted_term = None
            if align_target and adjustable_positive_terms:
                adjusted_term = adjustable_positive_terms[0]
            for sign, term in terms:
                if term == carrier or is_const_expr(term):
                    continue
                if sign < 0:
                    changed = add_value_hint(term, 0) or changed
                elif sign > 0 and isinstance(term, tuple) and term and term[0] in {'load', 'reg'}:
                    target = align_target if term == adjusted_term else 0
                    changed = add_value_hint(term, target) or changed
            return changed

        def apply_address_hint(addr_expr, width):
            affine_hint_regs = set()
            for narrow_expr in collect_narrow_exprs(addr_expr):
                affine_hint_regs.update(add_word_affine_zero_hint(narrow_expr))
            for term in collect_narrow_index_terms(addr_expr):
                if term[0] == 'reg' and term[1] in affine_hint_regs:
                    continue
                add_value_hint(term, 0)
            if not has_kind(addr_expr, 'mul'):
                add_linear_address_hint(addr_expr, width)
                return
            snapshot = (
                copy.deepcopy(load_value_hints),
                copy.deepcopy(load_pointer_hints),
                copy.deepcopy(reg_pointer_hints),
                copy.deepcopy(reg_value_hints),
            )
            if zero_additive_mul_index(addr_expr, width):
                return
            load_value_hints.clear()
            load_value_hints.update(snapshot[0])
            load_pointer_hints.clear()
            load_pointer_hints.update(snapshot[1])
            reg_pointer_hints.clear()
            reg_pointer_hints.update(snapshot[2])
            reg_value_hints.clear()
            reg_value_hints.update(snapshot[3])

            carrier = choose_carrier(addr_expr)
            if carrier is None:
                return
            snapshot = (
                copy.deepcopy(load_value_hints),
                copy.deepcopy(load_pointer_hints),
                copy.deepcopy(reg_pointer_hints),
                copy.deepcopy(reg_value_hints),
            )
            if constrain_to_carrier(addr_expr, carrier):
                if carrier[0] == 'load':
                    load_pointer_hints[carrier[1]] = max(load_pointer_hints.get(carrier[1], 0), 0)
                elif carrier[0] == 'reg':
                    reg_pointer_hints[carrier[1]] = max(reg_pointer_hints.get(carrier[1], 0), 0)
            else:
                load_value_hints.clear()
                load_value_hints.update(snapshot[0])
                load_pointer_hints.clear()
                load_pointer_hints.update(snapshot[1])
                reg_pointer_hints.clear()
                reg_pointer_hints.update(snapshot[2])
                reg_value_hints.clear()
                reg_value_hints.update(snapshot[3])

        for inst in prog.insts:
            if inst.type in [IType.Load, IType.Store, IType.Amo]:
                addr_expr = op_expr('add', reg_expr(inst.rs1), const_expr(inst.imm))
                apply_address_hint(addr_expr, inst.width)
            if inst.type == IType.Load:
                env[inst.rd] = ('load', inst.pc, inst)
                continue
            if isinstance(inst, StoreInst):
                continue
            rd = inst.get_def()
            if not rd:
                continue
            if isinstance(inst, RFmtInst):
                lhs = reg_expr(inst.rs1)
                rhs = reg_expr(inst.rs2)
                if inst.name in {'div', 'divu', 'divw', 'divuw', 'rem', 'remu', 'remw', 'remuw'}:
                    add_nonzero_hint(rhs)
                preferred = None
                if inst.rd == inst.rs1:
                    preferred = lhs
                elif inst.rd == inst.rs2:
                    preferred = rhs
                if inst.name == 'add':
                    env[rd] = op_expr('add', lhs, rhs, preferred=preferred)
                elif inst.name == 'addw':
                    env[rd] = op_expr('narrow', op_expr('add', lhs, rhs, preferred=preferred), preferred=preferred)
                elif inst.name == 'sub':
                    env[rd] = op_expr('sub', lhs, rhs, preferred=preferred)
                elif inst.name == 'subw':
                    env[rd] = op_expr('narrow', op_expr('sub', lhs, rhs, preferred=preferred), preferred=preferred)
                elif inst.name == 'mul':
                    env[rd] = op_expr('mul', lhs, rhs, preferred=preferred)
                elif inst.name == 'mulw':
                    env[rd] = op_expr('narrow', op_expr('mul', lhs, rhs, preferred=preferred), preferred=preferred)
                else:
                    env[rd] = unknown_expr(inst)
            elif isinstance(inst, IFmtInst):
                lhs = reg_expr(inst.rs1)
                preferred = lhs if inst.rd == inst.rs1 else None
                if inst.name == 'addi':
                    env[rd] = op_expr('add', lhs, const_expr(inst.imm), preferred=preferred)
                elif inst.name == 'addiw':
                    env[rd] = op_expr('narrow', op_expr('add', lhs, const_expr(inst.imm), preferred=preferred), preferred=preferred)
                elif inst.name == 'slli':
                    env[rd] = op_expr('mul', lhs, const_expr(1 << inst.imm), preferred=preferred)
                elif inst.name in {'srli', 'srai'}:
                    env[rd] = op_expr('shift', lhs, const_expr(inst.imm), preferred=preferred)
                elif inst.name == 'slliw':
                    env[rd] = op_expr('narrow', op_expr('mul', lhs, const_expr(1 << inst.imm), preferred=preferred), preferred=preferred)
                elif inst.name in {'srliw', 'sraiw'}:
                    env[rd] = op_expr('narrow', lhs, preferred=preferred)
                else:
                    env[rd] = unknown_expr(inst)
            else:
                env[rd] = unknown_expr(inst)

        direct_memory_base_regs = livein_memory_base_regs(prog.insts)
        for reg in list(reg_pointer_hints):
            if reg in direct_memory_base_regs:
                continue
            values = {value & ((1 << 64) - 1) for value in reg_value_hints.get(reg, [])}
            if len(values) == 1:
                del reg_pointer_hints[reg]

        return load_value_hints, load_pointer_hints, reg_pointer_hints, reg_value_hints, load_nonzero_hints, reg_nonzero_hints

    load_value_hints, load_pointer_hints, reg_pointer_hints, reg_value_hints, load_nonzero_hints, reg_nonzero_hints = build_arithmetic_address_hints()
    direct_memory_base_regs = livein_memory_base_regs(prog.insts)

    canonical_regs_by_name = {reg.name: reg for reg in reg_to_symbol}

    def canonical_hint_reg(reg):
        return canonical_regs_by_name.get(getattr(reg, 'name', None), reg)

    canonical_reg_pointer_hints = {}
    for reg, min_offset in reg_pointer_hints.items():
        canonical = canonical_hint_reg(reg)
        canonical_reg_pointer_hints[canonical] = max(
            canonical_reg_pointer_hints.get(canonical, 0),
            min_offset,
        )
    reg_pointer_hints = canonical_reg_pointer_hints

    canonical_reg_value_hints = {}
    for reg, values in reg_value_hints.items():
        canonical = canonical_hint_reg(reg)
        canonical_reg_value_hints.setdefault(canonical, []).extend(values)
    reg_value_hints = canonical_reg_value_hints

    reg_nonzero_hints = {canonical_hint_reg(reg) for reg in reg_nonzero_hints}

    trusted_base_regs = set(direct_memory_base_regs)
    for reg in list(reg_pointer_hints):
        if reg in trusted_base_regs:
            continue
        symbol = reg_to_symbol.get(reg)
        if symbol is None:
            continue
        symbol_vars = getattr(symbol, 'variables', set())
        if not symbol_vars:
            continue
        address_uses = [
            addr_symbol
            for _, addr_symbol, _, _ in mem_accesses
            if getattr(addr_symbol, 'variables', set()) & symbol_vars
        ]
        if not address_uses:
            continue
        def has_independent_address_use(other_vars):
            return any(
                (getattr(other_addr_symbol, 'variables', set()) & other_vars)
                and not (getattr(other_addr_symbol, 'variables', set()) & symbol_vars)
                for _, other_addr_symbol, _, _ in mem_accesses
            )

        covered_by_trusted_base = [
            any(
                other_reg != reg
                and other_vars
                and (getattr(addr_symbol, 'variables', set()) & other_vars)
                and (
                    other_reg in trusted_base_regs
                    or has_independent_address_use(other_vars)
                )
                for other_reg, other_symbol in reg_to_symbol.items()
                for other_vars in [getattr(other_symbol, 'variables', set())]
            )
            for addr_symbol in address_uses
        ]
        if not all(covered_by_trusted_base):
            continue
        del reg_pointer_hints[reg]
        existing_values = {
            value & ((1 << 64) - 1)
            for value in reg_value_hints.get(reg, [])
        }
        if not existing_values or existing_values == {0}:
            reg_value_hints.setdefault(reg, []).append(0)

    scalar_hint_regs = {
        reg
        for reg, values in reg_value_hints.items()
        if reg not in direct_memory_base_regs
        and len({value & ((1 << 64) - 1) for value in values}) == 1
    }
    if verbose and (load_value_hints or load_pointer_hints or reg_pointer_hints or reg_value_hints or load_nonzero_hints or reg_nonzero_hints):
        print('arithmetic_address_hints', {
            'load_value_hints': {hex(k): v for k, v in load_value_hints.items()},
            'load_pointer_hints': {hex(k): v for k, v in load_pointer_hints.items()},
            'reg_pointer_hints': {str(k): v for k, v in reg_pointer_hints.items()},
            'reg_value_hints': {str(k): v for k, v in reg_value_hints.items()},
            'load_nonzero_hints': [hex(k) for k in sorted(load_nonzero_hints)],
            'reg_nonzero_hints': [str(k) for k in sorted(reg_nonzero_hints, key=lambda r: r.id)],
        })

    load_entries_by_pc = {}
    for load_entry in load_accesses:
        load_inst = load_entry[0]
        load_entries_by_pc.setdefault(load_inst.pc, []).append(load_entry)

    def stable_expr_key(expr):
        return str(claripy.simplify(expr))

    def load_is_additive_offset_to_independent_base(load_entry):
        load_inst, rd_symbol, _, load_idx = load_entry
        if load_inst.width != 8:
            return False
        rd_vars = set(getattr(rd_symbol, 'variables', set()))
        if not rd_vars:
            return False

        address_uses = [
            addr_symbol
            for _, addr_symbol, access_idx, _ in mem_accesses
            if access_idx > load_idx
            and (getattr(addr_symbol, 'variables', set()) & rd_vars)
        ]
        if not address_uses:
            return False

        carrier_symbols = list(reg_to_symbol.values())
        carrier_symbols.extend(
            other_rd_symbol
            for other_inst, other_rd_symbol, _, other_idx in load_accesses
            if other_idx != load_idx and other_inst.width == 8
        )

        def has_independent_address_use(other_vars):
            return any(
                (getattr(other_addr_symbol, 'variables', set()) & other_vars)
                and not (getattr(other_addr_symbol, 'variables', set()) & rd_vars)
                for _, other_addr_symbol, _, _ in mem_accesses
            )

        for addr_symbol in address_uses:
            addr_vars = set(getattr(addr_symbol, 'variables', set()))
            covered_by_independent_base = False
            for other_symbol in carrier_symbols:
                other_vars = set(getattr(other_symbol, 'variables', set()))
                if not other_vars or (other_vars & rd_vars):
                    continue
                if not (addr_vars & other_vars):
                    continue
                try:
                    residual = claripy.simplify(addr_symbol - other_symbol)
                except Exception:
                    continue
                if set(getattr(residual, 'variables', set())) & other_vars:
                    continue
                if has_independent_address_use(other_vars):
                    covered_by_independent_base = True
                    break
            if not covered_by_independent_base:
                return False
        return True

    for pc in list(load_pointer_hints):
        entries = load_entries_by_pc.get(pc, [])
        if not entries:
            continue
        if not all(load_is_additive_offset_to_independent_base(entry) for entry in entries):
            continue
        del load_pointer_hints[pc]
        load_value_hints.setdefault(pc, []).append(0)

    pointer_source_value_keys = {
        (load_idx, stable_expr_key(rd_symbol))
        for _, rd_symbol, _, load_idx in pointer_source_loads
    }
    non_additive_loaded_addr_vars = set()
    for varset in non_additive_addr_value_varsets:
        non_additive_loaded_addr_vars.update(varset)
    for load_inst, rd_symbol, _, load_idx in address_source_loads:
        if load_inst.width != 8:
            continue
        if (load_idx, stable_expr_key(rd_symbol)) in pointer_source_value_keys:
            continue
        rd_vars = set(getattr(rd_symbol, 'variables', set()))
        if not rd_vars or not (rd_vars & non_additive_loaded_addr_vars):
            continue
        load_pointer_hints.pop(load_inst.pc, None)
        load_value_hints.setdefault(load_inst.pc, []).append(0)

    scalar_load_hint_keys = set()
    scalar_zero_address_load_keys = set()
    for pc, values in load_value_hints.items():
        unique_hint_values = {value & ((1 << 64) - 1) for value in values}
        if len(unique_hint_values) != 1:
            continue
        hinted_value = next(iter(unique_hint_values))
        for load_inst, rd_symbol, _, load_idx in load_entries_by_pc.get(pc, []):
            load_key = (load_idx, stable_expr_key(rd_symbol))
            scalar_load_hint_keys.add(load_key)
            rd_vars = getattr(rd_symbol, 'variables', set())
            used_in_later_addr = bool(rd_vars) and any(
                access_idx > load_idx and (getattr(addr_symbol, 'variables', set()) & rd_vars)
                for _, addr_symbol, access_idx, _ in mem_accesses
            )
            if hinted_value == 0 and load_inst.width < 8 and used_in_later_addr:
                scalar_zero_address_load_keys.add(load_key)

    for load_inst, rd_symbol, _, load_idx in address_source_loads:
        if load_inst.width >= 8 or load_inst.pc in load_nonzero_hints:
            continue
        scalar_zero_address_load_keys.add((load_idx, stable_expr_key(rd_symbol)))

    def materialize_init(candidate_solver, retry_index=0):
        _write_profile_stage(name, "init:materialize_init")
        candidate_solver = candidate_solver.branch()
        candidate_init = []
        reg_init = []
        reg_values = {}
        reg_runtime_recipes = {}
        reg_runtime_accesses = {}
        pending_reg_runtime_recipes = {}
        dynamic_mem_inits = []
        mem_values = {}
        mem_offset_addr_symbols = {}
        mem_offset_addr_entries = {}
        mem_slot_symbols = {}
        load_slot_layouts = {}
        addr_expr_offsets = {}
        expr_key_cache = {}
        expr_vars_cache = {}
        affine_key_cache = {}
        affine_base_offset_choices = {}
        affine_base_offset_records = []
        affine_base_min_offset_cache = {}
        cheap_same_address_cache = {}
        same_address_cache = {}
        forced_same_address_cache = {}
        prior_store_cache = {}
        forced_prior_store_cache = {}
        pointer_derived_availability_cache = {}
        pointer_derived_access_cache = {}
        added_constraint_cache = set()
        equiv_parent = {}
        equiv_base_offset_choices = {}
        hint_pointer_load_keys = set()
        register_anchor_min_offsets = {}
        residual_scalar_regs = set()
        loaded_pointer_base_candidate_cache = {}
        local_solver_timeout_ms = 100 if len(mem_accesses) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD else HEURISTIC_SOLVER_TIMEOUT_MS
        strict_retry_validation = (
            retry_index > 0
            and len(mem_entries) <= EAGER_POINTER_CONSTRAINT_LOAD_THRESHOLD
        )
        allow_initial_heuristics = (
            retry_index == 0
            or len(mem_entries) > EAGER_POINTER_CONSTRAINT_LOAD_THRESHOLD
        )
        if os.environ.get("RVMCA_DEBUG_LOAD_SLOTS") == "1":
            DEBUG(f"pointer_source_loads {[
                (load_idx, getattr(load_inst, 'code', str(load_inst)), str(load_addr_symbol), str(rd_symbol))
                for load_inst, rd_symbol, load_addr_symbol, load_idx in pointer_source_loads
            ]}")
            DEBUG(f"address_source_loads {[
                (load_idx, getattr(load_inst, 'code', str(load_inst)), str(load_addr_symbol), str(rd_symbol))
                for load_inst, rd_symbol, load_addr_symbol, load_idx in address_source_loads
            ]}")
        def expr_key(expr):
            cache_key = id(expr)
            if cache_key not in expr_key_cache:
                expr_key_cache[cache_key] = str(claripy.simplify(expr))
            return expr_key_cache[cache_key]

        def expr_vars(expr):
            key = id(expr)
            if key not in expr_vars_cache:
                expr_vars_cache[key] = getattr(expr, 'variables', set())
            return expr_vars_cache[key]

        def vars_belong_to_single_register(varset):
            varset = set(varset)
            if not varset:
                return False
            for reg_symbol in reg_to_symbol.values():
                reg_vars = expr_vars(reg_symbol)
                if varset <= reg_vars:
                    return True
            return False

        def is_long_block_address_scalar(load_inst, symbol, load_idx):
            if load_inst.width != 8:
                return False
            if (load_idx, stable_expr_key(symbol)) in pointer_source_value_keys:
                return False
            symbol_vars = expr_vars(symbol)
            if not symbol_vars or not (symbol_vars & non_additive_loaded_addr_vars):
                return False
            return (
                len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                and not (symbol_vars & pointer_loaded_addr_vars)
                and (load_idx, expr_key(symbol)) not in hint_pointer_load_keys
            )

        def is_deferred_loaded_address_scalar(load_inst, symbol, load_idx):
            if load_inst.width > 8:
                return False
            if load_inst.width == 8 and (load_idx, stable_expr_key(symbol)) in pointer_source_value_keys:
                return False
            if (load_idx, str(symbol)) in sp_affine_source_load_keys:
                return False
            symbol_vars = expr_vars(symbol)
            if not symbol_vars or not (symbol_vars & non_additive_loaded_addr_vars):
                return False
            scaled_ops = {'__lshift__', 'LShR', 'SShR', '__mul__', 'Mul', 'Concat'}

            def has_scaled_later_addr_use():
                for _, addr_symbol, access_idx, _ in mem_accesses:
                    if access_idx <= load_idx or not (expr_vars(addr_symbol) & symbol_vars):
                        continue
                    if any(
                        getattr(node, 'op', None) in scaled_ops
                        and (expr_vars(node) & symbol_vars)
                        for node in iter_ast_nodes(addr_symbol)
                    ):
                        return True
                return False

            if load_inst.width < 8:
                return has_scaled_later_addr_use()
            if is_long_block_address_scalar(load_inst, symbol, load_idx):
                return any(
                    access_idx > load_idx and (expr_vars(addr_symbol) & symbol_vars)
                    for _, addr_symbol, access_idx, _ in mem_accesses
                )
            if is_loaded_pointer_base_candidate(symbol, load_idx):
                return False
            return any(
                access_idx > load_idx and (expr_vars(addr_symbol) & symbol_vars)
                for _, addr_symbol, access_idx, _ in mem_accesses
            )

        def is_scalar_zero_address_load(load_inst, rd_symbol, load_idx):
            if narrow_load_feeds_pointer_load_address(load_inst, rd_symbol, load_idx):
                return False
            if is_deferred_loaded_address_scalar(load_inst, rd_symbol, load_idx):
                return False
            if is_scaled_loaded_address_source(load_inst, rd_symbol, load_idx):
                return False
            if (load_idx, expr_key(rd_symbol)) in scalar_zero_address_load_keys:
                return True
            if load_inst.width >= 8 or load_inst.pc in load_nonzero_hints:
                return False
            rd_vars = expr_vars(rd_symbol)
            return bool(rd_vars) and any(
                access_idx > load_idx and (expr_vars(addr_symbol) & rd_vars)
                for _, addr_symbol, access_idx, _ in mem_accesses
            )

        for pc, values in load_value_hints.items():
            unique_hint_values = {value & ((1 << 64) - 1) for value in values}
            if len(unique_hint_values) != 1:
                continue
            for load_inst, rd_symbol, _, load_idx in load_entries_by_pc.get(pc, []):
                pointer_loaded_addr_vars.difference_update(expr_vars(rd_symbol))
        for pc in load_pointer_hints:
            for load_inst, rd_symbol, _, _ in load_entries_by_pc.get(pc, []):
                if load_inst.width == 8:
                    pointer_loaded_addr_vars.update(expr_vars(rd_symbol))

        def equiv_find(var):
            parent = equiv_parent.get(var, var)
            if parent != var:
                parent = equiv_find(parent)
                equiv_parent[var] = parent
            return parent

        def equiv_union(var_a, var_b):
            root_a = equiv_find(var_a)
            root_b = equiv_find(var_b)
            if root_a == root_b:
                return
            if str(root_b) < str(root_a):
                root_a, root_b = root_b, root_a
            equiv_parent[root_b] = root_a
            old_key = f"equiv:{root_b}"
            new_key = f"equiv:{root_a}"
            old_offsets = equiv_base_offset_choices.pop(old_key, [])
            if old_offsets:
                merged_offsets = equiv_base_offset_choices.setdefault(new_key, [])
                for offset in old_offsets:
                    if offset not in merged_offsets:
                        merged_offsets.append(offset)
            cheap_same_address_cache.clear()

        def expr_equiv_roots(expr):
            return {equiv_find(var) for var in expr_vars(expr)}

        def expr_equiv_offset_key(expr):
            vars_ = expr_vars(expr)
            if len(vars_) != 1:
                return None
            return f"equiv:{equiv_find(next(iter(vars_)))}"

        def remember_equiv_base_offset(expr, offset):
            equiv_key = expr_equiv_offset_key(expr)
            if equiv_key is None:
                return
            offsets = equiv_base_offset_choices.setdefault(equiv_key, [])
            if offset not in offsets:
                offsets.append(offset)

        def exprs_may_be_related(expr_a, expr_b):
            vars_a = expr_vars(expr_a)
            vars_b = expr_vars(expr_b)
            if vars_a & vars_b:
                return True
            return bool({equiv_find(var) for var in vars_a} & {equiv_find(var) for var in vars_b})

        def register_expr_equality(expr_a, expr_b):
            vars_a = expr_vars(expr_a)
            vars_b = expr_vars(expr_b)
            if len(vars_a) == 1 and len(vars_b) == 1:
                equiv_union(next(iter(vars_a)), next(iter(vars_b)))

        def satisfiable_with(expr, val, timeout_ms=None):
            concrete_value = concrete_expr_value(expr)
            if concrete_value is not None:
                return concrete_value == (val & ((1 << 64) - 1))
            test_solver = candidate_solver.branch()
            test_solver.timeout = local_solver_timeout_ms if timeout_ms is None else timeout_ms
            try:
                test_solver.add(expr == val)
                return test_solver.satisfiable()
            except Exception:
                return False

        def solver_min(expr):
            try:
                test_solver = candidate_solver.branch()
                test_solver.timeout = local_solver_timeout_ms
                return test_solver.min(expr)
            except Exception:
                return None

        def solver_min_with(expr, extra_constraints):
            try:
                test_solver = candidate_solver.branch()
                test_solver.timeout = local_solver_timeout_ms
                return test_solver.min(expr, extra_constraints=extra_constraints)
            except Exception:
                return None

        def solver_eval_with(expr, extra_constraints, n=256):
            try:
                test_solver = candidate_solver.branch()
                test_solver.timeout = local_solver_timeout_ms
                return test_solver.eval(expr, n, extra_constraints=extra_constraints)
            except Exception:
                return []

        def solver_eval_limited(expr, n=1, timeout_ms=1000, extra_constraints=None):
            extra_constraints = [] if extra_constraints is None else extra_constraints
            try:
                test_solver = candidate_solver.branch()
                test_solver.timeout = min(timeout_ms, local_solver_timeout_ms)
                for constraint in extra_constraints:
                    test_solver.add(constraint)
                return test_solver.eval(expr, n)
            except Exception:
                return []

        def solver_eval_current(expr, n=8, timeout_ms=5000):
            try:
                test_solver = candidate_solver.branch()
                test_solver.timeout = timeout_ms
                return test_solver.eval(expr, n)
            except Exception:
                return []

        def concrete_expr_value(expr):
            if expr_vars(expr):
                return None
            try:
                value = expr.concrete_value
                if isinstance(value, int):
                    return value & ((1 << 64) - 1)
                nested_value = getattr(value, 'concrete_value', None)
                if isinstance(nested_value, int):
                    return nested_value & ((1 << 64) - 1)
                return int(value) & ((1 << 64) - 1)
            except Exception:
                pass
            try:
                values = solver_eval_limited(expr, n=1, timeout_ms=local_solver_timeout_ms)
                if values:
                    value = values[0]
                    if isinstance(value, int):
                        return value & ((1 << 64) - 1)
                    nested_value = getattr(value, 'concrete_value', None)
                    if isinstance(nested_value, int):
                        return nested_value & ((1 << 64) - 1)
                    return int(value) & ((1 << 64) - 1)
            except Exception:
                pass
            return None

        def sub_same_width(lhs, rhs):
            try:
                if lhs.size() != rhs.size():
                    return None
            except Exception:
                return None
            return claripy.simplify(lhs - rhs)

        def additive_residual_without_term(expr, term):
            expr = claripy.simplify(expr)
            term = claripy.simplify(term)
            try:
                bits = expr.size()
                if bits != term.size():
                    return None
            except Exception:
                return None

            term_key = expr_key(term)
            terms = []

            def collect(node, sign=1):
                node = claripy.simplify(node)
                op = getattr(node, 'op', '')
                args = [arg for arg in getattr(node, 'args', ()) if hasattr(arg, 'op')]
                if op in {'__add__', 'Add'}:
                    for arg in args:
                        collect(arg, sign)
                    return
                if op in {'__sub__', 'Sub'} and args:
                    collect(args[0], sign)
                    for arg in args[1:]:
                        collect(arg, -sign)
                    return
                terms.append((sign, node))

            collect(expr)
            removed = False
            residual = claripy.BVV(0, bits)
            for sign, node in terms:
                if not removed and sign > 0 and expr_key(node) == term_key:
                    removed = True
                    continue
                residual = residual + node if sign > 0 else residual - node
            if not removed:
                return None
            return claripy.simplify(residual)

        def affine_base_const(expr):
            expr = claripy.simplify(expr)
            try:
                bits = expr.size()
            except Exception:
                return None
            if bits != 64:
                return None

            terms = []
            const_total = 0
            mask = (1 << bits) - 1

            def collect(node, sign=1):
                nonlocal const_total
                node = claripy.simplify(node)
                if not expr_vars(node):
                    value = concrete_expr_value(node)
                    if value is None:
                        return False
                    const_total = (const_total + sign * _signed_u64(value)) & mask
                    return True
                op = getattr(node, 'op', '')
                args = [arg for arg in getattr(node, 'args', ()) if hasattr(arg, 'op')]
                if op in {'__add__', 'Add'}:
                    return all(collect(arg, sign) for arg in args)
                if op in {'__sub__', 'Sub'} and args:
                    if not collect(args[0], sign):
                        return False
                    return all(collect(arg, -sign) for arg in args[1:])
                terms.append((sign, node))
                return True

            if not collect(expr):
                return None

            base = claripy.BVV(0, bits)
            for sign, term in terms:
                base = base + term if sign > 0 else base - term
            base = claripy.simplify(base)
            return base, _signed_u64(const_total)

        def affine_key(expr):
            cache_key = id(expr)
            if cache_key not in affine_key_cache:
                result = affine_base_const(expr)
                if result is None:
                    affine_key_cache[cache_key] = None
                else:
                    base, imm = result
                    affine_key_cache[cache_key] = (expr_key(base), imm, base)
            return affine_key_cache[cache_key]

        def affine_same_or_distinct(addr_a, addr_b):
            affine_a = affine_key(addr_a)
            affine_b = affine_key(addr_b)
            if affine_a is None or affine_b is None:
                return None
            base_key_a, imm_a, _ = affine_a
            base_key_b, imm_b, _ = affine_b
            if base_key_a != base_key_b:
                return None
            return imm_a == imm_b

        def affine_accesses_disjoint(addr_a, width_a, addr_b, width_b):
            affine_a = affine_key(addr_a)
            affine_b = affine_key(addr_b)
            if affine_a is None or affine_b is None:
                return None
            base_key_a, imm_a, _ = affine_a
            base_key_b, imm_b, _ = affine_b
            if base_key_a != base_key_b:
                return None
            lo_a, hi_a = imm_a, imm_a + width_a - 1
            lo_b, hi_b = imm_b, imm_b + width_b - 1
            return hi_a < lo_b or hi_b < lo_a

        def concrete_offset_no_overlap_constraint(offset_expr, width, used_offset, used_width):
            used_lo = (used_offset - used_width + 1) & ((1 << 64) - 1)
            used_hi = used_offset & ((1 << 64) - 1)
            access_lo = offset_expr - (width - 1)
            return claripy.Or(
                claripy.ULT(offset_expr, claripy.BVV(used_lo, 64)),
                claripy.ULT(claripy.BVV(used_hi, 64), access_lo),
            )

        def value_selection_constraints(expr, positive=False, align=None, avoid=None, width=8):
            avoid = [] if avoid is None else avoid
            constraints = []
            if positive:
                constraints.append(claripy.UGT(expr, claripy.BVV(0, 64)))
                constraints.append(claripy.ULE(expr, claripy.BVV(STACK_RANGE, 64)))
            if align:
                constraints.append((expr & (align - 1)) == 0)
            for used, used_width in avoid:
                constraints.append(concrete_offset_no_overlap_constraint(expr, width, used, used_width))
            return constraints

        def concrete_value_from_materialized(expr):
            if not expr_vars(expr):
                return concrete_expr_value(expr)
            substitutions = {}
            for reg, value in reg_values.items():
                symbol = reg_to_symbol.get(reg)
                if symbol is None:
                    continue
                substitutions[expr_key(symbol)] = claripy.BVV(
                    value & ((1 << symbol.size()) - 1),
                    symbol.size(),
                )
            substitutions[expr_key(init_sp)] = claripy.BVV(
                CONCRETE_REPLAY_SP & ((1 << init_sp.size()) - 1),
                init_sp.size(),
            )

            cache = {}

            def substitute(node):
                if not hasattr(node, 'op'):
                    return node
                node_key = expr_key(node)
                if node_key in substitutions:
                    return substitutions[node_key]
                cache_key = id(node)
                if cache_key in cache:
                    return cache[cache_key]
                changed = False
                new_args = []
                for arg in getattr(node, 'args', ()):
                    new_arg = substitute(arg)
                    if new_arg is not arg:
                        changed = True
                    new_args.append(new_arg)
                if changed:
                    result = node.make_like(node.op, tuple(new_args))
                    result = claripy.simplify(result)
                else:
                    result = node
                cache[cache_key] = result
                return result

            substituted = substitute(expr)
            if expr_vars(substituted):
                return None
            return concrete_expr_value(claripy.simplify(substituted))

        def concrete_value_from_materialized_with(expr, replacements):
            if not expr_vars(expr):
                return concrete_expr_value(expr)
            substitutions = {}
            for reg, value in reg_values.items():
                symbol = reg_to_symbol.get(reg)
                if symbol is None:
                    continue
                substitutions[expr_key(symbol)] = claripy.BVV(
                    value & ((1 << symbol.size()) - 1),
                    symbol.size(),
                )
            substitutions[expr_key(init_sp)] = claripy.BVV(
                CONCRETE_REPLAY_SP & ((1 << init_sp.size()) - 1),
                init_sp.size(),
            )
            for replacement_expr, replacement_value in replacements:
                try:
                    bits = replacement_expr.size()
                except Exception:
                    bits = 64
                substitutions[expr_key(replacement_expr)] = claripy.BVV(
                    replacement_value & ((1 << bits) - 1),
                    bits,
                )

            cache = {}

            def substitute(node):
                if not hasattr(node, 'op'):
                    return node
                node_key = expr_key(node)
                if node_key in substitutions:
                    return substitutions[node_key]
                cache_key = id(node)
                if cache_key in cache:
                    return cache[cache_key]
                changed = False
                new_args = []
                for arg in getattr(node, 'args', ()):
                    new_arg = substitute(arg)
                    if new_arg is not arg:
                        changed = True
                    new_args.append(new_arg)
                if changed:
                    result = node.make_like(node.op, tuple(new_args))
                    result = claripy.simplify(result)
                else:
                    result = node
                cache[cache_key] = result
                return result

            try:
                substituted = substitute(expr)
                if expr_vars(substituted):
                    return None
                return concrete_expr_value(claripy.simplify(substituted))
            except claripy.errors.ClaripyZeroDivisionError:
                return None

        def choose_value(
            expr,
            preferred=None,
            positive=False,
            align=None,
            avoid=None,
            width=8,
            required=True,
            fast_positive=False,
            candidate_ok=None,
        ):
            avoid = [] if avoid is None else avoid
            step = align if align else 1
            complex_memory_block = len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
            value_solver_timeout_ms = 100 if complex_memory_block else 5000
            value_related_timeout_ms = 500 if complex_memory_block else 5000

            def concrete_value_ok(val):
                if candidate_ok is not None and not candidate_ok(val):
                    return False
                if positive and val <= 0:
                    return False
                if align and val % align != 0:
                    return False
                if positive and val > STACK_RANGE:
                    return False
                if any(concrete_ranges_overlap(val, width, used, used_width) for used, used_width in avoid):
                    return False
                return True

            def add_value_if_sat(val):
                if not concrete_value_ok(val):
                    return None
                if satisfiable_with(expr, val):
                    candidate_solver.add(expr == val)
                    return val
                return None

            seen = set()
            def try_candidate(val):
                if val is None or val in seen:
                    return None
                seen.add(val)
                return add_value_if_sat(val)

            if fast_positive and positive:
                for val in solver_eval_with(expr, [], n=8):
                    val &= ((1 << 64) - 1)
                    result = try_candidate(val)
                    if result is not None:
                        return result

            for val in [preferred]:
                result = try_candidate(val)
                if result is not None:
                    return result

            materialized_val = concrete_value_from_materialized(expr)
            if materialized_val is not None and concrete_value_ok(materialized_val):
                materialized_constraint = expr == expr_bvv(materialized_val, expr)
                if (
                    try_add_constraint_set_fast(
                        [materialized_constraint],
                        timeout_ms=value_solver_timeout_ms,
                    )
                    or try_add_constraint_set_related(
                        [materialized_constraint],
                        expr_vars(expr),
                        timeout_ms=value_related_timeout_ms,
                    )
                ):
                    return materialized_val
                materialized_vars = set(expr_vars(init_sp))
                for reg in reg_values:
                    reg_symbol = reg_to_symbol.get(reg)
                    if reg_symbol is not None:
                        materialized_vars.update(expr_vars(reg_symbol))
                if expr_vars(expr) <= materialized_vars:
                    candidate_solver.add(materialized_constraint)
                    added_constraint_cache.add(str(claripy.simplify(materialized_constraint)))
                    return materialized_val
            result = try_candidate(materialized_val)
            if result is not None:
                return result

            if not positive:
                result = try_candidate(0)
                if result is not None:
                    return result

            def try_stack_base_offset_candidate():
                if not positive:
                    return None
                try:
                    reg_offsets = list(reg_min_stack_offsets.items())
                except NameError:
                    return None
                expr_variables = expr_vars(expr)
                attempts = 0
                max_attempts = 2 if complex_memory_block else None
                for reg, min_base_offset in reg_offsets:
                    symbol = reg_to_symbol.get(reg)
                    if symbol is None:
                        continue
                    symbol_vars = expr_vars(symbol)
                    if not symbol_vars or not (expr_variables & symbol_vars):
                        continue
                    residual = claripy.simplify((init_sp - expr) - symbol)
                    if expr_vars(residual) & symbol_vars:
                        continue
                    residual_value = concrete_expr_value(residual)
                    if residual_value is None:
                        continue
                    imm = _signed_u64(residual_value)
                    base_start = max(INIT_PTR_MIN_OFFSET, min_base_offset)
                    if imm >= 0:
                        base_start = max(base_start, imm + width)
                    base_stop = min(STACK_RANGE, base_start + 256)
                    for base_offset in range(base_start, base_stop + 1):
                        if max_attempts is not None and attempts >= max_attempts:
                            return None
                        access_offset = base_offset - imm
                        if access_offset <= 0 or access_offset > STACK_RANGE:
                            continue
                        if align and access_offset % align != 0:
                            continue
                        if any(concrete_ranges_overlap(access_offset, width, used, used_width) for used, used_width in avoid):
                            continue
                        attempts += 1
                        constraints = [
                            (init_sp - symbol) == base_offset,
                            expr == access_offset,
                        ]
                        if not try_add_constraint_set_fast(
                            constraints,
                            timeout_ms=100 if complex_memory_block else HEURISTIC_SOLVER_TIMEOUT_MS,
                        ):
                            continue
                        return access_offset
                return None

            result = try_stack_base_offset_candidate()
            if result is not None:
                return result

            def try_any_sp_relative_register_candidate():
                if not positive:
                    return None
                expr_variables = expr_vars(expr)
                if not expr_variables:
                    return None
                attempts = 0
                max_attempts = 2 if complex_memory_block else None
                for reg, symbol in reg_to_symbol.items():
                    symbol_vars = expr_vars(symbol)
                    if not symbol_vars or not (expr_variables & symbol_vars):
                        continue
                    residual = claripy.simplify((init_sp - expr) - symbol)
                    if expr_vars(residual) & symbol_vars:
                        continue
                    residual_value = concrete_expr_value(residual)
                    if residual_value is None:
                        continue
                    imm = _signed_u64(residual_value)
                    base_start = INIT_PTR_MIN_OFFSET
                    if imm >= 0:
                        base_start = max(base_start, imm + width)
                    base_start = _align_up(base_start, INIT_ACCESS_ALIGN)
                    starts = []
                    if preferred is not None:
                        starts.append(preferred)
                    starts.append(_align_up(1, align) if align else 1)
                    starts.extend(used + max(width, used_width) for used, used_width in avoid)
                    seen_offsets = set()
                    for start in starts:
                        start = max(1, start)
                        if align:
                            start = _align_up(start, align)
                        for access_offset in range(start, min(STACK_RANGE, start + 256) + 1, step):
                            if max_attempts is not None and attempts >= max_attempts:
                                return None
                            if access_offset in seen_offsets:
                                continue
                            seen_offsets.add(access_offset)
                            if not concrete_value_ok(access_offset):
                                continue
                            base_offset = access_offset + imm
                            if base_offset <= 0 or base_offset > STACK_RANGE:
                                continue
                            if base_offset < base_start:
                                continue
                            constraints = [
                                (init_sp - symbol) == base_offset,
                                expr == access_offset,
                            ]
                            attempts += 1
                            if try_add_constraint_set_fast(constraints):
                                return access_offset
                return None

            result = try_any_sp_relative_register_candidate()
            if result is not None:
                return result

            def try_scaled_index_offset_candidate():
                if not positive:
                    return None
                if (
                    getattr(expr, 'op', None) in {'__sub__', 'Sub'}
                    and len(getattr(expr, 'args', ())) == 2
                    and expr_key(expr.args[0]) == expr_key(init_sp)
                ):
                    addr_expr = claripy.simplify(expr.args[1])
                else:
                    addr_expr = claripy.simplify(init_sp - expr)
                addr_vars = expr_vars(addr_expr)
                if not addr_vars:
                    return None
                mask = (1 << 64) - 1

                def parse_scaled(node, symbol, symbol_key, symbol_vars):
                    node = claripy.simplify(node)
                    if expr_key(node) == symbol_key:
                        return 1, 0, []
                    node_vars = expr_vars(node)
                    if not node_vars:
                        value = concrete_expr_value(node)
                        if value is None:
                            return None
                        return 0, value & mask, []
                    if not (node_vars & symbol_vars):
                        try:
                            zero = claripy.BVV(0, node.size())
                        except Exception:
                            zero = claripy.BVV(0, 64)
                        return 0, 0, [node == zero]
                    op = getattr(node, 'op', None)
                    raw_args = getattr(node, 'args', ())
                    args = [arg for arg in raw_args if hasattr(arg, 'op')]
                    if op in {'__add__', 'Add'}:
                        scale, const, constraints = 0, 0, []
                        for arg in args:
                            parsed = parse_scaled(arg, symbol, symbol_key, symbol_vars)
                            if parsed is None:
                                return None
                            arg_scale, arg_const, arg_constraints = parsed
                            scale += arg_scale
                            const = (const + arg_const) & mask
                            constraints.extend(arg_constraints)
                        return scale, const, constraints
                    if op in {'__sub__', 'Sub'} and args:
                        lhs = parse_scaled(args[0], symbol, symbol_key, symbol_vars)
                        if lhs is None:
                            return None
                        scale, const, constraints = lhs
                        for arg in args[1:]:
                            rhs = parse_scaled(arg, symbol, symbol_key, symbol_vars)
                            if rhs is None:
                                return None
                            rhs_scale, rhs_const, rhs_constraints = rhs
                            scale -= rhs_scale
                            const = (const - rhs_const) & mask
                            constraints.extend(rhs_constraints)
                        return scale, const, constraints
                    if op == '__lshift__' and len(raw_args) == 2:
                        parsed = parse_scaled(raw_args[0], symbol, symbol_key, symbol_vars)
                        shift_arg = raw_args[1]
                        shift_value = (
                            shift_arg
                            if isinstance(shift_arg, int)
                            else concrete_expr_value(shift_arg)
                        )
                        if parsed is None or shift_value is None:
                            return None
                        scale, const, constraints = parsed
                        return scale << shift_value, (const << shift_value) & mask, constraints
                    if op in {'ZeroExt', 'SignExt'} and args:
                        return parse_scaled(args[-1], symbol, symbol_key, symbol_vars)
                    if op == 'Extract' and len(raw_args) == 3:
                        _, low, child = raw_args
                        if low == 0 and expr_key(child) == symbol_key:
                            return 1, 0, []
                        return None
                    if op == 'Concat' and raw_args:
                        low_width = 0
                        for low_arg in raw_args[1:]:
                            if not hasattr(low_arg, 'op'):
                                return None
                            low_value = concrete_expr_value(low_arg)
                            if low_value != 0:
                                return None
                            low_width += low_arg.size()
                        parsed = parse_scaled(raw_args[0], symbol, symbol_key, symbol_vars)
                        if parsed is None:
                            return None
                        scale, const, constraints = parsed
                        return scale << low_width, (const << low_width) & mask, constraints
                    return None

                starts = []
                if preferred is not None:
                    starts.append(preferred)
                low = _align_up(1, align) if align else 1
                starts.append(low)
                starts.extend(used + max(width, used_width) for used, used_width in avoid)
                step_local = align if align else 1

                for reg, symbol in reg_to_symbol.items():
                    symbol_vars = expr_vars(symbol)
                    if not symbol_vars or not (addr_vars & symbol_vars):
                        continue
                    parsed = parse_scaled(addr_expr, symbol, expr_key(symbol), symbol_vars)
                    if parsed is None:
                        continue
                    scale, const, scaled_constraints = parsed
                    if scale <= 1 or scale & (scale - 1):
                        continue
                    group_requirements = []
                    for _, other_addr_symbol, _, other_width in mem_accesses:
                        if not (expr_vars(other_addr_symbol) & symbol_vars):
                            continue
                        other_parsed = parse_scaled(
                            other_addr_symbol,
                            symbol,
                            expr_key(symbol),
                            symbol_vars,
                        )
                        if other_parsed is None:
                            continue
                        other_scale, other_const, other_constraints = other_parsed
                        if other_scale != scale or other_constraints:
                            continue
                        delta = _signed_u64((const - other_const) & mask)
                        group_requirements.append((delta, other_width))

                    def scaled_group_access_ok(access_offset):
                        for delta, other_width in group_requirements:
                            other_offset = access_offset + delta
                            if other_offset <= 0 or other_offset > STACK_RANGE:
                                return False
                            if other_width > 1 and other_offset % other_width != 0:
                                return False
                        return True

                    seen_offsets = set()
                    attempts = 0
                    attempt_limit = (
                        128
                        if use_static_memory_collection
                        else (4 if complex_memory_block else 32)
                    )
                    group_low = low
                    for delta, other_width in group_requirements:
                        group_low = max(group_low, other_width - delta)
                    group_starts = list(starts)
                    if group_low > low:
                        group_starts.insert(0, group_low)
                    for start in group_starts:
                        start = _align_up(max(low, start), step_local)
                        for access_offset in range(start, min(STACK_RANGE, start + 512) + 1, step_local):
                            if access_offset in seen_offsets:
                                continue
                            seen_offsets.add(access_offset)
                            if attempts >= attempt_limit:
                                break
                            if not concrete_value_ok(access_offset):
                                continue
                            if not scaled_group_access_ok(access_offset):
                                continue
                            target_addr = concrete_stack_addr(access_offset)
                            raw_value = (target_addr - const) & mask
                            if raw_value % scale:
                                continue
                            reg_value = (raw_value // scale) & mask
                            attempts += 1
                            constraints = list(scaled_constraints) + [
                                symbol == reg_value,
                                expr == access_offset,
                            ]
                            if (
                                try_add_constraint_set_fast(
                                    constraints,
                                    timeout_ms=100 if complex_memory_block else HEURISTIC_SOLVER_TIMEOUT_MS,
                                )
                                or try_add_constraint_set_related(
                                    constraints,
                                    expr_vars(expr) | symbol_vars,
                                    timeout_ms=1000 if use_static_memory_collection else HEURISTIC_SOLVER_TIMEOUT_MS,
                                )
                            ):
                                return access_offset
                return None

            result = try_scaled_index_offset_candidate()
            if result is not None:
                return result

            def try_pointer_load_base_offset_candidate():
                if not positive:
                    return None
                expr_variables = expr_vars(expr)
                attempts = 0
                max_attempts = 2 if complex_memory_block else None
                for _, rd_symbol, _, load_idx in pointer_source_loads:
                    rd_vars = expr_vars(rd_symbol)
                    if not rd_vars or not (expr_variables & rd_vars):
                        continue
                    residual = claripy.simplify((init_sp - expr) - rd_symbol)
                    if expr_vars(residual) & rd_vars:
                        continue
                    residual_value = concrete_expr_value(residual)
                    if residual_value is None:
                        continue
                    imm = _signed_u64(residual_value)
                    base_start = min_pointer_offset_for_vars(rd_vars, load_idx)
                    if imm >= 0:
                        base_start = max(base_start, imm + width)
                    access_starts = []
                    if preferred is not None:
                        access_starts.append(preferred)
                    low = _align_up(1, align) if align else 1
                    access_starts.append(low)
                    access_starts.extend(used + max(width, used_width) for used, used_width in avoid)
                    seen_offsets = set()
                    for start in access_starts:
                        start = max(start, low)
                        if align:
                            start = _align_up(start, align)
                        for access_offset in range(start, min(STACK_RANGE, start + 256) + 1, step):
                            if max_attempts is not None and attempts >= max_attempts:
                                return None
                            if access_offset in seen_offsets:
                                continue
                            seen_offsets.add(access_offset)
                            if not concrete_value_ok(access_offset):
                                continue
                            pointer_offset = access_offset + imm
                            if pointer_offset <= 0 or pointer_offset > STACK_RANGE:
                                continue
                            if pointer_offset < base_start:
                                continue
                            attempts += 1
                            constraints = [
                                (init_sp - rd_symbol) == pointer_offset,
                                expr == access_offset,
                            ]
                            if not try_add_constraint_set_fast(
                                constraints,
                                timeout_ms=100 if complex_memory_block else HEURISTIC_SOLVER_TIMEOUT_MS,
                            ):
                                continue
                            return access_offset
                return None

            result = try_pointer_load_base_offset_candidate()
            if result is not None:
                return result

            def try_stack_carrier_offset_candidate():
                addr_symbol = None
                expr_signature = expr_key(expr)
                for _, candidate_addr_symbol, _, _ in mem_accesses:
                    projected_expr = claripy.simplify(init_sp - candidate_addr_symbol)
                    if expr_key(projected_expr) == expr_signature:
                        addr_symbol = claripy.simplify(candidate_addr_symbol)
                        break
                if (
                    addr_symbol is None
                    and
                    getattr(expr, 'op', None) in {'__sub__', 'Sub'}
                    and len(getattr(expr, 'args', ())) == 2
                    and expr_key(expr.args[0]) == expr_key(init_sp)
                ):
                    addr_symbol = claripy.simplify(expr.args[1])
                if addr_symbol is None:
                    addr_symbol = claripy.simplify(init_sp - expr)
                if expr_vars(addr_symbol) & expr_vars(init_sp):
                    return None
                addr_vars = expr_vars(addr_symbol)
                if not addr_vars:
                    return None

                carrier_candidates = []
                seen_carriers = set()

                def add_carrier(symbol, producer_idx, preferred_base):
                    symbol_vars = expr_vars(symbol)
                    if not symbol_vars or not (addr_vars & symbol_vars):
                        return
                    key = expr_key(symbol)
                    if key in seen_carriers:
                        return
                    seen_carriers.add(key)
                    materialized_reg_vars = set()
                    for materialized_reg in reg_values:
                        materialized_symbol = reg_to_symbol.get(materialized_reg)
                        if materialized_symbol is not None:
                            materialized_reg_vars.update(expr_vars(materialized_symbol))
                    deferred_reg_vars = set()
                    for deferred_reg in deferred_regs:
                        deferred_symbol = reg_to_symbol.get(deferred_reg)
                        if deferred_symbol is not None:
                            deferred_reg_vars.update(expr_vars(deferred_symbol))

                    residual = claripy.simplify(addr_symbol - symbol)
                    residual_vars = expr_vars(residual)
                    if not (residual_vars & symbol_vars):
                        residual_affine = affine_base_const(residual)
                        if residual_affine is not None:
                            _, residual_imm = residual_affine
                            if residual_imm:
                                residual_offset_constraints = constraints_to_constant(
                                    residual,
                                    residual_imm,
                                    forbidden_vars=symbol_vars,
                                )
                                if residual_offset_constraints is not None:
                                    carrier_candidates.append((
                                        preferred_base + 2,
                                        count_mul_ancestors(addr_symbol, symbol),
                                        len(addr_vars - symbol_vars),
                                        producer_idx,
                                        symbol,
                                        symbol_vars,
                                        residual_offset_constraints,
                                        residual_imm,
                                    ))

                        def non_reg_mul_zero_constraints(node):
                            for ast_node in iter_ast_nodes(node):
                                if getattr(ast_node, 'op', None) not in {'__mul__', 'Mul'}:
                                    continue
                                for arg in getattr(ast_node, 'args', ()):
                                    if not hasattr(arg, 'op'):
                                        continue
                                    arg_vars = expr_vars(arg)
                                    if not arg_vars:
                                        continue
                                    if arg_vars & (symbol_vars | materialized_reg_vars):
                                        continue
                                    if arg_vars & deferred_reg_vars:
                                        preferred_forbidden = symbol_vars | materialized_reg_vars
                                    else:
                                        preferred_forbidden = symbol_vars | materialized_reg_vars | deferred_reg_vars
                                    sub_constraints = constraints_to_constant(
                                        arg,
                                        0,
                                        forbidden_vars=preferred_forbidden,
                                    )
                                    if sub_constraints is not None:
                                        return sub_constraints
                                    return [arg == expr_bvv(0, arg)]
                            return None

                        load_mul_constraints = non_reg_mul_zero_constraints(residual)
                        if load_mul_constraints is not None:
                            carrier_candidates.append((
                                preferred_base + 3,
                                count_mul_ancestors(addr_symbol, symbol),
                                len(addr_vars - symbol_vars),
                                producer_idx,
                                symbol,
                                symbol_vars,
                                load_mul_constraints,
                                0,
                            ))

                        load_preferred_constraints = constraints_to_constant(
                            residual,
                            0,
                            forbidden_vars=symbol_vars | materialized_reg_vars,
                        )
                        if load_preferred_constraints is not None:
                            carrier_candidates.append((
                                preferred_base + 2,
                                count_mul_ancestors(addr_symbol, symbol),
                                len(addr_vars - symbol_vars),
                                producer_idx,
                                symbol,
                                symbol_vars,
                                load_preferred_constraints,
                                0,
                            ))

                        frozen_constraints = constraints_to_constant(
                            residual,
                            0,
                            forbidden_vars=symbol_vars | materialized_reg_vars,
                        )
                        if frozen_constraints is not None:
                            carrier_candidates.append((
                                preferred_base + 1,
                                count_mul_ancestors(addr_symbol, symbol),
                                len(addr_vars - symbol_vars),
                                producer_idx,
                                symbol,
                                symbol_vars,
                                frozen_constraints,
                                0,
                            ))

                    constraints = constraints_to_carrier(addr_symbol, symbol)
                    if constraints is None:
                        if residual_vars & symbol_vars:
                            return
                        constraints = constraints_to_constant(
                            residual,
                            0,
                            forbidden_vars=symbol_vars,
                        )
                        if constraints is None:
                            return
                    carrier_candidates.append((
                        preferred_base,
                        count_mul_ancestors(addr_symbol, symbol),
                        len(addr_vars - symbol_vars),
                        producer_idx,
                        symbol,
                        symbol_vars,
                        constraints,
                        0,
                    ))

                for load_inst, rd_symbol, _, load_idx in load_accesses:
                    if load_inst.width != 8:
                        continue
                    add_carrier(rd_symbol, load_idx, 1 if load_inst.pc in mem_base_pcs else 0)
                for reg, symbol in reg_to_symbol.items():
                    add_carrier(symbol, -1, 1 if reg in undef_base_regs else 0)

                if not carrier_candidates:
                    return None
                carrier_candidates.sort(
                    key=lambda item: (item[0], item[1], -item[2], item[3]),
                    reverse=True,
                )

                low = _align_up(1, align) if align else 1
                starts = []
                starts.append(low)
                if preferred is not None:
                    starts.append(preferred)
                starts.extend(used + max(width, used_width) for used, used_width in avoid)
                step_local = align if align else 1
                max_carriers = 4 if complex_memory_block else 16
                max_offsets_per_carrier = 4 if complex_memory_block else 32

                for _, _, _, producer_idx, symbol, symbol_vars, constraints, residual_offset in carrier_candidates[:max_carriers]:
                    min_offset = (
                        min_pointer_offset_for_vars(symbol_vars, producer_idx)
                        if producer_idx >= 0
                        else INIT_PTR_MIN_OFFSET
                    )
                    seen_offsets = set()
                    attempts = 0
                    for start in starts:
                        start = _align_up(max(low, start, min_offset), step_local)
                        for access_offset in range(start, min(STACK_RANGE, start + 512) + 1, step_local):
                            if attempts >= max_offsets_per_carrier:
                                break
                            if access_offset in seen_offsets:
                                continue
                            seen_offsets.add(access_offset)
                            if access_offset <= 0 or access_offset > STACK_RANGE:
                                continue
                            if align and access_offset % align != 0:
                                continue
                            if any(
                                concrete_ranges_overlap(access_offset, width, used_offset, used_width)
                                for used_offset, used_width in avoid
                            ):
                                continue
                            carrier_offset = access_offset + residual_offset
                            if carrier_offset < min_offset:
                                continue
                            if carrier_offset <= 0 or carrier_offset > STACK_RANGE:
                                continue
                            attempts += 1
                            constraint_set = list(constraints) + [
                                (init_sp - symbol) == carrier_offset,
                                expr == access_offset,
                            ]
                            if (
                                try_add_constraint_set_fast(
                                    constraint_set,
                                    timeout_ms=value_solver_timeout_ms,
                                )
                                or try_add_constraint_set_related(
                                    constraint_set,
                                    expr_vars(expr) | symbol_vars,
                                    timeout_ms=value_related_timeout_ms,
                                )
                            ):
                                return access_offset
                    if attempts == 0 and preferred is not None:
                        carrier_offset = preferred + residual_offset
                        if carrier_offset <= 0 or carrier_offset > STACK_RANGE:
                            continue
                        constraint_set = list(constraints) + [
                            (init_sp - symbol) == carrier_offset,
                            expr == preferred,
                        ]
                        if (
                            try_add_constraint_set_fast(
                                constraint_set,
                                timeout_ms=value_solver_timeout_ms,
                            )
                            or try_add_constraint_set_related(
                                constraint_set,
                                expr_vars(expr) | symbol_vars,
                                timeout_ms=value_related_timeout_ms,
                            )
                        ):
                            return preferred
                return None

            result = try_stack_carrier_offset_candidate()
            if result is not None:
                return result

            def positive_candidates(limit):
                if not positive:
                    return
                low = _align_up(1, align) if align else 1
                high = STACK_RANGE
                starts = []
                if preferred is not None:
                    starts.append(preferred)
                starts.append(low)
                for used, used_width in sorted(avoid):
                    starts.append(used + max(width, used_width))
                    starts.append(used + width)
                yielded = 0
                for start in starts:
                    start = max(start, low)
                    if align:
                        start = _align_up(start, align)
                    if start > high:
                        continue
                    for val in range(start, high + 1, step):
                        yield val
                        yielded += 1
                        if limit is not None and yielded >= limit:
                            return

            if positive:
                fast_limit = (4 if complex_memory_block else 24) if fast_positive else 256
                for val in positive_candidates(limit=fast_limit):
                    result = try_candidate(val)
                    if result is not None:
                        return result
                if fast_positive and not required:
                    return None
                if not required:
                    return None

            minimum = solver_min(expr)
            for val in [minimum]:
                result = try_candidate(val)
                if result is not None:
                    return result

            extra_constraints = value_selection_constraints(
                expr,
                positive=positive,
                align=align,
                avoid=avoid,
                width=width,
            )
            for val in [solver_min_with(expr, extra_constraints)]:
                result = try_candidate(val)
                if result is not None:
                    return result
            for val in solver_eval_with(expr, extra_constraints, n=512):
                result = try_candidate(val)
                if result is not None:
                    return result

            if preferred is not None and minimum is not None and preferred <= STACK_RANGE:
                start = preferred
            else:
                start = minimum
            if start is not None:
                if positive:
                    start = max(start, 1)
                if align:
                    start = _align_up(start, align)
                for i in range(64):
                    result = try_candidate(start + i * step)
                    if result is not None:
                        return result

            if not required:
                return None

            if positive:
                exhaustive_limit = 32 if fast_positive else None
                for val in positive_candidates(limit=exhaustive_limit):
                    result = try_candidate(val)
                    if result is not None:
                        return result

            final_constraints = value_selection_constraints(
                expr,
                positive=positive,
                align=align,
                avoid=avoid,
                width=width,
            )
            val = solver_min_with(expr, final_constraints)
            if val is not None:
                result = try_candidate(val)
                if result is not None:
                    return result

            val = solver_min_with(
                expr,
                value_selection_constraints(expr, positive=positive, align=align, width=width),
            )
            if val is not None:
                result = try_candidate(val)
                if result is not None:
                    return result

            if positive and avoid:
                low = _align_up(1, align) if align else 1
                attempts = 0
                val = low
                while val <= STACK_RANGE and attempts < 128:
                    if (not align or val % align == 0) and satisfiable_with(expr, val):
                        candidate_solver.add(expr == val)
                        return val
                    attempts += 1
                    val += step

            fallback_constraints = value_selection_constraints(
                expr,
                positive=positive,
                align=align,
                avoid=avoid,
                width=width,
            )
            for val in solver_eval_limited(expr, n=16, timeout_ms=5000, extra_constraints=fallback_constraints):
                val &= ((1 << 64) - 1)
                result = try_candidate(val)
                if result is not None:
                    return result

            val = minimum
            if val is None:
                raise AssertionError(f"cannot choose concrete value for {expr}")
            if not concrete_value_ok(val):
                raise AssertionError(f"cannot choose non-overlapping concrete value for {expr}")
            result = try_candidate(val)
            if result is not None:
                return result
            raise AssertionError(f"cannot choose satisfiable concrete value for {expr}")

        debug_constraint_var = os.environ.get("RVMCA_DEBUG_CONSTRAINT_VAR")

        def debug_constraint_add(source, constraint):
            if not debug_constraint_var:
                return
            constraint_str = str(claripy.simplify(constraint))
            if debug_constraint_var in constraint_str:
                try:
                    import inspect
                    callers = [frame.function for frame in inspect.stack()[2:7]]
                except Exception:
                    callers = []
                DEBUG(f"constraint_add_{source} callers={callers} {constraint_str[:1200]}")

        def try_add_constraint(constraint, timeout_ms=HEURISTIC_SOLVER_TIMEOUT_MS):
            constraint_key = str(claripy.simplify(constraint))
            if constraint_key in added_constraint_cache:
                return True
            test_solver = candidate_solver.branch()
            test_solver.timeout = timeout_ms
            try:
                test_solver.add(constraint)
                if test_solver.satisfiable():
                    candidate_solver.add(constraint)
                    added_constraint_cache.add(constraint_key)
                    debug_constraint_add("try_add", constraint)
                    return True
            except Exception:
                return False
            return False

        def constraint_satisfiability_with_current(constraint, timeout_ms=HEURISTIC_SOLVER_TIMEOUT_MS):
            constraint_key = str(claripy.simplify(constraint))
            if constraint_key in added_constraint_cache:
                return True
            test_solver = candidate_solver.branch()
            test_solver.timeout = timeout_ms
            try:
                test_solver.add(constraint)
                return bool(test_solver.satisfiable())
            except Exception:
                return None

        def try_add_constraint_set_fast(constraints, timeout_ms=100):
            unique_constraints = []
            seen_constraint_keys = set()
            for constraint in constraints:
                constraint_key = str(claripy.simplify(constraint))
                if constraint_key in seen_constraint_keys or constraint_key in added_constraint_cache:
                    continue
                seen_constraint_keys.add(constraint_key)
                unique_constraints.append((constraint_key, constraint))
            if not unique_constraints:
                return True
            test_solver = candidate_solver.branch()
            test_solver.timeout = timeout_ms
            try:
                for _, constraint in unique_constraints:
                    test_solver.add(constraint)
                if not test_solver.satisfiable():
                    return False
            except Exception:
                return False
            for constraint_key, constraint in unique_constraints:
                candidate_solver.add(constraint)
                added_constraint_cache.add(constraint_key)
                debug_constraint_add("set_fast", constraint)
            return True

        def try_add_constraint_set_related(constraints, seed_vars, timeout_ms=1000):
            constraints = list(constraints)
            anchor_vars = expr_vars(init_sp)
            closure = set(seed_vars) - anchor_vars
            for constraint in constraints:
                closure.update(getattr(constraint, 'variables', set()) - anchor_vars)
            if not closure:
                return try_add_constraint_set_fast(constraints, timeout_ms=timeout_ms)

            selected = []
            selected_ids = set()
            changed = True
            while changed:
                changed = False
                for constraint in candidate_solver.constraints:
                    constraint_id = id(constraint)
                    if constraint_id in selected_ids:
                        continue
                    constraint_vars = getattr(constraint, 'variables', set()) - anchor_vars
                    if not (constraint_vars & closure):
                        continue
                    selected_ids.add(constraint_id)
                    selected.append(constraint)
                    new_vars = constraint_vars - closure
                    if new_vars:
                        closure.update(new_vars)
                        changed = True

            test_solver = claripy.Solver()
            test_solver.timeout = timeout_ms
            try:
                for constraint in selected:
                    test_solver.add(constraint)
                for constraint in constraints:
                    test_solver.add(constraint)
                if not test_solver.satisfiable():
                    return False
            except Exception:
                return False

            if len(mem_entries) < GLOBAL_NO_OVERLAP_LOAD_THRESHOLD:
                full_solver = candidate_solver.branch()
                full_solver.timeout = timeout_ms
                try:
                    for constraint in constraints:
                        full_solver.add(constraint)
                    if not full_solver.satisfiable():
                        return False
                except Exception:
                    return False
            else:
                full_solver = candidate_solver.branch()
                full_solver.timeout = min(max(timeout_ms, 100), 300)
                try:
                    for constraint in constraints:
                        full_solver.add(constraint)
                    if not full_solver.satisfiable():
                        return False
                except Exception:
                    if strict_retry_validation:
                        return False

            for constraint in constraints:
                candidate_solver.add(constraint)
                added_constraint_cache.add(str(claripy.simplify(constraint)))
                debug_constraint_add("set_related", constraint)
            return True

        def constraint_set_related_satisfiable(constraints, seed_vars, timeout_ms=1000):
            constraints = list(constraints)
            if not constraints:
                return True
            if strict_retry_validation:
                test_solver = candidate_solver.branch()
                test_solver.timeout = max(timeout_ms, 1000)
                try:
                    for constraint in constraints:
                        test_solver.add(constraint)
                    return bool(test_solver.satisfiable())
                except Exception:
                    return False
            anchor_vars = expr_vars(init_sp)
            closure = set(seed_vars) - anchor_vars
            for constraint in constraints:
                closure.update(getattr(constraint, 'variables', set()) - anchor_vars)
            if not closure:
                return constraint_set_selection_satisfiable(
                    constraints,
                    timeout_ms=timeout_ms,
                )

            selected = []
            selected_ids = set()
            changed = True
            while changed:
                changed = False
                for constraint in candidate_solver.constraints:
                    constraint_id = id(constraint)
                    if constraint_id in selected_ids:
                        continue
                    constraint_vars = getattr(constraint, 'variables', set()) - anchor_vars
                    if not (constraint_vars & closure):
                        continue
                    selected_ids.add(constraint_id)
                    selected.append(constraint)
                    new_vars = constraint_vars - closure
                    if new_vars:
                        closure.update(new_vars)
                        changed = True

            test_solver = claripy.Solver()
            test_solver.timeout = timeout_ms
            try:
                for constraint in selected:
                    test_solver.add(constraint)
                for constraint in constraints:
                    test_solver.add(constraint)
                return bool(test_solver.satisfiable())
            except Exception:
                return None

        def commit_scalar_zero_constraint(
            expr,
            timeout_ms=None,
            assume_unknown=True,
            allow_related=True,
        ):
            constraint = expr == expr_bvv(0, expr)
            seed_vars = expr_vars(expr)
            zero_timeout_ms = timeout_ms if timeout_ms is not None else max(local_solver_timeout_ms, 1000)
            if (
                try_add_constraint_set_fast([constraint], timeout_ms=zero_timeout_ms)
                or (
                    allow_related
                    and try_add_constraint_set_related(
                        [constraint],
                        seed_vars,
                        timeout_ms=zero_timeout_ms,
                    )
                )
            ):
                return True
            if use_static_memory_collection and allow_related:
                sat = constraint_set_related_satisfiable(
                    [constraint],
                    seed_vars,
                    timeout_ms=max(zero_timeout_ms, 1000),
                )
                if sat is True or (assume_unknown and sat is not False):
                    candidate_solver.add(constraint)
                    added_constraint_cache.add(str(claripy.simplify(constraint)))
                    debug_constraint_add("scalar_zero_assumed", constraint)
                    return True
            return False

        def expr_bvv(value, expr):
            try:
                bits = expr.size()
            except Exception:
                bits = 64
            return claripy.BVV(value & ((1 << bits) - 1), bits)

        def try_constrain_expr_value(expr, value):
            if not expr_vars(expr):
                return False
            return try_add_constraint(expr == expr_bvv(value, expr))

        def iter_ast_nodes(expr):
            seen = set()
            stack = [expr]
            while stack:
                node = stack.pop()
                key = id(node)
                if key in seen:
                    continue
                seen.add(key)
                yield node
                for arg in getattr(node, 'args', ()):
                    if hasattr(arg, 'op'):
                        stack.append(arg)

        def has_scaled_address_use(symbol, min_access_idx=None):
            symbol_vars = expr_vars(symbol)
            if not symbol_vars:
                return False
            scaled_ops = {'__lshift__', 'LShR', 'SShR', '__mul__', 'Mul', 'Concat'}
            for _, addr_symbol, access_idx, _ in mem_accesses:
                if min_access_idx is not None and access_idx <= min_access_idx:
                    continue
                if not (expr_vars(addr_symbol) & symbol_vars):
                    continue
                for node in iter_ast_nodes(addr_symbol):
                    if getattr(node, 'op', None) in scaled_ops and (expr_vars(node) & symbol_vars):
                        return True
            return False

        def is_scaled_loaded_address_source(load_inst, symbol, load_idx):
            if load_inst.width != 8:
                return False
            if (load_idx, stable_expr_key(symbol)) in pointer_source_value_keys:
                return False
            symbol_vars = expr_vars(symbol)
            if not symbol_vars:
                return False
            if not any(
                access_idx > load_idx and (expr_vars(addr_symbol) & symbol_vars)
                for _, addr_symbol, access_idx, _ in mem_accesses
            ):
                return False
            return has_scaled_address_use(symbol, min_access_idx=load_idx)

        def narrow_load_feeds_pointer_load_address(load_inst, symbol, load_idx):
            if load_inst.width >= 8:
                return False
            symbol_vars = expr_vars(symbol)
            if not symbol_vars:
                return False
            for pointer_inst, _, pointer_addr_symbol, pointer_idx in pointer_source_loads:
                if pointer_idx <= load_idx or pointer_inst.width != 8:
                    continue
                if expr_vars(pointer_addr_symbol) & symbol_vars:
                    return True
            for later_inst, later_rd_symbol, later_addr_symbol, later_idx in load_accesses:
                if later_idx <= load_idx or later_inst.width != 8:
                    continue
                if not (expr_vars(later_addr_symbol) & symbol_vars):
                    continue
                later_vars = expr_vars(later_rd_symbol)
                if later_vars and any(
                    access_idx > later_idx and (expr_vars(addr_symbol) & later_vars)
                    for _, addr_symbol, access_idx, _ in mem_accesses
                ):
                    return True
            return False

        def add_neutral_arithmetic_constraints(expr, forbidden_vars=None):
            """Prefer simple scalar operands in complex address residuals.

            This is intentionally applied to address residuals, not to the
            whole address expression.  A pointer/base term should stay a
            pointer; only the nonlinear or additive scalar part is normalized.
            """
            forbidden_vars = set() if forbidden_vars is None else set(forbidden_vars)
            mul_ops = {'__mul__', 'Mul'}
            div_ops = {'__floordiv__', '__truediv__', '__div__', 'SDiv', 'UDiv'}
            add_ops = {'__add__', 'Add'}
            sub_ops = {'__sub__', 'Sub'}

            for node in iter_ast_nodes(expr):
                node_vars = expr_vars(node)
                if not node_vars or (node_vars & forbidden_vars):
                    continue
                op = getattr(node, 'op', '')
                symbolic_args = [
                    arg for arg in getattr(node, 'args', ())
                    if hasattr(arg, 'op')
                    and expr_vars(arg)
                    and not (expr_vars(arg) & forbidden_vars)
                ]
                symbolic_args.sort(key=lambda item: len(str(item)))
                if op in mul_ops or op in div_ops:
                    for arg in symbolic_args:
                        if try_constrain_expr_value(arg, 1):
                            break
                elif op in add_ops or op in sub_ops:
                    for arg in symbolic_args:
                        if try_constrain_expr_value(arg, 0):
                            break

        def target_value_for_expr(value, expr):
            try:
                bits = expr.size()
            except Exception:
                bits = 64
            return value & ((1 << bits) - 1)

        def ast_node_count(expr):
            seen = set()
            count = 0
            stack = [expr]
            while stack:
                node = stack.pop()
                key = id(node)
                if key in seen:
                    continue
                seen.add(key)
                count += 1
                for arg in getattr(node, 'args', ()):
                    if hasattr(arg, 'op'):
                        stack.append(arg)
            return count

        def symbolic_zero_priority(expr):
            vars_ = expr_vars(expr)
            has_init_reg = any(str(var).startswith(REG_PREFIX) for var in vars_)
            return (0 if has_init_reg else 1, len(vars_), ast_node_count(expr), len(str(expr)))

        def constraint_set_selection_satisfiable(constraints, timeout_ms=None):
            if not constraints:
                return True
            test_solver = candidate_solver.branch()
            test_solver.timeout = local_solver_timeout_ms if timeout_ms is None else timeout_ms
            try:
                for constraint in constraints:
                    test_solver.add(constraint)
                return bool(test_solver.satisfiable())
            except Exception:
                return None

        component_satisfiability_cache = {}

        def constraint_set_componentwise_satisfiable(constraints, timeout_ms=10000):
            """Prove full SAT by solving independent variable components."""
            anchor_vars = expr_vars(init_sp)
            fixed_sp_constraint = init_sp == expr_bvv(CONCRETE_REPLAY_SP, init_sp)
            combined = []
            seen = set()
            all_constraints = (
                list(candidate_solver.constraints)
                + [fixed_sp_constraint]
                + list(constraints)
            )
            for constraint in all_constraints:
                key = str(claripy.simplify(constraint))
                if key in seen:
                    continue
                seen.add(key)
                combined.append((key, constraint, expr_vars(constraint) - anchor_vars))

            parent = {}

            def find(variable):
                parent.setdefault(variable, variable)
                while parent[variable] != variable:
                    parent[variable] = parent[parent[variable]]
                    variable = parent[variable]
                return variable

            def union(lhs, rhs):
                lhs_root = find(lhs)
                rhs_root = find(rhs)
                if lhs_root != rhs_root:
                    parent[rhs_root] = lhs_root

            for _, _, variables in combined:
                variables = sorted(variables)
                for variable in variables:
                    find(variable)
                for variable in variables[1:]:
                    union(variables[0], variable)

            anchor_only = []
            grouped = {}
            for entry in combined:
                variables = entry[2]
                if not variables:
                    anchor_only.append(entry)
                    continue
                root = find(next(iter(variables)))
                grouped.setdefault(root, []).append(entry)

            def solve_component(entries):
                component_key = tuple(sorted(key for key, _, _ in entries))
                cached = component_satisfiability_cache.get(component_key)
                if cached is not None:
                    return cached
                test_solver = claripy.Solver()
                test_solver.timeout = timeout_ms
                try:
                    for _, constraint, _ in entries:
                        test_solver.add(constraint)
                    result = bool(test_solver.satisfiable())
                except Exception:
                    return None
                component_satisfiability_cache[component_key] = result
                return result

            anchor_result = solve_component(anchor_only)
            if anchor_result is not True:
                return anchor_result
            for component in grouped.values():
                result = solve_component(anchor_only + component)
                if result is not True:
                    return result
            return True

        def multiplicative_zero_priority(expr, constraints):
            vars_ = expr_vars(expr)
            pointer_like = bool(vars_ & (pointer_loaded_addr_vars | undef_base_vars))
            return (
                1 if pointer_like else 0,
                len(constraints),
                ast_node_count(expr),
                len(vars_),
                len(str(expr)),
            )

        def constraints_to_constant(expr, value, forbidden_vars=None, depth=0, assumed_constraints=None):
            forbidden_vars = set() if forbidden_vars is None else set(forbidden_vars)
            assumed_constraints = [] if assumed_constraints is None else list(assumed_constraints)
            expr = claripy.simplify(expr)
            value = target_value_for_expr(value, expr)
            vars_ = expr_vars(expr)
            if not vars_:
                concrete_value = concrete_expr_value(expr)
                if concrete_value is None:
                    return []
                return [] if target_value_for_expr(concrete_value, expr) == value else None
            if vars_ & forbidden_vars:
                return None
            if depth > 8:
                return None

            def assumed_expr_equals(target_expr, target_value):
                target_expr = claripy.simplify(target_expr)
                target_value = target_value_for_expr(target_value, target_expr)
                target_key = expr_key(target_expr)
                for constraint in assumed_constraints:
                    constraint = claripy.simplify(constraint)
                    if getattr(constraint, 'op', None) not in {'__eq__', 'Eq'}:
                        continue
                    eq_args = [
                        arg for arg in getattr(constraint, 'args', ())
                        if hasattr(arg, 'op')
                    ]
                    if len(eq_args) != 2:
                        continue
                    lhs, rhs = eq_args
                    lhs_value = concrete_expr_value(lhs)
                    rhs_value = concrete_expr_value(rhs)
                    if expr_key(lhs) == target_key and rhs_value is not None:
                        return target_value_for_expr(rhs_value, target_expr) == target_value
                    if expr_key(rhs) == target_key and lhs_value is not None:
                        return target_value_for_expr(lhs_value, target_expr) == target_value
                return False

            if assumed_expr_equals(expr, value):
                return []

            op = getattr(expr, 'op', '')
            args = [arg for arg in getattr(expr, 'args', ()) if hasattr(arg, 'op')]
            symbolic_args = [arg for arg in args if expr_vars(arg)]
            constraints = []

            if op in {'__add__', 'Add', '__sub__', 'Sub'}:
                signed_terms = []
                concrete_total = 0
                expr_mask = (1 << expr.size()) - 1
                for i, arg in enumerate(args):
                    sign = 1 if op in {'__add__', 'Add'} or i == 0 else -1
                    if expr_vars(arg):
                        signed_terms.append((sign, arg))
                        continue
                    concrete_value = concrete_expr_value(arg)
                    if concrete_value is None:
                        return None
                    concrete_total = (concrete_total + sign * concrete_value) & expr_mask

                if not signed_terms:
                    return [] if concrete_total == value else None

                target = (value - concrete_total) & expr_mask
                signed_terms.sort(key=lambda item: symbolic_zero_priority(item[1]))
                for sign, arg in signed_terms[:-1]:
                    sub_constraints = constraints_to_constant(
                        arg,
                        0,
                        forbidden_vars,
                        depth + 1,
                        assumed_constraints=assumed_constraints + constraints,
                    )
                    if sub_constraints is None:
                        return None
                    constraints.extend(sub_constraints)

                sign, arg = signed_terms[-1]
                arg_target = target if sign > 0 else (-target) & expr_mask
                sub_constraints = constraints_to_constant(
                    arg,
                    arg_target,
                    forbidden_vars,
                    depth + 1,
                    assumed_constraints=assumed_constraints + constraints,
                )
                if sub_constraints is None:
                    return None
                constraints.extend(sub_constraints)
                return constraints

            if op in {'__xor__', 'Xor'} and len(args) == 2:
                lhs, rhs = args
                lhs_vars = expr_vars(lhs)
                rhs_vars = expr_vars(rhs)
                if lhs_vars and not rhs_vars:
                    rhs_value = concrete_expr_value(rhs)
                    if rhs_value is None:
                        return None
                    return constraints_to_constant(
                        lhs,
                        value ^ rhs_value,
                        forbidden_vars,
                        depth + 1,
                        assumed_constraints=assumed_constraints,
                    )
                if rhs_vars and not lhs_vars:
                    lhs_value = concrete_expr_value(lhs)
                    if lhs_value is None:
                        return None
                    return constraints_to_constant(
                        rhs,
                        value ^ lhs_value,
                        forbidden_vars,
                        depth + 1,
                        assumed_constraints=assumed_constraints,
                    )

            if op == 'Extract' and args:
                source = args[-1]
                source_vars = expr_vars(source)
                if value == 0 and source_vars and all(str(var).startswith(REG_PREFIX) for var in source_vars):
                    return constraints_to_constant(
                        source,
                        0,
                        forbidden_vars,
                        depth + 1,
                        assumed_constraints=assumed_constraints,
                    )
                return [expr == expr_bvv(value, expr)]

            if op == 'Concat':
                remaining = expr.size()
                for arg in args:
                    arg_bits = arg.size()
                    remaining -= arg_bits
                    arg_value = (value >> remaining) & ((1 << arg_bits) - 1)
                    sub_constraints = constraints_to_constant(
                        arg,
                        arg_value,
                        forbidden_vars,
                        depth + 1,
                        assumed_constraints=assumed_constraints + constraints,
                    )
                    if sub_constraints is None:
                        return None
                    constraints.extend(sub_constraints)
                return constraints

            if op in {'ZeroExt', 'SignExt'} and args:
                return constraints_to_constant(
                    args[-1],
                    value,
                    forbidden_vars,
                    depth + 1,
                    assumed_constraints=assumed_constraints,
                )

            if op in {'__rshift__', 'SShR'} and len(args) >= 2:
                return [expr == expr_bvv(value, expr)]

            if value == 0:
                if op in {'__mul__', 'Mul'}:
                    if any(assumed_expr_equals(arg, 0) for arg in symbolic_args):
                        return []
                    candidates = []
                    for arg in sorted(symbolic_args, key=symbolic_zero_priority):
                        sub_constraints = constraints_to_constant(
                            arg,
                            0,
                            forbidden_vars,
                            depth + 1,
                            assumed_constraints=assumed_constraints,
                        )
                        if sub_constraints is not None:
                            candidates.append((arg, sub_constraints))
                    if not candidates:
                        return None
                    candidates.sort(
                        key=lambda item: multiplicative_zero_priority(item[0], item[1])
                    )
                    unknown = []
                    for _, sub_constraints in candidates:
                        satisfiable = constraint_set_selection_satisfiable(
                            assumed_constraints + sub_constraints,
                            timeout_ms=local_solver_timeout_ms,
                        )
                        if satisfiable is True:
                            return sub_constraints
                        if satisfiable is None:
                            unknown.append(sub_constraints)
                    if unknown:
                        return unknown[0]
                    return None
                if op in {'__lshift__', '__rshift__', 'LShR', 'SShR'}:
                    if not args:
                        return None
                    shifted = args[0]
                    if not expr_vars(shifted):
                        return []
                    return constraints_to_constant(
                        shifted,
                        0,
                        forbidden_vars,
                        depth + 1,
                        assumed_constraints=assumed_constraints,
                    )

            if op in {'__lshift__', 'LShR', 'SShR'} and len(args) >= 2:
                shift_value = concrete_expr_value(args[1])
                if shift_value is not None:
                    if op == '__lshift__':
                        if value & ((1 << shift_value) - 1):
                            return None
                        return constraints_to_constant(
                            args[0],
                            value >> shift_value,
                            forbidden_vars,
                            depth + 1,
                            assumed_constraints=assumed_constraints,
                        )
                    return constraints_to_constant(
                        args[0],
                        value << shift_value,
                        forbidden_vars,
                        depth + 1,
                        assumed_constraints=assumed_constraints,
                    )

            if op in {'__mul__', 'Mul'} and symbolic_args:
                concrete_product = 1
                for arg in args:
                    if expr_vars(arg):
                        continue
                    concrete_arg = concrete_expr_value(arg)
                    if concrete_arg is None:
                        return None
                    concrete_product = (concrete_product * concrete_arg) & ((1 << expr.size()) - 1)
                if concrete_product == 0:
                    return [] if value == 0 else None
                if concrete_product != 1:
                    if value % concrete_product != 0:
                        return None
                    carrier_target = value // concrete_product
                else:
                    carrier_target = value
                candidates = []
                for carrier_arg in sorted(symbolic_args, key=symbolic_zero_priority, reverse=True):
                    candidate_constraints = []
                    carrier_constraints = constraints_to_constant(
                        carrier_arg,
                        carrier_target,
                        forbidden_vars,
                        depth + 1,
                        assumed_constraints=assumed_constraints,
                    )
                    if carrier_constraints is None:
                        continue
                    candidate_constraints.extend(carrier_constraints)
                    valid = True
                    for other_arg in symbolic_args:
                        if other_arg is carrier_arg:
                            continue
                        other_constraints = constraints_to_constant(
                            other_arg,
                            1,
                            forbidden_vars,
                            depth + 1,
                            assumed_constraints=assumed_constraints + candidate_constraints,
                        )
                        if other_constraints is None:
                            valid = False
                            break
                        candidate_constraints.extend(other_constraints)
                    if valid:
                        candidates.append(candidate_constraints)
                unknown = []
                for candidate_constraints in candidates:
                    satisfiable = constraint_set_selection_satisfiable(
                        assumed_constraints + candidate_constraints,
                        timeout_ms=local_solver_timeout_ms,
                    )
                    if satisfiable is True:
                        return candidate_constraints
                    if satisfiable is None:
                        unknown.append(candidate_constraints)
                if unknown:
                    return unknown[0]
                return None

            if value == 1:
                if op in {'__mul__', 'Mul'}:
                    for arg in symbolic_args:
                        sub_constraints = constraints_to_constant(
                            arg,
                            1,
                            forbidden_vars,
                            depth + 1,
                            assumed_constraints=assumed_constraints + constraints,
                        )
                        if sub_constraints is None:
                            return None
                        constraints.extend(sub_constraints)
                    return constraints
                if op in {'__floordiv__', '__truediv__', '__div__', 'SDiv', 'UDiv'}:
                    if not symbolic_args:
                        return []
                    numerator = args[0] if args else None
                    if numerator is None or not expr_vars(numerator):
                        return None
                    sub_constraints = constraints_to_constant(
                        numerator,
                        1,
                        forbidden_vars,
                        depth + 1,
                        assumed_constraints=assumed_constraints + constraints,
                    )
                    if sub_constraints is None:
                        return None
                    constraints.extend(sub_constraints)
                    for arg in args[1:]:
                        if not expr_vars(arg):
                            continue
                        sub_constraints = constraints_to_constant(
                            arg,
                            1,
                            forbidden_vars,
                            depth + 1,
                            assumed_constraints=assumed_constraints + constraints,
                        )
                        if sub_constraints is None:
                            return None
                        constraints.extend(sub_constraints)
                    return constraints

            if len(vars_) == 1:
                return [expr == expr_bvv(value, expr)]

            return None

        def constraints_to_carrier(expr, carrier_expr, depth=0):
            expr = claripy.simplify(expr)
            carrier_expr = claripy.simplify(carrier_expr)
            if expr_key(expr) == expr_key(carrier_expr):
                return []
            carrier_vars = expr_vars(carrier_expr)
            if not carrier_vars or not (expr_vars(expr) & carrier_vars):
                return None
            if depth > 8:
                return None

            op = getattr(expr, 'op', '')
            args = [arg for arg in getattr(expr, 'args', ()) if hasattr(arg, 'op')]
            carrier_args = [arg for arg in args if expr_vars(arg) & carrier_vars]
            if len(carrier_args) != 1:
                return None
            carrier_arg = carrier_args[0]
            constraints = []

            if op in {'__add__', 'Add'}:
                sub_constraints = constraints_to_carrier(carrier_arg, carrier_expr, depth + 1)
                if sub_constraints is None:
                    return None
                constraints.extend(sub_constraints)
                residual_terms = []
                concrete_total = 0
                expr_mask = (1 << expr.size()) - 1
                for arg in args:
                    if arg is carrier_arg:
                        continue
                    if not expr_vars(arg):
                        concrete_value = concrete_expr_value(arg)
                        if concrete_value is None:
                            return None
                        concrete_total = (concrete_total + concrete_value) & expr_mask
                    else:
                        residual_terms.append(arg)
                if residual_terms:
                    target = (-concrete_total) & expr_mask
                    residual_terms.sort(key=symbolic_zero_priority)
                    for arg in residual_terms[:-1]:
                        sub_constraints = constraints_to_constant(arg, 0, carrier_vars, depth + 1)
                        if sub_constraints is None:
                            return None
                        constraints.extend(sub_constraints)
                    sub_constraints = constraints_to_constant(residual_terms[-1], target, carrier_vars, depth + 1)
                    if sub_constraints is None:
                        return None
                    constraints.extend(sub_constraints)
                elif concrete_total != 0:
                    return None
                return constraints

            if op in {'__sub__', 'Sub'}:
                if args and carrier_arg is not args[0]:
                    return None
                sub_constraints = constraints_to_carrier(carrier_arg, carrier_expr, depth + 1)
                if sub_constraints is None:
                    return None
                constraints.extend(sub_constraints)
                for arg in args[1:]:
                    if not expr_vars(arg):
                        continue
                    sub_constraints = constraints_to_constant(arg, 0, carrier_vars, depth + 1)
                    if sub_constraints is None:
                        return None
                    constraints.extend(sub_constraints)
                return constraints

            if op in {'__mul__', 'Mul'}:
                sub_constraints = constraints_to_carrier(carrier_arg, carrier_expr, depth + 1)
                if sub_constraints is None:
                    return None
                constraints.extend(sub_constraints)
                for arg in args:
                    if arg is carrier_arg or not expr_vars(arg):
                        continue
                    sub_constraints = constraints_to_constant(arg, 1, carrier_vars, depth + 1)
                    if sub_constraints is None:
                        return None
                    constraints.extend(sub_constraints)
                return constraints

            if op in {'__floordiv__', '__truediv__', '__div__', 'SDiv', 'UDiv'}:
                if args and carrier_arg is not args[0]:
                    return None
                sub_constraints = constraints_to_carrier(carrier_arg, carrier_expr, depth + 1)
                if sub_constraints is None:
                    return None
                constraints.extend(sub_constraints)
                for arg in args[1:]:
                    if not expr_vars(arg):
                        continue
                    sub_constraints = constraints_to_constant(arg, 1, carrier_vars, depth + 1)
                    if sub_constraints is None:
                        return None
                    constraints.extend(sub_constraints)
                return constraints

            if op in {'__lshift__', '__rshift__', 'LShR', 'SShR'}:
                if args and carrier_arg is not args[0]:
                    return None
                return constraints_to_carrier(carrier_arg, carrier_expr, depth + 1)

            return None

        def is_loaded_pointer_base_candidate(symbol, load_idx):
            symbol_vars = expr_vars(symbol)
            if not symbol_vars:
                return False
            cache_key = (load_idx, expr_key(symbol))
            if cache_key in loaded_pointer_base_candidate_cache:
                return loaded_pointer_base_candidate_cache[cache_key]
            for _, later_addr_symbol, later_idx, _ in mem_accesses:
                if later_idx <= load_idx:
                    continue
                later_vars = expr_vars(later_addr_symbol)
                if not (later_vars & symbol_vars):
                    continue
                residual = claripy.simplify(later_addr_symbol - symbol)
                residual_vars = expr_vars(residual)
                if residual_vars & symbol_vars:
                    continue
                if concrete_expr_value(residual) is not None:
                    loaded_pointer_base_candidate_cache[cache_key] = True
                    return True
                base_like_residual_vars = set(pointer_loaded_addr_vars) | set(undef_base_vars)
                for reg in reg_pointer_hints:
                    reg_symbol = reg_to_symbol.get(reg)
                    if reg_symbol is not None:
                        base_like_residual_vars.update(expr_vars(reg_symbol))
                if residual_vars and not (residual_vars & base_like_residual_vars):
                    loaded_pointer_base_candidate_cache[cache_key] = True
                    return True
                carrier_constraints = constraints_to_carrier(later_addr_symbol, symbol)
                if carrier_constraints is not None:
                    loaded_pointer_base_candidate_cache[cache_key] = True
                    return True
            loaded_pointer_base_candidate_cache[cache_key] = False
            return False

        def constraints_to_internal_carrier(expr, carrier_expr, depth=0):
            expr = claripy.simplify(expr)
            carrier_expr = claripy.simplify(carrier_expr)
            if expr_key(expr) == expr_key(carrier_expr):
                return []
            carrier_vars = expr_vars(carrier_expr)
            if not carrier_vars or not (expr_vars(expr) & carrier_vars):
                return None
            if depth > 8:
                return None

            op = getattr(expr, 'op', '')
            args = [arg for arg in getattr(expr, 'args', ()) if hasattr(arg, 'op')]
            carrier_args = [arg for arg in args if expr_vars(arg) & carrier_vars]
            constraints = []

            if op in {'__add__', 'Add'}:
                if len(carrier_args) != 1:
                    return None
                carrier_arg = carrier_args[0]
                sub_constraints = constraints_to_internal_carrier(carrier_arg, carrier_expr, depth + 1)
                if sub_constraints is None:
                    return None
                constraints.extend(sub_constraints)
                for arg in args:
                    if arg is carrier_arg or not expr_vars(arg):
                        continue
                    sub_constraints = constraints_to_constant(arg, 0, carrier_vars, depth + 1)
                    if sub_constraints is None:
                        return None
                    constraints.extend(sub_constraints)
                return constraints

            if op in {'__sub__', 'Sub'}:
                if not args or len(carrier_args) != 1 or carrier_args[0] is not args[0]:
                    return None
                sub_constraints = constraints_to_internal_carrier(args[0], carrier_expr, depth + 1)
                if sub_constraints is None:
                    return None
                constraints.extend(sub_constraints)
                for arg in args[1:]:
                    if not expr_vars(arg):
                        continue
                    sub_constraints = constraints_to_constant(arg, 0, carrier_vars, depth + 1)
                    if sub_constraints is None:
                        return None
                    constraints.extend(sub_constraints)
                return constraints

            if op in {'__mul__', 'Mul'}:
                if len(carrier_args) != 1:
                    return None
                carrier_arg = carrier_args[0]
                sub_constraints = constraints_to_internal_carrier(carrier_arg, carrier_expr, depth + 1)
                if sub_constraints is None:
                    return None
                constraints.extend(sub_constraints)
                for arg in args:
                    if arg is carrier_arg or not expr_vars(arg):
                        continue
                    sub_constraints = constraints_to_constant(arg, 1, carrier_vars, depth + 1)
                    if sub_constraints is None:
                        return None
                    constraints.extend(sub_constraints)
                return constraints

            if op in {'__floordiv__', '__truediv__', '__div__', 'SDiv', 'UDiv'}:
                if not args or len(carrier_args) != 1 or carrier_args[0] is not args[0]:
                    return None
                sub_constraints = constraints_to_internal_carrier(args[0], carrier_expr, depth + 1)
                if sub_constraints is None:
                    return None
                constraints.extend(sub_constraints)
                for arg in args[1:]:
                    if not expr_vars(arg):
                        continue
                    sub_constraints = constraints_to_constant(arg, 1, carrier_vars, depth + 1)
                    if sub_constraints is None:
                        return None
                    constraints.extend(sub_constraints)
                return constraints

            if op in {'__lshift__', '__rshift__', 'LShR', 'SShR'}:
                if not args or len(carrier_args) != 1 or carrier_args[0] is not args[0]:
                    return None
                return constraints_to_internal_carrier(args[0], carrier_expr, depth + 1)

            return None

        def count_mul_ancestors(expr, carrier_expr):
            carrier_vars = expr_vars(carrier_expr)
            if not carrier_vars:
                return 0
            count = 0
            stack = [expr]
            while stack:
                node = stack.pop()
                if not (expr_vars(node) & carrier_vars):
                    continue
                if getattr(node, 'op', '') in {'__mul__', 'Mul'}:
                    count += 1
                for arg in getattr(node, 'args', ()):
                    if hasattr(arg, 'op'):
                        stack.append(arg)
            return count

        def try_add_constraint_set(constraints, verify_constraints=None):
            verify_constraints = [] if verify_constraints is None else verify_constraints
            unique_constraints = []
            seen = set()
            for constraint in constraints:
                key = str(claripy.simplify(constraint))
                if key in seen or key in added_constraint_cache:
                    continue
                seen.add(key)
                unique_constraints.append(constraint)
            test_solver = candidate_solver.branch()
            for constraint in unique_constraints:
                test_solver.add(constraint)
            test_solver.timeout = HEURISTIC_SOLVER_TIMEOUT_MS
            try:
                for constraint in verify_constraints:
                    test_solver.add(constraint)
                if not test_solver.satisfiable():
                    return False
            except Exception:
                return False
            for constraint in unique_constraints:
                candidate_solver.add(constraint)
                added_constraint_cache.add(str(claripy.simplify(constraint)))
                debug_constraint_add("set", constraint)
            return True

        def append_value_init(
            insts,
            reg_name,
            value,
            force_stack_offset=None,
            force_sp_delta=None,
            force_inverse_sp_delta=None,
            force_scaled_stack=None,
            force_affine_quotient=None,
            allow_scaled_stack=False,
        ):
            target_reg = find_reg_by_name(reg_name)
            alternate_scratch = (
                TEMP_REG
                if target_reg == find_reg_by_name(TEMP_REG2)
                else TEMP_REG2
            )
            if force_affine_quotient is not None:
                recipe_kind = force_affine_quotient[0]
                if recipe_kind == 'affine_linear':
                    _, anchor_value, coefficient = force_affine_quotient
                    coefficient = int(coefficient)
                    if coefficient == 0:
                        raise ValueError(
                            f"invalid affine linear coefficient: {coefficient}"
                        )
                    scratch = alternate_scratch
                    insts.append(UFmtInst('li', reg_name, CONCRETE_REPLAY_SP))
                    insts.append(RFmtInst('sub', reg_name, 'sp', reg_name))
                    if abs(coefficient) > 1:
                        insts.append(UFmtInst('li', scratch, abs(coefficient)))
                        insts.append(RFmtInst('mul', reg_name, reg_name, scratch))
                    if coefficient < 0:
                        insts.append(RFmtInst('sub', reg_name, 'zero', reg_name))
                    insts.append(UFmtInst('li', scratch, int(anchor_value)))
                    insts.append(RFmtInst('add', reg_name, reg_name, scratch))
                    return
                if recipe_kind == 'affine_quotient':
                    _, offset, divisor = force_affine_quotient
                    multiplier = 1
                elif recipe_kind == 'affine_scaled_quotient':
                    _, offset, divisor, multiplier = force_affine_quotient
                else:
                    raise ValueError(
                        f"invalid runtime register recipe: {force_affine_quotient!r}"
                    )
                scratch = alternate_scratch
                insts.append(UFmtInst('li', reg_name, abs(offset)))
                if offset >= 0:
                    insts.append(RFmtInst('sub', reg_name, 'sp', reg_name))
                else:
                    insts.append(RFmtInst('add', reg_name, 'sp', reg_name))
                if divisor > 1:
                    insts.append(UFmtInst('li', scratch, divisor))
                    insts.append(RFmtInst('divu', reg_name, reg_name, scratch))
                if multiplier > 1:
                    if not (multiplier & (multiplier - 1)):
                        insts.append(IFmtInst(
                            'slli',
                            reg_name,
                            reg_name,
                            multiplier.bit_length() - 1,
                        ))
                    else:
                        insts.append(UFmtInst('li', scratch, multiplier))
                        insts.append(RFmtInst('mul', reg_name, reg_name, scratch))
                return
            if force_scaled_stack is not None:
                offset, shift = force_scaled_stack
                insts.append(UFmtInst('li', reg_name, abs(offset)))
                if offset >= 0:
                    insts.append(RFmtInst('sub', reg_name, 'sp', reg_name))
                else:
                    insts.append(RFmtInst('add', reg_name, 'sp', reg_name))
                insts.append(IFmtInst('srli', reg_name, reg_name, shift))
                return
            if force_sp_delta is not None:
                insts.append(UFmtInst('li', reg_name, force_sp_delta & ((1 << 64) - 1)))
                insts.append(RFmtInst('add', reg_name, 'sp', reg_name))
                return
            if force_inverse_sp_delta is not None:
                insts.append(UFmtInst('li', reg_name, force_inverse_sp_delta & ((1 << 64) - 1)))
                insts.append(RFmtInst('sub', reg_name, reg_name, 'sp'))
                return
            stack_offset = force_stack_offset
            if stack_offset is None:
                stack_offset = signed_stack_offset_for_value(value)
            if stack_offset is not None:
                abs_offset = abs(stack_offset)
                insts.append(UFmtInst('li', reg_name, abs_offset))
                if stack_offset >= 0:
                    insts.append(RFmtInst('sub', reg_name, 'sp', reg_name))
                else:
                    insts.append(RFmtInst('add', reg_name, 'sp', reg_name))
            elif allow_scaled_stack:
                scaled = scaled_stack_transform_for_value(value)
                if scaled is not None:
                    offset, shift = scaled
                    insts.append(UFmtInst('li', reg_name, abs(offset)))
                    if offset >= 0:
                        insts.append(RFmtInst('sub', reg_name, 'sp', reg_name))
                    else:
                        insts.append(RFmtInst('add', reg_name, 'sp', reg_name))
                    insts.append(IFmtInst('srli', reg_name, reg_name, shift))
                else:
                    insts.append(UFmtInst('li', reg_name, value & ((1 << 64) - 1)))
            else:
                insts.append(UFmtInst('li', reg_name, value & ((1 << 64) - 1)))

        def mem_value_expr(inst, rd_symbol):
            return rd_symbol

        def load_value_derived_access_range_constraints(
            value_expr,
            load_idx,
            avoid_existing_load_slots=False,
            candidate_constraints=None,
        ):
            value_vars = expr_vars(value_expr)
            if not value_vars:
                return []
            pending_constraints = list(candidate_constraints or [])

            def same_address_with_pending(addr_a, addr_b):
                if same_address(addr_a, addr_b, allow_solver=False):
                    return True
                if not pending_constraints:
                    return False
                affine_a = affine_key(addr_a)
                affine_b = affine_key(addr_b)
                if affine_a is None or affine_b is None:
                    return False
                if (
                    affine_a[1] == affine_b[1]
                    or len(expr_vars(affine_a[2])) != 1
                    or len(expr_vars(affine_b[2])) != 1
                ):
                    return False
                test_solver = candidate_solver.branch()
                test_solver.timeout = HEURISTIC_SOLVER_TIMEOUT_MS
                try:
                    for constraint in pending_constraints:
                        test_solver.add(constraint)
                    test_solver.add(addr_a != addr_b)
                    return not test_solver.satisfiable()
                except Exception:
                    return False

            constraints = []
            load_access_indices = {
                candidate_idx
                for _, _, _, candidate_idx in load_accesses
            }
            for _, future_addr_symbol, access_idx, access_width in mem_accesses:
                if access_idx <= load_idx:
                    continue
                if not (expr_vars(future_addr_symbol) & value_vars):
                    continue
                offset_expr = init_sp - future_addr_symbol
                constraints.extend([
                    claripy.UGE(offset_expr, claripy.BVV(access_width, 64)),
                    claripy.ULE(offset_expr, claripy.BVV(STACK_RANGE, 64)),
                ])
                if access_width > 1:
                    constraints.append(
                        (future_addr_symbol & (access_width - 1)) == 0
                    )
                if not avoid_existing_load_slots or access_idx not in load_access_indices:
                    continue
                for used_offset, used_width, used_addr_symbol in access_ranges:
                    if same_address_with_pending(
                        future_addr_symbol,
                        used_addr_symbol,
                    ):
                        continue
                    constraints.append(
                        concrete_offset_no_overlap_constraint(
                            offset_expr,
                            init_slot_width(access_width),
                            used_offset,
                            used_width,
                        )
                    )
            return constraints

        def load_raw_value(inst, value_expr):
            bits = inst.width * 8
            return value_expr[bits - 1:0]

        def constrain_word_field(word_symbol, byte_offset, inst, value_expr, protected=False):
            bits = inst.width * 8
            lo = byte_offset * 8
            hi = lo + bits - 1
            constraint = word_symbol[hi:lo] == load_raw_value(inst, value_expr)
            if protected:
                timeout_ms = 100 if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD else HEURISTIC_SOLVER_TIMEOUT_MS
                return try_add_constraint(constraint, timeout_ms=timeout_ms)
            if not try_add_constraint(constraint, timeout_ms=local_solver_timeout_ms):
                if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD:
                    seed_vars = expr_vars(word_symbol) | expr_vars(value_expr)
                    field_timeout_ms = 100
                    if try_add_constraint_set_related(
                        [constraint],
                        seed_vars,
                        timeout_ms=field_timeout_ms,
                    ):
                        return True
                    sat = constraint_set_related_satisfiable(
                        [constraint],
                        seed_vars,
                        timeout_ms=field_timeout_ms,
                    )
                    if sat is True:
                        candidate_solver.add(constraint)
                        added_constraint_cache.add(str(claripy.simplify(constraint)))
                        debug_constraint_add("word_field_required", constraint)
                        return True
                return False
            return True

        def cheap_same_address(addr_a, addr_b):
            if addr_b is None:
                return False
            cache_key = tuple(sorted((id(addr_a), id(addr_b))))
            if cache_key in cheap_same_address_cache:
                return cheap_same_address_cache[cache_key]

            def remember(value):
                cheap_same_address_cache[cache_key] = value
                return value

            key_a = expr_key(addr_a)
            key_b = expr_key(addr_b)
            if key_a == key_b:
                return remember(True)
            affine_result = affine_same_or_distinct(addr_a, addr_b)
            if affine_result is not None:
                return remember(affine_result)
            affine_a = affine_key(addr_a)
            affine_b = affine_key(addr_b)
            if affine_a is not None and affine_b is not None:
                _, imm_a, base_a = affine_a
                _, imm_b, base_b = affine_b
                if imm_a == imm_b:
                    roots_a = expr_equiv_roots(base_a)
                    roots_b = expr_equiv_roots(base_b)
                    if len(roots_a) == 1 and roots_a == roots_b:
                        return remember(True)
            diff_value = concrete_expr_value(claripy.simplify(addr_a - addr_b))
            if isinstance(diff_value, int):
                return remember(diff_value == 0)
            if not exprs_may_be_related(addr_a, addr_b):
                return remember(False)
            return remember(None)

        def same_address(addr_a, addr_b, allow_solver=True):
            cheap_result = cheap_same_address(addr_a, addr_b)
            if cheap_result is not None:
                return cheap_result
            if not allow_solver:
                return False
            key_a = expr_key(addr_a)
            key_b = expr_key(addr_b)
            cache_key = tuple(sorted((key_a, key_b)))
            if cache_key in same_address_cache:
                return same_address_cache[cache_key]
            test_solver = candidate_solver.branch()
            test_solver.timeout = HEURISTIC_SOLVER_TIMEOUT_MS
            try:
                test_solver.add(addr_a != addr_b)
                result = not test_solver.satisfiable()
            except Exception:
                result = False
            if result:
                same_address_cache[cache_key] = result
            return result

        def solver_same_address(addr_a, addr_b, timeout_ms=1000):
            if addr_b is None:
                return False
            key_a = expr_key(addr_a)
            key_b = expr_key(addr_b)
            if key_a == key_b:
                return True
            affine_result = affine_same_or_distinct(addr_a, addr_b)
            if affine_result is not None:
                return affine_result
            cache_key = tuple(sorted((key_a, key_b)))
            if cache_key in same_address_cache:
                return same_address_cache[cache_key]
            test_solver = candidate_solver.branch()
            test_solver.timeout = timeout_ms
            try:
                test_solver.add(addr_a != addr_b)
                result = not test_solver.satisfiable()
            except Exception:
                result = False
            if result:
                same_address_cache[cache_key] = result
            return result

        def forced_same_address_cached(addr_a, addr_b):
            if addr_b is None:
                return False
            key_a = expr_key(addr_a)
            key_b = expr_key(addr_b)
            if key_a == key_b:
                return True
            affine_result = affine_same_or_distinct(addr_a, addr_b)
            if affine_result is not None:
                return affine_result
            cache_key = tuple(sorted((key_a, key_b)))
            if cache_key in forced_same_address_cache:
                return forced_same_address_cache[cache_key]
            if not exprs_may_be_related(addr_a, addr_b):
                return False
            test_solver = candidate_solver.branch()
            test_solver.timeout = HEURISTIC_SOLVER_TIMEOUT_MS
            try:
                test_solver.add(addr_a != addr_b)
                result = not test_solver.satisfiable()
            except Exception:
                result = False
            if result:
                forced_same_address_cache[cache_key] = result
            return result

        def stored_value_for_load(store_data_symbol, store_width, load_inst):
            return stored_value_for_load_expr(store_data_symbol, store_width, load_inst)

        def prior_same_addr_store(addr_symbol, inst_idx, allow_solver=True):
            cache_key = (expr_key(addr_symbol), inst_idx, allow_solver)
            if cache_key in prior_store_cache:
                return prior_store_cache[cache_key]
            for store_inst, store_addr_symbol, store_idx, store_width, store_data_symbol in reversed(store_accesses):
                if store_idx < inst_idx and same_address(store_addr_symbol, addr_symbol, allow_solver=allow_solver):
                    result = store_inst, store_addr_symbol, store_idx, store_width, store_data_symbol
                    prior_store_cache[cache_key] = result
                    return result
            return None

        def has_intervening_same_addr_store(addr_symbol, prev_idx, next_idx, allow_solver=True):
            for _, store_addr_symbol, store_idx, _, _ in store_accesses:
                if prev_idx < store_idx < next_idx and same_address(store_addr_symbol, addr_symbol, allow_solver=allow_solver):
                    return True
            return False

        def has_prior_same_addr_store(addr_symbol, inst_idx, allow_solver=True):
            return prior_same_addr_store(addr_symbol, inst_idx, allow_solver=allow_solver) is not None

        def prior_forced_same_addr_store(addr_symbol, inst_idx):
            cache_key = (expr_key(addr_symbol), inst_idx, "forced")
            if cache_key in prior_store_cache and prior_store_cache[cache_key] is not None:
                return prior_store_cache[cache_key]
            for store_inst, store_addr_symbol, store_idx, store_width, store_data_symbol in reversed(store_accesses):
                if store_idx >= inst_idx:
                    continue
                if same_address(store_addr_symbol, addr_symbol, allow_solver=False):
                    result = store_inst, store_addr_symbol, store_idx, store_width, store_data_symbol
                    prior_store_cache[cache_key] = result
                    return result
                if (
                    len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                    and forced_same_address_cached(store_addr_symbol, addr_symbol)
                ):
                    result = store_inst, store_addr_symbol, store_idx, store_width, store_data_symbol
                    prior_store_cache[cache_key] = result
                    return result
            return None

        def same_or_forced_same_addr(addr_a, addr_b):
            if same_address(addr_a, addr_b, allow_solver=False):
                return True
            return (
                len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                and exprs_may_be_related(addr_a, addr_b)
                and forced_same_address_cached(addr_a, addr_b)
            )

        def load_has_same_slot_update_chain(load_inst, rd_symbol, addr_symbol, load_idx):
            if load_inst.width != 8:
                return False
            value_expr = mem_value_expr(load_inst, rd_symbol)
            value_vars = expr_vars(value_expr)
            if not value_vars:
                return False

            for _, store_addr_symbol, store_idx, store_width, store_data_symbol in reversed(store_accesses):
                if store_idx >= load_idx:
                    continue
                if not same_or_forced_same_addr(store_addr_symbol, addr_symbol):
                    continue
                stored_expr = stored_value_for_load(store_data_symbol, store_width, load_inst)
                return stored_expr is not None and bool(expr_vars(stored_expr))

            next_same_load_idx = None
            for later_inst, _, later_addr_symbol, later_idx in mem_entries:
                if later_idx <= load_idx or later_inst.width != load_inst.width:
                    continue
                if not same_or_forced_same_addr(later_addr_symbol, addr_symbol):
                    continue
                next_same_load_idx = later_idx
                break
            if next_same_load_idx is None:
                return False

            for _, store_addr_symbol, store_idx, store_width, store_data_symbol in store_accesses:
                if not (load_idx < store_idx < next_same_load_idx):
                    continue
                if not same_or_forced_same_addr(store_addr_symbol, addr_symbol):
                    continue
                stored_expr = stored_value_for_load(store_data_symbol, store_width, load_inst)
                if stored_expr is not None and (expr_vars(stored_expr) & value_vars):
                    return True
            return False

        def add_store_forward_constraints_for_load(prior_store, addr_symbol, inst, rd_symbol, load_idx=None):
            if prior_store is None:
                return False
            _, store_addr_symbol, _, store_width, store_data_symbol = prior_store
            stored_expr = stored_value_for_load(store_data_symbol, store_width, inst)
            if stored_expr is None:
                return False
            if (
                load_idx is not None
                and inst.width == 8
                and not load_value_is_additive_offset_to_live_base(rd_symbol, load_idx)
                and (
                    load_value_has_direct_pointer_use(rd_symbol, load_idx)
                    or load_value_has_direct_store_addr_use(rd_symbol, load_idx)
                )
            ):
                load_min_offset = min_pointer_offset_for_vars(expr_vars(rd_symbol), load_idx)
                stored_value = concrete_expr_value(stored_expr)
                if stored_value is not None:
                    stored_offset = stack_offset_for_value(stored_value)
                    if (
                        stored_offset is None
                        or stored_offset < load_min_offset
                        or stored_offset > STACK_RANGE
                    ):
                        if os.environ.get("RVMCA_DEBUG_STORE_FORWARD") == "1":
                            DEBUG(f"store_forward_skip_nonpointer_value {({
                                'idx': load_idx,
                                'inst': getattr(inst, 'code', str(inst)),
                                'stored': str(stored_expr),
                                'value': hex(stored_value & ((1 << 64) - 1)),
                            })}")
                        return False
                elif expr_vars(stored_expr):
                    stack_constraints = stack_pointer_constraints_for_expr(
                        stored_expr,
                        load_min_offset,
                    )
                    stack_sat = constraint_set_related_satisfiable(
                        stack_constraints,
                        expr_vars(stored_expr),
                        timeout_ms=100 if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD else 1000,
                    )
                    if stack_sat is False:
                        if os.environ.get("RVMCA_DEBUG_STORE_FORWARD") == "1":
                            DEBUG(f"store_forward_skip_unstackable_value {({
                                'idx': load_idx,
                                'inst': getattr(inst, 'code', str(inst)),
                                'stored': str(stored_expr),
                            })}")
                        return False
                else:
                    return False
            value_expr = mem_value_expr(inst, rd_symbol)
            constraints = []
            if not same_address(store_addr_symbol, addr_symbol, allow_solver=False):
                constraints.append(store_addr_symbol == addr_symbol)
            constraints.append(value_expr == stored_expr)
            seed_vars = (
                expr_vars(store_addr_symbol)
                | expr_vars(addr_symbol)
                | expr_vars(value_expr)
                | expr_vars(stored_expr)
            )
            added = (
                try_add_constraint_set_fast(constraints, timeout_ms=local_solver_timeout_ms)
                or try_add_constraint_set_related(
                    constraints,
                    seed_vars,
                    timeout_ms=max(local_solver_timeout_ms, 1000),
                )
            )
            if added:
                register_expr_equality(value_expr, stored_expr)
            return added

        def has_forced_prior_same_addr_store_cached(addr_symbol, inst_idx):
            cache_key = (expr_key(addr_symbol), inst_idx)
            if cache_key in forced_prior_store_cache:
                return forced_prior_store_cache[cache_key]
            for _, store_addr_symbol, store_idx, _, _ in reversed(store_accesses):
                if store_idx < inst_idx and forced_same_address_cached(store_addr_symbol, addr_symbol):
                    forced_prior_store_cache[cache_key] = True
                    return True
            return False

        def add_memory_dataflow_constraints():
            complex_memory_block = len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
            forced_alias_pair_budget_exceeded = (
                len(mem_entries) * max(1, len(store_accesses))
                > MEMORY_DATAFLOW_FORCED_ALIAS_PAIR_BUDGET
            )
            allow_load_load_solver = (
                len(store_accesses) >= GLOBAL_NO_OVERLAP_STORE_THRESHOLD
                and len(mem_entries) <= 64
            )
            if not complex_memory_block:
                for i, (first_inst, first_rd_symbol, first_addr_symbol, first_idx) in enumerate(mem_entries):
                    first_expr = mem_value_expr(first_inst, first_rd_symbol)
                    for inst, rd_symbol, addr_symbol, inst_idx in mem_entries[i + 1:]:
                        if has_intervening_same_addr_store(first_addr_symbol, first_idx, inst_idx, allow_solver=False):
                            continue
                        if same_address(first_addr_symbol, addr_symbol, allow_solver=allow_load_load_solver):
                            value_expr = mem_value_expr(inst, rd_symbol)
                            if try_add_constraint(value_expr == first_expr):
                                register_expr_equality(value_expr, first_expr)

            for inst, rd_symbol, addr_symbol, inst_idx in mem_entries:
                prior_store = prior_same_addr_store(addr_symbol, inst_idx, allow_solver=False)
                if (
                    prior_store is None
                    and len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                    and not forced_alias_pair_budget_exceeded
                ):
                    prior_store = prior_forced_same_addr_store(addr_symbol, inst_idx)
                add_store_forward_constraints_for_load(prior_store, addr_symbol, inst, rd_symbol, inst_idx)

        def add_same_address_load_alias_constraints():
            """Bind repeated full-width loads from the same address before role hints split them."""
            complex_memory_block = len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
            pair_budget = 256 if complex_memory_block else None
            pairs_tried = 0
            representatives = []

            for inst, rd_symbol, addr_symbol, inst_idx in mem_entries:
                if inst.width != 8:
                    continue
                matched_representative = False
                for first_inst, first_rd_symbol, first_addr_symbol, first_idx in representatives:
                    if pair_budget is not None and pairs_tried >= pair_budget:
                        return
                    pairs_tried += 1
                    cheap_same = same_address(first_addr_symbol, addr_symbol, allow_solver=False)
                    solver_same = False
                    if (
                        not cheap_same
                        and not complex_memory_block
                        and exprs_may_be_related(first_addr_symbol, addr_symbol)
                    ):
                        solver_same = solver_same_address(
                            first_addr_symbol,
                            addr_symbol,
                            timeout_ms=max(local_solver_timeout_ms, 1000),
                        )
                    if not (cheap_same or solver_same):
                        continue
                    if has_intervening_same_addr_store(
                        first_addr_symbol,
                        first_idx,
                        inst_idx,
                        allow_solver=bool(solver_same),
                    ):
                        continue

                    first_value_expr = mem_value_expr(first_inst, first_rd_symbol)
                    value_expr = mem_value_expr(inst, rd_symbol)
                    equality_constraint = value_expr == first_value_expr
                    seed_vars = expr_vars(value_expr) | expr_vars(first_value_expr)
                    equality_added = (
                        try_add_constraint_set_fast(
                            [equality_constraint],
                            timeout_ms=local_solver_timeout_ms,
                        )
                        or try_add_constraint_set_related(
                            [equality_constraint],
                            seed_vars,
                            timeout_ms=max(local_solver_timeout_ms, 1000),
                        )
                    )
                    if not equality_added:
                        equality_sat = constraint_set_related_satisfiable(
                            [equality_constraint],
                            seed_vars,
                            timeout_ms=max(local_solver_timeout_ms, 1000),
                        )
                        if equality_sat is True:
                            candidate_solver.add(equality_constraint)
                            added_constraint_cache.add(str(claripy.simplify(equality_constraint)))
                            debug_constraint_add("same_address_load_alias_assumed", equality_constraint)
                            equality_added = True
                    if equality_added:
                        register_expr_equality(value_expr, first_value_expr)
                    matched_representative = True
                    break
                if not matched_representative:
                    representatives.append((inst, rd_symbol, addr_symbol, inst_idx))

        def reg_is_source_load_base(reg):
            symbol = reg_to_symbol.get(reg)
            if symbol is None:
                return False
            symbol_vars = expr_vars(symbol)
            return bool(symbol_vars) and any(
                getattr(load_inst, 'rs1', None) == reg
                and (expr_vars(load_addr_symbol) & symbol_vars)
                for load_inst, _, load_addr_symbol, _ in address_source_loads
            )

        def reg_is_additive_offset_to_independent_base(reg):
            symbol = reg_to_symbol.get(reg)
            if symbol is None:
                return False
            symbol_vars = expr_vars(symbol)
            if not symbol_vars:
                return False
            if reg_is_source_load_base(reg):
                return False
            address_uses = [
                addr_symbol
                for _, addr_symbol, _, _ in mem_accesses
                if expr_vars(addr_symbol) & symbol_vars
            ]
            if not address_uses:
                return False

            def has_large_negative_register_residual_field_use():
                other_register_vars = set()
                for other_reg, other_symbol in reg_to_symbol.items():
                    if other_reg == reg:
                        continue
                    other_register_vars.update(expr_vars(other_symbol))
                if not other_register_vars:
                    return False
                for addr_symbol in address_uses:
                    residual = claripy.simplify(addr_symbol - symbol)
                    residual_vars = expr_vars(residual)
                    if residual_vars & symbol_vars:
                        continue
                    residual_affine = affine_base_const(residual)
                    if residual_affine is None:
                        continue
                    residual_base, residual_imm = residual_affine
                    residual_base_vars = expr_vars(residual_base)
                    if residual_base_vars & (address_loaded_addr_vars | pointer_loaded_addr_vars):
                        continue
                    if not (residual_base_vars & other_register_vars):
                        continue
                    if _signed_u64(residual_imm) <= -64:
                        return True
                return False

            if has_large_negative_register_residual_field_use():
                return False

            for addr_symbol in address_uses:
                residual = claripy.simplify(addr_symbol - symbol)
                if expr_vars(residual) & symbol_vars:
                    return False

            pointer_carrier_varsets = []
            seen_carrier_keys = set()
            for load_inst, rd_symbol, _, load_idx in (
                pointer_source_loads + address_source_loads + load_accesses
            ):
                if load_inst.width != 8:
                    continue
                carrier_vars = expr_vars(rd_symbol)
                if not carrier_vars:
                    continue
                carrier_key = (load_idx, expr_key(rd_symbol))
                if carrier_key in seen_carrier_keys:
                    continue
                seen_carrier_keys.add(carrier_key)
                pointer_carrier_varsets.append(carrier_vars)

            def other_has_independent_use(other_vars):
                return any(
                    (expr_vars(other_addr_symbol) & other_vars)
                    and not (expr_vars(other_addr_symbol) & symbol_vars)
                    for _, other_addr_symbol, _, _ in mem_accesses
                )

            return all(
                any(
                    other_reg != reg
                    and (other_vars := expr_vars(other_symbol))
                    and (expr_vars(addr_symbol) & other_vars)
                    and other_has_independent_use(other_vars)
                    for other_reg, other_symbol in reg_to_symbol.items()
                ) or any(
                    expr_vars(addr_symbol) & carrier_vars
                    for carrier_vars in pointer_carrier_varsets
                )
                for addr_symbol in address_uses
            )

        def reg_has_direct_scaled_residual_base_use_for_scalar_zero(reg):
            symbol = reg_to_symbol.get(reg)
            if symbol is None:
                return False
            symbol_vars = expr_vars(symbol)
            if not symbol_vars:
                return False
            scaled_ops = {'__lshift__', 'LShR', 'SShR', '__mul__', 'Mul', 'Concat'}

            def add_terms(node, sign=1, out=None):
                out = [] if out is None else out
                node = claripy.simplify(node)
                op = getattr(node, 'op', None)
                args = [arg for arg in getattr(node, 'args', ()) if hasattr(arg, 'op')]
                if op in {'__add__', 'Add'}:
                    for arg in args:
                        add_terms(arg, sign, out)
                    return out
                if op in {'__sub__', 'Sub'} and args:
                    add_terms(args[0], sign, out)
                    for arg in args[1:]:
                        add_terms(arg, -sign, out)
                    return out
                out.append((sign, node))
                return out

            def has_scaled_term(term):
                return any(
                    getattr(node, 'op', None) in scaled_ops and expr_vars(node)
                    for node in iter_ast_nodes(term)
                )

            for _, addr_symbol, _, _ in mem_accesses:
                if not (expr_vars(addr_symbol) & symbol_vars):
                    continue
                terms = add_terms(addr_symbol)
                has_direct_symbol_term = any(
                    sign > 0 and expr_key(term) == expr_key(symbol)
                    for sign, term in terms
                )
                if not has_direct_symbol_term:
                    continue
                if any(
                    sign > 0
                    and not (expr_vars(term) & symbol_vars)
                    and has_scaled_term(term)
                    for sign, term in terms
                ):
                    return True
            return False

        def add_additive_offset_scalar_zero_constraints():
            for reg, symbol in reg_to_symbol.items():
                if reg_has_direct_scaled_residual_base_use_for_scalar_zero(reg):
                    continue
                if not reg_is_additive_offset_to_independent_base(reg):
                    continue
                if try_add_constraint(symbol == expr_bvv(0, symbol), timeout_ms=local_solver_timeout_ms):
                    residual_scalar_regs.add(reg)

        def add_arithmetic_address_hint_constraints():
            complex_memory_block = len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
            hint_timeout_ms = 50 if complex_memory_block else HEURISTIC_SOLVER_TIMEOUT_MS
            pointer_hint_budget = LONG_BLOCK_ANCHOR_CANDIDATE_LIMIT * 2 if complex_memory_block else None

            def unique_values(values):
                seen = set()
                result = []
                for value in values:
                    value &= ((1 << 64) - 1)
                    if value in seen:
                        continue
                    seen.add(value)
                    result.append(value)
                return result

            def try_add_constraint_group(constraints):
                constraints = list(constraints)
                if not constraints:
                    return True
                test_solver = candidate_solver.branch()
                test_solver.timeout = hint_timeout_ms
                try:
                    for constraint in constraints:
                        test_solver.add(constraint)
                    if not test_solver.satisfiable():
                        return False
                except Exception:
                    return False
                for constraint in constraints:
                    candidate_solver.add(constraint)
                    added_constraint_cache.add(str(claripy.simplify(constraint)))
                return True

            def has_nonlinear_address_use(reg):
                symbol = reg_to_symbol.get(reg)
                if symbol is None:
                    return False
                symbol_vars = expr_vars(symbol)
                if not symbol_vars:
                    return False
                nonlinear_ops = {'__mul__', 'Mul', '__floordiv__', '__truediv__', '__div__', 'SDiv', 'UDiv'}
                for _, addr_symbol, _, _ in mem_accesses:
                    if not (expr_vars(addr_symbol) & symbol_vars):
                        continue
                    for node in iter_ast_nodes(addr_symbol):
                        if getattr(node, 'op', '') in nonlinear_ops and (expr_vars(node) & symbol_vars):
                            return True
                return False

            def has_fixed_residual_mul_carrier_use(reg):
                symbol = reg_to_symbol.get(reg)
                if symbol is None:
                    return False
                symbol_vars = expr_vars(symbol)
                if not symbol_vars:
                    return False
                for _, addr_symbol, _, _ in mem_accesses:
                    if not (expr_vars(addr_symbol) & symbol_vars):
                        continue
                    for mul_node in iter_ast_nodes(addr_symbol):
                        if getattr(mul_node, 'op', None) not in {'__mul__', 'Mul'}:
                            continue
                        if not (expr_vars(mul_node) & symbol_vars):
                            continue
                        residual = sub_same_width(addr_symbol, mul_node)
                        if residual is None:
                            continue
                        if expr_vars(residual) & expr_vars(mul_node):
                            continue
                        residual_value = concrete_expr_value(residual)
                        if residual_value is None:
                            continue
                        if stack_offset_for_value(residual_value) is None:
                            return True
                return False

            def has_scaled_residual_base_use(reg):
                symbol = reg_to_symbol.get(reg)
                if symbol is None:
                    return False
                symbol_vars = expr_vars(symbol)
                if not symbol_vars:
                    return False
                scaled_ops = {'__lshift__', 'LShR', 'SShR', '__mul__', 'Mul', 'Concat'}
                for _, addr_symbol, _, _ in mem_accesses:
                    if not (expr_vars(addr_symbol) & symbol_vars):
                        continue
                    residual = claripy.simplify(addr_symbol - symbol)
                    residual_vars = expr_vars(residual)
                    if residual_vars & symbol_vars:
                        continue
                    if not residual_vars:
                        continue
                    if any(
                        getattr(node, 'op', None) in scaled_ops
                        and (expr_vars(node) & residual_vars)
                        for node in iter_ast_nodes(residual)
                    ):
                        return True
                return False

            fixed_reg_values = {}
            for reg, values in reg_value_hints.items():
                if reg not in reg_to_symbol:
                    continue
                if not has_nonlinear_address_use(reg):
                    continue
                values = unique_values(values)
                if len(values) != 1:
                    continue
                if values[0] == 0 and has_fixed_residual_mul_carrier_use(reg):
                    continue
                if values[0] == 0 and has_scaled_residual_base_use(reg):
                    continue
                fixed_reg_values[reg] = values[0]
                symbol = reg_to_symbol[reg]
                try_add_constraint(symbol == expr_bvv(values[0], symbol), timeout_ms=hint_timeout_ms)

            for pc, values in load_value_hints.items():
                values = unique_values(values)
                if len(values) != 1:
                    continue
                for load_inst, rd_symbol, _, load_idx in load_entries_by_pc.get(pc, []):
                    if values[0] == 0 and is_deferred_loaded_address_scalar(load_inst, rd_symbol, load_idx):
                        continue
                    rd_vars = expr_vars(rd_symbol)
                    used_in_later_addr = bool(rd_vars) and any(
                        access_idx > load_idx and (expr_vars(addr_symbol) & rd_vars)
                        for _, addr_symbol, access_idx, _ in mem_accesses
                    )
                    if (
                        load_inst.width >= 8
                        and used_in_later_addr
                        and (
                            values[0] == 0
                            or (rd_vars & pointer_loaded_addr_vars)
                            or (
                                load_idx,
                                stable_expr_key(rd_symbol),
                            ) in pointer_source_value_keys
                        )
                    ):
                        continue
                    constraint = rd_symbol == expr_bvv(values[0], rd_symbol)
                    try_add_constraint(constraint, timeout_ms=hint_timeout_ms)

            pointer_hints_tried = 0
            for pc, min_offset in load_pointer_hints.items():
                for load_inst, rd_symbol, _, load_idx in load_entries_by_pc.get(pc, []):
                    if pointer_hint_budget is not None and pointer_hints_tried >= pointer_hint_budget:
                        break
                    if load_inst.width != 8:
                        continue
                    if load_value_is_additive_offset_to_live_base(rd_symbol, load_idx):
                        continue
                    rd_vars = expr_vars(rd_symbol)
                    if not rd_vars:
                        continue
                    pointer_hints_tried += 1
                    stack_constraints = stack_pointer_constraints_for_expr(
                        rd_symbol,
                        max(min_offset, min_pointer_offset_for_vars(rd_vars, load_idx)),
                    )
                    if try_add_constraint_group(stack_constraints):
                        hint_pointer_load_keys.add((load_idx, expr_key(rd_symbol)))

            reg_hints_tried = 0
            for reg, min_offset in reg_pointer_hints.items():
                if pointer_hint_budget is not None and reg_hints_tried >= pointer_hint_budget:
                    break
                if reg not in reg_to_symbol:
                    continue
                if reg in fixed_reg_values:
                    continue
                if reg_is_additive_offset_to_independent_base(reg):
                    continue
                symbol = reg_to_symbol[reg]
                stack_constraints = stack_pointer_constraints_for_reg_hint(reg, symbol, min_offset)
                reg_hints_tried += 1
                if try_add_constraint_group(stack_constraints):
                    register_anchor_min_offsets[reg] = max(
                        register_anchor_min_offsets.get(reg, INIT_PTR_MIN_OFFSET),
                        max(INIT_PTR_MIN_OFFSET, min_offset),
                    )

            for pc in load_nonzero_hints:
                for load_inst, rd_symbol, _, _ in load_entries_by_pc.get(pc, []):
                    try_add_constraint(rd_symbol != expr_bvv(0, rd_symbol), timeout_ms=hint_timeout_ms)

            for reg in reg_nonzero_hints:
                if reg not in reg_to_symbol:
                    continue
                symbol = reg_to_symbol[reg]
                try_add_constraint(symbol != expr_bvv(0, symbol), timeout_ms=hint_timeout_ms)

        def add_scalar_zero_address_load_constraints():
            for load_inst, rd_symbol, load_addr_symbol, load_idx in mem_entries:
                if not is_scalar_zero_address_load(load_inst, rd_symbol, load_idx):
                    continue
                if (
                    load_value_is_additive_offset_to_live_base(rd_symbol, load_idx)
                    and load_has_same_slot_update_chain(load_inst, rd_symbol, load_addr_symbol, load_idx)
                ):
                    continue
                commit_scalar_zero_constraint(rd_symbol, timeout_ms=max(local_solver_timeout_ms, 1000))

        def scaled_residual_component_zero_constraints(residual, forbidden_vars=None):
            forbidden_vars = set() if forbidden_vars is None else set(forbidden_vars)
            residual_vars = expr_vars(residual)
            if not residual_vars or residual_vars & forbidden_vars:
                return None
            scaled_ops = {'__lshift__', 'LShR', 'SShR', '__rshift__', 'SignExt', 'ZeroExt', 'Concat'}
            if not any(getattr(node, 'op', None) in scaled_ops for node in iter_ast_nodes(residual)):
                return None
            blocked_vars = set(pointer_loaded_addr_vars) | set(undef_base_vars)
            target_vars = residual_vars - forbidden_vars - blocked_vars
            if not target_vars:
                return None
            constraints = []
            covered_vars = set()

            for reg, symbol in reg_to_symbol.items():
                symbol_vars = expr_vars(symbol)
                if not symbol_vars or not (symbol_vars & target_vars):
                    continue
                if reg not in residual_scalar_regs and reg not in reg_value_hints:
                    continue
                symbol_constraints = constraints_to_constant(
                    symbol,
                    0,
                    forbidden_vars=set(),
                )
                if symbol_constraints is None:
                    symbol_constraints = [symbol == expr_bvv(0, symbol)]
                constraints.extend(symbol_constraints)
                covered_vars.update(symbol_vars & target_vars)

            for load_inst, rd_symbol, _, _ in load_accesses:
                if load_inst.width >= 8:
                    continue
                rd_vars = expr_vars(rd_symbol)
                if not rd_vars or not (rd_vars & target_vars):
                    continue
                load_constraints = constraints_to_constant(
                    rd_symbol,
                    0,
                    forbidden_vars=set(),
                )
                if load_constraints is None:
                    load_constraints = [rd_symbol == expr_bvv(0, rd_symbol)]
                constraints.extend(load_constraints)
                covered_vars.update(rd_vars & target_vars)

            if not constraints or covered_vars != target_vars:
                return None
            sat = constraint_set_related_satisfiable(
                constraints,
                target_vars,
                timeout_ms=max(local_solver_timeout_ms, 1000),
            )
            if sat is False:
                return None
            return constraints

        def load_value_has_direct_pointer_use(rd_symbol, load_idx):
            rd_vars = expr_vars(rd_symbol)
            if not rd_vars:
                return False
            forbidden_residual_vars = rd_vars | (set(pointer_loaded_addr_vars) - rd_vars)

            def simple_additive_residual(expr, depth=0):
                expr = claripy.simplify(expr)
                if depth > 8:
                    return False
                if not expr_vars(expr):
                    return True
                op = getattr(expr, 'op', '')
                if op == 'BVS':
                    return True
                args = [arg for arg in getattr(expr, 'args', ()) if hasattr(arg, 'op')]
                if op in {'__add__', 'Add', '__sub__', 'Sub'}:
                    return all(simple_additive_residual(arg, depth + 1) for arg in args)
                if op in {'SignExt', 'ZeroExt'} and args:
                    return simple_additive_residual(args[-1], depth + 1)
                return False

            for _, addr_symbol, access_idx, _ in mem_accesses:
                if access_idx <= load_idx:
                    continue
                if not (expr_vars(addr_symbol) & rd_vars):
                    continue
                residual = sub_same_width(addr_symbol, rd_symbol)
                if residual is None:
                    continue
                residual_vars = expr_vars(residual)
                if residual_vars & rd_vars:
                    continue
                if concrete_expr_value(residual) is not None:
                    return True
                if residual_vars & forbidden_residual_vars:
                    continue
                if not simple_additive_residual(residual):
                    residual_constraints = constraints_to_constant(
                        residual,
                        0,
                        forbidden_vars=forbidden_residual_vars,
                    )
                    if residual_constraints is not None:
                        residual_sat = constraint_set_related_satisfiable(
                            list(residual_constraints),
                            rd_vars | residual_vars,
                            timeout_ms=max(local_solver_timeout_ms, 1000),
                        )
                        if residual_sat is not False:
                            return True
                    continue
                for target in (0, 4, 8, 12, 16, -4, -8, -12, -16, 20, 24, 32):
                    residual_constraints = constraints_to_constant(
                        residual,
                        target,
                        forbidden_vars=forbidden_residual_vars,
                    )
                    if residual_constraints is not None:
                        return True
            return False

        def load_value_has_direct_store_addr_use(rd_symbol, load_idx):
            rd_vars = expr_vars(rd_symbol)
            if not rd_vars:
                return False
            forbidden_residual_vars = rd_vars | (set(pointer_loaded_addr_vars) - rd_vars)
            for _, store_addr_symbol, store_idx, _, _ in store_accesses:
                if store_idx <= load_idx:
                    continue
                if not (expr_vars(store_addr_symbol) & rd_vars):
                    continue
                residual = sub_same_width(store_addr_symbol, rd_symbol)
                if residual is None:
                    continue
                residual_vars = expr_vars(residual)
                if residual_vars & rd_vars:
                    continue
                if concrete_expr_value(residual) is not None:
                    return True
                if residual_vars & forbidden_residual_vars:
                    continue
                zero_residual_constraints = multiplicative_zero_residual_constraints(
                    residual,
                    forbidden_vars=forbidden_residual_vars,
                    direct_pointer_guard=True,
                    timeout_ms=100 if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD else 1000,
                )
                if zero_residual_constraints is not None:
                    zero_sat = constraint_set_related_satisfiable(
                        list(zero_residual_constraints),
                        rd_vars | residual_vars,
                        timeout_ms=100 if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD else 1000,
                    )
                    if zero_sat is not False:
                        return True
                for target in (0, 4, 8, 12, 16, -4, -8, -12, -16, 20, 24, 32):
                    residual_constraints = constraints_to_constant(
                        residual,
                        target,
                        forbidden_vars=forbidden_residual_vars,
                    )
                    if residual_constraints is not None:
                        return True
            return False

        def expr_has_direct_pointer_use(expr):
            value_vars = expr_vars(expr)
            if not value_vars:
                return False
            for _load_inst, rd_symbol, _, load_idx in load_accesses:
                rd_vars = expr_vars(rd_symbol)
                if not rd_vars or not (value_vars & rd_vars):
                    continue
                if load_value_has_direct_pointer_use(rd_symbol, load_idx):
                    return True
            return False

        def multiplicative_zero_residual_constraint_options(
            residual,
            forbidden_vars=None,
            direct_pointer_guard=True,
            timeout_ms=None,
        ):
            forbidden_vars = set() if forbidden_vars is None else set(forbidden_vars)
            timeout_ms = local_solver_timeout_ms if timeout_ms is None else timeout_ms
            debug_mul_zero = (
                os.environ.get("RVMCA_DEBUG_POINTER_VALUE") == "1"
                or os.environ.get("RVMCA_DEBUG_LOAD_SLOTS") == "1"
            )

            def debug_zero_option(event, **fields):
                if debug_mul_zero:
                    fields.setdefault('residual', str(residual))
                    DEBUG(f"mul_zero_residual_{event} {fields}")

            zero_candidates = []
            for mul_node in iter_ast_nodes(residual):
                if getattr(mul_node, 'op', None) not in {'__mul__', 'Mul'}:
                    continue
                for operand in getattr(mul_node, 'args', ()):
                    if not hasattr(operand, 'op'):
                        continue
                    operand_vars = expr_vars(operand)
                    if not operand_vars or (operand_vars & forbidden_vars):
                        if operand_vars & forbidden_vars:
                            debug_zero_option(
                                "reject_forbidden",
                                operand=str(operand),
                                vars=sorted(operand_vars & forbidden_vars),
                            )
                        continue
                    if direct_pointer_guard and expr_has_direct_pointer_use(operand):
                        debug_zero_option(
                            "reject_direct_pointer_use",
                            operand=str(operand),
                            vars=sorted(operand_vars),
                        )
                        continue
                    operand_constraints = constraints_to_constant(
                        operand,
                        0,
                        forbidden_vars=forbidden_vars,
                    )
                    if operand_constraints is None:
                        debug_zero_option(
                            "reject_no_constraints",
                            operand=str(operand),
                            vars=sorted(operand_vars),
                        )
                        continue
                    zero_candidates.append((operand, list(operand_constraints)))

            zero_candidates.sort(
                key=lambda item: multiplicative_zero_priority(item[0], item[1])
            )
            options = []
            seen = set()
            for operand, operand_constraints in zero_candidates:
                option_key = tuple(
                    str(claripy.simplify(constraint))
                    for constraint in operand_constraints
                )
                if option_key in seen:
                    continue
                seen.add(option_key)
                sat = constraint_set_selection_satisfiable(
                    operand_constraints,
                    timeout_ms=timeout_ms,
                )
                if sat is False:
                    sat = constraint_set_related_satisfiable(
                        operand_constraints,
                        expr_vars(operand),
                        timeout_ms=max(timeout_ms, 1000),
                    )
                if sat is False:
                    debug_zero_option(
                        "reject_unsat",
                        operand=str(operand),
                        constraints=[str(c) for c in operand_constraints],
                    )
                    continue
                debug_zero_option(
                    "candidate",
                    operand=str(operand),
                    constraints=[str(c) for c in operand_constraints],
                    sat=sat,
                )
                options.append((operand, operand_constraints, sat))
            return options

        def multiplicative_zero_residual_constraints(
            residual,
            forbidden_vars=None,
            direct_pointer_guard=True,
            timeout_ms=None,
        ):
            options = multiplicative_zero_residual_constraint_options(
                residual,
                forbidden_vars=forbidden_vars,
                direct_pointer_guard=direct_pointer_guard,
                timeout_ms=timeout_ms,
            )
            return None if not options else options[0][1]

        def stack_pointer_constraints_for_reg_hint(reg, symbol, min_offset=INIT_PTR_MIN_OFFSET):
            symbol_vars = expr_vars(symbol)
            if symbol_vars:
                direct_accesses = []
                for access_inst, addr_symbol, _, access_width in mem_accesses:
                    if getattr(access_inst, 'rs1', None) != reg:
                        continue
                    if not (expr_vars(addr_symbol) & symbol_vars):
                        continue
                    residual = claripy.simplify(addr_symbol - symbol)
                    if expr_vars(residual) & symbol_vars:
                        continue
                    residual_value = concrete_expr_value(residual)
                    if residual_value is None:
                        continue
                    direct_accesses.append((
                        access_width,
                        _signed_u64(residual_value),
                    ))
                if direct_accesses:
                    access_width, residual_imm = max(
                        direct_accesses,
                        key=lambda item: (
                            item[0],
                            item[1] if item[1] >= 0 else 0,
                        ),
                    )
                    required_offset = max(min_offset, INIT_PTR_MIN_OFFSET, access_width)
                    if residual_imm >= 0:
                        required_offset = max(required_offset, residual_imm + access_width)
                    return stack_pointer_constraints_for_access_base(
                        symbol,
                        required_offset,
                        access_width,
                        residual_imm,
                    )
            return stack_pointer_constraints_for_expr(symbol, min_offset)

        def add_store_pointer_source_constraints():
            source_loads = []
            seen_source_loads = set()
            for load_inst, rd_symbol, load_addr_symbol, load_idx in pointer_source_loads:
                key = (load_idx, expr_key(rd_symbol), expr_key(load_addr_symbol))
                seen_source_loads.add(key)
                source_loads.append((load_inst, rd_symbol, load_addr_symbol, load_idx))
            for load_inst, rd_symbol, load_addr_symbol, load_idx in address_source_loads:
                key = (load_idx, expr_key(rd_symbol), expr_key(load_addr_symbol))
                if key in seen_source_loads:
                    continue
                if load_inst.width != 8:
                    continue
                if not load_value_has_direct_pointer_use(rd_symbol, load_idx):
                    continue
                seen_source_loads.add(key)
                source_loads.append((load_inst, rd_symbol, load_addr_symbol, load_idx))

            for load_inst, rd_symbol, load_addr_symbol, load_idx in source_loads:
                if (load_idx, expr_key(rd_symbol)) in scalar_load_hint_keys:
                    continue
                prior_store = prior_same_addr_store(load_addr_symbol, load_idx)
                if prior_store is None:
                    continue
                _, _, _, store_width, store_data_symbol = prior_store
                stored_expr = stored_value_for_load(store_data_symbol, store_width, load_inst)
                if stored_expr is not None:
                    stored_vars = expr_vars(stored_expr)
                    load_min_offset = min_pointer_offset_for_vars(expr_vars(rd_symbol), load_idx)
                    carrier_added = False
                    if stored_vars:
                        carrier_candidates = []
                        for carrier_inst, carrier_rd_symbol, _, carrier_idx in load_accesses:
                            if carrier_idx >= load_idx or carrier_inst.width != 8:
                                continue
                            carrier_vars = expr_vars(carrier_rd_symbol)
                            if not carrier_vars or not (stored_vars & carrier_vars):
                                continue
                            carrier_constraints = constraints_to_carrier(stored_expr, carrier_rd_symbol)
                            if carrier_constraints is None:
                                continue
                            carrier_candidates.append((
                                carrier_idx,
                                carrier_rd_symbol,
                                carrier_vars,
                                carrier_constraints,
                            ))
                        carrier_candidates.sort(key=lambda item: item[0], reverse=True)
                        for carrier_idx, carrier_rd_symbol, _, carrier_constraints in carrier_candidates:
                            constraints = list(carrier_constraints)
                            constraints.extend(
                                stack_pointer_constraints_for_expr(
                                    carrier_rd_symbol,
                                    load_min_offset,
                                )
                            )
                            if try_add_constraint_set(constraints):
                                hint_pointer_load_keys.add((carrier_idx, expr_key(carrier_rd_symbol)))
                                carrier_added = True
                                break
                    if carrier_added:
                        continue

                    constraints = []
                    if stored_vars:
                        constraints.extend(
                            stack_pointer_constraints_for_expr(
                                stored_expr,
                                load_min_offset,
                            )
                        )
                    try_add_constraint_set(constraints)

        def add_loaded_pointer_scalar_offset_constraints():
            for reg, symbol in reg_to_symbol.items():
                symbol_vars = expr_vars(symbol)
                if not symbol_vars:
                    continue
                if reg_has_direct_scaled_residual_base_use_for_scalar_zero(reg):
                    continue
                has_direct_livein_base_use = any(
                    getattr(inst, 'rs1', None) == reg
                    and (expr_vars(addr_symbol) & symbol_vars)
                    for inst, addr_symbol, _, _ in mem_accesses
                )
                if has_direct_livein_base_use:
                    continue
                for load_inst, rd_symbol, _, load_idx in load_accesses:
                    if load_inst.width != 8:
                        continue
                    rd_vars = expr_vars(rd_symbol)
                    if not rd_vars:
                        continue
                    for _, addr_symbol, access_idx, access_width in mem_accesses:
                        if access_idx <= load_idx:
                            continue
                        addr_vars = expr_vars(addr_symbol)
                        if not (addr_vars & symbol_vars) or not (addr_vars & rd_vars):
                            continue
                        if (addr_vars & pointer_loaded_addr_vars) and not (rd_vars & pointer_loaded_addr_vars):
                            continue
                        residual = additive_residual_without_term(addr_symbol, rd_symbol)
                        if residual is None:
                            residual = claripy.simplify(addr_symbol - rd_symbol)
                        residual_vars = expr_vars(residual)
                        unscaled_livein_residual_feeds_store = (
                            len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
                            and load_inst.width == 8
                            and access_width == 8
                            and bool(residual_vars)
                            and not (residual_vars & rd_vars)
                            and residual_vars <= symbol_vars
                            and not any(
                                getattr(node, 'op', None) in {
                                    '__lshift__',
                                    'LShR',
                                    'SShR',
                                    '__mul__',
                                    'Mul',
                                    'Concat',
                                }
                                and expr_vars(node)
                                for node in iter_ast_nodes(residual)
                            )
                            and (
                                load_value_has_direct_pointer_use(rd_symbol, load_idx)
                                or load_value_has_direct_store_addr_use(rd_symbol, load_idx)
                            )
                        )
                        if unscaled_livein_residual_feeds_store:
                            continue
                        if not (residual_vars & rd_vars) and (residual_vars & symbol_vars):
                            residual_affine = affine_base_const(residual)
                            if residual_affine is not None:
                                residual_base, residual_imm = residual_affine
                                if (
                                    abs(_signed_u64(residual_imm)) > 64
                                    and (expr_vars(residual_base) & symbol_vars)
                                ):
                                    continue
                        residual_constraints = constraints_to_carrier(addr_symbol, rd_symbol)
                        component_zero_constraints = scaled_residual_component_zero_constraints(
                            residual,
                            forbidden_vars=rd_vars,
                        )
                        if (
                            residual_constraints is not None
                            and component_zero_constraints is not None
                        ):
                            residual_constraints = component_zero_constraints
                        if residual_constraints is None:
                            if (residual_vars & rd_vars) or not (residual_vars & symbol_vars):
                                continue
                            residual_constraints = constraints_to_constant(
                                residual,
                                0,
                                forbidden_vars=rd_vars,
                            )
                            if (
                                component_zero_constraints is not None
                                and (
                                    residual_constraints is None
                                    or len(component_zero_constraints) < len(residual_constraints)
                                )
                            ):
                                residual_constraints = component_zero_constraints
                            if residual_constraints is None:
                                continue
                        if not any(expr_vars(constraint) & symbol_vars for constraint in residual_constraints):
                            continue
                        stack_constraints = stack_pointer_constraints_for_access_base(
                            rd_symbol,
                            min_pointer_offset_for_vars(rd_vars, load_idx),
                            access_width,
                            0,
                        )
                        residual_constraints = list(residual_constraints)
                        if try_add_constraint_set(residual_constraints + stack_constraints):
                            break
                        residual_vars_for_add = set()
                        for constraint in residual_constraints:
                            residual_vars_for_add.update(getattr(constraint, 'variables', set()))
                        residual_added = (
                            try_add_constraint_set_fast(
                                residual_constraints,
                                timeout_ms=max(local_solver_timeout_ms, 1000),
                            )
                            or try_add_constraint_set_related(
                                residual_constraints,
                                residual_vars_for_add | symbol_vars,
                                timeout_ms=max(local_solver_timeout_ms, 1000),
                            )
                        )
                        if (
                            not residual_added
                            and len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
                            and len(residual_constraints) <= 2
                            and all(ast_node_count(constraint) <= 48 for constraint in residual_constraints)
                        ):
                            residual_sat = constraint_set_related_satisfiable(
                                residual_constraints,
                                residual_vars_for_add | symbol_vars,
                                timeout_ms=max(local_solver_timeout_ms, 1000),
                            )
                            if residual_sat is not False:
                                for constraint in residual_constraints:
                                    candidate_solver.add(constraint)
                                    added_constraint_cache.add(str(claripy.simplify(constraint)))
                                    debug_constraint_add("loaded_pointer_scalar_assumed", constraint)
                                residual_added = True
                        if residual_added:
                            try_add_constraint_set(stack_constraints)
                            break

        def add_loaded_pointer_residual_anchor_constraints():
            small_targets = [0, 4, 8, 16, -4, -8]
            long_anchor_block = len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
            anchor_attempts = 0
            anchor_attempt_limit = 64 if long_anchor_block else None
            related_access_limit = 8 if long_anchor_block else None
            register_value_vars = set()
            for symbol in reg_to_symbol.values():
                register_value_vars.update(expr_vars(symbol))
            store_required_pointer_vars = set()
            for required_vars in store_pointer_required_varsets:
                store_required_pointer_vars.update(required_vars)

            def try_add_anchor_constraints(constraints, seed_vars):
                nonlocal anchor_attempts
                if anchor_attempt_limit is not None:
                    if anchor_attempts >= anchor_attempt_limit:
                        return False
                    anchor_attempts += 1
                    return (
                        try_add_constraint_set_fast(
                            constraints,
                            timeout_ms=100,
                        )
                        or try_add_constraint_set_related(
                            constraints,
                            seed_vars,
                            timeout_ms=100,
                        )
                    )
                return try_add_constraint_set(constraints)

            def residual_constraint_options(residual, target, forbidden_vars):
                options = []
                seen_options = set()

                def add_option(constraints):
                    if constraints is None:
                        return
                    constraints = list(constraints)
                    option_key = tuple(
                        str(claripy.simplify(constraint))
                        for constraint in constraints
                    )
                    if option_key in seen_options:
                        return
                    seen_options.add(option_key)
                    options.append(constraints)

                if target == 0:
                    for _, zero_constraints, _ in multiplicative_zero_residual_constraint_options(
                        residual,
                        forbidden_vars=forbidden_vars,
                        direct_pointer_guard=True,
                        timeout_ms=100 if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD else local_solver_timeout_ms,
                    ):
                        add_option(zero_constraints)
                    add_option(
                        scaled_residual_component_zero_constraints(
                            residual,
                            forbidden_vars=forbidden_vars,
                        )
                    )

                add_option(
                    constraints_to_constant(
                        residual,
                        target,
                        forbidden_vars=forbidden_vars,
                    )
                )
                return options

            for load_inst, rd_symbol, _, load_idx in load_accesses:
                if load_inst.width != 8:
                    continue
                if (
                    (load_idx, stable_expr_key(rd_symbol)) not in pointer_source_value_keys
                    and load_inst.pc not in load_pointer_hints
                ):
                    continue
                rd_vars = expr_vars(rd_symbol)
                if not rd_vars:
                    continue
                if load_value_is_additive_offset_to_live_base(rd_symbol, load_idx):
                    continue
                related_accesses_seen = 0
                for _, addr_symbol, access_idx, width in mem_accesses:
                    if access_idx <= load_idx:
                        continue
                    if not (expr_vars(addr_symbol) & rd_vars):
                        continue
                    if (
                        related_access_limit is not None
                        and related_accesses_seen >= related_access_limit
                    ):
                        break
                    related_accesses_seen += 1
                    residual = claripy.simplify(addr_symbol - rd_symbol)
                    residual_vars = expr_vars(residual)
                    if residual_vars & rd_vars:
                        continue
                    if residual_vars & store_required_pointer_vars:
                        continue
                    residual_affine = affine_base_const(residual)
                    if residual_affine is not None:
                        residual_base, residual_imm = residual_affine
                        residual_base_vars = expr_vars(residual_base)
                        if (
                            abs(_signed_u64(residual_imm)) > 64
                            and (
                                residual_base_vars
                                & (address_loaded_addr_vars | register_value_vars)
                            )
                        ):
                            continue
                    if not residual_vars:
                        residual_value = concrete_expr_value(residual)
                        if residual_value is None:
                            continue
                        imm = _signed_u64(residual_value)
                        min_offset = max(min_pointer_offset_for_vars(rd_vars, load_idx), width)
                        if imm >= 0:
                            min_offset = max(min_offset, imm + width)
                        stack_constraints = stack_pointer_constraints_for_access_base(
                            rd_symbol,
                            min_offset,
                            width,
                            imm,
                        )
                        if try_add_anchor_constraints(stack_constraints, rd_vars):
                            hint_pointer_load_keys.add((load_idx, expr_key(rd_symbol)))
                        continue
                    target_candidates = list(small_targets)
                    if (
                        len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
                        and width == 8
                        and vars_belong_to_single_register(residual_vars)
                        and not any(
                            getattr(node, 'op', None) in {
                                '__lshift__',
                                'LShR',
                                'SShR',
                                '__mul__',
                                'Mul',
                                'Concat',
                            }
                            and expr_vars(node)
                            for node in iter_ast_nodes(residual)
                        )
                        and (
                            load_value_has_direct_pointer_use(rd_symbol, load_idx)
                            or load_value_has_direct_store_addr_use(rd_symbol, load_idx)
                        )
                    ):
                        target_candidates = [8, 16, 4, 0, -4, -8]
                    for target in target_candidates:
                        target_added = False
                        for residual_constraints in residual_constraint_options(
                            residual,
                            target,
                            rd_vars,
                        ):
                            min_offset = max(min_pointer_offset_for_vars(rd_vars, load_idx), width)
                            if target >= 0:
                                min_offset = max(min_offset, target + width)
                            stack_constraints = stack_pointer_constraints_for_access_base(
                                rd_symbol,
                                min_offset,
                                width,
                                target,
                            )
                            # Heuristic residual reducers can be intentionally partial
                            # (for example zeroing one multiplicative term).  Keep the
                            # real residual target in the accepted constraint set so a
                            # partial reducer cannot anchor a pointer to an address that
                            # the later load-slot materializer can never realize.
                            target_constraint = residual == expr_bvv(target, residual)
                            anchor_constraints = (
                                list(residual_constraints)
                                + [target_constraint]
                                + stack_constraints
                            )
                            anchor_seed_vars = rd_vars | residual_vars
                            if try_add_anchor_constraints(anchor_constraints, anchor_seed_vars):
                                hint_pointer_load_keys.add((load_idx, expr_key(rd_symbol)))
                                for reg, symbol in reg_to_symbol.items():
                                    symbol_vars = expr_vars(symbol)
                                    if symbol_vars and (residual_vars & symbol_vars):
                                        residual_scalar_regs.add(reg)
                                target_added = True
                                break
                        if target_added:
                            break

        def add_livein_base_residual_anchor_constraints():
            small_targets = [0, 4, 8, 16]
            register_vars_by_reg = {
                reg: expr_vars(symbol)
                for reg, symbol in reg_to_symbol.items()
            }
            source_load_base_vars = set()
            for source_reg, source_vars in register_vars_by_reg.items():
                if reg_is_source_load_base(source_reg):
                    source_load_base_vars.update(source_vars)
            for reg, symbol in reg_to_symbol.items():
                if reg_is_additive_offset_to_independent_base(reg):
                    continue
                symbol_vars = expr_vars(symbol)
                if not symbol_vars:
                    continue
                for _, addr_symbol, _, width in mem_accesses:
                    if not (expr_vars(addr_symbol) & symbol_vars):
                        continue
                    residual = claripy.simplify(addr_symbol - symbol)
                    residual_vars = expr_vars(residual)
                    if not residual_vars or (residual_vars & symbol_vars):
                        continue
                    if residual_vars & source_load_base_vars:
                        continue
                    target_candidates = list(small_targets)
                    residual_affine = affine_base_const(residual)
                    if residual_affine is not None:
                        residual_base, residual_imm = residual_affine
                        residual_base_vars = expr_vars(residual_base)
                        if (
                            abs(_signed_u64(residual_imm)) > 64
                            and (residual_base_vars & (address_loaded_addr_vars | pointer_loaded_addr_vars))
                        ):
                            continue
                        if residual_imm not in target_candidates:
                            target_candidates.insert(0, residual_imm)
                    for target in target_candidates:
                        residual_constraints = constraints_to_constant(
                            residual,
                            target,
                            forbidden_vars=symbol_vars,
                        )
                        if residual_constraints is None:
                            continue
                        min_offset = max(INIT_PTR_MIN_OFFSET, width)
                        if target >= 0:
                            min_offset = max(min_offset, target + width)
                        min_offset = _align_up(min_offset, INIT_ACCESS_ALIGN)
                        stack_constraints = stack_pointer_constraints_for_expr(symbol, min_offset)
                        if try_add_constraint_set(list(residual_constraints) + stack_constraints):
                            register_anchor_min_offsets[reg] = max(
                                register_anchor_min_offsets.get(reg, INIT_PTR_MIN_OFFSET),
                                min_offset,
                            )
                            for other_reg, other_symbol in reg_to_symbol.items():
                                if other_reg == reg:
                                    continue
                                other_vars = expr_vars(other_symbol)
                                if other_vars and (residual_vars & other_vars):
                                    residual_scalar_regs.add(other_reg)
                            break
                    if reg in register_anchor_min_offsets:
                        break

        def add_mul_address_carrier_constraints():
            mul_ops = {'__mul__', 'Mul'}

            def has_singleton_zero_hint(reg):
                values = {
                    value & ((1 << 64) - 1)
                    for value in reg_value_hints.get(reg, [])
                }
                return values == {0}

            for _, addr_symbol, _, width in mem_accesses:
                addr_vars = expr_vars(addr_symbol)
                if not addr_vars:
                    continue
                for mul_node in iter_ast_nodes(addr_symbol):
                    if getattr(mul_node, 'op', None) not in mul_ops:
                        continue
                    residual = sub_same_width(addr_symbol, mul_node)
                    if residual is None:
                        continue
                    mul_args = [
                        arg for arg in getattr(mul_node, 'args', ())
                        if hasattr(arg, 'op')
                    ]
                    if len(mul_args) < 2:
                        continue
                    if expr_vars(residual) & expr_vars(mul_node):
                        continue
                    residual_livein_base_vars = set()
                    for _, other_symbol in reg_to_symbol.items():
                        other_vars = expr_vars(other_symbol)
                        if other_vars and (expr_vars(residual) & other_vars):
                            residual_livein_base_vars.update(other_vars)
                    if residual_livein_base_vars:
                        continue
                    residual_value = concrete_expr_value(residual)
                    if residual_value is None:
                        continue
                    residual_imm = _signed_u64(residual_value)

                    carrier_candidates = []
                    for reg, symbol in reg_to_symbol.items():
                        symbol_vars = expr_vars(symbol)
                        if not symbol_vars or not (addr_vars & symbol_vars):
                            continue
                        for carrier_arg in mul_args:
                            if not (expr_vars(carrier_arg) & symbol_vars):
                                continue
                            carrier_constraints = constraints_to_carrier(carrier_arg, symbol)
                            if carrier_constraints is None:
                                continue
                            other_constraints = []
                            valid = True
                            for other_arg in mul_args:
                                if other_arg is carrier_arg:
                                    continue
                                if not expr_vars(other_arg):
                                    other_value = concrete_expr_value(other_arg)
                                    if other_value is None or other_value != 1:
                                        valid = False
                                        break
                                    continue
                                sub_constraints = constraints_to_constant(
                                    other_arg,
                                    1,
                                    forbidden_vars=symbol_vars,
                                )
                                if sub_constraints is None:
                                    valid = False
                                    break
                                other_constraints.extend(sub_constraints)
                            if not valid:
                                continue
                            carrier_candidates.append((
                                has_singleton_zero_hint(reg),
                                reg.id,
                                reg,
                                symbol,
                                symbol_vars,
                                list(carrier_constraints) + other_constraints,
                            ))
                            break

                    carrier_candidates.sort(key=lambda item: (item[0], item[1]))
                    for _, _, reg, symbol, symbol_vars, constraints in carrier_candidates:
                        min_offset = max(INIT_PTR_MIN_OFFSET, width)
                        if residual_imm >= 0:
                            min_offset = max(min_offset, residual_imm + width)
                        min_offset = _align_up(min_offset, INIT_ACCESS_ALIGN)
                        stack_constraints = stack_pointer_constraints_for_expr(symbol, min_offset)
                        if not try_add_constraint_set(list(constraints) + stack_constraints):
                            continue
                        register_anchor_min_offsets[reg] = max(
                            register_anchor_min_offsets.get(reg, INIT_PTR_MIN_OFFSET),
                            min_offset,
                        )
                        for other_reg, other_symbol in reg_to_symbol.items():
                            if other_reg == reg:
                                continue
                            other_vars = expr_vars(other_symbol)
                            if other_vars and (expr_vars(mul_node) & other_vars):
                                residual_scalar_regs.add(other_reg)
                        break

        def add_scaled_loaded_address_range_constraints():
            for load_inst, rd_symbol, _, load_idx in address_source_loads:
                if load_inst.width != 8:
                    continue
                if (load_idx, stable_expr_key(rd_symbol)) in pointer_source_value_keys:
                    continue
                if not has_scaled_address_use(rd_symbol, min_access_idx=load_idx):
                    continue
                rd_vars = expr_vars(rd_symbol)
                if not rd_vars:
                    continue
                constraints = []
                for _, addr_symbol, access_idx, access_width in mem_accesses:
                    if access_idx <= load_idx:
                        continue
                    if not (expr_vars(addr_symbol) & rd_vars):
                        continue
                    offset_expr = init_sp - addr_symbol
                    constraints.extend([
                        claripy.UGT(offset_expr, claripy.BVV(0, 64)),
                        claripy.ULE(offset_expr, claripy.BVV(STACK_RANGE, 64)),
                        claripy.ULT(addr_symbol, init_sp),
                    ])
                    if access_width > 1:
                        constraints.append((addr_symbol & (access_width - 1)) == 0)
                if constraints:
                    try_add_constraint_set_related(
                        constraints,
                        rd_vars,
                        timeout_ms=1000,
                    )

        def add_loaded_address_scalar_zero_constraints():
            def has_scaled_loaded_address_use(symbol_vars):
                for _, addr_symbol, _, _ in mem_accesses:
                    addr_vars = expr_vars(addr_symbol)
                    if not (addr_vars & symbol_vars) or not (addr_vars & address_loaded_addr_vars):
                        continue
                    for node in iter_ast_nodes(addr_symbol):
                        if (
                            getattr(node, 'op', None) in {'__lshift__', 'LShR', 'SShR', '__mul__', 'Mul'}
                            and (expr_vars(node) & symbol_vars)
                        ):
                            return True
                return False

            def has_loaded_scaled_residual_base_use(symbol, symbol_vars):
                scaled_ops = {'__lshift__', 'LShR', 'SShR', '__mul__', 'Mul', 'Concat'}
                loaded_value_vars = (
                    set(address_loaded_addr_vars)
                    | set(pointer_loaded_addr_vars)
                )
                for _, addr_symbol, _, _ in mem_accesses:
                    addr_vars = expr_vars(addr_symbol)
                    if not (addr_vars & symbol_vars):
                        continue
                    residual = claripy.simplify(addr_symbol - symbol)
                    residual_vars = expr_vars(residual)
                    if not residual_vars or (residual_vars & symbol_vars):
                        continue
                    if not (residual_vars & loaded_value_vars):
                        continue
                    if any(
                        getattr(node, 'op', None) in scaled_ops
                        and (expr_vars(node) & loaded_value_vars)
                        for node in iter_ast_nodes(residual)
                    ):
                        return True
                return False

            for reg, symbol in reg_to_symbol.items():
                symbol_vars = expr_vars(symbol)
                if not symbol_vars:
                    continue
                if (
                    reg_has_direct_scaled_residual_base_use_for_scalar_zero(reg)
                    or has_loaded_scaled_residual_base_use(symbol, symbol_vars)
                ):
                    continue
                has_direct_livein_base_use = any(
                    getattr(inst, 'rs1', None) == reg
                    and (expr_vars(addr_symbol) & symbol_vars)
                    for inst, addr_symbol, _, _ in mem_accesses
                )
                if has_direct_livein_base_use:
                    continue
                has_loaded_address_use = any(
                    (expr_vars(addr_symbol) & symbol_vars)
                    and (expr_vars(addr_symbol) & address_loaded_addr_vars)
                    for _, addr_symbol, _, _ in mem_accesses
                )
                if has_loaded_address_use:
                    if has_scaled_loaded_address_use(symbol_vars):
                        continue
                    try_add_constraint(symbol == expr_bvv(0, symbol))

        def add_direct_loaded_pointer_stack_constraints():
            for load_inst, rd_symbol, _, load_idx in address_source_loads:
                if load_inst.width != 8:
                    continue
                if (load_idx, expr_key(rd_symbol)) in scalar_load_hint_keys:
                    continue
                rd_vars = expr_vars(rd_symbol)
                if not rd_vars:
                    continue
                min_offset = None
                for access_inst, addr_symbol, access_idx, access_width in mem_accesses:
                    if access_idx <= load_idx:
                        continue
                    if not (expr_vars(addr_symbol) & rd_vars):
                        continue
                    residual = claripy.simplify(addr_symbol - rd_symbol)
                    if expr_vars(residual) & rd_vars:
                        continue
                    residual_value = concrete_expr_value(residual)
                    if residual_value is None:
                        continue
                    imm = _signed_u64(residual_value)
                    required_offset = max(INIT_PTR_MIN_OFFSET, access_width)
                    if imm >= 0:
                        required_offset = max(required_offset, imm + access_width)
                    min_offset = required_offset if min_offset is None else max(min_offset, required_offset)
                if min_offset is None:
                    continue
                try_add_constraint_set(
                    stack_pointer_constraints_for_expr(
                        rd_symbol,
                        _align_up(min_offset, INIT_ACCESS_ALIGN),
                    )
                )

        def add_livein_loaded_offset_base_constraints():
            complex_memory_block = len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
            attempt_budget = (
                LONG_BLOCK_ANCHOR_CANDIDATE_LIMIT * 4
                if complex_memory_block
                else None
            )
            attempts = 0
            for reg, symbol in reg_to_symbol.items():
                symbol_vars = expr_vars(symbol)
                if not symbol_vars:
                    continue
                has_direct_livein_base_use = any(
                    getattr(inst, 'rs1', None) == reg
                    and (expr_vars(addr_symbol) & symbol_vars)
                    for inst, addr_symbol, _, _ in mem_accesses
                )
                if has_direct_livein_base_use:
                    continue
                for access_inst, addr_symbol, _, access_width in mem_accesses:
                    addr_vars = expr_vars(addr_symbol)
                    if not (addr_vars & symbol_vars):
                        continue
                    if not (addr_vars & address_loaded_addr_vars):
                        continue
                    residual = claripy.simplify(addr_symbol - symbol)
                    residual_vars = expr_vars(residual)
                    if residual_vars & symbol_vars:
                        continue
                    if not (residual_vars & address_loaded_addr_vars):
                        continue
                    direct_additive_base_residual = additive_residual_without_term(
                        addr_symbol,
                        symbol,
                    )
                    direct_additive_base = (
                        bool(symbol_vars & undef_base_vars)
                        and direct_additive_base_residual is not None
                        and not (expr_vars(direct_additive_base_residual) & symbol_vars)
                    )
                    if complex_memory_block and direct_additive_base:
                        continue
                    if complex_memory_block:
                        zero_constraint = symbol == expr_bvv(0, symbol)
                        if (
                            try_add_constraint(zero_constraint, timeout_ms=local_solver_timeout_ms)
                            or try_add_constraint_set_related(
                                [zero_constraint],
                                symbol_vars,
                                timeout_ms=250,
                            )
                        ):
                            break
                        continue
                    if (
                        complex_memory_block
                        and (
                            ast_node_count(addr_symbol) > 96
                            or ast_node_count(residual) > 48
                        )
                    ):
                        continue
                    residual_affine = affine_base_const(residual)
                    if residual_affine is not None:
                        residual_base, residual_imm = residual_affine
                        residual_base_vars = expr_vars(residual_base)
                        if (
                            abs(_signed_u64(residual_imm)) > 64
                            and (
                                residual_base_vars
                                & (address_loaded_addr_vars | pointer_loaded_addr_vars)
                            )
                        ):
                            residual_scalar_regs.add(reg)
                            continue
                    residual_constraints = constraints_to_constant(
                        residual,
                        0,
                        forbidden_vars=symbol_vars,
                    )
                    if residual_constraints is None:
                        continue
                    if complex_memory_block and len(residual_constraints) > 2:
                        continue
                    min_offset = _align_up(max(INIT_PTR_MIN_OFFSET, access_width), INIT_ACCESS_ALIGN)
                    constraints = stack_pointer_constraints_for_expr(symbol, min_offset)
                    constraints.extend(residual_constraints)
                    if complex_memory_block:
                        if attempts >= attempt_budget:
                            return
                        attempts += 1
                        added = (
                            try_add_constraint_set_fast(constraints, timeout_ms=50)
                            or try_add_constraint_set_related(
                                constraints,
                                symbol_vars | residual_vars,
                                timeout_ms=250,
                            )
                        )
                    else:
                        added = try_add_constraint_set(constraints)
                    if added:
                        register_anchor_min_offsets[reg] = max(
                            register_anchor_min_offsets.get(reg, INIT_PTR_MIN_OFFSET),
                            min_offset,
                        )
                        break

        def add_risky_source_no_overlap_constraints():
            if len(store_accesses) >= GLOBAL_NO_OVERLAP_STORE_THRESHOLD:
                return
            if not address_narrow_source_loads:
                return
            complex_memory_block = len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
            if len(mem_entries) >= LOAD_SLOT_PRUNE_THRESHOLD:
                pair_budget = LONG_BLOCK_ANCHOR_CANDIDATE_LIMIT * 4
            elif complex_memory_block:
                pair_budget = LONG_BLOCK_ANCHOR_CANDIDATE_LIMIT * 8
            else:
                pair_budget = None
            pointer_like_sources = []
            seen_pointer_like_sources = set()
            source_entries = list(pointer_source_loads)
            if not complex_memory_block:
                source_entries.extend(
                    entry
                    for entry in address_source_loads
                    if entry[0].width == 8
                )
            for load_inst, pointer_rd, pointer_addr, pointer_idx in source_entries:
                key = (pointer_idx, expr_key(pointer_rd), expr_key(pointer_addr))
                if key in seen_pointer_like_sources:
                    continue
                seen_pointer_like_sources.add(key)
                pointer_like_sources.append((load_inst, pointer_rd, pointer_addr, pointer_idx))
            if not pointer_like_sources:
                return
            pairs_tried = 0
            for _, pointer_rd, pointer_addr, pointer_idx in pointer_like_sources:
                if (pointer_idx, expr_key(pointer_rd)) in scalar_load_hint_keys:
                    continue
                if complex_memory_block:
                    if has_prior_same_addr_store(pointer_addr, pointer_idx, allow_solver=False):
                        continue
                elif has_forced_prior_same_addr_store_cached(pointer_addr, pointer_idx):
                    continue
                pointer_affine = affine_key(pointer_addr)
                if (
                    pointer_affine is not None
                    and expr_vars(pointer_affine[2]) & address_loaded_addr_vars
                    and ast_node_count(pointer_affine[2]) > 1
                ):
                    continue
                if complex_memory_block and pointer_affine is None and ast_node_count(pointer_addr) > 32:
                    continue
                for narrow_addr, narrow_idx in address_narrow_source_loads:
                    if pair_budget is not None and pairs_tried >= pair_budget:
                        return
                    if complex_memory_block:
                        if has_prior_same_addr_store(narrow_addr, narrow_idx, allow_solver=False):
                            continue
                    elif has_forced_prior_same_addr_store_cached(narrow_addr, narrow_idx):
                        continue
                    same_result = cheap_same_address(pointer_addr, narrow_addr)
                    if same_result is True:
                        continue
                    if complex_memory_block and same_result is None and exprs_may_be_related(pointer_addr, narrow_addr):
                        continue
                    if affine_accesses_disjoint(pointer_addr, INIT_ACCESS_SLOT_WIDTH, narrow_addr, INIT_ACCESS_SLOT_WIDTH):
                        continue
                    if complex_memory_block and affine_key(narrow_addr) is None and ast_node_count(narrow_addr) > 32:
                        continue
                    pairs_tried += 1
                    constraint = symbolic_access_no_overlap(
                        pointer_addr,
                        INIT_ACCESS_SLOT_WIDTH,
                        narrow_addr,
                        INIT_ACCESS_SLOT_WIDTH,
                    )
                    if complex_memory_block:
                        try_add_constraint_set_fast([constraint], timeout_ms=50)
                    else:
                        try_add_constraint(
                            constraint,
                            timeout_ms=local_solver_timeout_ms,
                        )

        def add_pointer_slot_store_no_overlap_constraints():
            if len(store_accesses) >= GLOBAL_NO_OVERLAP_STORE_THRESHOLD:
                return
            if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD:
                return
            for load_inst, rd_symbol, load_addr_symbol, load_idx in pointer_source_loads:
                if (load_idx, expr_key(rd_symbol)) in scalar_load_hint_keys:
                    continue
                pointer_vars = getattr(rd_symbol, 'variables', set())
                last_use_idx = load_idx
                for _, addr_symbol, access_idx, _ in mem_accesses:
                    if access_idx <= load_idx:
                        continue
                    if getattr(addr_symbol, 'variables', set()) & pointer_vars:
                        last_use_idx = max(last_use_idx, access_idx)
                if last_use_idx <= load_idx:
                    continue
                for store_inst, store_addr_symbol, store_idx, store_width, _ in store_accesses:
                    if store_idx <= load_idx or store_idx > last_use_idx:
                        continue
                    if same_address(store_addr_symbol, load_addr_symbol, allow_solver=True):
                        continue
                    if has_forced_prior_same_addr_store_cached(load_addr_symbol, load_idx):
                        continue
                    if affine_accesses_disjoint(
                        store_addr_symbol,
                        store_width,
                        load_addr_symbol,
                        init_slot_width(load_inst.width),
                    ):
                        continue
                    try_add_constraint(
                        symbolic_access_no_overlap(
                            store_addr_symbol,
                            store_width,
                            load_addr_symbol,
                            init_slot_width(load_inst.width),
                        )
                    )

        def add_store_load_slot_no_overlap_constraints():
            if len(store_accesses) >= GLOBAL_NO_OVERLAP_STORE_THRESHOLD:
                return
            static_symbolic_block = use_static_memory_collection and len(mem_entries) >= 3
            complex_memory_block = len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
            if static_symbolic_block and not complex_memory_block:
                return
            if complex_memory_block:
                required_load_indices = {
                    load_idx for _, _, _, load_idx in pointer_source_loads + address_source_loads
                }
                load_entries = [
                    entry for entry in mem_entries
                    if entry[3] in required_load_indices
                ]
                pair_budget = 512
            else:
                load_entries = mem_entries
                pair_budget = None
            residual_scalar_value_vars = set()
            if complex_memory_block:
                for residual_reg in residual_scalar_regs:
                    residual_symbol = reg_to_symbol.get(residual_reg)
                    if residual_symbol is not None:
                        residual_scalar_value_vars.update(expr_vars(residual_symbol))
            pairs_tried = 0
            for load_inst, _, load_addr_symbol, load_idx in load_entries:
                if complex_memory_block:
                    load_affine = affine_key(load_addr_symbol)
                    if load_affine is None or ast_node_count(load_affine[2]) > 1:
                        continue
                for _, store_addr_symbol, store_idx, store_width, _ in store_accesses:
                    if store_idx >= load_idx:
                        continue
                    if pair_budget is not None and pairs_tried >= pair_budget:
                        return
                    pairs_tried += 1
                    same_result = cheap_same_address(store_addr_symbol, load_addr_symbol)
                    if same_result is True:
                        continue
                    if affine_accesses_disjoint(
                        store_addr_symbol,
                        store_width,
                        load_addr_symbol,
                        INIT_ACCESS_SLOT_WIDTH,
                    ):
                        continue
                    if same_result is None:
                        if static_symbolic_block and exprs_may_be_related(store_addr_symbol, load_addr_symbol):
                            continue
                        if not static_symbolic_block and same_address(store_addr_symbol, load_addr_symbol):
                            continue
                    constraint = symbolic_word_slot_no_overlap(
                        store_addr_symbol,
                        store_width,
                        load_addr_symbol,
                    )
                    if (
                        complex_memory_block
                        and residual_scalar_value_vars
                        and (getattr(constraint, 'variables', set()) & residual_scalar_value_vars)
                    ):
                        continue
                    if complex_memory_block:
                        try_add_constraint(
                            constraint,
                            timeout_ms=100,
                        )
                    else:
                        try_add_constraint(
                            constraint,
                            timeout_ms=100 if static_symbolic_block else HEURISTIC_SOLVER_TIMEOUT_MS,
                        )

        def add_load_slot_no_overlap_constraints():
            if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD:
                return
            for i, (_, _, addr_a, idx_a) in enumerate(mem_entries):
                if has_prior_same_addr_store(addr_a, idx_a, allow_solver=False):
                    continue
                for _, _, addr_b, idx_b in mem_entries[i + 1:]:
                    if has_prior_same_addr_store(addr_b, idx_b, allow_solver=False):
                        continue
                    same_result = cheap_same_address(addr_a, addr_b)
                    if same_result is True:
                        continue
                    if same_result is None and exprs_may_be_related(addr_a, addr_b):
                        continue
                    if affine_accesses_disjoint(addr_a, INIT_ACCESS_SLOT_WIDTH, addr_b, INIT_ACCESS_SLOT_WIDTH):
                        continue
                    try_add_constraint(symbolic_init_slots_no_overlap(addr_a, addr_b))

        def add_pointer_scalar_load_slot_no_overlap_constraints():
            if len(mem_entries) >= 32:
                return
            complex_memory_block = len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
            if complex_memory_block:
                return
            pointer_entries = []
            scalar_entries = []
            for load_inst, rd_symbol, addr_symbol, load_idx in mem_entries:
                if has_prior_same_addr_store(addr_symbol, load_idx, allow_solver=False):
                    continue
                if is_scalar_zero_address_load(load_inst, rd_symbol, load_idx):
                    scalar_entries.append((load_inst, addr_symbol, load_idx))
                    continue
                if load_inst.width != 8:
                    continue
                rd_vars = expr_vars(rd_symbol)
                if not rd_vars:
                    continue
                if (rd_vars & pointer_loaded_addr_vars) or (load_idx, expr_key(rd_symbol)) in hint_pointer_load_keys:
                    pointer_entries.append((load_inst, addr_symbol, load_idx))

            pair_budget = 128
            pairs_tried = 0
            for pointer_inst, pointer_addr, pointer_idx in pointer_entries:
                for scalar_inst, scalar_addr, scalar_idx in scalar_entries:
                    if pointer_idx == scalar_idx:
                        continue
                    if (
                        complex_memory_block
                        and (
                            (affine_key(pointer_addr) is None and ast_node_count(pointer_addr) > 8)
                            or (affine_key(scalar_addr) is None and ast_node_count(scalar_addr) > 8)
                        )
                    ):
                        continue
                    if pairs_tried >= pair_budget:
                        return
                    if same_address(pointer_addr, scalar_addr, allow_solver=False):
                        continue
                    if affine_accesses_disjoint(
                        pointer_addr,
                        init_slot_width(pointer_inst.width),
                        scalar_addr,
                        INIT_ACCESS_SLOT_WIDTH,
                    ):
                        continue
                    pairs_tried += 1
                    constraint = symbolic_init_slots_no_overlap(pointer_addr, scalar_addr)
                    if not try_add_constraint(constraint):
                        candidate_solver.add(constraint)
                        added_constraint_cache.add(str(claripy.simplify(constraint)))
        def add_pointer_load_slot_no_overlap_constraints():
            if len(mem_entries) < GLOBAL_NO_OVERLAP_LOAD_THRESHOLD:
                return
            if address_narrow_source_loads:
                return

            pointer_loads = []
            seen_pointer_loads = set()

            def add_pointer_load(inst, rd_symbol, addr_symbol, inst_idx):
                if inst.width != 8:
                    return
                key = (inst_idx, expr_key(addr_symbol))
                if key in seen_pointer_loads:
                    return
                seen_pointer_loads.add(key)
                pointer_loads.append((inst, rd_symbol, addr_symbol, inst_idx))

            for pc in load_pointer_hints:
                for load_inst, rd_symbol, addr_symbol, load_idx in load_entries_by_pc.get(pc, []):
                    if (load_idx, expr_key(rd_symbol)) in hint_pointer_load_keys:
                        add_pointer_load(load_inst, rd_symbol, addr_symbol, load_idx)

            if not pointer_loads:
                return

            pointer_loads.sort(key=lambda item: item[3], reverse=True)
            pointer_loads = pointer_loads[:LONG_BLOCK_ANCHOR_CANDIDATE_LIMIT]

            pair_budget = 32
            pairs_tried = 0
            for pointer_inst, _, pointer_addr, pointer_idx in pointer_loads:
                if has_prior_same_addr_store(pointer_addr, pointer_idx, allow_solver=False):
                    continue
                pointer_affine = affine_key(pointer_addr)
                if (
                    pointer_affine is not None
                    and expr_vars(pointer_affine[2]) & address_loaded_addr_vars
                    and ast_node_count(pointer_affine[2]) > 1
                ):
                    continue
                other_entries = [
                    entry for entry in mem_entries
                    if entry[0].width < 8
                ]
                other_entries.sort(key=lambda entry: (abs(entry[3] - pointer_idx), entry[3]))
                for other_inst, _, other_addr, other_idx in other_entries:
                    if other_idx == pointer_idx:
                        continue
                    if pairs_tried >= pair_budget:
                        return
                    pairs_tried += 1
                    if has_prior_same_addr_store(other_addr, other_idx, allow_solver=False):
                        continue
                    if same_address(pointer_addr, other_addr, allow_solver=False):
                        continue
                    if affine_accesses_disjoint(
                        pointer_addr,
                        init_slot_width(pointer_inst.width),
                        other_addr,
                        init_slot_width(other_inst.width),
                    ):
                        continue
                    try_add_constraint(symbolic_init_slots_no_overlap(pointer_addr, other_addr))

        def add_pointer_derived_access_slot_no_overlap_constraints():
            if not pointer_source_loads:
                return
            if len(mem_entries) >= 3:
                return
            pair_budget = None
            pairs_tried = 0
            pointer_carriers = [
                (pointer_rd, pointer_idx)
                for _, pointer_rd, _, pointer_idx in pointer_source_loads
                if (pointer_idx, expr_key(pointer_rd)) not in scalar_load_hint_keys
            ]
            for reg, symbol in reg_to_symbol.items():
                if (
                    reg in undef_base_regs
                    or reg in register_anchor_min_offsets
                    or reg in reg_pointer_hints
                ):
                    pointer_carriers.append((symbol, -1))

            seen_carriers = set()
            for pointer_rd, pointer_idx in pointer_carriers:
                carrier_key = expr_key(pointer_rd)
                if carrier_key in seen_carriers:
                    continue
                seen_carriers.add(carrier_key)
                pointer_vars = expr_vars(pointer_rd)
                if not pointer_vars:
                    continue
                for access_inst, access_addr, access_idx, access_width in mem_accesses:
                    if access_idx <= pointer_idx:
                        continue
                    if not (expr_vars(access_addr) & pointer_vars):
                        continue
                    for slot_inst, _, slot_addr, slot_idx in pointer_source_loads:
                        if pair_budget is not None and pairs_tried >= pair_budget:
                            return
                        if slot_idx == pointer_idx:
                            continue
                        if has_prior_same_addr_store(slot_addr, slot_idx, allow_solver=False):
                            continue
                        same_result = cheap_same_address(access_addr, slot_addr)
                        if same_result is True:
                            continue
                        if same_result is None and exprs_may_be_related(access_addr, slot_addr):
                            continue
                        if affine_accesses_disjoint(
                            access_addr,
                            init_slot_width(access_width),
                            slot_addr,
                            init_slot_width(slot_inst.width),
                        ):
                            continue
                        pairs_tried += 1
                        try_add_constraint(symbolic_init_slots_no_overlap(access_addr, slot_addr))

        def add_pointer_value_no_alias_constraints():
            if len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD:
                return
            pair_budget = 64 if len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD else None
            pairs_tried = 0
            for i, (_, rd_a, addr_a, idx_a) in enumerate(pointer_source_loads):
                if has_prior_same_addr_store(addr_a, idx_a, allow_solver=False):
                    continue
                vars_a = getattr(rd_a, 'variables', set())
                if not vars_a:
                    continue
                for _, rd_b, addr_b, idx_b in pointer_source_loads[i + 1:]:
                    if pair_budget is not None and pairs_tried >= pair_budget:
                        return
                    if has_prior_same_addr_store(addr_b, idx_b, allow_solver=False):
                        continue
                    vars_b = getattr(rd_b, 'variables', set())
                    if not vars_b:
                        continue
                    if idx_a == idx_b:
                        continue
                    if same_address(addr_a, addr_b, allow_solver=True):
                        continue
                    source_disjoint = affine_accesses_disjoint(
                        addr_a,
                        INIT_ACCESS_SLOT_WIDTH,
                        addr_b,
                        INIT_ACCESS_SLOT_WIDTH,
                    )
                    if source_disjoint is not True and exprs_may_be_related(addr_a, addr_b):
                        continue
                    source_affine_a = affine_key(addr_a)
                    source_affine_b = affine_key(addr_b)
                    if source_affine_a is not None and source_affine_b is not None:
                        source_base_a, source_imm_a, _ = source_affine_a
                        source_base_b, source_imm_b, _ = source_affine_b
                        if source_base_a == source_base_b:
                            continue
                        source_a_negative = source_imm_a < 0
                        source_b_negative = source_imm_b < 0
                        source_a_pointer_indirect = bool(expr_vars(addr_a) & pointer_loaded_addr_vars)
                        source_b_pointer_indirect = bool(expr_vars(addr_b) & pointer_loaded_addr_vars)
                        suspect_source_pair = (
                            (source_a_pointer_indirect and source_b_pointer_indirect)
                            or (source_a_negative and source_b_pointer_indirect)
                            or (source_b_negative and source_a_pointer_indirect)
                        )
                    else:
                        suspect_source_pair = False
                        source_a_negative = source_b_negative = False
                        source_a_pointer_indirect = source_b_pointer_indirect = False
                    same_value = cheap_same_address(rd_a, rd_b)
                    if same_value is True:
                        continue
                    if same_value is None and exprs_may_be_related(rd_a, rd_b):
                        continue
                    if affine_accesses_disjoint(rd_a, INIT_ACCESS_SLOT_WIDTH, rd_b, INIT_ACCESS_SLOT_WIDTH):
                        continue
                    pairs_tried += 1
                    constraint = symbolic_access_no_overlap(
                        rd_a,
                        INIT_ACCESS_SLOT_WIDTH,
                        rd_b,
                        INIT_ACCESS_SLOT_WIDTH,
                    )
                    if suspect_source_pair:
                        continue
                    try_add_constraint(constraint)

        def add_pointer_anchor_simplification_constraints():
            if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD:
                return
            anchor_accesses = mem_accesses
            candidate_budget = None
            candidates_tried = 0
            long_block = len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
            if len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD:
                anchor_accesses = list(reversed(mem_accesses))[:LONG_BLOCK_ANCHOR_CANDIDATE_LIMIT * 4]
                candidate_budget = LONG_BLOCK_ANCHOR_CANDIDATE_LIMIT * 8
            for access_inst, addr_symbol, access_idx, width in anchor_accesses:
                if _signed_u64(access_inst.imm) < 0:
                    continue
                if long_block and ast_node_count(addr_symbol) > 96:
                    continue
                carrier_candidates = []
                addr_vars = expr_vars(addr_symbol)
                candidate_loads = [
                    entry for entry in load_accesses
                    if entry[3] < access_idx
                ]
                if len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD:
                    candidate_loads = list(reversed(candidate_loads))[:LONG_BLOCK_ANCHOR_CANDIDATE_LIMIT]
                for load_inst, rd_symbol, _, load_idx in candidate_loads:
                    if load_idx >= access_idx:
                        continue
                    if load_inst.width != 8:
                        continue
                    if (load_idx, expr_key(rd_symbol)) in scalar_load_hint_keys:
                        continue
                    rd_vars = expr_vars(rd_symbol)
                    if not rd_vars or not (addr_vars & rd_vars):
                        continue
                    if (addr_vars & pointer_loaded_addr_vars) and not (rd_vars & pointer_loaded_addr_vars):
                        continue
                    if long_block and ast_node_count(rd_symbol) > 48:
                        continue
                    if candidate_budget is not None:
                        if candidates_tried >= candidate_budget:
                            break
                        candidates_tried += 1
                    constraints = constraints_to_carrier(addr_symbol, rd_symbol)
                    preferred_base = 1 if load_inst.pc in mem_base_pcs else 0
                    if constraints is not None:
                        carrier_candidates.append((
                            preferred_base,
                            count_mul_ancestors(addr_symbol, rd_symbol),
                            1,
                            load_idx,
                            rd_symbol,
                            rd_vars,
                            constraints,
                        ))
                    internal_constraints = constraints_to_internal_carrier(addr_symbol, rd_symbol)
                    if internal_constraints is not None:
                        carrier_candidates.append((
                            preferred_base,
                            count_mul_ancestors(addr_symbol, rd_symbol),
                            0,
                            load_idx,
                            rd_symbol,
                            rd_vars,
                            internal_constraints,
                        ))
                if verbose and carrier_candidates:
                    print('carrier_candidates', {
                        'access_idx': access_idx,
                        'addr': str(addr_symbol),
                        'candidates': [
                            (preferred, score, kind, load_idx, getattr(rd_symbol, 'shallow_repr', lambda: str(rd_symbol))(), len(constraints))
                            for preferred, score, kind, load_idx, rd_symbol, _, constraints in carrier_candidates
                        ],
                    })
                if not carrier_candidates:
                    continue

                carrier_candidates.sort(key=lambda item: (item[0], item[1], item[2], item[3]), reverse=True)
                for _, _, _, load_idx, rd_symbol, rd_vars, constraints in carrier_candidates:
                    stack_constraints = stack_pointer_constraints_for_expr(
                        rd_symbol,
                        min_pointer_offset_for_vars(rd_vars, load_idx),
                    )
                    if try_add_constraint_set(
                        list(constraints) + stack_constraints,
                        verify_constraints=[addr_symbol == rd_symbol],
                    ):
                        if verbose:
                            print('carrier_selected', {
                                'access_idx': access_idx,
                                'load_idx': load_idx,
                                'rd': str(rd_symbol),
                                'constraints': [str(claripy.simplify(c)) for c in list(constraints) + stack_constraints],
                            })
                        break

        def add_register_anchor_simplification_constraints():
            if len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD:
                return
            long_register_anchor = len(mem_accesses) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
            anchor_accesses = mem_accesses
            if long_register_anchor:
                anchor_accesses = list(reversed(mem_accesses))[:LONG_BLOCK_ANCHOR_CANDIDATE_LIMIT * 4]

            for access_inst, addr_symbol, _, width in anchor_accesses:
                if long_register_anchor and ast_node_count(addr_symbol) > 96:
                    continue
                addr_vars = expr_vars(addr_symbol)
                has_pointer_loaded_base = bool(addr_vars & (pointer_loaded_addr_vars | address_loaded_addr_vars))
                carrier_candidates = []
                direct_carrier_keys = set()
                for reg, symbol in reg_to_symbol.items():
                    if reg in scalar_hint_regs:
                        continue
                    if reg_is_additive_offset_to_independent_base(reg):
                        continue
                    symbol_vars = expr_vars(symbol)
                    if not symbol_vars or not (addr_vars & symbol_vars):
                        continue
                    if has_pointer_loaded_base and getattr(access_inst, 'rs1', None) != reg:
                        continue
                    carrier_constraints = constraints_to_carrier(addr_symbol, symbol)
                    if carrier_constraints is not None:
                        residual_vars = addr_vars - symbol_vars
                        direct_carrier_keys.add(reg)
                        carrier_candidates.append((
                            count_mul_ancestors(addr_symbol, symbol),
                            len(residual_vars),
                            0,
                            reg.name,
                            symbol,
                            carrier_constraints,
                            width,
                        ))
                        continue
                    residual = claripy.simplify(addr_symbol - symbol)
                    residual_vars = expr_vars(residual)
                    if residual_vars & symbol_vars:
                        continue
                    if long_register_anchor and ast_node_count(residual) > 64:
                        continue
                    constraints = constraints_to_constant(
                        residual,
                        0,
                        forbidden_vars=symbol_vars,
                    )
                    if constraints is None:
                        continue
                    direct_carrier_keys.add(reg)
                    carrier_candidates.append((
                        count_mul_ancestors(addr_symbol, symbol),
                        len(residual_vars),
                        0,
                        reg.name,
                        symbol,
                        constraints,
                        width,
                    ))

                for reg, symbol in reg_to_symbol.items():
                    if reg in direct_carrier_keys:
                        continue
                    if reg in scalar_hint_regs:
                        continue
                    if reg_is_additive_offset_to_independent_base(reg):
                        continue
                    symbol_vars = expr_vars(symbol)
                    if not symbol_vars or not (addr_vars & symbol_vars):
                        continue
                    if has_pointer_loaded_base and getattr(access_inst, 'rs1', None) != reg:
                        continue
                    residual = claripy.simplify(addr_symbol - symbol)
                    residual_vars = expr_vars(residual)
                    if residual_vars & symbol_vars:
                        continue
                    if long_register_anchor and ast_node_count(residual) > 64:
                        continue
                    # Heuristic for indexed stack accesses such as
                    #   base + ((load - 1) * stride) * scale
                    # where the index can be solved away by prior value hints.
                    # Adding the equality directly lets the solver pick the
                    # needed scalar values without recursively decomposing a
                    # large bit-vector multiplication expression.
                    carrier_candidates.append((
                        count_mul_ancestors(addr_symbol, symbol),
                        len(residual_vars),
                        1,
                        reg.name,
                        symbol,
                        [addr_symbol == symbol],
                        width,
                    ))
                if not carrier_candidates:
                    continue

                carrier_candidates.sort(key=lambda item: (item[0], -item[1], -item[2], item[3]), reverse=True)
                for _, _, _, reg_name, symbol, constraints, access_width in carrier_candidates:
                    min_offset = max(INIT_PTR_MIN_OFFSET, access_width)
                    stack_constraints = stack_pointer_constraints_for_expr(symbol, min_offset)
                    if try_add_constraint_set(
                        list(constraints) + stack_constraints,
                        verify_constraints=[addr_symbol == symbol],
                    ):
                        reg = find_reg_by_name(reg_name)
                        register_anchor_min_offsets[reg] = max(
                            register_anchor_min_offsets.get(reg, INIT_PTR_MIN_OFFSET),
                            _align_up(min_offset, INIT_ACCESS_ALIGN),
                        )
                        break

        def add_store_no_overlap_for_word(word_offset, addr_symbols):
            long_block = len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
            slot = mem_slot_symbols.get(word_offset)
            residual_scalar_value_vars = set()
            for residual_reg in residual_scalar_regs:
                residual_symbol = reg_to_symbol.get(residual_reg)
                if residual_symbol is not None:
                    residual_scalar_value_vars.update(expr_vars(residual_symbol))
            protected_pointer_slot = bool(
                slot is not None
                and (
                    slot.get('pointer_like')
                    or slot.get('must_be_pointer')
                    or slot.get('sp_affine')
                )
            )
            if long_block and not protected_pointer_slot:
                return
            addr_symbol_vars = set()
            for addr_symbol in addr_symbols:
                addr_symbol_vars.update(expr_vars(addr_symbol))
            long_block_checks = 0
            long_block_check_budget = 8 if protected_pointer_slot else 0
            for _, store_addr_symbol, _, store_width, _ in store_accesses:
                if long_block:
                    store_vars = expr_vars(store_addr_symbol)
                    if (
                        addr_symbol_vars
                        and store_vars
                        and not (addr_symbol_vars & store_vars)
                        and not protected_pointer_slot
                    ):
                        continue
                if any(
                    same_address(
                        store_addr_symbol,
                        addr_symbol,
                        allow_solver=not long_block,
                    )
                    for addr_symbol in addr_symbols
                ):
                    continue
                if addr_symbols and all(
                    affine_accesses_disjoint(store_addr_symbol, store_width, addr_symbol, INIT_ACCESS_SLOT_WIDTH)
                    for addr_symbol in addr_symbols
                ):
                    continue
                constraint = symbolic_no_overlap(store_addr_symbol, store_width, word_offset)
                if long_block:
                    if long_block_checks >= long_block_check_budget:
                        return
                    long_block_checks += 1
                    if (
                        residual_scalar_value_vars
                        and (getattr(constraint, 'variables', set()) & residual_scalar_value_vars)
                        and not protected_pointer_slot
                    ):
                        continue
                    try_add_constraint_set_fast(
                        [constraint],
                        timeout_ms=50,
                    )
                else:
                    try_add_constraint(constraint)

        def add_access_range_constraints():
            direct_add_for_long_block = len(mem_accesses) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD

            def try_add_constraint_group(constraints):
                constraints = list(constraints)
                if not constraints:
                    return True
                if direct_add_for_long_block:
                    test_solver = candidate_solver.branch()
                    test_solver.timeout = local_solver_timeout_ms
                    try:
                        for constraint in constraints:
                            test_solver.add(constraint)
                        if not test_solver.satisfiable():
                            return False
                    except Exception:
                        return False
                    for constraint in constraints:
                        constraint_key = str(claripy.simplify(constraint))
                        if constraint_key in added_constraint_cache:
                            continue
                        candidate_solver.add(constraint)
                        added_constraint_cache.add(constraint_key)
                    return True
                test_solver = candidate_solver.branch()
                test_solver.timeout = HEURISTIC_SOLVER_TIMEOUT_MS
                try:
                    for constraint in constraints:
                        test_solver.add(constraint)
                    if not test_solver.satisfiable():
                        return False
                except Exception:
                    return False
                for constraint in constraints:
                    candidate_solver.add(constraint)
                    added_constraint_cache.add(str(claripy.simplify(constraint)))
                return True

            grouped = {}
            fallback = []
            for _, addr_symbol, _, width in mem_accesses:
                affine = affine_key(addr_symbol)
                if affine is None:
                    fallback.append((addr_symbol, width))
                    continue
                base_key, imm, base = affine
                grouped.setdefault(base_key, {'base': base, 'accesses': []})['accesses'].append((imm, width))

            group_values = list(grouped.values())
            if len(mem_accesses) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD:
                group_values.sort(key=lambda item: (-len(item['accesses']), str(item['base'])))
                group_values = group_values[:LONG_BLOCK_ANCHOR_CANDIDATE_LIMIT * 4]

            for group in group_values:
                base = group['base']
                base_offset = init_sp - base
                lower = None
                upper = None
                align_constraints = set()
                for imm, width in group['accesses']:
                    access_lower = imm + width
                    lower = access_lower if lower is None else max(lower, access_lower)
                    access_upper = STACK_RANGE + imm
                    upper = access_upper if upper is None else min(upper, access_upper)
                    if width > 1:
                        mask = width - 1
                        align_constraints.add((width, (-imm) & mask))
                group_accesses = group['accesses']
                if lower is None:
                    continue
                if lower < 1:
                    if len(mem_accesses) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD:
                        group_accesses = group_accesses[:LONG_BLOCK_ANCHOR_CANDIDATE_LIMIT * 4]
                    for imm, width in group_accesses:
                        addr_symbol = claripy.simplify(base + claripy.BVV(imm & ((1 << 64) - 1), 64))
                        offset_expr = init_sp - addr_symbol
                        constraints = [
                            claripy.UGE(offset_expr, claripy.BVV(width, 64)),
                            claripy.ULE(offset_expr, claripy.BVV(STACK_RANGE, 64)),
                        ]
                        if width > 1:
                            constraints.append((addr_symbol & (width - 1)) == 0)
                        try_add_constraint_group(constraints)
                    continue
                if upper is None:
                    upper = STACK_RANGE
                if lower > upper:
                    if len(mem_accesses) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD:
                        group_accesses = group_accesses[:LONG_BLOCK_ANCHOR_CANDIDATE_LIMIT * 4]
                    for imm, width in group_accesses:
                        addr_symbol = claripy.simplify(base + claripy.BVV(imm & ((1 << 64) - 1), 64))
                        offset_expr = init_sp - addr_symbol
                        constraints = [
                            claripy.UGE(offset_expr, claripy.BVV(width, 64)),
                            claripy.ULE(offset_expr, claripy.BVV(STACK_RANGE, 64)),
                        ]
                        if width > 1:
                            constraints.append((addr_symbol & (width - 1)) == 0)
                        try_add_constraint_group(constraints)
                    continue
                constraints = [
                    claripy.UGE(base_offset, claripy.BVV(lower, 64)),
                    claripy.ULE(base_offset, claripy.BVV(upper, 64)),
                ]
                for width, residue in sorted(align_constraints):
                    constraints.append((base & (width - 1)) == residue)
                if not try_add_constraint_group(constraints):
                    group_accesses = group['accesses']
                    if len(mem_accesses) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD:
                        group_accesses = group_accesses[:LONG_BLOCK_ANCHOR_CANDIDATE_LIMIT * 4]
                    for imm, width in group_accesses:
                        addr_symbol = claripy.simplify(base + claripy.BVV(imm & ((1 << 64) - 1), 64))
                        offset_expr = init_sp - addr_symbol
                        access_constraints = [
                            claripy.UGE(offset_expr, claripy.BVV(width, 64)),
                            claripy.ULE(offset_expr, claripy.BVV(STACK_RANGE, 64)),
                        ]
                        if width > 1:
                            access_constraints.append((addr_symbol & (width - 1)) == 0)
                        try_add_constraint_group(access_constraints)

            if len(mem_accesses) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD:
                fallback = fallback[:LONG_BLOCK_ANCHOR_CANDIDATE_LIMIT * 8]
            for addr_symbol, width in fallback:
                offset_expr = init_sp - addr_symbol
                constraints = [
                    claripy.UGE(offset_expr, claripy.BVV(width, 64)),
                    claripy.ULE(offset_expr, claripy.BVV(STACK_RANGE, 64)),
                ]
                if width > 1:
                    constraints.append((addr_symbol & (width - 1)) == 0)
                try_add_constraint_group(constraints)

        def choose_register_value(symbol, preferred=None, align=None):
            symbol_vars = getattr(symbol, 'variables', set())
            if symbol_vars and not any(
                getattr(constraint, 'variables', set()) & symbol_vars
                for constraint in candidate_solver.constraints
            ):
                val = preferred if preferred is not None else 0
                if align and val % align != 0:
                    val = _align_up(val, align)
                candidate_solver.add(symbol == val)
                return val

            symbol_key = expr_key(symbol)
            for constraint in candidate_solver.constraints:
                if getattr(constraint, 'op', None) not in {'__eq__', 'BoolS'}:
                    continue
                args = [
                    arg for arg in getattr(constraint, 'args', ())
                    if hasattr(arg, 'op')
                ]
                if len(args) != 2:
                    continue
                lhs, rhs = args
                if expr_key(lhs) == symbol_key and not expr_vars(rhs):
                    val = concrete_expr_value(rhs)
                elif expr_key(rhs) == symbol_key and not expr_vars(lhs):
                    val = concrete_expr_value(lhs)
                else:
                    val = None
                if val is None:
                    continue
                val &= ((1 << 64) - 1)
                if align and val % align != 0:
                    continue
                return val

            choices = []
            if preferred is not None:
                choices.append(preferred)
            choices.extend([
                0,
                1,
                2,
                4,
                8,
                16,
                32,
                (-8) & ((1 << 64) - 1),
                (-16) & ((1 << 64) - 1),
                (-32) & ((1 << 64) - 1),
            ])

            seen = set()
            for val in choices:
                if val in seen:
                    continue
                seen.add(val)
                if align and val % align != 0:
                    continue
                stack_offset = stack_offset_for_value(val)
                if stack_offset is not None and any(
                    concrete_ranges_overlap(stack_offset, 8, used_offset, used_width)
                    for used_offset, used_width in used_stack_offsets
                ):
                    continue
                if satisfiable_with(symbol, val, timeout_ms=local_solver_timeout_ms):
                    candidate_solver.add(symbol == val)
                    if stack_offset is not None:
                        used_stack_offsets.append((stack_offset, 8))
                    return val

            minimum = solver_min(symbol)
            if minimum is not None:
                choices.append(minimum)
                step = align if align else 1
                for i in range(1, 64):
                    choices.append(minimum + i * step)

            for val in choices:
                if val in seen:
                    continue
                seen.add(val)
                if align and val % align != 0:
                    continue
                stack_offset = stack_offset_for_value(val)
                if stack_offset is not None and any(
                    concrete_ranges_overlap(stack_offset, 8, used_offset, used_width)
                    for used_offset, used_width in used_stack_offsets
                ):
                    continue
                if satisfiable_with(symbol, val, timeout_ms=local_solver_timeout_ms):
                    candidate_solver.add(symbol == val)
                    if stack_offset is not None:
                        used_stack_offsets.append((stack_offset, 8))
                    return val

            val = choose_value(symbol, preferred, align=align)
            stack_offset = stack_offset_for_value(val)
            if stack_offset is not None:
                used_stack_offsets.append((stack_offset, 8))
            return val

        def choose_stack_relative_register_value(symbol):
            offset_expr = init_sp - symbol
            offset = choose_value(
                offset_expr,
                None,
                positive=True,
                align=8,
                avoid=used_stack_offsets,
                width=8,
                required=False,
            )
            if offset is None:
                offset = choose_value(
                    offset_expr,
                    None,
                    positive=True,
                    align=8,
                    required=False,
                )
            if offset is None:
                return None
            used_stack_offsets.append((offset, 8))
            return concrete_stack_addr(offset)

        def has_tight_loaded_pointer_field_window():
            for load_inst, rd_symbol, _, load_idx in load_accesses:
                if load_inst.width != 8:
                    continue
                rd_vars = expr_vars(rd_symbol)
                if not rd_vars:
                    continue
                positive = []
                negative = []
                for _, addr_symbol, access_idx, width in mem_accesses:
                    if access_idx <= load_idx:
                        continue
                    if not (expr_vars(addr_symbol) & rd_vars):
                        continue
                    residual = claripy.simplify(addr_symbol - rd_symbol)
                    if expr_vars(residual) & rd_vars:
                        continue
                    residual_value = concrete_expr_value(residual)
                    if residual_value is None:
                        continue
                    imm = _signed_u64(residual_value)
                    if imm >= 0:
                        positive.append(imm + width)
                    else:
                        negative.append(STACK_RANGE + imm)
                if not positive or not negative:
                    continue
                lower = max(positive)
                upper = min(negative)
                if lower > 512 and upper >= lower and upper - lower <= 512:
                    return True
            return False

        prefer_high_base_offsets = (
            len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
            and has_tight_loaded_pointer_field_window()
        )

        def choose_base_register_value(symbol, min_offset=INIT_PTR_MIN_OFFSET, fast_anchor=False):
            symbol_vars = expr_vars(symbol)
            start_offset = max(1, min_offset)
            candidates = []
            concrete_symbol_value = concrete_expr_value(symbol)
            offset_expr = init_sp - symbol
            fallback_start = _align_up(max(INIT_PTR_MIN_OFFSET, min_offset), INIT_ACCESS_ALIGN)
            debug_base_choice_enabled = os.environ.get("RVMCA_DEBUG_LOAD_SLOTS") == "1"

            def debug_base_choice(event, **fields):
                if debug_base_choice_enabled:
                    fields.setdefault('symbol', str(symbol))
                    DEBUG(f"base_register_choice_{event} {fields}")

            def remember_chosen_base_offset(base_offset):
                remember_equiv_base_offset(symbol, base_offset)
                current_affine = affine_key(symbol)
                if current_affine is None:
                    return
                base_key, imm, base = current_affine
                known_base_offset = base_offset + imm
                if known_base_offset <= 0 or known_base_offset > STACK_RANGE:
                    return
                remember_affine_base_offset(base_key, base, known_base_offset)
                remember_equiv_base_offset(base, known_base_offset)

            def concrete_base_value(base_offset):
                remember_chosen_base_offset(base_offset)
                return concrete_stack_addr(base_offset)

            def residual_offset_and_constraints(residual):
                residual_vars = expr_vars(residual)
                if residual_vars & symbol_vars:
                    return None
                residual_value = concrete_expr_value(residual)
                if residual_value is not None:
                    return _signed_u64(residual_value), []
                residual_affine = affine_base_const(residual)
                if residual_affine is None:
                    return None
                _, residual_imm = residual_affine
                residual_constraints = constraints_to_constant(
                    residual,
                    residual_imm,
                    forbidden_vars=symbol_vars,
                )
                if residual_constraints is None:
                    return None
                return residual_imm, list(residual_constraints)

            def residual_zero_choice(residual, addr_symbol=None):
                residual_constraints = constraints_to_constant(
                    residual,
                    0,
                    forbidden_vars=symbol_vars,
                )
                if residual_constraints is not None:
                    return 0, list(residual_constraints)
                residual_vars = expr_vars(residual)
                if (
                    addr_symbol is not None
                    and (residual_vars & symbol_vars)
                    and (expr_vars(addr_symbol) & (address_loaded_addr_vars | pointer_loaded_addr_vars))
                ):
                    return 0, [residual == expr_bvv(0, residual)]
                return None

            def base_offset_alignment():
                modulus = 1
                residue = 0
                for access_inst, addr_symbol, _, access_width in mem_accesses:
                    if access_width <= 1:
                        continue
                    if not (expr_vars(addr_symbol) & symbol_vars):
                        continue
                    residual = claripy.simplify(addr_symbol - symbol)
                    residual_choice = residual_offset_and_constraints(residual)
                    if residual_choice is None:
                        continue
                    imm, _ = residual_choice
                    width_residue = imm % access_width
                    new_modulus = max(modulus, access_width)
                    if residue % access_width != width_residue:
                        if width_residue % modulus != residue:
                            return None
                        residue = width_residue
                    modulus = new_modulus
                return modulus, residue % modulus

            base_alignment = base_offset_alignment()

            def has_scaled_loaded_pointer_load_address():
                scaled_ops = {'__lshift__', 'LShR', 'SShR', '__mul__', 'Mul', 'Concat'}
                for pointer_inst, _, pointer_addr_symbol, pointer_idx in pointer_source_loads:
                    if pointer_inst.width != 8:
                        continue
                    if not (expr_vars(pointer_addr_symbol) & symbol_vars):
                        continue
                    residual = claripy.simplify(pointer_addr_symbol - symbol)
                    residual_vars = expr_vars(residual)
                    if not residual_vars:
                        continue
                    if not (residual_vars & address_loaded_addr_vars):
                        continue
                    if any(
                        getattr(node, 'op', None) in scaled_ops
                        and (expr_vars(node) & address_loaded_addr_vars)
                        for node in iter_ast_nodes(residual)
                    ):
                        return True
                return False

            def has_scaled_loaded_access_residual():
                loaded_value_vars = set(loaded_addr_vars) | set(address_loaded_addr_vars) | set(pointer_loaded_addr_vars)
                for _load_inst, rd_symbol, _load_addr_symbol, _load_idx in load_accesses:
                    loaded_value_vars.update(expr_vars(rd_symbol))
                if not loaded_value_vars:
                    return False
                scaled_ops = {'__lshift__', 'LShR', 'SShR', '__mul__', 'Mul', 'Concat'}
                for _, addr_symbol, _, _ in mem_accesses:
                    if not (expr_vars(addr_symbol) & symbol_vars):
                        continue
                    residual = claripy.simplify(addr_symbol - symbol)
                    residual_vars = expr_vars(residual)
                    if not (residual_vars & loaded_value_vars):
                        continue
                    if any(
                        getattr(node, 'op', None) in scaled_ops
                        and (expr_vars(node) & loaded_value_vars)
                        for node in iter_ast_nodes(residual)
                    ):
                        return True
                return False

            def direct_access_window_for_symbol():
                lower = INIT_PTR_MIN_OFFSET
                upper = STACK_RANGE
                saw_positive = False
                saw_negative = False
                for access_inst, addr_symbol, _, access_width in mem_accesses:
                    if not (expr_vars(addr_symbol) & symbol_vars):
                        continue
                    residual = claripy.simplify(addr_symbol - symbol)
                    residual_choice = residual_offset_and_constraints(residual)
                    if residual_choice is None:
                        continue
                    imm, _ = residual_choice
                    if imm >= 0:
                        lower = max(lower, imm + access_width)
                        saw_positive = True
                    else:
                        upper = min(upper, STACK_RANGE + imm)
                        saw_negative = True
                if not (
                    saw_positive
                    and saw_negative
                    and lower > 512
                    and upper >= lower
                    and upper - lower <= 1024
                ):
                    return None
                return lower, upper

            prefer_high_base_for_symbol = (
                prefer_high_base_offsets
                or (
                    len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                    and has_scaled_loaded_pointer_load_address()
                )
                or (
                    len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                    and direct_access_window_for_symbol() is not None
                )
            )
            if (
                not prefer_high_base_for_symbol
                and len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                and has_scaled_loaded_access_residual()
            ):
                prefer_high_base_for_symbol = True

            def align_base_offset(start):
                if base_alignment is None:
                    return None
                modulus, residue = base_alignment
                start = max(1, start)
                if modulus <= 1:
                    return start
                delta = (residue - (start % modulus)) % modulus
                return start + delta

            def align_base_offset_down(start):
                if base_alignment is None:
                    return None
                modulus, residue = base_alignment
                start = max(1, start)
                if modulus <= 1:
                    return start
                delta = (start - residue) % modulus
                return start - delta

            def base_offset_step():
                if base_alignment is None:
                    return INIT_ACCESS_ALIGN
                return max(1, base_alignment[0])

            residual_choice_cache = {}

            def residual_choice_for_access(access_inst, addr_symbol):
                cache_key = (id(access_inst), expr_key(addr_symbol))
                if cache_key in residual_choice_cache:
                    return residual_choice_cache[cache_key]
                residual = claripy.simplify(addr_symbol - symbol)
                residual_choice = residual_offset_and_constraints(residual)
                if residual_choice is None:
                    residual_choice = residual_zero_choice(residual, addr_symbol)
                if residual_choice is None:
                    imm_target = _signed_u64(access_inst.imm)
                    residual_constraints = constraints_to_constant(
                        residual,
                        imm_target & ((1 << residual.size()) - 1),
                        forbidden_vars=symbol_vars,
                    )
                    if residual_constraints is not None:
                        residual_choice = (imm_target, list(residual_constraints))
                residual_choice_cache[cache_key] = residual_choice
                return residual_choice

            def has_constrainable_symbolic_access_residual():
                for access_inst, addr_symbol, _, _ in mem_accesses:
                    if not (expr_vars(addr_symbol) & symbol_vars):
                        continue
                    residual = claripy.simplify(addr_symbol - symbol)
                    if not expr_vars(residual):
                        continue
                    if residual_choice_for_access(access_inst, addr_symbol) is not None:
                        return True
                return False

            def base_access_ranges_for_offset(base_offset):
                ranges = []
                for access_inst, addr_symbol, _, access_width in mem_accesses:
                    if not (expr_vars(addr_symbol) & symbol_vars):
                        continue
                    residual_choice = residual_choice_for_access(access_inst, addr_symbol)
                    if residual_choice is None:
                        continue
                    imm, residual_constraints = residual_choice
                    access_offset = base_offset - imm
                    if access_offset <= 0 or access_offset > STACK_RANGE:
                        return None
                    if access_width > 1 and access_offset % access_width:
                        return None
                    ranges.append((access_offset, access_width, addr_symbol, residual_constraints))
                return ranges

            def stack_ranges_available(ranges):
                if ranges is None:
                    return False
                def overlaps_known_same_address(offset, width, addr_symbol, used_offset, used_width):
                    if addr_symbol is None:
                        return False
                    if not concrete_ranges_overlap(offset, width, used_offset, used_width):
                        return False
                    candidate_words = {
                        used_offset,
                        ((used_offset + 7) // 8) * 8,
                        ((offset + 7) // 8) * 8,
                    }
                    for word_offset in candidate_words:
                        for known_addr_symbol in mem_offset_addr_symbols.get(word_offset, []):
                            if same_address(addr_symbol, known_addr_symbol, allow_solver=False):
                                return True
                    return False

                for offset, width, addr_symbol, _ in ranges:
                    for used_offset, used_width in used_stack_offsets:
                        if not concrete_ranges_overlap(offset, width, used_offset, used_width):
                            continue
                        if overlaps_known_same_address(
                            offset,
                            width,
                            addr_symbol,
                            used_offset,
                            used_width,
                        ):
                            continue
                        return False
                return True

            def reserve_stack_ranges(ranges):
                reserved = []
                for offset, width, _, _ in ranges:
                    if any(
                        concrete_ranges_overlap(offset, width, used_offset, used_width)
                        for used_offset, used_width in used_stack_offsets + reserved
                    ):
                        continue
                    reserved.append((offset, width))
                used_stack_offsets.extend(reserved)

            def reserve_base_access_ranges(ranges):
                for offset, width, addr_symbol, _ in ranges:
                    if addr_symbol is None:
                        continue
                    if any(
                        used_offset == offset
                        and same_address(addr_symbol, used_addr_symbol, allow_solver=False)
                        for used_offset, _, used_addr_symbol in reserved_base_access_ranges
                    ):
                        continue
                    reserved_base_access_ranges.append((offset, width, addr_symbol))

            def try_select_base_offset(base_offset, timeout_ms=HEURISTIC_SOLVER_TIMEOUT_MS):
                ranges = base_access_ranges_for_offset(base_offset)
                if not stack_ranges_available(ranges):
                    debug_base_choice(
                        "reject_ranges",
                        base_offset=base_offset,
                        ranges=[] if ranges is None else [
                            (offset, width, str(addr_symbol))
                            for offset, width, addr_symbol, _ in ranges
                        ],
                        used=used_stack_offsets[:16],
                    )
                    return None
                constraints = [offset_expr == base_offset]
                for _, _, _, residual_constraints in ranges:
                    constraints.extend(residual_constraints)
                if try_add_constraint_set_fast(constraints, timeout_ms=timeout_ms):
                    reserve_stack_ranges(ranges)
                    reserve_base_access_ranges(ranges)
                    debug_base_choice(
                        "choose",
                        base_offset=base_offset,
                        ranges=[
                            (offset, width, str(addr_symbol))
                            for offset, width, addr_symbol, _ in ranges
                        ],
                    )
                    return concrete_base_value(base_offset)
                related_accesses = [
                    access_inst
                    for access_inst, addr_symbol, _, _ in mem_accesses
                    if expr_vars(addr_symbol) & symbol_vars
                ]
                has_disconnected_nonlinear_constraint = any(
                    not (expr_vars(constraint) & symbol_vars)
                    and any(
                        getattr(node, 'op', None) in {
                            '__mul__', 'Mul', '__floordiv__', '__truediv__',
                            '__div__', 'SDiv', 'UDiv',
                        }
                        for node in iter_ast_nodes(constraint)
                    )
                    for constraint in candidate_solver.constraints
                )
                direct_load_group = (
                    fast_anchor
                    and bool(related_accesses)
                    and len(ranges) == len(related_accesses)
                    and all(
                        access_inst.type == IType.Load
                        for access_inst in related_accesses
                    )
                    and all(
                        not residual_constraints
                        for _, _, _, residual_constraints in ranges
                    )
                    and has_disconnected_nonlinear_constraint
                )
                if direct_load_group:
                    componentwise_sat = constraint_set_componentwise_satisfiable(
                        constraints,
                        timeout_ms=10000,
                    )
                    if componentwise_sat is True:
                        for constraint in constraints:
                            constraint_key = str(claripy.simplify(constraint))
                            if constraint_key in added_constraint_cache:
                                continue
                            candidate_solver.add(constraint)
                            added_constraint_cache.add(constraint_key)
                            debug_constraint_add("base_offset_componentwise", constraint)
                        reserve_stack_ranges(ranges)
                        reserve_base_access_ranges(ranges)
                        debug_base_choice(
                            "choose_componentwise",
                            base_offset=base_offset,
                            ranges=[
                                (offset, width, str(addr_symbol))
                                for offset, width, addr_symbol, _ in ranges
                            ],
                        )
                        return concrete_base_value(base_offset)
                has_materialized_access_offset = any(
                    (expr_vars(addr_symbol) & symbol_vars)
                    and expr_key(addr_symbol) in addr_expr_offsets
                    for _, addr_symbol, _, _ in mem_accesses
                )
                direct_simple_long_base_offset = (
                    allow_initial_heuristics
                    and
                    len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
                    and not has_materialized_access_offset
                    and all(ast_node_count(constraint) <= 64 for constraint in constraints)
                )
                if direct_simple_long_base_offset:
                    for constraint in constraints:
                        constraint_key = str(claripy.simplify(constraint))
                        if constraint_key in added_constraint_cache:
                            continue
                        candidate_solver.add(constraint)
                        added_constraint_cache.add(constraint_key)
                        debug_constraint_add("base_offset_direct_assumed", constraint)
                    reserve_stack_ranges(ranges)
                    reserve_base_access_ranges(ranges)
                    debug_base_choice(
                        "choose_direct_assumed",
                        base_offset=base_offset,
                        ranges=[
                            (offset, width, str(addr_symbol))
                            for offset, width, addr_symbol, _ in ranges
                        ],
                    )
                    return concrete_base_value(base_offset)
                simple_long_base_offset = (
                    len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                    and not has_materialized_access_offset
                    and len(constraints) <= 8
                    and all(ast_node_count(constraint) <= 64 for constraint in constraints)
                )
                if simple_long_base_offset:
                    if try_add_constraint_set_related(
                        constraints,
                        symbol_vars,
                        timeout_ms=max(timeout_ms, 1000),
                    ):
                        reserve_stack_ranges(ranges)
                        reserve_base_access_ranges(ranges)
                        debug_base_choice(
                            "choose_related",
                            base_offset=base_offset,
                            ranges=[
                                (offset, width, str(addr_symbol))
                                for offset, width, addr_symbol, _ in ranges
                            ],
                        )
                        return concrete_base_value(base_offset)
                    base_offset_sat = constraint_set_related_satisfiable(
                        constraints,
                        symbol_vars,
                        timeout_ms=max(timeout_ms, 1000),
                    )
                    if base_offset_sat is not False:
                        for constraint in constraints:
                            candidate_solver.add(constraint)
                            added_constraint_cache.add(str(claripy.simplify(constraint)))
                            debug_constraint_add("base_offset_assumed", constraint)
                        reserve_stack_ranges(ranges)
                        reserve_base_access_ranges(ranges)
                        debug_base_choice(
                            "choose_assumed",
                            base_offset=base_offset,
                            ranges=[
                                (offset, width, str(addr_symbol))
                                for offset, width, addr_symbol, _ in ranges
                            ],
                        )
                        return concrete_base_value(base_offset)
                debug_base_choice(
                    "reject_solver",
                    base_offset=base_offset,
                    ranges=[
                        (offset, width, str(addr_symbol))
                        for offset, width, addr_symbol, _ in ranges
                    ],
                    constraints=[
                        str(claripy.simplify(constraint))[:500]
                        for constraint in constraints[:6]
                    ],
                )
                return None

            debug_base_choice(
                "start",
                min_offset=min_offset,
                fallback_start=fallback_start,
                base_alignment=base_alignment,
                fast_anchor=fast_anchor,
                concrete_value=None if concrete_symbol_value is None else hex(concrete_symbol_value),
            )
            if concrete_symbol_value is not None:
                concrete_offset = stack_offset_for_value(concrete_symbol_value)
                if concrete_offset is not None:
                    value = try_select_base_offset(
                        concrete_offset,
                        timeout_ms=100 if fast_anchor else HEURISTIC_SOLVER_TIMEOUT_MS,
                    )
                    if value is not None:
                        return value
                if not symbol_vars:
                    return concrete_symbol_value

            if fast_anchor and has_constrainable_symbolic_access_residual():
                seen_high_offsets = set()
                high_attempts = 0
                high_safe_start = STACK_RANGE - LIVEIN_STORE_LOW_GUARD_OFFSET
                for high_start in (high_safe_start, 0x800, 0x400):
                    offset = align_base_offset_down(high_start)
                    if offset is None:
                        continue
                    while offset >= fallback_start and high_attempts < 16:
                        if offset not in seen_high_offsets:
                            seen_high_offsets.add(offset)
                            value = try_select_base_offset(offset, timeout_ms=1000)
                            high_attempts += 1
                            if value is not None:
                                debug_base_choice("high_residual", base_offset=offset)
                                return value
                        offset -= base_offset_step()

            def try_known_access_offset_base():
                candidates = []
                seen_offsets = set()

                def add_candidate(base_offset, known_access_offset):
                    if base_offset <= 0 or base_offset > MAX_SP_REL_OFFSET:
                        return
                    if base_offset in seen_offsets:
                        return
                    seen_offsets.add(base_offset)
                    candidates.append((base_offset, known_access_offset))

                for _access_inst, addr_symbol, _access_idx, _access_width in mem_accesses:
                    if not (expr_vars(addr_symbol) & symbol_vars):
                        continue
                    known_access_offsets = []
                    known_access_offset = addr_expr_offsets.get(expr_key(addr_symbol))
                    if known_access_offset is not None:
                        known_access_offsets.append(known_access_offset)
                    access_affine = affine_key(addr_symbol)
                    if access_affine is not None:
                        access_base_key, access_imm, access_base = access_affine
                        for cached_base_offset in affine_base_offsets_for(access_base_key, access_base):
                            known_access_offsets.append(cached_base_offset - access_imm)
                    if not known_access_offsets:
                        continue
                    residual_choice = residual_choice_for_access(_access_inst, addr_symbol)
                    if residual_choice is None:
                        continue
                    imm, _ = residual_choice
                    for known_access_offset in known_access_offsets:
                        if known_access_offset <= 0 or known_access_offset > STACK_RANGE:
                            continue
                        add_candidate(known_access_offset + imm, known_access_offset)
                if prefer_high_base_for_symbol:
                    candidates.sort(key=lambda item: (abs(item[0] - 0xc00), item[0], item[1]))
                else:
                    candidates.sort(key=lambda item: (item[0], item[1]))
                for base_offset, known_access_offset in candidates[:8]:
                    value = try_select_base_offset(
                        base_offset,
                        timeout_ms=1000 if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD else HEURISTIC_SOLVER_TIMEOUT_MS,
                    )
                    if value is not None:
                        debug_base_choice(
                            "known_access_offset",
                            base_offset=base_offset,
                            known_access_offset=known_access_offset,
                        )
                        return value
                return None

            known_access_value = try_known_access_offset_base()
            if known_access_value is not None:
                return known_access_value

            def add_base_offset_constraints_direct(base_offset, ranges):
                constraints = [offset_expr == base_offset]
                for _, _, _, residual_constraints in ranges:
                    for constraint in residual_constraints:
                        constraints.append(constraint)
                if try_add_constraint_set_fast(
                    constraints,
                    timeout_ms=local_solver_timeout_ms,
                ):
                    return True
                if (
                    allow_initial_heuristics
                    and
                    len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
                    and all(not residual_constraints for _, _, _, residual_constraints in ranges)
                ):
                    for constraint in constraints:
                        candidate_solver.add(constraint)
                        added_constraint_cache.add(str(claripy.simplify(constraint)))
                        debug_constraint_add("base_offset_assumed", constraint)
                    return True
                return False

            if fast_anchor and len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD:
                direct_window = direct_access_window_for_symbol()
                if direct_window is not None:
                    lower, upper = direct_window
                    candidate_offsets = [
                        min(upper, max(lower, 0xc00)),
                        upper,
                        lower,
                    ]
                    seen_direct_offsets = set()
                    for candidate_offset in candidate_offsets:
                        candidate_offset = align_base_offset_down(candidate_offset)
                        if (
                            candidate_offset is None
                            or candidate_offset < fallback_start
                            or candidate_offset < lower
                            or candidate_offset > upper
                            or candidate_offset in seen_direct_offsets
                        ):
                            continue
                        seen_direct_offsets.add(candidate_offset)
                        ranges = base_access_ranges_for_offset(candidate_offset)
                        if not stack_ranges_available(ranges):
                            continue
                        if add_base_offset_constraints_direct(candidate_offset, ranges):
                            reserve_stack_ranges(ranges)
                            reserve_base_access_ranges(ranges)
                            debug_base_choice("direct_window", base_offset=candidate_offset)
                            return concrete_base_value(candidate_offset)

                low_offset = align_base_offset(fallback_start)
                if low_offset is None:
                    return None

                first_offset = low_offset
                if prefer_high_base_for_symbol:
                    high_offset = align_base_offset(max(fallback_start, 0xc00))
                    if high_offset is not None and high_offset <= STACK_RANGE:
                        first_offset = high_offset
                starts = [first_offset]
                if low_offset != first_offset:
                    starts.append(low_offset)
                for used_offset, used_width in used_stack_offsets:
                    starts.append(used_offset + max(INIT_ACCESS_SLOT_WIDTH, used_width))

                seen_offsets = set()
                direct_add_candidate = None
                attempts = 0
                start_order = starts if prefer_high_base_for_symbol else sorted(starts)
                for start in start_order:
                    offset = align_base_offset(max(start, fallback_start))
                    if offset is None:
                        continue
                    while (
                        offset <= STACK_RANGE
                        and attempts < LONG_BLOCK_ANCHOR_CANDIDATE_LIMIT * 4
                    ):
                        if offset not in seen_offsets:
                            seen_offsets.add(offset)
                            ranges = base_access_ranges_for_offset(offset)
                            if stack_ranges_available(ranges):
                                value = try_select_base_offset(offset, timeout_ms=100)
                                if value is not None:
                                    return value
                                if direct_add_candidate is None:
                                    direct_add_candidate = (offset, ranges)
                            attempts += 1
                        offset += base_offset_step()

                if direct_add_candidate is None:
                    return None
                offset, ranges = direct_add_candidate
                if not add_base_offset_constraints_direct(offset, ranges):
                    return None
                reserve_stack_ranges(ranges)
                reserve_base_access_ranges(ranges)
                return concrete_base_value(offset)

            if fast_anchor:
                has_negative_access = False
                for _, addr_symbol, _, _ in mem_accesses:
                    if not (expr_vars(addr_symbol) & symbol_vars):
                        continue
                    residual = claripy.simplify(addr_symbol - symbol)
                    if expr_vars(residual) & symbol_vars:
                        continue
                    residual_value = concrete_expr_value(residual)
                    if residual_value is not None and _signed_u64(residual_value) < 0:
                        has_negative_access = True
                        break
                if has_negative_access:
                    stop_offset = min(STACK_RANGE, fallback_start + 512)
                    first_offset = align_base_offset(fallback_start)
                    if first_offset is None:
                        return None
                    direct_add_candidate = None
                    attempts = 0
                    for preferred_offset in range(first_offset, stop_offset + 1, base_offset_step()):
                        if attempts >= 32:
                            break
                        attempts += 1
                        value = try_select_base_offset(preferred_offset, timeout_ms=100)
                        if value is not None:
                            return value
                        if direct_add_candidate is None:
                            ranges = base_access_ranges_for_offset(preferred_offset)
                            if stack_ranges_available(ranges):
                                direct_add_candidate = (preferred_offset, ranges)
                    if direct_add_candidate is not None:
                        offset, ranges = direct_add_candidate
                        if not add_base_offset_constraints_direct(offset, ranges):
                            return None
                        reserve_stack_ranges(ranges)
                        reserve_base_access_ranges(ranges)
                        return concrete_base_value(offset)
                else:
                    first_offset = align_base_offset(fallback_start)
                    if first_offset is None:
                        return None
                    stop_offset = min(STACK_RANGE, first_offset + 512)
                    direct_add_candidate = None
                    attempts = 0
                    for preferred_offset in range(first_offset, stop_offset + 1, base_offset_step()):
                        if attempts >= 32:
                            break
                        attempts += 1
                        value = try_select_base_offset(preferred_offset, timeout_ms=100)
                        if value is not None:
                            return value
                        if direct_add_candidate is None:
                            ranges = base_access_ranges_for_offset(preferred_offset)
                            if stack_ranges_available(ranges):
                                direct_add_candidate = (preferred_offset, ranges)
                    if direct_add_candidate is not None:
                        offset, ranges = direct_add_candidate
                        if not add_base_offset_constraints_direct(offset, ranges):
                            return None
                        reserve_stack_ranges(ranges)
                        reserve_base_access_ranges(ranges)
                        return concrete_base_value(offset)
                return None
            first_offset = align_base_offset(fallback_start)
            if first_offset is None:
                return None
            for offset in range(first_offset, STACK_RANGE + 1, base_offset_step()):
                sat = satisfiable_with(offset_expr, offset)
                if fast_anchor:
                    if not sat:
                        continue
                    value = try_select_base_offset(offset)
                    if value is not None:
                        return value
                if sat:
                    value = try_select_base_offset(offset)
                    if value is not None:
                        return value
            for _, addr_symbol, _, width in mem_accesses:
                if not (expr_vars(addr_symbol) & symbol_vars):
                    continue
                residual = claripy.simplify(addr_symbol - symbol)
                if expr_vars(residual) & symbol_vars:
                    continue
                residual_value = concrete_expr_value(residual)
                if residual_value is None:
                    continue
                imm = _signed_u64(residual_value)
                align = width if width > 1 else 1
                access_start = _align_up(start_offset, align)
                for access_offset in range(access_start, STACK_RANGE + 1, align):
                    value = (CONCRETE_REPLAY_SP - access_offset - imm) & ((1 << 64) - 1)
                    candidates.append(value)

            for offset in range(first_offset, STACK_RANGE + 1, base_offset_step()):
                candidates.append(concrete_stack_addr(offset))

            seen = set()
            relaxed_candidates = []
            for value in candidates:
                value &= ((1 << 64) - 1)
                if value in seen:
                    continue
                seen.add(value)
                stack_offset = stack_offset_for_value(value)
                if stack_offset is not None:
                    ranges = base_access_ranges_for_offset(stack_offset)
                    if not stack_ranges_available(ranges):
                        relaxed_candidates.append(value)
                        continue
                if satisfiable_with(symbol, value):
                    candidate_solver.add(symbol == value)
                    if stack_offset is not None:
                        reserve_stack_ranges(base_access_ranges_for_offset(stack_offset))
                        remember_chosen_base_offset(stack_offset)
                    return value

            for value in relaxed_candidates:
                stack_offset = stack_offset_for_value(value)
                if stack_offset is not None and not stack_ranges_available(base_access_ranges_for_offset(stack_offset)):
                    continue
                if satisfiable_with(symbol, value):
                    candidate_solver.add(symbol == value)
                    if stack_offset is not None:
                        reserve_stack_ranges(base_access_ranges_for_offset(stack_offset))
                        remember_chosen_base_offset(stack_offset)
                    return value

            for offset in range(first_offset, STACK_RANGE + 1, base_offset_step()):
                value = try_select_base_offset(offset)
                if value is not None:
                    return value
            return None

        def scaled_symbol_affine(expr, symbol, min_scale=2):
            symbol_key = expr_key(symbol)
            symbol_vars = expr_vars(symbol)
            mask = (1 << 64) - 1

            def parse(node):
                node = claripy.simplify(node)
                if expr_key(node) == symbol_key:
                    return 1, 0, []
                node_vars = expr_vars(node)
                if not node_vars:
                    value = concrete_expr_value(node)
                    if value is None:
                        return None
                    return 0, value & mask, []
                if not (node_vars & symbol_vars):
                    return 0, 0, [node == expr_bvv(0, node)]

                op = getattr(node, 'op', None)
                args = getattr(node, 'args', ())
                if op in {'__add__', 'Add'}:
                    scale, const, constraints = 0, 0, []
                    for arg in args:
                        parsed = parse(arg)
                        if parsed is None:
                            return None
                        arg_scale, arg_const, arg_constraints = parsed
                        scale += arg_scale
                        const = (const + arg_const) & mask
                        constraints.extend(arg_constraints)
                    return scale, const, constraints
                if op in {'__sub__', 'Sub'} and len(args) == 2:
                    lhs = parse(args[0])
                    rhs = parse(args[1])
                    if lhs is None or rhs is None:
                        return None
                    return lhs[0] - rhs[0], (lhs[1] - rhs[1]) & mask, lhs[2] + rhs[2]
                if op in {'__mul__', 'Mul'} and len(args) == 2:
                    for affine_arg, factor_arg in (args, reversed(args)):
                        if expr_vars(factor_arg):
                            continue
                        factor = concrete_expr_value(factor_arg)
                        if factor is None:
                            continue
                        factor_bits = factor_arg.size()
                        if factor & (1 << (factor_bits - 1)):
                            factor -= 1 << factor_bits
                        if (
                            factor == 0
                            or abs(factor) > MAX_AFFINE_QUOTIENT_SCALE
                        ):
                            continue
                        parsed = parse(affine_arg)
                        if parsed is None:
                            continue
                        scale, const, constraints = parsed
                        return scale * factor, (const * factor) & mask, constraints
                    return None
                if op == '__lshift__' and len(args) == 2:
                    parsed = parse(args[0])
                    shift_arg = args[1]
                    shift_value = (
                        shift_arg
                        if isinstance(shift_arg, int)
                        else concrete_expr_value(shift_arg)
                    )
                    if parsed is None or shift_value is None:
                        return None
                    scale, const, constraints = parsed
                    return scale << shift_value, (const << shift_value) & mask, constraints
                if op in {'ZeroExt', 'SignExt'} and args:
                    return parse(args[-1])
                if op == 'Extract' and len(args) == 3:
                    high, low, child = args
                    if low == 0 and expr_key(child) == symbol_key:
                        return 1, 0, []
                    return None
                if op == 'Concat' and args:
                    low_width = 0
                    low_const = 0
                    for low_arg in args[1:]:
                        low_value = concrete_expr_value(low_arg)
                        if low_value is None:
                            return None
                        low_const = (
                            (low_const << low_arg.size()) | low_value
                        ) & mask
                        low_width += low_arg.size()
                    high = parse(args[0])
                    if high is None:
                        return None
                    return (
                        high[0] << low_width,
                        ((high[1] << low_width) + low_const) & mask,
                        high[2],
                    )
                return None

            parsed = parse(expr)
            if parsed is None:
                return None
            scale, const, constraints = parsed
            if scale < min_scale or scale > MAX_AFFINE_QUOTIENT_SCALE:
                return None
            return scale, const & mask, constraints

        def fixed_sp_affine_quotient_compatible(
            addr_symbol,
            access_offset,
            access_width=0,
            avoid_ranges=(),
        ):
            if runtime_recipe_scratch_unavailable():
                return True
            mask = (1 << 64) - 1
            for reg in regs_undefined:
                symbol = reg_to_symbol.get(reg)
                if symbol is None:
                    continue
                scaled = scaled_symbol_affine(addr_symbol, symbol)
                if scaled is None:
                    continue
                scale, const, constraints = scaled
                if constraints:
                    continue
                raw_value = (
                    CONCRETE_REPLAY_SP - access_offset - const
                ) & mask
                if raw_value % scale:
                    return False
                if access_width and avoid_ranges:
                    remainders = _affine_quotient_remainders(
                        access_offset + _signed_u64(const),
                        scale,
                    )
                    if not remainders:
                        return False
                    max_remainder = max(remainders)
                    runtime_range = (
                        access_offset + max_remainder,
                        access_width + max_remainder,
                    )
                    if any(
                        concrete_ranges_overlap(
                            *runtime_range,
                            used_offset,
                            used_width,
                        )
                        for used_offset, used_width in avoid_ranges
                    ):
                        return False
            return True

        def choose_scaled_address_register_value(symbol):
            symbol_vars = expr_vars(symbol)
            if not symbol_vars:
                return None
            symbol_key = expr_key(symbol)
            pending_reg_runtime_recipes.pop(symbol_key, None)
            candidates = []
            debug_runtime_recipe = os.environ.get("RVMCA_DEBUG_REPAIR") == "1"

            def runtime_stack_ranges(runtime_info):
                if runtime_info is None:
                    return ()
                remainders = runtime_info.get('remainders') or ()
                if not remainders:
                    return ()
                numerator_offset = int(runtime_info['recipe'][1])
                max_remainder = max(remainders)
                return tuple(
                    (
                        numerator_offset - int(addr_const) + max_remainder,
                        int(width) + max_remainder,
                    )
                    for _, addr_const, width, _ in runtime_info['accesses']
                )

            def candidate_ranges_available(ranges):
                return not any(
                    concrete_ranges_overlap(
                        candidate_offset,
                        candidate_width,
                        used_offset,
                        used_width,
                    )
                    for candidate_offset, candidate_width in ranges
                    for used_offset, used_width in used_stack_offsets
                )

            def mul_carrier_constraints(mul_node):
                mul_args = [
                    arg for arg in getattr(mul_node, 'args', ())
                    if hasattr(arg, 'op')
                ]
                carrier_args = [
                    arg for arg in mul_args
                    if expr_vars(arg) & symbol_vars
                ]
                if len(carrier_args) != 1:
                    return None
                carrier_arg = carrier_args[0]
                constraints = constraints_to_carrier(carrier_arg, symbol)
                if constraints is None:
                    return None
                constraints = list(constraints)
                for other_arg in mul_args:
                    if other_arg is carrier_arg:
                        continue
                    if not expr_vars(other_arg):
                        other_value = concrete_expr_value(other_arg)
                        if other_value is None or other_value != 1:
                            return None
                        continue
                    other_constraints = constraints_to_constant(
                        other_arg,
                        1,
                        forbidden_vars=symbol_vars,
                    )
                    if other_constraints is None:
                        return None
                    constraints.extend(other_constraints)
                return constraints

            def mul_carrier_affine(addr_symbol):
                for mul_node in iter_ast_nodes(addr_symbol):
                    if getattr(mul_node, 'op', None) not in {'__mul__', 'Mul'}:
                        continue
                    if not (expr_vars(mul_node) & symbol_vars):
                        continue
                    residual = sub_same_width(addr_symbol, mul_node)
                    if residual is None:
                        continue
                    if expr_vars(residual) & expr_vars(mul_node):
                        continue
                    residual_value = concrete_expr_value(residual)
                    if residual_value is None:
                        continue
                    carrier_constraints = mul_carrier_constraints(mul_node)
                    if carrier_constraints is None:
                        continue
                    return residual_value & ((1 << 64) - 1), carrier_constraints
                return None

            def shifted_carrier_affine(addr_symbol):
                for shift_node in iter_ast_nodes(addr_symbol):
                    if getattr(shift_node, 'op', None) not in {
                        '__rshift__', 'LShR', 'SShR',
                    }:
                        continue
                    shift_args = getattr(shift_node, 'args', ())
                    if len(shift_args) != 2:
                        continue
                    child, shift_arg = shift_args
                    if not (expr_vars(child) & symbol_vars):
                        continue
                    shift = (
                        shift_arg
                        if isinstance(shift_arg, int)
                        else concrete_expr_value(shift_arg)
                    )
                    if shift is None or shift <= 0 or shift > 8:
                        continue
                    carrier_constraints = constraints_to_carrier(child, symbol)
                    if carrier_constraints is None:
                        continue
                    outer = scaled_symbol_affine(
                        addr_symbol,
                        shift_node,
                        min_scale=1,
                    )
                    if outer is None:
                        continue
                    divisor, const, outer_constraints = outer
                    if divisor <= 0:
                        continue
                    return (
                        divisor,
                        const,
                        1 << shift,
                        list(carrier_constraints) + list(outer_constraints),
                    )
                return None

            def add_shifted_carrier_candidates(addr_symbol, width):
                initial_candidate_count = len(candidates)
                shifted = shifted_carrier_affine(addr_symbol)
                if shifted is None:
                    return False
                divisor, const, multiplier, shifted_constraints = shifted
                runtime_accesses = []
                runtime_recipe_eligible = (
                    not runtime_recipe_scratch_unavailable()
                )
                group_requirements = []
                for other_inst, other_addr_symbol, other_idx, other_width in mem_accesses:
                    if not (expr_vars(other_addr_symbol) & symbol_vars):
                        continue
                    other_shifted = shifted_carrier_affine(other_addr_symbol)
                    if other_shifted is None:
                        runtime_recipe_eligible = False
                        continue
                    (
                        other_divisor,
                        other_const,
                        other_multiplier,
                        other_constraints,
                    ) = other_shifted
                    if (
                        other_divisor != divisor
                        or other_multiplier != multiplier
                    ):
                        runtime_recipe_eligible = False
                        continue
                    runtime_accesses.append((
                        other_idx,
                        _signed_u64(other_const),
                        other_width,
                        other_inst.type == IType.Load,
                    ))
                    delta = _signed_u64(
                        (const - other_const) & ((1 << 64) - 1)
                    )
                    group_requirements.append((
                        other_addr_symbol,
                        delta,
                        other_width,
                        other_constraints,
                    ))
                if not runtime_recipe_eligible or not runtime_accesses:
                    return False

                align = width if width > 1 else 1
                starts = [align, INIT_PTR_MIN_OFFSET]
                preferred = next_free_stack_offset(
                    used_stack_offsets,
                    align=align,
                    width=INIT_ACCESS_SLOT_WIDTH,
                    start=align,
                )
                if preferred is not None:
                    starts.insert(0, preferred)
                known_access_offset = addr_expr_offsets.get(expr_key(addr_symbol))
                if known_access_offset is not None:
                    starts.insert(0, known_access_offset)
                starts.extend(
                    used + max(width, used_width)
                    for used, used_width in used_stack_offsets
                )
                seen_offsets = set()
                for start in starts:
                    start = _align_up(max(1, start), align)
                    for access_offset in range(
                        start,
                        min(STACK_RANGE, start + 512) + 1,
                        align,
                    ):
                        if access_offset in seen_offsets:
                            continue
                        seen_offsets.add(access_offset)
                        group_targets = []
                        group_constraints = list(shifted_constraints)
                        group_ok = True
                        for (
                            other_addr_symbol,
                            delta,
                            other_width,
                            other_constraints,
                        ) in group_requirements:
                            other_offset = access_offset + delta
                            if (
                                other_offset <= 0
                                or other_offset > STACK_RANGE
                                or (
                                    other_width > 1
                                    and other_offset % other_width
                                )
                            ):
                                group_ok = False
                                break
                            group_targets.append((
                                other_addr_symbol,
                                concrete_stack_addr(other_offset),
                            ))
                            group_constraints.extend(other_constraints)
                        if not group_ok:
                            continue

                        target_addr = concrete_stack_addr(access_offset)
                        raw_value = (target_addr - const) & ((1 << 64) - 1)
                        if raw_value % divisor:
                            continue
                        value = (
                            (raw_value // divisor) * multiplier
                        ) & ((1 << 64) - 1)
                        numerator_offset = access_offset + _signed_u64(const)
                        remainders = _affine_quotient_remainders(
                            numerator_offset,
                            divisor,
                        )
                        if not remainders:
                            continue
                        runtime_safe = True
                        for _, other_const, other_width, _ in runtime_accesses:
                            base_offset = numerator_offset - other_const
                            for remainder in remainders:
                                actual_offset = base_offset + remainder
                                if (
                                    actual_offset < max(1, other_width)
                                    or actual_offset > STACK_RANGE
                                    or (
                                        other_width > 1
                                        and actual_offset % other_width
                                    )
                                ):
                                    runtime_safe = False
                                    break
                            if not runtime_safe:
                                break
                        if not runtime_safe:
                            continue
                        runtime_info = {
                            'recipe': (
                                'affine_scaled_quotient',
                                numerator_offset,
                                divisor,
                                multiplier,
                            ),
                            'accesses': tuple(runtime_accesses),
                            'remainders': remainders,
                        }
                        if not candidate_ranges_available(
                            runtime_stack_ranges(runtime_info)
                        ):
                            continue
                        candidates.append((
                            value,
                            addr_symbol,
                            target_addr,
                            access_offset,
                            group_constraints,
                            group_targets,
                            runtime_info,
                        ))
                return len(candidates) > initial_candidate_count

            for inst, addr_symbol, _, width in mem_accesses:
                if not (expr_vars(addr_symbol) & symbol_vars):
                    continue
                scaled = scaled_symbol_affine(addr_symbol, symbol)
                if scaled is None:
                    if add_shifted_carrier_candidates(addr_symbol, width):
                        continue
                    mul_carrier = mul_carrier_affine(addr_symbol)
                    if mul_carrier is not None:
                        residual_value, carrier_constraints = mul_carrier
                        align = width if width > 1 else 1
                        starts = [align, INIT_PTR_MIN_OFFSET]
                        preferred = next_free_stack_offset(
                            used_stack_offsets,
                            align=align,
                            width=INIT_ACCESS_SLOT_WIDTH,
                            start=align,
                        )
                        if preferred is not None:
                            starts.insert(0, preferred)
                        starts.extend(used + max(width, used_width) for used, used_width in used_stack_offsets)
                        group_requirements = []
                        for _, other_addr_symbol, _, other_width in mem_accesses:
                            if not (expr_vars(other_addr_symbol) & symbol_vars):
                                continue
                            other_mul_carrier = mul_carrier_affine(other_addr_symbol)
                            if other_mul_carrier is None:
                                continue
                            other_residual, other_constraints = other_mul_carrier
                            delta = _signed_u64((residual_value - other_residual) & ((1 << 64) - 1))
                            group_requirements.append((other_addr_symbol, delta, other_width, other_constraints))
                        group_low = align
                        for _, delta, other_width, _ in group_requirements:
                            group_low = max(group_low, other_width - delta)
                        if group_low > align:
                            starts.insert(0, group_low)
                        seen_offsets = set()
                        for start in starts:
                            start = _align_up(max(1, start), align)
                            for access_offset in range(start, min(STACK_RANGE, start + 512) + 1, align):
                                if access_offset in seen_offsets:
                                    continue
                                seen_offsets.add(access_offset)
                                if any(
                                    concrete_ranges_overlap(access_offset, INIT_ACCESS_SLOT_WIDTH, used_offset, used_width)
                                    for used_offset, used_width in used_stack_offsets
                                ):
                                    continue
                                group_ok = True
                                group_targets = []
                                group_constraints = list(carrier_constraints)
                                for other_addr_symbol, delta, other_width, other_constraints in group_requirements:
                                    other_offset = access_offset + delta
                                    if other_offset <= 0 or other_offset > STACK_RANGE:
                                        group_ok = False
                                        break
                                    if other_width > 1 and other_offset % other_width != 0:
                                        group_ok = False
                                        break
                                    group_targets.append((other_addr_symbol, concrete_stack_addr(other_offset)))
                                    group_constraints.extend(other_constraints)
                                if not group_ok:
                                    continue
                                target_addr = concrete_stack_addr(access_offset)
                                value = (target_addr - residual_value) & ((1 << 64) - 1)
                                candidates.append((
                                    value,
                                    addr_symbol,
                                    target_addr,
                                    access_offset,
                                    group_constraints,
                                    group_targets,
                                    None,
                                ))
                    continue
                scale, const, scaled_constraints = scaled
                runtime_accesses = []
                runtime_blocked_vars = symbol_vars | expr_vars(init_sp)

                def runtime_stable_constraints(constraints):
                    return all(
                        not (expr_vars(constraint) & runtime_blocked_vars)
                        for constraint in constraints
                    )

                runtime_recipe_eligible = (
                    runtime_stable_constraints(scaled_constraints)
                    and not runtime_recipe_scratch_unavailable()
                )
                # The expression proof must cover every address affected by
                # this live-in.  A partial recipe would relocate only some of
                # the accesses and could silently change aliasing.
                for other_inst, other_addr_symbol, other_idx, other_width in mem_accesses:
                    if not (expr_vars(other_addr_symbol) & symbol_vars):
                        continue
                    other_scaled = scaled_symbol_affine(other_addr_symbol, symbol)
                    if other_scaled is None:
                        runtime_recipe_eligible = False
                        continue
                    other_scale, other_const, other_constraints = other_scaled
                    if (
                        other_scale != scale
                        or not runtime_stable_constraints(other_constraints)
                    ):
                        runtime_recipe_eligible = False
                        continue
                    runtime_accesses.append((
                        other_idx,
                        _signed_u64(other_const),
                        other_width,
                        other_inst.type == IType.Load,
                    ))
                group_requirements = []
                for _, other_addr_symbol, _, other_width in mem_accesses:
                    if not (expr_vars(other_addr_symbol) & symbol_vars):
                        continue
                    other_scaled = scaled_symbol_affine(other_addr_symbol, symbol)
                    if other_scaled is None:
                        continue
                    other_scale, other_const, other_constraints = other_scaled
                    if other_scale != scale:
                        continue
                    delta = _signed_u64((const - other_const) & ((1 << 64) - 1))
                    group_requirements.append((
                        other_addr_symbol,
                        delta,
                        other_width,
                        other_constraints,
                    ))

                def scaled_register_group_ok(access_offset):
                    for _, delta, other_width, _ in group_requirements:
                        other_offset = access_offset + delta
                        if other_offset <= 0 or other_offset > STACK_RANGE:
                            return False
                        if other_width > 1 and other_offset % other_width != 0:
                            return False
                    return True

                align = width if width > 1 else 1
                starts = [align, INIT_PTR_MIN_OFFSET]
                preferred = next_free_stack_offset(
                    used_stack_offsets,
                    align=align,
                    width=INIT_ACCESS_SLOT_WIDTH,
                    start=align,
                )
                if preferred is not None:
                    starts.insert(0, preferred)
                known_access_offset = addr_expr_offsets.get(expr_key(addr_symbol))
                if known_access_offset is not None:
                    starts.insert(0, known_access_offset)
                starts.extend(used + max(width, used_width) for used, used_width in used_stack_offsets)
                group_low = align
                for _, delta, other_width, _ in group_requirements:
                    group_low = max(group_low, other_width - delta)
                if group_low > align:
                    starts.insert(0, group_low)
                seen_offsets = set()
                search_span = max(512, abs(scale))
                for start in starts:
                    start = _align_up(max(1, start), align)
                    for access_offset in range(
                        start,
                        min(STACK_RANGE, start + search_span) + 1,
                        align,
                    ):
                        if access_offset in seen_offsets:
                            continue
                        seen_offsets.add(access_offset)
                        if not scaled_register_group_ok(access_offset):
                            continue
                        target_addr = concrete_stack_addr(access_offset)
                        raw_value = (target_addr - const) & ((1 << 64) - 1)
                        if raw_value % scale:
                            continue
                        value = (raw_value // scale) & ((1 << 64) - 1)
                        group_targets = []
                        group_constraints = list(scaled_constraints)
                        for (
                            other_addr_symbol,
                            delta,
                            _,
                            other_constraints,
                        ) in group_requirements:
                            group_targets.append((
                                other_addr_symbol,
                                concrete_stack_addr(access_offset + delta),
                            ))
                            group_constraints.extend(other_constraints)
                        runtime_info = None
                        direct_scaled_recipe = scaled_stack_transform_for_value(value)
                        needs_quotient_recipe = (
                            bool(scale & (scale - 1))
                            or direct_scaled_recipe is None
                        )
                        if (
                            runtime_recipe_eligible
                            and needs_quotient_recipe
                            and runtime_accesses
                        ):
                            numerator_offset = access_offset + _signed_u64(const)
                            remainders = _affine_quotient_remainders(
                                numerator_offset,
                                scale,
                            )
                            runtime_safe = bool(remainders)
                            for _, other_const, other_width, _ in runtime_accesses:
                                base_offset = numerator_offset - other_const
                                for remainder in remainders:
                                    actual_offset = base_offset + remainder
                                    if (
                                        actual_offset < max(1, other_width)
                                        or actual_offset > STACK_RANGE
                                        or (
                                            other_width > 1
                                            and actual_offset % other_width
                                        )
                                    ):
                                        runtime_safe = False
                                        break
                                if not runtime_safe:
                                    break
                            if runtime_safe:
                                runtime_info = {
                                    'recipe': (
                                        'affine_quotient',
                                        numerator_offset,
                                        scale,
                                    ),
                                    'accesses': tuple(runtime_accesses),
                                    'remainders': remainders,
                                }
                        candidate_ranges = (
                            runtime_stack_ranges(runtime_info)
                            if runtime_info is not None
                            else ((access_offset, INIT_ACCESS_SLOT_WIDTH),)
                        )
                        if not candidate_ranges_available(candidate_ranges):
                            continue
                        candidates.append((
                            value,
                            addr_symbol,
                            target_addr,
                            access_offset,
                            group_constraints,
                            group_targets,
                            runtime_info,
                        ))

                mul_carrier = mul_carrier_affine(addr_symbol)
                if mul_carrier is None:
                    continue
                residual_value, carrier_constraints = mul_carrier
                align = width if width > 1 else 1
                starts = [align, INIT_PTR_MIN_OFFSET]
                preferred = next_free_stack_offset(
                    used_stack_offsets,
                    align=align,
                    width=INIT_ACCESS_SLOT_WIDTH,
                    start=align,
                )
                if preferred is not None:
                    starts.insert(0, preferred)
                starts.extend(used + max(width, used_width) for used, used_width in used_stack_offsets)
                group_requirements = []
                for _, other_addr_symbol, _, other_width in mem_accesses:
                    if not (expr_vars(other_addr_symbol) & symbol_vars):
                        continue
                    other_mul_carrier = mul_carrier_affine(other_addr_symbol)
                    if other_mul_carrier is None:
                        continue
                    other_residual, other_constraints = other_mul_carrier
                    delta = _signed_u64((residual_value - other_residual) & ((1 << 64) - 1))
                    group_requirements.append((other_addr_symbol, delta, other_width, other_constraints))

                def mul_group_access_ok(access_offset):
                    for _, delta, other_width, _ in group_requirements:
                        other_offset = access_offset + delta
                        if other_offset <= 0 or other_offset > STACK_RANGE:
                            return False
                        if other_width > 1 and other_offset % other_width != 0:
                            return False
                    return True

                group_low = align
                for _, delta, other_width, _ in group_requirements:
                    group_low = max(group_low, other_width - delta)
                if group_low > align:
                    starts.insert(0, group_low)
                seen_offsets = set()
                for start in starts:
                    start = _align_up(max(1, start), align)
                    for access_offset in range(start, min(STACK_RANGE, start + 512) + 1, align):
                        if access_offset in seen_offsets:
                            continue
                        seen_offsets.add(access_offset)
                        if any(
                            concrete_ranges_overlap(access_offset, INIT_ACCESS_SLOT_WIDTH, used_offset, used_width)
                            for used_offset, used_width in used_stack_offsets
                        ):
                            continue
                        if not mul_group_access_ok(access_offset):
                            continue
                        target_addr = concrete_stack_addr(access_offset)
                        value = (target_addr - residual_value) & ((1 << 64) - 1)
                        group_targets = []
                        group_constraints = list(carrier_constraints)
                        for other_addr_symbol, delta, _, other_constraints in group_requirements:
                            group_targets.append((other_addr_symbol, concrete_stack_addr(access_offset + delta)))
                            group_constraints.extend(other_constraints)
                        candidates.append((
                            value,
                            addr_symbol,
                            target_addr,
                            access_offset,
                            group_constraints,
                            group_targets,
                            None,
                        ))
            seen_values = set()
            for (
                value,
                addr_symbol,
                target_addr,
                access_offset,
                scaled_constraints,
                group_targets,
                runtime_info,
            ) in candidates:
                if value in seen_values:
                    continue
                seen_values.add(value)
                constraints = list(scaled_constraints) + [
                    symbol == value,
                    addr_symbol == target_addr,
                ]
                for other_addr_symbol, other_target_addr in group_targets:
                    constraints.append(other_addr_symbol == other_target_addr)
                if (
                    try_add_constraint_set_fast(
                        constraints,
                        timeout_ms=5000,
                    )
                    or try_add_constraint_set_related(
                        constraints,
                        expr_vars(symbol) | expr_vars(addr_symbol),
                        timeout_ms=5000,
                    )
                ):
                    if runtime_info is not None:
                        pending_reg_runtime_recipes[symbol_key] = runtime_info
                        used_stack_offsets.extend(runtime_stack_ranges(runtime_info))
                    else:
                        used_stack_offsets.append((
                            access_offset,
                            INIT_ACCESS_SLOT_WIDTH,
                        ))
                    if debug_runtime_recipe:
                        DEBUG(f"scaled_address_value_selected {({
                            'symbol': str(symbol),
                            'value': hex(value),
                            'access_offset': access_offset,
                            'runtime_recipe': runtime_info,
                        })}")
                    return value
            if debug_runtime_recipe:
                DEBUG(f"scaled_address_value_unavailable {({
                    'symbol': str(symbol),
                    'candidate_count': len(candidates),
                })}")
            return None

        def is_power_of_two_scaled_affine(expr, symbol):
            scaled = scaled_symbol_affine(expr, symbol)
            if scaled is None:
                return False
            scale = scaled[0]
            return not (scale & (scale - 1))

        loaded_affine_quotient_choices = {}
        loaded_affine_quotient_runtime_accesses = {}

        def choose_affine_quotient_loaded_address_value(
            symbol,
            load_idx,
            require_explicit_livein_constraints=False,
        ):
            """Choose a runtime-SP quotient for a scaled loaded address value."""
            choice_key = (load_idx, expr_key(symbol))
            if choice_key in loaded_affine_quotient_choices:
                return loaded_affine_quotient_choices[choice_key]
            symbol_vars = expr_vars(symbol)
            if not symbol_vars:
                return None

            related_accesses = []
            runtime_accesses = []
            affine_constraints = []
            affine_constraint_keys = set()
            affine_constraint_vars = set()
            livein_vars = set()
            for livein_symbol in reg_to_symbol.values():
                livein_vars.update(expr_vars(livein_symbol))
            loaded_value_vars = set()
            for _, loaded_symbol, _, _ in load_accesses:
                loaded_value_vars.update(expr_vars(loaded_symbol))
            used_explicit_livein_constraints = False
            for access_inst, addr_symbol, access_idx, width in mem_accesses:
                if access_idx <= load_idx or not (expr_vars(addr_symbol) & symbol_vars):
                    continue
                scaled = scaled_symbol_affine(addr_symbol, symbol)
                if scaled is None:
                    return None
                scale, const, constraints = scaled
                if constraints:
                    implication_solver = candidate_solver.branch()
                    implication_solver.timeout = HEURISTIC_SOLVER_TIMEOUT_MS
                    try:
                        implication_solver.add(
                            claripy.Not(claripy.And(*constraints))
                        )
                        if implication_solver.satisfiable():
                            if (
                                scale <= RUNTIME_SP_ALIGNMENT
                                or scale & (scale - 1)
                            ):
                                return None
                            constraint_vars = set().union(*(
                                expr_vars(constraint)
                                for constraint in constraints
                            ))
                            if (
                                not constraint_vars
                                or not constraint_vars <= livein_vars
                                or constraint_vars & loaded_value_vars
                            ):
                                return None
                            for constraint in constraints:
                                key = str(claripy.simplify(constraint))
                                if key in affine_constraint_keys:
                                    continue
                                affine_constraint_keys.add(key)
                                affine_constraints.append(constraint)
                            for livein_symbol in reg_to_symbol.values():
                                if not (expr_vars(livein_symbol) & constraint_vars):
                                    continue
                                zero_constraint = (
                                    livein_symbol == expr_bvv(0, livein_symbol)
                                )
                                key = str(claripy.simplify(zero_constraint))
                                if key in affine_constraint_keys:
                                    continue
                                affine_constraint_keys.add(key)
                                affine_constraints.append(zero_constraint)
                            affine_constraint_vars.update(constraint_vars)
                            used_explicit_livein_constraints = True
                    except Exception:
                        return None
                related_accesses.append((addr_symbol, width, scale, _signed_u64(const)))
                runtime_accesses.append((
                    access_idx,
                    _signed_u64(const),
                    width,
                    access_inst.type == IType.Load,
                ))
            if not related_accesses:
                return None
            if (
                require_explicit_livein_constraints
                and not used_explicit_livein_constraints
            ):
                return None

            scales = {scale for _, _, scale, _ in related_accesses}
            if len(scales) != 1:
                return None
            scale = next(iter(scales))
            if scale <= 1 or scale > MAX_AFFINE_QUOTIENT_SCALE:
                return None
            # Shift recipes are exact only up to the guaranteed SP alignment.
            if not (scale & (scale - 1)) and scale <= RUNTIME_SP_ALIGNMENT:
                return None

            primary_addr, primary_width, _, primary_const = related_accesses[0]
            align = primary_width if primary_width > 1 else 1
            starts = [align, INIT_PTR_MIN_OFFSET]
            preferred = next_free_stack_offset(
                used_stack_offsets,
                align=align,
                width=INIT_ACCESS_SLOT_WIDTH,
                start=align,
            )
            if preferred is not None:
                starts.insert(0, preferred)
            starts.extend(
                used_offset + max(primary_width, used_width)
                for used_offset, used_width in used_stack_offsets
            )

            seen_offsets = set()
            mask = (1 << 64) - 1
            for start in starts:
                start = _align_up(max(1, start), align)
                for access_offset in range(start, STACK_RANGE + 1, align):
                    if access_offset in seen_offsets:
                        continue
                    seen_offsets.add(access_offset)
                    numerator_offset = access_offset + primary_const
                    numerator = (CONCRETE_REPLAY_SP - numerator_offset) & mask
                    if numerator % scale:
                        continue
                    remainders = _affine_quotient_remainders(
                        numerator_offset,
                        scale,
                    )
                    if not remainders:
                        continue

                    group_targets = []
                    group_ranges = []
                    runtime_safe = True
                    for addr_symbol, width, _, addr_const in related_accesses:
                        base_offset = access_offset + primary_const - addr_const
                        for remainder in remainders:
                            actual_offset = base_offset + remainder
                            if (
                                actual_offset < max(1, width)
                                or actual_offset > STACK_RANGE
                                or (width > 1 and actual_offset % width)
                                or any(
                                    concrete_ranges_overlap(
                                        actual_offset,
                                        width,
                                        used_offset,
                                        used_width,
                                    )
                                    for used_offset, used_width in used_stack_offsets
                                )
                            ):
                                runtime_safe = False
                                break
                        if not runtime_safe:
                            break
                        group_targets.append(
                            (addr_symbol, concrete_stack_addr(base_offset))
                        )
                        group_ranges.append((base_offset, width))
                    if not runtime_safe:
                        continue

                    value = numerator // scale
                    constraints = list(affine_constraints)
                    constraints.append(symbol == expr_bvv(value, symbol))
                    constraints.extend(
                        addr_symbol == target_addr
                        for addr_symbol, target_addr in group_targets
                    )
                    if not (
                        try_add_constraint_set_fast(constraints, timeout_ms=5000)
                        or try_add_constraint_set_related(
                            constraints,
                            symbol_vars | affine_constraint_vars,
                            timeout_ms=5000,
                        )
                    ):
                        continue

                    max_remainder = max(remainders)
                    for base_offset, width in group_ranges:
                        used_stack_offsets.append((
                            base_offset + max_remainder,
                            width + max_remainder,
                        ))
                    recipe = (
                        'affine_quotient',
                        numerator_offset,
                        scale,
                    )
                    if os.environ.get("RVMCA_DEBUG_REPAIR") == "1":
                        DEBUG(f"loaded_affine_quotient_selected {({
                            'value': hex(value),
                            'recipe': recipe,
                            'remainders': remainders,
                            'access_count': len(related_accesses),
                        })}")
                    choice = (value, recipe)
                    loaded_affine_quotient_choices[choice_key] = choice
                    loaded_affine_quotient_runtime_accesses[choice_key] = (
                        recipe,
                        tuple(runtime_accesses),
                    )
                    return choice
            return None

        def choose_scaled_loaded_address_value(symbol):
            symbol_vars = expr_vars(symbol)
            if not symbol_vars:
                return None
            related_accesses = [
                (addr_symbol, width)
                for _, addr_symbol, _, width in mem_accesses
                if expr_vars(addr_symbol) & symbol_vars
            ]
            if not related_accesses:
                return None

            mask = (1 << 64) - 1
            zero_residual_candidates = []
            seen_zero_residual_candidates = set()

            def add_zero_residual_candidate(value):
                if value is None:
                    return
                value &= mask
                if value in seen_zero_residual_candidates:
                    return
                seen_zero_residual_candidates.add(value)
                zero_residual_candidates.append(value)

            def candidate_values_from_constraints(constraints):
                values = []
                symbol_key = expr_key(symbol)
                for constraint in constraints:
                    if getattr(constraint, 'op', None) not in {'__eq__', 'BoolS'}:
                        continue
                    args = [
                        arg for arg in getattr(constraint, 'args', ())
                        if hasattr(arg, 'op')
                    ]
                    if len(args) != 2:
                        continue
                    lhs, rhs = args
                    if expr_key(lhs) == symbol_key and not expr_vars(rhs):
                        value = concrete_expr_value(rhs)
                    elif expr_key(rhs) == symbol_key and not expr_vars(lhs):
                        value = concrete_expr_value(lhs)
                    else:
                        value = None
                    if value is not None:
                        values.append(value & mask)
                return values

            for addr_symbol, _ in related_accesses:
                for load_inst, loaded_symbol, _, _ in load_accesses:
                    if load_inst.width != 8:
                        continue
                    loaded_vars = expr_vars(loaded_symbol)
                    if not loaded_vars or not (expr_vars(addr_symbol) & loaded_vars):
                        continue
                    residual = additive_residual_without_term(addr_symbol, loaded_symbol)
                    if residual is None:
                        residual = claripy.simplify(addr_symbol - loaded_symbol)
                    residual_vars = expr_vars(residual)
                    if not (residual_vars & symbol_vars) or (residual_vars & loaded_vars):
                        continue
                    residual_constraints = constraints_to_constant(
                        residual,
                        0,
                        forbidden_vars=loaded_vars,
                    )
                    if residual_constraints is None:
                        continue
                    for value in candidate_values_from_constraints(residual_constraints):
                        add_zero_residual_candidate(value)

            if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD:
                candidates = list(zero_residual_candidates) + [0, 1]
                seen_candidates = set()
                for candidate in candidates:
                    candidate &= mask
                    if candidate in seen_candidates:
                        continue
                    seen_candidates.add(candidate)
                    constraint = symbol == expr_bvv(candidate, symbol)
                    if try_add_constraint_set_related(
                        [constraint],
                        symbol_vars,
                        timeout_ms=local_solver_timeout_ms,
                    ):
                        return candidate
                return None
            candidates = list(zero_residual_candidates) + [0, 1]
            for value in range(1, 257):
                candidates.append((-value) & mask)
            for value in range(2, 65):
                candidates.append(value)
            for value in (512, 1024, 2048, (-512) & mask, (-1024) & mask, (-2048) & mask):
                candidates.append(value)

            def concrete_int(value):
                if value is None:
                    return None
                if isinstance(value, int):
                    return value & mask
                if hasattr(value, 'op'):
                    value = concrete_expr_value(value)
                    if value is None or hasattr(value, 'op'):
                        return None
                if isinstance(value, int):
                    return value & mask
                concrete_value = getattr(value, 'concrete_value', None)
                if isinstance(concrete_value, int):
                    return concrete_value & mask
                try:
                    return int(value) & mask
                except Exception:
                    return None

            seen = set()
            for candidate in candidates:
                candidate &= mask
                if candidate in seen:
                    continue
                seen.add(candidate)
                candidate_constraints = [symbol == expr_bvv(candidate, symbol)]
                checked = 0
                ok = True
                for addr_symbol, width in related_accesses:
                    offset_expr = init_sp - addr_symbol
                    candidate_constraints.extend([
                        claripy.UGT(offset_expr, claripy.BVV(0, 64)),
                        claripy.ULE(offset_expr, claripy.BVV(STACK_RANGE, 64)),
                        claripy.ULT(addr_symbol, init_sp),
                    ])
                    if width > 1:
                        candidate_constraints.append((addr_symbol & (width - 1)) == 0)
                    concrete_addr = concrete_value_from_materialized_with(
                        addr_symbol,
                        [(symbol, candidate)],
                    )
                    concrete_addr = concrete_int(concrete_addr)
                    if concrete_addr is None:
                        continue
                    checked += 1
                    concrete_offset = (CONCRETE_REPLAY_SP - concrete_addr) & mask
                    if concrete_addr >= CONCRETE_REPLAY_SP or concrete_offset <= 0 or concrete_offset > STACK_RANGE:
                        ok = False
                        break
                    if width > 1 and concrete_addr % width:
                        ok = False
                        break
                if not ok:
                    continue
                if try_add_constraint_set_fast(candidate_constraints, timeout_ms=100):
                    return candidate
            return None

        def choose_memory_value(
            expr,
            preferred=None,
            avoid_stack_offsets=None,
            pointer_like=False,
            min_pointer_offset=None,
            allow_pointer_scalar_fallback=True,
            pointer_candidate_ok=None,
            pointer_alias_exprs=None,
        ):
            avoid_stack_offsets = [] if avoid_stack_offsets is None else avoid_stack_offsets
            pointer_alias_exprs = [] if pointer_alias_exprs is None else pointer_alias_exprs
            if pointer_like:
                offset_expr = init_sp - expr
                pointer_vars = expr_vars(expr)
                start_offset = INIT_PTR_MIN_OFFSET if min_pointer_offset is None else max(0, min_pointer_offset)
                long_block = len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                pointer_candidate_limit = 16 if long_block else 32
                pointer_relaxed_candidate_limit = 4 if long_block else pointer_candidate_limit
                pointer_eval_limit = 4 if long_block else 128
                pointer_confirm_timeout_ms = local_solver_timeout_ms if long_block else 5000
                pointer_related_timeout_ms = 250 if long_block else max(pointer_confirm_timeout_ms, 1000)
                pointer_store_relative_offsets = None
                pointer_relative_targets = (-8, -4, 0, 4, 8, -12, 12, -16, 16)
                pointer_debug_enabled = os.environ.get("RVMCA_DEBUG_POINTER_VALUE") == "1"

                def debug_pointer_residual(event, **fields):
                    if pointer_debug_enabled:
                        DEBUG(f"pointer_residual_{event} {fields}")

                def pointer_value_allowed(value):
                    if pointer_candidate_ok is None:
                        return True
                    try:
                        return bool(pointer_candidate_ok(value & ((1 << 64) - 1)))
                    except Exception:
                        return False

                def dedupe_constraint_list(constraints):
                    result = []
                    seen = set()
                    for constraint in constraints:
                        key = str(claripy.simplify(constraint))
                        if key in seen:
                            continue
                        seen.add(key)
                        result.append(constraint)
                    return result

                def residual_constraints_satisfiable(constraints):
                    constraints = dedupe_constraint_list(constraints)
                    if not constraints:
                        return True
                    if long_block:
                        test_solver = claripy.Solver()
                        test_solver.timeout = pointer_confirm_timeout_ms
                        try:
                            for constraint in constraints:
                                test_solver.add(constraint)
                            return test_solver.satisfiable()
                        except Exception:
                            return False
                    anchor_vars = expr_vars(init_sp)
                    closure = set()
                    for constraint in constraints:
                        closure.update(getattr(constraint, 'variables', set()) - anchor_vars)

                    selected = []
                    if closure:
                        selected_ids = set()
                        changed = True
                        while changed:
                            changed = False
                            for existing in candidate_solver.constraints:
                                existing_id = id(existing)
                                if existing_id in selected_ids:
                                    continue
                                existing_vars = getattr(existing, 'variables', set()) - anchor_vars
                                if not (existing_vars & closure):
                                    continue
                                selected_ids.add(existing_id)
                                selected.append(existing)
                                new_vars = existing_vars - closure
                                if new_vars:
                                    closure.update(new_vars)
                                    changed = True

                    test_solver = claripy.Solver()
                    test_solver.timeout = pointer_confirm_timeout_ms if long_block else pointer_related_timeout_ms
                    try:
                        for constraint in selected:
                            test_solver.add(constraint)
                        for constraint in constraints:
                            test_solver.add(constraint)
                        return test_solver.satisfiable()
                    except Exception:
                        local_solver = claripy.Solver()
                        local_solver.timeout = pointer_related_timeout_ms
                        try:
                            for constraint in constraints:
                                local_solver.add(constraint)
                            return local_solver.satisfiable()
                        except Exception:
                            return False

                def current_constrained_residual_value(residual):
                    residual_vars = set(expr_vars(residual)) - set(expr_vars(init_sp))
                    if not residual_vars:
                        value = concrete_expr_value(residual)
                        return None if value is None else _signed_u64(value)
                    if long_block:
                        return None
                    if long_block and ast_node_count(residual) > 128:
                        return None

                    selected = []
                    selected_ids = set()
                    closure = set(residual_vars)
                    changed = True
                    while changed:
                        changed = False
                        for constraint in candidate_solver.constraints:
                            constraint_id = id(constraint)
                            if constraint_id in selected_ids:
                                continue
                            constraint_vars = set(getattr(constraint, 'variables', set())) - set(expr_vars(init_sp))
                            if not (constraint_vars & closure):
                                continue
                            selected_ids.add(constraint_id)
                            selected.append(constraint)
                            new_vars = constraint_vars - closure
                            if new_vars:
                                closure.update(new_vars)
                                changed = True

                    test_solver = claripy.Solver()
                    test_solver.timeout = pointer_confirm_timeout_ms if long_block else pointer_related_timeout_ms
                    try:
                        for constraint in selected:
                            test_solver.add(constraint)
                        if not test_solver.satisfiable():
                            return None
                        values = test_solver.eval(residual, 2)
                    except Exception:
                        return None
                    normalized = []
                    seen_values = set()
                    for value in values:
                        try:
                            int_value = int(value) & ((1 << residual.size()) - 1)
                        except Exception:
                            concrete_value = getattr(value, 'concrete_value', None)
                            if not isinstance(concrete_value, int):
                                continue
                            int_value = concrete_value & ((1 << residual.size()) - 1)
                        if int_value in seen_values:
                            continue
                        seen_values.add(int_value)
                        normalized.append(int_value)
                    if len(normalized) != 1:
                        return None

                    verify_solver = claripy.Solver()
                    verify_solver.timeout = pointer_confirm_timeout_ms if long_block else pointer_related_timeout_ms
                    try:
                        for constraint in selected:
                            verify_solver.add(constraint)
                        verify_solver.add(residual != expr_bvv(normalized[0], residual))
                        if verify_solver.satisfiable():
                            return None
                    except Exception:
                        return None
                    return _signed_u64(normalized[0])

                def commit_pointer_constraints_heuristic(constraints):
                    if not long_block:
                        return False
                    constraints = dedupe_constraint_list(constraints)
                    if not constraints:
                        return True
                    seed_vars = set()
                    for constraint in constraints:
                        seed_vars.update(getattr(constraint, 'variables', set()))
                    return (
                        try_add_constraint_set_fast(
                            constraints,
                            timeout_ms=pointer_confirm_timeout_ms,
                        )
                        or try_add_constraint_set_related(
                            constraints,
                            seed_vars,
                            timeout_ms=pointer_related_timeout_ms,
                        )
                    )

                def constraints_already_added(constraints):
                    for constraint in dedupe_constraint_list(constraints):
                        constraint_key = str(claripy.simplify(constraint))
                        if constraint_key not in added_constraint_cache:
                            return False
                    return True

                def add_constraints_assuming_sat(constraints, source):
                    for constraint in dedupe_constraint_list(constraints):
                        candidate_solver.add(constraint)
                        added_constraint_cache.add(str(claripy.simplify(constraint)))
                        debug_constraint_add(source, constraint)

                def pointer_residual_options(residual):
                    residual_vars = expr_vars(residual)
                    if residual_vars & pointer_vars:
                        debug_pointer_residual(
                            "reject_self",
                            expr=str(expr),
                            residual=str(residual),
                            vars=sorted(residual_vars & pointer_vars),
                        )
                        return []
                    other_pointer_vars = set(pointer_loaded_addr_vars) - set(pointer_vars)
                    if residual_vars & other_pointer_vars:
                        debug_pointer_residual(
                            "reject_other_pointer",
                            expr=str(expr),
                            residual=str(residual),
                            vars=sorted(residual_vars & other_pointer_vars),
                        )
                        return []

                    residual_value = concrete_expr_value(residual)
                    if residual_value is not None:
                        return [(_signed_u64(residual_value), [])]

                    options = []
                    seen_targets = set()
                    seen_option_keys = set()

                    def add_residual_option(target, constraints):
                        constraints = dedupe_constraint_list(constraints)
                        option_key = (
                            target & ((1 << 64) - 1),
                            tuple(str(claripy.simplify(constraint)) for constraint in constraints),
                        )
                        if option_key in seen_option_keys:
                            return False
                        seen_option_keys.add(option_key)
                        if not residual_constraints_satisfiable(constraints):
                            debug_pointer_residual(
                                "option_unsat",
                                expr=str(expr),
                                target=target,
                                constraints=[str(c) for c in constraints],
                            )
                            return False
                        options.append((target, constraints))
                        seen_targets.add(target & ((1 << 64) - 1))
                        return True

                    def add_direct_residual_option(target):
                        constraint = residual == expr_bvv(target, residual)
                        return add_residual_option(target, [constraint])

                    current_value = current_constrained_residual_value(residual)
                    if current_value is not None:
                        debug_pointer_residual(
                            "current_value",
                            expr=str(expr),
                            residual=str(residual),
                            target=current_value,
                        )
                        add_residual_option(current_value, [])

                    residual_affine = affine_base_const(residual)
                    if residual_affine is not None:
                        _, residual_imm = residual_affine
                        residual_imm = _signed_u64(residual_imm)
                        residual_constraints = constraints_to_constant(
                            residual,
                            residual_imm & ((1 << 64) - 1),
                            forbidden_vars=pointer_vars | other_pointer_vars,
                        )
                        if residual_constraints is not None:
                            add_residual_option(residual_imm, list(residual_constraints))
                        elif (residual_imm & ((1 << 64) - 1)) == 0:
                            for _, zero_constraints, _ in multiplicative_zero_residual_constraint_options(
                                residual,
                                forbidden_vars=pointer_vars | other_pointer_vars,
                                direct_pointer_guard=True,
                                timeout_ms=pointer_confirm_timeout_ms,
                            ):
                                add_residual_option(residual_imm, list(zero_constraints))
                        if (residual_imm & ((1 << 64) - 1)) not in seen_targets:
                            add_direct_residual_option(residual_imm)

                    for target in pointer_relative_targets:
                        target_key = target & ((1 << 64) - 1)
                        if target_key in seen_targets:
                            continue
                        residual_constraints = constraints_to_constant(
                            residual,
                            target_key,
                            forbidden_vars=pointer_vars | other_pointer_vars,
                        )
                        if residual_constraints is not None and add_residual_option(
                            target,
                            list(residual_constraints),
                        ):
                            continue
                        if target_key == 0:
                            for _, zero_constraints, _ in multiplicative_zero_residual_constraint_options(
                                residual,
                                forbidden_vars=pointer_vars | other_pointer_vars,
                                direct_pointer_guard=True,
                                timeout_ms=pointer_confirm_timeout_ms,
                            ):
                                add_residual_option(target, list(zero_constraints))
                            if target_key in seen_targets:
                                continue
                        add_direct_residual_option(target)
                    if not options:
                        debug_pointer_residual(
                            "no_options",
                            expr=str(expr),
                            residual=str(residual),
                            vars=sorted(residual_vars),
                        )
                    return options

                def get_pointer_store_relative_offsets():
                    nonlocal pointer_store_relative_offsets
                    if pointer_store_relative_offsets is not None:
                        return pointer_store_relative_offsets
                    result = []
                    selected_relative_constraints = []
                    if pointer_vars:
                        checked = 0
                        for access_inst, access_addr_symbol, _, access_width in mem_accesses:
                            if not (expr_vars(access_addr_symbol) & pointer_vars):
                                continue
                            if long_block:
                                if checked >= 8:
                                    break
                                if ast_node_count(access_addr_symbol) > 96 or ast_node_count(expr) > 96:
                                    debug_pointer_residual(
                                        "skip_complex",
                                        expr=str(expr),
                                        access=str(access_addr_symbol),
                                        access_nodes=ast_node_count(access_addr_symbol),
                                        expr_nodes=ast_node_count(expr),
                                    )
                                    continue
                                checked += 1
                            residual = claripy.simplify(access_addr_symbol - expr)
                            residual_options = pointer_residual_options(residual)
                            if not residual_options:
                                debug_pointer_residual(
                                    "no_relative_option",
                                    expr=str(expr),
                                    access=str(access_addr_symbol),
                                    residual=str(residual),
                                    residual_vars=sorted(expr_vars(residual)),
                                )
                                continue
                            selected_option = None
                            for imm, residual_constraints in residual_options:
                                combined_constraints = dedupe_constraint_list(
                                    selected_relative_constraints + list(residual_constraints)
                                )
                                if residual_constraints_satisfiable(combined_constraints):
                                    selected_option = (imm, residual_constraints, combined_constraints)
                                    break
                            if selected_option is None:
                                debug_pointer_residual(
                                    "no_compatible_relative_option",
                                    expr=str(expr),
                                    access=str(access_addr_symbol),
                                    residual=str(residual),
                                )
                                continue
                            imm, residual_constraints, selected_relative_constraints = selected_option
                            debug_pointer_residual(
                                "relative_option",
                                expr=str(expr),
                                access=str(access_addr_symbol),
                                imm=imm,
                                constraints=[str(c) for c in residual_constraints],
                            )
                            result.append((
                                imm,
                                init_slot_width(access_width),
                                access_width,
                                dedupe_constraint_list(residual_constraints),
                            ))
                    pointer_store_relative_offsets = result
                    return pointer_store_relative_offsets

                def pointer_store_relative_constraints():
                    constraints = []
                    for _, _, _, residual_constraints in get_pointer_store_relative_offsets():
                        constraints.extend(residual_constraints)
                    return dedupe_constraint_list(constraints)

                def pointer_store_ranges_for_offset(offset):
                    relative_offsets = get_pointer_store_relative_offsets()
                    ranges = [] if relative_offsets else [(offset, 8)]
                    for imm, store_width, access_width, _ in relative_offsets:
                        access_offset = offset - imm
                        if access_offset <= 0 or access_offset > STACK_RANGE:
                            return None
                        if access_width > 1 and access_offset % access_width:
                            return None
                        slot_offset = access_offset
                        if access_width < 8:
                            access_word_offset = ((access_offset + 7) // 8) * 8
                            byte_offset = access_word_offset - access_offset
                            if byte_offset < 0 or byte_offset + access_width > 8:
                                return None
                            slot_offset = access_word_offset
                            access_slot = mem_slot_symbols.get(access_word_offset)
                            if access_slot is not None and (
                                access_slot.get('pointer_like')
                                or access_slot.get('must_be_pointer')
                                or access_slot.get('sp_affine')
                            ):
                                return None
                        ranges.append((slot_offset, store_width))
                    return ranges

                def pointer_offset_search_upper():
                    upper = STACK_RANGE
                    for imm, _store_width, _access_width, _ in get_pointer_store_relative_offsets():
                        signed_imm = _signed_u64(imm)
                        if signed_imm > 0:
                            upper = max(upper, STACK_RANGE + min(signed_imm, STACK_RANGE))
                    return upper

                def pointer_offset_value_ok(offset):
                    if offset <= 0:
                        return False
                    if offset <= STACK_RANGE:
                        return True
                    if not get_pointer_store_relative_offsets():
                        return False
                    return pointer_store_ranges_for_offset(offset) is not None

                def pointer_offset_conflicts(offset, avoid_ranges):
                    ranges = pointer_store_ranges_for_offset(offset)
                    if ranges is None:
                        return True
                    return any(
                        concrete_ranges_overlap(access_offset, access_width, used_offset, used_width)
                        and not (
                            access_offset == used_offset
                            and access_width == used_width
                        )
                        for access_offset, access_width in ranges
                        for used_offset, used_width in avoid_ranges
                    )

                def known_access_relative_constraints_for_offset(offset):
                    constraints = []
                    saw_known_access = False
                    for _, access_addr_symbol, _, access_width in mem_accesses:
                        if not (expr_vars(access_addr_symbol) & pointer_vars):
                            continue
                        known_access_offset = addr_expr_offsets.get(expr_key(access_addr_symbol))
                        if known_access_offset is None:
                            continue
                        if known_access_offset <= 0 or known_access_offset > STACK_RANGE:
                            return None
                        if access_width > 1 and known_access_offset % access_width:
                            return None
                        residual = claripy.simplify(access_addr_symbol - expr)
                        residual_vars = expr_vars(residual)
                        if residual_vars & pointer_vars:
                            return None
                        target = (offset - known_access_offset) & ((1 << 64) - 1)
                        residual_constraints = constraints_to_constant(
                            residual,
                            target,
                            forbidden_vars=pointer_vars,
                        )
                        if residual_constraints is None:
                            residual_constraints = [residual == expr_bvv(target, residual)]
                            if not residual_constraints_satisfiable(residual_constraints):
                                return None
                        constraints.extend(residual_constraints)
                        saw_known_access = True
                    if not saw_known_access:
                        return []
                    return dedupe_constraint_list(constraints)

                def has_known_related_access_offsets():
                    return any(
                        (expr_vars(access_addr_symbol) & pointer_vars)
                        and expr_key(access_addr_symbol) in addr_expr_offsets
                        for _, access_addr_symbol, _, _ in mem_accesses
                    )

                def next_available_pointer_offset(offset, avoid_ranges):
                    relative_offsets = get_pointer_store_relative_offsets()
                    offset = max(offset, start_offset)
                    if not relative_offsets:
                        offset = _align_up(offset, INIT_ACCESS_ALIGN)
                    step = 1 if relative_offsets else INIT_ACCESS_ALIGN
                    search_upper = pointer_offset_search_upper()
                    while offset <= search_upper:
                        if not pointer_offset_value_ok(offset):
                            offset += step
                            continue
                        if not pointer_offset_conflicts(offset, avoid_ranges):
                            return offset
                        offset += step
                    return None

                def pointer_offset_candidates(avoid_ranges, limit=None):
                    starts = [start_offset]
                    starts.extend(used_offset + max(8, used_width) for used_offset, used_width in avoid_ranges)
                    yielded = 0
                    seen_offsets = set()
                    for start in sorted(starts):
                        offset = next_available_pointer_offset(start, avoid_ranges)
                        while offset is not None and offset <= STACK_RANGE and offset not in seen_offsets:
                            seen_offsets.add(offset)
                            yield offset
                            yielded += 1
                            if limit is not None and yielded >= limit:
                                return
                            offset = next_available_pointer_offset(offset + INIT_ACCESS_ALIGN, avoid_ranges)

                def derived_pointer_offset_candidates(avoid_ranges, limit=None):
                    candidates = []
                    for imm, store_width, _access_width, _ in get_pointer_store_relative_offsets():
                        for used_offset, used_width in avoid_ranges:
                            if used_width != store_width:
                                continue
                            candidates.append(used_offset + imm)
                    yielded = 0
                    seen_offsets = set()
                    for offset in sorted(candidates):
                        if offset in seen_offsets:
                            continue
                        seen_offsets.add(offset)
                        if offset < start_offset or not pointer_offset_value_ok(offset):
                            continue
                        if pointer_offset_conflicts(offset, avoid_ranges):
                            continue
                        yield offset
                        yielded += 1
                        if limit is not None and yielded >= limit:
                            return

                def choose_pointer_access_anchor(avoid_ranges, relaxed=False, limit=None):
                    if not pointer_vars:
                        return None
                    mask = (1 << 64) - 1
                    residual_targets = (0, -4, 4, 8, -8, 12, -12, 16, -16)
                    checked_accesses = 0
                    selected = 0

                    def access_slot_range(access_offset, access_width):
                        word_offset = ((access_offset + 7) // 8) * 8
                        byte_offset = word_offset - access_offset
                        if byte_offset < 0 or byte_offset + access_width > 8:
                            return None
                        return word_offset, init_slot_width(access_width)

                    def access_slot_conflicts(slot_offset, slot_width):
                        return any(
                            concrete_ranges_overlap(slot_offset, slot_width, used_offset, used_width)
                            and not (
                                slot_offset == used_offset
                                and slot_width == used_width
                            )
                            for used_offset, used_width in avoid_ranges
                        )

                    for _, access_addr_symbol, _, access_width in mem_accesses:
                        if not (expr_vars(access_addr_symbol) & pointer_vars):
                            continue
                        known_access_offset = addr_expr_offsets.get(expr_key(access_addr_symbol))
                        if long_block:
                            if checked_accesses >= 8:
                                break
                            if (
                                known_access_offset is None
                                and (ast_node_count(access_addr_symbol) > 128 or ast_node_count(expr) > 96)
                            ):
                                continue
                            checked_accesses += 1
                        residual = claripy.simplify(access_addr_symbol - expr)
                        residual_vars = expr_vars(residual)
                        if residual_vars & pointer_vars:
                            continue

                        if known_access_offset is None:
                            continue
                        if known_access_offset <= 0 or known_access_offset > STACK_RANGE:
                            continue
                        if access_width > 1 and known_access_offset % access_width:
                            continue
                        slot_range = access_slot_range(known_access_offset, access_width)
                        if slot_range is None:
                            continue
                        slot_offset, slot_width = slot_range
                        if not relaxed and access_slot_conflicts(slot_offset, slot_width):
                            continue

                        residual_options = pointer_residual_options(residual)
                        if not residual_options:
                            seen_targets = set()
                            for target in residual_targets:
                                target_key = target & mask
                                if target_key in seen_targets:
                                    continue
                                seen_targets.add(target_key)
                                residual_constraints = constraints_to_constant(
                                    residual,
                                    target_key,
                                    forbidden_vars=pointer_vars,
                                )
                                if residual_constraints is None:
                                    continue
                                residual_options.append((target, list(residual_constraints)))
                        for residual_target, residual_constraints in residual_options:
                            pointer_offset = known_access_offset + residual_target
                            if not pointer_offset_value_ok(pointer_offset):
                                continue
                            if pointer_store_ranges_for_offset(pointer_offset) is None:
                                continue
                            if not relaxed and pointer_offset_conflicts(pointer_offset, avoid_ranges):
                                continue
                            value = concrete_stack_addr(pointer_offset)
                            relative_constraints = dedupe_constraint_list(
                                list(residual_constraints)
                                + pointer_store_relative_constraints()
                            )
                            if not pointer_value_allowed(value) and not relative_constraints:
                                continue
                            constraints = relative_constraints + [
                                expr == expr_bvv(value, expr),
                                offset_expr == pointer_offset,
                                (init_sp - access_addr_symbol) == known_access_offset,
                            ]
                            if (
                                try_add_constraint_set_fast(
                                    constraints,
                                    timeout_ms=pointer_confirm_timeout_ms,
                                )
                                or try_add_constraint_set_related(
                                    constraints,
                                    pointer_vars | expr_vars(access_addr_symbol),
                                    timeout_ms=pointer_related_timeout_ms,
                                )
                            ):
                                if verbose:
                                    label = (
                                        'choose_pointer_like_access_anchor_relaxed_selected'
                                        if relaxed
                                        else 'choose_pointer_like_access_anchor_selected'
                                    )
                                    print(label, str(expr), pointer_offset, known_access_offset, residual_target)
                                return value
                            selected += 1
                            if limit is not None and selected >= limit:
                                return None
                    return None

                def choose_pointer_affine_base_anchor(avoid_ranges, relaxed=False, limit=None):
                    if not pointer_vars:
                        return None
                    mask = (1 << 64) - 1
                    selected = 0

                    def access_slot_range(access_offset, access_width):
                        word_offset = ((access_offset + 7) // 8) * 8
                        byte_offset = word_offset - access_offset
                        if byte_offset < 0 or byte_offset + access_width > 8:
                            return None
                        return word_offset, init_slot_width(access_width)

                    def access_slot_conflicts(slot_offset, slot_width):
                        return any(
                            concrete_ranges_overlap(slot_offset, slot_width, used_offset, used_width)
                            and not (
                                slot_offset == used_offset
                                and slot_width == used_width
                            )
                            for used_offset, used_width in avoid_ranges
                        )

                    for _, access_addr_symbol, _, access_width in mem_accesses:
                        if not (expr_vars(access_addr_symbol) & pointer_vars):
                            continue
                        known_access_offset = addr_expr_offsets.get(expr_key(access_addr_symbol))
                        if known_access_offset is None:
                            continue
                        if known_access_offset <= 0 or known_access_offset > STACK_RANGE:
                            continue
                        if access_width > 1 and known_access_offset % access_width:
                            continue
                        slot_range = access_slot_range(known_access_offset, access_width)
                        if slot_range is None:
                            continue
                        slot_offset, slot_width = slot_range
                        if not relaxed and access_slot_conflicts(slot_offset, slot_width):
                            continue
                        residual = claripy.simplify(access_addr_symbol - expr)
                        residual_vars = expr_vars(residual)
                        if residual_vars & pointer_vars:
                            continue
                        residual_options = pointer_residual_options(residual)
                        if not residual_options:
                            continue
                        for residual_target, residual_constraints in residual_options:
                            value = (
                                concrete_stack_addr(known_access_offset)
                                - (residual_target & mask)
                            ) & mask
                            if not pointer_value_allowed(value) and not residual_constraints:
                                continue
                            constraints = dedupe_constraint_list(
                                list(residual_constraints)
                                + pointer_store_relative_constraints()
                            ) + [
                                expr == expr_bvv(value, expr),
                                (init_sp - access_addr_symbol) == known_access_offset,
                            ]
                            if (
                                try_add_constraint_set_fast(
                                    constraints,
                                    timeout_ms=pointer_confirm_timeout_ms,
                                )
                                or try_add_constraint_set_related(
                                    constraints,
                                    pointer_vars | expr_vars(access_addr_symbol),
                                    timeout_ms=pointer_related_timeout_ms,
                                )
                            ):
                                if verbose:
                                    label = (
                                        'choose_pointer_like_affine_base_relaxed_selected'
                                        if relaxed
                                        else 'choose_pointer_like_affine_base_selected'
                                    )
                                    print(label, str(expr), known_access_offset, residual_target)
                                return value
                            selected += 1
                            if limit is not None and selected >= limit:
                                return None
                    return None

                def choose_pointer_offset(offset, relaxed=False):
                    conflict = (not relaxed and pointer_offset_conflicts(offset, avoid_stack_offsets))
                    if os.environ.get("RVMCA_DEBUG_POINTER_VALUE") == "1":
                        DEBUG(f"pointer_value_candidate {({
                            'expr': str(expr),
                            'offset': offset,
                            'relaxed': relaxed,
                            'conflict': conflict,
                            'relative_offsets': get_pointer_store_relative_offsets(),
                        })}")
                    if conflict:
                        return None
                    value = concrete_stack_addr(offset)
                    known_relative_constraints = known_access_relative_constraints_for_offset(offset)
                    if known_relative_constraints is None:
                        return None
                    relative_constraints = (
                        known_relative_constraints
                        if known_relative_constraints
                        else pointer_store_relative_constraints()
                    )
                    if not pointer_value_allowed(value):
                        if not relative_constraints:
                            return None
                        if pointer_debug_enabled:
                            DEBUG(f"pointer_value_precheck_deferred {({
                                'expr': str(expr),
                                'offset': offset,
                                'relative_constraints': [str(c) for c in relative_constraints],
                            })}")
                    if relative_constraints:
                        offset_constraints = relative_constraints + [
                            offset_expr == offset,
                        ]
                        simple_long_relative = long_block and simple_long_block_relative_offsets()
                        if simple_long_relative and (
                            constraints_already_added(relative_constraints)
                            or ast_node_count(expr) <= 32
                        ):
                            touches_residual_scalar = constraints_touch_pointer_residual_scalar(
                                relative_constraints
                            )
                            if touches_residual_scalar:
                                strict_constraints = relative_constraints + [
                                    expr == expr_bvv(value, expr),
                                    offset_expr == offset,
                                ]
                                if (
                                    try_add_constraint_set_fast(
                                        strict_constraints,
                                        timeout_ms=pointer_related_timeout_ms,
                                    )
                                    or try_add_constraint_set_related(
                                        strict_constraints,
                                        pointer_vars,
                                        timeout_ms=pointer_related_timeout_ms,
                                    )
                                ):
                                    if verbose:
                                        label = 'choose_pointer_like_relaxed_selected' if relaxed else 'choose_pointer_like_selected'
                                        print(label, str(expr), offset)
                                    return value
                            offset_seed_vars = set(pointer_vars)
                            for constraint in offset_constraints:
                                offset_seed_vars.update(getattr(constraint, 'variables', set()))
                            offset_sat = constraint_set_related_satisfiable(
                                offset_constraints,
                                offset_seed_vars,
                                timeout_ms=pointer_related_timeout_ms,
                            )
                            if offset_sat is not False:
                                assumed_constraints = []
                                if not constraints_already_added(relative_constraints):
                                    assumed_constraints.extend(relative_constraints)
                                if not touches_residual_scalar:
                                    assumed_constraints.append(expr == expr_bvv(value, expr))
                                assumed_constraints.append(offset_expr == offset)
                                add_constraints_assuming_sat(
                                    assumed_constraints,
                                    "pointer_relative_offset_assumed",
                                )
                                if verbose:
                                    label = 'choose_pointer_like_relaxed_selected' if relaxed else 'choose_pointer_like_selected'
                                    print(label, str(expr), offset)
                                return value
                            if pointer_debug_enabled:
                                DEBUG(f"pointer_offset_assumed_reject {({
                                    'expr': str(expr),
                                    'offset': offset,
                                    'offset_sat': offset_sat,
                                })}")
                            if offset_sat is False:
                                if pointer_debug_enabled:
                                    DEBUG(f"pointer_offset_concrete_selected {({
                                        'expr': str(expr),
                                        'offset': offset,
                                    })}")
                                if touches_residual_scalar and not (
                                    try_add_constraint_set_fast(
                                        relative_constraints,
                                        timeout_ms=pointer_related_timeout_ms,
                                    )
                                    or try_add_constraint_set_related(
                                        relative_constraints,
                                        pointer_vars,
                                        timeout_ms=pointer_related_timeout_ms,
                                    )
                                ):
                                    return None
                                return value
                        elif pointer_debug_enabled:
                            DEBUG(f"pointer_offset_assumed_skip {({
                                'expr': str(expr),
                                'offset': offset,
                                'long_block': long_block,
                                'simple_relative': simple_long_block_relative_offsets(),
                                'relative_known': constraints_already_added(relative_constraints),
                            })}")
                        if (
                            try_add_constraint_set_fast(
                                offset_constraints,
                                timeout_ms=pointer_confirm_timeout_ms,
                            )
                            or commit_pointer_constraints_heuristic(offset_constraints)
                            or try_add_constraint_set_related(
                                offset_constraints,
                                pointer_vars,
                                timeout_ms=pointer_related_timeout_ms,
                            )
                        ):
                            if verbose:
                                label = 'choose_pointer_like_relaxed_selected' if relaxed else 'choose_pointer_like_selected'
                                print(label, str(expr), offset)
                            return value
                        constraints = relative_constraints + [
                            expr == expr_bvv(value, expr),
                            offset_expr == offset,
                        ]
                        if (
                            try_add_constraint_set_fast(
                                constraints,
                                timeout_ms=pointer_confirm_timeout_ms,
                            )
                            or commit_pointer_constraints_heuristic(constraints)
                            or try_add_constraint_set_related(
                                constraints,
                                pointer_vars,
                                timeout_ms=pointer_related_timeout_ms,
                            )
                        ):
                            if verbose:
                                label = 'choose_pointer_like_relaxed_selected' if relaxed else 'choose_pointer_like_selected'
                                print(label, str(expr), offset)
                            return value
                        if os.environ.get("RVMCA_DEBUG_POINTER_VALUE") == "1":
                            def debug_constraints_sat(test_constraints):
                                test_solver = candidate_solver.branch()
                                test_solver.timeout = pointer_related_timeout_ms
                                try:
                                    for constraint in test_constraints:
                                        test_solver.add(constraint)
                                    return test_solver.satisfiable()
                                except Exception as exc:
                                    return type(exc).__name__
                            base_constraints = [
                                expr == expr_bvv(value, expr),
                                offset_expr == offset,
                            ]
                            DEBUG(f"pointer_value_candidate_failed {({
                                'expr': str(expr),
                                'offset': offset,
                                'base_sat': debug_constraints_sat(base_constraints),
                                'relative_sat': debug_constraints_sat(relative_constraints),
                                'combined_sat': debug_constraints_sat(constraints),
                            })}")
                        return None
                    if (
                        allow_initial_heuristics
                        and
                        long_block
                        and simple_long_block_relative_offsets()
                        and get_pointer_store_relative_offsets()
                    ):
                        if pointer_debug_enabled:
                            DEBUG(f"pointer_offset_concrete_selected {({
                                'expr': str(expr),
                                'offset': offset,
                                'reason': 'simple_relative_no_constraints',
                            })}")
                        return value
                    base_constraints = [
                        expr == expr_bvv(value, expr),
                        offset_expr == offset,
                    ]
                    if (
                        try_add_constraint_set_fast(
                            base_constraints,
                            timeout_ms=pointer_confirm_timeout_ms,
                        )
                        or commit_pointer_constraints_heuristic(base_constraints)
                        or try_add_constraint_set_related(
                            base_constraints,
                            pointer_vars,
                            timeout_ms=pointer_related_timeout_ms,
                        )
                    ):
                        if verbose:
                            label = 'choose_pointer_like_relaxed_selected' if relaxed else 'choose_pointer_like_selected'
                            print(label, str(expr), offset)
                        return value
                    if satisfiable_with(expr, value):
                        candidate_solver.add(expr == value)
                        if verbose:
                            label = 'choose_pointer_like_relaxed_selected' if relaxed else 'choose_pointer_like_selected'
                            print(label, str(expr), offset)
                        return value
                    if not relaxed and try_add_constraint(expr == expr_bvv(value, expr), timeout_ms=pointer_confirm_timeout_ms):
                        if verbose:
                            print('choose_pointer_like_confirmed_selected', str(expr), offset)
                        return value
                    if satisfiable_with(offset_expr, offset):
                        candidate_solver.add(offset_expr == offset)
                        if verbose:
                            label = 'choose_pointer_like_relaxed_selected' if relaxed else 'choose_pointer_like_selected'
                            print(label, str(expr), offset)
                        return value
                    if not relaxed and try_add_constraint(offset_expr == offset, timeout_ms=pointer_confirm_timeout_ms):
                        if verbose:
                            print('choose_pointer_like_offset_confirmed_selected', str(expr), offset)
                        return value
                    if os.environ.get("RVMCA_DEBUG_POINTER_VALUE") == "1":
                        def debug_constraints_sat(test_constraints):
                            test_solver = candidate_solver.branch()
                            test_solver.timeout = pointer_related_timeout_ms
                            try:
                                for constraint in test_constraints:
                                    test_solver.add(constraint)
                                return test_solver.satisfiable()
                            except Exception as exc:
                                return type(exc).__name__

                        def debug_eval_values(eval_expr, limit=4):
                            test_solver = candidate_solver.branch()
                            test_solver.timeout = pointer_related_timeout_ms
                            try:
                                values = test_solver.eval(eval_expr, limit)
                            except Exception as exc:
                                return type(exc).__name__
                            result = []
                            for eval_value in values:
                                try:
                                    int_value = int(eval_value)
                                except Exception:
                                    concrete_value = getattr(eval_value, 'concrete_value', None)
                                    if not isinstance(concrete_value, int):
                                        result.append(str(eval_value))
                                        continue
                                    int_value = concrete_value
                                result.append(hex(int_value & ((1 << eval_expr.size()) - 1)))
                            return result

                        DEBUG(f"pointer_value_base_candidate_failed {({
                            'expr': str(expr),
                            'offset': offset,
                            'relaxed': relaxed,
                            'expr_sat': debug_constraints_sat([expr == expr_bvv(value, expr)]),
                            'offset_sat': debug_constraints_sat([offset_expr == offset]),
                            'base_sat': debug_constraints_sat(base_constraints),
                            'expr_values': debug_eval_values(expr),
                            'offset_values': debug_eval_values(offset_expr),
                        })}")
                    return None

                def simple_long_block_relative_offsets():
                    relative_offsets = get_pointer_store_relative_offsets()
                    if not relative_offsets or len(relative_offsets) > 4:
                        return False
                    for imm, _store_width, access_width, residual_constraints in relative_offsets:
                        if len(residual_constraints) > 4:
                            return False
                        if any(ast_node_count(constraint) > 24 for constraint in residual_constraints):
                            return False
                        if access_width > 8:
                            return False
                        signed_imm = _signed_u64(imm)
                        if abs(signed_imm) > 64 and not (
                            signed_imm >= 0
                            and start_offset >= signed_imm + access_width
                        ):
                            return False
                    return True

                def skip_regular_pointer_candidates(has_relative_offsets):
                    return (
                        long_block
                        and has_relative_offsets
                        and not simple_long_block_relative_offsets()
                    )

                pointer_residual_scalar_vars = set()
                for reg in residual_scalar_regs:
                    reg_symbol = reg_to_symbol.get(reg)
                    if reg_symbol is not None:
                        pointer_residual_scalar_vars.update(expr_vars(reg_symbol))

                def constraints_touch_pointer_residual_scalar(constraints):
                    if not pointer_residual_scalar_vars:
                        return False
                    return any(
                        getattr(constraint, 'variables', set()) & pointer_residual_scalar_vars
                        for constraint in constraints
                    )

                if start_offset == 0:
                    has_relative_offsets = bool(get_pointer_store_relative_offsets())
                    value = choose_pointer_access_anchor(
                        avoid_stack_offsets,
                        limit=pointer_candidate_limit,
                    )
                    if value is not None:
                        return value
                    value = choose_pointer_affine_base_anchor(
                        avoid_stack_offsets,
                        limit=pointer_candidate_limit,
                    )
                    if value is not None:
                        return value
                    for offset in derived_pointer_offset_candidates(avoid_stack_offsets, limit=pointer_candidate_limit):
                        value = choose_pointer_offset(offset)
                        if value is not None:
                            return value
                    if not skip_regular_pointer_candidates(has_relative_offsets):
                        for offset in pointer_offset_candidates(avoid_stack_offsets, limit=pointer_candidate_limit):
                            value = choose_pointer_offset(offset)
                            if value is not None:
                                return value

                anchored_candidates = []
                if preferred is not None:
                    anchored_candidates.append(preferred)
                if long_block:
                    write_stage(
                        "init:materialize_init:memory_values:slot",
                        phase="pointer_anchored_eval",
                        pointer_like=True,
                    )
                else:
                    minimum = solver_min(expr)
                    if minimum is not None:
                        anchored_candidates.append(minimum)
                    anchored_candidates.extend(solver_eval_with(expr, [], n=8))
                seen_anchored = set()
                anchored_scalar = None
                for value in anchored_candidates:
                    value &= ((1 << 64) - 1)
                    if value in seen_anchored:
                        continue
                    seen_anchored.add(value)
                    offset = stack_offset_for_value(value)
                    if offset is None:
                        if anchored_scalar is None and satisfiable_with(expr, value):
                            anchored_scalar = value
                        continue
                    if not pointer_value_allowed(value):
                        continue
                    if (
                        offset % INIT_ACCESS_ALIGN != 0
                        and not get_pointer_store_relative_offsets()
                        and pointer_candidate_ok is None
                    ):
                        if anchored_scalar is None and satisfiable_with(expr, value):
                            anchored_scalar = value
                        continue
                    if offset < start_offset or not pointer_offset_value_ok(offset):
                        if anchored_scalar is None and satisfiable_with(expr, value):
                            anchored_scalar = value
                        continue
                    if any(
                        concrete_ranges_overlap(offset, 8, used_offset, used_width)
                        for used_offset, used_width in avoid_stack_offsets
                    ):
                        continue
                    if pointer_offset_conflicts(offset, avoid_stack_offsets):
                        continue
                    if satisfiable_with(expr, value):
                        candidate_solver.add(expr == value)
                        if verbose:
                            print('choose_pointer_like_anchored_selected', str(expr), offset)
                        return value

                if verbose:
                    print('choose_pointer_like', {
                        'expr': str(expr),
                        'preferred': preferred,
                        'start_offset': start_offset,
                        'avoid': avoid_stack_offsets,
                    })
                extra_constraints = value_selection_constraints(
                    offset_expr,
                    positive=True,
                    align=INIT_ACCESS_ALIGN,
                    avoid=avoid_stack_offsets,
                    width=8,
                )
                extra_constraints.append(claripy.UGE(offset_expr, claripy.BVV(start_offset, 64)))
                if long_block:
                    write_stage(
                        "init:materialize_init:memory_values:slot",
                        phase="pointer_candidates",
                        pointer_like=True,
                    )
                value = choose_pointer_access_anchor(
                    avoid_stack_offsets,
                    limit=pointer_candidate_limit,
                )
                if value is not None:
                    return value
                value = choose_pointer_affine_base_anchor(
                    avoid_stack_offsets,
                    limit=pointer_candidate_limit,
                )
                if value is not None:
                    return value
                has_relative_offsets = bool(get_pointer_store_relative_offsets())
                if long_block and has_relative_offsets:
                    eval_constraints = pointer_store_relative_constraints() + [
                        claripy.UGE(offset_expr, claripy.BVV(start_offset, 64)),
                        claripy.ULE(offset_expr, claripy.BVV(pointer_offset_search_upper(), 64)),
                    ]
                    for offset in solver_eval_with(offset_expr, eval_constraints, n=pointer_eval_limit):
                        if offset < start_offset:
                            continue
                        value = choose_pointer_offset(offset)
                        if value is not None:
                            return value
                for offset in derived_pointer_offset_candidates(avoid_stack_offsets, limit=pointer_candidate_limit):
                    value = choose_pointer_offset(offset)
                    if value is not None:
                        return value
                if not skip_regular_pointer_candidates(has_relative_offsets):
                    for offset in pointer_offset_candidates(avoid_stack_offsets, limit=pointer_candidate_limit):
                        value = choose_pointer_offset(offset)
                        if value is not None:
                            return value
                if long_block:
                    for offset in solver_eval_current(
                        offset_expr,
                        n=pointer_eval_limit,
                        timeout_ms=max(pointer_related_timeout_ms, 1000),
                    ):
                        offset = _signed_u64(offset)
                        if offset < start_offset:
                            continue
                        if not pointer_offset_value_ok(offset):
                            continue
                        if pointer_offset_conflicts(offset, avoid_stack_offsets):
                            continue
                        value = choose_pointer_offset(offset)
                        if value is not None:
                            return value
                if long_block:
                    write_stage(
                        "init:materialize_init:memory_values:slot",
                        phase="pointer_eval",
                        pointer_like=True,
                    )
                else:
                    for offset in [solver_min_with(offset_expr, extra_constraints)]:
                        if offset is None:
                            continue
                        if offset < start_offset:
                            continue
                        value = choose_pointer_offset(offset)
                        if value is not None:
                            return value
                if not skip_regular_pointer_candidates(has_relative_offsets):
                    for offset in solver_eval_with(offset_expr, extra_constraints, n=pointer_eval_limit):
                        if offset < start_offset:
                            continue
                        value = choose_pointer_offset(offset)
                        if value is not None:
                            return value
                if verbose:
                    print('choose_pointer_like_failed', str(expr), str(offset_expr))
                if long_block and preferred is not None:
                    preferred_offset = stack_offset_for_value(preferred)
                    if (
                        preferred_offset is not None
                        and preferred_offset >= start_offset
                        and pointer_offset_value_ok(preferred_offset)
                        and (
                            preferred_offset % INIT_ACCESS_ALIGN == 0
                            or get_pointer_store_relative_offsets()
                        )
                        and pointer_value_allowed(preferred)
                        and satisfiable_with(expr, preferred)
                    ):
                        candidate_solver.add(expr == expr_bvv(preferred, expr))
                        if verbose:
                            print('choose_pointer_like_direct_preferred_selected', str(expr), preferred_offset)
                        return preferred & ((1 << 64) - 1)
                relaxed_constraints = value_selection_constraints(
                    offset_expr,
                    positive=True,
                    align=INIT_ACCESS_ALIGN,
                    width=8,
                )
                relaxed_constraints.append(claripy.UGE(offset_expr, claripy.BVV(start_offset, 64)))
                relaxed_constraints.append(
                    claripy.ULE(offset_expr, claripy.BVV(pointer_offset_search_upper(), 64))
                )
                if long_block:
                    write_stage(
                        "init:materialize_init:memory_values:slot",
                        phase="pointer_relaxed_candidates",
                        pointer_like=True,
                    )
                value = choose_pointer_access_anchor(
                    [],
                    relaxed=True,
                    limit=pointer_relaxed_candidate_limit,
                )
                if value is not None:
                    return value
                value = choose_pointer_affine_base_anchor(
                    [],
                    relaxed=True,
                    limit=pointer_relaxed_candidate_limit,
                )
                if value is not None:
                    return value
                if not skip_regular_pointer_candidates(has_relative_offsets):
                    for offset in pointer_offset_candidates([], limit=pointer_relaxed_candidate_limit):
                        value = choose_pointer_offset(offset, relaxed=True)
                        if value is not None:
                            return value

                def can_zero_additive_pointer_operand():
                    if not pointer_vars:
                        return False
                    saw_related_address = False
                    base_like_residual_vars = (
                        set(pointer_loaded_addr_vars)
                        | set(undef_base_vars)
                    )
                    for load_inst, rd_symbol, _, _ in address_source_loads:
                        if load_inst.width == 8:
                            base_like_residual_vars.update(expr_vars(rd_symbol))
                    for reg_symbol in reg_to_symbol.values():
                        base_like_residual_vars.update(expr_vars(reg_symbol))
                    for _, access_addr_symbol, _, _access_width in mem_accesses:
                        if not (expr_vars(access_addr_symbol) & pointer_vars):
                            continue
                        residual = claripy.simplify(access_addr_symbol - expr)
                        residual_vars = expr_vars(residual)
                        if residual_vars & pointer_vars:
                            return False
                        if not residual_vars:
                            return False
                        if not (residual_vars & base_like_residual_vars):
                            return False
                        saw_related_address = True
                    return saw_related_address

                def additive_pointer_scalar_candidates():
                    base_like_residual_vars = (
                        set(pointer_loaded_addr_vars)
                        | set(undef_base_vars)
                        | set(expr_vars(init_sp))
                    )
                    for load_inst, rd_symbol, _, _ in address_source_loads:
                        if load_inst.width == 8:
                            base_like_residual_vars.update(expr_vars(rd_symbol))
                    for reg_symbol in reg_to_symbol.values():
                        base_like_residual_vars.update(expr_vars(reg_symbol))

                    operands = [expr]
                    seen_operand_keys = {expr_key(expr)}
                    for alias_expr in pointer_alias_exprs:
                        try:
                            if alias_expr.size() != expr.size():
                                continue
                        except Exception:
                            continue
                        alias_key = expr_key(alias_expr)
                        if alias_key in seen_operand_keys:
                            continue
                        seen_operand_keys.add(alias_key)
                        operands.append(alias_expr)

                    additive_accesses = []
                    all_operand_vars = set()
                    for operand in operands:
                        all_operand_vars.update(expr_vars(operand))
                    for _, access_addr_symbol, _, access_width in mem_accesses:
                        access_vars = expr_vars(access_addr_symbol)
                        operand = next(
                            (
                                candidate_operand
                                for candidate_operand in operands
                                if access_vars & expr_vars(candidate_operand)
                            ),
                            None,
                        )
                        if operand is None:
                            continue
                        residual = claripy.simplify(access_addr_symbol - operand)
                        residual_vars = expr_vars(residual)
                        if residual_vars & all_operand_vars:
                            continue
                        if not residual_vars:
                            continue
                        if not (residual_vars & base_like_residual_vars):
                            continue
                        alias_constraints = []
                        if expr_key(operand) != expr_key(expr):
                            alias_constraints.append(operand == expr)
                        additive_accesses.append((
                            access_addr_symbol,
                            access_width,
                            residual,
                            alias_constraints,
                        ))

                    additive_ok = bool(additive_accesses)
                    debug_pointer_residual(
                        'additive_scalar_gate',
                        expr=str(expr),
                        allowed=additive_ok,
                    )
                    if not additive_ok:
                        return []
                    candidates = []
                    seen_candidates = set()
                    for (
                        access_addr_symbol,
                        access_width,
                        residual,
                        alias_constraints,
                    ) in additive_accesses:
                        align = max(1, access_width)
                        first_offset = _align_up(
                            max(INIT_PTR_MIN_OFFSET, access_width),
                            align,
                        )
                        target_offsets = [first_offset]
                        target_offsets.extend(
                            _align_up(used_offset + max(used_width, access_width), align)
                            for used_offset, used_width in avoid_stack_offsets
                        )
                        for access_offset in target_offsets:
                            if access_offset <= 0 or access_offset > STACK_RANGE:
                                continue
                            candidate_expr = claripy.simplify(
                                init_sp
                                - expr_bvv(access_offset, init_sp)
                                - residual
                            )
                            candidate_value = concrete_value_from_materialized(candidate_expr)
                            target_constraint = access_addr_symbol == (
                                init_sp - expr_bvv(access_offset, init_sp)
                            )
                            target_constraints = alias_constraints + [target_constraint]
                            if candidate_value is None:
                                scalar_limit = expr_bvv(STACK_RANGE, expr)
                                negative_limit = expr_bvv(-STACK_RANGE, expr)
                                small_scalar_constraint = claripy.Or(
                                    claripy.ULE(expr, scalar_limit),
                                    claripy.UGE(expr, negative_limit),
                                )
                                candidate_value = solver_min_with(
                                    expr,
                                    target_constraints + [small_scalar_constraint],
                                )
                            debug_pointer_residual(
                                'additive_scalar_candidate',
                                expr=str(expr),
                                residual=str(residual),
                                access_offset=access_offset,
                                candidate_expr=str(candidate_expr),
                                candidate_value=candidate_value,
                            )
                            if candidate_value is None:
                                continue
                            signed_value = _signed_u64(candidate_value)
                            if not -STACK_RANGE <= signed_value <= STACK_RANGE:
                                continue
                            candidate_value &= ((1 << expr.size()) - 1)
                            if candidate_value in seen_candidates:
                                continue
                            seen_candidates.add(candidate_value)
                            candidates.append((candidate_value, target_constraints))
                    return candidates

                if allow_pointer_scalar_fallback and can_zero_additive_pointer_operand():
                    zero_constraint = expr == expr_bvv(0, expr)
                    if (
                        try_add_constraint_set_fast([zero_constraint], timeout_ms=pointer_confirm_timeout_ms)
                        or try_add_constraint_set_related(
                            [zero_constraint],
                            pointer_vars,
                            timeout_ms=pointer_related_timeout_ms,
                        )
                    ):
                        if verbose:
                            print('choose_pointer_like_additive_zero_selected', str(expr))
                        return 0
                if long_block:
                    write_stage(
                        "init:materialize_init:memory_values:slot",
                        phase="pointer_relaxed_eval",
                        pointer_like=True,
                    )
                else:
                    for offset in [solver_min_with(offset_expr, relaxed_constraints)]:
                        if offset is None or offset < start_offset:
                            continue
                        value = choose_pointer_offset(offset, relaxed=True)
                        if value is not None:
                            return value
                if not skip_regular_pointer_candidates(has_relative_offsets):
                    for offset in solver_eval_with(offset_expr, relaxed_constraints, n=pointer_eval_limit):
                        if offset < start_offset:
                            continue
                        value = choose_pointer_offset(offset, relaxed=True)
                        if value is not None:
                            return value
                if anchored_scalar is not None and allow_pointer_scalar_fallback:
                    candidate_solver.add(expr == anchored_scalar)
                    if verbose:
                        print('choose_pointer_like_scalar_anchored_selected', str(expr), anchored_scalar)
                    return anchored_scalar
                if allow_pointer_scalar_fallback:
                    for scalar_value in (0,):
                        if satisfiable_with(expr, scalar_value):
                            candidate_solver.add(expr == expr_bvv(scalar_value, expr))
                            if verbose:
                                print('choose_pointer_like_scalar_fallback_selected', str(expr), scalar_value)
                            return scalar_value
                if not allow_pointer_scalar_fallback:
                    for scalar_value, target_constraints in additive_pointer_scalar_candidates():
                        scalar_constraint = expr == expr_bvv(scalar_value, expr)
                        scalar_sat = try_add_constraint_set_fast(
                            target_constraints + [scalar_constraint],
                            timeout_ms=max(pointer_confirm_timeout_ms, 1000),
                        )
                        debug_pointer_residual(
                            'additive_scalar_sat',
                            expr=str(expr),
                            scalar_value=_signed_u64(scalar_value),
                            satisfiable=scalar_sat,
                        )
                        if scalar_sat:
                            if verbose:
                                print(
                                    'choose_pointer_like_additive_scalar_selected',
                                    str(expr),
                                    _signed_u64(scalar_value),
                                )
                            return scalar_value
                raise AssertionError(f"cannot choose stack pointer value for {expr}")

            choices = []
            if preferred is not None:
                choices.append(preferred)
            choices.append(0)

            seen = set()
            for val in choices:
                if val in seen:
                    continue
                seen.add(val)
                stack_offset = stack_offset_for_value(val)
                if stack_offset is not None and any(
                    concrete_ranges_overlap(stack_offset, 8, used_offset, used_width)
                    for used_offset, used_width in avoid_stack_offsets
                ):
                    continue
                if satisfiable_with(expr, val):
                    candidate_solver.add(expr == val)
                    return val

            minimum = solver_min(expr)
            if minimum is not None:
                choices = [minimum]
                for i in range(1, 64):
                    choices.append(minimum + i * 8)
            else:
                choices = []

            for val in choices:
                if val in seen:
                    continue
                seen.add(val)
                stack_offset = stack_offset_for_value(val)
                if stack_offset is not None and any(
                    concrete_ranges_overlap(stack_offset, 8, used_offset, used_width)
                    for used_offset, used_width in avoid_stack_offsets
                ):
                    continue
                if satisfiable_with(expr, val):
                    candidate_solver.add(expr == val)
                    return val

            return choose_value(expr, preferred)

        def choose_mem_slot_value(word_offset, slot):
            if 'chosen_value' in slot:
                return slot['chosen_value']
            val_symbol = slot.get('direct_value_expr', slot['symbol'])
            used_mem_offsets = [
                (used_addr, 8)
                for used_addr, used_slot in mem_slot_symbols.items()
                if used_addr != word_offset
            ]
            used_mem_offsets.extend((used_addr, 8) for used_addr in mem_values)
            preferred_offset = None
            preferred_value = None
            preferred_scalar_value = slot.get('preferred_scalar_value')
            if slot.get('pointer_like'):
                preferred_offset = next_free_stack_offset(
                    used_mem_offsets,
                    align=INIT_ACCESS_ALIGN,
                    width=INIT_ACCESS_SLOT_WIDTH,
                    start=max(INIT_PTR_MIN_OFFSET, slot.get('min_pointer_offset') or 0),
                )
                if preferred_offset is not None:
                    preferred_value = concrete_stack_addr(preferred_offset)
            write_stage(
                "init:materialize_init:memory_values:slot",
                offset=word_offset,
                phase="choose_value",
                pointer_like=bool(slot.get('pointer_like')),
                sp_affine=bool(slot.get('sp_affine')),
            )

            def pointer_slot_source_exprs():
                source_exprs = []
                seen_sources = set()
                for source_expr in (
                    [val_symbol, slot.get('direct_value_expr')]
                    + list(slot.get('value_exprs', []))
                ):
                    if source_expr is None:
                        continue
                    source_key = expr_key(source_expr)
                    if source_key in seen_sources:
                        continue
                    seen_sources.add(source_key)
                    source_exprs.append(source_expr)
                return source_exprs

            repeated_pointer_alias_cache = {}
            pointer_candidate_alias_offset_cache = {}

            def repeated_pointer_value_alias_exprs(source_expr):
                source_key = expr_key(source_expr)
                if source_key in repeated_pointer_alias_cache:
                    return repeated_pointer_alias_cache[source_key]

                source_loads = []
                for load_inst, rd_symbol, load_addr_symbol, load_idx in mem_entries:
                    if load_inst.width != 8:
                        continue
                    if expr_key(mem_value_expr(load_inst, rd_symbol)) != source_key:
                        continue
                    source_loads.append((load_addr_symbol, load_idx))

                aliases = [source_expr]
                seen_aliases = {source_key}
                for source_addr_symbol, source_idx in source_loads:
                    for alias_inst, alias_rd_symbol, alias_addr_symbol, alias_idx in mem_entries:
                        if alias_inst.width != 8 or alias_idx == source_idx:
                            continue
                        alias_key = expr_key(mem_value_expr(alias_inst, alias_rd_symbol))
                        if alias_key in seen_aliases:
                            continue
                        cheap_same = same_address(
                            source_addr_symbol,
                            alias_addr_symbol,
                            allow_solver=False,
                        )
                        solver_same = False
                        if (
                            not cheap_same
                            and exprs_may_be_related(source_addr_symbol, alias_addr_symbol)
                        ):
                            solver_same = solver_same_address(
                                source_addr_symbol,
                                alias_addr_symbol,
                                timeout_ms=100 if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD else 1000,
                            )
                        if not (cheap_same or solver_same):
                            continue
                        prev_idx = min(source_idx, alias_idx)
                        next_idx = max(source_idx, alias_idx)
                        if has_intervening_same_addr_store(
                            source_addr_symbol,
                            prev_idx,
                            next_idx,
                            allow_solver=bool(solver_same),
                        ):
                            continue
                        seen_aliases.add(alias_key)
                        aliases.append(mem_value_expr(alias_inst, alias_rd_symbol))

                repeated_pointer_alias_cache[source_key] = aliases
                return aliases

            def repeated_pointer_source_exprs():
                expanded = []
                seen_sources = set()
                for source_expr in pointer_slot_source_exprs():
                    for alias_expr in repeated_pointer_value_alias_exprs(source_expr):
                        alias_key = expr_key(alias_expr)
                        if alias_key in seen_sources:
                            continue
                        seen_sources.add(alias_key)
                        expanded.append(alias_expr)
                return expanded

            def pointer_alias_offset_available(alias_expr, pointer_offset):
                if pointer_offset <= 0 or pointer_offset > STACK_RANGE:
                    return False
                alias_vars = expr_vars(alias_expr)
                if not alias_vars:
                    return True
                cache_key = (expr_key(alias_expr), pointer_offset)
                if cache_key in pointer_candidate_alias_offset_cache:
                    return pointer_candidate_alias_offset_cache[cache_key]
                offset_expr = claripy.simplify(init_sp - alias_expr)
                constraint = offset_expr == expr_bvv(pointer_offset, offset_expr)
                sat = constraint_set_related_satisfiable(
                    [constraint],
                    alias_vars | expr_vars(offset_expr),
                    timeout_ms=100 if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD else 1000,
                )
                result = sat is not False
                pointer_candidate_alias_offset_cache[cache_key] = result
                return result

            def used_slot_aliases_related_access(
                used_offset,
                related_addr_symbol,
                proof_constraints=None,
            ):
                used_word_offset = ((used_offset + 7) // 8) * 8
                known_addrs = mem_offset_addr_symbols.get(used_word_offset, [])
                if any(
                    same_address(related_addr_symbol, known_addr, allow_solver=False)
                    for known_addr in known_addrs
                ):
                    return True
                if not proof_constraints:
                    return False
                for known_addr in known_addrs:
                    if not exprs_may_be_related(related_addr_symbol, known_addr):
                        continue
                    proof_solver = candidate_solver.branch()
                    proof_solver.timeout = max(local_solver_timeout_ms, 1000)
                    try:
                        for constraint in proof_constraints:
                            proof_solver.add(constraint)
                        if not proof_solver.satisfiable():
                            continue
                        inequality_solver = proof_solver.branch()
                        inequality_solver.add(related_addr_symbol != known_addr)
                        if not inequality_solver.satisfiable():
                            return True
                    except Exception:
                        continue
                return False

            def unique_current_value_for_expr(expr, timeout_ms=None):
                timeout_ms = max(local_solver_timeout_ms, 1000) if timeout_ms is None else timeout_ms
                values = solver_eval_current(expr, n=2, timeout_ms=timeout_ms)
                normalized_values = []
                seen_values = set()
                for value in values:
                    value = target_value_for_expr(value, expr)
                    if value in seen_values:
                        continue
                    seen_values.add(value)
                    normalized_values.append(value)
                if len(normalized_values) != 1:
                    return None
                actual_value = normalized_values[0]
                uniqueness_check = candidate_solver.branch()
                uniqueness_check.timeout = timeout_ms
                try:
                    uniqueness_check.add(expr != expr_bvv(actual_value, expr))
                    if uniqueness_check.satisfiable():
                        return None
                except Exception:
                    return None
                return actual_value

            residual_scalar_value_vars = set()
            for reg in residual_scalar_regs:
                reg_symbol = reg_to_symbol.get(reg)
                if reg_symbol is not None:
                    residual_scalar_value_vars.update(expr_vars(reg_symbol))

            def current_residual_value(residual):
                residual_value = concrete_expr_value(residual)
                if residual_value is not None:
                    return _signed_u64(residual_value)
                residual_affine = affine_base_const(residual)
                if residual_affine is not None:
                    residual_base, residual_imm = residual_affine
                    residual_base_vars = expr_vars(residual_base)
                    if residual_base_vars and residual_base_vars <= residual_scalar_value_vars:
                        residual_constraints = constraints_to_constant(
                            residual,
                            residual_imm & ((1 << 64) - 1),
                            forbidden_vars=set(),
                        )
                        if residual_constraints is not None and (
                            try_add_constraint_set_fast(
                                list(residual_constraints),
                                timeout_ms=local_solver_timeout_ms,
                            )
                            or try_add_constraint_set_related(
                                list(residual_constraints),
                                residual_base_vars,
                                timeout_ms=max(local_solver_timeout_ms, 1000),
                            )
                        ):
                            return _signed_u64(residual_imm)
                        if (
                            residual_constraints is not None
                            and len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
                            and len(residual_constraints) <= 2
                            and all(ast_node_count(constraint) <= 64 for constraint in residual_constraints)
                        ):
                            residual_sat = constraint_set_related_satisfiable(
                                list(residual_constraints),
                                residual_base_vars,
                                timeout_ms=local_solver_timeout_ms,
                            )
                            if residual_sat is not False:
                                seen_residual_constraints = set()
                                for constraint in residual_constraints:
                                    constraint_key = str(claripy.simplify(constraint))
                                    if constraint_key in seen_residual_constraints:
                                        continue
                                    seen_residual_constraints.add(constraint_key)
                                    candidate_solver.add(constraint)
                                    added_constraint_cache.add(constraint_key)
                                    debug_constraint_add("pointer_slot_residual_assumed", constraint)
                                return _signed_u64(residual_imm)
                model_value = unique_current_value_for_expr(residual)
                if model_value is None:
                    return None
                return _signed_u64(model_value)

            def pointer_candidate_related_constraints(actual_value):
                if not slot.get('pointer_like'):
                    return []
                pointer_offset = stack_offset_for_value(actual_value)
                if pointer_offset is None:
                    return []
                source_exprs = repeated_pointer_source_exprs()
                primary_source_keys = {
                    expr_key(source_expr)
                    for source_expr in pointer_slot_source_exprs()
                }
                if not any(expr_vars(source_expr) for source_expr in source_exprs):
                    return []
                saw_related_access = False
                related_constraints = []
                related_constraint_keys = set()

                def remember_related_constraint(constraint):
                    key = str(claripy.simplify(constraint))
                    if key in related_constraint_keys:
                        return
                    related_constraint_keys.add(key)
                    related_constraints.append(constraint)

                def dedupe_related_constraints(constraints):
                    result = []
                    seen = set()
                    for constraint in constraints:
                        key = str(claripy.simplify(constraint))
                        if key in seen:
                            continue
                        seen.add(key)
                        result.append(constraint)
                    return result

                def residual_constraints_for_target(residual, target, source_vars):
                    residual_vars = expr_vars(residual)
                    other_pointer_vars = set(pointer_loaded_addr_vars) - set(source_vars)
                    if residual_vars & source_vars:
                        return None
                    if residual_vars & other_pointer_vars:
                        return None
                    forbidden_vars = set(source_vars) | other_pointer_vars
                    target_value = target_value_for_expr(target, residual)
                    zero_delta = claripy.simplify(
                        residual - expr_bvv(target_value, residual)
                    )

                    candidate_sets = []

                    def add_candidate_set(constraints):
                        if constraints is None:
                            return
                        constraints = dedupe_related_constraints(constraints)
                        if not constraints:
                            candidate_sets.append([])
                            return
                        candidate_sets.append(constraints)

                    for _, zero_constraints, _ in multiplicative_zero_residual_constraint_options(
                        zero_delta,
                        forbidden_vars=forbidden_vars,
                        direct_pointer_guard=True,
                        timeout_ms=100 if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD else local_solver_timeout_ms,
                    ):
                        add_candidate_set(list(zero_constraints))

                    add_candidate_set(
                        constraints_to_constant(
                            zero_delta,
                            0,
                            forbidden_vars=forbidden_vars,
                        )
                    )
                    add_candidate_set(
                        constraints_to_constant(
                            residual,
                            target_value,
                            forbidden_vars=forbidden_vars,
                        )
                    )

                    if not candidate_sets:
                        direct_constraint = residual == expr_bvv(target_value, residual)
                        sat = constraint_set_related_satisfiable(
                            [direct_constraint],
                            residual_vars,
                            timeout_ms=max(local_solver_timeout_ms, 1000),
                        )
                        if sat is not False:
                            candidate_sets.append([direct_constraint])

                    for constraints in candidate_sets:
                        if not constraints:
                            return []
                        sat = constraint_set_related_satisfiable(
                            constraints,
                            residual_vars,
                            timeout_ms=100 if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD else max(local_solver_timeout_ms, 1000),
                        )
                        if sat is not False:
                            return constraints
                    return None

                def unresolved_residual_target_candidates(related_inst, related_width, pointer_offset):
                    mask = (1 << 64) - 1
                    candidates = []
                    seen_targets = set()

                    def add_target(target):
                        target = _signed_u64(target)
                        target_key = target & mask
                        if target_key in seen_targets:
                            return
                        seen_targets.add(target_key)
                        related_offset = pointer_offset - target
                        if related_offset <= 0 or related_offset > STACK_RANGE:
                            return
                        if related_width > 1 and related_offset % related_width:
                            return
                        candidates.append(target)

                    add_target(getattr(related_inst, 'imm', 0))
                    for target in (0, -4, 4, -8, 8, -12, 12, -16, 16, 20, 24, 32):
                        add_target(target)
                    return candidates

                for source_expr in source_exprs:
                    source_vars = expr_vars(source_expr)
                    if not source_vars:
                        continue
                    # When this function is used as a pre-check from
                    # choose_pointer_offset(), the candidate value constraint has
                    # not been added yet.  The primary value expression is the
                    # candidate itself, so its stack offset is guaranteed by the
                    # later value constraint; pre-check only the repeated aliases.
                    source_is_current_value = expr_key(source_expr) == expr_key(val_symbol)
                    if (
                        not source_is_current_value
                        and not pointer_alias_offset_available(source_expr, pointer_offset)
                    ):
                        if expr_key(source_expr) not in primary_source_keys:
                            if os.environ.get("RVMCA_DEBUG_POINTER_VALUE") == "1":
                                DEBUG(f"pointer_slot_candidate_alias_deferred {({
                                    'offset': word_offset,
                                    'expr': str(val_symbol),
                                    'source': str(source_expr),
                                    'value': hex(actual_value & ((1 << 64) - 1)),
                                    'pointer_offset': pointer_offset,
                                })}")
                        else:
                            if os.environ.get("RVMCA_DEBUG_POINTER_VALUE") == "1":
                                DEBUG(f"pointer_slot_candidate_reject {({
                                    'offset': word_offset,
                                    'expr': str(val_symbol),
                                    'source': str(source_expr),
                                    'value': hex(actual_value & ((1 << 64) - 1)),
                                    'reason': 'alias_offset_unsat',
                                    'pointer_offset': pointer_offset,
                                })}")
                            return None
                    for related_inst, related_addr_symbol, _related_idx, related_width in mem_accesses:
                        if not (expr_vars(related_addr_symbol) & source_vars):
                            continue
                        residual = claripy.simplify(related_addr_symbol - source_expr)
                        residual_vars = expr_vars(residual)
                        if residual_vars & source_vars:
                            continue
                        residual_value = current_residual_value(residual)
                        if residual_value is None:
                            resolved_residual = False
                            if residual_vars & residual_scalar_value_vars:
                                for target in unresolved_residual_target_candidates(
                                    related_inst,
                                    related_width,
                                    pointer_offset,
                                ):
                                    target_constraints = residual_constraints_for_target(
                                        residual,
                                        target,
                                        source_vars,
                                    )
                                    if target_constraints is None:
                                        continue
                                    for constraint in target_constraints:
                                        remember_related_constraint(constraint)
                                    residual_value = target & ((1 << 64) - 1)
                                    saw_related_access = True
                                    resolved_residual = True
                                    if os.environ.get("RVMCA_DEBUG_POINTER_VALUE") == "1":
                                        DEBUG(f"pointer_slot_residual_target_selected {({
                                            'offset': word_offset,
                                            'expr': str(val_symbol),
                                            'source': str(source_expr),
                                            'value': hex(actual_value & ((1 << 64) - 1)),
                                            'pointer_offset': pointer_offset,
                                            'target': target,
                                            'constraints': len(target_constraints),
                                            'residual': str(residual),
                                        })}")
                                    break
                                if not resolved_residual:
                                    if os.environ.get("RVMCA_DEBUG_POINTER_VALUE") == "1":
                                        DEBUG(f"pointer_slot_candidate_reject {({
                                            'offset': word_offset,
                                            'expr': str(val_symbol),
                                            'source': str(source_expr),
                                            'value': hex(actual_value & ((1 << 64) - 1)),
                                            'reason': 'unresolved_residual_scalar',
                                            'pointer_offset': pointer_offset,
                                            'residual': str(residual),
                                        })}")
                                    return None
                            if pointer_offset > STACK_RANGE:
                                return None
                            if not resolved_residual:
                                continue
                        saw_related_access = True
                        residual_imm = _signed_u64(residual_value)
                        if residual_vars:
                            remember_related_constraint(
                                residual == expr_bvv(
                                    residual_imm & ((1 << residual.size()) - 1),
                                    residual,
                                )
                            )
                        related_offset = pointer_offset - residual_imm
                        if related_offset <= 0 or related_offset > STACK_RANGE:
                            if os.environ.get("RVMCA_DEBUG_POINTER_VALUE") == "1":
                                DEBUG(f"pointer_slot_candidate_reject {({
                                    'offset': word_offset,
                                    'expr': str(val_symbol),
                                    'source': str(source_expr),
                                    'value': hex(actual_value & ((1 << 64) - 1)),
                                    'reason': 'derived_out_of_stack',
                                    'pointer_offset': pointer_offset,
                                    'residual': residual_imm,
                                    'derived_offset': related_offset,
                                })}")
                            return None
                        if related_width > 1 and related_offset % related_width:
                            if os.environ.get("RVMCA_DEBUG_POINTER_VALUE") == "1":
                                DEBUG(f"pointer_slot_candidate_reject {({
                                    'offset': word_offset,
                                    'expr': str(val_symbol),
                                    'source': str(source_expr),
                                    'value': hex(actual_value & ((1 << 64) - 1)),
                                    'reason': 'derived_unaligned',
                                    'pointer_offset': pointer_offset,
                                    'residual': residual_imm,
                                    'derived_offset': related_offset,
                                    'width': related_width,
                                })}")
                            return None
                        related_slot_width = init_slot_width(related_width)
                        related_slot_offset = (
                            ((related_offset + 7) // 8) * 8
                            if related_width < 8
                            else related_offset
                        )
                        for used_offset, used_width in used_mem_offsets:
                            if not concrete_ranges_overlap(
                                related_slot_offset,
                                related_slot_width,
                                used_offset,
                                used_width,
                            ):
                                continue
                            if (
                                related_slot_offset == used_offset
                                and related_slot_width == used_width
                                and used_slot_aliases_related_access(
                                    used_offset,
                                    related_addr_symbol,
                                    list(related_constraints) + [
                                        val_symbol == expr_bvv(actual_value, val_symbol),
                                    ],
                                )
                            ):
                                continue
                            if os.environ.get("RVMCA_DEBUG_POINTER_VALUE") == "1":
                                DEBUG(f"pointer_slot_candidate_reject {({
                                    'offset': word_offset,
                                    'expr': str(val_symbol),
                                    'source': str(source_expr),
                                    'value': hex(actual_value & ((1 << 64) - 1)),
                                    'reason': 'derived_overlap',
                                    'pointer_offset': pointer_offset,
                                    'residual': residual_imm,
                                    'derived_offset': related_slot_offset,
                                    'derived_width': related_slot_width,
                                    'used_offset': used_offset,
                                    'used_width': used_width,
                                    'is_store': related_inst.type == IType.Store,
                                })}")
                            return None
                if pointer_offset <= STACK_RANGE or saw_related_access:
                    return related_constraints
                return None

            def pointer_candidate_related_ranges_ok(actual_value):
                related_constraints = pointer_candidate_related_constraints(actual_value)
                if related_constraints is None:
                    return False
                if not strict_retry_validation:
                    return True
                candidate_constraints = list(related_constraints) + [
                    val_symbol == expr_bvv(actual_value, val_symbol),
                ]
                candidate_vars = set(expr_vars(val_symbol))
                for constraint in candidate_constraints:
                    candidate_vars.update(expr_vars(constraint))
                return constraint_set_related_satisfiable(
                    candidate_constraints,
                    candidate_vars,
                    timeout_ms=max(local_solver_timeout_ms, 1000),
                ) is True

            def add_pointer_candidate_constraints(actual_value, constraints, seed_vars=None, timeout_ms=None):
                related_constraints = pointer_candidate_related_constraints(actual_value)
                if related_constraints is None:
                    return False
                combined_constraints = list(constraints or []) + list(related_constraints)
                if not combined_constraints:
                    return True
                combined_vars = set(seed_vars or set())
                for constraint in combined_constraints:
                    combined_vars.update(expr_vars(constraint))
                timeout_ms = local_solver_timeout_ms if timeout_ms is None else timeout_ms
                added = (
                    try_add_constraint_set_fast(
                        combined_constraints,
                        timeout_ms=timeout_ms,
                    )
                    or try_add_constraint_set_related(
                        combined_constraints,
                        combined_vars,
                        timeout_ms=max(timeout_ms, 1000),
                    )
                )
                if added:
                    for constraint in combined_constraints:
                        added_constraint_cache.add(str(claripy.simplify(constraint)))
                    return True
                if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD:
                    related_sat = constraint_set_related_satisfiable(
                        combined_constraints,
                        combined_vars,
                        timeout_ms=max(timeout_ms, 1000),
                    )
                    if related_sat is not False:
                        for constraint in combined_constraints:
                            candidate_solver.add(constraint)
                            added_constraint_cache.add(str(claripy.simplify(constraint)))
                            debug_constraint_add("pointer_related_assumed", constraint)
                        return True
                return False

            def choose_forced_small_scalar_value():
                if preferred_scalar_value is not None:
                    return None
                if not (
                    slot.get('sp_affine')
                    or slot.get('scalar_zero')
                    or (
                        slot.get('pointer_like')
                        and slot.get('must_be_pointer')
                        and not slot.get('value_exprs')
                    )
                ):
                    return None
                candidate_values = solver_eval_current(val_symbol, n=2, timeout_ms=max(local_solver_timeout_ms, 1000))
                normalized_values = []
                seen_values = set()
                for value in candidate_values:
                    value = target_value_for_expr(value, val_symbol)
                    if value in seen_values:
                        continue
                    seen_values.add(value)
                    normalized_values.append(value)
                if len(normalized_values) != 1:
                    return None
                actual_value = normalized_values[0]
                signed_value = _signed_u64(actual_value)
                if not (-STACK_RANGE <= signed_value <= STACK_RANGE):
                    return None
                if stack_offset_for_value(actual_value) is not None:
                    return None
                value_constraint = val_symbol == expr_bvv(actual_value, val_symbol)
                uniqueness_check = candidate_solver.branch()
                uniqueness_check.timeout = max(local_solver_timeout_ms, 1000)
                try:
                    uniqueness_check.add(val_symbol != expr_bvv(actual_value, val_symbol))
                    if uniqueness_check.satisfiable():
                        return None
                except Exception:
                    return None
                if (
                    try_add_constraint_set_fast([value_constraint], timeout_ms=local_solver_timeout_ms)
                    or try_add_constraint_set_related(
                        [value_constraint],
                        expr_vars(val_symbol),
                        timeout_ms=max(local_solver_timeout_ms, 1000),
                    )
                ):
                    slot['chosen_value'] = actual_value
                    if os.environ.get("RVMCA_DEBUG_POINTER_VALUE") == "1":
                        DEBUG(f"pointer_slot_forced_scalar_selected {({
                            'offset': word_offset,
                            'expr': str(val_symbol),
                            'value': hex(actual_value),
                            'signed': signed_value,
                            'pointer_like': bool(slot.get('pointer_like')),
                            'must_be_pointer': bool(slot.get('must_be_pointer')),
                            'sp_affine': bool(slot.get('sp_affine')),
                            'scalar_zero': bool(slot.get('scalar_zero')),
                        })}")
                    write_stage(
                        "init:materialize_init:memory_values:slot",
                        offset=word_offset,
                        phase="chosen",
                        pointer_like=False,
                        sp_affine=bool(slot.get('sp_affine')),
                    )
                    return actual_value
                return None

            def choose_forced_stack_relative_pointer_value():
                if not slot.get('pointer_like'):
                    return None
                actual_value = unique_current_value_for_expr(val_symbol)
                if actual_value is None:
                    return None
                pointer_offset = stack_offset_for_value(actual_value)
                if pointer_offset is None:
                    return None
                min_pointer_offset = max(
                    1,
                    int(slot.get('min_pointer_offset') or 0),
                )
                if pointer_offset < min_pointer_offset or pointer_offset > STACK_RANGE:
                    return None
                value_constraint = val_symbol == expr_bvv(actual_value, val_symbol)
                if add_pointer_candidate_constraints(
                    actual_value,
                    [value_constraint],
                    seed_vars=expr_vars(val_symbol),
                    timeout_ms=local_solver_timeout_ms,
                ):
                    slot['chosen_value'] = actual_value
                    if os.environ.get("RVMCA_DEBUG_POINTER_VALUE") == "1":
                        DEBUG(f"pointer_slot_forced_stack_relative_selected {({
                            'offset': word_offset,
                            'expr': str(val_symbol),
                            'value': hex(actual_value),
                            'stack_offset': pointer_offset,
                            'pointer_like': bool(slot.get('pointer_like')),
                            'must_be_pointer': bool(slot.get('must_be_pointer')),
                            'sp_affine': bool(slot.get('sp_affine')),
                        })}")
                    write_stage(
                        "init:materialize_init:memory_values:slot",
                        offset=word_offset,
                        phase="chosen",
                        pointer_like=True,
                        sp_affine=bool(slot.get('sp_affine')),
                    )
                    return actual_value
                return None

            if preferred_scalar_value is not None and not (
                slot.get('pointer_like')
                or slot.get('must_be_pointer')
                or slot.get('sp_affine')
            ):
                actual_value = preferred_scalar_value & ((1 << 64) - 1)
                constraint = val_symbol == expr_bvv(actual_value, val_symbol)
                if (
                    try_add_constraint_set_fast([constraint], timeout_ms=local_solver_timeout_ms)
                    or try_add_constraint_set_related(
                        [constraint],
                        expr_vars(val_symbol),
                        timeout_ms=local_solver_timeout_ms,
                    )
                ):
                    slot['chosen_value'] = actual_value
                    write_stage(
                        "init:materialize_init:memory_values:slot",
                        offset=word_offset,
                        phase="chosen",
                        pointer_like=bool(slot.get('pointer_like')),
                        sp_affine=bool(slot.get('sp_affine')),
                    )
                    return actual_value
            forced_scalar_value = choose_forced_small_scalar_value()
            if forced_scalar_value is not None:
                return forced_scalar_value
            forced_stack_pointer_value = choose_forced_stack_relative_pointer_value()
            if forced_stack_pointer_value is not None:
                return forced_stack_pointer_value
            if (
                (len(mem_entries) >= 3 or word_offset > STACK_RANGE)
                and slot.get('pointer_like')
            ):
                def dedupe_preferred_constraints(constraints):
                    result = []
                    seen = set()
                    for constraint in constraints:
                        key = str(claripy.simplify(constraint))
                        if key in seen:
                            continue
                        seen.add(key)
                        result.append(constraint)
                    return result

                def pointer_preferred_offset_constraints(offset):
                    source_exprs = []
                    seen_sources = set()
                    for source_expr in (
                        [val_symbol, slot.get('direct_value_expr')]
                        + list(slot.get('value_exprs', []))
                    ):
                        if source_expr is None:
                            continue
                        source_key = expr_key(source_expr)
                        if source_key in seen_sources:
                            continue
                        seen_sources.add(source_key)
                        source_exprs.append(source_expr)
                    if not any(expr_vars(source_expr) for source_expr in source_exprs):
                        return []
                    long_block = len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
                    constraints = []
                    for source_expr in source_exprs:
                        value_vars = expr_vars(source_expr)
                        if not value_vars:
                            continue
                        other_pointer_vars = set(pointer_loaded_addr_vars) - set(value_vars)
                        for access_inst, access_addr_symbol, _access_idx, access_width in mem_accesses:
                            if not (expr_vars(access_addr_symbol) & value_vars):
                                continue
                            residual = claripy.simplify(access_addr_symbol - source_expr)
                            residual_vars = expr_vars(residual)
                            if residual_vars & value_vars:
                                continue
                            if residual_vars & other_pointer_vars:
                                return None
                            residual_value = concrete_expr_value(residual)
                            if residual_value is None:
                                if long_block:
                                    continue
                                residual_affine = affine_base_const(residual)
                                if residual_affine is None:
                                    return None
                                _, residual_imm = residual_affine
                                residual_value = _signed_u64(residual_imm)
                                residual_constraints = constraints_to_constant(
                                    residual,
                                    residual_value & ((1 << 64) - 1),
                                    forbidden_vars=value_vars | other_pointer_vars,
                                )
                                if residual_constraints is None:
                                    return None
                                constraints.extend(residual_constraints)
                            else:
                                residual_value = _signed_u64(residual_value)
                            access_offset = offset - residual_value
                            if access_offset <= 0 or access_offset > STACK_RANGE:
                                return None
                            if access_width > 1 and access_offset % access_width:
                                return None
                            access_slot_width = init_slot_width(access_width)
                            access_slot_offset = (
                                ((access_offset + 7) // 8) * 8
                                if access_width < 8
                                else access_offset
                            )
                            for used_offset, used_width in used_mem_offsets:
                                if not concrete_ranges_overlap(
                                    access_slot_offset,
                                    access_slot_width,
                                    used_offset,
                                    used_width,
                                ):
                                    continue
                                if (
                                    access_slot_offset == used_offset
                                    and access_slot_width == used_width
                                    and (
                                        access_inst.type != IType.Store
                                        or used_slot_aliases_related_access(
                                            used_offset,
                                            access_addr_symbol,
                                        )
                                    )
                                ):
                                    continue
                                return None
                            if access_width < 8:
                                access_word_offset = ((access_offset + 7) // 8) * 8
                                access_slot = mem_slot_symbols.get(access_word_offset)
                                if access_slot is not None and access_word_offset != word_offset and (
                                    access_slot.get('pointer_like')
                                    or access_slot.get('must_be_pointer')
                                    or access_slot.get('sp_affine')
                                ):
                                    return None
                    return dedupe_preferred_constraints(constraints)

                if preferred_value is None:
                    fallback_offset = _align_up(
                        max(INIT_PTR_MIN_OFFSET, slot.get('min_pointer_offset') or 0),
                        INIT_ACCESS_ALIGN,
                    )
                    if fallback_offset > STACK_RANGE:
                        fallback_offset = INIT_PTR_MIN_OFFSET
                    preferred_value = concrete_stack_addr(fallback_offset)
                actual_value = preferred_value & ((1 << 64) - 1)
                preferred_offset_for_value = stack_offset_for_value(actual_value)
                preferred_constraints = (
                    None
                    if preferred_offset_for_value is None
                    else pointer_preferred_offset_constraints(preferred_offset_for_value)
                )
                if (
                    preferred_offset_for_value is not None
                    and preferred_constraints is not None
                    and add_pointer_candidate_constraints(
                        actual_value,
                        preferred_constraints + [val_symbol == expr_bvv(actual_value, val_symbol)],
                        seed_vars=expr_vars(val_symbol),
                        timeout_ms=local_solver_timeout_ms,
                    )
                ):
                    slot['chosen_value'] = actual_value
                    write_stage(
                        "init:materialize_init:memory_values:slot",
                        offset=word_offset,
                        phase="chosen",
                        pointer_like=True,
                        sp_affine=bool(slot.get('sp_affine')),
                    )
                    return actual_value
            def choose_pointer_value_from_known_access_slots():
                if not slot.get('pointer_like'):
                    return None
                min_offset = max(INIT_PTR_MIN_OFFSET, slot.get('min_pointer_offset') or 0)
                mask = (1 << 64) - 1
                long_pointer_block = len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
                source_exprs = []
                seen_source_exprs = set()
                for source_expr in (
                    [slot.get('direct_value_expr')]
                    + list(slot.get('value_exprs', []))
                    + [val_symbol]
                ):
                    if source_expr is None:
                        continue
                    source_key = expr_key(source_expr)
                    if source_key in seen_source_exprs:
                        continue
                    seen_source_exprs.add(source_key)
                    source_exprs.append(source_expr)

                def dedupe_constraints(constraints):
                    result = []
                    seen = set()
                    for constraint in constraints:
                        key = str(claripy.simplify(constraint))
                        if key in seen:
                            continue
                        seen.add(key)
                        result.append(constraint)
                    return result

                def residual_constraint_options_for_target(residual, target, source_vars):
                    residual_vars = expr_vars(residual)
                    if residual_vars & source_vars:
                        return []
                    other_pointer_vars = set(pointer_loaded_addr_vars) - set(source_vars)
                    if residual_vars & other_pointer_vars:
                        return []
                    residual_value = concrete_expr_value(residual)
                    if residual_value is not None:
                        if (_signed_u64(residual_value) & mask) == (target & mask):
                            return [[]]
                        return []

                    options = []
                    seen_options = set()

                    def add_option(constraints):
                        constraints = dedupe_constraints(constraints)
                        option_key = tuple(
                            str(claripy.simplify(constraint))
                            for constraint in constraints
                        )
                        if option_key in seen_options:
                            return
                        seen_options.add(option_key)
                        options.append(constraints)

                    target_key = target & mask
                    if target_key == 0:
                        for _, zero_constraints, _ in multiplicative_zero_residual_constraint_options(
                            residual,
                            forbidden_vars=source_vars | other_pointer_vars,
                            direct_pointer_guard=True,
                            timeout_ms=100 if long_pointer_block else local_solver_timeout_ms,
                        ):
                            add_option(list(zero_constraints))
                    constraints = constraints_to_constant(
                        residual,
                        target_key,
                        forbidden_vars=source_vars | other_pointer_vars,
                    )
                    if constraints is not None:
                        add_option(list(constraints))
                    if not options:
                        direct_constraint = residual == expr_bvv(target, residual)
                        sat = constraint_set_related_satisfiable(
                            [direct_constraint],
                            residual_vars,
                            timeout_ms=max(local_solver_timeout_ms, 1000),
                        )
                        if sat is not False:
                            add_option([direct_constraint])
                    return options

                def related_ranges_ok(source_expr, source_vars, pointer_offset):
                    ranges = []
                    for related_inst, related_addr_symbol, related_idx, related_width in mem_accesses:
                        related_vars = expr_vars(related_addr_symbol)
                        if not (related_vars & source_vars):
                            continue
                        residual = claripy.simplify(related_addr_symbol - source_expr)
                        residual_value = concrete_expr_value(residual)
                        if residual_value is None:
                            continue
                        residual_imm = _signed_u64(residual_value)
                        related_offset = pointer_offset - residual_imm
                        if related_offset <= 0 or related_offset > STACK_RANGE:
                            return False
                        if related_width > 1 and related_offset % related_width:
                            return False
                        related_slot_width = init_slot_width(related_width)
                        related_slot_offset = (
                            ((related_offset + 7) // 8) * 8
                            if related_width < 8
                            else related_offset
                        )
                        ranges.append((related_slot_offset, related_slot_width, related_addr_symbol, related_inst))
                    for related_offset, related_width, related_addr_symbol, related_inst in ranges:
                        for used_offset, used_width in used_mem_offsets:
                            if not concrete_ranges_overlap(
                                related_offset,
                                related_width,
                                used_offset,
                                used_width,
                            ):
                                continue
                            if (
                                related_offset == used_offset
                                and related_width == used_width
                                and (
                                    related_inst.type != IType.Store
                                    or used_slot_aliases_related_access(
                                        used_offset,
                                        related_addr_symbol,
                                    )
                                )
                            ):
                                continue
                            return False
                    return True

                def known_access_aliases_current_pointer_slot(
                    known_access_offset,
                    access_width,
                    access_addr_symbol,
                ):
                    if access_width <= 0:
                        return False
                    if access_width > 1 and known_access_offset % access_width:
                        return False
                    access_slot_width = init_slot_width(access_width)
                    access_slot_offset = (
                        ((known_access_offset + 7) // 8) * 8
                        if access_width < 8
                        else known_access_offset
                    )
                    if access_slot_offset != word_offset or access_slot_width != 8:
                        return False
                    return used_slot_aliases_related_access(
                        word_offset,
                        access_addr_symbol,
                    )

                def residual_forced_to_target(residual, target):
                    values = solver_eval_limited(residual, n=2, timeout_ms=100)
                    normalized_values = {
                        target_value_for_expr(value, residual)
                        for value in values
                    }
                    return (
                        len(normalized_values) == 1
                        and next(iter(normalized_values)) == target_value_for_expr(target, residual)
                    )

                candidates = []
                seen_candidates = set()
                for source_order, source_expr in enumerate(source_exprs):
                    source_vars = expr_vars(source_expr)
                    if not source_vars:
                        continue
                    for access_inst, access_addr_symbol, access_idx, access_width in mem_accesses:
                        if not (expr_vars(access_addr_symbol) & source_vars):
                            continue
                        known_access_offset = addr_expr_offsets.get(expr_key(access_addr_symbol))
                        if known_access_offset is None:
                            continue
                        residual = claripy.simplify(access_addr_symbol - source_expr)
                        for target in (0, 4, 8, 12, 16, -4, -8, -12, -16, 20, 24, 32):
                            residual_constraint_options = residual_constraint_options_for_target(
                                residual,
                                target,
                                source_vars,
                            )
                            if not residual_constraint_options:
                                continue
                            pointer_offset = known_access_offset + target
                            if pointer_offset < min_offset:
                                self_pointer_slot = (
                                    pointer_offset == word_offset
                                    and slot.get('pointer_like')
                                    and not slot.get('sp_affine')
                                )
                                if not (
                                    self_pointer_slot
                                    or known_access_aliases_current_pointer_slot(
                                        known_access_offset,
                                        access_width,
                                        access_addr_symbol,
                                    )
                                ):
                                    continue
                            if pointer_offset > STACK_RANGE:
                                continue
                            if pointer_offset <= 0:
                                continue
                            for residual_constraints in residual_constraint_options:
                                constraints_key = tuple(
                                    str(claripy.simplify(constraint))
                                    for constraint in residual_constraints
                                )
                                candidate_key = (
                                    pointer_offset,
                                    expr_key(source_expr),
                                    target & mask,
                                    constraints_key,
                                )
                                if candidate_key in seen_candidates:
                                    continue
                                if not related_ranges_ok(source_expr, source_vars, pointer_offset):
                                    continue
                                scalar_address_field = (
                                    access_width < 8
                                    and any(
                                        load_idx == access_idx
                                        and is_scalar_zero_address_load(load_inst, load_rd_symbol, load_idx)
                                        for load_inst, load_rd_symbol, _, load_idx in mem_entries
                                    )
                                )
                                seen_candidates.add(candidate_key)
                                candidates.append((
                                    pointer_offset,
                                    source_order,
                                    0 if scalar_address_field else 1,
                                    source_expr,
                                    source_vars,
                                    dedupe_constraints(residual_constraints),
                                    known_access_offset,
                                    target,
                                    residual,
                                    access_addr_symbol,
                                ))

                candidates.sort(
                    key=lambda item: (
                        item[1],
                        0 if item[7] == 0 else 1,
                        abs(_signed_u64(item[7])),
                        item[2],
                        item[0],
                    )
                )
                candidate_limit = 32 if len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD else 64
                for pointer_offset, _source_order, _scalar_rank, source_expr, source_vars, residual_constraints, known_access_offset, target, residual, access_addr_symbol in candidates[:candidate_limit]:
                    actual_value = concrete_stack_addr(pointer_offset) & mask
                    if long_pointer_block:
                        value_constraints = [
                            (init_sp - val_symbol) == pointer_offset,
                        ]
                        if expr_key(source_expr) != expr_key(val_symbol):
                            value_constraints.append(
                                (init_sp - source_expr) == pointer_offset
                            )
                    else:
                        value_constraints = [val_symbol == expr_bvv(actual_value, val_symbol)]
                        if expr_key(source_expr) != expr_key(val_symbol):
                            value_constraints.append(source_expr == expr_bvv(actual_value, source_expr))
                    constraints = dedupe_constraints(
                        list(residual_constraints)
                        + value_constraints
                        + [(init_sp - access_addr_symbol) == known_access_offset]
                    )
                    related_vars = expr_vars(val_symbol) | source_vars | expr_vars(access_addr_symbol)
                    added = (
                        try_add_constraint_set_fast(
                            constraints,
                            timeout_ms=local_solver_timeout_ms,
                        )
                        or try_add_constraint_set_related(
                            constraints,
                            related_vars,
                            timeout_ms=local_solver_timeout_ms if long_pointer_block else max(local_solver_timeout_ms, 1000),
                        )
                    )
                    assumed = False
                    if (
                        not added
                        and len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
                        and target == 0
                        and len(constraints) <= 4
                        and all(ast_node_count(constraint) <= 64 for constraint in constraints)
                    ):
                        related_sat = constraint_set_related_satisfiable(
                            constraints,
                            related_vars,
                            timeout_ms=local_solver_timeout_ms if long_pointer_block else max(local_solver_timeout_ms, 1000),
                        )
                        if related_sat is not False:
                            for constraint in constraints:
                                candidate_solver.add(constraint)
                                added_constraint_cache.add(str(claripy.simplify(constraint)))
                                debug_constraint_add("pointer_known_access_assumed", constraint)
                            added = True
                            assumed = True
                    if (
                        not added
                        and residual_constraints
                        and not residual_forced_to_target(residual, target)
                    ):
                        continue
                    if not added and len(mem_entries) < GLOBAL_NO_OVERLAP_LOAD_THRESHOLD:
                        continue
                    if added:
                        for constraint in constraints:
                            added_constraint_cache.add(str(claripy.simplify(constraint)))
                    slot['chosen_value'] = actual_value
                    if os.environ.get("RVMCA_DEBUG_POINTER_VALUE") == "1":
                        DEBUG(f"pointer_slot_known_access_selected {({
                            'offset': word_offset,
                            'expr': str(val_symbol),
                            'source': str(source_expr),
                            'value': hex(actual_value),
                            'pointer_offset': pointer_offset,
                            'known_access_offset': known_access_offset,
                            'residual': target,
                            'constraints_added': added,
                            'constraints_assumed': assumed,
                        })}")
                    write_stage(
                        "init:materialize_init:memory_values:slot",
                        offset=word_offset,
                        phase="chosen",
                        pointer_like=True,
                        sp_affine=bool(slot.get('sp_affine')),
                    )
                    return actual_value
                return None

            known_access_value = choose_pointer_value_from_known_access_slots()
            if known_access_value is not None:
                return known_access_value
            val_vars = expr_vars(val_symbol)
            constrained_slot_value = bool(val_vars) and any(
                getattr(constraint, 'variables', set()) & val_vars
                for constraint in candidate_solver.constraints
            )
            pointer_feeds_later_store = bool(val_vars) and any(
                expr_vars(store_addr_symbol) & val_vars
                for _, store_addr_symbol, _, _, _ in store_accesses
            )
            if (
                len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
                and not slot.get('pointer_like')
                and not slot.get('sp_affine')
                and not slot.get('must_be_pointer')
            ):
                zero_constraint = val_symbol == expr_bvv(0, val_symbol)
                if (
                    try_add_constraint_set_fast(
                        [zero_constraint],
                        timeout_ms=local_solver_timeout_ms,
                    )
                    or try_add_constraint_set_related(
                        [zero_constraint],
                        val_vars,
                        timeout_ms=max(local_solver_timeout_ms, 1000),
                    )
                ):
                    slot['chosen_value'] = 0
                    write_stage(
                        "init:materialize_init:memory_values:slot",
                        offset=word_offset,
                        phase="chosen",
                        pointer_like=False,
                        sp_affine=False,
                    )
                    return 0
            if (
                len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
                and slot.get('pointer_like')
                and preferred_value is not None
                and expr_key(val_symbol) == expr_key(slot['symbol'])
            ):
                actual_value = preferred_value & ((1 << 64) - 1)
                if add_pointer_candidate_constraints(
                    actual_value,
                    [val_symbol == expr_bvv(actual_value, val_symbol)],
                    seed_vars=expr_vars(val_symbol),
                    timeout_ms=local_solver_timeout_ms,
                ):
                    slot['chosen_value'] = actual_value
                    if os.environ.get("RVMCA_DEBUG_POINTER_VALUE") == "1":
                        DEBUG(f"pointer_slot_concrete_selected {({
                            'offset': word_offset,
                            'expr': str(val_symbol),
                            'value': hex(actual_value),
                            'stack_offset': preferred_offset,
                        })}")
                    write_stage(
                        "init:materialize_init:memory_values:slot",
                        offset=word_offset,
                        phase="chosen",
                        pointer_like=True,
                        sp_affine=bool(slot.get('sp_affine')),
                    )
                    return actual_value
            if (
                constrained_slot_value
                and not slot.get('pointer_like')
                and not slot.get('sp_affine')
                and not slot.get('must_be_pointer')
            ):
                for model_value in solver_eval_current(val_symbol, n=8, timeout_ms=5000):
                    model_value &= ((1 << 64) - 1)
                    model_constraint = val_symbol == expr_bvv(model_value, val_symbol)
                    if (
                        try_add_constraint_set_fast([model_constraint], timeout_ms=5000)
                        or try_add_constraint_set_related(
                            [model_constraint],
                            val_vars,
                            timeout_ms=5000,
                        )
                    ):
                        slot['chosen_value'] = model_value
                        write_stage(
                            "init:materialize_init:memory_values:slot",
                            offset=word_offset,
                            phase="chosen",
                            pointer_like=False,
                            sp_affine=False,
                        )
                        return model_value
            if slot.get('pointer_like') and preferred_offset is not None and not pointer_feeds_later_store:
                offset = preferred_offset
                attempts = 0
                max_pointer_slot_attempts = 2 if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD else 32
                pointer_slot_timeout_ms = 100 if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD else 1000
                while offset is not None and attempts < max_pointer_slot_attempts:
                    value = concrete_stack_addr(offset)
                    value_constraint = val_symbol == expr_bvv(value, val_symbol)
                    if not add_pointer_candidate_constraints(
                        value,
                        [value_constraint],
                        seed_vars=expr_vars(val_symbol),
                        timeout_ms=pointer_slot_timeout_ms,
                    ):
                        attempts += 1
                        offset = next_free_stack_offset(
                            used_mem_offsets,
                            align=INIT_ACCESS_ALIGN,
                            width=INIT_ACCESS_SLOT_WIDTH,
                            start=offset + INIT_ACCESS_ALIGN,
                        )
                        continue
                    actual_value = value & ((1 << 64) - 1)
                    slot['chosen_value'] = actual_value
                    write_stage(
                        "init:materialize_init:memory_values:slot",
                        offset=word_offset,
                        phase="chosen",
                        pointer_like=True,
                        sp_affine=bool(slot.get('sp_affine')),
                    )
                    return actual_value
                    attempts += 1
                    offset = next_free_stack_offset(
                        used_mem_offsets,
                        align=INIT_ACCESS_ALIGN,
                        width=INIT_ACCESS_SLOT_WIDTH,
                        start=offset + INIT_ACCESS_ALIGN,
                    )
                if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD:
                    offset = _align_up(max(INIT_PTR_MIN_OFFSET, slot.get('min_pointer_offset') or 0), INIT_ACCESS_ALIGN)
                    relaxed_attempts = 0
                    while offset <= STACK_RANGE and relaxed_attempts < 4:
                        value = concrete_stack_addr(offset)
                        value_constraint = val_symbol == expr_bvv(value, val_symbol)
                        if not add_pointer_candidate_constraints(
                            value,
                            [value_constraint],
                            seed_vars=expr_vars(val_symbol),
                            timeout_ms=100,
                        ):
                            relaxed_attempts += 1
                            offset += INIT_ACCESS_ALIGN
                            continue
                        actual_value = value & ((1 << 64) - 1)
                        slot['chosen_value'] = actual_value
                        write_stage(
                            "init:materialize_init:memory_values:slot",
                            offset=word_offset,
                            phase="chosen",
                            pointer_like=True,
                            sp_affine=bool(slot.get('sp_affine')),
                        )
                        return actual_value
                if len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD and preferred_value is not None:
                    actual_value = preferred_value & ((1 << 64) - 1)
                    preferred_constraint = val_symbol == expr_bvv(actual_value, val_symbol)
                    if add_pointer_candidate_constraints(
                        actual_value,
                        [preferred_constraint],
                        seed_vars=expr_vars(val_symbol),
                        timeout_ms=local_solver_timeout_ms,
                    ):
                        slot['chosen_value'] = actual_value
                        write_stage(
                            "init:materialize_init:memory_values:slot",
                            offset=word_offset,
                            phase="chosen",
                            pointer_like=True,
                            sp_affine=bool(slot.get('sp_affine')),
                        )
                        return actual_value
            if (
                slot.get('scalar_zero')
                and not slot.get('pointer_like')
                and not slot.get('sp_affine')
                and not slot.get('must_be_pointer')
            ):
                zero_constraint = val_symbol == expr_bvv(0, val_symbol)
                if try_add_constraint_set_fast([zero_constraint], timeout_ms=local_solver_timeout_ms):
                    val = 0
                    slot['chosen_value'] = val
                    write_stage(
                        "init:materialize_init:memory_values:slot",
                        offset=word_offset,
                        phase="chosen",
                        pointer_like=False,
                        sp_affine=False,
                    )
                    return val
            if (
                len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                and not slot.get('pointer_like')
                and not slot.get('sp_affine')
                and not slot.get('must_be_pointer')
                and bool(val_vars)
                and not constrained_slot_value
            ):
                val = 0
                if strict_retry_validation:
                    zero_constraint = val_symbol == expr_bvv(val, val_symbol)
                    candidate_solver.add(zero_constraint)
                    added_constraint_cache.add(str(claripy.simplify(zero_constraint)))
                    debug_constraint_add("unconstrained_slot_zero", zero_constraint)
                slot['chosen_value'] = val
                write_stage(
                    "init:materialize_init:memory_values:slot",
                    offset=word_offset,
                    phase="chosen",
                    pointer_like=False,
                    sp_affine=False,
                )
                return val
            try:
                if os.environ.get("RVMCA_DEBUG_POINTER_VALUE") == "1" and slot.get('pointer_like'):
                    DEBUG(f"pointer_slot_choose_memory {({
                        'offset': word_offset,
                        'symbol': str(slot.get('symbol')),
                        'val_symbol': str(val_symbol),
                        'direct_value_expr': str(slot.get('direct_value_expr')),
                        'value_exprs': [str(expr) for expr in slot.get('value_exprs', [])],
                        'must_be_pointer': bool(slot.get('must_be_pointer')),
                        'min_pointer_offset': slot.get('min_pointer_offset'),
                        'sp_affine': bool(slot.get('sp_affine')),
                        'scalar_zero': bool(slot.get('scalar_zero')),
                    })}")
                val = choose_memory_value(
                    val_symbol,
                    preferred_value,
                    avoid_stack_offsets=used_mem_offsets,
                    pointer_like=slot['pointer_like'],
                    min_pointer_offset=slot.get('min_pointer_offset'),
                    allow_pointer_scalar_fallback=not slot.get('must_be_pointer'),
                    pointer_candidate_ok=pointer_candidate_related_ranges_ok,
                    pointer_alias_exprs=slot.get('value_exprs', []),
                )
            except AssertionError:
                if slot.get('pointer_like') or slot.get('sp_affine'):
                    raise
                val = 0
                if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD:
                    candidate_solver.add(val_symbol == expr_bvv(val, val_symbol))
                elif not try_add_constraint_set_fast([val_symbol == expr_bvv(val, val_symbol)]):
                    raise
            actual_value = val & ((1 << 64) - 1)
            slot['chosen_value'] = actual_value
            write_stage(
                "init:materialize_init:memory_values:slot",
                offset=word_offset,
                phase="chosen",
                pointer_like=bool(slot.get('pointer_like')),
                sp_affine=bool(slot.get('sp_affine')),
            )
            return actual_value

        def next_free_stack_offset(avoid_ranges, align=1, width=INIT_ACCESS_SLOT_WIDTH, start=1):
            align = align if align else 1
            offset = _align_up(start, align)
            while offset <= STACK_RANGE:
                if not any(
                    concrete_ranges_overlap(offset, width, used_offset, used_width)
                    for used_offset, used_width in avoid_ranges
                ):
                    return offset
                offset += align
            return None

        def equiv_normalized_expr_key(expr):
            key = expr_key(expr)
            for var in sorted(expr_vars(expr), key=len, reverse=True):
                key = key.replace(var, equiv_find(var))
            return key

        def remember_affine_base_offset(base_key, base_expr, base_offset):
            affine_base_offset_choices[base_key] = base_offset
            if not expr_vars(base_expr):
                return
            record_key = expr_key(base_expr)
            for idx, (known_key, _, _) in enumerate(affine_base_offset_records):
                if known_key == record_key:
                    affine_base_offset_records[idx] = (record_key, base_expr, base_offset)
                    return
            affine_base_offset_records.append((record_key, base_expr, base_offset))

        def affine_base_offsets_for(base_key, base_expr):
            offsets = []
            seen_offsets = set()
            direct_offset = affine_base_offset_choices.get(base_key)
            if direct_offset is not None:
                offsets.append(direct_offset)
                seen_offsets.add(direct_offset)
            if expr_vars(base_expr):
                target_key = equiv_normalized_expr_key(base_expr)
                for _, known_base_expr, known_offset in affine_base_offset_records:
                    if known_offset in seen_offsets:
                        continue
                    if equiv_normalized_expr_key(known_base_expr) != target_key:
                        continue
                    offsets.append(known_offset)
                    seen_offsets.add(known_offset)
            return offsets

        def min_offset_for_affine_base(base_key):
            if base_key in affine_base_min_offset_cache:
                return affine_base_min_offset_cache[base_key]
            minimum = INIT_PTR_MIN_OFFSET
            for _, access_addr_symbol, _, access_width in mem_accesses:
                if (
                    len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                    and ast_node_count(access_addr_symbol) > 64
                ):
                    continue
                access_affine = affine_key(access_addr_symbol)
                if access_affine is None:
                    continue
                access_base_key, access_imm, _ = access_affine
                if access_base_key != base_key:
                    continue
                minimum = max(minimum, access_imm + access_width)
            minimum = max(INIT_PTR_MIN_OFFSET, minimum)
            affine_base_min_offset_cache[base_key] = minimum
            return minimum

        def choose_affine_addr_offset(addr_symbol, addr_expr, preferred, align, avoid_ranges, width):
            debug_load_slots = os.environ.get("RVMCA_DEBUG_LOAD_SLOTS") == "1"

            def debug_affine_choice(event, **fields):
                if debug_load_slots:
                    fields.setdefault('addr', str(addr_symbol))
                    DEBUG(f"affine_addr_{event} {fields}")

            if (
                len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
                and any(getattr(node, 'op', None) in {'__mul__', 'Mul'} for node in iter_ast_nodes(addr_symbol))
            ):
                debug_affine_choice("skip_long_mul")
                return None
            if (
                len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                and ast_node_count(addr_symbol) > 64
            ):
                debug_affine_choice("skip_complex", nodes=ast_node_count(addr_symbol))
                return None
            affine = affine_key(addr_symbol)
            if affine is None:
                debug_affine_choice("skip_non_affine")
                return None
            base_key, imm, base = affine
            if not expr_vars(base):
                debug_affine_choice("skip_concrete_base", base=str(base), imm=imm)
                return None
            loaded_pointer_base = bool(expr_vars(base) & (pointer_loaded_addr_vars | address_loaded_addr_vars))
            step = align if align else 1
            debug_affine_choice(
                "start",
                base=str(base),
                imm=imm,
                loaded_pointer_base=loaded_pointer_base,
                preferred=preferred,
                align=align,
                width=width,
            )

            def access_ok(access_offset):
                if access_offset <= 0 or access_offset > STACK_RANGE:
                    return False
                if align and access_offset % align != 0:
                    return False
                if not fixed_sp_affine_quotient_compatible(
                    addr_symbol,
                    access_offset,
                    width,
                    avoid_ranges,
                ):
                    return False
                if any(
                    concrete_ranges_overlap(access_offset, width, used, used_width)
                        for used, used_width in avoid_ranges
                ):
                    return False
                return True

            def access_shape_ok(access_offset):
                if access_offset <= 0 or access_offset > STACK_RANGE:
                    return False
                if align and access_offset % align != 0:
                    return False
                return True

            if len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD:
                for reg, value in reg_values.items():
                    symbol = reg_to_symbol.get(reg)
                    if symbol is None or expr_key(symbol) != base_key:
                        continue
                    base_offset = stack_offset_for_value(value)
                    if base_offset is None:
                        continue
                    access_offset = base_offset - imm
                    if access_ok(access_offset):
                        constraint = addr_expr == access_offset
                        if (
                            try_add_constraint_set_fast([constraint], timeout_ms=5000)
                            or try_add_constraint_set_related(
                                [constraint],
                                expr_vars(addr_expr),
                                timeout_ms=5000,
                            )
                        ):
                            remember_affine_base_offset(base_key, base, base_offset)
                            debug_affine_choice(
                                "choose_materialized_reg",
                                access_offset=access_offset,
                                base_offset=base_offset,
                            )
                            return access_offset

            cached_base_offsets = affine_base_offsets_for(base_key, base)
            if cached_base_offsets:
                for cached_base_offset in cached_base_offsets:
                    access_offset = cached_base_offset - imm
                    if os.environ.get("RVMCA_DEBUG_LOAD_SLOTS") == "1":
                        DEBUG(f"affine_addr_cached_base {({
                            'addr': str(addr_symbol),
                            'base_key': base_key,
                            'base_offset': cached_base_offset,
                            'imm': imm,
                            'access_offset': access_offset,
                            'access_ok': access_ok(access_offset),
                            'avoid': avoid_ranges,
                        })}")
                    if access_ok(access_offset):
                        constraint = addr_expr == access_offset
                        if (
                            try_add_constraint_set_fast([constraint], timeout_ms=5000)
                            or try_add_constraint_set_related(
                                [constraint],
                                expr_vars(addr_expr),
                                timeout_ms=5000,
                            )
                        ):
                            return access_offset
                        if os.environ.get("RVMCA_DEBUG_LOAD_SLOTS") == "1":
                            DEBUG(f"affine_addr_cached_base_reject_solver {({
                                'addr': str(addr_symbol),
                                'base_offset': cached_base_offset,
                                'access_offset': access_offset,
                            })}")
                    elif (
                        loaded_pointer_base
                        and len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                        and access_shape_ok(access_offset)
                    ):
                        debug_affine_choice(
                            "reject_cached_base_overlap",
                            base_offset=cached_base_offset,
                            access_offset=access_offset,
                            avoid=avoid_ranges,
                        )
                if not loaded_pointer_base:
                    return None

            if loaded_pointer_base:
                carrier_min_base_offset = max(INIT_PTR_MIN_OFFSET, width)
                min_base_offset = max(
                    min_offset_for_affine_base(base_key),
                    carrier_min_base_offset,
                )
                starts = []
                starts.extend([
                    0xc00 - imm,
                    0x800 - imm,
                    0x400 - imm,
                    min_base_offset - imm,
                ])
                if preferred is not None:
                    starts.append(preferred)
                starts.extend(used + max(width, used_width) for used, used_width in avoid_ranges)
                seen_access_offsets = set()
                attempts = 0
                max_attempts = 96 if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD else 16
                attempts_per_start = 16 if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD else 16
                for start in starts:
                    access_start = max(1, start)
                    if align:
                        access_start = _align_up(access_start, align)
                    start_attempts = 0
                    for access_offset in range(access_start, min(STACK_RANGE, access_start + 512) + 1, step):
                        if attempts >= max_attempts:
                            debug_affine_choice("loaded_pointer_failed", attempts=attempts)
                            return None
                        if start_attempts >= attempts_per_start:
                            break
                        if access_offset in seen_access_offsets:
                            continue
                        seen_access_offsets.add(access_offset)
                        if not access_ok(access_offset):
                            continue
                        base_offset = access_offset + imm
                        if base_offset < min_base_offset:
                            continue
                        if (
                            base_offset < carrier_min_base_offset
                            or base_offset <= 0
                            or base_offset > STACK_RANGE
                        ):
                            continue
                        attempts += 1
                        start_attempts += 1
                        constraints = [
                            (init_sp - base) == base_offset,
                            addr_expr == access_offset,
                        ]
                        if (
                            try_add_constraint_set_fast(constraints, timeout_ms=5000)
                            or try_add_constraint_set_related(
                                constraints,
                                expr_vars(addr_expr) | expr_vars(base),
                                timeout_ms=5000,
                            )
                        ):
                            remember_affine_base_offset(base_key, base, base_offset)
                            debug_affine_choice(
                                "choose_loaded_pointer_uncached",
                                access_offset=access_offset,
                                base_offset=base_offset,
                            )
                            return access_offset
                        if (
                            len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                            and ast_node_count(addr_symbol) <= 128
                        ):
                            affine_sat = constraint_set_related_satisfiable(
                                constraints,
                                expr_vars(addr_expr) | expr_vars(base),
                                timeout_ms=5000,
                            )
                            if affine_sat is not False:
                                for constraint in constraints:
                                    candidate_solver.add(constraint)
                                    added_constraint_cache.add(str(claripy.simplify(constraint)))
                                    debug_constraint_add("affine_loaded_base_assumed", constraint)
                                remember_affine_base_offset(base_key, base, base_offset)
                                debug_affine_choice(
                                    "choose_loaded_pointer_assumed",
                                    access_offset=access_offset,
                                    base_offset=base_offset,
                                )
                                return access_offset
                        debug_affine_choice(
                            "reject_loaded_pointer_uncached",
                            access_offset=access_offset,
                            base_offset=base_offset,
                        )
                debug_affine_choice("loaded_pointer_failed", attempts=attempts)
                return None

            if len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD:
                debug_affine_choice("skip_long_block_uncached")
                return None

            starts = []
            if preferred is not None:
                starts.append(preferred)
            min_base_offset = min_offset_for_affine_base(base_key)
            starts.append(min_base_offset - imm)
            starts.extend(used + max(width, used_width) for used, used_width in avoid_ranges)

            seen_access_offsets = set()
            attempts = 0
            max_attempts = 2 if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD else 8
            for start in sorted(starts):
                access_start = max(1, start)
                if align:
                    access_start = _align_up(access_start, align)
                for access_offset in range(access_start, min(STACK_RANGE, access_start + 512) + 1, step):
                    if attempts >= max_attempts:
                        return None
                    if access_offset in seen_access_offsets:
                        continue
                    seen_access_offsets.add(access_offset)
                    if not access_ok(access_offset):
                        continue
                    base_offset = access_offset + imm
                    if base_offset < min_base_offset:
                        continue
                    if base_offset <= 0 or base_offset > STACK_RANGE:
                        continue
                    attempts += 1
                    constraints = [
                        (init_sp - base) == base_offset,
                        addr_expr == access_offset,
                    ]
                    debug_affine_choice(
                        "try",
                        access_offset=access_offset,
                        base_offset=base_offset,
                        attempts=attempts,
                    )
                    if (
                        try_add_constraint_set_fast(constraints)
                        if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                        else try_add_constraint_set(constraints)
                    ):
                        remember_affine_base_offset(base_key, base, base_offset)
                        debug_affine_choice(
                            "choose",
                            access_offset=access_offset,
                            base_offset=base_offset,
                        )
                        return access_offset
            debug_affine_choice("failed", attempts=attempts)
            return None

        def choose_pointer_load_addr_offset(
            addr_symbol,
            addr_expr,
            preferred,
            align,
            avoid_ranges,
            width,
            current_load_value_expr,
            current_load_idx,
        ):
            long_block = len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
            if long_block and ast_node_count(addr_symbol) > 512:
                return None
            addr_vars = expr_vars(addr_symbol)
            debug_load_slots = os.environ.get("RVMCA_DEBUG_LOAD_SLOTS") == "1"
            candidate_timeout_ms = 50 if long_block else 5000
            related_candidate_timeout_ms = 100 if long_block else 5000

            def debug_pointer_choice(event, **fields):
                if debug_load_slots:
                    fields.setdefault('addr', str(addr_symbol))
                    DEBUG(f"pointer_load_addr_{event} {fields}")

            def debug_pointer_sat(constraints):
                if not debug_load_slots:
                    return None
                test_solver = candidate_solver.branch()
                test_solver.timeout = 50 if long_block else 1000
                try:
                    for constraint in constraints:
                        test_solver.add(constraint)
                    return bool(test_solver.satisfiable())
                except Exception as exc:
                    return type(exc).__name__

            def remember_pointer_base_offset(rd_symbol, pointer_offset):
                affine_base_offset_choices[expr_key(rd_symbol)] = pointer_offset
                remember_equiv_base_offset(rd_symbol, pointer_offset)
                current_affine = affine_key(addr_symbol)
                if current_affine is not None:
                    remember_affine_base_offset(current_affine[0], current_affine[2], pointer_offset)
                    remember_equiv_base_offset(current_affine[2], pointer_offset)
                base_offset_eval_cache.clear()

            def pointer_table_access_should_avoid_low_guard(access_offset):
                if not (
                    long_block
                    and width == 8
                    and access_offset > STACK_RANGE - LIVEIN_STORE_LOW_GUARD_OFFSET
                ):
                    return False
                try:
                    if not current_pointer_like_load:
                        return False
                    current_value_vars = expr_vars(mem_value_expr(inst, rd_symbol))
                except NameError:
                    return False
                if current_value_vars and any(
                    store_idx > inst_idx
                    and (expr_vars(store_addr_symbol) & current_value_vars)
                    for _, store_addr_symbol, store_idx, _, _ in store_accesses
                ):
                    return True
                return addr_has_loaded_base_with_residual_scalar(
                    addr_symbol,
                    scaled_only=False,
                )

            base_offset_eval_cache = {}

            def current_pointer_base_offsets(rd_symbol):
                rd_key = expr_key(rd_symbol)
                if rd_key not in base_offset_eval_cache:
                    offsets = []
                    seen_offsets = set()
                    known_offset = affine_base_offset_choices.get(rd_key)
                    if (
                        known_offset is not None
                        and known_offset > 0
                        and known_offset <= STACK_RANGE
                    ):
                        seen_offsets.add(known_offset)
                        offsets.append(known_offset)
                    equiv_key = expr_equiv_offset_key(rd_symbol)
                    if equiv_key is not None:
                        for known_offset in equiv_base_offset_choices.get(equiv_key, []):
                            if (
                                known_offset <= 0
                                or known_offset > STACK_RANGE
                                or known_offset in seen_offsets
                            ):
                                continue
                            seen_offsets.add(known_offset)
                            offsets.append(known_offset)
                    for value in solver_eval_current(
                        init_sp - rd_symbol,
                        n=4 if long_block else 16,
                        timeout_ms=100 if long_block else 1000,
                    ):
                        offset = _signed_u64(value)
                        if offset <= 0 or offset > STACK_RANGE or offset in seen_offsets:
                            continue
                        seen_offsets.add(offset)
                        offsets.append(offset)
                    base_offset_eval_cache[rd_key] = offsets
                return base_offset_eval_cache[rd_key]

            def choose_direct_pointer_base_addr(rd_symbol, rd_vars, load_idx):
                pointer_avoid_ranges = []
                load_addr_symbol = None
                for _, candidate_rd, candidate_addr, candidate_idx in load_accesses:
                    if candidate_idx == load_idx and expr_key(candidate_rd) == expr_key(rd_symbol):
                        load_addr_symbol = candidate_addr
                        break
                if load_addr_symbol is not None:
                    load_offset = addr_expr_offsets.get(expr_key(load_addr_symbol))
                    if load_offset is not None:
                        pointer_avoid_ranges.append((load_offset, INIT_ACCESS_SLOT_WIDTH))
                base_start = min_pointer_offset_for_vars(
                    rd_vars,
                    load_idx,
                    avoid_ranges=pointer_avoid_ranges,
                )
                base_start = max(base_start, width)

                pointer_offsets = []
                pointer_offsets.extend(current_pointer_base_offsets(rd_symbol))
                pointer_offsets.extend([0xc00, 0x800, 0x400, base_start, 0x200])
                seen_pointer_offsets = set()
                pointer_offsets = [
                    offset
                    for offset in pointer_offsets
                    if not (offset in seen_pointer_offsets or seen_pointer_offsets.add(offset))
                ]

                access_starts = []
                if preferred is not None:
                    access_starts.append(preferred)
                access_starts.append(_align_up(1, align) if align else 1)
                access_starts.extend(used + max(width, used_width) for used, used_width in avoid_ranges)
                step = align if align else 1
                low = _align_up(1, align) if align else 1
                attempts = 0
                max_attempts = 8 if long_block else 48
                for pointer_offset in pointer_offsets:
                    if pointer_offset < base_start or pointer_offset <= 0 or pointer_offset > STACK_RANGE:
                        continue
                    seen_offsets = set()
                    for start in access_starts:
                        start = max(start, low)
                        if align:
                            start = _align_up(start, align)
                        for access_offset in range(start, min(STACK_RANGE, start + 256) + 1, step):
                            if attempts >= max_attempts:
                                return None
                            if access_offset in seen_offsets:
                                continue
                            seen_offsets.add(access_offset)
                            if access_offset <= 0 or access_offset > STACK_RANGE:
                                continue
                            if align and access_offset % align:
                                continue
                            if pointer_table_access_should_avoid_low_guard(access_offset):
                                debug_pointer_choice(
                                    "reject_low_guard_pointer_table",
                                    access_offset=access_offset,
                                    guard=LIVEIN_STORE_LOW_GUARD_OFFSET,
                                )
                                continue
                            if any(
                                concrete_ranges_overlap(access_offset, width, used, used_width)
                                for used, used_width in avoid_ranges
                            ):
                                continue
                            constraints = [
                                (init_sp - rd_symbol) == pointer_offset,
                                addr_expr == access_offset,
                            ]
                            attempts += 1
                            if not pointer_offset_keeps_derived_accesses_available(
                                rd_symbol,
                                rd_vars,
                                pointer_offset,
                                avoid_ranges,
                                constraints,
                                producer_load_addr_symbol=load_addr_symbol,
                                producer_idx=load_idx,
                            ):
                                continue
                            if (
                                try_add_constraint_set_fast(constraints, timeout_ms=candidate_timeout_ms)
                                or try_add_constraint_set_related(
                                    constraints,
                                    expr_vars(addr_expr) | rd_vars,
                                    timeout_ms=related_candidate_timeout_ms,
                                )
                            ):
                                remember_pointer_base_offset(rd_symbol, pointer_offset)
                                debug_pointer_choice(
                                    "choose_direct_base",
                                    access_offset=access_offset,
                                    pointer_offset=pointer_offset,
                                )
                                return access_offset
                            debug_pointer_choice(
                                "reject_direct_base",
                                access_offset=access_offset,
                                pointer_offset=pointer_offset,
                                base_sat=debug_pointer_sat([(init_sp - rd_symbol) == pointer_offset]),
                                addr_sat=debug_pointer_sat([addr_expr == access_offset]),
                                base_addr_sat=debug_pointer_sat(constraints),
                                related_constraints=[
                                    str(claripy.simplify(constraint))[:500]
                                    for constraint in candidate_solver.constraints
                                    if expr_vars(constraint) & rd_vars
                                ][:8] if debug_load_slots and pointer_offset in {0x800, 0xc00} else [],
                            )
                return None

            def pointer_offset_keeps_derived_accesses_available(
                rd_symbol,
                rd_vars,
                pointer_offset,
                related_avoid_ranges=None,
                candidate_constraints=None,
                producer_load_addr_symbol=None,
                producer_idx=None,
            ):
                related_avoid_ranges = [] if related_avoid_ranges is None else related_avoid_ranges
                candidate_constraints = [] if candidate_constraints is None else candidate_constraints
                related_pointer_sources = [(rd_symbol, rd_vars)]
                if producer_load_addr_symbol is not None and producer_idx is not None:
                    for sibling_inst, sibling_rd_symbol, sibling_addr_symbol, sibling_idx in load_accesses:
                        if sibling_idx == producer_idx or sibling_inst.width != 8:
                            continue
                        sibling_vars = expr_vars(sibling_rd_symbol)
                        if not sibling_vars:
                            continue
                        if any(sibling_vars == known_vars for _, known_vars in related_pointer_sources):
                            continue
                        if not same_address(
                            sibling_addr_symbol,
                            producer_load_addr_symbol,
                            allow_solver=False,
                        ):
                            continue
                        if has_intervening_same_addr_store(
                            producer_load_addr_symbol,
                            min(producer_idx, sibling_idx),
                            max(producer_idx, sibling_idx),
                            allow_solver=False,
                        ):
                            continue
                        related_pointer_sources.append((sibling_rd_symbol, sibling_vars))

                def prior_store_may_clobber_related_slot(
                    related_addr_symbol,
                    related_offset,
                    related_slot_width,
                    related_idx,
                ):
                    for _, store_addr_symbol, store_idx, store_width, _ in store_accesses:
                        if store_idx >= related_idx:
                            continue
                        if same_address(related_addr_symbol, store_addr_symbol, allow_solver=False):
                            continue
                        store_offset = concrete_stack_offset_for_addr_expr(store_addr_symbol)
                        if store_offset is not None:
                            if concrete_ranges_overlap(
                                related_offset,
                                related_slot_width,
                                store_offset,
                                init_slot_width(store_width),
                            ):
                                return True
                            continue
                        if exprs_may_be_related(related_addr_symbol, store_addr_symbol):
                            return True
                    return False

                def forced_same_derived_overlap(related_addr_symbol, used_addr_symbol, related_offset):
                    if same_address(related_addr_symbol, used_addr_symbol, allow_solver=False):
                        return True
                    if not exprs_may_be_related(related_addr_symbol, used_addr_symbol):
                        return False
                    test_solver = candidate_solver.branch()
                    test_solver.timeout = max(related_candidate_timeout_ms, 1000)
                    try:
                        test_solver.add((init_sp - rd_symbol) == pointer_offset)
                        test_solver.add((init_sp - related_addr_symbol) == related_offset)
                        test_solver.add(related_addr_symbol != used_addr_symbol)
                        return not test_solver.satisfiable()
                    except Exception:
                        return False

                def forced_same_existing_access(related_addr_symbol, existing_addr_symbol):
                    if same_address(related_addr_symbol, existing_addr_symbol, allow_solver=False):
                        return True
                    if not candidate_constraints:
                        return False
                    if not exprs_may_be_related(related_addr_symbol, existing_addr_symbol):
                        return False
                    test_solver = candidate_solver.branch()
                    test_solver.timeout = max(related_candidate_timeout_ms, 1000)
                    try:
                        for constraint in candidate_constraints:
                            test_solver.add(constraint)
                        test_solver.add(related_addr_symbol != existing_addr_symbol)
                        return not test_solver.satisfiable()
                    except Exception:
                        return False

                def derived_access_forbidden_by_avoid(
                    access_offset,
                    related_slot_width,
                    related_addr_symbol,
                ):
                    for used_offset, used_width in related_avoid_ranges:
                        if not concrete_ranges_overlap(
                            access_offset,
                            related_slot_width,
                            used_offset,
                            used_width,
                        ):
                            continue
                        same_existing_access = False
                        for existing_addr, existing_width, existing_addr_symbol in access_ranges:
                            if not concrete_ranges_overlap(
                                access_offset,
                                related_slot_width,
                                existing_addr,
                                existing_width,
                            ):
                                continue
                            if same_address(
                                related_addr_symbol,
                                existing_addr_symbol,
                                allow_solver=False,
                            ) or (
                                related_slot_width == 8
                                and existing_width == 8
                                and forced_same_existing_access(
                                    related_addr_symbol,
                                    existing_addr_symbol,
                                )
                            ):
                                same_existing_access = True
                                break
                        if same_existing_access:
                            continue
                        debug_pointer_choice(
                            "reject_derived_avoid_overlap",
                            pointer_offset=pointer_offset,
                            related_offset=access_offset,
                            related_width=related_slot_width,
                            used_addr=used_offset,
                            used_width=used_width,
                            related=str(related_addr_symbol),
                        )
                        return True
                    return False

                source_keys = tuple(
                    (expr_key(candidate_symbol), tuple(sorted(candidate_vars)))
                    for candidate_symbol, candidate_vars in related_pointer_sources
                )
                avoid_key = tuple(sorted(related_avoid_ranges))
                constraints_key = tuple(
                    str(claripy.simplify(constraint))
                    for constraint in candidate_constraints
                )
                cache_key = (
                    source_keys,
                    pointer_offset,
                    avoid_key,
                    producer_idx,
                    constraints_key,
                ) if long_block else None
                if cache_key is not None and cache_key in pointer_derived_availability_cache:
                    return pointer_derived_availability_cache[cache_key]

                def finish_derived_availability(result):
                    if cache_key is not None:
                        pointer_derived_availability_cache[cache_key] = result
                    return result

                related_scan_entries = mem_accesses
                if long_block:
                    scan_key = (source_keys, producer_idx)
                    if scan_key not in pointer_derived_access_cache:
                        selected_entries = []
                        for entry in mem_accesses:
                            _, scan_addr_symbol, scan_idx, _ = entry
                            if producer_idx is not None and scan_idx <= producer_idx:
                                continue
                            scan_vars = expr_vars(scan_addr_symbol)
                            if any(scan_vars & candidate_vars for _, candidate_vars in related_pointer_sources):
                                selected_entries.append(entry)
                        pointer_derived_access_cache[scan_key] = selected_entries[:64]
                    related_scan_entries = pointer_derived_access_cache[scan_key]

                for _, related_addr_symbol, related_idx, related_width in related_scan_entries:
                    related_addr_vars = expr_vars(related_addr_symbol)
                    source_symbol = None
                    source_vars = None
                    for candidate_symbol, candidate_vars in related_pointer_sources:
                        if related_addr_vars & candidate_vars:
                            source_symbol = candidate_symbol
                            source_vars = candidate_vars
                            break
                    if source_symbol is None or source_vars is None:
                        continue
                    residual = additive_residual_without_term(
                        related_addr_symbol,
                        source_symbol,
                    )
                    if residual is None:
                        residual = claripy.simplify(related_addr_symbol - source_symbol)
                    residual_value = concrete_expr_value(residual)
                    if residual_value is None:
                        if expr_vars(residual) & source_vars:
                            related_affine = affine_key(related_addr_symbol)
                            if related_affine is None or related_affine[0] != expr_key(source_symbol):
                                continue
                            residual_value = related_affine[1]
                        else:
                            continue
                    imm = _signed_u64(residual_value)
                    access_offset = pointer_offset - imm
                    if access_offset <= 0 or access_offset > STACK_RANGE:
                        debug_pointer_choice(
                            "reject_derived_range",
                            pointer_offset=pointer_offset,
                            related_offset=access_offset,
                            related=str(related_addr_symbol),
                        )
                        return finish_derived_availability(False)
                    if related_width > 1 and access_offset % related_width:
                        debug_pointer_choice(
                            "reject_derived_align",
                            pointer_offset=pointer_offset,
                            related_offset=access_offset,
                            related_width=related_width,
                            related=str(related_addr_symbol),
                        )
                        return finish_derived_availability(False)
                    if (
                        long_block
                        and related_width == 8
                        and access_offset > STACK_RANGE - LIVEIN_STORE_LOW_GUARD_OFFSET
                        and prior_store_may_clobber_related_slot(
                            related_addr_symbol,
                            access_offset,
                            init_slot_width(related_width),
                            related_idx,
                        )
                    ):
                        debug_pointer_choice(
                            "reject_derived_low_guard_prior_store",
                            pointer_offset=pointer_offset,
                            related_offset=access_offset,
                            related=str(related_addr_symbol),
                        )
                        return finish_derived_availability(False)
                    related_slot_width = init_slot_width(related_width)
                    if derived_access_forbidden_by_avoid(
                        access_offset,
                        related_slot_width,
                        related_addr_symbol,
                    ):
                        return finish_derived_availability(False)
                    if related_width < 8:
                        access_word_offset = ((access_offset + 7) // 8) * 8
                        access_slot = mem_slot_symbols.get(access_word_offset)
                        if access_slot is not None and (
                            access_slot.get('pointer_like')
                            or access_slot.get('must_be_pointer')
                            or access_slot.get('sp_affine')
                        ):
                            debug_pointer_choice(
                                "reject_derived_slot_type",
                                pointer_offset=pointer_offset,
                                related_offset=access_offset,
                                word_offset=access_word_offset,
                                related=str(related_addr_symbol),
                            )
                            return finish_derived_availability(False)
                    related_scalar_zero = False
                    related_pointer_like = False
                    for related_load_inst, related_rd_symbol, _, related_load_idx in load_accesses:
                        if related_load_idx != related_idx:
                            continue
                        related_scalar_zero = is_scalar_zero_address_load(
                            related_load_inst,
                            related_rd_symbol,
                            related_load_idx,
                        )
                        related_entry = load_entries_by_idx.get(related_idx) if 'load_entries_by_idx' in locals() else None
                        related_pointer_like = (
                            related_entry is not None
                            and load_slot_entry_pointer_like(related_entry)
                        )
                        break
                    for used_addr, used_width, used_addr_symbol in access_ranges:
                        if not concrete_ranges_overlap(
                            access_offset,
                            related_slot_width,
                            used_addr,
                            used_width,
                        ):
                            continue
                        if same_address(related_addr_symbol, used_addr_symbol, allow_solver=False):
                            continue
                        used_word_offset = ((used_addr + 7) // 8) * 8
                        used_slot = mem_slot_symbols.get(used_word_offset)
                        if (
                            related_scalar_zero
                            and used_slot is not None
                            and used_slot.get('scalar_zero')
                            and not used_slot.get('pointer_like')
                            and not used_slot.get('must_be_pointer')
                            and not used_slot.get('sp_affine')
                        ):
                            continue
                        if (
                            related_width == 8
                            and used_width == 8
                            and used_slot is None
                            and len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                        ):
                            continue
                        if (
                            related_width == 8
                            and used_width == 8
                            and used_slot is not None
                            and not used_slot.get('scalar_zero')
                            and not used_slot.get('pointer_like')
                            and not used_slot.get('must_be_pointer')
                            and not used_slot.get('sp_affine')
                        ):
                            continue
                        if (
                            related_pointer_like
                            and used_slot is not None
                            and not used_slot.get('scalar_zero')
                            and not used_slot.get('pointer_like')
                            and not used_slot.get('must_be_pointer')
                            and not used_slot.get('sp_affine')
                        ):
                            continue
                        if (
                            related_pointer_like
                            and related_width == 8
                            and used_width == 8
                            and used_slot is not None
                            and not used_slot.get('scalar_zero')
                            and (
                                used_slot.get('pointer_like')
                                or used_slot.get('must_be_pointer')
                                or used_slot.get('sp_affine')
                            )
                            and forced_same_derived_overlap(
                                related_addr_symbol,
                                used_addr_symbol,
                                access_offset,
                            )
                        ):
                            continue
                        debug_pointer_choice(
                            "reject_derived_overlap",
                            pointer_offset=pointer_offset,
                            related_offset=access_offset,
                            related_width=related_slot_width,
                            used_addr=used_addr,
                            used_width=used_width,
                            used=str(used_addr_symbol),
                            related=str(related_addr_symbol),
                        )
                        return finish_derived_availability(False)
                return finish_derived_availability(True)

            source_load_candidates = []
            seen_source_loads = set()
            for load_entry in pointer_source_loads + address_source_loads:
                load_inst, rd_symbol, load_addr_symbol, load_idx = load_entry
                key = (load_idx, expr_key(rd_symbol))
                if key in seen_source_loads:
                    continue
                if key in scalar_load_hint_keys:
                    continue
                seen_source_loads.add(key)
                source_load_candidates.append(load_entry)
            for load_entry in load_accesses:
                load_inst, rd_symbol, load_addr_symbol, load_idx = load_entry
                if load_inst.width != 8:
                    continue
                key = (load_idx, expr_key(rd_symbol))
                if key in seen_source_loads:
                    continue
                rd_vars = expr_vars(rd_symbol)
                if not rd_vars or not (addr_vars & rd_vars):
                    continue
                residual = additive_residual_without_term(addr_symbol, rd_symbol)
                if residual is None:
                    residual = claripy.simplify(addr_symbol - rd_symbol)
                if expr_vars(residual) & rd_vars:
                    carrier_constraints = constraints_to_carrier(addr_symbol, rd_symbol)
                    if carrier_constraints is None:
                        continue
                elif (
                    not is_loaded_pointer_base_candidate(rd_symbol, load_idx)
                    and not expr_vars(residual)
                ):
                    continue
                seen_source_loads.add(key)
                source_load_candidates.append(load_entry)
                debug_pointer_choice(
                    "source_candidates",
                    count=len(source_load_candidates),
                    candidates=[
                        (load_idx, getattr(load_inst, 'code', str(load_inst)), str(rd_symbol))
                    for load_inst, rd_symbol, _, load_idx in source_load_candidates[:8]
                ],
                addr_vars=sorted(addr_vars),
            )

            def source_candidate_priority(load_entry):
                _load_inst, rd_symbol, _load_addr_symbol, load_idx = load_entry
                rd_vars = expr_vars(rd_symbol)
                if not rd_vars or not (addr_vars & rd_vars):
                    return (9, 0, 0)
                residual = additive_residual_without_term(addr_symbol, rd_symbol)
                if residual is None:
                    residual = claripy.simplify(addr_symbol - rd_symbol)
                residual_vars = expr_vars(residual)
                if residual_vars & rd_vars:
                    return (4, 0, -load_idx)
                residual_value = concrete_expr_value(residual)
                if residual_value is not None:
                    signed_residual = _signed_u64(residual_value)
                    return (
                        0 if abs(signed_residual) <= 64 else 1,
                        abs(signed_residual),
                        -load_idx,
                    )
                if residual_vars:
                    return (2, len(residual_vars), -load_idx)
                return (3, 0, -load_idx)

            source_load_candidates.sort(key=source_candidate_priority)
            deferred_low_guard_candidates = []
            seen_deferred_low_guard_candidates = set()

            def defer_low_guard_candidate(access_offset, pointer_offset, imm, rd_symbol, constraints, related_vars):
                key = (access_offset, pointer_offset, expr_key(rd_symbol), _signed_u64(imm))
                if key in seen_deferred_low_guard_candidates:
                    return
                if len(deferred_low_guard_candidates) >= 64:
                    return
                seen_deferred_low_guard_candidates.add(key)
                deferred_low_guard_candidates.append((
                    access_offset,
                    pointer_offset,
                    imm,
                    rd_symbol,
                    list(constraints),
                    set(related_vars),
                ))

            def try_deferred_low_guard_candidates():
                if not deferred_low_guard_candidates:
                    return None
                guard_limit = STACK_RANGE - LIVEIN_STORE_LOW_GUARD_OFFSET
                deferred_low_guard_candidates.sort(
                    key=lambda item: (abs(item[0] - guard_limit), item[0])
                )
                for (
                    access_offset,
                    pointer_offset,
                    imm,
                    candidate_rd_symbol,
                    constraints,
                    related_vars,
                ) in deferred_low_guard_candidates:
                    if (
                        try_add_constraint_set_fast(
                            constraints,
                            timeout_ms=candidate_timeout_ms,
                        )
                        or try_add_constraint_set_related(
                            constraints,
                            related_vars,
                            timeout_ms=related_candidate_timeout_ms,
                        )
                    ):
                        remember_pointer_base_offset(candidate_rd_symbol, pointer_offset)
                        debug_pointer_choice(
                            "choose_deferred_low_guard",
                            access_offset=access_offset,
                            pointer_offset=pointer_offset,
                            imm=imm,
                        )
                        return access_offset
                    debug_pointer_choice(
                        "reject_deferred_low_guard_solver",
                        access_offset=access_offset,
                        pointer_offset=pointer_offset,
                        imm=imm,
                    )
                return None

            for _, rd_symbol, load_addr_symbol, load_idx in source_load_candidates:
                rd_vars = expr_vars(rd_symbol)
                if not rd_vars or not (addr_vars & rd_vars):
                    continue
                residual = additive_residual_without_term(addr_symbol, rd_symbol)
                if residual is None:
                    residual = claripy.simplify(addr_symbol - rd_symbol)
                affine_residual_value = None
                if expr_vars(residual) & rd_vars:
                    affine = affine_key(addr_symbol)
                    if affine is None or affine[0] != expr_key(rd_symbol):
                        continue
                    affine_residual_value = affine[1]
                residual_value = concrete_expr_value(residual)
                if residual_value is None and affine_residual_value is not None:
                    residual_value = affine_residual_value
                residual_options = []
                if residual_value is not None:
                    residual_options.append((residual_value, [], True))
                else:
                    seen_residual_targets = set()
                    seen_residual_option_keys = set()
                    residual_targets = []
                    residual_affine = affine_base_const(residual)
                    if residual_affine is not None:
                        _, residual_imm = residual_affine
                        residual_targets.append(_signed_u64(residual_imm))
                    for residual_eval in solver_eval_current(
                        residual,
                        n=2 if long_block else 8,
                        timeout_ms=100 if long_block else 5000,
                    ):
                        residual_targets.append(_signed_u64(residual_eval))
                    residual_targets.extend([-4, 0, 4, 8, 16])
                    residual_debug = []
                    for residual_target in residual_targets:
                        target_key = residual_target & ((1 << 64) - 1)
                        if target_key in seen_residual_targets:
                            continue
                        seen_residual_targets.add(target_key)

                        def append_residual_option(residual_constraints, label):
                            option_key = (
                                target_key,
                                tuple(
                                    str(claripy.simplify(constraint))
                                    for constraint in residual_constraints
                                ),
                            )
                            if option_key in seen_residual_option_keys:
                                return False
                            seen_residual_option_keys.add(option_key)
                            residual_options.append((residual_target, residual_constraints, False))
                            if debug_load_slots:
                                residual_debug.append((
                                    _signed_u64(target_key),
                                    label,
                                    len(residual_constraints),
                                ))
                            return True

                        if target_key == 0:
                            for _, zero_constraints, _ in multiplicative_zero_residual_constraint_options(
                                residual,
                                forbidden_vars=rd_vars,
                                direct_pointer_guard=True,
                                timeout_ms=100 if long_block else 1000,
                            ):
                                append_residual_option(
                                    list(zero_constraints),
                                    'mul_zero_option',
                                )
                        residual_constraints = constraints_to_constant(
                            residual,
                            target_key,
                            forbidden_vars=rd_vars,
                        )
                        if residual_constraints is None:
                            direct_constraint = residual == expr_bvv(target_key, residual)
                            direct_sat = constraint_set_selection_satisfiable(
                                [direct_constraint],
                                timeout_ms=100 if long_block else 1000,
                            )
                            if direct_sat is not True:
                                if debug_load_slots:
                                    residual_debug.append((
                                        _signed_u64(target_key),
                                        'reject_direct',
                                        direct_sat,
                                    ))
                                continue
                            residual_constraints = [direct_constraint]
                        elif debug_load_slots:
                            residual_debug.append((
                                _signed_u64(target_key),
                                'constraints',
                                len(residual_constraints),
                            ))
                        append_residual_option(list(residual_constraints), 'constraints')
                if not residual_options:
                    debug_pointer_choice(
                        "no_residual_options",
                        load_idx=load_idx,
                        rd=str(rd_symbol),
                        residual=str(residual),
                        residual_vars=sorted(expr_vars(residual)),
                        residual_debug=residual_debug if 'residual_debug' in locals() else [],
                    )
                    direct_addr = choose_direct_pointer_base_addr(rd_symbol, rd_vars, load_idx)
                    if direct_addr is not None:
                        return direct_addr
                    continue
                residual_option_sat = {}
                residual_vars_for_priority = expr_vars(residual)
                prefer_separated_unscaled_residual = (
                    long_block
                    and width == 8
                    and bool(residual_vars_for_priority)
                    and not (residual_vars_for_priority & rd_vars)
                    and vars_belong_to_single_register(residual_vars_for_priority)
                    and not any(
                        getattr(node, 'op', None) in {
                            '__lshift__',
                            'LShR',
                            'SShR',
                            '__mul__',
                            'Mul',
                            'Concat',
                        }
                        and expr_vars(node)
                        for node in iter_ast_nodes(residual)
                    )
                    and (
                        load_value_has_direct_pointer_use(rd_symbol, load_idx)
                        or load_value_has_direct_store_addr_use(rd_symbol, load_idx)
                    )
                )
                if prefer_separated_unscaled_residual:
                    debug_pointer_choice(
                        "prefer_separated_unscaled_residual",
                        load_idx=load_idx,
                        rd=str(rd_symbol),
                        residual=str(residual),
                    )

                def residual_option_cache_key(option):
                    residual_target, residual_constraints, residual_is_concrete = option
                    return (
                        residual_target & ((1 << 64) - 1),
                        tuple(
                            str(claripy.simplify(constraint))
                            for constraint in residual_constraints
                        ),
                        bool(residual_is_concrete),
                    )

                def residual_constraints_satisfiable(residual_constraints):
                    if not residual_constraints:
                        return True
                    sat = constraint_set_selection_satisfiable(
                        residual_constraints,
                        timeout_ms=100 if long_block else 1000,
                    )
                    if sat is False and long_block:
                        related_sat = constraint_set_related_satisfiable(
                            residual_constraints,
                            expr_vars(residual),
                            timeout_ms=500,
                        )
                        if related_sat is not False:
                            return related_sat
                    return sat

                def residual_option_key(option):
                    residual_target, residual_constraints, residual_is_concrete = option
                    sat = residual_constraints_satisfiable(residual_constraints)
                    residual_option_sat[residual_option_cache_key(option)] = sat
                    signed_target = _signed_u64(residual_target)
                    if prefer_separated_unscaled_residual:
                        if signed_target in {8, 16, 4, 24, 32}:
                            target_rank = 0
                        elif signed_target == 0:
                            target_rank = 1
                        elif signed_target > 0:
                            target_rank = 2
                        else:
                            target_rank = 3
                    else:
                        target_rank = 0 if signed_target == 0 else 1
                    return (
                        0 if sat is True else 1,
                        target_rank,
                        0 if residual_is_concrete else 1,
                        abs(signed_target),
                        len(residual_constraints),
                    )

                residual_options.sort(key=residual_option_key)
                load_addr_key = expr_key(load_addr_symbol)
                load_offset = addr_expr_offsets.get(load_addr_key)
                debug_pointer_choice(
                    "source",
                    load_idx=load_idx,
                    rd=str(rd_symbol),
                    load_offset=load_offset,
                    base_offsets=(
                        current_pointer_base_offsets(rd_symbol)
                        if debug_load_slots
                        else []
                    ),
                    residual_options=[
                        (_signed_u64(value), len(constraints), concrete)
                        for value, constraints, concrete in residual_options
                    ],
                    preferred=preferred,
                    align=align,
                )
                for residual_value, residual_constraints, residual_is_concrete in residual_options:
                    residual_sat = residual_option_sat.get(
                        residual_option_cache_key(
                            (residual_value, residual_constraints, residual_is_concrete)
                        )
                    )
                    if residual_sat is None and residual_constraints:
                        residual_sat = residual_constraints_satisfiable(residual_constraints)
                    if residual_sat is False:
                        debug_pointer_choice(
                            "skip_unsat_residual",
                            load_idx=load_idx,
                            imm=_signed_u64(residual_value),
                            constraints=[
                                str(claripy.simplify(constraint))[:500]
                                for constraint in residual_constraints
                            ] if debug_load_slots else [],
                        )
                        continue
                    imm = _signed_u64(residual_value)
                    pointer_avoid_ranges = (
                        [(load_offset, INIT_ACCESS_SLOT_WIDTH)]
                        if load_offset is not None
                        else None
                    )
                    access_avoid_ranges = list(avoid_ranges)
                    if load_offset is not None and not any(
                        concrete_ranges_overlap(
                            load_offset,
                            INIT_ACCESS_SLOT_WIDTH,
                            used_offset,
                            used_width,
                        )
                        for used_offset, used_width in access_avoid_ranges
                    ):
                        access_avoid_ranges.append((load_offset, INIT_ACCESS_SLOT_WIDTH))
                    base_start = min_pointer_offset_for_vars(
                        rd_vars,
                        load_idx,
                        avoid_ranges=pointer_avoid_ranges,
                    )
                    if imm >= 0:
                        base_start = max(base_start, imm + width)
                    current_base_offsets = current_pointer_base_offsets(rd_symbol)
                    debug_pointer_choice(
                        "residual_plan",
                        load_idx=load_idx,
                        base_start=base_start,
                        imm=imm,
                        current_base_offsets=current_base_offsets,
                        avoid_near=[
                            (used, used_width)
                            for used, used_width in avoid_ranges
                            if current_base_offsets and abs(used - (current_base_offsets[0] - imm)) <= 64
                        ] if debug_load_slots else [],
                    )
                    small_concrete_residual = (
                        long_block
                        and residual_is_concrete
                        and abs(_signed_u64(imm)) <= 64
                    )
                    if load_offset is not None:
                        source_slot = mem_slot_symbols.get(load_offset)
                        source_value = None if source_slot is None else source_slot.get('chosen_value')
                        source_pointer_offset = None if source_value is None else stack_offset_for_value(source_value)
                        if source_pointer_offset is not None:
                            access_offset = source_pointer_offset - imm
                            constraints = list(residual_constraints) + [
                                (init_sp - rd_symbol) == source_pointer_offset,
                                addr_expr == access_offset,
                            ]
                            if (
                                access_offset > 0
                                and access_offset <= STACK_RANGE
                                and (not align or access_offset % align == 0)
                                and not pointer_table_access_should_avoid_low_guard(access_offset)
                                and source_pointer_offset >= base_start
                                and pointer_offset_keeps_derived_accesses_available(
                                    rd_symbol,
                                    rd_vars,
                                    source_pointer_offset,
                                    access_avoid_ranges,
                                    constraints,
                                    producer_load_addr_symbol=load_addr_symbol,
                                    producer_idx=load_idx,
                                )
                                and not any(
                                    concrete_ranges_overlap(access_offset, width, used, used_width)
                                    for used, used_width in access_avoid_ranges
                                )
                            ):
                                if try_add_constraint_set_fast(constraints, timeout_ms=candidate_timeout_ms):
                                    remember_pointer_base_offset(rd_symbol, source_pointer_offset)
                                    debug_pointer_choice(
                                        "choose_source_value",
                                        access_offset=access_offset,
                                        pointer_offset=source_pointer_offset,
                                        imm=imm,
                                    )
                                    return access_offset
                    if long_block and residual_constraints:
                        starts = []
                        # Long pointer-chasing blocks often already have low offsets
                        # ruled out by earlier no-overlap/range constraints.  Try
                        # stable high stack slots before spending the small long-block
                        # solver budget on low offsets.
                        starts.extend([0xc00 - imm, 0x800 - imm, 0x400 - imm])
                        starts.extend(
                            pointer_offset - imm
                            for pointer_offset in current_base_offsets
                        )
                        if preferred is not None:
                            starts.append(preferred)
                    else:
                        starts = []
                        if small_concrete_residual:
                            starts.append(base_start - imm)
                            if preferred is not None:
                                starts.append(preferred)
                            starts.extend(
                                pointer_offset - imm
                                for pointer_offset in current_base_offsets
                            )
                            starts.extend([0x400 - imm, 0x800 - imm, 0xc00 - imm])
                        else:
                            starts.extend(
                                pointer_offset - imm
                                for pointer_offset in current_base_offsets
                            )
                            if long_block:
                                starts.extend([0xc00 - imm, 0x800 - imm, 0x400 - imm])
                            if preferred is not None:
                                starts.append(preferred)
                    low = _align_up(1, align) if align else 1
                    starts.append(low)
                    if not small_concrete_residual:
                        starts.append(base_start - imm)
                    starts.extend(used + max(width, used_width) for used, used_width in access_avoid_ranges)
                    seen_offsets = set()
                    step = align if align else 1
                    attempts = 0
                    attempts_per_start = (
                        4
                        if long_block and residual_constraints
                        else (4 if long_block else 16)
                    )
                    max_attempts = 24 if long_block else attempts_per_start

                    def overlap_is_scalar_zero_alias(access_offset, overlap_ranges):
                        try:
                            current_is_scalar_zero = bool(current_scalar_zero_load)
                        except NameError:
                            current_is_scalar_zero = False
                        try:
                            current_is_mutated_additive_offset = bool(current_mutated_additive_offset_scalar)
                        except NameError:
                            current_is_mutated_additive_offset = False
                        if current_is_mutated_additive_offset:
                            return False
                        if not current_is_scalar_zero and width >= 8:
                            return False
                        for used, used_width in overlap_ranges:
                            if used != access_offset or used_width != width:
                                return False
                            used_word_offset = ((used + 7) // 8) * 8
                            used_slot = mem_slot_symbols.get(used_word_offset)
                            if used_slot is None:
                                continue
                            if (
                                used_slot.get('pointer_like')
                                or used_slot.get('must_be_pointer')
                                or used_slot.get('sp_affine')
                            ):
                                return False
                            if not current_is_scalar_zero and used_slot.get('scalar_zero') is False and width >= 8:
                                return False
                        return True

                    def overlap_is_forced_same_pointer_load(
                        access_offset,
                        overlap_ranges,
                        candidate_constraints,
                    ):
                        try:
                            current_is_pointer_like = bool(current_pointer_like_load)
                        except NameError:
                            current_is_pointer_like = False
                        if not current_is_pointer_like or width != 8:
                            return False

                        def forced_same_address_with_constraints(other_addr_symbol):
                            if same_address(addr_symbol, other_addr_symbol, allow_solver=False):
                                return True
                            if not exprs_may_be_related(addr_symbol, other_addr_symbol):
                                return False
                            test_solver = candidate_solver.branch()
                            test_solver.timeout = max(related_candidate_timeout_ms, 1000)
                            try:
                                for constraint in candidate_constraints:
                                    test_solver.add(constraint)
                                test_solver.add(addr_symbol != other_addr_symbol)
                                return not test_solver.satisfiable()
                            except Exception:
                                return False

                        def store_may_clobber_alias(prior_idx):
                            for _, store_addr_symbol, store_idx, _store_width, _ in store_accesses:
                                if store_idx <= prior_idx or store_idx >= inst_idx:
                                    continue
                                if not exprs_may_be_related(addr_symbol, store_addr_symbol):
                                    continue
                                test_solver = candidate_solver.branch()
                                test_solver.timeout = max(related_candidate_timeout_ms, 1000)
                                try:
                                    for constraint in candidate_constraints:
                                        test_solver.add(constraint)
                                    test_solver.add(addr_symbol == store_addr_symbol)
                                    if test_solver.satisfiable():
                                        return True
                                except Exception:
                                    return True
                            return False

                        for used, used_width in overlap_ranges:
                            if used != access_offset or used_width != width:
                                return False
                            word_offset = ((used + 7) // 8) * 8
                            if word_offset != used:
                                return False
                            used_slot = mem_slot_symbols.get(word_offset)
                            if used_slot is not None and used_slot.get('scalar_zero'):
                                return False
                            matched_alias = False
                            for known_addr, known_idx in mem_offset_addr_entries.get(word_offset, []):
                                if known_idx >= inst_idx:
                                    continue
                                if not forced_same_address_with_constraints(known_addr):
                                    continue
                                if store_may_clobber_alias(known_idx):
                                    continue
                                matched_alias = True
                                break
                            if not matched_alias:
                                return False
                        return add_existing_slot_value_constraints(
                            access_offset,
                            candidate_constraints,
                        )

                    def add_existing_slot_value_constraints(
                        access_offset,
                        candidate_constraints,
                    ):
                        if current_load_value_expr is None or width != 8 or access_offset % 8:
                            return False
                        word_offset = ((access_offset + 7) // 8) * 8
                        used_slot = mem_slot_symbols.get(word_offset)
                        if used_slot is None:
                            return True
                        prior_value_exprs = []
                        if 'direct_value_expr' in used_slot:
                            prior_value_exprs.append(used_slot['direct_value_expr'])
                        prior_value_exprs.extend(used_slot.get('value_exprs', []))
                        existing_constraint_keys = {
                            str(claripy.simplify(constraint))
                            for constraint in candidate_constraints
                        }
                        for prior_value_expr in prior_value_exprs:
                            equality_constraint = current_load_value_expr == prior_value_expr
                            equality_key = str(claripy.simplify(equality_constraint))
                            if equality_key in existing_constraint_keys:
                                continue
                            existing_constraint_keys.add(equality_key)
                            candidate_constraints.append(equality_constraint)
                        for range_constraint in load_value_derived_access_range_constraints(
                            current_load_value_expr,
                            current_load_idx,
                            avoid_existing_load_slots=True,
                            candidate_constraints=candidate_constraints,
                        ):
                            range_key = str(claripy.simplify(range_constraint))
                            if range_key in existing_constraint_keys:
                                continue
                            existing_constraint_keys.add(range_key)
                            candidate_constraints.append(range_constraint)
                        return True

                    def overlap_is_existing_pointer_slot_alias(
                        access_offset,
                        overlap_ranges,
                        candidate_constraints=None,
                        record=True,
                    ):
                        if candidate_constraints is None:
                            return False
                        if not overlap_is_forced_same_pointer_load(
                            access_offset,
                            overlap_ranges,
                            candidate_constraints,
                        ):
                            return False
                        if record:
                            allowed_pointer_slot_alias_offsets.add(access_offset)
                        return True

                    for start in starts:
                        start = max(start, low)
                        if align:
                            start = _align_up(start, align)
                        start_attempts = 0
                        for access_offset in range(start, min(STACK_RANGE, start + 256) + 1, step):
                            if attempts >= max_attempts:
                                deferred_choice = try_deferred_low_guard_candidates()
                                if deferred_choice is not None:
                                    return deferred_choice
                                return None
                            if start_attempts >= attempts_per_start:
                                break
                            if access_offset in seen_offsets:
                                continue
                            seen_offsets.add(access_offset)
                            if access_offset <= 0 or access_offset > STACK_RANGE:
                                continue
                            if align and access_offset % align != 0:
                                continue
                            defer_for_low_guard = pointer_table_access_should_avoid_low_guard(access_offset)
                            if defer_for_low_guard:
                                debug_pointer_choice(
                                    "defer_low_guard_pointer_table",
                                    access_offset=access_offset,
                                    guard=LIVEIN_STORE_LOW_GUARD_OFFSET,
                                )
                            pointer_offset = access_offset + imm
                            if pointer_offset <= 0 or pointer_offset > STACK_RANGE:
                                continue
                            constraints = list(residual_constraints) + [
                                (init_sp - rd_symbol) == pointer_offset,
                                addr_expr == access_offset,
                            ]
                            overlap_ranges = [
                                (used, used_width)
                                for used, used_width in access_avoid_ranges
                                if concrete_ranges_overlap(access_offset, width, used, used_width)
                            ]
                            if pointer_offset < base_start:
                                below_base_start_alias = (
                                    bool(overlap_ranges)
                                    and overlap_is_existing_pointer_slot_alias(
                                        access_offset,
                                        overlap_ranges,
                                        record=False,
                                    )
                                )
                                if below_base_start_alias:
                                    debug_pointer_choice(
                                        "allow_below_base_start_pointer_slot_alias",
                                        access_offset=access_offset,
                                        pointer_offset=pointer_offset,
                                        base_start=base_start,
                                        imm=imm,
                                        overlaps=overlap_ranges,
                                    )
                                else:
                                    if debug_load_slots and pointer_offset in current_base_offsets:
                                        debug_pointer_choice(
                                            "reject_base_start",
                                            access_offset=access_offset,
                                            pointer_offset=pointer_offset,
                                            base_start=base_start,
                                            imm=imm,
                                    )
                                    continue
                            if pointer_offset >= base_start:
                                pass
                            elif debug_load_slots:
                                debug_pointer_choice(
                                    "try_below_base_start_pointer_slot_alias",
                                    access_offset=access_offset,
                                    pointer_offset=pointer_offset,
                                    base_start=base_start,
                                    imm=imm,
                                )
                            attempts += 1
                            start_attempts += 1
                            if not pointer_offset_keeps_derived_accesses_available(
                                rd_symbol,
                                rd_vars,
                                pointer_offset,
                                access_avoid_ranges,
                                constraints,
                                producer_load_addr_symbol=load_addr_symbol,
                                producer_idx=load_idx,
                            ):
                                if debug_load_slots and pointer_offset < base_start:
                                    debug_pointer_choice(
                                        "reject_below_base_start_derived",
                                        access_offset=access_offset,
                                        pointer_offset=pointer_offset,
                                        base_start=base_start,
                                        imm=imm,
                                )
                                continue
                            if overlap_ranges:
                                if overlap_is_scalar_zero_alias(access_offset, overlap_ranges):
                                    debug_pointer_choice(
                                        "allow_scalar_zero_alias",
                                        access_offset=access_offset,
                                        overlaps=overlap_ranges,
                                    )
                                elif overlap_is_existing_pointer_slot_alias(
                                    access_offset,
                                    overlap_ranges,
                                    candidate_constraints=constraints,
                                ):
                                    debug_pointer_choice(
                                        "allow_existing_pointer_slot_alias",
                                        access_offset=access_offset,
                                        pointer_offset=pointer_offset,
                                        imm=imm,
                                        overlaps=overlap_ranges,
                                    )
                                else:
                                    if overlap_is_forced_same_pointer_load(
                                        access_offset,
                                        overlap_ranges,
                                        constraints,
                                    ):
                                        debug_pointer_choice(
                                            "allow_forced_same_pointer_alias",
                                            access_offset=access_offset,
                                            pointer_offset=pointer_offset,
                                            imm=imm,
                                            overlaps=overlap_ranges,
                                        )
                                    else:
                                        if debug_load_slots and (access_offset + imm) in current_base_offsets:
                                            debug_pointer_choice(
                                                "reject_avoid_overlap",
                                                access_offset=access_offset,
                                                pointer_offset=access_offset + imm,
                                                imm=imm,
                                                overlaps=overlap_ranges,
                                            )
                                        continue
                            if defer_for_low_guard:
                                defer_low_guard_candidate(
                                    access_offset,
                                    pointer_offset,
                                    imm,
                                    rd_symbol,
                                    constraints,
                                    expr_vars(addr_expr) | rd_vars,
                                )
                                continue
                            if preferred is not None and access_offset == preferred:
                                if try_add_constraint_set_fast(constraints, timeout_ms=candidate_timeout_ms):
                                    remember_pointer_base_offset(rd_symbol, pointer_offset)
                                    return access_offset
                            if not (
                                try_add_constraint_set_fast(
                                    constraints,
                                    timeout_ms=candidate_timeout_ms,
                                )
                                or try_add_constraint_set_related(
                                    constraints,
                                    expr_vars(addr_expr) | rd_vars,
                                    timeout_ms=related_candidate_timeout_ms,
                                )
                            ):
                                if (
                                    long_block
                                    and residual_constraints
                                    and len(constraints) <= 4
                                    and pointer_offset >= 0x400
                                    and all(ast_node_count(constraint) <= 96 for constraint in constraints)
                                ):
                                    related_sat = constraint_set_related_satisfiable(
                                        constraints,
                                        expr_vars(addr_expr) | rd_vars | expr_vars(residual),
                                        timeout_ms=related_candidate_timeout_ms,
                                    )
                                    if related_sat is not False:
                                        for constraint in constraints:
                                            candidate_solver.add(constraint)
                                            added_constraint_cache.add(str(claripy.simplify(constraint)))
                                            debug_constraint_add("pointer_load_addr_high_assumed", constraint)
                                        remember_pointer_base_offset(rd_symbol, pointer_offset)
                                        debug_pointer_choice(
                                            "choose_high_assumed",
                                            access_offset=access_offset,
                                            pointer_offset=pointer_offset,
                                            imm=imm,
                                            residual_constraints=len(residual_constraints),
                                            related_sat=related_sat,
                                        )
                                        return access_offset
                                if (
                                    long_block
                                    and residual_constraints
                                    and len(residual_constraints) > 1
                                    and _signed_u64(residual_value) == 0
                                ):
                                    related_sat = constraint_set_related_satisfiable(
                                        constraints,
                                        expr_vars(addr_expr) | rd_vars | expr_vars(residual),
                                        timeout_ms=max(related_candidate_timeout_ms, 1000),
                                    )
                                    if related_sat is True:
                                        for constraint in constraints:
                                            candidate_solver.add(constraint)
                                            added_constraint_cache.add(str(claripy.simplify(constraint)))
                                            debug_constraint_add("pointer_load_addr_assumed", constraint)
                                        remember_pointer_base_offset(rd_symbol, pointer_offset)
                                        debug_pointer_choice(
                                            "choose_related_assumed",
                                            access_offset=access_offset,
                                            pointer_offset=pointer_offset,
                                            imm=imm,
                                            residual_constraints=len(residual_constraints),
                                        )
                                        return access_offset
                                debug_fields = {
                                    'access_offset': access_offset,
                                    'pointer_offset': pointer_offset,
                                    'imm': imm,
                                }
                                if debug_load_slots:
                                    related_debug_vars = expr_vars(addr_expr) | rd_vars | expr_vars(residual)
                                    residual_debug_vars = expr_vars(residual)
                                    debug_fields.update({
                                        'residual_sat': debug_pointer_sat(residual_constraints),
                                        'base_sat': debug_pointer_sat([(init_sp - rd_symbol) == pointer_offset]),
                                        'addr_sat': debug_pointer_sat([addr_expr == access_offset]),
                                        'residual_base_sat': debug_pointer_sat(
                                            list(residual_constraints)
                                            + [(init_sp - rd_symbol) == pointer_offset]
                                        ),
                                        'constraints': [
                                            str(claripy.simplify(constraint))
                                            for constraint in constraints[:4]
                                        ],
                                        'existing_related': [
                                            str(claripy.simplify(constraint))[:500]
                                            for constraint in candidate_solver.constraints
                                            if getattr(constraint, 'variables', set()) & related_debug_vars
                                        ][:12],
                                        'existing_residual_related': [
                                            str(claripy.simplify(constraint))[:500]
                                            for constraint in candidate_solver.constraints
                                            if getattr(constraint, 'variables', set()) & residual_debug_vars
                                        ][:24],
                                        'existing_base_related': [
                                            str(claripy.simplify(constraint))[:500]
                                            for constraint in candidate_solver.constraints
                                            if getattr(constraint, 'variables', set()) & rd_vars
                                        ][:24],
                                    })
                                debug_pointer_choice(
                                    "reject_solver",
                                    **debug_fields,
                                )
                                continue
                            remember_pointer_base_offset(rd_symbol, pointer_offset)
                            debug_pointer_choice(
                                "choose",
                                access_offset=access_offset,
                                pointer_offset=pointer_offset,
                                imm=imm,
                            )
                            return access_offset
            return try_deferred_low_guard_candidates()

        def choose_carrier_residual_stack_offset(addr_symbol, addr_expr, preferred, align, avoid_ranges, width, allow_overlap=False):
            if preferred is None:
                return None
            debug_load_slots = os.environ.get("RVMCA_DEBUG_LOAD_SLOTS") == "1"
            long_block = len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
            carrier_solver_timeout_ms = 100 if long_block else 5000
            carrier_related_timeout_ms = 500 if long_block else 5000
            carrier_attempt_limit = 32 if long_block else None
            carrier_attempts = 0
            addr_vars = expr_vars(addr_symbol)
            small_residual_targets = [0, 1, 2, 4, 8, 16]
            access_offset_candidates = [preferred]
            if long_block:
                access_offset_candidates.extend([0xc00, 0x800, 0x400, 0x200])
                next_start = preferred + (align if align else 1)
                for _ in range(4):
                    next_offset = next_free_stack_offset(
                        avoid_ranges,
                        align=align if align else 1,
                        width=width,
                        start=next_start,
                    )
                    if next_offset is None:
                        break
                    access_offset_candidates.append(next_offset)
                    next_start = next_offset + (align if align else 1)
            deduped_access_offsets = []
            seen_access_offsets = set()
            for candidate_offset in access_offset_candidates:
                if candidate_offset in seen_access_offsets:
                    continue
                seen_access_offsets.add(candidate_offset)
                deduped_access_offsets.append(candidate_offset)
            carrier_symbols = [(symbol, True) for symbol in reg_to_symbol.values()]
            carrier_symbols.extend(
                (rd_symbol, False)
                for load_inst, rd_symbol, _, _ in load_accesses
                if load_inst.width == 8
            )
            residual_scalar_reg_symbol_keys = {
                expr_key(reg_to_symbol[reg])
                for reg in residual_scalar_regs
                if reg in reg_to_symbol
            }
            residual_scalar_reg_vars = set()
            for reg in residual_scalar_regs:
                reg_symbol = reg_to_symbol.get(reg)
                if reg_symbol is not None:
                    residual_scalar_reg_vars.update(expr_vars(reg_symbol))
            seen_carriers = set()
            for symbol, allow_direct_add in carrier_symbols:
                carrier_key = expr_key(symbol)
                if carrier_key in seen_carriers:
                    continue
                seen_carriers.add(carrier_key)
                if allow_direct_add and carrier_key in residual_scalar_reg_symbol_keys:
                    if debug_load_slots:
                        DEBUG(f"carrier_residual_skip_scalar_reg {({
                            'addr': str(addr_symbol),
                            'carrier': str(symbol),
                        })}")
                    continue
                symbol_vars = expr_vars(symbol)
                if not symbol_vars or not (addr_vars & symbol_vars):
                    continue
                residual = claripy.simplify(addr_symbol - symbol)
                if expr_vars(residual) & symbol_vars:
                    if debug_load_slots:
                        DEBUG(f"carrier_residual_skip_self {({
                            'addr': str(addr_symbol),
                            'carrier': str(symbol),
                            'residual': str(residual),
                        })}")
                    continue
                carrier_from_load = any(
                    load_inst.width == 8
                    and expr_key(rd_symbol) == carrier_key
                    for load_inst, rd_symbol, _, _ in load_accesses
                )
                carrier_symbolic_read = any(
                    str(var).startswith('symbolic_read_')
                    for var in symbol_vars
                )
                carrier_min_base_offset = 1
                if (
                    carrier_from_load
                    or not allow_direct_add
                    or carrier_symbolic_read
                    or symbol_vars & (
                        set(pointer_loaded_addr_vars)
                        | set(address_loaded_addr_vars)
                        | set(undef_base_vars)
                    )
                ):
                    carrier_min_base_offset = max(INIT_PTR_MIN_OFFSET, width)

                def remember_carrier_base_offset(base_offset):
                    if carrier_min_base_offset <= 1:
                        return
                    if base_offset <= 0 or base_offset > STACK_RANGE:
                        return
                    affine_base_offset_choices[carrier_key] = base_offset
                    remember_equiv_base_offset(symbol, base_offset)

                residual_targets = []
                residual_value = concrete_expr_value(residual)
                if residual_value is not None:
                    residual_targets.append(_signed_u64(residual_value))
                residual_affine = affine_base_const(residual)
                if residual_affine is not None:
                    _, residual_imm = residual_affine
                    residual_targets.append(_signed_u64(residual_imm))
                residual_targets.extend(small_residual_targets)
                seen_targets = set()
                for residual_target in residual_targets:
                    if residual_target in seen_targets:
                        continue
                    seen_targets.add(residual_target)
                    residual_constraints = constraints_to_constant(
                        residual,
                        residual_target & ((1 << 64) - 1),
                        forbidden_vars=symbol_vars,
                    )
                    if residual_constraints is None and (residual_target & ((1 << 64) - 1)) == 0:
                        residual_constraints = multiplicative_zero_residual_constraints(
                            residual,
                            forbidden_vars=symbol_vars,
                            direct_pointer_guard=True,
                            timeout_ms=100 if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD else 1000,
                        )
                    if residual_constraints is None:
                        residual_constraints = [residual == expr_bvv(residual_target, residual)]
                    for access_offset in deduped_access_offsets:
                        if access_offset <= 0 or access_offset > STACK_RANGE:
                            continue
                        if align and access_offset % align != 0:
                            continue
                        if (
                            not allow_overlap
                            and any(concrete_ranges_overlap(access_offset, width, used, used_width) for used, used_width in avoid_ranges)
                        ):
                            if debug_load_slots:
                                DEBUG(f"carrier_residual_reject_overlap {({
                                    'addr': str(addr_symbol),
                                    'carrier': str(symbol),
                                    'access_offset': access_offset,
                                    'target': _signed_u64(residual_target),
                                })}")
                            continue
                        base_offset = access_offset + residual_target
                        if (
                            base_offset < carrier_min_base_offset
                            or base_offset <= 0
                            or base_offset > STACK_RANGE
                        ):
                            if debug_load_slots and base_offset < carrier_min_base_offset:
                                DEBUG(f"carrier_residual_reject_base_min {({
                                    'addr': str(addr_symbol),
                                    'carrier': str(symbol),
                                    'access_offset': access_offset,
                                    'base_offset': base_offset,
                                    'min_base_offset': carrier_min_base_offset,
                                    'carrier_from_load': carrier_from_load,
                                    'carrier_symbolic_read': carrier_symbolic_read,
                                    'target': _signed_u64(residual_target),
                                })}")
                            continue
                        constraints = list(residual_constraints) + [
                            (init_sp - symbol) == base_offset,
                            addr_expr == access_offset,
                        ]
                        if carrier_attempt_limit is not None:
                            if carrier_attempts >= carrier_attempt_limit:
                                return None
                            carrier_attempts += 1
                        if (
                            try_add_constraint_set_fast(constraints, timeout_ms=carrier_solver_timeout_ms)
                            or try_add_constraint_set_related(
                                constraints,
                                expr_vars(addr_expr) | symbol_vars,
                                timeout_ms=carrier_related_timeout_ms,
                            )
                        ):
                            remember_carrier_base_offset(base_offset)
                            if debug_load_slots:
                                DEBUG(f"carrier_residual_choose {({
                                    'addr': str(addr_symbol),
                                    'carrier': str(symbol),
                                    'access_offset': access_offset,
                                    'base_offset': base_offset,
                                    'target': _signed_u64(residual_target),
                                    'constraints': [
                                        str(claripy.simplify(constraint))[:500]
                                        for constraint in constraints[:4]
                                    ],
                                })}")
                            return access_offset
                        if long_block:
                            touches_residual_scalar = any(
                                getattr(constraint, 'variables', set()) & residual_scalar_reg_vars
                                for constraint in constraints
                            )
                            carrier_sat = constraint_set_related_satisfiable(
                                constraints,
                                expr_vars(addr_expr) | symbol_vars | expr_vars(residual),
                                timeout_ms=carrier_related_timeout_ms,
                            )
                            if carrier_sat is not False and not touches_residual_scalar:
                                for constraint in constraints:
                                    candidate_solver.add(constraint)
                                    added_constraint_cache.add(str(claripy.simplify(constraint)))
                                    debug_constraint_add("carrier_residual_assumed", constraint)
                                remember_carrier_base_offset(base_offset)
                                if debug_load_slots:
                                    DEBUG(f"carrier_residual_choose_assumed {({
                                        'addr': str(addr_symbol),
                                        'carrier': str(symbol),
                                        'access_offset': access_offset,
                                        'base_offset': base_offset,
                                        'target': _signed_u64(residual_target),
                                        'sat': carrier_sat,
                                    })}")
                                return access_offset
                            if debug_load_slots and carrier_sat is not False and touches_residual_scalar:
                                DEBUG(f"carrier_residual_skip_assumed_scalar {({
                                    'addr': str(addr_symbol),
                                    'carrier': str(symbol),
                                    'access_offset': access_offset,
                                    'base_offset': base_offset,
                                    'target': _signed_u64(residual_target),
                                    'sat': carrier_sat,
                                })}")
                        if debug_load_slots:
                            DEBUG(f"carrier_residual_reject_solver {({
                                'addr': str(addr_symbol),
                                'carrier': str(symbol),
                                'access_offset': access_offset,
                                'base_offset': base_offset,
                                'target': _signed_u64(residual_target),
                                'constraint_count': len(constraints),
                                'constraints': [
                                    str(claripy.simplify(constraint))[:500]
                                    for constraint in constraints[:5]
                                ],
                            })}")

            if preferred <= 0 or preferred > STACK_RANGE:
                return None
            if align and preferred % align != 0:
                return None
            if (
                not allow_overlap
                and any(concrete_ranges_overlap(preferred, width, used, used_width) for used, used_width in avoid_ranges)
            ):
                return None

            for mul_node in iter_ast_nodes(addr_symbol):
                if getattr(mul_node, 'op', None) not in {'__mul__', 'Mul'}:
                    continue
                mul_vars = expr_vars(mul_node)
                if not mul_vars:
                    continue
                residual = sub_same_width(addr_symbol, mul_node)
                if residual is None:
                    continue
                if expr_vars(residual) & mul_vars:
                    continue
                residual_value = concrete_expr_value(residual)
                if residual_value is None:
                    continue
                target_product = (concrete_stack_addr(preferred) - residual_value) & ((1 << 64) - 1)
                mul_args = [
                    arg for arg in getattr(mul_node, 'args', ())
                    if hasattr(arg, 'op')
                ]
                carrier_args = [
                    arg for arg in mul_args
                    if expr_vars(arg)
                ]
                carrier_args.sort(
                    key=lambda arg: (
                        0 if expr_vars(arg) & set().union(*(expr_vars(symbol) for symbol in reg_to_symbol.values())) else 1,
                        ast_node_count(arg),
                    )
                )
                for carrier_arg in carrier_args:
                    carrier_vars = expr_vars(carrier_arg)
                    constraints = [
                        carrier_arg == expr_bvv(target_product, carrier_arg),
                        addr_expr == preferred,
                    ]
                    valid = True
                    for other_arg in mul_args:
                        if other_arg is carrier_arg:
                            continue
                        if not expr_vars(other_arg):
                            other_value = concrete_expr_value(other_arg)
                            if other_value is None or other_value != 1:
                                valid = False
                                break
                            continue
                        other_constraints = constraints_to_constant(
                            other_arg,
                            1,
                            forbidden_vars=carrier_vars,
                        )
                        if other_constraints is None:
                            valid = False
                            break
                        constraints.extend(other_constraints)
                    if not valid:
                        continue
                    if (
                        try_add_constraint_set_fast(constraints, timeout_ms=5000)
                        or try_add_constraint_set_related(
                            constraints,
                            mul_vars,
                            timeout_ms=5000,
                        )
                    ):
                        return preferred
            return None

        def reserve_constant_access_ranges_for_materialized_base(symbol, base_offset):
            symbol_vars = expr_vars(symbol)
            if not symbol_vars:
                return
            for _, addr_symbol, _, access_width in mem_accesses:
                if not (expr_vars(addr_symbol) & symbol_vars):
                    continue
                residual = claripy.simplify(addr_symbol - symbol)
                if expr_vars(residual) & symbol_vars:
                    continue
                residual_value = concrete_expr_value(residual)
                if residual_value is None:
                    continue
                imm = _signed_u64(residual_value)
                access_offset = base_offset - imm
                if access_offset <= 0 or access_offset > STACK_RANGE:
                    continue
                if access_width > 1 and access_offset % access_width:
                    continue
                if not any(
                    used_offset == access_offset
                    and same_address(addr_symbol, used_addr_symbol, allow_solver=False)
                    for used_offset, _, used_addr_symbol in reserved_base_access_ranges
                ):
                    reserved_base_access_ranges.append((access_offset, access_width, addr_symbol))
                if not any(
                    concrete_ranges_overlap(access_offset, init_slot_width(access_width), used_offset, used_width)
                    for used_offset, used_width in used_stack_offsets
                ):
                    used_stack_offsets.append((access_offset, init_slot_width(access_width)))

        reserved_base_access_ranges = []
        used_stack_offsets = []
        scalar_offset = 0
        sp_affine_mem_offsets = {}

        debug_unsat_stages = os.environ.get("RVMCA_DEBUG_UNSAT") == "1"
        def debug_check_stage(stage):
            if not debug_unsat_stages:
                return
            result = None
            try:
                check_solver = candidate_solver.branch()
                check_solver.timeout = local_solver_timeout_ms
                result = check_solver.satisfiable()
            except Exception as exc:
                result = f"error:{type(exc).__name__}"
            DEBUG(f"debug_unsat_stage {stage}: {result}")

        early_reg_defined_before_access_cache = {}

        def reg_defined_before_access(reg, access_idx):
            key = (reg, access_idx)
            if key not in early_reg_defined_before_access_cache:
                early_reg_defined_before_access_cache[key] = any(
                    getattr(prev_inst, 'get_def', lambda: None)() == reg
                    for prev_inst in prog2se.insts[:access_idx]
                )
            return early_reg_defined_before_access_cache[key]

        def load_value_is_additive_offset_to_live_base(value_expr, producer_idx):
            value_vars = expr_vars(value_expr)
            if not value_vars:
                return False
            debug_additive_offset = os.environ.get("RVMCA_DEBUG_LOAD_SLOTS") == "1"

            def reject_additive_offset(reason, **fields):
                if debug_additive_offset:
                    fields.setdefault('idx', producer_idx)
                    fields.setdefault('value', str(value_expr))
                    DEBUG(f"additive_offset_live_base_reject {reason} {fields}")
                return False

            if (
                (producer_idx, stable_expr_key(value_expr)) in pointer_source_value_keys
                and (producer_idx, stable_expr_key(value_expr)) not in scalar_load_hint_keys
            ):
                return reject_additive_offset("pointer_source_value")

            value_feeds_pointer_chase = False
            for later_inst, later_rd_symbol, later_addr_symbol, later_idx in load_accesses:
                if later_idx <= producer_idx or later_inst.width != 8:
                    continue
                if not (expr_vars(later_addr_symbol) & value_vars):
                    continue
                later_rd_vars = expr_vars(later_rd_symbol)
                if not later_rd_vars:
                    continue
                if any(
                    access_idx > later_idx and (expr_vars(addr_symbol) & later_rd_vars)
                    for _, addr_symbol, access_idx, _ in mem_accesses
                ):
                    value_feeds_pointer_chase = True
                    break
            if value_feeds_pointer_chase:
                return reject_additive_offset(
                    "pointer_chase_source",
                )
            producer_addr_pointer_derived = False
            for load_inst, rd_symbol, load_addr_symbol, load_idx in load_accesses:
                if load_idx != producer_idx:
                    continue
                if expr_key(rd_symbol) != expr_key(value_expr):
                    continue
                producer_addr_pointer_derived = bool(
                    expr_vars(load_addr_symbol)
                    & (pointer_loaded_addr_vars | address_loaded_addr_vars)
                )
                break
            if (
                producer_addr_pointer_derived
                and (
                    load_value_has_direct_pointer_use(value_expr, producer_idx)
                    or load_value_has_direct_store_addr_use(value_expr, producer_idx)
                )
            ):
                return reject_additive_offset(
                    "direct_pointer_or_store_addr_use",
                )

            def additive_terms(expr, sign=1, depth=0):
                expr = claripy.simplify(expr)
                if depth > 12:
                    return [(sign, expr)]
                op = getattr(expr, 'op', '')
                args = [arg for arg in getattr(expr, 'args', ()) if hasattr(arg, 'op')]
                if op in {'__add__', 'Add'}:
                    terms = []
                    for arg in args:
                        terms.extend(additive_terms(arg, sign, depth + 1))
                    return terms
                if op in {'__sub__', 'Sub'} and args:
                    terms = additive_terms(args[0], sign, depth + 1)
                    for arg in args[1:]:
                        terms.extend(additive_terms(arg, -sign, depth + 1))
                    return terms
                if op in {'SignExt', 'ZeroExt'} and args:
                    inner_terms = additive_terms(args[-1], sign, depth + 1)
                    if len(inner_terms) == 1 and inner_terms[0][1] is args[-1]:
                        return [(sign, expr)]
                    return inner_terms
                return [(sign, expr)]

            def residual_without_value_terms(addr_symbol):
                terms = additive_terms(addr_symbol)
                residual_terms = []
                saw_value_term = False
                for sign, term in terms:
                    term_vars = expr_vars(term)
                    if term_vars & value_vars:
                        if sign < 0:
                            return None
                        saw_value_term = True
                        continue
                    residual_terms.append((sign, term))
                if not saw_value_term:
                    return None
                width = addr_symbol.size()
                residual = claripy.BVV(0, width)
                for sign, term in residual_terms:
                    if term.size() != width:
                        return None
                    residual = residual + term if sign > 0 else residual - term
                return claripy.simplify(residual)

            def residual_is_simple_additive(expr, depth=0):
                expr = claripy.simplify(expr)
                if depth > 8:
                    return False
                if not expr_vars(expr):
                    return True
                op = getattr(expr, 'op', '')
                args = [arg for arg in getattr(expr, 'args', ()) if hasattr(arg, 'op')]
                if op == 'BVS':
                    return True
                if op in {'__add__', 'Add', '__sub__', 'Sub'}:
                    return all(residual_is_simple_additive(arg, depth + 1) for arg in args)
                if op in {'SignExt', 'ZeroExt'} and args:
                    return residual_is_simple_additive(args[-1], depth + 1)
                return False

            def residual_has_live_base_candidate(residual_vars, access_idx):
                for reg, reg_symbol in reg_to_symbol.items():
                    reg_vars = expr_vars(reg_symbol)
                    if not reg_vars or not (reg_vars & residual_vars):
                        continue
                    if reg_defined_before_access(reg, access_idx):
                        continue
                    return True
                return False

            saw_address_use = False
            saw_live_base = False
            for _, addr_symbol, access_idx, _ in mem_accesses:
                if access_idx <= producer_idx:
                    continue
                addr_vars = expr_vars(addr_symbol)
                if not (addr_vars & value_vars):
                    continue
                saw_address_use = True
                residual = residual_without_value_terms(addr_symbol)
                if residual is None:
                    residual = sub_same_width(addr_symbol, value_expr)
                if residual is None:
                    residual = claripy.simplify(addr_symbol - value_expr)
                residual_vars = expr_vars(residual)
                if residual_vars & value_vars:
                    return reject_additive_offset(
                        "residual_keeps_value",
                        access_idx=access_idx,
                        addr=str(addr_symbol),
                        residual=str(residual),
                    )
                if not residual_vars:
                    return reject_additive_offset(
                        "residual_concrete",
                        access_idx=access_idx,
                        addr=str(addr_symbol),
                        residual=str(residual),
                    )
                if not residual_is_simple_additive(residual):
                    return reject_additive_offset(
                        "residual_not_simple",
                        access_idx=access_idx,
                        addr=str(addr_symbol),
                        residual=str(residual),
                    )
                if not residual_has_live_base_candidate(residual_vars, access_idx):
                    return reject_additive_offset(
                        "no_live_base",
                        access_idx=access_idx,
                        addr=str(addr_symbol),
                        residual=str(residual),
                        residual_vars=sorted(residual_vars),
                    )
                saw_live_base = True
            if not saw_address_use:
                return reject_additive_offset("no_address_use")
            if not saw_live_base:
                return reject_additive_offset("no_live_base_seen")
            return True

        def undefined_regs_for_vars(variables, excluded_reg):
            return {
                candidate_reg
                for candidate_reg in regs_undefined
                if candidate_reg != excluded_reg
                and (
                    expr_vars(reg_to_symbol.get(candidate_reg))
                    & variables
                )
            }

        mixed_affine_primary_residual_regs = set()
        mixed_affine_support_regs = set()
        for reg in regs_undefined:
            symbol = reg_to_symbol.get(reg)
            symbol_vars = expr_vars(symbol)
            if not symbol_vars:
                continue
            direct_companions = set()
            scaled_base_companions = set()
            scaled_support_companions = set()
            for _, addr_symbol, _, _ in mem_accesses:
                if not (expr_vars(addr_symbol) & symbol_vars):
                    continue
                direct_residual = claripy.simplify(addr_symbol - symbol)
                if not (expr_vars(direct_residual) & symbol_vars):
                    direct_companions.update(undefined_regs_for_vars(
                        expr_vars(direct_residual),
                        reg,
                    ))
                scaled = scaled_symbol_affine(addr_symbol, symbol)
                if scaled is None:
                    continue
                _, _, companion_constraints = scaled
                companion_vars = set()
                for constraint in companion_constraints:
                    companion_vars.update(expr_vars(constraint))
                for companion_reg in undefined_regs_for_vars(
                    companion_vars - symbol_vars,
                    reg,
                ):
                    companion_symbol = reg_to_symbol.get(companion_reg)
                    companion_symbol_vars = expr_vars(companion_symbol)
                    companion_residual = claripy.simplify(
                        addr_symbol - companion_symbol
                    )
                    if not (
                        expr_vars(companion_residual) & companion_symbol_vars
                    ):
                        scaled_base_companions.add(companion_reg)
                    elif (
                        scaled_symbol_affine(addr_symbol, companion_symbol)
                        is not None
                    ):
                        scaled_support_companions.add(companion_reg)
            if any(
                direct_companion != scaled_companion
                for direct_companion in direct_companions
                for scaled_companion in scaled_base_companions
            ):
                mixed_affine_primary_residual_regs.add(reg)
                mixed_affine_support_regs.update(
                    scaled_support_companions - direct_companions
                )

        mixed_affine_residual_regs = (
            mixed_affine_primary_residual_regs | mixed_affine_support_regs
        )
        mixed_affine_zero_constraints = [
            reg_to_symbol[reg] == expr_bvv(0, reg_to_symbol[reg])
            for reg in sorted(
                mixed_affine_residual_regs,
                key=lambda item: item.id,
            )
            if reg in reg_to_symbol
        ]
        if mixed_affine_zero_constraints:
            _write_profile_stage(
                name,
                "init:materialize_init:mixed_affine_residual_zero",
            )
            mixed_affine_zero_committed = try_add_constraint_set_fast(
                mixed_affine_zero_constraints,
                timeout_ms=max(local_solver_timeout_ms, 10000),
            )
            if not mixed_affine_zero_committed:
                mixed_affine_primary_residual_regs.clear()
                mixed_affine_support_regs.clear()
                mixed_affine_residual_regs.clear()

        _write_profile_stage(name, "init:materialize_init:global_constraints")
        _write_profile_stage(name, "init:materialize_init:global_constraints:same_address_load_alias")
        add_same_address_load_alias_constraints()
        debug_check_stage("same_address_load_alias")
        _write_profile_stage(name, "init:materialize_init:global_constraints:loaded_pointer_scalar_offsets")
        if retry_index > 0 or len(mem_entries) > EAGER_POINTER_CONSTRAINT_LOAD_THRESHOLD:
            add_loaded_pointer_scalar_offset_constraints()
        debug_check_stage("loaded_pointer_scalar_offsets")
        _write_profile_stage(name, "init:materialize_init:global_constraints:loaded_pointer_residual_anchor")
        if retry_index > 0 or len(mem_entries) > EAGER_POINTER_CONSTRAINT_LOAD_THRESHOLD:
            add_loaded_pointer_residual_anchor_constraints()
        debug_check_stage("loaded_pointer_residual_anchor")
        _write_profile_stage(name, "init:materialize_init:global_constraints:livein_base_residual_anchor")
        add_livein_base_residual_anchor_constraints()
        debug_check_stage("livein_base_residual_anchor")
        _write_profile_stage(name, "init:materialize_init:global_constraints:mul_address_carrier")
        add_mul_address_carrier_constraints()
        debug_check_stage("mul_address_carrier")
        _write_profile_stage(name, "init:materialize_init:global_constraints:additive_offset_scalar_zero")
        add_additive_offset_scalar_zero_constraints()
        debug_check_stage("additive_offset_scalar_zero")
        _write_profile_stage(name, "init:materialize_init:global_constraints:arithmetic_hints")
        if retry_index == 0 or len(mem_entries) < GLOBAL_NO_OVERLAP_LOAD_THRESHOLD:
            add_arithmetic_address_hint_constraints()
        debug_check_stage("arithmetic_hints")
        _write_profile_stage(name, "init:materialize_init:global_constraints:scalar_zero_address_loads")
        add_scalar_zero_address_load_constraints()
        debug_check_stage("scalar_zero_address_loads")
        _write_profile_stage(name, "init:materialize_init:global_constraints:livein_loaded_offset_base")
        add_livein_loaded_offset_base_constraints()
        debug_check_stage("livein_loaded_offset_base")
        _write_profile_stage(name, "init:materialize_init:global_constraints:loaded_addr_scalar_zero")
        add_loaded_address_scalar_zero_constraints()
        debug_check_stage("loaded_addr_scalar_zero")
        _write_profile_stage(name, "init:materialize_init:global_constraints:direct_loaded_pointer_stack")
        add_direct_loaded_pointer_stack_constraints()
        debug_check_stage("direct_loaded_pointer_stack")
        _write_profile_stage(name, "init:materialize_init:global_constraints:pointer_scalar_load_slot_no_overlap")
        add_pointer_scalar_load_slot_no_overlap_constraints()
        debug_check_stage("pointer_scalar_load_slot_no_overlap")
        _write_profile_stage(name, "init:materialize_init:global_constraints:access_range")
        add_access_range_constraints()
        debug_check_stage("access_range")
        _write_profile_stage(name, "init:materialize_init:global_constraints:memory_dataflow")
        add_memory_dataflow_constraints()
        debug_check_stage("memory_dataflow")
        _write_profile_stage(name, "init:materialize_init:global_constraints:store_pointer_sources")
        if retry_index == 0 or len(mem_entries) < GLOBAL_NO_OVERLAP_LOAD_THRESHOLD:
            add_store_pointer_source_constraints()
        debug_check_stage("store_pointer_sources")
        _write_profile_stage(name, "init:materialize_init:global_constraints:load_slot_no_overlap")
        add_load_slot_no_overlap_constraints()
        debug_check_stage("load_slot_no_overlap")
        _write_profile_stage(name, "init:materialize_init:global_constraints:pointer_load_slot_no_overlap")
        add_pointer_load_slot_no_overlap_constraints()
        debug_check_stage("pointer_load_slot_no_overlap")
        _write_profile_stage(name, "init:materialize_init:global_constraints:pointer_derived_slot_no_overlap")
        add_pointer_derived_access_slot_no_overlap_constraints()
        debug_check_stage("pointer_derived_slot_no_overlap")
        _write_profile_stage(name, "init:materialize_init:global_constraints:pointer_value_no_alias")
        add_pointer_value_no_alias_constraints()
        debug_check_stage("pointer_value_no_alias")
        _write_profile_stage(name, "init:materialize_init:global_constraints:pointer_anchor")
        add_pointer_anchor_simplification_constraints()
        debug_check_stage("pointer_anchor")
        _write_profile_stage(name, "init:materialize_init:global_constraints:register_anchor")
        add_register_anchor_simplification_constraints()
        debug_check_stage("register_anchor")
        _write_profile_stage(name, "init:materialize_init:global_constraints:store_load_slot_no_overlap")
        add_store_load_slot_no_overlap_constraints()
        debug_check_stage("store_load_slot_no_overlap")
        _write_profile_stage(name, "init:materialize_init:global_constraints:risky_source_no_overlap")
        add_risky_source_no_overlap_constraints()
        debug_check_stage("risky_source_no_overlap")
        _write_profile_stage(name, "init:materialize_init:global_constraints:pointer_slot_store_no_overlap")
        add_pointer_slot_store_no_overlap_constraints()
        debug_check_stage("pointer_slot_store_no_overlap")
        _write_profile_stage(name, "init:materialize_init:global_constraints:done")

        loaded_addr_vars = set()
        for load_inst, rd_symbol, _, load_idx in load_accesses:
            rd_vars = getattr(rd_symbol, 'variables', set())
            if not rd_vars:
                continue
            for _, addr_symbol, access_idx, _ in mem_accesses:
                if access_idx > load_idx and (getattr(addr_symbol, 'variables', set()) & rd_vars):
                    loaded_addr_vars.update(rd_vars)
                    break

        fixed_reg_value_hints = {}
        def has_nonlinear_address_use_for_reg(reg):
            symbol = reg_to_symbol.get(reg)
            if symbol is None:
                return False
            symbol_vars = expr_vars(symbol)
            if not symbol_vars:
                return False
            nonlinear_ops = {'__mul__', 'Mul', '__floordiv__', '__truediv__', '__div__', 'SDiv', 'UDiv'}
            for _, addr_symbol, _, _ in mem_accesses:
                if not (expr_vars(addr_symbol) & symbol_vars):
                    continue
                for node in iter_ast_nodes(addr_symbol):
                    if getattr(node, 'op', '') in nonlinear_ops and (expr_vars(node) & symbol_vars):
                        return True
            return False

        for reg, values in reg_value_hints.items():
            if reg not in reg_to_symbol:
                continue
            if not has_nonlinear_address_use_for_reg(reg):
                continue
            unique_hint_values = []
            seen_hint_values = set()
            for value in values:
                value &= ((1 << 64) - 1)
                if value in seen_hint_values:
                    continue
                seen_hint_values.add(value)
                unique_hint_values.append(value)
            if len(unique_hint_values) == 1:
                fixed_reg_value_hints[reg] = unique_hint_values[0]

        base_like_regs = set()
        base_like_sources = {}
        reg_min_stack_offsets = {}
        reg_defined_before_access_cache = {}

        def reg_defined_before_access(reg, access_idx):
            key = (reg, access_idx)
            if key not in reg_defined_before_access_cache:
                reg_defined_before_access_cache[key] = any(
                    getattr(prev_inst, 'get_def', lambda: None)() == reg
                    for prev_inst in prog2se.insts[:access_idx]
                )
            return reg_defined_before_access_cache[key]

        for reg, min_offset in register_anchor_min_offsets.items():
            if reg in reg_to_symbol:
                base_like_regs.add(reg)
                base_like_sources.setdefault(reg, 'register_anchor')
                reg_min_stack_offsets[reg] = _align_up(min_offset, INIT_ACCESS_ALIGN)
        for reg in undef_base_regs:
            if reg in reg_to_symbol:
                symbol_vars = expr_vars(reg_to_symbol[reg])
                if symbol_vars and not any(
                    expr_vars(addr_symbol) & symbol_vars
                    for _, addr_symbol, _, _ in mem_accesses
                ):
                    continue
                if reg_is_additive_offset_to_independent_base(reg):
                    continue
                if symbol_vars and not any(
                    (expr_vars(addr_symbol) & symbol_vars)
                    and not reg_defined_before_access(reg, access_idx)
                    and not (
                        expr_vars(claripy.simplify(addr_symbol - reg_to_symbol[reg]))
                        & symbol_vars
                    )
                    for _, addr_symbol, access_idx, _ in mem_accesses
                ):
                    continue
                base_like_regs.add(reg)
                base_like_sources.setdefault(reg, 'undef_base')
                reg_min_stack_offsets[reg] = max(
                    reg_min_stack_offsets.get(reg, INIT_PTR_MIN_OFFSET),
                    INIT_PTR_MIN_OFFSET,
                )
        for reg in reg_to_symbol:
            symbol_vars = expr_vars(reg_to_symbol[reg])
            for inst, addr_symbol, access_idx, width in mem_accesses:
                if getattr(inst, 'rs1', None) != reg:
                    continue
                if reg_defined_before_access(reg, access_idx):
                    continue
                if symbol_vars and not (expr_vars(addr_symbol) & symbol_vars):
                    continue
                base_like_regs.add(reg)
                base_like_sources.setdefault(reg, 'direct_livein_rs1')
                min_offset = reg_min_stack_offsets.get(reg, INIT_PTR_MIN_OFFSET)
                imm = _signed_u64(inst.imm)
                if imm >= 0:
                    min_offset = max(min_offset, imm + width)
                reg_min_stack_offsets[reg] = _align_up(min_offset, INIT_ACCESS_ALIGN)
        # Direct live-in pointer loads are often mixed with repeated pointer-chain
        # field loads.  Keep their derived access slots above that small field
        # window, otherwise the base register may be fixed before load-slot
        # materialization and later collide with an already chosen pointer slot.
        direct_pointer_load_headroom = INIT_PTR_MIN_OFFSET + 6 * INIT_ACCESS_SLOT_WIDTH
        for load_inst, _rd_symbol, load_addr_symbol, load_idx in pointer_source_loads:
            if load_inst.width != 8:
                continue
            for reg, symbol in reg_to_symbol.items():
                if getattr(load_inst, 'rs1', None) != reg:
                    continue
                if reg_defined_before_access(reg, load_idx):
                    continue
                symbol_vars = expr_vars(symbol)
                if symbol_vars and not (expr_vars(load_addr_symbol) & symbol_vars):
                    continue
                residual = claripy.simplify(load_addr_symbol - symbol)
                if expr_vars(residual) & symbol_vars:
                    continue
                residual_value = concrete_expr_value(residual)
                if residual_value is None:
                    continue
                imm = _signed_u64(residual_value)
                if imm < 0:
                    continue
                min_offset = reg_min_stack_offsets.get(reg, INIT_PTR_MIN_OFFSET)
                pointer_load_min_offset = imm + load_inst.width
                headroom_offset = imm + direct_pointer_load_headroom
                if headroom_offset <= STACK_RANGE:
                    pointer_load_min_offset = max(pointer_load_min_offset, headroom_offset)
                reg_min_stack_offsets[reg] = _align_up(
                    max(min_offset, pointer_load_min_offset),
                    INIT_ACCESS_ALIGN,
                )
        for reg, symbol in reg_to_symbol.items():
            symbol_vars = getattr(symbol, 'variables', set())
            if not symbol_vars:
                continue
            if reg_is_additive_offset_to_independent_base(reg):
                continue
            for inst, addr_symbol, _, width in mem_accesses:
                if not (symbol_vars & getattr(addr_symbol, 'variables', set())):
                    continue
                residual = claripy.simplify(addr_symbol - symbol)
                residual_vars = getattr(residual, 'variables', set())
                if not (symbol_vars & residual_vars) and not (residual_vars & loaded_addr_vars):
                    base_like_regs.add(reg)
                    base_like_sources.setdefault(reg, 'additive_residual')
                    min_offset = reg_min_stack_offsets.get(reg, INIT_PTR_MIN_OFFSET)
                    residual_value = concrete_expr_value(residual)
                    if residual_value is not None:
                        imm = _signed_u64(residual_value)
                        if imm >= 0:
                            min_offset = max(min_offset, imm + width)
                    reg_min_stack_offsets[reg] = _align_up(min_offset, INIT_ACCESS_ALIGN)
            if reg in base_like_regs:
                continue

        def direct_affine_accesses_for_reg(reg):
            symbol = reg_to_symbol.get(reg)
            if symbol is None:
                return []
            symbol_vars = expr_vars(symbol)
            if not symbol_vars:
                return []
            accesses = []
            for _, addr_symbol, _, width in mem_accesses:
                if not (expr_vars(addr_symbol) & symbol_vars):
                    continue
                residual = claripy.simplify(addr_symbol - symbol)
                if expr_vars(residual) & symbol_vars:
                    continue
                residual_value = concrete_expr_value(residual)
                if residual_value is None:
                    continue
                accesses.append((_signed_u64(residual_value), width))
            return accesses

        repeated_direct_base_regs = set()
        repeated_direct_base_vars = set()
        for reg in reg_to_symbol:
            direct_accesses = direct_affine_accesses_for_reg(reg)
            if len(direct_accesses) < 2:
                continue
            repeated_direct_base_regs.add(reg)
            base_like_regs.add(reg)
            base_like_sources.setdefault(reg, 'repeated_direct_affine')
            min_offset = reg_min_stack_offsets.get(reg, INIT_PTR_MIN_OFFSET)
            for imm, width in direct_accesses:
                if imm >= 0:
                    min_offset = max(min_offset, imm + width)
            reg_min_stack_offsets[reg] = _align_up(min_offset, INIT_ACCESS_ALIGN)
            repeated_direct_base_vars.update(expr_vars(reg_to_symbol[reg]))

        for reg in list(base_like_regs):
            if direct_affine_accesses_for_reg(reg):
                continue
            symbol = reg_to_symbol.get(reg)
            if symbol is None:
                continue
            symbol_vars = expr_vars(symbol)
            if not symbol_vars:
                continue
            address_uses = [
                addr_symbol
                for _, addr_symbol, _, _ in mem_accesses
                if expr_vars(addr_symbol) & symbol_vars
            ]
            if not address_uses:
                continue
            if all(
                (expr_vars(addr_symbol) & (repeated_direct_base_vars - symbol_vars))
                for addr_symbol in address_uses
            ):
                base_like_regs.remove(reg)
                base_like_sources.pop(reg, None)
                reg_min_stack_offsets.pop(reg, None)

        for load_inst, rd_symbol, load_addr_symbol, load_idx in pointer_source_loads:
            if load_inst.width != 8:
                continue
            prior_store = prior_same_addr_store(load_addr_symbol, load_idx, allow_solver=False)
            if prior_store is None:
                continue
            _, _, _, store_width, store_data_symbol = prior_store
            stored_expr = stored_value_for_load(store_data_symbol, store_width, load_inst)
            if stored_expr is None:
                continue
            stored_vars = expr_vars(stored_expr)
            if not stored_vars:
                continue
            load_min_offset = _align_up(
                max(
                    INIT_PTR_MIN_OFFSET,
                    min_pointer_offset_for_vars(expr_vars(rd_symbol), load_idx),
                ),
                INIT_ACCESS_ALIGN,
            )
            for reg, symbol in reg_to_symbol.items():
                symbol_vars = expr_vars(symbol)
                if not symbol_vars or not (stored_vars & symbol_vars):
                    continue
                residual = sub_same_width(stored_expr, symbol)
                if residual is None:
                    continue
                if expr_vars(residual) & symbol_vars:
                    continue
                residual_value = concrete_expr_value(residual)
                if residual_value is None:
                    continue
                imm = _signed_u64(residual_value)
                min_offset = load_min_offset
                if imm >= 0:
                    min_offset = max(min_offset, load_min_offset + imm)
                min_offset = _align_up(max(INIT_PTR_MIN_OFFSET, min_offset), INIT_ACCESS_ALIGN)
                base_like_regs.add(reg)
                base_like_sources.setdefault(reg, 'store_forwarded_pointer')
                reg_min_stack_offsets[reg] = max(
                    reg_min_stack_offsets.get(reg, INIT_PTR_MIN_OFFSET),
                    min_offset,
                )

        direct_memory_base_like_regs = set()
        for reg in reg_to_symbol:
            symbol_vars = expr_vars(reg_to_symbol[reg])
            for inst, addr_symbol, access_idx, _ in mem_accesses:
                if getattr(inst, 'rs1', None) != reg:
                    continue
                if reg_defined_before_access(reg, access_idx):
                    continue
                if symbol_vars and not (expr_vars(addr_symbol) & symbol_vars):
                    continue
                residual = claripy.simplify(addr_symbol - reg_to_symbol[reg])
                if expr_vars(residual) & symbol_vars:
                    continue
                if concrete_expr_value(residual) is None:
                    continue
                direct_memory_base_like_regs.add(reg)
                break
        direct_memory_base_like_regs.update(repeated_direct_base_regs)

        def reg_has_direct_scaled_residual_base_use(reg):
            symbol = reg_to_symbol.get(reg)
            if symbol is None:
                return False
            symbol_vars = expr_vars(symbol)
            if not symbol_vars:
                return False
            scaled_ops = {'__lshift__', 'LShR', 'SShR', '__mul__', 'Mul', 'Concat'}

            def add_terms(node, sign=1, out=None):
                out = [] if out is None else out
                node = claripy.simplify(node)
                op = getattr(node, 'op', None)
                args = [arg for arg in getattr(node, 'args', ()) if hasattr(arg, 'op')]
                if op in {'__add__', 'Add'}:
                    for arg in args:
                        add_terms(arg, sign, out)
                    return out
                if op in {'__sub__', 'Sub'} and args:
                    add_terms(args[0], sign, out)
                    for arg in args[1:]:
                        add_terms(arg, -sign, out)
                    return out
                out.append((sign, node))
                return out

            def has_scaled_term(term):
                return any(
                    getattr(node, 'op', None) in scaled_ops and expr_vars(node)
                    for node in iter_ast_nodes(term)
                )

            for _, addr_symbol, _, _ in mem_accesses:
                if not (expr_vars(addr_symbol) & symbol_vars):
                    continue
                terms = add_terms(addr_symbol)
                has_direct_symbol_term = any(
                    sign > 0 and expr_key(term) == expr_key(symbol)
                    for sign, term in terms
                )
                if not has_direct_symbol_term:
                    continue
                if any(
                    sign > 0
                    and not (expr_vars(term) & symbol_vars)
                    and has_scaled_term(term)
                    for sign, term in terms
                ):
                    return True
            return False

        direct_scaled_residual_base_regs = {
            reg for reg in reg_to_symbol
            if reg_has_direct_scaled_residual_base_use(reg)
        }
        direct_memory_base_like_regs.update(direct_scaled_residual_base_regs)
        for reg in direct_scaled_residual_base_regs:
            base_like_regs.add(reg)
            base_like_sources.setdefault(reg, 'direct_scaled_residual')
            reg_min_stack_offsets[reg] = max(
                reg_min_stack_offsets.get(reg, INIT_PTR_MIN_OFFSET),
                INIT_PTR_MIN_OFFSET,
            )

        loaded_pointer_scalar_regs = set()
        pointer_nonlinear_scalar_regs = set()
        for reg, symbol in reg_to_symbol.items():
            if reg not in base_like_regs:
                continue
            symbol_vars = expr_vars(symbol)
            if not symbol_vars:
                continue
            has_direct_livein_base_use = any(
                getattr(inst, 'rs1', None) == reg
                and (expr_vars(addr_symbol) & symbol_vars)
                and not reg_defined_before_access(reg, access_idx)
                for inst, addr_symbol, access_idx, _ in mem_accesses
            )
            if has_direct_livein_base_use:
                continue
            addr_uses = [
                addr_symbol
                for _, addr_symbol, _, _ in mem_accesses
                if expr_vars(addr_symbol) & symbol_vars
            ]
            if not addr_uses:
                continue
            scalar_constrained = False
            for load_inst, rd_symbol, _, load_idx in load_accesses:
                if load_inst.width != 8:
                    continue
                rd_vars = expr_vars(rd_symbol)
                if not rd_vars:
                    continue
                for _, addr_symbol, access_idx, _ in mem_accesses:
                    if access_idx <= load_idx:
                        continue
                    addr_vars = expr_vars(addr_symbol)
                    if not (addr_vars & symbol_vars) or not (addr_vars & rd_vars):
                        continue
                    if (addr_vars & pointer_loaded_addr_vars) and not (rd_vars & pointer_loaded_addr_vars):
                        continue
                    residual_constraints = constraints_to_carrier(addr_symbol, rd_symbol)
                    if residual_constraints is None:
                        residual = claripy.simplify(addr_symbol - rd_symbol)
                        residual_vars = expr_vars(residual)
                        if (residual_vars & rd_vars) or not (residual_vars & symbol_vars):
                            continue
                        residual_constraints = constraints_to_constant(
                            residual,
                            0,
                            forbidden_vars=rd_vars,
                        )
                        if residual_constraints is None:
                            continue
                    if not any(expr_vars(constraint) & symbol_vars for constraint in residual_constraints):
                        continue
                    if try_add_constraint_set(residual_constraints):
                        loaded_pointer_scalar_regs.add(reg)
                        scalar_constrained = True
                        break
                if scalar_constrained:
                    break

        nonlinear_ops = {'__mul__', 'Mul', '__floordiv__', '__truediv__', '__div__', 'SDiv', 'UDiv'}
        for reg, symbol in reg_to_symbol.items():
            if reg not in base_like_regs:
                continue
            symbol_vars = expr_vars(symbol)
            if not symbol_vars:
                continue
            has_direct_livein_base_use = any(
                getattr(inst, 'rs1', None) == reg
                and (expr_vars(addr_symbol) & symbol_vars)
                for inst, addr_symbol, _, _ in mem_accesses
            )
            if has_direct_livein_base_use:
                continue
            for _, addr_symbol, _, _ in mem_accesses:
                addr_vars = expr_vars(addr_symbol)
                if not (addr_vars & symbol_vars) or not (addr_vars & pointer_loaded_addr_vars):
                    continue
                if any(
                    getattr(node, 'op', '') in nonlinear_ops
                    and (expr_vars(node) & symbol_vars)
                    for node in iter_ast_nodes(addr_symbol)
                ):
                    pointer_nonlinear_scalar_regs.add(reg)
                    break

        for reg in loaded_pointer_scalar_regs:
            if reg in direct_memory_base_like_regs:
                continue
            base_like_regs.discard(reg)
            base_like_sources.pop(reg, None)
            reg_min_stack_offsets.pop(reg, None)
        for reg in pointer_nonlinear_scalar_regs:
            if reg in direct_memory_base_like_regs:
                continue
            base_like_regs.discard(reg)
            base_like_sources.pop(reg, None)
            reg_min_stack_offsets.pop(reg, None)
        for reg in residual_scalar_regs:
            if reg in direct_memory_base_like_regs:
                continue
            base_like_regs.discard(reg)
            base_like_sources.pop(reg, None)
            reg_min_stack_offsets.pop(reg, None)
        for reg in fixed_reg_value_hints:
            if reg in direct_memory_base_like_regs:
                continue
            base_like_regs.discard(reg)
            base_like_sources.pop(reg, None)
            reg_min_stack_offsets.pop(reg, None)
        for reg in scalar_hint_regs:
            if reg in direct_memory_base_like_regs:
                continue
            if reg in register_anchor_min_offsets:
                continue
            base_like_regs.discard(reg)
            base_like_sources.pop(reg, None)
            reg_min_stack_offsets.pop(reg, None)

        if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD:
            for reg in list(base_like_regs):
                symbol = reg_to_symbol.get(reg)
                if symbol is None:
                    continue
                symbol_vars = expr_vars(symbol)
                if not symbol_vars:
                    continue
                min_offset = reg_min_stack_offsets.get(reg, INIT_PTR_MIN_OFFSET)
                guarded_store = False
                for store_inst, store_addr_symbol, store_idx, store_width, _ in store_accesses:
                    if getattr(store_inst, 'rs1', None) != reg:
                        continue
                    if reg_defined_before_access(reg, store_idx):
                        continue
                    if not (expr_vars(store_addr_symbol) & symbol_vars):
                        continue
                    residual = claripy.simplify(store_addr_symbol - symbol)
                    if expr_vars(residual) & symbol_vars:
                        continue
                    residual_value = concrete_expr_value(residual)
                    if residual_value is None:
                        continue
                    imm = _signed_u64(residual_value)
                    if imm < 0:
                        continue
                    min_offset = max(
                        min_offset,
                        imm + max(LIVEIN_STORE_LOW_GUARD_OFFSET, store_width),
                    )
                    guarded_store = True
                if guarded_store:
                    reg_min_stack_offsets[reg] = _align_up(min_offset, INIT_ACCESS_ALIGN)
                    base_like_sources.setdefault(reg, 'guarded_livein_store')

        if verbose:
            print('base_like_regs', [str(reg) for reg in sorted(base_like_regs, key=lambda r: r.id)])
            print('reg_min_stack_offsets', {str(reg): offset for reg, offset in reg_min_stack_offsets.items()})
            if loaded_pointer_scalar_regs:
                print('loaded_pointer_scalar_regs', [str(reg) for reg in sorted(loaded_pointer_scalar_regs, key=lambda r: r.id)])
            if pointer_nonlinear_scalar_regs:
                print('pointer_nonlinear_scalar_regs', [str(reg) for reg in sorted(pointer_nonlinear_scalar_regs, key=lambda r: r.id)])
            if residual_scalar_regs:
                print('residual_scalar_regs', [str(reg) for reg in sorted(residual_scalar_regs, key=lambda r: r.id)])
            print('base_like_sources', {str(reg): base_like_sources.get(reg) for reg in sorted(base_like_regs, key=lambda r: r.id)})

        deferred_regs = set()
        deferred_regs.update(direct_scaled_residual_base_regs)

        def has_scaled_address_carrier_use(symbol):
            symbol_vars = expr_vars(symbol)
            if not symbol_vars:
                return False
            scaled_ops = {'__lshift__', 'LShR', 'SShR', '__mul__', 'Mul', 'Concat'}
            for _, addr_symbol, _, _ in mem_accesses:
                if not (expr_vars(addr_symbol) & symbol_vars):
                    continue
                if scaled_symbol_affine(addr_symbol, symbol) is not None:
                    return True
                for node in iter_ast_nodes(addr_symbol):
                    if getattr(node, 'op', None) in scaled_ops and (expr_vars(node) & symbol_vars):
                        return True
            return False

        def has_self_mul_address_residual(reg):
            tracking = False
            for inst in prog.insts:
                if (
                    isinstance(inst, RFmtInst)
                    and inst.name in {'mul', 'mulw'}
                    and inst.rd == reg
                    and (inst.rs1 == reg or inst.rs2 == reg)
                ):
                    tracking = True
                    continue
                if tracking and inst.type in [IType.Load, IType.Store, IType.Amo] and inst.rs1 == reg:
                    return True
                rd = inst.get_def()
                if rd != reg:
                    continue
                uses_reg = (
                    getattr(inst, 'rs1', None) == reg
                    or getattr(inst, 'rs2', None) == reg
                )
                if tracking and uses_reg:
                    continue
                tracking = False

        def has_fixed_residual_mul_carrier_use_for_symbol(symbol):
            symbol_vars = expr_vars(symbol)
            if not symbol_vars:
                return False
            for _, addr_symbol, _, _ in mem_accesses:
                if not (expr_vars(addr_symbol) & symbol_vars):
                    continue
                for mul_node in iter_ast_nodes(addr_symbol):
                    if getattr(mul_node, 'op', None) not in {'__mul__', 'Mul'}:
                        continue
                    if not (expr_vars(mul_node) & symbol_vars):
                        continue
                    residual = sub_same_width(addr_symbol, mul_node)
                    if residual is None:
                        continue
                    if expr_vars(residual) & expr_vars(mul_node):
                        continue
                    residual_value = concrete_expr_value(residual)
                    if residual_value is None:
                        continue
                    if stack_offset_for_value(residual_value) is None:
                        return True
            return False

        loaded_residual_base_vars = loaded_addr_vars | address_loaded_addr_vars | pointer_loaded_addr_vars
        for _load_inst, rd_symbol, _load_addr_symbol, _load_idx in load_accesses:
            loaded_residual_base_vars.update(expr_vars(rd_symbol))
        for reg in list(base_like_regs):
            symbol = reg_to_symbol.get(reg)
            if symbol is None:
                continue
            symbol_vars = getattr(symbol, 'variables', set())
            if not symbol_vars:
                continue
            for _, addr_symbol, _, _ in mem_accesses:
                addr_vars = expr_vars(addr_symbol)
                if (
                    (addr_vars & symbol_vars)
                    and (addr_vars & loaded_residual_base_vars)
                ):
                    deferred_regs.add(reg)
                    break

        for reg, symbol in reg_to_symbol.items():
            if reg in base_like_regs:
                continue
            symbol_vars = getattr(symbol, 'variables', set())
            if not symbol_vars:
                continue
            if has_fixed_residual_mul_carrier_use_for_symbol(symbol):
                deferred_regs.add(reg)
                continue
            if has_scaled_address_carrier_use(symbol):
                continue
            for _, addr_symbol, _, _ in mem_accesses:
                addr_vars = getattr(addr_symbol, 'variables', set())
                if (addr_vars & symbol_vars) and (addr_vars & loaded_addr_vars):
                    deferred_regs.add(reg)
                    break
            if reg in deferred_regs:
                continue
            for _, _, load_addr_symbol, load_idx in address_source_loads:
                for _, store_addr_symbol, store_idx, _, store_data_symbol in store_accesses:
                    if store_idx >= load_idx:
                        continue
                    if not same_address(store_addr_symbol, load_addr_symbol):
                        continue
                    if getattr(store_data_symbol, 'variables', set()) & symbol_vars:
                        deferred_regs.add(reg)
                        break
                if reg in deferred_regs:
                    break

        reg_memory_relevance_cache = {}

        def reg_flows_to_memory_or_control(reg):
            if reg in reg_memory_relevance_cache:
                return reg_memory_relevance_cache[reg]
            tainted = {reg}
            for inst in prog.insts:
                uses = set(inst.get_uses() or [])
                if tainted & uses and inst.type in [IType.Branch, IType.Jump]:
                    reg_memory_relevance_cache[reg] = True
                    return True
                if inst.type in [IType.Load, IType.Store, IType.Amo, IType.Lr, IType.Sc]:
                    if inst.get_addr() in tainted or inst.get_data() in tainted:
                        reg_memory_relevance_cache[reg] = True
                        return True
                rd = inst.get_def()
                if rd is None or rd == XREG[0]:
                    continue
                if tainted & uses:
                    tainted.add(rd)
                elif rd in tainted:
                    tainted.remove(rd)
                if not tainted:
                    break
            reg_memory_relevance_cache[reg] = False
            return False

        def choose_store_only_symbolic_base_value(symbol, min_offset):
            symbol_vars = expr_vars(symbol)
            if not symbol_vars:
                return None
            related = []
            max_positive_residual = 0
            for _inst, addr_symbol, _idx, access_width, _store_data_symbol in store_accesses:
                if not (expr_vars(addr_symbol) & symbol_vars):
                    continue
                residual = claripy.simplify(addr_symbol - symbol)
                if expr_vars(residual) & symbol_vars:
                    return None
                residual_value = concrete_expr_value(residual)
                residual_constraints = []
                if residual_value is None:
                    residual_constraints = constraints_to_constant(
                        residual,
                        0,
                        forbidden_vars=symbol_vars,
                    )
                    if residual_constraints is None:
                        return None
                    imm = 0
                else:
                    imm = _signed_u64(residual_value)
                related.append((imm, access_width, list(residual_constraints)))
                if imm >= 0:
                    max_positive_residual = max(max_positive_residual, imm + access_width)
            if not related:
                return None
            start = _align_up(
                max(INIT_PTR_MIN_OFFSET, min_offset, max_positive_residual),
                INIT_ACCESS_ALIGN,
            )
            for base_offset in range(start, STACK_RANGE + 1, INIT_ACCESS_ALIGN):
                ranges = []
                constraints = [(init_sp - symbol) == base_offset]
                ok = True
                for imm, access_width, residual_constraints in related:
                    access_offset = base_offset - imm
                    if access_offset <= 0 or access_offset > STACK_RANGE:
                        ok = False
                        break
                    if access_width > 1 and access_offset % access_width:
                        ok = False
                        break
                    ranges.append((access_offset, init_slot_width(access_width)))
                    constraints.extend(residual_constraints)
                if not ok:
                    continue
                if any(
                    concrete_ranges_overlap(access_offset, access_width, used_offset, used_width)
                    for access_offset, access_width in ranges
                    for used_offset, used_width in used_stack_offsets
                ):
                    continue
                if (
                    try_add_constraint_set_fast(constraints, timeout_ms=100)
                    or try_add_constraint_set_related(
                        constraints,
                        symbol_vars,
                        timeout_ms=100,
                    )
                ):
                    used_stack_offsets.extend(ranges)
                    return concrete_stack_addr(base_offset)
            return None

        def materialize_register(r):
            nonlocal scalar_offset
            symbol = reg_to_symbol[r]
            write_stage("init:materialize_init:register", reg=r.name, phase="start")
            hinted_values = sorted({value & ((1 << 64) - 1) for value in reg_value_hints.get(r, [])})
            symbol_vars_for_fallback = expr_vars(symbol)
            address_uses_for_symbol = [
                addr_symbol
                for _, addr_symbol, _, _ in mem_accesses
                if symbol_vars_for_fallback and (expr_vars(addr_symbol) & symbol_vars_for_fallback)
            ]
            has_additive_address_use = any(
                not (expr_vars(claripy.simplify(addr_symbol - symbol)) & symbol_vars_for_fallback)
                for addr_symbol in address_uses_for_symbol
            )
            has_nonadditive_address_use = any(
                expr_vars(claripy.simplify(addr_symbol - symbol)) & symbol_vars_for_fallback
                for addr_symbol in address_uses_for_symbol
            )
            loaded_value_varset_for_residual = set(loaded_addr_vars) | set(address_loaded_addr_vars) | set(pointer_loaded_addr_vars)
            for _load_inst, loaded_rd_symbol, _load_addr_symbol, _load_idx in load_accesses:
                loaded_value_varset_for_residual.update(expr_vars(loaded_rd_symbol))
            has_loaded_symbolic_address_residual = any(
                expr_vars(claripy.simplify(addr_symbol - symbol)) & loaded_value_varset_for_residual
                for addr_symbol in address_uses_for_symbol
            )
            base_like_varset = set()
            for base_reg in base_like_regs:
                base_symbol = reg_to_symbol.get(base_reg)
                if base_symbol is not None:
                    base_like_varset.update(expr_vars(base_symbol))
            has_other_stack_carrier = any(
                (expr_vars(addr_symbol) - symbol_vars_for_fallback)
                & (base_like_varset | pointer_loaded_addr_vars)
                for addr_symbol in address_uses_for_symbol
            )
            materialized_reg_vars = set()
            for materialized_reg in reg_values:
                materialized_symbol = reg_to_symbol.get(materialized_reg)
                if materialized_symbol is not None:
                    materialized_reg_vars.update(expr_vars(materialized_symbol))
            constrained_by_materialized = any(
                (getattr(constraint, 'variables', set()) & symbol_vars_for_fallback)
                and (getattr(constraint, 'variables', set()) & materialized_reg_vars)
                for constraint in candidate_solver.constraints
            )
            constrained_by_existing_solver = any(
                getattr(constraint, 'variables', set()) & symbol_vars_for_fallback
                for constraint in candidate_solver.constraints
            )
            additive_offset_to_pointer_source = reg_is_additive_offset_to_independent_base(r)
            residual_like_scalar = r in residual_scalar_regs or r in pointer_nonlinear_scalar_regs
            self_mul_address_residual = has_self_mul_address_residual(r)
            scaled_address_carrier_use = has_scaled_address_carrier_use(symbol)
            non_power_two_affine_use = any(
                (
                    (scaled := scaled_symbol_affine(addr_symbol, symbol))
                    is not None
                )
                and bool(scaled[0] & (scaled[0] - 1))
                for _, addr_symbol, _, _ in mem_accesses
                if expr_vars(addr_symbol) & symbol_vars_for_fallback
            )
            fixed_residual_mul_carrier_use = has_fixed_residual_mul_carrier_use_for_symbol(symbol)
            mul_address_carrier_use = any(
                (expr_vars(addr_symbol) & symbol_vars_for_fallback)
                and any(
                    getattr(node, 'op', None) in {'__mul__', 'Mul'}
                    and (expr_vars(node) & symbol_vars_for_fallback)
                    for node in iter_ast_nodes(addr_symbol)
                )
                for _, addr_symbol, _, _ in mem_accesses
            )
            singleton_scalar_hint = len(hinted_values) == 1 and r not in direct_memory_base_like_regs
            allow_scalar_base_fallback = (
                has_additive_address_use
                and not residual_like_scalar
                and not self_mul_address_residual
                and not singleton_scalar_hint
                and r not in scalar_hint_regs
            )
            direct_affine_address_base = (
                has_additive_address_use
                and not has_nonadditive_address_use
                and not has_other_stack_carrier
                and not residual_like_scalar
                and not fixed_residual_mul_carrier_use
                and r not in scalar_hint_regs
            )
            if os.environ.get("RVMCA_DEBUG_LOAD_SLOTS") == "1" and (
                has_additive_address_use or has_nonadditive_address_use
            ):
                DEBUG(f"materialize_register_class {({
                    'reg': r.name,
                    'base_like': r in base_like_regs,
                    'has_additive_address_use': has_additive_address_use,
                    'has_nonadditive_address_use': has_nonadditive_address_use,
                    'has_loaded_symbolic_address_residual': has_loaded_symbolic_address_residual,
                    'has_other_stack_carrier': has_other_stack_carrier,
                    'residual_like_scalar': residual_like_scalar,
                    'fixed_residual_mul_carrier_use': fixed_residual_mul_carrier_use,
                    'mul_address_carrier_use': mul_address_carrier_use,
                    'self_mul_address_residual': self_mul_address_residual,
                    'scaled_address_carrier_use': scaled_address_carrier_use,
                    'non_power_two_affine_use': non_power_two_affine_use,
                    'scalar_hint': r in scalar_hint_regs,
                    'direct_affine_address_base': direct_affine_address_base,
                })}")
            val = None
            if r in mixed_affine_residual_regs:
                write_stage(
                    "init:materialize_init:register",
                    reg=r.name,
                    phase="mixed_affine_residual_zero",
                )
                zero_constraint = symbol == expr_bvv(0, symbol)
                zero_timeout_ms = max(local_solver_timeout_ms, 5000)
                if (
                    try_add_constraint_set_fast(
                        [zero_constraint],
                        timeout_ms=zero_timeout_ms,
                    )
                    or try_add_constraint_set_related(
                        [zero_constraint],
                        symbol_vars_for_fallback,
                        timeout_ms=zero_timeout_ms,
                    )
                ):
                    val = 0
            if (
                val is None
                and r in base_like_regs
                and has_additive_address_use
                and has_loaded_symbolic_address_residual
                and constrained_by_existing_solver
                and not direct_affine_address_base
            ):
                write_stage("init:materialize_init:register", reg=r.name, phase="loaded_residual_current_model")
                for model_val in solver_eval_current(symbol, n=8, timeout_ms=5000):
                    model_constraint = symbol == expr_bvv(model_val, symbol)
                    if (
                        try_add_constraint_set_fast([model_constraint], timeout_ms=5000)
                        or try_add_constraint_set_related(
                            [model_constraint],
                            symbol_vars_for_fallback,
                            timeout_ms=5000,
                        )
                    ):
                        val = model_val & ((1 << 64) - 1)
                        break
            if (
                r not in base_like_regs
		                and has_additive_address_use
                and (has_other_stack_carrier or additive_offset_to_pointer_source)
                and not fixed_residual_mul_carrier_use
            ):
                write_stage("init:materialize_init:register", reg=r.name, phase="additive_addr_scalar_zero")
                zero_constraint = symbol == expr_bvv(0, symbol)
                if (
                    try_add_constraint_set_fast([zero_constraint], timeout_ms=1000)
                    or try_add_constraint_set_related(
                        [zero_constraint],
                        symbol_vars_for_fallback,
                        timeout_ms=1000,
                    )
                ):
                    val = 0
            if (
                val is None
                and r not in base_like_regs
                and residual_like_scalar
                and has_additive_address_use
                and has_loaded_symbolic_address_residual
                and not fixed_residual_mul_carrier_use
            ):
                write_stage("init:materialize_init:register", reg=r.name, phase="loaded_residual_scalar_zero")
                zero_constraint = symbol == expr_bvv(0, symbol)
                if (
                    try_add_constraint_set_fast([zero_constraint], timeout_ms=1000)
                    or try_add_constraint_set_related(
                        [zero_constraint],
                        symbol_vars_for_fallback,
                        timeout_ms=1000,
                    )
                    ):
                        val = 0
            if (
                val is None
                and r not in base_like_regs
                and residual_like_scalar
                and singleton_scalar_hint
                and hinted_values[0] == 0
                and not fixed_residual_mul_carrier_use
            ):
                write_stage("init:materialize_init:register", reg=r.name, phase="residual_scalar_zero_hint")
                zero_constraint = symbol == expr_bvv(0, symbol)
                if (
                    try_add_constraint_set_fast([zero_constraint], timeout_ms=1000)
                    or try_add_constraint_set_related(
                        [zero_constraint],
                        symbol_vars_for_fallback,
                        timeout_ms=1000,
                    )
                ):
                    val = 0
            if (
                val is None
                and r not in base_like_regs
                and has_nonadditive_address_use
                and mul_address_carrier_use
                and not has_additive_address_use
                and not fixed_residual_mul_carrier_use
            ):
                write_stage("init:materialize_init:register", reg=r.name, phase="mul_residual_scalar_zero")
                zero_constraint = symbol == expr_bvv(0, symbol)
                zero_added = (
                    try_add_constraint_set_fast([zero_constraint], timeout_ms=1000)
                    or try_add_constraint_set_related(
                        [zero_constraint],
                        symbol_vars_for_fallback,
                        timeout_ms=1000,
                    )
                )
                if (
                    not zero_added
                    and use_static_memory_collection
                    and constraint_set_related_satisfiable(
                        [zero_constraint],
                        symbol_vars_for_fallback,
                        timeout_ms=max(local_solver_timeout_ms, 1000),
                    ) is not False
                ):
                    candidate_solver.add(zero_constraint)
                    added_constraint_cache.add(str(claripy.simplify(zero_constraint)))
                    debug_constraint_add("mul_residual_scalar_zero_assumed", zero_constraint)
                    zero_added = True
                if zero_added:
                    val = 0
            if (
                val is None
                and r not in base_like_regs
                and (
                    (has_nonadditive_address_use and has_other_stack_carrier)
                    or self_mul_address_residual
                )
                and not fixed_residual_mul_carrier_use
            ):
                write_stage("init:materialize_init:register", reg=r.name, phase="early_nonadditive_addr_scalar_zero")
                zero_constraint = symbol == expr_bvv(0, symbol)
                zero_timeout_ms = (
                    1000
                    if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                    else HEURISTIC_SOLVER_TIMEOUT_MS
                )
                zero_added = (
                    try_add_constraint_set_fast([zero_constraint], timeout_ms=zero_timeout_ms)
                    or try_add_constraint_set_related(
                        [zero_constraint],
                        symbol_vars_for_fallback,
                        timeout_ms=zero_timeout_ms,
                    )
                )
                if (
                    not zero_added
                    and use_static_memory_collection
                    and constraint_set_related_satisfiable(
                        [zero_constraint],
                        symbol_vars_for_fallback,
                        timeout_ms=max(local_solver_timeout_ms, 1000),
                    ) is not False
                ):
                    candidate_solver.add(zero_constraint)
                    added_constraint_cache.add(str(claripy.simplify(zero_constraint)))
                    debug_constraint_add("early_nonadditive_addr_scalar_zero_assumed", zero_constraint)
                    zero_added = True
                if zero_added:
                    val = 0
            if (
                val is None
                and r not in base_like_regs
                and non_power_two_affine_use
            ):
                write_stage(
                    "init:materialize_init:register",
                    reg=r.name,
                    phase="runtime_affine_quotient",
                )
                val = choose_scaled_address_register_value(symbol)
            if (
                val is None
                and r not in base_like_regs
                and (not self_mul_address_residual or scaled_address_carrier_use)
            ):
                if os.environ.get("RVMCA_DEBUG_REPAIR") == "1":
                    DEBUG(f"scaled_address_carrier_try {({
                        'reg': r.name,
                        'symbol': str(symbol),
                    })}")
                write_stage("init:materialize_init:register", reg=r.name, phase="scaled_addr_carrier")
                val = choose_scaled_address_register_value(symbol)
            if (
                val is None
                and constrained_by_materialized
                and r not in base_like_regs
                and not direct_affine_address_base
            ):
                write_stage("init:materialize_init:register", reg=r.name, phase="current_model")
                for model_val in solver_eval_current(symbol, n=8, timeout_ms=5000):
                    if try_add_constraint_set_fast(
                        [symbol == expr_bvv(model_val, symbol)],
                        timeout_ms=5000,
                    ):
                            val = model_val & ((1 << 64) - 1)
                            break
            if os.environ.get("RVMCA_DEBUG_REPAIR") == "1" and scaled_address_carrier_use:
                DEBUG(f"scaled_address_carrier_state {({
                    'reg': r.name,
                    'value': None if val is None else hex(val),
                })}")
            if (
                val is None
                and r not in base_like_regs
                and scaled_address_carrier_use
                and mul_address_carrier_use
                and has_nonadditive_address_use
                and not self_mul_address_residual
            ):
                write_stage("init:materialize_init:register", reg=r.name, phase="mul_neutral_factor")
                one_constraint = symbol == expr_bvv(1, symbol)
                if (
                    try_add_constraint_set_fast([one_constraint], timeout_ms=1000)
                    or try_add_constraint_set_related(
                        [one_constraint],
                        symbol_vars_for_fallback,
                        timeout_ms=1000,
                    )
                ):
                    val = 1
            if (
                len(hinted_values) == 1
                and r not in base_like_regs
                and r not in direct_memory_base_like_regs
                and not self_mul_address_residual
                and not scaled_address_carrier_use
                and not direct_affine_address_base
            ):
                write_stage("init:materialize_init:register", reg=r.name, phase="value_hint")
                if val is None:
                    try:
                        val = choose_register_value(symbol, hinted_values[0])
                    except AssertionError:
                        val = None
            if val is None and r in base_like_regs and r in reg_min_stack_offsets:
                if os.environ.get("RVMCA_DEBUG_LOAD_SLOTS") == "1":
                    DEBUG(f"materialize_register_branch {({'reg': r.name, 'branch': 'base_like_pointer'})}")
                write_stage(
                    "init:materialize_init:register",
                    reg=r.name,
                    phase="base_like_pointer",
                    base_source=base_like_sources.get(r),
                    min_offset=reg_min_stack_offsets.get(r),
                )
                if val is None:
                    val = choose_base_register_value(
                        symbol,
                        min_offset=reg_min_stack_offsets[r],
                        fast_anchor=True,
                    )
            if (
                val is None
                and direct_affine_address_base
            ):
                if os.environ.get("RVMCA_DEBUG_LOAD_SLOTS") == "1":
                    DEBUG(f"materialize_register_branch {({'reg': r.name, 'branch': 'direct_affine_base'})}")
                direct_min_offset = INIT_PTR_MIN_OFFSET
                direct_affine_only = True
                for _, addr_symbol, _, access_width in mem_accesses:
                    if not (expr_vars(addr_symbol) & symbol_vars_for_fallback):
                        continue
                    residual = claripy.simplify(addr_symbol - symbol)
                    if expr_vars(residual) & symbol_vars_for_fallback:
                        if os.environ.get("RVMCA_DEBUG_LOAD_SLOTS") == "1":
                            DEBUG(f"direct_affine_base_reject_self {({
                                'reg': r.name,
                                'addr': str(addr_symbol),
                                'residual': str(residual),
                            })}")
                        direct_affine_only = False
                        break
                    residual_value = concrete_expr_value(residual)
                    if residual_value is None:
                        if os.environ.get("RVMCA_DEBUG_LOAD_SLOTS") == "1":
                            DEBUG(f"direct_affine_base_reject_symbolic {({
                                'reg': r.name,
                                'addr': str(addr_symbol),
                                'residual': str(residual),
                                'vars': sorted(expr_vars(residual)),
                            })}")
                        direct_affine_only = False
                        break
                    imm = _signed_u64(residual_value)
                    if imm >= 0:
                        direct_min_offset = max(direct_min_offset, imm + access_width)
                if direct_affine_only:
                    write_stage("init:materialize_init:register", reg=r.name, phase="direct_affine_base")
                    val = choose_base_register_value(
                        symbol,
                        min_offset=_align_up(direct_min_offset, INIT_ACCESS_ALIGN),
                        fast_anchor=True,
                    )
            if val is None:
                if os.environ.get("RVMCA_DEBUG_LOAD_SLOTS") == "1":
                    DEBUG(f"materialize_register_branch {({'reg': r.name, 'branch': 'stack_relative' if r in base_like_regs else 'non_base'})}")
                write_stage("init:materialize_init:register", reg=r.name, phase="stack_relative" if r in base_like_regs else "non_base")
                if r in base_like_regs:
                    fallback_start = max(
                        INIT_PTR_MIN_OFFSET,
                        reg_min_stack_offsets.get(r, INIT_PTR_MIN_OFFSET),
                    )
                    if has_additive_address_use:
                        store_only_symbolic_base = (
                            not load_accesses
                            and not direct_affine_address_base
                            and any(
                                expr_vars(claripy.simplify(addr_symbol - symbol))
                                for addr_symbol in address_uses_for_symbol
                            )
                        )
                        if store_only_symbolic_base:
                            val = choose_store_only_symbolic_base_value(
                                symbol,
                                fallback_start,
                            )
                        if val is None:
                            val = choose_base_register_value(
                                symbol,
                                min_offset=fallback_start,
                                fast_anchor=store_only_symbolic_base,
                            )
                    else:
                        direct_offset = next_free_stack_offset(
                            used_stack_offsets,
                            align=INIT_ACCESS_ALIGN,
                            width=8,
                            start=fallback_start,
                        )
                        if direct_offset is not None:
                            if os.environ.get("RVMCA_DEBUG_LOAD_SLOTS") == "1":
                                DEBUG(f"materialize_register_stack_direct {({'reg': r.name, 'offset': direct_offset})}")
                            val = concrete_stack_addr(direct_offset)
                if val is None:
                    val = (
                        choose_stack_relative_register_value(
                            symbol,
                        )
                        if r in base_like_regs
                        else None
                    )
            if val is None and r not in base_like_regs:
                symbol_vars = expr_vars(symbol)
                has_direct_livein_base_use = symbol_vars and any(
                    getattr(inst, 'rs1', None) == r
                    and (expr_vars(addr_symbol) & symbol_vars)
                    and not reg_defined_before_access(r, access_idx)
                    for inst, addr_symbol, access_idx, _ in mem_accesses
                )
                has_loaded_address_use = symbol_vars and any(
                    (expr_vars(addr_symbol) & symbol_vars)
                    and (expr_vars(addr_symbol) & loaded_addr_vars)
                    for _, addr_symbol, _, _ in mem_accesses
                )
                if (
                    has_loaded_address_use
                    and not has_direct_livein_base_use
                    and not fixed_residual_mul_carrier_use
                ):
                    write_stage("init:materialize_init:register", reg=r.name, phase="loaded_addr_scalar_zero")
                    if try_add_constraint(symbol == expr_bvv(0, symbol)):
                        val = 0
            if (
                val is None
                and r not in base_like_regs
                and has_additive_address_use
                and has_other_stack_carrier
                and not fixed_residual_mul_carrier_use
            ):
                write_stage("init:materialize_init:register", reg=r.name, phase="additive_addr_scalar_zero")
                zero_constraint = symbol == expr_bvv(0, symbol)
                if (
                    try_add_constraint_set_fast([zero_constraint], timeout_ms=1000)
                    or try_add_constraint_set_related(
                        [zero_constraint],
                        symbol_vars_for_fallback,
                        timeout_ms=1000,
                    )
                ):
                    val = 0
            if (
                val is None
                and r not in base_like_regs
                and (
                    (has_nonadditive_address_use and has_other_stack_carrier)
                    or self_mul_address_residual
                )
                and not fixed_residual_mul_carrier_use
            ):
                write_stage("init:materialize_init:register", reg=r.name, phase="nonadditive_addr_scalar_zero")
                zero_constraint = symbol == expr_bvv(0, symbol)
                zero_timeout_ms = (
                    1000
                    if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                    else HEURISTIC_SOLVER_TIMEOUT_MS
                )
                if (
                    try_add_constraint_set_fast([zero_constraint], timeout_ms=zero_timeout_ms)
                    or try_add_constraint_set_related(
                        [zero_constraint],
                        symbol_vars_for_fallback,
                        timeout_ms=zero_timeout_ms,
                    )
                ):
                    val = 0
                elif (
                    use_static_memory_collection
                    and constraint_set_selection_satisfiable(
                        [zero_constraint],
                        timeout_ms=max(local_solver_timeout_ms, 1000),
                    ) is not False
                ):
                    candidate_solver.add(zero_constraint)
                    added_constraint_cache.add(str(claripy.simplify(zero_constraint)))
                    val = 0
            if val is not None:
                value_constraint = symbol == expr_bvv(val, symbol)
                stack_offset = stack_offset_for_value(val)
                stack_offset_constraint_added = False
                if r in base_like_regs and stack_offset is not None:
                    stack_offset_constraint = (init_sp - symbol) == stack_offset
                    stack_offset_constraint_added = (
                        try_add_constraint_set_fast(
                            [stack_offset_constraint],
                            timeout_ms=max(local_solver_timeout_ms, 1000),
                        )
                        or try_add_constraint_set_related(
                            [stack_offset_constraint],
                            symbol_vars_for_fallback,
                            timeout_ms=max(local_solver_timeout_ms, 1000),
                        )
                    )
                if debug_constraint_var and debug_constraint_var in str(symbol):
                    value_sat = constraint_set_selection_satisfiable(
                        [value_constraint],
                        timeout_ms=5000,
                    )
                    DEBUG(
                        f"materialize_register_value reg={r.name} "
                        f"value=0x{val & ((1 << 64) - 1):x} sat={value_sat}"
                    )
                value_commit_timeout_ms = (
                    max(local_solver_timeout_ms, 5000)
                    if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                    else max(local_solver_timeout_ms, HEURISTIC_SOLVER_TIMEOUT_MS)
                )
                value_constraint_added = try_add_constraint_set_fast(
                    [value_constraint],
                    timeout_ms=value_commit_timeout_ms,
                )
                if not value_constraint_added:
                    value_constraint_added = try_add_constraint_set_related(
                        [value_constraint],
                        symbol_vars_for_fallback,
                        timeout_ms=value_commit_timeout_ms,
                    )
                if (
                    not value_constraint_added
                    and len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                ):
                    value_sat = constraint_set_related_satisfiable(
                        [value_constraint],
                        symbol_vars_for_fallback,
                        timeout_ms=value_commit_timeout_ms,
                    )
                    if value_sat is not False:
                        candidate_solver.add(value_constraint)
                        added_constraint_cache.add(str(claripy.simplify(value_constraint)))
                        debug_constraint_add("register_value_assumed", value_constraint)
                        value_constraint_added = True
                if not value_constraint_added and stack_offset_constraint_added:
                    value_constraint_added = True
                if not value_constraint_added:
                    val = None
                else:
                    if r in base_like_regs and stack_offset is not None:
                        reserve_constant_access_ranges_for_materialized_base(symbol, stack_offset)
                    if stack_offset is not None and not any(
                        concrete_ranges_overlap(stack_offset, 8, used_offset, used_width)
                        for used_offset, used_width in used_stack_offsets
                    ):
                        used_stack_offsets.append((stack_offset, 8))
            if val is None:
                write_stage("init:materialize_init:register", reg=r.name, phase="scalar")
                symbol_vars = expr_vars(symbol)
                has_address_use = symbol_vars and any(
                    expr_vars(addr_symbol) & symbol_vars
                    for _, addr_symbol, _, _ in mem_accesses
                )
                if (
                    r not in base_like_regs
                    and not has_address_use
                ):
                    zero_constraint = symbol == expr_bvv(0, symbol)
                    unconstrained_scalar = not any(
                        getattr(constraint, 'variables', set()) & symbol_vars
                        for constraint in candidate_solver.constraints
                    )
                    if unconstrained_scalar:
                        candidate_solver.add(zero_constraint)
                        val = 0
                    elif (
                        try_add_constraint_set_fast([zero_constraint])
                        or try_add_constraint_set_related(
                            [zero_constraint],
                            symbol_vars,
                            timeout_ms=1000,
                        )
                    ):
                        val = 0
                    elif len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD:
                        if not reg_flows_to_memory_or_control(r):
                            val = 0
                        else:
                            for model_val in solver_eval_current(symbol, n=4, timeout_ms=5000):
                                model_constraint = symbol == expr_bvv(model_val, symbol)
                                if (
                                    try_add_constraint_set_fast([model_constraint], timeout_ms=5000)
                                    or try_add_constraint_set_related(
                                        [model_constraint],
                                        symbol_vars,
                                        timeout_ms=5000,
                                    )
                                ):
                                    val = model_val & ((1 << 64) - 1)
                                    break
                        store_data_only = any(
                            expr_vars(store_data_symbol) & symbol_vars
                            for _, _, _, _, store_data_symbol in store_accesses
                        )
                        if val is None and store_data_only:
                            val = 0
                if (
                    val is None
                    and r not in base_like_regs
                    and has_address_use
                    and not direct_affine_address_base
                    and not fixed_residual_mul_carrier_use
                    and (
                        has_nonadditive_address_use
                        or mul_address_carrier_use
                        or not has_additive_address_use
                    )
                ):
                    write_stage("init:materialize_init:register", reg=r.name, phase="address_scalar_zero_fallback")
                    zero_constraint = symbol == expr_bvv(0, symbol)
                    zero_timeout_ms = max(local_solver_timeout_ms, 5000)
                    if (
                        try_add_constraint_set_fast([zero_constraint], timeout_ms=zero_timeout_ms)
                        or try_add_constraint_set_related(
                            [zero_constraint],
                            symbol_vars,
                            timeout_ms=zero_timeout_ms,
                        )
                    ):
                        val = 0
                    elif (
                        use_static_memory_collection
                        and constraint_set_related_satisfiable(
                            [zero_constraint],
                            symbol_vars,
                            timeout_ms=zero_timeout_ms,
                        ) is True
                    ):
                        candidate_solver.add(zero_constraint)
                        added_constraint_cache.add(str(claripy.simplify(zero_constraint)))
                        debug_constraint_add("address_scalar_zero_fallback_assumed", zero_constraint)
                        val = 0
                if (
                    val is None
                    and r not in base_like_regs
                    and has_address_use
                    and allow_scalar_base_fallback
                ):
                    constrained_address_scalar = any(
                        getattr(constraint, 'variables', set()) & symbol_vars
                        for constraint in candidate_solver.constraints
                    )
                    if constrained_address_scalar:
                        write_stage("init:materialize_init:register", reg=r.name, phase="scalar_base_fallback")
                        val = choose_base_register_value(symbol, INIT_PTR_MIN_OFFSET, fast_anchor=True)
                if (
                    val is None
                    and r not in base_like_regs
                    and not direct_affine_address_base
                ):
                    write_stage("init:materialize_init:register", reg=r.name, phase="scalar_zero_fallback")
                    zero_constraint = symbol == expr_bvv(0, symbol)
                    zero_timeout_ms = max(local_solver_timeout_ms, 5000)
                    zero_added = (
                        try_add_constraint_set_fast([zero_constraint], timeout_ms=zero_timeout_ms)
                        or try_add_constraint_set_related(
                            [zero_constraint],
                            symbol_vars,
                            timeout_ms=zero_timeout_ms,
                        )
                    )
                    if (
                        not zero_added
                        and use_static_memory_collection
                        and constraint_set_related_satisfiable(
                            [zero_constraint],
                            symbol_vars,
                            timeout_ms=zero_timeout_ms,
                        ) is True
                    ):
                        candidate_solver.add(zero_constraint)
                        added_constraint_cache.add(str(claripy.simplify(zero_constraint)))
                        debug_constraint_add("scalar_zero_fallback_assumed", zero_constraint)
                        zero_added = True
                    if zero_added:
                        val = 0
                if val is None and r not in base_like_regs:
                    write_stage("init:materialize_init:register", reg=r.name, phase="scalar_model_fallback")
                    for model_val in solver_eval_current(symbol, n=8, timeout_ms=5000):
                        model_constraint = symbol == expr_bvv(model_val, symbol)
                        model_added = (
                            try_add_constraint_set_fast([model_constraint], timeout_ms=5000)
                            or try_add_constraint_set_related(
                                [model_constraint],
                                symbol_vars,
                                timeout_ms=5000,
                            )
                        )
                        if (
                            not model_added
                            and constraint_set_selection_satisfiable(
                                [model_constraint],
                                timeout_ms=5000,
                            ) is True
                        ):
                            candidate_solver.add(model_constraint)
                            added_constraint_cache.add(str(claripy.simplify(model_constraint)))
                            debug_constraint_add("scalar_model_fallback_assumed", model_constraint)
                            model_added = True
                        if model_added:
                            val = model_val & ((1 << 64) - 1)
                            break
                try:
                    if val is None:
                        val = choose_register_value(symbol, None)
                except AssertionError:
                    write_stage("init:materialize_init:register", reg=r.name, phase="scalar_stack_fallback")
                    fallback_offset = next_free_stack_offset(
                        used_stack_offsets,
                        align=INIT_ACCESS_ALIGN,
                        width=8,
                        start=max(INIT_PTR_MIN_OFFSET, 2048),
                    )
                    if fallback_offset is not None:
                        val = concrete_stack_addr(fallback_offset)
                        if try_add_constraint((init_sp - symbol) == fallback_offset):
                            used_stack_offsets.append((fallback_offset, 8))
                        else:
                            val = None
                    else:
                        val = None
                    if val is None:
                        write_stage("init:materialize_init:register", reg=r.name, phase="scaled_addr_fallback")
                        val = choose_scaled_address_register_value(symbol)
                    if val is None and allow_scalar_base_fallback:
                        val = choose_base_register_value(symbol, INIT_PTR_MIN_OFFSET, fast_anchor=True)
                    if val is None:
                        val = choose_stack_relative_register_value(symbol)
                    if val is None:
                        raise
            write_stage("init:materialize_init:register", reg=r.name, phase="emit")
            runtime_info = pending_reg_runtime_recipes.get(expr_key(symbol))
            runtime_recipe = None
            if runtime_info is not None:
                candidate_recipe = runtime_info['recipe']
                if _runtime_reg_recipe_value(CONCRETE_REPLAY_SP, candidate_recipe) == val:
                    runtime_recipe = candidate_recipe
                    reg_runtime_recipes[r] = candidate_recipe
                    reg_runtime_accesses[r] = runtime_info['accesses']
            append_value_init(
                reg_init,
                r.name,
                val,
                force_affine_quotient=runtime_recipe,
                allow_scaled_stack=True,
            )
            reg_values[r] = val & ((1 << 64) - 1)
            scalar_offset += 8

        def refresh_materialized_register_values():
            refreshed = False
            long_block = len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
            if long_block:
                return refreshed
            refresh_check_timeout_ms = 100 if long_block else max(local_solver_timeout_ms, 1000)
            refresh_eval_timeout_ms = 50 if long_block else 5000
            for reg, old_value in list(reg_values.items()):
                symbol = reg_to_symbol.get(reg)
                if symbol is None:
                    continue
                old_value &= ((1 << 64) - 1)
                old_constraint = symbol == expr_bvv(old_value, symbol)
                if long_block:
                    old_ok = constraint_set_selection_satisfiable(
                        [old_constraint],
                        timeout_ms=refresh_check_timeout_ms,
                    )
                else:
                    old_ok = constraint_set_related_satisfiable(
                        [old_constraint],
                        expr_vars(symbol),
                        timeout_ms=refresh_check_timeout_ms,
                    )
                if old_ok is not False:
                    continue
                new_values = solver_eval_current(symbol, n=1, timeout_ms=refresh_eval_timeout_ms)
                if not new_values:
                    continue
                new_value = new_values[0] & ((1 << 64) - 1)
                new_constraint = symbol == expr_bvv(new_value, symbol)
                if (
                    try_add_constraint_set_fast([new_constraint], timeout_ms=refresh_eval_timeout_ms)
                    or try_add_constraint_set_related(
                        [new_constraint],
                        expr_vars(symbol),
                        timeout_ms=refresh_eval_timeout_ms,
                    )
                ):
                    reg_values[reg] = new_value
                    recipe = reg_runtime_recipes.get(reg)
                    if (
                        recipe is not None
                        and _runtime_reg_recipe_value(CONCRETE_REPLAY_SP, recipe) != new_value
                    ):
                        reg_runtime_recipes.pop(reg, None)
                        reg_runtime_accesses.pop(reg, None)
                    stack_offset = stack_offset_for_value(new_value)
                    if stack_offset is not None and not any(
                        concrete_ranges_overlap(stack_offset, 8, used_offset, used_width)
                        for used_offset, used_width in used_stack_offsets
                    ):
                        used_stack_offsets.append((stack_offset, 8))
                    refreshed = True
                    if verbose:
                        print('refresh_materialized_register', reg.name, hex(old_value), hex(new_value))
            return refreshed

        def rebuild_register_init():
            rebuilt = []
            ordered_regs = [
                reg for reg in regs_undefined
                if reg not in runtime_recipe_temp_regs
            ] + [
                reg for reg in regs_undefined
                if reg in runtime_recipe_temp_regs
            ]
            for reg in ordered_regs:
                if reg not in reg_values:
                    continue
                append_value_init(
                    rebuilt,
                    reg.name,
                    reg_values[reg] & ((1 << 64) - 1),
                    force_affine_quotient=reg_runtime_recipes.get(reg),
                    allow_scaled_stack=True,
                )
            return rebuilt

        for reg in mixed_affine_primary_residual_regs:
            base_like_regs.discard(reg)
            base_like_sources.pop(reg, None)
            reg_min_stack_offsets.pop(reg, None)

        if verbose and mixed_affine_residual_regs:
            print('mixed_affine_residual_regs', [
                str(reg)
                for reg in sorted(mixed_affine_residual_regs, key=lambda item: item.id)
            ])

        for load_inst, loaded_symbol, _, load_idx in load_accesses:
            if load_inst.width != 8:
                continue
            loaded_value_expr = mem_value_expr(load_inst, loaded_symbol)
            if (
                load_value_has_direct_pointer_use(loaded_value_expr, load_idx)
                or load_value_has_direct_store_addr_use(loaded_value_expr, load_idx)
                or not is_deferred_loaded_address_scalar(
                    load_inst,
                    loaded_value_expr,
                    load_idx,
                )
            ):
                continue
            preselected_choice = choose_affine_quotient_loaded_address_value(
                loaded_value_expr,
                load_idx,
                require_explicit_livein_constraints=True,
            )
            if (
                preselected_choice is not None
                and os.environ.get("RVMCA_DEBUG_REPAIR") == "1"
            ):
                DEBUG(f"loaded_affine_quotient_preselected {({
                    'inst_idx': load_idx,
                    'choice': preselected_choice,
                })}")

        ordered_undefined_regs = [
            r for r in regs_undefined
            if r in mixed_affine_residual_regs
        ] + [
            r for r in regs_undefined
            if r in base_like_regs and r not in mixed_affine_residual_regs
        ] + [
            r for r in regs_undefined
            if r not in base_like_regs and r not in mixed_affine_residual_regs
        ]
        for r in ordered_undefined_regs:
            if r in deferred_regs:
                continue
            _write_profile_stage(name, "init:materialize_init:registers")
            materialize_register(r)
            if debug_unsat_stages:
                debug_check_stage(f"register_{r.name}")

        if (
            ENABLE_POINTER_LOAD_ANCHORS
            and len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
            and not address_narrow_source_loads
        ):
            anchored_pointer_load_values = set()
            anchor_candidates = list(pointer_source_loads)
            anchor_candidates = [
                entry for entry in anchor_candidates
                if (entry[3], expr_key(entry[1])) not in scalar_load_hint_keys
            ]
            anchor_candidates.sort(key=lambda item: item[3], reverse=True)
            anchor_candidates = anchor_candidates[:LONG_BLOCK_ANCHOR_CANDIDATE_LIMIT]
            for load_inst, rd_symbol, _, load_idx in anchor_candidates:
                if load_inst.width != 8:
                    continue
                rd_key = expr_key(rd_symbol)
                if rd_key in anchored_pointer_load_values:
                    continue
                anchored_pointer_load_values.add(rd_key)
                offset_expr = init_sp - rd_symbol
                min_offset = _align_up(
                    min_pointer_offset_for_vars(expr_vars(rd_symbol), load_idx),
                    INIT_ACCESS_ALIGN,
                )
                preferred_offset = next_free_stack_offset(
                    used_stack_offsets,
                    align=INIT_ACCESS_ALIGN,
                    width=INIT_ACCESS_SLOT_WIDTH,
                    start=min_offset,
                )
                if preferred_offset is None:
                    continue
                write_stage(
                    "init:materialize_init:pointer_load_anchors",
                    inst_idx=load_idx,
                    phase="choose_value",
                )
                value_offset = None
                candidate_offsets = solver_eval_limited(offset_expr, n=4, timeout_ms=100)
                seen_candidate_offsets = set()
                for candidate_offset in candidate_offsets:
                    candidate_offset &= (1 << 64) - 1
                    if candidate_offset in seen_candidate_offsets:
                        continue
                    seen_candidate_offsets.add(candidate_offset)
                    if candidate_offset <= 0 or candidate_offset > STACK_RANGE:
                        continue
                    if candidate_offset % INIT_ACCESS_ALIGN != 0:
                        continue
                    if any(
                        concrete_ranges_overlap(candidate_offset, 8, used_offset, used_width)
                        for used_offset, used_width in used_stack_offsets
                    ):
                        continue
                    if try_add_constraint(offset_expr == candidate_offset, timeout_ms=100):
                        value_offset = candidate_offset
                        break
                if value_offset is None:
                    continue
                if value_offset is not None and not any(
                    concrete_ranges_overlap(value_offset, 8, used_offset, used_width)
                    for used_offset, used_width in used_stack_offsets
                ):
                    used_stack_offsets.append((value_offset, 8))

        _write_profile_stage(name, "init:materialize_init:load_slots")
        access_ranges = list(reserved_base_access_ranges)
        processed_load_addr_keys = set()
        pointer_source_indices = {
            pointer_idx
            for _, pointer_rd_symbol, _, pointer_idx in pointer_source_loads
            if (pointer_idx, expr_key(pointer_rd_symbol)) not in scalar_load_hint_keys
        }
        load_slot_entries = list(enumerate(mem_entries))
        load_entries_by_idx = {
            entry[3]: entry
            for entry in mem_entries
        }

        def load_value_is_pointer_source_residual_scalar(rd_symbol, load_idx):
            rd_vars = expr_vars(rd_symbol)
            if not rd_vars:
                return False
            current_is_pointer_source = load_idx in pointer_source_indices
            zero_constraints = constraints_to_constant(rd_symbol, 0)
            if zero_constraints is None:
                return False
            related_uses = 0
            for _, addr_symbol, access_idx, _ in mem_accesses:
                if access_idx <= load_idx:
                    continue
                addr_vars = expr_vars(addr_symbol)
                if not (addr_vars & rd_vars):
                    continue
                carried_by_pointer_source = False
                for _, pointer_rd_symbol, _, pointer_idx in pointer_source_loads:
                    if pointer_idx >= access_idx:
                        continue
                    if current_is_pointer_source and pointer_idx <= load_idx:
                        continue
                    pointer_vars = expr_vars(pointer_rd_symbol)
                    if not pointer_vars or pointer_vars & rd_vars:
                        continue
                    if not (addr_vars & pointer_vars):
                        continue
                    residual = sub_same_width(addr_symbol, pointer_rd_symbol)
                    if residual is None:
                        residual = additive_residual_without_term(
                            addr_symbol,
                            pointer_rd_symbol,
                        )
                    if residual is None:
                        continue
                    residual_vars = expr_vars(residual)
                    if residual_vars & pointer_vars:
                        continue
                    if residual_vars & rd_vars:
                        carried_by_pointer_source = True
                        break
                if not carried_by_pointer_source:
                    return False
                related_uses += 1
            if related_uses == 0:
                return False
            return constraint_set_related_satisfiable(
                list(zero_constraints),
                rd_vars,
                timeout_ms=max(local_solver_timeout_ms, 1000),
            ) is not False

        forwarded_store_address_scalar_cache = {}

        def load_value_is_additive_offset_to_live_base(value_expr, producer_idx):
            value_vars = expr_vars(value_expr)
            if not value_vars:
                return False
            debug_additive_offset = os.environ.get("RVMCA_DEBUG_LOAD_SLOTS") == "1"

            def reject_additive_offset(reason, **fields):
                if debug_additive_offset:
                    fields.setdefault('idx', producer_idx)
                    fields.setdefault('value', str(value_expr))
                    DEBUG(f"additive_offset_live_base_reject {reason} {fields}")
                return False

            if (
                (producer_idx, stable_expr_key(value_expr)) in pointer_source_value_keys
                and (producer_idx, stable_expr_key(value_expr)) not in scalar_load_hint_keys
            ):
                return reject_additive_offset("pointer_source_value")

            value_feeds_pointer_chase = False
            for later_inst, later_rd_symbol, later_addr_symbol, later_idx in load_accesses:
                if later_idx <= producer_idx or later_inst.width != 8:
                    continue
                if not (expr_vars(later_addr_symbol) & value_vars):
                    continue
                later_rd_vars = expr_vars(later_rd_symbol)
                if not later_rd_vars:
                    continue
                if any(
                    access_idx > later_idx and (expr_vars(addr_symbol) & later_rd_vars)
                    for _, addr_symbol, access_idx, _ in mem_accesses
                ):
                    value_feeds_pointer_chase = True
                    break
            if value_feeds_pointer_chase:
                return reject_additive_offset(
                    "pointer_chase_source",
                )
            producer_addr_pointer_derived = False
            for load_inst, rd_symbol, load_addr_symbol, load_idx in load_accesses:
                if load_idx != producer_idx:
                    continue
                if expr_key(rd_symbol) != expr_key(value_expr):
                    continue
                producer_addr_pointer_derived = bool(
                    expr_vars(load_addr_symbol)
                    & (pointer_loaded_addr_vars | address_loaded_addr_vars)
                )
                break
            if (
                producer_addr_pointer_derived
                and (
                    load_value_has_direct_pointer_use(value_expr, producer_idx)
                    or load_value_has_direct_store_addr_use(value_expr, producer_idx)
                )
            ):
                return reject_additive_offset(
                    "direct_pointer_or_store_addr_use",
                )

            def additive_terms(expr, sign=1, depth=0):
                expr = claripy.simplify(expr)
                if depth > 12:
                    return [(sign, expr)]
                op = getattr(expr, 'op', '')
                args = [arg for arg in getattr(expr, 'args', ()) if hasattr(arg, 'op')]
                if op in {'__add__', 'Add'}:
                    terms = []
                    for arg in args:
                        terms.extend(additive_terms(arg, sign, depth + 1))
                    return terms
                if op in {'__sub__', 'Sub'} and args:
                    terms = additive_terms(args[0], sign, depth + 1)
                    for arg in args[1:]:
                        terms.extend(additive_terms(arg, -sign, depth + 1))
                    return terms
                if op in {'SignExt', 'ZeroExt'} and args:
                    inner_terms = additive_terms(args[-1], sign, depth + 1)
                    if len(inner_terms) == 1 and inner_terms[0][1] is args[-1]:
                        return [(sign, expr)]
                    return inner_terms
                return [(sign, expr)]

            def residual_without_value_terms(addr_symbol):
                terms = additive_terms(addr_symbol)
                residual_terms = []
                saw_value_term = False
                for sign, term in terms:
                    term_vars = expr_vars(term)
                    if term_vars & value_vars:
                        if sign < 0:
                            return None
                        saw_value_term = True
                        continue
                    residual_terms.append((sign, term))
                if not saw_value_term:
                    return None
                width = addr_symbol.size()
                residual = claripy.BVV(0, width)
                for sign, term in residual_terms:
                    if term.size() != width:
                        return None
                    residual = residual + term if sign > 0 else residual - term
                return claripy.simplify(residual)

            def residual_is_simple_additive(expr, depth=0):
                expr = claripy.simplify(expr)
                if depth > 8:
                    return False
                if not expr_vars(expr):
                    return True
                op = getattr(expr, 'op', '')
                args = [arg for arg in getattr(expr, 'args', ()) if hasattr(arg, 'op')]
                if op == 'BVS':
                    return True
                if op in {'__add__', 'Add', '__sub__', 'Sub'}:
                    return all(residual_is_simple_additive(arg, depth + 1) for arg in args)
                if op in {'SignExt', 'ZeroExt'} and args:
                    return residual_is_simple_additive(args[-1], depth + 1)
                return False

            def residual_has_live_base_candidate(residual_vars, access_idx):
                for reg, reg_symbol in reg_to_symbol.items():
                    reg_vars = expr_vars(reg_symbol)
                    if not reg_vars or not (reg_vars & residual_vars):
                        continue
                    if reg_defined_before_access(reg, access_idx):
                        continue
                    return True
                return False

            saw_address_use = False
            saw_live_base = False
            for _, addr_symbol, access_idx, _ in mem_accesses:
                if access_idx <= producer_idx:
                    continue
                addr_vars = expr_vars(addr_symbol)
                if not (addr_vars & value_vars):
                    continue
                saw_address_use = True
                residual = residual_without_value_terms(addr_symbol)
                if residual is None:
                    residual = sub_same_width(addr_symbol, value_expr)
                if residual is None:
                    residual = claripy.simplify(addr_symbol - value_expr)
                residual_vars = expr_vars(residual)
                if residual_vars & value_vars:
                    return reject_additive_offset(
                        "residual_keeps_value",
                        access_idx=access_idx,
                        addr=str(addr_symbol),
                        residual=str(residual),
                    )
                if not residual_vars:
                    return reject_additive_offset(
                        "residual_concrete",
                        access_idx=access_idx,
                        addr=str(addr_symbol),
                        residual=str(residual),
                    )
                if not residual_is_simple_additive(residual):
                    return reject_additive_offset(
                        "residual_not_simple",
                        access_idx=access_idx,
                        addr=str(addr_symbol),
                        residual=str(residual),
                    )
                if not residual_has_live_base_candidate(residual_vars, access_idx):
                    return reject_additive_offset(
                        "no_live_base",
                        access_idx=access_idx,
                        addr=str(addr_symbol),
                        residual=str(residual),
                        residual_vars=sorted(residual_vars),
                    )
                saw_live_base = True
            if not saw_address_use:
                return reject_additive_offset("no_address_use")
            if not saw_live_base:
                return reject_additive_offset("no_live_base_seen")
            return True

        def load_value_feeds_forwarded_address_scalar(value_expr, producer_idx):
            value_vars = expr_vars(value_expr)
            if not value_vars:
                return False
            cache_key = (producer_idx, stable_expr_key(value_expr))
            if cache_key in forwarded_store_address_scalar_cache:
                return forwarded_store_address_scalar_cache[cache_key]
            debug_store_forward = os.environ.get("RVMCA_DEBUG_STORE_FORWARD") == "1"

            def later_load_is_address_scalar(load_inst, later_rd_symbol, later_idx):
                later_rd_vars = expr_vars(later_rd_symbol)
                if not later_rd_vars:
                    return False
                if later_idx in pointer_source_indices:
                    return False
                if (later_idx, stable_expr_key(later_rd_symbol)) in pointer_source_value_keys:
                    return False
                if load_value_has_direct_pointer_use(later_rd_symbol, later_idx):
                    return False
                if is_loaded_pointer_base_candidate(later_rd_symbol, later_idx):
                    return False
                if (
                    is_scaled_loaded_address_source(load_inst, later_rd_symbol, later_idx)
                    or is_deferred_loaded_address_scalar(load_inst, later_rd_symbol, later_idx)
                    or load_value_is_pointer_source_residual_scalar(later_rd_symbol, later_idx)
                    or load_value_is_additive_offset_to_live_base(later_rd_symbol, later_idx)
                ):
                    return True
                for _, later_addr_symbol, access_idx, _ in mem_accesses:
                    if access_idx <= later_idx:
                        continue
                    if not (expr_vars(later_addr_symbol) & later_rd_vars):
                        continue
                    residual = sub_same_width(later_addr_symbol, later_rd_symbol)
                    if residual is None:
                        residual = claripy.simplify(later_addr_symbol - later_rd_symbol)
                    if expr_vars(residual) & later_rd_vars:
                        return True
                return False

            for _, store_addr_symbol, store_idx, store_width, store_data_symbol in store_accesses:
                if store_idx <= producer_idx:
                    continue
                if store_width < 8:
                    continue
                if not (expr_vars(store_data_symbol) & value_vars):
                    continue
                for load_inst, later_rd_symbol, later_addr_symbol, later_idx in mem_entries:
                    if later_idx <= store_idx:
                        continue
                    if not later_load_is_address_scalar(load_inst, later_rd_symbol, later_idx):
                        continue
                    same_store_load_addr = same_address(
                        store_addr_symbol,
                        later_addr_symbol,
                        allow_solver=False,
                    )
                    if (
                        not same_store_load_addr
                        and len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                    ):
                        same_store_load_addr = forced_same_address_cached(
                            store_addr_symbol,
                            later_addr_symbol,
                        )
                    if debug_store_forward:
                        DEBUG(f"forwarded_store_address_scalar {({
                            'producer_idx': producer_idx,
                            'store_idx': store_idx,
                            'later_idx': later_idx,
                            'later_inst': getattr(load_inst, 'code', str(load_inst)),
                            'same_addr': same_store_load_addr,
                            'value': str(value_expr),
                            'store_data': str(store_data_symbol),
                        })}")
                    if same_store_load_addr:
                        forwarded_store_address_scalar_cache[cache_key] = True
                        return True
            forwarded_store_address_scalar_cache[cache_key] = False
            return False

        def load_slot_entry_pointer_like(entry):
            inst, rd_symbol, _, inst_idx = entry
            rd_vars = expr_vars(rd_symbol)
            if inst.width != 8 or not rd_vars:
                return False
            if load_value_feeds_forwarded_address_scalar(rd_symbol, inst_idx):
                return False
            if load_value_is_additive_offset_to_live_base(rd_symbol, inst_idx):
                return False
            if load_value_is_pointer_source_residual_scalar(rd_symbol, inst_idx):
                return False
            direct_pointer_use = load_value_has_direct_pointer_use(rd_symbol, inst_idx)
            if is_long_block_address_scalar(inst, rd_symbol, inst_idx) and not direct_pointer_use:
                return False
            value_used_later = any(
                later_idx > inst_idx and (expr_vars(later_addr_symbol) & rd_vars)
                for _, later_addr_symbol, later_idx, _ in mem_accesses
            )
            if not value_used_later:
                return False
            return (
                inst_idx in pointer_source_indices
                or (rd_vars & pointer_loaded_addr_vars)
                or (inst_idx, expr_key(rd_symbol)) in hint_pointer_load_keys
                or is_loaded_pointer_base_candidate(rd_symbol, inst_idx)
                or direct_pointer_use
            )

        def load_slot_priority(entry):
            inst, rd_symbol, addr_symbol, inst_idx = entry
            concrete_addr = concrete_value_from_materialized(addr_symbol)
            if concrete_addr is not None:
                concrete_offset = stack_offset_for_value(concrete_addr)
                rd_vars = expr_vars(rd_symbol)
                value_feeds_later_address = bool(rd_vars) and any(
                    later_idx > inst_idx
                    and (expr_vars(later_addr_symbol) & rd_vars)
                    for _, later_addr_symbol, later_idx, _ in mem_accesses
                )
                if (
                    concrete_offset is not None
                    and 0 < concrete_offset <= STACK_RANGE
                    and (inst.width <= 1 or concrete_offset % inst.width == 0)
                    and value_feeds_later_address
                ):
                    return -3
            if inst.width < 8 and is_scalar_zero_address_load(inst, rd_symbol, inst_idx):
                return 0
            if load_slot_entry_pointer_like(entry):
                if retry_index > 0:
                    def rigid_affine_base_producer(candidate_entry):
                        _, _, candidate_addr, candidate_idx = candidate_entry
                        candidate_affine = affine_key(candidate_addr)
                        if (
                            candidate_affine is None
                            or candidate_affine[1] == 0
                            or not (
                                expr_vars(candidate_affine[2])
                                & (pointer_loaded_addr_vars | address_loaded_addr_vars)
                            )
                        ):
                            return None
                        candidate_base_vars = expr_vars(candidate_affine[2])
                        producer = next((
                            producer_entry
                            for producer_entry in mem_entries
                            if producer_entry[3] < candidate_idx
                            and expr_vars(producer_entry[1]) & candidate_base_vars
                        ), None)
                        if (
                            producer is None
                            or expr_vars(producer[2])
                            & (pointer_loaded_addr_vars | address_loaded_addr_vars)
                        ):
                            return None
                        return producer

                    addr_affine = affine_key(addr_symbol)
                    base_vars = expr_vars(addr_affine[2]) if addr_affine is not None else set()
                    base_producer = next((
                        producer_entry
                        for producer_entry in mem_entries
                        if producer_entry[3] < inst_idx
                        and expr_vars(producer_entry[1]) & base_vars
                    ), None)
                    rigid_producer = rigid_affine_base_producer(entry)
                    if rigid_producer is not None:
                        return -2
                    if base_producer is not None:
                        for later_entry in mem_entries:
                            if later_entry[3] <= inst_idx:
                                continue
                            later_producer = rigid_affine_base_producer(later_entry)
                            if later_producer is None:
                                continue
                            if same_address(
                                base_producer[2],
                                later_producer[2],
                                allow_solver=False,
                            ):
                                return -1
                return 0
            if (
                inst.width == 8
                and load_value_feeds_forwarded_address_scalar(rd_symbol, inst_idx)
            ):
                return 1
            if inst_idx in pointer_source_indices:
                return 1
            return 2

        forwarded_store_pointer_cache = {}

        def load_value_feeds_forwarded_pointer_use(value_expr, producer_idx):
            value_vars = expr_vars(value_expr)
            if not value_vars:
                return False
            cache_key = (producer_idx, stable_expr_key(value_expr))
            if cache_key in forwarded_store_pointer_cache:
                return forwarded_store_pointer_cache[cache_key]
            debug_store_forward = os.environ.get("RVMCA_DEBUG_STORE_FORWARD") == "1"
            for _, store_addr_symbol, store_idx, store_width, store_data_symbol in store_accesses:
                if store_idx <= producer_idx:
                    continue
                if store_width < 8:
                    continue
                if not (expr_vars(store_data_symbol) & value_vars):
                    continue
                if debug_store_forward:
                    DEBUG(f"forwarded_store_candidate {({
                        'producer_idx': producer_idx,
                        'value': str(value_expr),
                        'store_idx': store_idx,
                        'store_addr': str(store_addr_symbol),
                        'store_data': str(store_data_symbol),
                    })}")
                for load_inst, later_rd_symbol, later_addr_symbol, later_idx in mem_entries:
                    if later_idx <= store_idx:
                        continue
                    later_rd_vars = expr_vars(later_rd_symbol)
                    if not later_rd_vars:
                        continue
                    later_value_used_as_pointer = any(
                        access_idx > later_idx and (expr_vars(access_addr_symbol) & later_rd_vars)
                        for _, access_addr_symbol, access_idx, _ in mem_accesses
                    )
                    if not later_value_used_as_pointer:
                        continue
                    same_store_load_addr = same_address(
                        store_addr_symbol,
                        later_addr_symbol,
                        allow_solver=False,
                    )
                    if (
                        not same_store_load_addr
                        and len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                    ):
                        same_store_load_addr = forced_same_address_cached(
                            store_addr_symbol,
                            later_addr_symbol,
                        )
                    if debug_store_forward:
                        DEBUG(f"forwarded_store_later_load {({
                            'producer_idx': producer_idx,
                            'store_idx': store_idx,
                            'later_idx': later_idx,
                            'later_inst': getattr(load_inst, 'code', str(load_inst)),
                            'later_pointer': later_value_used_as_pointer,
                            'same_addr': same_store_load_addr,
                            'later_addr': str(later_addr_symbol),
                        })}")
                    if same_store_load_addr:
                        forwarded_store_pointer_cache[cache_key] = True
                        return True
            forwarded_store_pointer_cache[cache_key] = False
            return False

        forwarded_pointer_carrier_cache = {}
        forwarded_pointer_carrier_claims = {}
        forwarded_store_required_pointer_vars = set()
        for required_vars in store_pointer_required_varsets:
            forwarded_store_required_pointer_vars.update(required_vars)

        def forwarded_pointer_carrier_constraints(value_expr, producer_idx):
            value_vars = expr_vars(value_expr)
            if not value_vars:
                return None
            cache_key = (producer_idx, stable_expr_key(value_expr))
            if cache_key in forwarded_pointer_carrier_cache:
                cached_options = forwarded_pointer_carrier_cache[cache_key]
                for group_key, constraints in cached_options:
                    claimed_key = forwarded_pointer_carrier_claims.get(group_key)
                    if claimed_key is None or claimed_key == cache_key:
                        return group_key, constraints
                return None
            debug_store_forward = os.environ.get("RVMCA_DEBUG_STORE_FORWARD") == "1"
            options = []
            for _, store_addr_symbol, store_idx, store_width, store_data_symbol in store_accesses:
                if store_idx <= producer_idx or store_width < 8:
                    continue
                if not (expr_vars(store_data_symbol) & value_vars):
                    continue
                carrier_constraints = constraints_to_carrier(store_data_symbol, value_expr)
                if carrier_constraints is None:
                    continue
                for load_inst, later_rd_symbol, later_addr_symbol, later_idx in mem_entries:
                    if later_idx <= store_idx:
                        continue
                    later_rd_vars = expr_vars(later_rd_symbol)
                    if not later_rd_vars:
                        continue
                    later_value_used_as_pointer = any(
                        access_idx > later_idx and (expr_vars(access_addr_symbol) & later_rd_vars)
                        for _, access_addr_symbol, access_idx, _ in mem_accesses
                    )
                    if not later_value_used_as_pointer:
                        continue
                    same_store_load_addr = same_address(
                        store_addr_symbol,
                        later_addr_symbol,
                        allow_solver=False,
                    )
                    if (
                        not same_store_load_addr
                        and len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                    ):
                        same_store_load_addr = forced_same_address_cached(
                            store_addr_symbol,
                            later_addr_symbol,
                        )
                    if not same_store_load_addr:
                        continue
                    min_offset = min_pointer_offset_for_vars(later_rd_vars, later_idx)
                    constraints = list(carrier_constraints)
                    constraints.extend(stack_pointer_constraints_for_expr(value_expr, min_offset))
                    deduped = []
                    seen_constraints = set()
                    for constraint in constraints:
                        constraint_key = str(claripy.simplify(constraint))
                        if constraint_key in seen_constraints:
                            continue
                        seen_constraints.add(constraint_key)
                        deduped.append(constraint)
                    protected_store_vars = forwarded_store_required_pointer_vars - value_vars
                    if protected_store_vars and any(
                        expr_vars(constraint) & protected_store_vars
                        for constraint in deduped
                    ):
                        if debug_store_forward:
                            DEBUG(f"forwarded_pointer_carrier_reject {({
                                'producer_idx': producer_idx,
                                'store_idx': store_idx,
                                'later_idx': later_idx,
                                'value': str(value_expr),
                                'store_data': str(store_data_symbol),
                                'reason': 'protect_store_required_pointer',
                                'protected_vars': sorted(protected_store_vars),
                                'constraints': [str(c) for c in deduped],
                            })}")
                        continue
                    seed_vars = (
                        expr_vars(store_data_symbol)
                        | value_vars
                        | later_rd_vars
                    )
                    sat = constraint_set_related_satisfiable(
                        deduped,
                        seed_vars,
                        timeout_ms=max(local_solver_timeout_ms, 1000),
                    )
                    if sat is False:
                        if debug_store_forward:
                            DEBUG(f"forwarded_pointer_carrier_reject {({
                                'producer_idx': producer_idx,
                                'store_idx': store_idx,
                                'later_idx': later_idx,
                                'value': str(value_expr),
                                'store_data': str(store_data_symbol),
                                'constraints': [str(c) for c in deduped],
                            })}")
                        continue
                    group_key = (store_idx, stable_expr_key(store_data_symbol))
                    claimed_key = forwarded_pointer_carrier_claims.get(group_key)
                    if claimed_key is not None and claimed_key != cache_key:
                        continue
                    options.append((later_idx, len(deduped), group_key, deduped))
                    if debug_store_forward:
                        DEBUG(f"forwarded_pointer_carrier_candidate {({
                            'producer_idx': producer_idx,
                            'store_idx': store_idx,
                            'later_idx': later_idx,
                            'group': group_key,
                            'value': str(value_expr),
                            'store_data': str(store_data_symbol),
                            'constraints': [str(c) for c in deduped],
                            'sat': sat,
                        })}")
            if not options:
                forwarded_pointer_carrier_cache[cache_key] = []
                return None
            options.sort(key=lambda item: (item[0], item[1]))
            cached_options = [(group_key, constraints) for _, _, group_key, constraints in options]
            forwarded_pointer_carrier_cache[cache_key] = cached_options
            for group_key, constraints in cached_options:
                claimed_key = forwarded_pointer_carrier_claims.get(group_key)
                if claimed_key is None or claimed_key == cache_key:
                    return group_key, constraints
            return None

        load_slot_entries.sort(
            key=lambda item: (
                load_slot_priority(item[1]),
                item[0],
            )
        )
        for load_slot_idx, (inst, rd_symbol, addr_symbol, inst_idx) in load_slot_entries:
            rd_vars_for_prune = expr_vars(rd_symbol)
            value_used_later_for_prune = bool(rd_vars_for_prune) and any(
                later_idx > inst_idx and (expr_vars(later_addr_symbol) & rd_vars_for_prune)
                for _, later_addr_symbol, later_idx, _ in mem_accesses
            )
            value_feeds_later_store_addr_for_prune = bool(rd_vars_for_prune) and any(
                store_idx > inst_idx and (expr_vars(store_addr_symbol) & rd_vars_for_prune)
                for _, store_addr_symbol, store_idx, _, _ in store_accesses
            )
            has_prior_store_for_prune = any(
                store_idx < inst_idx
                for _, _, store_idx, _, _ in store_accesses
            )
            has_symbolic_prior_store_for_prune = any(
                store_idx < inst_idx and bool(expr_vars(store_addr_symbol))
                for _, store_addr_symbol, store_idx, _, _ in store_accesses
            )
            value_feeds_forwarded_pointer_for_prune = load_value_feeds_forwarded_pointer_use(
                rd_symbol,
                inst_idx,
            )
            current_forwarded_address_scalar = load_value_feeds_forwarded_address_scalar(
                rd_symbol,
                inst_idx,
            )
            current_additive_offset_scalar = load_value_is_additive_offset_to_live_base(
                rd_symbol,
                inst_idx,
            )
            current_mutated_additive_offset_scalar = (
                current_additive_offset_scalar
                and load_has_same_slot_update_chain(inst, rd_symbol, addr_symbol, inst_idx)
            )
            current_scalar_zero_load = (
                is_scalar_zero_address_load(inst, rd_symbol, inst_idx)
                or current_forwarded_address_scalar
                or current_additive_offset_scalar
            )
            current_pointer_like_load = (
                inst.width == 8
                and not current_forwarded_address_scalar
                and not current_additive_offset_scalar
                and value_used_later_for_prune
                and (
                    not is_long_block_address_scalar(inst, rd_symbol, inst_idx)
                    or load_value_has_direct_pointer_use(rd_symbol, inst_idx)
                )
                and (
                    inst_idx in pointer_source_indices
                    or (rd_vars_for_prune & pointer_loaded_addr_vars)
                    or (inst_idx, expr_key(rd_symbol)) in hint_pointer_load_keys
                    or is_loaded_pointer_base_candidate(rd_symbol, inst_idx)
                    or load_value_has_direct_pointer_use(rd_symbol, inst_idx)
                )
            )
            current_value_feeds_store_addr = load_value_has_direct_store_addr_use(
                rd_symbol,
                inst_idx,
            )
            if os.environ.get("RVMCA_DEBUG_LOAD_SLOTS") == "1" and (current_scalar_zero_load or current_pointer_like_load):
                DEBUG(f"load_slot_class {({
                    'idx': inst_idx,
                    'inst': getattr(inst, 'code', str(inst)),
                    'scalar_zero': current_scalar_zero_load,
                    'forwarded_address_scalar': current_forwarded_address_scalar,
                    'mutated_additive_offset_scalar': current_mutated_additive_offset_scalar,
                    'pointer_like': current_pointer_like_load,
                    'rd': str(rd_symbol),
                    'addr': str(addr_symbol),
                })}")
            load_value_key_for_prune = load_value_identity_key(inst_idx, rd_symbol, addr_symbol)
            force_exact_load_slot = (
                load_value_key_for_prune in required_load_value_keys
                or value_used_later_for_prune
                or value_feeds_forwarded_pointer_for_prune
                or current_forwarded_address_scalar
                or inst.pc in load_nonzero_hints
            )
            if (
                len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
                and not force_exact_load_slot
            ):
                continue
            write_stage(
                "init:materialize_init:load_slots:entry",
                slot=load_slot_idx,
                inst_idx=inst_idx,
                phase="start",
            )
            access_width = inst.width if inst.width > 0 else INIT_ACCESS_SLOT_WIDTH
            addr_expr = init_sp - addr_symbol
            addr_key = expr_key(addr_symbol)
            allowed_pointer_slot_alias_offsets = set()
            prior_forward_store = prior_same_addr_store(addr_symbol, inst_idx, allow_solver=False)
            if prior_forward_store is None and (
                current_pointer_like_load
                or current_scalar_zero_load
                or force_exact_load_slot
            ):
                prior_forward_store = prior_forced_same_addr_store(addr_symbol, inst_idx)
            if add_store_forward_constraints_for_load(
                prior_forward_store,
                addr_symbol,
                inst,
                rd_symbol,
                inst_idx,
            ):
                if os.environ.get("RVMCA_DEBUG_LOAD_SLOTS") == "1":
                    DEBUG(f"load_slot_store_forward {({
                        'idx': inst_idx,
                        'inst': getattr(inst, 'code', str(inst)),
                        'addr': str(addr_symbol),
                    })}")
                continue

            hard_slot_type_load = current_scalar_zero_load or current_pointer_like_load

            def same_address_for_slot_reuse(addr_a, addr_b, timeout_ms=100):
                if same_address(addr_a, addr_b, allow_solver=False):
                    return True
                if not hard_slot_type_load:
                    return False
                if not exprs_may_be_related(addr_a, addr_b):
                    return False
                return solver_same_address(addr_a, addr_b, timeout_ms=timeout_ms)

            def current_addr_aliases_used_offset(used_addr):
                for prior_addr, _, prior_addr_symbol in access_ranges:
                    if prior_addr != used_addr:
                        continue
                    if same_address_for_slot_reuse(addr_symbol, prior_addr_symbol):
                        return True
                return False

            def existing_slot_conflicts_with_current(used_addr):
                if used_addr in allowed_pointer_slot_alias_offsets:
                    return False
                if current_addr_aliases_used_offset(used_addr):
                    return False
                used_word_offset = ((used_addr + 7) // 8) * 8
                used_slot = mem_slot_symbols.get(used_word_offset)
                if used_slot is None:
                    return False
                if current_scalar_zero_load and (
                    used_slot.get('pointer_like')
                    or used_slot.get('must_be_pointer')
                ):
                    return True
                if current_pointer_like_load and used_slot.get('scalar_zero'):
                    return True
                if existing_slot_can_upgrade_for_current(used_addr):
                    return False
                if current_pointer_like_load and (
                    used_slot.get('pointer_like')
                    or used_slot.get('must_be_pointer')
                    or used_slot.get('sp_affine')
                ):
                    return bool(
                        used_slot.get('feeds_store_addr')
                        or current_value_feeds_store_addr
                    )
                if current_pointer_like_load and not (
                    used_slot.get('pointer_like')
                    or used_slot.get('must_be_pointer')
                    or used_slot.get('sp_affine')
                ):
                    return True
                return False

            def existing_slot_can_alias_current(used_addr):
                if not current_scalar_zero_load or current_mutated_additive_offset_scalar:
                    return False
                used_word_offset = ((used_addr + 7) // 8) * 8
                used_slot = mem_slot_symbols.get(used_word_offset)
                if used_slot is None:
                    return False
                return (
                    used_slot.get('scalar_zero')
                    and not used_slot.get('pointer_like')
                    and not used_slot.get('must_be_pointer')
                    and not used_slot.get('sp_affine')
                )

            def existing_slot_can_upgrade_for_current(used_addr):
                if not current_pointer_like_load or access_width != 8:
                    return False
                used_word_offset = ((used_addr + 7) // 8) * 8
                used_slot = mem_slot_symbols.get(used_word_offset)
                if used_slot is None:
                    return len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                return (
                    not used_slot.get('scalar_zero')
                    and not used_slot.get('pointer_like')
                    and not used_slot.get('must_be_pointer')
                    and not used_slot.get('sp_affine')
                )

            def compatible_alias_offsets_for_current(access_width, align):
                if not current_scalar_zero_load:
                    return []
                alias_offsets = []
                seen_alias_offsets = set()
                align = align if align else 1
                for used_addr, _, _ in access_ranges:
                    if not existing_slot_can_alias_current(used_addr):
                        continue
                    used_word_offset = ((used_addr + 7) // 8) * 8
                    for byte_offset in range(0, 8 - access_width + 1):
                        alias_offset = used_word_offset - byte_offset
                        if alias_offset <= 0 or alias_offset > STACK_RANGE:
                            continue
                        if alias_offset % align:
                            continue
                        if alias_offset in seen_alias_offsets:
                            continue
                        if existing_slot_conflicts_with_current(alias_offset):
                            continue
                        seen_alias_offsets.add(alias_offset)
                        alias_offsets.append(alias_offset)
                return alias_offsets

            def projected_future_hard_load_ranges():
                if not (
                    current_scalar_zero_load
                    and not current_pointer_like_load
                    and access_width < 8
                ):
                    return []
                projected = []
                seen_projected = set()
                for future_inst, future_rd_symbol, future_addr_symbol, future_idx in mem_entries:
                    if future_idx <= inst_idx:
                        continue
                    future_scalar_zero = is_scalar_zero_address_load(
                        future_inst,
                        future_rd_symbol,
                        future_idx,
                    )
                    future_pointer_like = load_slot_entry_pointer_like((
                        future_inst,
                        future_rd_symbol,
                        future_addr_symbol,
                        future_idx,
                    ))
                    if not future_pointer_like:
                        continue
                    if same_address_for_slot_reuse(addr_symbol, future_addr_symbol):
                        continue

                    future_offsets = []
                    future_addr_key = expr_key(future_addr_symbol)
                    known_future_offset = addr_expr_offsets.get(future_addr_key)
                    if known_future_offset is not None:
                        future_offsets.append(known_future_offset)
                    future_affine = affine_key(future_addr_symbol)
                    if future_affine is not None:
                        future_base_key, future_imm, future_base = future_affine
                        for future_base_offset in affine_base_offsets_for(
                            future_base_key,
                            future_base,
                        ):
                            future_offsets.append(future_base_offset - future_imm)

                    for future_offset in future_offsets:
                        if future_offset <= 0 or future_offset > STACK_RANGE:
                            continue
                        future_width = (
                            future_inst.width
                            if future_inst.width > 0
                            else INIT_ACCESS_SLOT_WIDTH
                        )
                        if future_width < 8:
                            continue
                        if future_width > 1 and future_offset % future_width:
                            continue
                        key = (
                            future_offset,
                            future_width,
                            future_idx,
                            expr_key(future_addr_symbol),
                        )
                        if key in seen_projected:
                            continue
                        seen_projected.add(key)
                        projected.append((
                            future_offset,
                            future_width,
                            future_addr_symbol,
                            future_idx,
                            "pointer",
                        ))
                return projected

            future_hard_load_ranges = projected_future_hard_load_ranges()

            def candidate_conflicts_with_future_hard_load(candidate_offset):
                for future_offset, future_width, future_addr_symbol, future_idx, future_kind in future_hard_load_ranges:
                    if not concrete_ranges_overlap(
                        candidate_offset,
                        access_width,
                        future_offset,
                        future_width,
                    ):
                        continue
                    if same_address_for_slot_reuse(addr_symbol, future_addr_symbol):
                        continue
                    debug_load_slot_choice(
                        "reject_future_hard_overlap",
                        candidate_offset=candidate_offset,
                        future_idx=future_idx,
                        future_offset=future_offset,
                        future_width=future_width,
                        future_kind=future_kind,
                        future=str(future_addr_symbol),
                    )
                    return True
                return False

            def related_load_is_scalar_zero(related_idx):
                related_entry = load_entries_by_idx.get(related_idx)
                if related_entry is None:
                    return False
                related_inst, related_rd_symbol, _, related_load_idx = related_entry
                return is_scalar_zero_address_load(
                    related_inst,
                    related_rd_symbol,
                    related_load_idx,
                )

            def addr_has_loaded_base_with_residual_scalar(candidate_addr_symbol, scaled_only=False):
                addr_vars = expr_vars(candidate_addr_symbol)
                scaled_residual_ops = {'__lshift__', 'LShR', 'SShR', '__mul__', 'Mul', 'Concat'}
                residual_scalar_vars = set()
                for residual_reg in residual_scalar_regs:
                    residual_symbol = reg_to_symbol.get(residual_reg)
                    if residual_symbol is not None:
                        residual_scalar_vars.update(expr_vars(residual_symbol))
                if not addr_vars:
                    return False
                for _load_inst, loaded_symbol, _load_addr_symbol, _load_idx in load_accesses:
                    if _load_inst.width != 8:
                        continue
                    loaded_vars = expr_vars(loaded_symbol)
                    if not loaded_vars or not (addr_vars & loaded_vars):
                        continue
                    residual = additive_residual_without_term(
                        candidate_addr_symbol,
                        loaded_symbol,
                    )
                    if residual is None:
                        residual = claripy.simplify(candidate_addr_symbol - loaded_symbol)
                    residual_vars = expr_vars(residual)
                    if residual_vars & loaded_vars:
                        continue
                    residual_value = concrete_expr_value(residual)
                    if (
                        not scaled_only
                        and residual_value is not None
                        and abs(_signed_u64(residual_value)) <= 64
                        and is_loaded_pointer_base_candidate(loaded_symbol, _load_idx)
                    ):
                        return True
                    has_scaled_residual = any(
                        getattr(node, 'op', None) in scaled_residual_ops
                        and (expr_vars(node) & residual_vars)
                        for node in iter_ast_nodes(residual)
                    )
                    if has_scaled_residual:
                        base_like_residual_vars = (
                            set(pointer_loaded_addr_vars)
                        )
                        residual_constraints = constraints_to_constant(
                            residual,
                            0,
                            forbidden_vars=loaded_vars | base_like_residual_vars,
                        )
                        if residual_constraints is None:
                            residual_constraints = multiplicative_zero_residual_constraints(
                                residual,
                                forbidden_vars=loaded_vars | base_like_residual_vars,
                                direct_pointer_guard=True,
                                timeout_ms=100 if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD else 1000,
                            )
                        if os.environ.get("RVMCA_DEBUG_LOAD_SLOTS") == "1":
                            DEBUG(f"loaded_residual_class_scaled {({
                                'addr': str(candidate_addr_symbol),
                                'loaded': str(loaded_symbol),
                                'residual': str(residual),
                                'residual_vars': sorted(residual_vars),
                                'base_like_vars': sorted(residual_vars & base_like_residual_vars),
                                'constraints': None if residual_constraints is None else len(residual_constraints),
                            })}")
                        if residual_constraints is not None:
                            return True
                        continue
                    if scaled_only:
                        continue
                    if residual_vars & residual_scalar_vars:
                        return True
                return False

            def zeroable_scaled_loaded_source_offsets(candidate_addr_symbol):
                addr_vars = expr_vars(candidate_addr_symbol)
                if not addr_vars:
                    return []
                scaled_residual_ops = {'__lshift__', 'LShR', 'SShR', '__mul__', 'Mul', 'Concat'}
                source_offsets = []
                for _load_inst, loaded_symbol, load_addr_symbol, _load_idx in load_accesses:
                    if _load_inst.width != 8:
                        continue
                    loaded_vars = expr_vars(loaded_symbol)
                    if not loaded_vars or not (addr_vars & loaded_vars):
                        continue
                    residual = additive_residual_without_term(
                        candidate_addr_symbol,
                        loaded_symbol,
                    )
                    if residual is None:
                        residual = claripy.simplify(candidate_addr_symbol - loaded_symbol)
                    residual_vars = expr_vars(residual)
                    if residual_vars & loaded_vars:
                        continue
                    if not any(
                        getattr(node, 'op', None) in scaled_residual_ops
                        and (expr_vars(node) & residual_vars)
                        for node in iter_ast_nodes(residual)
                    ):
                        continue
                    residual_constraints = constraints_to_constant(
                        residual,
                        0,
                        forbidden_vars=loaded_vars | set(pointer_loaded_addr_vars),
                    )
                    if residual_constraints is None:
                        residual_constraints = multiplicative_zero_residual_constraints(
                            residual,
                            forbidden_vars=loaded_vars | set(pointer_loaded_addr_vars),
                            direct_pointer_guard=True,
                            timeout_ms=100 if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD else 1000,
                        )
                    if residual_constraints is None:
                        continue
                    source_offset = addr_expr_offsets.get(expr_key(load_addr_symbol))
                    if source_offset is not None:
                        source_offsets.append(source_offset)
                return source_offsets

            debug_load_slots = os.environ.get("RVMCA_DEBUG_LOAD_SLOTS") == "1"

            def debug_load_slot_choice(event, **fields):
                if debug_load_slots and (current_scalar_zero_load or current_pointer_like_load):
                    fields.setdefault('idx', inst_idx)
                    fields.setdefault('inst', getattr(inst, 'code', str(inst)))
                    fields.setdefault('addr', str(addr_symbol))
                    DEBUG(f"load_slot_choice_{event} {fields}")

            def concrete_stack_offset_for_addr_expr(candidate_addr_symbol):
                concrete_addr = concrete_value_from_materialized(candidate_addr_symbol)
                if concrete_addr is not None:
                    concrete_offset = stack_offset_for_value(concrete_addr)
                    if concrete_offset is not None:
                        return concrete_offset
                offset_expr = claripy.simplify(init_sp - candidate_addr_symbol)
                concrete_offset = concrete_value_from_materialized(offset_expr)
                if concrete_offset is not None:
                    return concrete_offset & ((1 << 64) - 1)
                values = solver_eval_limited(
                    offset_expr,
                    n=2,
                    timeout_ms=100 if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD else 1000,
                )
                normalized = []
                seen_values = set()
                for value in values:
                    value &= ((1 << 64) - 1)
                    if value in seen_values:
                        continue
                    seen_values.add(value)
                    normalized.append(value)
                if len(normalized) == 1:
                    offset_value = normalized[0]
                    offset_forced = constraint_set_related_satisfiable(
                        [offset_expr != expr_bvv(offset_value, offset_expr)],
                        expr_vars(offset_expr),
                        timeout_ms=100 if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD else 1000,
                    )
                    if offset_forced is False:
                        return offset_value
                return None

            prior_store_avoid_ranges = []
            for store_inst, store_addr_symbol, store_idx, store_width, _ in store_accesses:
                if store_idx >= inst_idx:
                    continue
                if same_address(store_addr_symbol, addr_symbol, allow_solver=False):
                    continue
                store_offset = concrete_stack_offset_for_addr_expr(store_addr_symbol)
                if store_offset is None or store_offset <= 0 or store_offset > STACK_RANGE:
                    continue
                prior_store_avoid_ranges.append((
                    store_offset,
                    store_width,
                    store_addr_symbol,
                    getattr(store_inst, 'code', str(store_inst)),
                ))

            def prior_store_conflicts_with_current(candidate_offset):
                def move_symbolic_prior_store_away(store_addr_symbol, store_offset, store_width):
                    if not hard_slot_type_load:
                        return False
                    store_vars = expr_vars(store_addr_symbol)
                    if not store_vars:
                        return False
                    store_offset_expr = claripy.simplify(init_sp - store_addr_symbol)
                    if not expr_vars(store_offset_expr):
                        return False
                    current_offset = expr_bvv(candidate_offset, store_offset_expr)
                    current_lo = expr_bvv(candidate_offset - (access_width - 1), store_offset_expr)
                    store_lo = store_offset_expr - (store_width - 1)
                    constraints = [
                        claripy.Or(
                            claripy.ULT(store_offset_expr, current_lo),
                            claripy.ULT(current_offset, store_lo),
                        )
                    ]
                    if (
                        try_add_constraint_set_fast(constraints, timeout_ms=100)
                        or try_add_constraint_set_related(
                            constraints,
                            store_vars | expr_vars(store_offset_expr),
                            timeout_ms=1000,
                        )
                    ):
                        debug_load_slot_choice(
                            "move_prior_store_overlap",
                            candidate_offset=candidate_offset,
                            store_offset=store_offset,
                            store_width=store_width,
                            store_addr=str(store_addr_symbol),
                        )
                        return True
                    if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD:
                        sat = constraint_set_related_satisfiable(
                            constraints,
                            store_vars | expr_vars(store_offset_expr),
                            timeout_ms=1000,
                        )
                        if sat is not False:
                            for constraint in constraints:
                                candidate_solver.add(constraint)
                                added_constraint_cache.add(str(claripy.simplify(constraint)))
                                debug_constraint_add("prior_store_overlap_moved", constraint)
                            debug_load_slot_choice(
                                "assume_move_prior_store_overlap",
                                candidate_offset=candidate_offset,
                                store_offset=store_offset,
                                store_width=store_width,
                                store_addr=str(store_addr_symbol),
                            )
                            return True
                    return False

                for store_offset, store_width, store_addr_symbol, store_code in prior_store_avoid_ranges:
                    if not concrete_ranges_overlap(
                        candidate_offset,
                        access_width,
                        store_offset,
                        store_width,
                    ):
                        continue
                    if same_address(addr_symbol, store_addr_symbol, allow_solver=False):
                        continue
                    if move_symbolic_prior_store_away(
                        store_addr_symbol,
                        store_offset,
                        store_width,
                    ):
                        continue
                    debug_load_slot_choice(
                        "reject_prior_store_overlap",
                        candidate_offset=candidate_offset,
                        store_offset=store_offset,
                        store_width=store_width,
                        store=store_code,
                        store_addr=str(store_addr_symbol),
                    )
                    return True
                return False

            def same_slot_value_must_alias(word_offset, byte_offset):
                if inst.width != 8 or byte_offset != 0:
                    return False
                for known_addr, known_idx in mem_offset_addr_entries.get(word_offset, []):
                    cheap_same = same_address(addr_symbol, known_addr, allow_solver=False)
                    solver_same = False
                    if not cheap_same:
                        solver_same = same_address_for_slot_reuse(addr_symbol, known_addr)
                    if not (cheap_same or solver_same):
                        continue
                    prev_idx = min(inst_idx, known_idx)
                    next_idx = max(inst_idx, known_idx)
                    if has_intervening_same_addr_store(
                        addr_symbol,
                        prev_idx,
                        next_idx,
                        allow_solver=bool(solver_same),
                    ):
                        continue
                    return True
                return False

            def slot_has_same_address(word_offset, candidate_addr_symbol):
                known_addrs = list(mem_offset_addr_symbols.get(word_offset, []))
                known_addrs.extend(
                    known_addr
                    for known_addr, _ in mem_offset_addr_entries.get(word_offset, [])
                )
                for known_addr in known_addrs:
                    if same_address(candidate_addr_symbol, known_addr, allow_solver=False):
                        return True
                    if (
                        hard_slot_type_load
                        and exprs_may_be_related(candidate_addr_symbol, known_addr)
                        and solver_same_address(
                            candidate_addr_symbol,
                            known_addr,
                            timeout_ms=100,
                        )
                    ):
                        return True
                return False

            def future_load_slot_reuse_constraints(
                candidate_offset,
                related_addr_symbol,
                related_idx,
                related_width,
            ):
                if (
                    related_idx == inst_idx
                    or related_idx not in load_entries_by_idx
                    or related_width != inst.width
                    or not same_address_for_slot_reuse(
                        addr_symbol,
                        related_addr_symbol,
                        timeout_ms=1000,
                    )
                ):
                    return None

                candidate_constraint = addr_expr == expr_bvv(
                    candidate_offset,
                    addr_expr,
                )
                no_clobber_constraints = []
                first_idx = min(inst_idx, related_idx)
                last_idx = max(inst_idx, related_idx)
                for _, store_addr_symbol, store_idx, store_width, _ in store_accesses:
                    if not (first_idx < store_idx < last_idx):
                        continue
                    byte_aliases = [
                        addr_symbol + load_byte == store_addr_symbol + store_byte
                        for load_byte in range(access_width)
                        for store_byte in range(store_width)
                    ]
                    if not byte_aliases:
                        continue
                    no_clobber_constraints.append(
                        claripy.Not(claripy.Or(*byte_aliases))
                    )
                test_solver = candidate_solver.branch()
                test_solver.timeout = 1000
                try:
                    test_solver.add(candidate_constraint)
                    for constraint in no_clobber_constraints:
                        test_solver.add(constraint)
                    if not test_solver.satisfiable():
                        return None
                except Exception:
                    return None
                return no_clobber_constraints

            def candidate_keeps_affine_group_available(
                candidate_offset,
                slot_reuse_constraints,
            ):
                if not (current_scalar_zero_load or current_pointer_like_load):
                    return True
                current_affine = affine_key(addr_symbol)
                if current_affine is None:
                    return True
                base_key, current_imm, base = current_affine
                base_vars = expr_vars(base)
                if not (base_vars & (pointer_loaded_addr_vars | address_loaded_addr_vars)):
                    return True
                base_offset = candidate_offset + current_imm
                if base_offset <= 0 or base_offset > STACK_RANGE:
                    debug_load_slot_choice(
                        "reject_group_base_range",
                        candidate_offset=candidate_offset,
                        base_offset=base_offset,
                        imm=current_imm,
                        base=str(base),
                    )
                    return False
                for related_inst, related_addr_symbol, related_idx, related_width in mem_accesses:
                    if related_idx == inst_idx:
                        continue
                    related_affine = affine_key(related_addr_symbol)
                    if related_affine is None:
                        continue
                    related_base_key, related_imm, _ = related_affine
                    if related_base_key != base_key:
                        continue
                    related_offset = base_offset - related_imm
                    if related_offset <= 0 or related_offset > STACK_RANGE:
                        debug_load_slot_choice(
                            "reject_group_range",
                            candidate_offset=candidate_offset,
                            related_idx=related_idx,
                            related_offset=related_offset,
                            related=str(related_addr_symbol),
                        )
                        return False
                    if related_width > 1 and related_offset % related_width:
                        debug_load_slot_choice(
                            "reject_group_align",
                            candidate_offset=candidate_offset,
                            related_idx=related_idx,
                            related_offset=related_offset,
                            related_width=related_width,
                            related=str(related_addr_symbol),
                        )
                        return False
                    reuse_constraints = future_load_slot_reuse_constraints(
                        candidate_offset,
                        related_addr_symbol,
                        related_idx,
                        related_width,
                    )
                    if reuse_constraints is not None:
                        known_constraints = {
                            str(claripy.simplify(constraint))
                            for constraint in slot_reuse_constraints
                        }
                        for constraint in reuse_constraints:
                            constraint_key = str(claripy.simplify(constraint))
                            if constraint_key in known_constraints:
                                continue
                            known_constraints.add(constraint_key)
                            slot_reuse_constraints.append(constraint)
                        continue
                    related_scalar_zero = related_load_is_scalar_zero(related_idx)
                    related_entry = load_entries_by_idx.get(related_idx)
                    related_pointer_like = (
                        related_entry is not None
                        and load_slot_entry_pointer_like(related_entry)
                    )
                    related_slot_width = init_slot_width(related_width)
                    related_word_offset = ((related_offset + 7) // 8) * 8
                    related_slot = mem_slot_symbols.get(related_word_offset)
                    if related_slot is not None:
                        related_slot_alias = slot_has_same_address(
                            related_word_offset,
                            related_addr_symbol,
                        )
                        if (
                            not related_slot_alias
                            and
                            (
                                related_slot.get('pointer_like')
                                or related_slot.get('must_be_pointer')
                                or related_slot.get('sp_affine')
                            )
                            and not related_pointer_like
                        ):
                            debug_load_slot_choice(
                                "reject_group_slot_type",
                                candidate_offset=candidate_offset,
                                related_idx=related_idx,
                                related_offset=related_offset,
                                word_offset=related_word_offset,
                                related=str(related_addr_symbol),
                            )
                            return False
                        if (
                            not related_slot_alias
                            and related_slot.get('scalar_zero')
                            and not related_scalar_zero
                        ):
                            debug_load_slot_choice(
                                "reject_group_scalar_alias",
                                candidate_offset=candidate_offset,
                                related_idx=related_idx,
                                related_offset=related_offset,
                                word_offset=related_word_offset,
                                related=str(related_addr_symbol),
                            )
                            return False
                    for used_addr, used_width, used_addr_symbol in access_ranges:
                        if not concrete_ranges_overlap(
                            related_offset,
                            related_slot_width,
                            used_addr,
                            used_width,
                        ):
                            continue
                        overlap_same_address = same_address(
                            related_addr_symbol,
                            used_addr_symbol,
                            allow_solver=False,
                        )
                        if (
                            not overlap_same_address
                            and hard_slot_type_load
                            and exprs_may_be_related(related_addr_symbol, used_addr_symbol)
                        ):
                            overlap_same_address = solver_same_address(
                                related_addr_symbol,
                                used_addr_symbol,
                                timeout_ms=100,
                            )
                        if overlap_same_address:
                            continue
                        if related_scalar_zero and existing_slot_can_alias_current(used_addr):
                            continue
                        debug_load_slot_choice(
                            "reject_group_overlap",
                            candidate_offset=candidate_offset,
                            related_idx=related_idx,
                            related_offset=related_offset,
                            used_addr=used_addr,
                            used_width=used_width,
                            used=str(used_addr_symbol),
                            related=str(related_addr_symbol),
                        )
                        return False
                return True

            low_guard_reuse_proven_offsets = set()

            def low_guard_prior_store_conflict(addr, slot_reuse_constraints=None):
                def prior_store_may_clobber_current_slot():
                    for store_offset, store_width, store_addr_symbol, _ in prior_store_avoid_ranges:
                        if not concrete_ranges_overlap(
                            addr,
                            access_width,
                            store_offset,
                            init_slot_width(store_width),
                        ):
                            continue
                        if same_address(addr_symbol, store_addr_symbol, allow_solver=False):
                            continue
                        debug_load_slot_choice(
                            "low_guard_prior_store_overlap",
                            candidate_offset=addr,
                            store_offset=store_offset,
                            store_width=store_width,
                            store_addr=str(store_addr_symbol),
                        )
                        return True
                    for _, store_addr_symbol, store_idx, store_width, _ in store_accesses:
                        if store_idx >= inst_idx:
                            continue
                        if same_address(addr_symbol, store_addr_symbol, allow_solver=False):
                            continue
                        store_offset = concrete_stack_offset_for_addr_expr(store_addr_symbol)
                        if store_offset is not None:
                            continue
                        if exprs_may_be_related(addr_symbol, store_addr_symbol):
                            debug_load_slot_choice(
                                "low_guard_related_prior_store",
                                candidate_offset=addr,
                                store_idx=store_idx,
                                store_width=store_width,
                                store_addr=str(store_addr_symbol),
                            )
                            return True
                    return False

                def future_same_addr_reused_after_store():
                    if addr in low_guard_reuse_proven_offsets:
                        return False
                    for _, future_addr_symbol, future_idx, future_width in mem_accesses:
                        if future_idx <= inst_idx or future_width != inst.width:
                            continue
                        if not any(inst_idx < store_idx < future_idx for _, _, store_idx, _, _ in store_accesses):
                            continue
                        same_future_addr = same_address(
                            addr_symbol,
                            future_addr_symbol,
                            allow_solver=False,
                        )
                        if not same_future_addr:
                            same_future_addr = (
                                affine_same_or_distinct(
                                    addr_symbol,
                                    future_addr_symbol,
                                )
                                is True
                            )
                        if (
                            not same_future_addr
                            and hard_slot_type_load
                            and exprs_may_be_related(addr_symbol, future_addr_symbol)
                            and solver_same_address(
                                addr_symbol,
                                future_addr_symbol,
                                timeout_ms=100,
                            )
                        ):
                            same_future_addr = True
                        if not same_future_addr:
                            continue
                        reuse_constraints = None
                        if slot_reuse_constraints is not None:
                            reuse_constraints = future_load_slot_reuse_constraints(
                                addr,
                                future_addr_symbol,
                                future_idx,
                                future_width,
                            )
                        if reuse_constraints is not None:
                            known_constraints = {
                                str(claripy.simplify(constraint))
                                for constraint in slot_reuse_constraints
                            }
                            for constraint in reuse_constraints:
                                constraint_key = str(claripy.simplify(constraint))
                                if constraint_key in known_constraints:
                                    continue
                                known_constraints.add(constraint_key)
                                slot_reuse_constraints.append(constraint)
                            debug_load_slot_choice(
                                "allow_low_guard_repeated_store_no_overlap",
                                candidate_offset=addr,
                                future_idx=future_idx,
                                future_addr=str(future_addr_symbol),
                            )
                            continue
                        debug_load_slot_choice(
                            "low_guard_repeated_after_store",
                            candidate_offset=addr,
                            future_idx=future_idx,
                            future_addr=str(future_addr_symbol),
                        )
                        return True
                    return False

                return (
                    len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                    and inst.width == 8
                    and addr > STACK_RANGE - LIVEIN_STORE_LOW_GUARD_OFFSET
                    and (
                        prior_store_may_clobber_current_slot()
                        or (
                            current_pointer_like_load
                            and future_same_addr_reused_after_store()
                        )
                    )
                )

            def choose_low_guard_fallback_addr():
                guard_limit = STACK_RANGE - LIVEIN_STORE_LOW_GUARD_OFFSET
                align = inst.width if inst.width > 1 else 1
                width = access_width
                try:
                    local_avoid_ranges = list(avoid_ranges)
                except NameError:
                    local_avoid_ranges = []
                start = align
                attempts = 0
                while attempts < 64:
                    fallback_offset = next_free_stack_offset(
                        local_avoid_ranges,
                        align=align,
                        width=width,
                        start=start,
                    )
                    if fallback_offset is None or fallback_offset > guard_limit:
                        return None
                    attempts += 1
                    if not existing_slot_conflicts_with_current(fallback_offset) and (
                        try_add_constraint_set_fast([addr_expr == fallback_offset], timeout_ms=100)
                        or try_add_constraint_set_related(
                            [addr_expr == fallback_offset],
                            expr_vars(addr_expr),
                            timeout_ms=1000,
                        )
                    ):
                        debug_load_slot_choice(
                            "low_guard_fallback",
                            candidate_offset=fallback_offset,
                            guard=LIVEIN_STORE_LOW_GUARD_OFFSET,
                        )
                        return fallback_offset
                    local_avoid_ranges.append((fallback_offset, width))
                    start = fallback_offset + align
                return None

            def commit_load_addr_constraint(addr, timeout_ms=None):
                def remember_committed_addr_offset():
                    low_guard_reuse_proven_offsets.add(addr)
                    remember_equiv_base_offset(addr_symbol, addr)
                    addr_affine = affine_key(addr_symbol)
                    if addr_affine is not None:
                        base_key, imm, base = addr_affine
                        remember_affine_base_offset(base_key, base, addr + imm)
                        remember_equiv_base_offset(base, addr + imm)

                try:
                    quotient_avoid_ranges = avoid_ranges
                except NameError:
                    quotient_avoid_ranges = ()
                if not fixed_sp_affine_quotient_compatible(
                    addr_symbol,
                    addr,
                    access_width,
                    quotient_avoid_ranges,
                ):
                    debug_load_slot_choice(
                        "reject_affine_quotient_inexact",
                        candidate_offset=addr,
                    )
                    return False
                slot_reuse_constraints = []
                if low_guard_prior_store_conflict(addr, slot_reuse_constraints):
                    debug_load_slot_choice(
                        "reject_low_guard_prior_store",
                        candidate_offset=addr,
                        guard=LIVEIN_STORE_LOW_GUARD_OFFSET,
                    )
                    return False
                if prior_store_conflicts_with_current(addr):
                    return False
                if candidate_conflicts_with_future_hard_load(addr):
                    return False
                if hard_slot_type_load and existing_slot_conflicts_with_current(addr):
                    debug_load_slot_choice("reject_slot_conflict", candidate_offset=addr)
                    return False
                if not candidate_keeps_affine_group_available(
                    addr,
                    slot_reuse_constraints,
                ):
                    return False
                constraint = addr_expr == claripy.BVV(
                    addr & ((1 << addr_expr.size()) - 1),
                    addr_expr.size(),
                )
                commit_constraints = [constraint] + slot_reuse_constraints
                slot_value_equalities = []
                word_offset = ((addr + 7) // 8) * 8
                byte_offset = word_offset - addr
                existing_slot = mem_slot_symbols.get(word_offset)
                if (
                    existing_slot is not None
                    and inst.width == 8
                    and byte_offset == 0
                ):
                    must_alias_same_slot_value = same_slot_value_must_alias(
                        word_offset,
                        byte_offset,
                    )
                    current_value_expr = mem_value_expr(inst, rd_symbol)
                    prior_value_exprs = []
                    if 'direct_value_expr' in existing_slot:
                        prior_value_exprs.append(existing_slot['direct_value_expr'])
                    prior_value_exprs.extend(existing_slot.get('value_exprs', []))
                    for prior_value_expr in prior_value_exprs:
                        equality_constraint = current_value_expr == prior_value_expr
                        commit_constraints.append(equality_constraint)
                        slot_value_equalities.append((current_value_expr, prior_value_expr))
                    if slot_value_equalities:
                        commit_constraints.extend(
                            load_value_derived_access_range_constraints(
                                current_value_expr,
                                inst_idx,
                                avoid_existing_load_slots=not must_alias_same_slot_value,
                                candidate_constraints=commit_constraints,
                            )
                        )
                timeout_ms = (
                    1000
                    if timeout_ms is None and len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                    else (local_solver_timeout_ms if timeout_ms is None else timeout_ms)
                )
                if try_add_constraint_set_fast(commit_constraints, timeout_ms=timeout_ms):
                    for current_value_expr, prior_value_expr in slot_value_equalities:
                        register_expr_equality(current_value_expr, prior_value_expr)
                    remember_committed_addr_offset()
                    debug_load_slot_choice("commit_fast", candidate_offset=addr)
                    return True
                if slot_value_equalities:
                    if os.environ.get("RVMCA_DEBUG_LOAD_SLOTS") == "1":
                        DEBUG(f"load_slot_reject_value_conflict {({
                            'idx': inst_idx,
                            'inst': getattr(inst, 'code', str(inst)),
                            'candidate_offset': addr,
                            'word_offset': word_offset,
                            'current': str(slot_value_equalities[0][0]),
                            'prior': [str(prior) for _, prior in slot_value_equalities],
                        })}")
                    return False
                if (
                    len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                    and not force_exact_load_slot
                ):
                    debug_load_slot_choice("reject_fast_unsat", candidate_offset=addr)
                    return False
                related_ok = try_add_constraint_set_related(
                    commit_constraints,
                    expr_vars(addr_expr),
                    timeout_ms=max(timeout_ms, 1000),
                )
                if (
                    not related_ok
                    and os.environ.get("RVMCA_DEBUG_LOAD_SLOTS") == "1"
                    and (current_scalar_zero_load or current_pointer_like_load)
                ):
                    debug_values = solver_eval_limited(
                        addr_expr,
                        n=4,
                        timeout_ms=max(timeout_ms, 1000),
                    )
                    debug_load_slot_choice(
                        "reject_related_detail",
                        candidate_offset=addr,
                        values=[hex(value & ((1 << 64) - 1)) for value in debug_values],
                        vars=sorted(expr_vars(addr_expr)),
                    )
                debug_load_slot_choice(
                    "commit_related" if related_ok else "reject_related_unsat",
                    candidate_offset=addr,
                )
                if related_ok:
                    remember_committed_addr_offset()
                return related_ok

            duplicate_load_addr = addr_key in processed_load_addr_keys
            if addr_key in processed_load_addr_keys:
                if addr_key in addr_expr_offsets:
                    addr = addr_expr_offsets[addr_key]
                    if not commit_load_addr_constraint(addr):
                        if (
                            len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                            and not force_exact_load_slot
                        ):
                            continue
                        duplicate_load_addr = False
                        addr_expr_offsets.pop(addr_key, None)
                else:
                    duplicate_load_addr = False
            if addr_key in addr_expr_offsets:
                addr = addr_expr_offsets[addr_key]
                if not commit_load_addr_constraint(addr):
                    if (
                        len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                        and not force_exact_load_slot
                    ):
                        continue
                    addr_expr_offsets.pop(addr_key, None)
                    duplicate_load_addr = False
                else:
                    pass
            if addr_key not in addr_expr_offsets:
                addr = None
            if addr is not None:
                pass
            else:
                prefer_pointer_load_addr_solver = addr_has_loaded_base_with_residual_scalar(addr_symbol)
                if hard_slot_type_load:
                    forced_offset = concrete_stack_offset_for_addr_expr(addr_symbol)
                    if (
                        forced_offset is not None
                        and forced_offset > 0
                        and forced_offset <= STACK_RANGE
                        and (inst.width <= 1 or forced_offset % inst.width == 0)
                        and commit_load_addr_constraint(forced_offset, timeout_ms=1000)
                    ):
                        addr = forced_offset
                        addr_expr_offsets[addr_key] = addr
                        debug_load_slot_choice(
                            "commit_forced_offset",
                            candidate_offset=addr,
                        )
                    if addr is None:
                        seen_eval_offsets = set()
                        for eval_offset in solver_eval_limited(
                            addr_expr,
                            n=4,
                            timeout_ms=1000 if len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD else 1000,
                        ):
                            eval_offset &= ((1 << addr_expr.size()) - 1)
                            if eval_offset in seen_eval_offsets:
                                continue
                            seen_eval_offsets.add(eval_offset)
                            if eval_offset <= 0 or eval_offset > STACK_RANGE:
                                continue
                            if inst.width > 1 and eval_offset % inst.width:
                                continue
                            if not any(
                                concrete_ranges_overlap(
                                    eval_offset,
                                    access_width,
                                    used_addr,
                                    used_width,
                                )
                                for used_addr, used_width, _ in access_ranges
                            ):
                                continue
                            if (
                                current_pointer_like_load
                                and not current_addr_aliases_used_offset(eval_offset)
                            ):
                                continue
                            if commit_load_addr_constraint(eval_offset, timeout_ms=1000):
                                addr = eval_offset
                                addr_expr_offsets[addr_key] = addr
                                debug_load_slot_choice(
                                    "commit_eval_offset",
                                    candidate_offset=addr,
                                )
                                break
                if addr is not None:
                    pass
                else:
                    write_stage(
                        "init:materialize_init:load_slots:entry",
                        slot=load_slot_idx,
                        inst_idx=inst_idx,
                        phase="same_addr_scan",
                    )
                    prefer_pointer_load_addr_solver = addr_has_loaded_base_with_residual_scalar(addr_symbol)
                    scaled_loaded_source_offsets = zeroable_scaled_loaded_source_offsets(addr_symbol)
                    same_addr_offset = None
                    same_addr_solver_budget = (
                        (
                            12
                            if prefer_pointer_load_addr_solver
                            else 2
                        )
                        if len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
                        else None
                    )
                    same_addr_solver_checks = 0
                    skip_same_addr_scan = (
                        len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
                        and ast_node_count(addr_symbol) > 64
                    )
                    if not skip_same_addr_scan:
                        for used_addr, _, used_addr_symbol in access_ranges:
                            affine_same = affine_same_or_distinct(addr_symbol, used_addr_symbol)
                            cheap_same = same_address(addr_symbol, used_addr_symbol, allow_solver=False)
                            solver_same = False
                            if (
                                hard_slot_type_load
                                and not cheap_same
                                and affine_same is None
                                and exprs_may_be_related(addr_symbol, used_addr_symbol)
                                and (
                                    same_addr_solver_budget is None
                                    or same_addr_solver_checks < same_addr_solver_budget
                                )
                            ):
                                same_addr_solver_checks += 1
                                solver_same = solver_same_address(
                                    addr_symbol,
                                    used_addr_symbol,
                                    timeout_ms=50 if same_addr_solver_budget is not None else 1000,
                                )
                            if (
                                cheap_same
                                or affine_same is True
                                or solver_same
                            ):
                                if existing_slot_conflicts_with_current(used_addr):
                                    continue
                                if any(
                                    concrete_ranges_overlap(
                                        used_addr,
                                        access_width,
                                        source_offset,
                                        INIT_ACCESS_SLOT_WIDTH,
                                    )
                                    for source_offset in scaled_loaded_source_offsets
                                ):
                                    debug_load_slot_choice(
                                        "reject_same_addr_source_slot",
                                        candidate_offset=used_addr,
                                        source_offsets=scaled_loaded_source_offsets,
                                    )
                                    continue
                                same_addr_offset = used_addr
                                break
                    if same_addr_offset is not None:
                        addr = same_addr_offset
                        if commit_load_addr_constraint(addr):
                            addr_expr_offsets[addr_key] = addr
                        else:
                            addr = None
                if addr is None:
                    pass
                else:
                    pass
            if addr is None:
                write_stage(
                    "init:materialize_init:load_slots:entry",
                    slot=load_slot_idx,
                    inst_idx=inst_idx,
                    phase="same_addr_scan",
                )
                prefer_pointer_load_addr_solver = addr_has_loaded_base_with_residual_scalar(addr_symbol)
                scaled_loaded_source_offsets = zeroable_scaled_loaded_source_offsets(addr_symbol)
                if addr is None:
                    for materialized_reg, materialized_value in reg_values.items():
                        materialized_symbol = reg_to_symbol.get(materialized_reg)
                        if materialized_symbol is None or expr_key(materialized_symbol) != addr_key:
                            continue
                        materialized_offset = stack_offset_for_value(materialized_value)
                        if materialized_offset is None:
                            continue
                        if materialized_offset <= 0 or materialized_offset > STACK_RANGE:
                            continue
                        if inst.width > 1 and materialized_offset % inst.width:
                            continue
                        if commit_load_addr_constraint(materialized_offset, timeout_ms=100):
                            addr = materialized_offset
                            addr_expr_offsets[addr_key] = addr
                        break
                if addr is None and not prefer_pointer_load_addr_solver:
                    constrained_offsets = solver_eval_limited(
                        addr_expr,
                        n=2,
                        timeout_ms=local_solver_timeout_ms,
                    )
                    seen_constrained_offsets = set()
                    for constrained_offset in constrained_offsets:
                        constrained_offset &= ((1 << 64) - 1)
                        if constrained_offset in seen_constrained_offsets:
                            continue
                        seen_constrained_offsets.add(constrained_offset)
                        if constrained_offset <= 0 or constrained_offset > STACK_RANGE:
                            continue
                        if inst.width > 1 and constrained_offset % inst.width:
                            continue
                        if commit_load_addr_constraint(constrained_offset, timeout_ms=100):
                            addr = constrained_offset
                            addr_expr_offsets[addr_key] = addr
                            break
                if addr is None:
                    write_stage(
                        "init:materialize_init:load_slots:entry",
                        slot=load_slot_idx,
                        inst_idx=inst_idx,
                        phase="choose_offset",
                    )
                    avoid_ranges = [
                        (used_addr, used_width)
                        for used_addr, used_width, used_addr_symbol in access_ranges
                        if (
                            existing_slot_conflicts_with_current(used_addr)
                            or (
                                not existing_slot_can_alias_current(used_addr)
                                and not existing_slot_can_upgrade_for_current(used_addr)
                                and not same_address(addr_symbol, used_addr_symbol, allow_solver=False)
                            )
                        )
                    ]
                    avoid_ranges.extend(
                        (store_offset, store_width)
                        for store_offset, store_width, _, _ in prior_store_avoid_ranges
                    )
                    avoid_ranges.extend(
                        (future_offset, future_width)
                        for future_offset, future_width, _, _, _ in future_hard_load_ranges
                    )
                    if (
                        len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                        and inst.width == 8
                        and has_prior_store_for_prune
                    ):
                        avoid_ranges.append((
                            STACK_RANGE,
                            LIVEIN_STORE_LOW_GUARD_OFFSET,
                        ))
                    skip_low_loaded_residual_fallback = False
                    attempted_pointer_load_addr = False
                    alias_offsets = (
                        []
                        if prefer_pointer_load_addr_solver
                        else compatible_alias_offsets_for_current(
                            access_width,
                            inst.width if inst.width > 1 else 1,
                        )
                    )
                    for alias_offset in alias_offsets:
                        if commit_load_addr_constraint(alias_offset):
                            addr = alias_offset
                            addr_expr_offsets[addr_key] = addr
                            break
                    if addr is None:
                        current_affine = affine_key(addr_symbol)
                        if current_affine is not None:
                            current_base_key, current_imm, current_base = current_affine
                            for known_base_offset in affine_base_offsets_for(
                                current_base_key,
                                current_base,
                            ):
                                affine_offset = known_base_offset - current_imm
                                if affine_offset <= 0 or affine_offset > STACK_RANGE:
                                    continue
                                if inst.width > 1 and affine_offset % inst.width:
                                    continue
                                if commit_load_addr_constraint(affine_offset, timeout_ms=100):
                                    addr = affine_offset
                                    addr_expr_offsets[addr_key] = addr
                                    break
                    preferred_offset = next_free_stack_offset(
                        avoid_ranges,
                        align=inst.width if inst.width > 1 else 1,
                        width=access_width,
                    )
                    if (
                        preferred_offset is not None
                        and len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                        and ast_node_count(addr_symbol) > 64
                        and not prefer_pointer_load_addr_solver
                    ):
                        preferred_constraint = addr_expr == preferred_offset
                        if (
                            try_add_constraint_set_fast([preferred_constraint], timeout_ms=100)
                            or try_add_constraint_set_related(
                                [preferred_constraint],
                                expr_vars(addr_expr),
                                timeout_ms=1000,
                            )
                        ):
                            addr = preferred_offset
                    else:
                        if (
                            addr is None
                            and prefer_pointer_load_addr_solver
                            and not skip_low_loaded_residual_fallback
                        ):
                            write_stage(
                                "init:materialize_init:load_slots:entry",
                                slot=load_slot_idx,
                                inst_idx=inst_idx,
                                phase="choose_offset:pointer_load_addr_pre_affine",
                            )
                            attempted_pointer_load_addr = True
                            addr = choose_pointer_load_addr_offset(
                                addr_symbol,
                                addr_expr,
                                preferred_offset,
                                inst.width if inst.width > 1 else None,
                                avoid_ranges,
                                access_width,
                                mem_value_expr(inst, rd_symbol),
                                inst_idx,
                            )
                        write_stage(
                            "init:materialize_init:load_slots:entry",
                            slot=load_slot_idx,
                            inst_idx=inst_idx,
                            phase="choose_offset:affine_addr",
                        )
                        if addr is None and not prefer_pointer_load_addr_solver:
                            addr = choose_affine_addr_offset(
                                addr_symbol,
                                addr_expr,
                                preferred_offset,
                                inst.width if inst.width > 1 else None,
                                avoid_ranges,
                                access_width,
                            )
                    write_stage(
                        "init:materialize_init:load_slots:entry",
                        slot=load_slot_idx,
                        inst_idx=inst_idx,
                        phase="choose_offset:pointer_load_addr",
                    )
                    if (
                        addr is None
                        and not skip_low_loaded_residual_fallback
                        and not attempted_pointer_load_addr
                    ):
                        addr = choose_pointer_load_addr_offset(
                            addr_symbol,
                            addr_expr,
                            preferred_offset,
                            inst.width if inst.width > 1 else None,
                            avoid_ranges,
                            access_width,
                            mem_value_expr(inst, rd_symbol),
                            inst_idx,
                        )
                    if (
                        addr is None
                        and preferred_offset is not None
                        and not skip_low_loaded_residual_fallback
                    ):
                        addr = choose_carrier_residual_stack_offset(
                            addr_symbol,
                            addr_expr,
                            preferred_offset,
                            inst.width if inst.width > 1 else None,
                            avoid_ranges,
                            access_width,
                        )
                    if (
                        addr is None
                        and preferred_offset is not None
                        and len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
                        and not force_exact_load_slot
                        and not skip_low_loaded_residual_fallback
                    ):
                        addr = preferred_offset
                    elif (
                        addr is None
                        and preferred_offset is not None
                        and len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                        and not skip_low_loaded_residual_fallback
                    ):
                        addr = choose_carrier_residual_stack_offset(
                            addr_symbol,
                            addr_expr,
                            preferred_offset,
                            inst.width if inst.width > 1 else None,
                            avoid_ranges,
                            access_width,
                        )
                        if addr is None and (
                            try_add_constraint_set_fast([addr_expr == preferred_offset], timeout_ms=100)
                            or try_add_constraint_set_related(
                                [addr_expr == preferred_offset],
                                expr_vars(addr_expr),
                                timeout_ms=1000,
                            )
                            ):
                                addr = preferred_offset
                    if (
                        addr is None
                        and prefer_pointer_load_addr_solver
                        and not skip_low_loaded_residual_fallback
                    ):
                        pointer_model_offsets = solver_eval_current(
                            addr_expr,
                            n=8,
                            timeout_ms=5000,
                        )
                        if os.environ.get("RVMCA_DEBUG_LOAD_SLOTS") == "1":
                            DEBUG(
                                f"pointer_model_offsets idx={inst_idx} "
                                f"values={[hex(value & ((1 << addr_expr.size()) - 1)) for value in pointer_model_offsets]}"
                            )
                        seen_model_offsets = set()
                        for model_offset in pointer_model_offsets:
                            model_offset &= ((1 << addr_expr.size()) - 1)
                            if model_offset in seen_model_offsets:
                                continue
                            seen_model_offsets.add(model_offset)
                            if model_offset <= 0 or model_offset > STACK_RANGE:
                                continue
                            if inst.width > 1 and model_offset % inst.width:
                                continue
                            if commit_load_addr_constraint(
                                model_offset,
                                timeout_ms=5000,
                            ):
                                addr = model_offset
                                addr_expr_offsets[addr_key] = addr
                                debug_load_slot_choice(
                                    "commit_pointer_model_offset",
                                    candidate_offset=addr,
                                )
                                break
                    if (
                        addr is None
                        and skip_low_loaded_residual_fallback
                        and len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                        and not force_exact_load_slot
                    ):
                        continue
                    if addr is None and not (
                        preferred_offset is not None
                        and len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                    ):
                        write_stage(
                            "init:materialize_init:load_slots:entry",
                            slot=load_slot_idx,
                            inst_idx=inst_idx,
                            phase="choose_offset:positive_avoid",
                        )
                        try:
                            addr = choose_value(
                                addr_expr,
                                preferred_offset,
                                positive=True,
                                align=inst.width if inst.width > 1 else None,
                                avoid=avoid_ranges,
                                width=access_width,
                                required=False,
                                fast_positive=True,
                                candidate_ok=lambda candidate: (
                                    fixed_sp_affine_quotient_compatible(
                                        addr_symbol,
                                        candidate,
                                        access_width,
                                        avoid_ranges,
                                    )
                                ),
                            )
                        except AssertionError:
                            addr = None
                    if (
                        addr is None
                        and preferred_offset is not None
                        and hard_slot_type_load
                    ):
                        write_stage(
                            "init:materialize_init:load_slots:entry",
                            slot=load_slot_idx,
                            inst_idx=inst_idx,
                            phase="choose_offset:positive_avoid_hard_conflict",
                        )
                        if len(mem_entries) < GLOBAL_NO_OVERLAP_LOAD_THRESHOLD:
                            try:
                                addr = choose_value(
                                    addr_expr,
                                    preferred_offset,
                                    positive=True,
                                    align=inst.width if inst.width > 1 else None,
                                    avoid=avoid_ranges,
                                    width=access_width,
                                    required=False,
                                    fast_positive=True,
                                    candidate_ok=lambda candidate: (
                                        fixed_sp_affine_quotient_compatible(
                                            addr_symbol,
                                            candidate,
                                            access_width,
                                            avoid_ranges,
                                        )
                                    ),
                                )
                            except AssertionError:
                                addr = None
                        if addr is None:
                            align = inst.width if inst.width > 1 else 1
                            next_start = (preferred_offset + align) if preferred_offset is not None else align
                            hard_attempts = 0
                            hard_attempt_limit = 8 if len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD else 16
                            while hard_attempts < hard_attempt_limit:
                                fallback_offset = next_free_stack_offset(
                                    avoid_ranges,
                                    align=align,
                                    width=access_width,
                                    start=next_start,
                                )
                                if fallback_offset is None:
                                    break
                                hard_attempts += 1
                                if commit_load_addr_constraint(fallback_offset, timeout_ms=100):
                                    addr = fallback_offset
                                    break
                                next_start = fallback_offset + align
                    if addr is None and preferred_offset is not None and not hard_slot_type_load:
                        write_stage(
                            "init:materialize_init:load_slots:entry",
                            slot=load_slot_idx,
                            inst_idx=inst_idx,
                            phase="choose_offset:preferred_no_avoid",
                        )
                        addr = choose_value(
                            addr_expr,
                            preferred_offset,
                            positive=True,
                            align=inst.width if inst.width > 1 else None,
                            width=access_width,
                            required=False,
                            fast_positive=True,
                            candidate_ok=lambda candidate: (
                                fixed_sp_affine_quotient_compatible(
                                    addr_symbol,
                                    candidate,
                                    access_width,
                                    avoid_ranges,
                                )
                            ),
                        )
                    if addr is None and not hard_slot_type_load:
                        try:
                            write_stage(
                                "init:materialize_init:load_slots:entry",
                                slot=load_slot_idx,
                                inst_idx=inst_idx,
                                phase="choose_offset:any_positive",
                            )
                            addr = choose_value(
                                addr_expr,
                                None,
                                positive=True,
                                align=inst.width if inst.width > 1 else None,
                                width=access_width,
                                required=not (len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD),
                                fast_positive=True,
                                candidate_ok=lambda candidate: (
                                    fixed_sp_affine_quotient_compatible(
                                        addr_symbol,
                                        candidate,
                                        access_width,
                                        avoid_ranges,
                                    )
                                ),
                            )
                            if (
                                addr is None
                                and len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                            ):
                                continue
                        except AssertionError:
                            fallback_offset = preferred_offset
                            if fallback_offset is None:
                                fallback_offset = next_free_stack_offset(
                                    avoid_ranges,
                                    align=inst.width if inst.width > 1 else 1,
                                    width=access_width,
                                )
                            if (
                                fallback_offset is not None
                                and hard_slot_type_load
                                and existing_slot_conflicts_with_current(fallback_offset)
                            ):
                                fallback_offset = None
                            if fallback_offset is not None and (
                                try_add_constraint(addr_expr == fallback_offset)
                                or try_add_constraint_set_related(
                                    [addr_expr == fallback_offset],
                                    expr_vars(addr_expr),
                                    timeout_ms=1000,
                                )
                            ):
                                addr = fallback_offset
                            else:
                                if (
                                    len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                                    and not force_exact_load_slot
                                ):
                                    continue
                                raise
                    if (
                        addr is None
                        and len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                        and not force_exact_load_slot
                    ):
                        continue
                    if addr is None:
                        raise AssertionError(f"cannot choose load slot address for {addr_symbol}")
                    if low_guard_prior_store_conflict(addr):
                        debug_load_slot_choice(
                            "reject_low_guard_final",
                            candidate_offset=addr,
                            guard=LIVEIN_STORE_LOW_GUARD_OFFSET,
                        )
                        fallback_addr = choose_low_guard_fallback_addr()
                        if fallback_addr is None:
                            addr = None
                            if (
                                len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                                and not force_exact_load_slot
                            ):
                                continue
                            raise AssertionError(f"cannot choose load slot address for {addr_symbol}")
                        addr = fallback_addr
                    if hard_slot_type_load and existing_slot_conflicts_with_current(addr):
                        addr = None
                        if (
                            len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                            and not force_exact_load_slot
                        ):
                            continue
                        raise AssertionError(f"load slot type conflict for {addr_symbol}")
                    addr_expr_offsets[addr_key] = addr
            if addr is None:
                if (
                    len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                    and not force_exact_load_slot
                ):
                    continue
                raise AssertionError(f"cannot choose load slot address for {addr_symbol}")
            if debug_unsat_stages:
                debug_check_stage(f"load_slot_{load_slot_idx}_idx_{inst_idx}_addr_{addr}")
            processed_load_addr_keys.add(addr_key)
            if not duplicate_load_addr:
                access_ranges.append((addr, access_width, addr_symbol))
            if os.environ.get("RVMCA_DEBUG_LOAD_SLOTS") == "1" and (current_scalar_zero_load or current_pointer_like_load):
                DEBUG(f"load_slot_addr {({
                    'idx': inst_idx,
                    'inst': getattr(inst, 'code', str(inst)),
                    'addr_offset': addr,
                    'word_offset': ((addr + 7) // 8) * 8,
                    'duplicate': duplicate_load_addr,
                })}")

            write_stage(
                "init:materialize_init:load_slots:entry",
                slot=load_slot_idx,
                inst_idx=inst_idx,
                phase="field",
            )
            value_expr = mem_value_expr(inst, rd_symbol)
            value_vars = getattr(value_expr, 'variables', set())
            write_stage(
                "init:materialize_init:load_slots:entry",
                slot=load_slot_idx,
                inst_idx=inst_idx,
                phase="field:classify",
            )
            value_is_nonadditive_address_scalar = (
                bool(value_vars)
                and bool(value_vars & non_additive_loaded_addr_vars)
                and (inst_idx, stable_expr_key(value_expr)) not in pointer_source_value_keys
            )
            value_has_direct_pointer_use = (
                inst.width == 8
                and load_value_has_direct_pointer_use(value_expr, inst_idx)
            )
            value_is_pointer_source_residual_scalar = (
                inst.width == 8
                and load_value_is_pointer_source_residual_scalar(value_expr, inst_idx)
            )
            value_is_additive_offset_to_live_base = (
                inst.width == 8
                and load_value_is_additive_offset_to_live_base(value_expr, inst_idx)
            )
            value_is_mutated_additive_offset_to_live_base = (
                value_is_additive_offset_to_live_base
                and load_has_same_slot_update_chain(inst, rd_symbol, addr_symbol, inst_idx)
            )
            value_is_sp_affine_source_load = (
                inst.width == 8
                and (inst_idx, str(value_expr)) in sp_affine_source_load_keys
            )
            if value_is_pointer_source_residual_scalar or value_is_additive_offset_to_live_base:
                value_has_direct_pointer_use = False
                value_is_nonadditive_address_scalar = True
            if value_is_sp_affine_source_load:
                value_has_direct_pointer_use = False
                value_is_nonadditive_address_scalar = False
            if value_has_direct_pointer_use:
                value_is_nonadditive_address_scalar = False
            write_stage(
                "init:materialize_init:load_slots:entry",
                slot=load_slot_idx,
                inst_idx=inst_idx,
                phase="field:later_addr_scan",
            )
            value_used_in_later_addr = bool(value_vars) and any(
                later_idx > inst_idx and (expr_vars(later_addr_symbol) & value_vars)
                for _, later_addr_symbol, later_idx, _ in mem_accesses
            )
            write_stage(
                "init:materialize_init:load_slots:entry",
                slot=load_slot_idx,
                inst_idx=inst_idx,
                phase="field:store_data_scan",
            )
            value_used_as_later_store_data = bool(value_vars) and any(
                store_idx > inst_idx and (expr_vars(store_data_symbol) & value_vars)
                for _, _, store_idx, _, store_data_symbol in store_accesses
            )
            value_feeds_forwarded_pointer = load_value_feeds_forwarded_pointer_use(
                value_expr,
                inst_idx,
            )
            if value_feeds_forwarded_pointer:
                value_used_in_later_addr = True
            value_feeds_forwarded_address_scalar = load_value_feeds_forwarded_address_scalar(
                value_expr,
                inst_idx,
            )
            value_feeds_store_addr = load_value_has_direct_store_addr_use(
                value_expr,
                inst_idx,
            )
            value_is_store_address_base = (
                value_feeds_store_addr
                and not value_is_additive_offset_to_live_base
                and not value_is_pointer_source_residual_scalar
                and not value_feeds_forwarded_address_scalar
            )
            if value_is_store_address_base:
                value_is_nonadditive_address_scalar = False
            if value_feeds_forwarded_address_scalar:
                value_used_in_later_addr = True
                value_is_nonadditive_address_scalar = True
                value_has_direct_pointer_use = False
                value_feeds_forwarded_pointer = False
            load_value_key = load_value_identity_key(inst_idx, rd_symbol, addr_symbol)
            scalar_zero_load = (
                current_scalar_zero_load
                or value_is_pointer_source_residual_scalar
                or value_is_additive_offset_to_live_base
                or value_feeds_forwarded_address_scalar
            )
            if value_is_sp_affine_source_load:
                scalar_zero_load = False
            if value_has_direct_pointer_use:
                scalar_zero_load = False
            if value_is_store_address_base:
                scalar_zero_load = False
            scaled_loaded_value = None
            loaded_affine_quotient_recipe = None
            value_is_scaled_address_scalar = False
            value_needs_scaled_sp_recipe = (
                inst.width == 8
                and any(
                    later_idx > inst_idx
                    and bool(expr_vars(later_addr_symbol) & value_vars)
                    and is_power_of_two_scaled_affine(
                        later_addr_symbol,
                        value_expr,
                    )
                    for _, later_addr_symbol, later_idx, _ in mem_accesses
                )
            )
            write_stage(
                "init:materialize_init:load_slots:entry",
                slot=load_slot_idx,
                inst_idx=inst_idx,
                phase="field:deferred_scaled_check",
            )
            deferred_loaded_address_scalar = is_deferred_loaded_address_scalar(
                inst,
                value_expr,
                inst_idx,
            )
            if (
                not value_has_direct_pointer_use
                and not value_is_store_address_base
                and deferred_loaded_address_scalar
            ):
                affine_quotient_choice = choose_affine_quotient_loaded_address_value(
                    value_expr,
                    inst_idx,
                )
                if affine_quotient_choice is not None:
                    (
                        scaled_loaded_value,
                        loaded_affine_quotient_recipe,
                    ) = affine_quotient_choice
                else:
                    scaled_loaded_value = choose_scaled_loaded_address_value(value_expr)
                if scaled_loaded_value is not None:
                    value_is_scaled_address_scalar = True
                    if scaled_loaded_value == 0:
                        scalar_zero_load = True
                        value_is_nonadditive_address_scalar = True
            forwarded_pointer_carrier_added = False
            if (
                value_feeds_forwarded_pointer
                and not value_feeds_forwarded_address_scalar
                and not value_is_scaled_address_scalar
            ):
                forwarded_carrier = forwarded_pointer_carrier_constraints(
                    value_expr,
                    inst_idx,
                )
                if forwarded_carrier is not None:
                    forwarded_carrier_group, forwarded_carrier_constraints = forwarded_carrier
                    forwarded_constraint_vars = set()
                    for constraint in forwarded_carrier_constraints:
                        forwarded_constraint_vars.update(expr_vars(constraint))
                    forwarded_pointer_carrier_added = (
                        try_add_constraint_set_fast(
                            forwarded_carrier_constraints,
                            timeout_ms=local_solver_timeout_ms,
                        )
                        or try_add_constraint_set_related(
                            forwarded_carrier_constraints,
                            forwarded_constraint_vars | value_vars,
                            timeout_ms=max(local_solver_timeout_ms, 1000),
                        )
                    )
                    if forwarded_pointer_carrier_added:
                        forwarded_pointer_carrier_claims[
                            forwarded_carrier_group
                        ] = (inst_idx, stable_expr_key(value_expr))
                        hint_pointer_load_keys.add((inst_idx, expr_key(value_expr)))
                    elif len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD:
                        forwarded_sat = constraint_set_related_satisfiable(
                            forwarded_carrier_constraints,
                            forwarded_constraint_vars | value_vars,
                            timeout_ms=max(local_solver_timeout_ms, 1000),
                        )
                        if forwarded_sat is not False:
                            for constraint in forwarded_carrier_constraints:
                                candidate_solver.add(constraint)
                                added_constraint_cache.add(str(claripy.simplify(constraint)))
                                debug_constraint_add("forwarded_pointer_carrier_assumed", constraint)
                            forwarded_pointer_carrier_added = True
                            forwarded_pointer_carrier_claims[
                                forwarded_carrier_group
                            ] = (inst_idx, stable_expr_key(value_expr))
                            hint_pointer_load_keys.add((inst_idx, expr_key(value_expr)))
            write_stage(
                "init:materialize_init:load_slots:entry",
                slot=load_slot_idx,
                inst_idx=inst_idx,
                phase="field:scalar_zero_constraint",
            )
            scalar_zero_constraint_added = False
            if scalar_zero_load and not value_is_mutated_additive_offset_to_live_base:
                scalar_zero_constraint_added = commit_scalar_zero_constraint(
                    value_expr,
                    timeout_ms=max(local_solver_timeout_ms, 1000),
                    assume_unknown=not value_is_additive_offset_to_live_base,
                    allow_related=not value_is_additive_offset_to_live_base,
                )
            if value_is_sp_affine_source_load:
                sp_affine_stack_constraints = stack_pointer_constraints_for_expr(
                    value_expr,
                    _align_up(
                        max(
                            INIT_PTR_MIN_OFFSET,
                            min_pointer_offset_for_vars(
                                value_vars,
                                inst_idx,
                                avoid_ranges=[(addr, access_width)],
                            ),
                        ),
                        INIT_ACCESS_ALIGN,
                    ),
                )
                if not (
                    try_add_constraint_set_fast(
                        sp_affine_stack_constraints,
                        timeout_ms=max(local_solver_timeout_ms, 1000),
                    )
                    or try_add_constraint_set_related(
                        sp_affine_stack_constraints,
                        value_vars,
                        timeout_ms=max(local_solver_timeout_ms, 1000),
                    )
                ):
                    sp_affine_sat = constraint_set_related_satisfiable(
                        sp_affine_stack_constraints,
                        value_vars,
                        timeout_ms=max(local_solver_timeout_ms, 1000),
                    )
                    if sp_affine_sat is not False:
                        for constraint in sp_affine_stack_constraints:
                            candidate_solver.add(constraint)
                            added_constraint_cache.add(str(claripy.simplify(constraint)))
                            debug_constraint_add("sp_affine_source_stack_assumed", constraint)
            skip_static_store_data_value = (
                use_static_memory_collection
                and inst.width == 4
                and value_used_as_later_store_data
                and not value_used_in_later_addr
                and load_value_key not in required_load_value_keys
            )
            require_load_value = (
                not skip_static_store_data_value
                and (
                    len(mem_entries) < STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD
                    or load_value_key in required_load_value_keys
                    or value_used_in_later_addr
                    or inst.pc in load_nonzero_hints
                )
            )
            word_offset = ((addr + 7) // 8) * 8
            byte_offset = word_offset - addr
            load_slot_layouts[inst_idx] = (
                word_offset,
                byte_offset,
                inst.width,
            )
            assert 0 <= byte_offset and byte_offset + inst.width <= 8, (
                f"invalid init slot field: offset={addr}, width={inst.width}, "
                f"byte_offset={byte_offset}, inst_idx={inst_idx}, addr={addr_symbol}"
            )
            write_stage(
                "init:materialize_init:load_slots:entry",
                slot=load_slot_idx,
                inst_idx=inst_idx,
                phase="field:slot_prepare",
            )
            new_word_slot = word_offset not in mem_slot_symbols
            if word_offset not in mem_slot_symbols:
                word_symbol = claripy.BVS(f'init_mem_word_{len(mem_slot_symbols)}_{word_offset}', 64)
                mem_slot_symbols[word_offset] = {
                    'symbol': word_symbol,
                    'pointer_like': False,
                    'must_be_pointer': False,
                    'min_pointer_offset': 0,
                    'sp_affine': False,
                    'scalar_zero': False,
                    'feeds_store_addr': False,
                }
                mem_offset_addr_symbols[word_offset] = []
                mem_offset_addr_entries[word_offset] = []
            else:
                word_symbol = mem_slot_symbols[word_offset]['symbol']

            slot = mem_slot_symbols[word_offset]
            prior_value_exprs = []
            if inst.width == 8 and byte_offset == 0:
                prior_value_exprs.extend(slot.get('value_exprs', []))
                if 'direct_value_expr' in slot:
                    prior_value_exprs.append(slot['direct_value_expr'])
            if scaled_loaded_value is not None and inst.width == 8 and byte_offset == 0:
                slot['preferred_scalar_value'] = scaled_loaded_value
            if scalar_zero_load and scalar_zero_constraint_added:
                slot['scalar_zero'] = True
                if byte_offset == 0 and not (
                    slot.get('pointer_like')
                    or slot.get('must_be_pointer')
                    or slot.get('sp_affine')
                ):
                    slot['preferred_scalar_value'] = 0
            if (
                value_is_nonadditive_address_scalar
                and not value_is_mutated_additive_offset_to_live_base
            ):
                nonadditive_zero_added = commit_scalar_zero_constraint(
                    value_expr,
                    timeout_ms=max(local_solver_timeout_ms, 1000),
                    assume_unknown=False,
                    allow_related=False,
                )
                if nonadditive_zero_added:
                    slot['scalar_zero'] = True
                    if byte_offset == 0 and not (
                        slot.get('pointer_like')
                        or slot.get('must_be_pointer')
                        or slot.get('sp_affine')
                    ):
                        slot['preferred_scalar_value'] = 0
            forced_same_slot_value = (
                inst.width == 8
                and byte_offset == 0
                and same_slot_value_must_alias(word_offset, byte_offset)
            )
            if (
                not new_word_slot
                and 'direct_value_expr' in slot
            ):
                direct_value_constraint = slot['symbol'] == slot['direct_value_expr']
                direct_value_added = (
                    try_add_constraint(direct_value_constraint, timeout_ms=local_solver_timeout_ms)
                    or try_add_constraint_set_related(
                        [direct_value_constraint],
                        expr_vars(slot['symbol']) | expr_vars(slot['direct_value_expr']),
                        timeout_ms=max(local_solver_timeout_ms, 1000),
                    )
                )
                if not direct_value_added and len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD:
                    direct_value_sat = constraint_set_related_satisfiable(
                        [direct_value_constraint],
                        expr_vars(slot['symbol']) | expr_vars(slot['direct_value_expr']),
                        timeout_ms=max(local_solver_timeout_ms, 1000),
                    )
                    if direct_value_sat is not False:
                        candidate_solver.add(direct_value_constraint)
                        added_constraint_cache.add(str(claripy.simplify(direct_value_constraint)))
                        debug_constraint_add("direct_value_required", direct_value_constraint)
                        direct_value_added = True
                if direct_value_added:
                    del slot['direct_value_expr']

            if not require_load_value:
                field_added = False
            elif new_word_slot and inst.width == 8 and byte_offset == 0:
                mem_slot_symbols[word_offset]['direct_value_expr'] = value_expr
                field_added = True
            else:
                write_stage(
                    "init:materialize_init:load_slots:entry",
                    slot=load_slot_idx,
                    inst_idx=inst_idx,
                    phase="field:constrain_word",
                )
                field_added = constrain_word_field(
                    word_symbol,
                    byte_offset,
                    inst,
                    value_expr,
                    protected=not new_word_slot,
                )
            if inst.width == 8 and byte_offset == 0 and prior_value_exprs:
                for prior_value_expr in prior_value_exprs:
                    equality_constraint = value_expr == prior_value_expr
                    equality_added = (
                        try_add_constraint_set_fast(
                            [equality_constraint],
                            timeout_ms=local_solver_timeout_ms,
                        )
                        or try_add_constraint_set_related(
                            [equality_constraint],
                            expr_vars(value_expr) | expr_vars(prior_value_expr),
                            timeout_ms=max(local_solver_timeout_ms, 1000),
                        )
                    )
                    if not equality_added and forced_same_slot_value:
                        equality_sat = constraint_set_related_satisfiable(
                            [equality_constraint],
                            expr_vars(value_expr) | expr_vars(prior_value_expr),
                            timeout_ms=max(local_solver_timeout_ms, 1000),
                        )
                        if equality_sat is not False:
                            candidate_solver.add(equality_constraint)
                            added_constraint_cache.add(str(claripy.simplify(equality_constraint)))
                            equality_added = True
                    if equality_added:
                        register_expr_equality(value_expr, prior_value_expr)
            if not any(
                same_address(addr_symbol, known_addr, allow_solver=False)
                for known_addr in mem_offset_addr_symbols[word_offset]
            ):
                mem_offset_addr_symbols[word_offset].append(addr_symbol)
            if inst.width == 8 and byte_offset == 0:
                entry_key = (expr_key(addr_symbol), inst_idx)
                if not any(
                    expr_key(known_addr) == entry_key[0] and known_idx == inst_idx
                    for known_addr, known_idx in mem_offset_addr_entries[word_offset]
                ):
                    mem_offset_addr_entries[word_offset].append((addr_symbol, inst_idx))
            if field_added and inst.width == 8 and byte_offset == 0:
                for prior_value_expr in prior_value_exprs:
                    register_expr_equality(value_expr, prior_value_expr)
                slot.setdefault('value_exprs', []).append(value_expr)
                if value_feeds_store_addr:
                    slot['feeds_store_addr'] = True
            if field_added and inst.width == 8 and byte_offset == 0 and (inst_idx, str(value_expr)) in sp_affine_source_load_keys:
                mem_slot_symbols[word_offset]['sp_affine'] = True
            if field_added and inst.width == 8 and byte_offset == 0 and value_needs_scaled_sp_recipe:
                mem_slot_symbols[word_offset]['scaled_sp_affine'] = True
            if (
                field_added
                and inst.width == 8
                and byte_offset == 0
                and loaded_affine_quotient_recipe is not None
            ):
                mem_slot_symbols[word_offset]['affine_quotient'] = (
                    loaded_affine_quotient_recipe
                )
            write_stage(
                "init:materialize_init:load_slots:entry",
                slot=load_slot_idx,
                inst_idx=inst_idx,
                phase="field:pointer_mark",
            )
            debug_pointer_mark_before = (
                bool(mem_slot_symbols[word_offset].get('pointer_like')),
                bool(mem_slot_symbols[word_offset].get('must_be_pointer')),
                bool(mem_slot_symbols[word_offset].get('sp_affine')),
                bool(mem_slot_symbols[word_offset].get('scalar_zero')),
            )
            debug_pointer_mark_store_required = any(
                value_vars & required_vars
                for required_vars, _ in store_pointer_required_min_offsets
            )
            debug_pointer_mark_source_alias = any(
                (value_vars & getattr(pointer_rd_symbol, 'variables', set()))
                for _, pointer_rd_symbol, _, pointer_idx in pointer_source_loads
                if (pointer_idx, expr_key(pointer_rd_symbol)) not in scalar_load_hint_keys
            )
            debug_pointer_mark_same_addr_source = any(
                (
                    (inst_idx == pointer_idx or same_address(addr_symbol, pointer_addr_symbol, allow_solver=False))
                    and (pointer_idx, expr_key(pointer_rd_symbol)) not in scalar_load_hint_keys
                )
                for _, pointer_rd_symbol, pointer_addr_symbol, pointer_idx in pointer_source_loads
            )
            if (
                inst.width == 8
                and byte_offset == 0
                and value_has_direct_pointer_use
                and not value_is_scaled_address_scalar
            ):
                mem_slot_symbols[word_offset]['pointer_like'] = True
                mem_slot_symbols[word_offset]['must_be_pointer'] = True
                mem_slot_symbols[word_offset]['min_pointer_offset'] = max(
                    mem_slot_symbols[word_offset]['min_pointer_offset'],
                    min_pointer_offset_for_vars(
                        value_vars,
                        inst_idx,
                        avoid_ranges=[(word_offset, 8)],
                    ),
                )
            if (
                inst.width == 8
                and byte_offset == 0
                and value_used_in_later_addr
                and value_vars & pointer_loaded_addr_vars
                and not value_is_pointer_source_residual_scalar
                and not value_is_scaled_address_scalar
            ):
                mem_slot_symbols[word_offset]['pointer_like'] = True
                mem_slot_symbols[word_offset]['must_be_pointer'] = True
                mem_slot_symbols[word_offset]['min_pointer_offset'] = max(
                    mem_slot_symbols[word_offset]['min_pointer_offset'],
                    min_pointer_offset_for_vars(
                        value_vars,
                        inst_idx,
                        avoid_ranges=[(word_offset, 8)],
                    ),
                )
            if field_added and inst.width == 8 and byte_offset == 0:
                if (
                    value_feeds_forwarded_pointer
                    and (debug_pointer_mark_store_required or forwarded_pointer_carrier_added)
                    and not value_is_scaled_address_scalar
                ):
                    mem_slot_symbols[word_offset]['pointer_like'] = True
                    mem_slot_symbols[word_offset]['must_be_pointer'] = True
                    mem_slot_symbols[word_offset]['min_pointer_offset'] = max(
                        mem_slot_symbols[word_offset]['min_pointer_offset'],
                        INIT_PTR_MIN_OFFSET,
                    )
                if (
                    value_vars & pointer_loaded_addr_vars
                    and not value_is_pointer_source_residual_scalar
                    and not value_is_scaled_address_scalar
                ):
                    mem_slot_symbols[word_offset]['pointer_like'] = True
                    if value_used_in_later_addr:
                        mem_slot_symbols[word_offset]['must_be_pointer'] = True
                    mem_slot_symbols[word_offset]['min_pointer_offset'] = max(
                        mem_slot_symbols[word_offset]['min_pointer_offset'],
                        min_pointer_offset_for_vars(
                            value_vars,
                            inst_idx,
                            avoid_ranges=[(word_offset, 8)],
                            ),
                        )
                if value_is_store_address_base and not value_is_scaled_address_scalar:
                    mem_slot_symbols[word_offset]['pointer_like'] = True
                    mem_slot_symbols[word_offset]['must_be_pointer'] = True
                    mem_slot_symbols[word_offset]['min_pointer_offset'] = max(
                        mem_slot_symbols[word_offset]['min_pointer_offset'],
                        min_pointer_offset_for_vars(
                            value_vars,
                            inst_idx,
                            avoid_ranges=[(word_offset, 8)],
                        ),
                    )
                if not value_is_nonadditive_address_scalar and not value_is_scaled_address_scalar:
                    for _, later_addr_symbol, later_idx, _ in mem_accesses:
                        if later_idx <= inst_idx:
                            continue
                        later_addr_vars = expr_vars(later_addr_symbol)
                        if not (later_addr_vars & value_vars):
                            continue
                        if (later_addr_vars & pointer_loaded_addr_vars) and not (value_vars & pointer_loaded_addr_vars):
                            continue
                        residual = claripy.simplify(later_addr_symbol - value_expr)
                        residual_vars = expr_vars(residual)
                        if not (residual_vars & value_vars) and concrete_expr_value(residual) is not None:
                            mem_slot_symbols[word_offset]['pointer_like'] = True
                            mem_slot_symbols[word_offset]['must_be_pointer'] = True
                            mem_slot_symbols[word_offset]['min_pointer_offset'] = max(
                                mem_slot_symbols[word_offset]['min_pointer_offset'],
                                min_pointer_offset_for_vars(
                                    value_vars,
                                    inst_idx,
                                    avoid_ranges=[(word_offset, 8)],
                                ),
                            )
                            break
                        if constraints_to_carrier(later_addr_symbol, value_expr) is None:
                            continue
                        mem_slot_symbols[word_offset]['pointer_like'] = True
                        mem_slot_symbols[word_offset]['must_be_pointer'] = True
                        mem_slot_symbols[word_offset]['min_pointer_offset'] = max(
                            mem_slot_symbols[word_offset]['min_pointer_offset'],
                            min_pointer_offset_for_vars(
                                value_vars,
                                inst_idx,
                                avoid_ranges=[(word_offset, 8)],
                            ),
                        )
                        break
                for required_vars, required_min_offset in store_pointer_required_min_offsets:
                    if value_is_scaled_address_scalar:
                        break
                    if not (value_vars & required_vars):
                        continue
                    mem_slot_symbols[word_offset]['pointer_like'] = True
                    mem_slot_symbols[word_offset]['must_be_pointer'] = True
                    mem_slot_symbols[word_offset]['min_pointer_offset'] = max(
                        mem_slot_symbols[word_offset]['min_pointer_offset'],
                        _align_up(
                            max(INIT_PTR_MIN_OFFSET, required_min_offset),
                            INIT_ACCESS_ALIGN,
                        ),
                    )
                    break
                if (
                    not value_is_nonadditive_address_scalar
                    and not value_is_scaled_address_scalar
                    and (inst_idx, expr_key(value_expr)) in hint_pointer_load_keys
                ):
                    value_vars = getattr(value_expr, 'variables', set())
                    mem_slot_symbols[word_offset]['pointer_like'] = True
                    if value_used_in_later_addr:
                        mem_slot_symbols[word_offset]['must_be_pointer'] = True
                    mem_slot_symbols[word_offset]['min_pointer_offset'] = max(
                        mem_slot_symbols[word_offset]['min_pointer_offset'],
                        min_pointer_offset_for_vars(
                            value_vars,
                            inst_idx,
                            avoid_ranges=[(word_offset, 8)],
                        ),
                    )
                for _, pointer_rd_symbol, pointer_addr_symbol, pointer_idx in pointer_source_loads:
                    if value_is_scaled_address_scalar:
                        break
                    if (pointer_idx, expr_key(pointer_rd_symbol)) in scalar_load_hint_keys:
                        continue
                    if pointer_idx in pointer_source_indices and has_prior_same_addr_store(pointer_addr_symbol, pointer_idx):
                        continue
                    pointer_vars = getattr(pointer_rd_symbol, 'variables', set())
                    if not (value_vars & pointer_vars):
                        continue
                    mem_slot_symbols[word_offset]['pointer_like'] = True
                    if value_used_in_later_addr:
                        mem_slot_symbols[word_offset]['must_be_pointer'] = True
                    mem_slot_symbols[word_offset]['min_pointer_offset'] = max(
                        mem_slot_symbols[word_offset]['min_pointer_offset'],
                            min_pointer_offset_for_vars(pointer_vars, pointer_idx, avoid_ranges=[(word_offset, 8)]),
                        )
            if field_added and inst.width == 8 and byte_offset == 0:
                for pointer_inst, pointer_rd_symbol, pointer_addr_symbol, pointer_idx in pointer_source_loads:
                    if value_is_scaled_address_scalar:
                        break
                    if (pointer_idx, expr_key(pointer_rd_symbol)) in scalar_load_hint_keys:
                        continue
                    if pointer_idx in pointer_source_indices and has_prior_same_addr_store(pointer_addr_symbol, pointer_idx, allow_solver=False):
                        continue
                    if inst_idx == pointer_idx or same_address(addr_symbol, pointer_addr_symbol, allow_solver=False):
                        pointer_vars = getattr(pointer_rd_symbol, 'variables', set())
                        mem_slot_symbols[word_offset]['pointer_like'] = True
                        if value_used_in_later_addr:
                            mem_slot_symbols[word_offset]['must_be_pointer'] = True
                        mem_slot_symbols[word_offset]['min_pointer_offset'] = max(
                            mem_slot_symbols[word_offset]['min_pointer_offset'],
                            min_pointer_offset_for_vars(pointer_vars, pointer_idx, avoid_ranges=[(word_offset, 8)]),
                        )
            if os.environ.get("RVMCA_DEBUG_LOAD_SLOTS") == "1":
                debug_pointer_mark_after = (
                    bool(mem_slot_symbols[word_offset].get('pointer_like')),
                    bool(mem_slot_symbols[word_offset].get('must_be_pointer')),
                    bool(mem_slot_symbols[word_offset].get('sp_affine')),
                    bool(mem_slot_symbols[word_offset].get('scalar_zero')),
                )
                if debug_pointer_mark_after != debug_pointer_mark_before:
                    DEBUG(f"load_slot_pointer_mark {({
                        'word_offset': word_offset,
                        'idx': inst_idx,
                        'inst': getattr(inst, 'code', str(inst)),
                        'value': str(value_expr),
                        'before': debug_pointer_mark_before,
                        'after': debug_pointer_mark_after,
                        'value_used_in_later_addr': value_used_in_later_addr,
                        'value_is_nonadditive_address_scalar': value_is_nonadditive_address_scalar,
                        'value_is_additive_offset_to_live_base': value_is_additive_offset_to_live_base,
                        'value_is_mutated_additive_offset_to_live_base': value_is_mutated_additive_offset_to_live_base,
                        'scalar_zero_load': scalar_zero_load,
                        'scaled_address_scalar': value_is_scaled_address_scalar,
                        'value_feeds_forwarded_pointer': value_feeds_forwarded_pointer,
                        'forwarded_pointer_carrier_added': forwarded_pointer_carrier_added,
                        'value_feeds_forwarded_address_scalar': value_feeds_forwarded_address_scalar,
                        'value_is_store_address_base': value_is_store_address_base,
                        'value_has_direct_pointer_use': value_has_direct_pointer_use,
                        'in_pointer_loaded_vars': bool(value_vars & pointer_loaded_addr_vars),
                        'hint_pointer': (inst_idx, expr_key(value_expr)) in hint_pointer_load_keys,
                        'store_required': debug_pointer_mark_store_required,
                        'source_alias': debug_pointer_mark_source_alias,
                        'same_addr_source': debug_pointer_mark_same_addr_source,
                    })}")
            if debug_unsat_stages:
                debug_check_stage(f"load_slot_{load_slot_idx}_idx_{inst_idx}_word_{word_offset}_field_{field_added}")

        _write_profile_stage(name, "init:materialize_init:refresh_registers")
        refresh_materialized_register_values()
        if debug_unsat_stages:
            debug_check_stage("refresh_registers")

        for word_offset, slot in mem_slot_symbols.items():
            write_stage("init:materialize_init:store_no_overlap", word_offset=word_offset)
            add_store_no_overlap_for_word(word_offset, mem_offset_addr_symbols[word_offset])
            if debug_unsat_stages:
                debug_check_stage(f"store_no_overlap_word_{word_offset}")

        if verbose:
            print('mem_slot_symbols', {
                offset: {
                    'pointer_like': slot.get('pointer_like'),
                    'must_be_pointer': slot.get('must_be_pointer'),
                    'min_pointer_offset': slot.get('min_pointer_offset'),
                    'sp_affine': slot.get('sp_affine'),
                    'symbol': str(slot.get('symbol')),
                }
                for offset, slot in sorted(mem_slot_symbols.items())
            })

        def sp_affine_mode_for_compensation_value(value):
            value &= ((1 << 64) - 1)
            candidate_reg_values = list(reg_values.values())
            for reg, symbol in reg_to_symbol.items():
                if reg in reg_values:
                    continue
                value_bvv = expr_bvv(value, symbol)
                for combined in (
                    claripy.simplify(value_bvv + symbol),
                    claripy.simplify(value_bvv - symbol),
                ):
                    if try_add_constraint_set(stack_pointer_constraints_for_expr(combined)):
                        return 'direct'
                candidate_reg_values.extend(solver_eval_with(symbol, [], n=8))
            seen_reg_values = set()
            for reg_value in candidate_reg_values:
                reg_value &= ((1 << 64) - 1)
                if reg_value in seen_reg_values:
                    continue
                seen_reg_values.add(reg_value)
                reg_stack_offset = signed_stack_offset_for_value(reg_value)
                if reg_stack_offset is None:
                    continue
                plus_value = (value + reg_value) & ((1 << 64) - 1)
                minus_value = (value - reg_value) & ((1 << 64) - 1)
                if -STACK_RANGE <= _signed_u64(plus_value) <= STACK_RANGE:
                    return 'inverse'
                if -STACK_RANGE <= _signed_u64(minus_value) <= STACK_RANGE:
                    return 'direct'
            return None

        _write_profile_stage(name, "init:materialize_init:memory_values")
        if len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD:
            pass
        elif len(mem_entries) >= STATIC_MEMORY_COLLECTION_ACCESS_THRESHOLD:
            satisfiable_result = None
            try:
                satisfiable_check = candidate_solver.branch()
                satisfiable_check.timeout = local_solver_timeout_ms
                satisfiable_result = satisfiable_check.satisfiable()
            except Exception:
                pass
            assert satisfiable_result is not False, f"[ERROR]: {name} init memory constraints are unsatisfiable"
        else:
            assert candidate_solver.satisfiable(), f"[ERROR]: {name} init memory constraints are unsatisfiable"
        for addr, slot in mem_slot_symbols.items():
            write_stage(
                "init:materialize_init:memory_values:slot",
                offset=addr,
                pointer_like=bool(slot.get('pointer_like')),
                sp_affine=bool(slot.get('sp_affine')),
            )
            actual_value = choose_mem_slot_value(addr, slot)
            value_stack_offset = stack_offset_for_value(actual_value)
            force_sp_delta = None
            force_inverse_sp_delta = None
            force_scaled_stack = None
            force_affine_quotient = slot.get('affine_quotient')
            actual_signed_value = _signed_u64(actual_value)
            scalar_sp_affine_value = -STACK_RANGE <= actual_signed_value <= STACK_RANGE
            write_stage(
                "init:materialize_init:memory_values:slot",
                offset=addr,
                phase="sp_affine_check",
                pointer_like=bool(slot.get('pointer_like')),
                sp_affine=bool(slot.get('sp_affine')),
            )
            if force_affine_quotient is not None:
                expected_value = _affine_quotient_value(
                    CONCRETE_REPLAY_SP,
                    force_affine_quotient,
                )
                assert actual_value == expected_value, (
                    "affine quotient slot value changed after selection: "
                    f"actual={actual_value:#x}, expected={expected_value:#x}, "
                    f"recipe={force_affine_quotient!r}"
                )
                sp_affine_mem_offsets[addr] = force_affine_quotient
                combined_sp_affine_mode = None
            else:
                combined_sp_affine_mode = (
                    sp_affine_mode_for_compensation_value(actual_value)
                    if value_stack_offset is None and not scalar_sp_affine_value
                    else None
                )
            combined_sp_affine_value = combined_sp_affine_mode is not None
            if combined_sp_affine_mode == 'direct' and not slot.get('sp_affine'):
                combined_sp_affine_value = False
            if combined_sp_affine_mode is not None and verbose:
                print('combined_sp_affine_mode', addr, hex(actual_value), combined_sp_affine_mode)
            if (
                (slot.get('sp_affine') or combined_sp_affine_value)
                and signed_stack_offset_for_value(actual_value) is None
                and not scalar_sp_affine_value
            ):
                mode = combined_sp_affine_mode or 'direct'
                sp_affine_mem_offsets[addr] = mode
                if mode == 'inverse':
                    force_inverse_sp_delta = (actual_value + CONCRETE_REPLAY_SP) & ((1 << 64) - 1)
                else:
                    force_sp_delta = (actual_value - CONCRETE_REPLAY_SP) & ((1 << 64) - 1)
            if slot.get('scaled_sp_affine'):
                force_scaled_stack = scaled_stack_transform_for_value(
                    actual_value,
                    max_offset=MAX_SP_REL_OFFSET,
                )
                if force_scaled_stack is not None:
                    sp_affine_mem_offsets[addr] = (
                        'scaled',
                        force_scaled_stack[0],
                        force_scaled_stack[1],
                    )

            # prepare value
            append_value_init(
                candidate_init,
                TEMP_REG,
                actual_value,
                force_stack_offset=value_stack_offset,
                force_sp_delta=force_sp_delta,
                force_inverse_sp_delta=force_inverse_sp_delta,
                force_scaled_stack=force_scaled_stack,
                force_affine_quotient=force_affine_quotient,
            )
            # prepare address
            candidate_init.append(UFmtInst('li', TEMP_REG2, addr))
            candidate_init.append(RFmtInst('sub', TEMP_REG2, 'sp', TEMP_REG2))

            candidate_init.append(StoreInst('sd', TEMP_REG, TEMP_REG2, 0))
            mem_values[addr] = actual_value

        for r in regs_undefined:
            if r in deferred_regs:
                _write_profile_stage(name, "init:materialize_init:deferred_registers")
                materialize_register(r)

        def install_linear_runtime_register_recipes():
            if runtime_recipe_scratch_unavailable():
                return

            translation_delta = claripy.BVS(
                "rvmca_linear_runtime_translation_delta",
                64,
            )
            base_replacements = {
                init_sp.hash(): init_sp + translation_delta,
            }
            source_replacements = {}
            source_coefficients = {}
            unsupported_runtime_source_vars = set()

            def translation_identity(left, right):
                equality = claripy.simplify(left == right)
                if claripy.is_true(equality):
                    return True
                proof_solver = claripy.Solver()
                proof_solver.timeout = max(local_solver_timeout_ms, 1000)
                proof_solver.add(claripy.Not(equality))
                try:
                    return proof_solver.satisfiable() is False
                except Exception:
                    return False

            for runtime_reg, runtime_value in reg_values.items():
                runtime_symbol = reg_to_symbol.get(runtime_reg)
                runtime_vars = expr_vars(runtime_symbol)
                if not runtime_vars:
                    continue
                runtime_recipe = reg_runtime_recipes.get(runtime_reg)
                if runtime_recipe is not None:
                    if runtime_recipe[0] == 'affine_linear':
                        runtime_coefficient = int(runtime_recipe[2])
                        base_replacements[runtime_symbol.hash()] = (
                            runtime_symbol + translation_delta * expr_bvv(
                                runtime_coefficient & ((1 << 64) - 1),
                                runtime_symbol,
                            )
                        )
                    else:
                        unsupported_runtime_source_vars.update(runtime_vars)
                    continue
                if signed_stack_offset_for_value(runtime_value) is not None:
                    base_replacements[runtime_symbol.hash()] = (
                        runtime_symbol + translation_delta
                    )
                elif scaled_stack_transform_for_value(runtime_value) is not None:
                    unsupported_runtime_source_vars.update(runtime_vars)

            for load_inst, value_expr, load_addr_symbol, load_idx in mem_entries:
                layout = load_slot_layouts.get(load_idx)
                if layout is None:
                    continue
                word_offset, byte_offset, layout_width = layout
                if load_inst.width != 8 or layout_width != 8 or byte_offset != 0:
                    continue
                mode = sp_affine_mode(sp_affine_mem_offsets, word_offset)
                value_vars = expr_vars(value_expr)
                if mode == 'direct':
                    coefficient = 1
                elif mode == 'inverse':
                    coefficient = -1
                elif mode is None:
                    slot_value = mem_values.get(word_offset)
                    if (
                        slot_value is None
                        or signed_stack_offset_for_value(slot_value) is None
                    ):
                        continue
                    coefficient = 1
                else:
                    unsupported_runtime_source_vars.update(value_vars)
                    continue
                if any(
                    store_idx < load_idx
                    and exprs_may_be_related(store_addr_symbol, load_addr_symbol)
                    for _, store_addr_symbol, store_idx, _, _ in store_accesses
                ):
                    unsupported_runtime_source_vars.update(value_vars)
                    continue

                translated_load_addr = claripy.replace_dict(
                    load_addr_symbol,
                    base_replacements,
                )
                if not translation_identity(
                    translated_load_addr,
                    load_addr_symbol + translation_delta,
                ):
                    unsupported_runtime_source_vars.update(value_vars)
                    continue

                source_key = expr_key(value_expr)
                previous_coefficient = source_coefficients.get(source_key)
                if (
                    previous_coefficient is not None
                    and previous_coefficient != coefficient
                ):
                    unsupported_runtime_source_vars.update(value_vars)
                    source_replacements.pop(value_expr.hash(), None)
                    continue
                source_coefficients[source_key] = coefficient
                source_replacements[value_expr.hash()] = (
                    value_expr + translation_delta * expr_bvv(
                        coefficient & ((1 << 64) - 1),
                        value_expr,
                    )
                )

            if os.environ.get("RVMCA_DEBUG_REPAIR") == "1":
                DEBUG(f"linear_runtime_recipe_sources {({
                    'source_count': len(source_replacements),
                    'base_count': len(base_replacements),
                    'unsupported_vars': sorted(unsupported_runtime_source_vars),
                })}")
            if not source_replacements:
                return

            def flows_to_control(reg):
                tainted = {reg}
                for inst in prog.insts:
                    uses = set(inst.get_uses() or [])
                    if tainted & uses and inst.type in [IType.Branch, IType.Jump]:
                        return True
                    rd = inst.get_def()
                    if rd is None or rd == XREG[0]:
                        continue
                    if tainted & uses:
                        tainted.add(rd)
                    elif rd in tainted:
                        tainted.remove(rd)
                    if not tainted:
                        break
                return False

            coefficient_candidates = [
                coefficient
                for magnitude in range(2, 65)
                for coefficient in (-magnitude, magnitude)
            ]
            for reg in regs_undefined:
                if reg in reg_runtime_recipes or reg not in reg_values:
                    continue
                if reg not in base_like_regs:
                    continue
                if flows_to_control(reg):
                    continue
                symbol = reg_to_symbol.get(reg)
                symbol_vars = expr_vars(symbol)
                if not symbol_vars:
                    continue
                affected_addresses = [
                    addr_symbol
                    for _, addr_symbol, _, _ in mem_accesses
                    if expr_vars(addr_symbol) & symbol_vars
                ]
                if not affected_addresses:
                    continue
                affected_vars = set().union(*(
                    expr_vars(addr_symbol)
                    for addr_symbol in affected_addresses
                ))
                if affected_vars & unsupported_runtime_source_vars:
                    continue
                if not any(
                    expr_vars(source_expr) & affected_vars
                    for _, source_expr, _, _ in load_accesses
                    if source_expr.hash() in source_replacements
                ):
                    continue

                for coefficient in coefficient_candidates:
                    replacements = dict(base_replacements)
                    replacements.update(source_replacements)
                    replacements[symbol.hash()] = (
                        symbol + translation_delta * expr_bvv(
                            coefficient & ((1 << 64) - 1),
                            symbol,
                        )
                    )
                    if not all(
                        translation_identity(
                            claripy.replace_dict(addr_symbol, replacements),
                            addr_symbol + translation_delta,
                        )
                        for addr_symbol in affected_addresses
                    ):
                        continue

                    anchor_value = reg_values[reg] & ((1 << 64) - 1)
                    recipe = ('affine_linear', anchor_value, coefficient)
                    if _runtime_reg_recipe_value(CONCRETE_REPLAY_SP, recipe) != anchor_value:
                        continue
                    reg_runtime_recipes[reg] = recipe
                    reg_runtime_accesses[reg] = ()
                    if os.environ.get("RVMCA_DEBUG_REPAIR") == "1":
                        DEBUG(f"linear_runtime_recipe_selected {({
                            'reg': reg.name,
                            'coefficient': coefficient,
                            'affected_accesses': len(affected_addresses),
                        })}")
                    break
                else:
                    if os.environ.get("RVMCA_DEBUG_REPAIR") == "1":
                        DEBUG(f"linear_runtime_recipe_unproved {({
                            'reg': reg.name,
                            'affected_addresses': [
                                str(addr) for addr in affected_addresses
                            ],
                        })}")

        install_linear_runtime_register_recipes()

        seen_dynamic_mem_inits = set()
        store_name_for_width = {
            1: 'sb',
            2: 'sh',
            4: 'sw',
            8: 'sd',
        }
        def append_dynamic_mem_init(recipe, inst_idx, addr_const, width, is_load):
            if not is_load or width not in store_name_for_width:
                return
            layout = load_slot_layouts.get(inst_idx)
            if layout is None:
                raw_value = 0
            else:
                word_offset, byte_offset, layout_width = layout
                if layout_width != width:
                    return
                word_value = mem_values.get(word_offset, 0)
                raw_value = (
                    word_value >> (byte_offset * 8)
                ) & ((1 << (width * 8)) - 1)
            value_recipe = (
                sp_affine_mode(sp_affine_mem_offsets, layout[0])
                if layout is not None
                else None
            )
            entry = (
                recipe,
                addr_const,
                width,
                raw_value,
                value_recipe,
            )
            if entry in seen_dynamic_mem_inits:
                return
            seen_dynamic_mem_inits.add(entry)
            dynamic_mem_inits.append(entry)

            address_recipe = (
                'affine_quotient',
                recipe[1],
                recipe[2],
            )
            append_value_init(
                candidate_init,
                TEMP_REG,
                0,
                force_affine_quotient=address_recipe,
            )
            candidate_init.append(
                RFmtInst('mul', TEMP_REG, TEMP_REG, TEMP_REG2)
            )
            if addr_const:
                candidate_init.append(
                    UFmtInst('li', TEMP_REG2, abs(addr_const))
                )
                candidate_init.append(RFmtInst(
                    'add' if addr_const > 0 else 'sub',
                    TEMP_REG,
                    TEMP_REG,
                    TEMP_REG2,
                ))
            value_stack_offset = stack_offset_for_value(raw_value)
            value_force_sp_delta = None
            value_force_inverse_sp_delta = None
            value_force_scaled_stack = None
            if value_recipe == 'direct':
                value_force_sp_delta = (
                    raw_value - CONCRETE_REPLAY_SP
                ) & ((1 << 64) - 1)
            elif value_recipe == 'inverse':
                value_force_inverse_sp_delta = (
                    raw_value + CONCRETE_REPLAY_SP
                ) & ((1 << 64) - 1)
            elif (
                isinstance(value_recipe, (tuple, list))
                and len(value_recipe) == 3
                and value_recipe[0] == 'scaled'
            ):
                value_force_scaled_stack = (
                    int(value_recipe[1]),
                    int(value_recipe[2]),
                )
            append_value_init(
                candidate_init,
                TEMP_REG2,
                raw_value,
                force_stack_offset=value_stack_offset,
                force_sp_delta=value_force_sp_delta,
                force_inverse_sp_delta=value_force_inverse_sp_delta,
                force_scaled_stack=value_force_scaled_stack,
            )
            candidate_init.append(StoreInst(
                store_name_for_width[width],
                TEMP_REG2,
                TEMP_REG,
                0,
            ))

        for reg, recipe in reg_runtime_recipes.items():
            for access in reg_runtime_accesses.get(reg, ()):
                append_dynamic_mem_init(recipe, *access)

        for recipe, accesses in loaded_affine_quotient_runtime_accesses.values():
            for access in accesses:
                append_dynamic_mem_init(recipe, *access)

        reg_init = rebuild_register_init()
        candidate_init.extend(reg_init)
        return (
            candidate_init,
            reg_values,
            mem_values,
            mem_offset_addr_symbols,
            candidate_solver,
            sp_affine_mem_offsets,
            reg_runtime_recipes,
            dynamic_mem_inits,
        )

    def find_alias_constraints(
        reg_values,
        mem_values,
        mem_offset_addr_symbols,
        constraint_solver,
        sp_value=CONCRETE_REPLAY_SP,
        sp_affine_mem_offsets=None,
        reg_runtime_recipes=None,
        dynamic_mem_inits=None,
    ):
        alias_same_address_cache = {}

        def same_address(addr_a, addr_b):
            if addr_b is None:
                return False
            key = (str(addr_a), str(addr_b))
            if key[0] == key[1]:
                return True
            if key in alias_same_address_cache:
                return alias_same_address_cache[key]
            if not (getattr(addr_a, 'variables', set()) & getattr(addr_b, 'variables', set())):
                alias_same_address_cache[key] = False
                return False
            test_solver = constraint_solver.branch()
            test_solver.timeout = (
                100
                if len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
                else 1000
            )
            try:
                test_solver.add(addr_a != addr_b)
                result = not test_solver.satisfiable()
            except Exception:
                result = False
            alias_same_address_cache[key] = result
            return result

        constraints = []
        mem_offsets = sorted(mem_values.keys())
        prefix_states = replay_prefix_states(
            reg_values,
            mem_values,
            sp_value=sp_value,
            sp_affine_mem_offsets=sp_affine_mem_offsets,
            reg_runtime_recipes=reg_runtime_recipes,
            dynamic_mem_inits=dynamic_mem_inits,
        )

        concrete_access_cache = {}

        def concrete_access_addr(inst, inst_idx):
            if inst_idx in concrete_access_cache:
                return concrete_access_cache[inst_idx]
            state = prefix_states.get(original_access_addr(inst_idx)) if prefix_states is not None else None
            if state is None:
                concrete_access_cache[inst_idx] = None
                return None
            try:
                value = (state.solver.eval(getattr(state.regs, str(inst.rs1))) + inst.imm) & ((1 << 64) - 1)
            except Exception:
                value = None
            concrete_access_cache[inst_idx] = value
            return value

        def has_later_concrete_same_addr_load(store_idx, concrete_store_addr):
            for load_inst, _, _, load_idx in mem_entries:
                if load_idx <= store_idx:
                    continue
                concrete_load_addr = concrete_access_addr(load_inst, load_idx)
                if concrete_load_addr == concrete_store_addr:
                    return True
            return False

        for store_inst, store_addr_symbol, store_inst_idx, store_width, _ in store_accesses:
            store_addr = original_access_addr(store_inst_idx)
            store_state = prefix_states.get(store_addr) if prefix_states is not None else None
            if store_state is None:
                continue

            concrete_store_addr = store_state.solver.eval(getattr(store_state.regs, str(store_inst.rs1))) \
                                  + store_inst.imm
            concrete_store_offset = (sp_value - concrete_store_addr) & ((1 << 64) - 1)
            store_feeds_later_load = None
            for mem_offset in mem_offsets:
                if not concrete_ranges_overlap(concrete_store_offset, store_width, mem_offset, 8):
                    continue
                if any(same_address(store_addr_symbol, addr_symbol)
                       for addr_symbol in mem_offset_addr_symbols.get(mem_offset, [])):
                    continue
                if store_feeds_later_load is None:
                    store_feeds_later_load = has_later_concrete_same_addr_load(
                        store_inst_idx,
                        concrete_store_addr & ((1 << 64) - 1),
                    )
                if store_feeds_later_load:
                    continue
                constraints.append(symbolic_no_overlap(store_addr_symbol, store_width, mem_offset))

        return constraints

    def find_store_pointer_constraints(
        reg_values,
        mem_values,
        constraint_solver,
        sp_value=CONCRETE_REPLAY_SP,
        sp_affine_mem_offsets=None,
        reg_runtime_recipes=None,
        dynamic_mem_inits=None,
    ):
        constraints = []
        seen_loads = set()
        protected_idx = last_prefix_fail_info.get('protected_access_idx')
        failing_address_vars = set()
        if protected_idx is not None:
            for _, addr_symbol, inst_idx, _ in mem_accesses:
                if inst_idx == protected_idx:
                    failing_address_vars.update(
                        getattr(addr_symbol, 'variables', set())
                    )
                    break

        candidate_loads = list(pointer_source_loads + address_source_loads)
        candidate_load_keys = {
            (entry[3], stable_expr_key(entry[1]))
            for entry in candidate_loads
        }
        for entry in mem_entries:
            rd_vars = set(getattr(entry[1], 'variables', set()))
            key = (entry[3], stable_expr_key(entry[1]))
            if (
                rd_vars & failing_address_vars
                and key not in candidate_load_keys
            ):
                candidate_loads.append(entry)
                candidate_load_keys.add(key)

        prefix_states = replay_prefix_states(
            reg_values,
            mem_values,
            sp_value=sp_value,
            sp_affine_mem_offsets=sp_affine_mem_offsets,
            reg_runtime_recipes=reg_runtime_recipes,
            dynamic_mem_inits=dynamic_mem_inits,
        )
        for load_inst, rd_symbol, load_addr_symbol, load_idx in candidate_loads:
            rd_vars = set(getattr(rd_symbol, 'variables', set()))
            feeds_failing_address = bool(rd_vars & failing_address_vars)
            if (
                (load_idx, stable_expr_key(rd_symbol)) in scalar_load_hint_keys
                and not feeds_failing_address
            ):
                continue
            load_key = (load_idx, str(rd_symbol), str(load_addr_symbol))
            if load_key in seen_loads:
                continue
            seen_loads.add(load_key)
            load_addr = original_access_addr(load_idx)
            load_state = prefix_states.get(load_addr) if prefix_states is not None else None
            if load_state is None:
                continue
            concrete_load_addr = load_state.solver.eval(getattr(load_state.regs, str(load_inst.rs1))) + load_inst.imm
            concrete_load_offset = (sp_value - concrete_load_addr) & ((1 << 64) - 1)
            min_offset = min_pointer_offset_for_vars(
                rd_vars,
                load_idx,
                avoid_ranges=[(concrete_load_offset, load_inst.width)],
            )
            pointer_like_load = any(
                p_idx == load_idx and bool(getattr(p_rd, 'variables', set()) & rd_vars)
                for _, p_rd, _, p_idx in pointer_source_loads
            ) or load_value_directly_feeds_pointer_access(load_inst, rd_symbol, load_idx)
            if feeds_failing_address and not failing_address_vars <= rd_vars:
                pointer_like_load = False

            def stored_expr_can_feed_pointer(stored_expr):
                if not pointer_like_load:
                    return True
                stored_value = concrete_expr_value(stored_expr)
                if stored_value is not None:
                    stored_offset = stack_offset_for_value(stored_value)
                    return (
                        stored_offset is not None
                        and stored_offset >= min_offset
                        and stored_offset <= STACK_RANGE
                    )
                stored_vars = getattr(stored_expr, 'variables', set())
                if not stored_vars:
                    return False
                test_solver = constraint_solver.branch()
                test_solver.timeout = 1000
                try:
                    for constraint in stack_pointer_constraints_for_expr(stored_expr, min_offset):
                        test_solver.add(constraint)
                    return test_solver.satisfiable()
                except Exception:
                    return True

            for store_inst, store_addr_symbol, store_idx, store_width, store_data_symbol in reversed(store_accesses):
                if store_idx >= load_idx:
                    continue
                store_addr = original_access_addr(store_idx)
                store_state = prefix_states.get(store_addr) if prefix_states is not None else None
                if store_state is None:
                    continue
                concrete_store_addr = store_state.solver.eval(getattr(store_state.regs, str(store_inst.rs1))) + store_inst.imm
                concrete_store_offset = (sp_value - concrete_store_addr) & ((1 << 64) - 1)
                if not concrete_ranges_overlap(concrete_store_offset, store_width, concrete_load_offset, load_inst.width):
                    continue
                stored_expr = stored_value_for_load_expr(store_data_symbol, store_width, load_inst)
                if stored_expr is not None:
                    if not stored_expr_can_feed_pointer(stored_expr):
                        if not forced_same_address(store_addr_symbol, load_addr_symbol, constraint_solver):
                            constraints.append(
                                symbolic_access_no_overlap(
                                    store_addr_symbol,
                                    store_width,
                                    load_addr_symbol,
                                    load_inst.width,
                                )
                            )
                        break
                    constraints.append(rd_symbol == stored_expr)
                    if pointer_like_load and getattr(stored_expr, 'variables', set()):
                        constraints.extend(stack_pointer_constraints_for_expr(stored_expr, min_offset))
                    break
                if not forced_same_address(store_addr_symbol, load_addr_symbol, constraint_solver):
                    constraints.append(symbolic_access_no_overlap(store_addr_symbol, store_width, load_addr_symbol, load_inst.width))
                    break
        return constraints

    def find_pointer_slot_store_constraints(
        reg_values,
        mem_values,
        constraint_solver,
        sp_value=CONCRETE_REPLAY_SP,
        sp_affine_mem_offsets=None,
        reg_runtime_recipes=None,
        dynamic_mem_inits=None,
    ):
        constraints = []
        prefix_states = replay_prefix_states(
            reg_values,
            mem_values,
            sp_value=sp_value,
            sp_affine_mem_offsets=sp_affine_mem_offsets,
            reg_runtime_recipes=reg_runtime_recipes,
            dynamic_mem_inits=dynamic_mem_inits,
        )
        for load_inst, rd_symbol, load_addr_symbol, load_idx in pointer_source_loads:
            pointer_vars = getattr(rd_symbol, 'variables', set())
            load_addr_key = stable_expr_key(load_addr_symbol)
            same_addr_loads = [
                entry
                for entry in mem_entries
                if (
                    entry[3] <= load_idx
                    and entry[0].width == load_inst.width
                    and stable_expr_key(entry[2]) == load_addr_key
                )
            ]
            first_same_addr_load = min(
                same_addr_loads,
                key=lambda entry: entry[3],
                default=(load_inst, rd_symbol, load_addr_symbol, load_idx),
            )
            first_same_addr_inst, _, _, first_same_addr_load_idx = first_same_addr_load
            last_use_idx = load_idx
            for _, addr_symbol, access_idx, _ in mem_accesses:
                if access_idx <= load_idx:
                    continue
                if getattr(addr_symbol, 'variables', set()) & pointer_vars:
                    last_use_idx = max(last_use_idx, access_idx)
            if last_use_idx <= load_idx:
                continue
            load_addr = original_access_addr(first_same_addr_load_idx)
            load_state = prefix_states.get(load_addr) if prefix_states is not None else None
            if load_state is None:
                continue
            concrete_load_addr = (
                load_state.solver.eval(
                    getattr(load_state.regs, str(first_same_addr_inst.rs1))
                )
                + first_same_addr_inst.imm
            )
            concrete_load_offset = (sp_value - concrete_load_addr) & ((1 << 64) - 1)
            repeated_source = first_same_addr_load_idx < load_idx
            for store_inst, store_addr_symbol, store_idx, store_width, _ in store_accesses:
                if store_idx <= first_same_addr_load_idx or store_idx > last_use_idx:
                    continue
                if repeated_source:
                    if forced_same_address(store_addr_symbol, load_addr_symbol, constraint_solver):
                        continue
                    constraints.append(
                        symbolic_access_no_overlap(
                            store_addr_symbol,
                            store_width,
                            load_addr_symbol,
                            init_slot_width(load_inst.width),
                        )
                    )
                    continue
                store_addr = original_access_addr(store_idx)
                store_state = prefix_states.get(store_addr) if prefix_states is not None else None
                if store_state is None:
                    continue
                concrete_store_addr = store_state.solver.eval(getattr(store_state.regs, str(store_inst.rs1))) + store_inst.imm
                concrete_store_offset = (sp_value - concrete_store_addr) & ((1 << 64) - 1)
                if concrete_ranges_overlap(
                    concrete_store_offset,
                    store_width,
                    concrete_load_offset,
                    init_slot_width(load_inst.width),
                ):
                    if forced_same_address(store_addr_symbol, load_addr_symbol, constraint_solver):
                        continue
                    constraints.append(
                        symbolic_access_no_overlap(
                            store_addr_symbol,
                            store_width,
                            load_addr_symbol,
                            init_slot_width(load_inst.width),
                        )
                    )
        return constraints

    def find_replay_access_constraints(
        reg_values,
        mem_values,
        constraint_solver,
        sp_value=CONCRETE_REPLAY_SP,
        sp_affine_mem_offsets=None,
        reg_runtime_recipes=None,
        dynamic_mem_inits=None,
    ):
        def translation_covariant_register_constraints(addr_symbol):
            addr_vars = set(getattr(addr_symbol, 'variables', set()))
            contributors = [
                (reg, symbol)
                for reg, symbol in reg_to_symbol.items()
                if (
                    symbol.size() == 64
                    and (set(getattr(symbol, 'variables', set())) & addr_vars)
                )
            ]
            if not contributors or len(contributors) > 6:
                return []

            delta = claripy.BVS("rvmca_replay_translation_delta", 64)
            # A single contributor is already covered by the address range
            # constraint itself.  Extra anchoring is only needed when two or
            # more live-ins must translate together through truncation.
            for group_size in range(2, min(3, len(contributors)) + 1):
                for group in combinations(contributors, group_size):
                    replacements = {
                        symbol.hash(): symbol + delta
                        for _, symbol in group
                    }
                    translated = claripy.replace_dict(
                        addr_symbol,
                        replacements,
                    )
                    covariance = claripy.simplify(
                        translated == addr_symbol + delta
                    )
                    if not claripy.is_true(covariance):
                        continue

                    constraints = []
                    for _, symbol in group:
                        offset_expr = init_sp - symbol
                        constraints.extend([
                            claripy.UGE(offset_expr, claripy.BVV(1, 64)),
                            claripy.ULE(
                                offset_expr,
                                claripy.BVV(STACK_RANGE, 64),
                            ),
                        ])
                    return constraints
            return []

        constraints = []
        prefix_states = replay_prefix_states(
            reg_values,
            mem_values,
            sp_value=sp_value,
            sp_affine_mem_offsets=sp_affine_mem_offsets,
            reg_runtime_recipes=reg_runtime_recipes,
            dynamic_mem_inits=dynamic_mem_inits,
        )
        for inst, addr_symbol, inst_idx, width in mem_accesses:
            access_addr = original_access_addr(inst_idx)
            access_state = prefix_states.get(access_addr) if prefix_states is not None else None
            if access_state is None:
                continue

            concrete_addr = access_state.solver.eval(getattr(access_state.regs, str(inst.rs1))) + inst.imm
            concrete_offset = (sp_value - concrete_addr) & ((1 << 64) - 1)
            bad_range = concrete_addr >= sp_value or concrete_offset > STACK_RANGE
            bad_align = width > 1 and (concrete_addr & (width - 1)) != 0
            if bad_range:
                offset_expr = init_sp - addr_symbol
                range_constraints = [
                    claripy.UGE(offset_expr, claripy.BVV(width, 64)),
                    claripy.ULE(offset_expr, claripy.BVV(STACK_RANGE, 64)),
                ]
                constraints.extend(range_constraints)
                constraints.extend(
                    translation_covariant_register_constraints(addr_symbol)
                )
            if bad_align:
                constraints.append((addr_symbol & (width - 1)) == 0)

        protected_idx = last_prefix_fail_info.get('protected_access_idx')
        protected_offset_text = last_prefix_fail_info.get('protected_access_offset')
        protected_kind = last_prefix_fail_info.get('protected_access_kind')
        failed_access_idx = last_prefix_fail_info.get('inst_idx')
        if failed_access_idx is not None:
            failed_pointer_load_indices = []
            for load_inst, rd_symbol, load_addr_symbol, load_idx in mem_entries:
                if load_idx == failed_access_idx and load_inst.width == 8:
                    failed_pointer_load_indices.append(load_idx)
            if not failed_pointer_load_indices:
                failed_mem_inst = None
                for inst, _, inst_idx, _ in mem_accesses:
                    if inst_idx == failed_access_idx:
                        failed_mem_inst = inst
                        break
                failed_base_reg = getattr(failed_mem_inst, 'rs1', None)
                if failed_base_reg is not None:
                    for load_inst, rd_symbol, _, load_idx in reversed(mem_entries):
                        if load_idx >= failed_access_idx or load_inst.width != 8:
                            continue
                        if getattr(load_inst, 'rd', None) != failed_base_reg:
                            continue
                        failed_pointer_load_indices.append(load_idx)
                        break
            for load_inst, rd_symbol, load_addr_symbol, load_idx in mem_entries:
                if load_idx not in failed_pointer_load_indices or load_inst.width != 8:
                    continue
                if (
                    load_idx == failed_access_idx
                    and not load_value_directly_feeds_pointer_access(load_inst, rd_symbol, load_idx)
                ):
                    break
                min_offset = min_pointer_offset_for_vars(
                    set(getattr(rd_symbol, 'variables', set())),
                    load_idx,
                )
                for store_inst, store_addr_symbol, store_idx, store_width, store_data_symbol in reversed(store_accesses):
                    if store_idx >= load_idx:
                        continue
                    store_addr = original_access_addr(store_idx)
                    store_state = prefix_states.get(store_addr) if prefix_states is not None else None
                    if store_state is None:
                        continue
                    try:
                        concrete_store_addr = (
                            store_state.solver.eval(getattr(store_state.regs, str(store_inst.rs1)))
                            + store_inst.imm
                        ) & ((1 << 64) - 1)
                    except Exception:
                        continue
                    load_addr = original_access_addr(load_idx)
                    load_state = prefix_states.get(load_addr) if prefix_states is not None else None
                    if load_state is None:
                        continue
                    try:
                        concrete_load_addr = (
                            load_state.solver.eval(getattr(load_state.regs, str(load_inst.rs1)))
                            + load_inst.imm
                        ) & ((1 << 64) - 1)
                    except Exception:
                        continue
                    if not concrete_ranges_overlap(
                        (sp_value - concrete_store_addr) & ((1 << 64) - 1),
                        store_width,
                        (sp_value - concrete_load_addr) & ((1 << 64) - 1),
                        load_inst.width,
                    ):
                        continue
                    stored_expr = stored_value_for_load_expr(
                        store_data_symbol,
                        store_width,
                        load_inst,
                    )
                    if stored_expr is None:
                        continue
                    target_offset = _align_up(
                        max(INIT_PTR_MIN_OFFSET, min_offset),
                        INIT_ACCESS_ALIGN,
                    )
                    if target_offset > STACK_RANGE:
                        target_offset = STACK_RANGE
                    constraints.append(
                        (init_sp - stored_expr)
                        == claripy.BVV(
                            target_offset & ((1 << stored_expr.size()) - 1),
                            stored_expr.size(),
                        )
                    )
                    break
                break
        if protected_idx is not None and protected_offset_text is not None:
            try:
                protected_offset = int(protected_offset_text, 16)
            except Exception:
                protected_offset = None
            if protected_offset is not None:
                for inst, addr_symbol, inst_idx, width in mem_accesses:
                    if inst_idx != protected_idx:
                        continue
                    offset_expr = init_sp - addr_symbol
                    range_constraints = [
                        claripy.UGE(offset_expr, claripy.BVV(max(width, 1), 64)),
                        claripy.ULE(offset_expr, claripy.BVV(STACK_RANGE, 64)),
                    ]
                    constraints.extend(range_constraints)
                    constraints.extend(
                        translation_covariant_register_constraints(addr_symbol)
                    )
                    if width > 1:
                        constraints.append((addr_symbol & (width - 1)) == 0)

                    if protected_kind == 'store':
                        for load_inst, _, load_addr_symbol, load_idx in mem_entries:
                            if load_idx <= inst_idx:
                                continue
                            if forced_same_address(
                                addr_symbol,
                                load_addr_symbol,
                                constraint_solver,
                            ):
                                continue
                            constraints.append(
                                symbolic_access_no_overlap(
                                    addr_symbol,
                                    width,
                                    load_addr_symbol,
                                    init_slot_width(load_inst.width),
                                )
                            )
                    break

        return constraints

    def find_narrow_pointer_alias_constraints(
        reg_values,
        mem_values,
        mem_offset_addr_symbols,
        check_planned_slots=False,
        sp_value=CONCRETE_REPLAY_SP,
        sp_affine_mem_offsets=None,
        reg_runtime_recipes=None,
        dynamic_mem_inits=None,
    ):
        constraints = []
        scalar_loads = []
        pointer_loads = []

        for load_inst, rd_symbol, addr_symbol, load_idx in mem_entries:
            rd_vars = getattr(rd_symbol, 'variables', set())
            if not rd_vars:
                continue
            used_in_later_addr = any(
                access_idx > load_idx and (getattr(later_addr, 'variables', set()) & rd_vars)
                for _, later_addr, access_idx, _ in mem_accesses
            )
            if load_inst.width < 8 and load_inst.pc not in load_nonzero_hints and used_in_later_addr:
                scalar_loads.append((load_inst, addr_symbol, load_idx))
            elif (
                load_inst.width == 8
                and used_in_later_addr
                and (
                    rd_vars & pointer_loaded_addr_vars
                    or load_inst.pc in load_pointer_hints
                    or (load_idx, stable_expr_key(rd_symbol)) not in scalar_load_hint_keys
                )
            ):
                pointer_loads.append((load_inst, addr_symbol, load_idx))

        if not scalar_loads or not pointer_loads:
            return constraints

        concrete_addrs = {}
        prefix_states = replay_prefix_states(
            reg_values,
            mem_values,
            sp_value=sp_value,
            sp_affine_mem_offsets=sp_affine_mem_offsets,
            reg_runtime_recipes=reg_runtime_recipes,
            dynamic_mem_inits=dynamic_mem_inits,
        )

        def concrete_addr_from_materialized(addr_symbol):
            substitutions = {}
            for reg, value in reg_values.items():
                symbol = reg_to_symbol.get(reg)
                if symbol is None:
                    continue
                substitutions[str(claripy.simplify(symbol))] = claripy.BVV(
                    value & ((1 << symbol.size()) - 1),
                    symbol.size(),
                )
            substitutions[str(claripy.simplify(init_sp))] = claripy.BVV(
                CONCRETE_REPLAY_SP & ((1 << init_sp.size()) - 1),
                init_sp.size(),
            )

            cache = {}

            def substitute(node):
                if not hasattr(node, 'op'):
                    return node
                node_key = str(claripy.simplify(node))
                if node_key in substitutions:
                    return substitutions[node_key]
                cache_key = id(node)
                if cache_key in cache:
                    return cache[cache_key]
                changed = False
                new_args = []
                for arg in getattr(node, 'args', ()):
                    new_arg = substitute(arg)
                    if new_arg is not arg:
                        changed = True
                    new_args.append(new_arg)
                result = claripy.simplify(node.make_like(node.op, tuple(new_args))) if changed else node
                cache[cache_key] = result
                return result

            substituted = claripy.simplify(substitute(addr_symbol))
            if getattr(substituted, 'variables', set()):
                return None
            concrete_value = getattr(substituted, 'concrete_value', None)
            if isinstance(concrete_value, int):
                return concrete_value & ((1 << 64) - 1)
            try:
                solver = claripy.Solver()
                return solver.eval(substituted, 1)[0] & ((1 << 64) - 1)
            except Exception:
                return None

        def concrete_load_addr(load_inst, addr_symbol, load_idx):
            key = load_idx
            if key in concrete_addrs:
                return concrete_addrs[key]
            access_addr = original_access_addr(load_idx)
            state = prefix_states.get(access_addr) if prefix_states is not None else None
            if state is None:
                default_sp_addr = concrete_addr_from_materialized(addr_symbol)
                if default_sp_addr is None:
                    concrete_addrs[key] = None
                    return None
                default_offset = (CONCRETE_REPLAY_SP - default_sp_addr) & ((1 << 64) - 1)
                if default_offset > STACK_RANGE:
                    concrete_addrs[key] = None
                    return None
                concrete_addrs[key] = (sp_value - default_offset) & ((1 << 64) - 1)
                return concrete_addrs[key]
            concrete_addr = state.solver.eval(getattr(state.regs, str(load_inst.rs1))) + load_inst.imm
            concrete_addrs[key] = concrete_addr & ((1 << 64) - 1)
            return concrete_addrs[key]

        seen = set()
        used_slots = set(mem_values)
        for load_inst, addr_symbol, load_idx in [
            (entry[0], entry[2], entry[3])
            for entry in mem_entries
        ]:
            concrete_addr = concrete_load_addr(load_inst, addr_symbol, load_idx)
            if concrete_addr is None:
                continue
            used_slots.add(((sp_value - concrete_addr) + 7) & ~7)

        planned_slots_by_addr = {}
        if check_planned_slots:
            for slot_offset, addr_symbols in mem_offset_addr_symbols.items():
                for addr_symbol in addr_symbols:
                    planned_slots_by_addr.setdefault(
                        stable_expr_key(addr_symbol),
                        set(),
                    ).add(slot_offset)

        def next_unused_slot(exclude_slot):
            offset = INIT_ACCESS_ALIGN
            while offset <= STACK_RANGE:
                if offset != exclude_slot and offset not in used_slots:
                    return offset
                offset += INIT_ACCESS_ALIGN
            return None

        for pointer_inst, pointer_addr_symbol, pointer_idx in pointer_loads:
            pointer_addr = concrete_load_addr(pointer_inst, pointer_addr_symbol, pointer_idx)
            planned_pointer_slots = planned_slots_by_addr.get(
                stable_expr_key(pointer_addr_symbol),
                set(),
            )
            if pointer_addr is None and not planned_pointer_slots:
                continue
            actual_pointer_slot = (
                ((sp_value - pointer_addr) + 7) & ~7
                if pointer_addr is not None
                else None
            )
            for scalar_inst, scalar_addr_symbol, scalar_idx in scalar_loads:
                scalar_addr = concrete_load_addr(scalar_inst, scalar_addr_symbol, scalar_idx)
                if scalar_addr is None:
                    continue
                scalar_slot = ((sp_value - scalar_addr) + 7) & ~7
                colliding_pointer_slots = {
                    pointer_slot
                    for pointer_slot in planned_pointer_slots
                    if pointer_slot == scalar_slot
                }
                if actual_pointer_slot == scalar_slot:
                    colliding_pointer_slots.add(actual_pointer_slot)
                if not colliding_pointer_slots:
                    continue
                key = (pointer_idx, scalar_idx)
                if key in seen:
                    continue
                seen.add(key)
                constraints.append(symbolic_init_slots_no_overlap(pointer_addr_symbol, scalar_addr_symbol))
                target_slot = next_unused_slot(min(colliding_pointer_slots))
                if target_slot is not None:
                    constraints.append(
                        (init_sp - scalar_addr_symbol) == claripy.BVV(target_slot, 64)
                    )

        return constraints

    active_repair_constraints = []
    repair_timeout_ms = max(HEURISTIC_SOLVER_TIMEOUT_MS, 1000)

    def repair_constraint_key(constraint):
        return str(claripy.simplify(constraint))

    def build_solver_from_active_repair():
        solver = base_solver.branch()
        for constraint in active_repair_constraints:
            solver.add(constraint)
        return solver

    def active_repair_satisfiable(constraints):
        test_solver = base_solver.branch()
        test_solver.timeout = repair_timeout_ms
        try:
            for constraint in constraints:
                test_solver.add(constraint)
            return test_solver.satisfiable()
        except Exception:
            return None

    def add_repair_constraints_checked(solver, constraints, label):
        unique_constraints = []
        seen_constraints = set()
        existing_constraints = {repair_constraint_key(constraint) for constraint in active_repair_constraints}
        for constraint in constraints:
            key = repair_constraint_key(constraint)
            if key in seen_constraints or key in existing_constraints:
                continue
            seen_constraints.add(key)
            unique_constraints.append(constraint)
        if not unique_constraints:
            return solver, 0

        batch_solver = solver.branch()
        batch_solver.timeout = repair_timeout_ms
        try:
            for constraint in unique_constraints:
                batch_solver.add(constraint)
            if batch_solver.satisfiable():
                for constraint in unique_constraints:
                    solver.add(constraint)
                    active_repair_constraints.append(constraint)
                return solver, len(unique_constraints)
        except Exception:
            pass

        added = 0
        for constraint in unique_constraints:
            test_solver = solver.branch()
            test_solver.timeout = repair_timeout_ms
            try:
                test_solver.add(constraint)
                sat = test_solver.satisfiable()
            except Exception:
                sat = None
            if sat is False:
                replacement_done = False
                constraint_vars = getattr(constraint, 'variables', set())
                for old_idx in range(len(active_repair_constraints) - 1, -1, -1):
                    old_constraint = active_repair_constraints[old_idx]
                    old_vars = getattr(old_constraint, 'variables', set())
                    if constraint_vars and old_vars and not (constraint_vars & old_vars):
                        continue
                    trial_constraints = (
                        active_repair_constraints[:old_idx]
                        + active_repair_constraints[old_idx + 1:]
                        + [constraint]
                    )
                    trial_sat = active_repair_satisfiable(trial_constraints)
                    if trial_sat is not True:
                        continue
                    if os.environ.get("RVMCA_DEBUG_REPAIR") == "1":
                        DEBUG(f"repair_constraint_replace {label} old={repair_constraint_key(old_constraint)[:600]} new={repair_constraint_key(constraint)[:600]}")
                    active_repair_constraints[:] = trial_constraints
                    solver = build_solver_from_active_repair()
                    added += 1
                    replacement_done = True
                    break
                if not replacement_done:
                    if os.environ.get("RVMCA_DEBUG_REPAIR") == "1":
                        DEBUG(f"repair_constraint_skip_unsat {label} {repair_constraint_key(constraint)[:1200]}")
                    continue
                continue
            solver.add(constraint)
            active_repair_constraints.append(constraint)
            added += 1
        return solver, added

    current_solver = base_solver.branch()
    for retry in range(MAX_INIT_SOLVE_RETRIES + 1):
        _write_profile_stage(name, f"init:solve_retry_{retry}:satisfiability")
        try:
            (
                candidate_init,
                reg_values,
                mem_values,
                mem_offset_addr_symbols,
                candidate_solver,
                sp_affine_mem_offsets,
                reg_runtime_recipes,
                dynamic_mem_inits,
            ) = materialize_init(current_solver, retry)
        except AssertionError as exc:
            message = str(exc)
            retryable_materialize_failure = any(
                marker in message
                for marker in (
                    "cannot choose load slot address",
                    "cannot choose stack pointer value",
                    "cannot choose non-overlapping concrete value",
                    "cannot choose concrete value",
                )
            )
            if retryable_materialize_failure and retry < MAX_INIT_SOLVE_RETRIES:
                if os.environ.get("RVMCA_DEBUG_REPAIR") == "1":
                    DEBUG(f"materialize_retry retry={retry} error={message}")
                _write_profile_stage(
                    name,
                    f"init:solve_retry_{retry}:materialize_retry",
                    error=message[:240],
                )
                continue
            raise
        _write_profile_stage(name, f"init:solve_retry_{retry}:concrete_replay")
        failed_replay_sp = None
        replay_sps = (
            [CONCRETE_REPLAY_SP]
            if len(mem_entries) >= GLOBAL_NO_OVERLAP_LOAD_THRESHOLD
            else CONCRETE_REPLAY_ALT_SPS
        )
        for replay_sp in replay_sps:
            replay_prefix_context.clear()
            replay_prefix_context.update({
                'retry': retry,
                'phase': 'validate',
            })
            _write_profile_stage(
                name,
                f"init:solve_retry_{retry}:concrete_replay_sp",
                sp=hex(replay_sp),
            )
            if replay_concrete_init(
                reg_values,
                mem_values,
                debug=verbose,
                sp_value=replay_sp,
                sp_affine_mem_offsets=sp_affine_mem_offsets,
                reg_runtime_recipes=reg_runtime_recipes,
                dynamic_mem_inits=dynamic_mem_inits,
            ) is None:
                failed_replay_sp = replay_sp
                break
        if failed_replay_sp is None:
            replay_prefix_context.clear()
            replay_prefix_context.update({
                'retry': retry,
                'phase': 'pp_alias',
            })
            _write_profile_stage(name, f"init:solve_retry_{retry}:pp_alias_constraints")
            pp_alias_constraints = find_narrow_pointer_alias_constraints(
                reg_values,
                mem_values,
                mem_offset_addr_symbols,
                sp_value=CONCRETE_REPLAY_SP,
                sp_affine_mem_offsets=sp_affine_mem_offsets,
                reg_runtime_recipes=reg_runtime_recipes,
                dynamic_mem_inits=dynamic_mem_inits,
            )
            if os.environ.get("RVMCA_DEBUG_REPAIR") == "1" and pp_alias_constraints:
                DEBUG(f"pp_alias_repair_constraints {({
                    'retry': retry,
                    'count': len(pp_alias_constraints),
                    'constraints': [str(claripy.simplify(c)) for c in pp_alias_constraints[:12]],
                })}")
            if pp_alias_constraints and retry < MAX_INIT_SOLVE_RETRIES:
                current_solver, added = add_repair_constraints_checked(
                    current_solver,
                    pp_alias_constraints,
                    "pp_alias",
                )
                if added:
                    continue
            _write_profile_stage(name, f"init:solve_retry_{retry}:pp_alias_constraints:done")
            _write_profile_stage(name, "init:done")
            return candidate_init

        _write_profile_stage(name, f"init:solve_retry_{retry}:derive_replay_constraints")
        replay_prefix_context.clear()
        replay_prefix_context.update({
            'retry': retry,
            'phase': 'replay_repair',
        })
        _write_profile_stage(name, f"init:solve_retry_{retry}:derive_replay_constraints:alias")
        alias_constraints = find_alias_constraints(
            reg_values,
            mem_values,
            mem_offset_addr_symbols,
            current_solver,
            sp_value=failed_replay_sp,
            sp_affine_mem_offsets=sp_affine_mem_offsets,
            reg_runtime_recipes=reg_runtime_recipes,
            dynamic_mem_inits=dynamic_mem_inits,
        )
        _write_profile_stage(name, f"init:solve_retry_{retry}:derive_replay_constraints:store_pointer")
        alias_constraints.extend(find_store_pointer_constraints(
            reg_values,
            mem_values,
            current_solver,
            sp_value=failed_replay_sp,
            sp_affine_mem_offsets=sp_affine_mem_offsets,
            reg_runtime_recipes=reg_runtime_recipes,
            dynamic_mem_inits=dynamic_mem_inits,
        ))
        _write_profile_stage(name, f"init:solve_retry_{retry}:derive_replay_constraints:pointer_slot_store")
        alias_constraints.extend(find_pointer_slot_store_constraints(
            reg_values,
            mem_values,
            current_solver,
            sp_value=failed_replay_sp,
            sp_affine_mem_offsets=sp_affine_mem_offsets,
            reg_runtime_recipes=reg_runtime_recipes,
            dynamic_mem_inits=dynamic_mem_inits,
        ))
        _write_profile_stage(name, f"init:solve_retry_{retry}:derive_replay_constraints:replay_access")
        alias_constraints.extend(find_replay_access_constraints(
            reg_values,
            mem_values,
            current_solver,
            sp_value=failed_replay_sp,
            sp_affine_mem_offsets=sp_affine_mem_offsets,
            reg_runtime_recipes=reg_runtime_recipes,
            dynamic_mem_inits=dynamic_mem_inits,
        ))
        _write_profile_stage(name, f"init:solve_retry_{retry}:derive_replay_constraints:narrow_pointer_alias")
        alias_constraints.extend(find_narrow_pointer_alias_constraints(
            reg_values,
            mem_values,
            mem_offset_addr_symbols,
            check_planned_slots=True,
            sp_value=failed_replay_sp,
            sp_affine_mem_offsets=sp_affine_mem_offsets,
            reg_runtime_recipes=reg_runtime_recipes,
            dynamic_mem_inits=dynamic_mem_inits,
        ))
        if os.environ.get("RVMCA_DEBUG_REPAIR") == "1" and alias_constraints:
            DEBUG(f"replay_repair_constraints {({
                'retry': retry,
                'failed_sp': hex(failed_replay_sp),
                'count': len(alias_constraints),
                'constraints': [str(claripy.simplify(c)) for c in alias_constraints[:16]],
            })}")
        if not alias_constraints or retry == MAX_INIT_SOLVE_RETRIES:
            replay_detail = f" detail={last_prefix_fail_info}" if last_prefix_fail_info else ""
            raise ConcreteReplayFailure(
                f"[ERROR]: {name} concrete replay fails after init solving{replay_detail}",
                candidate_init=candidate_init,
            )

        current_solver, added = add_repair_constraints_checked(
            current_solver,
            alias_constraints,
            "replay",
        )
        if not added:
            replay_detail = f" detail={last_prefix_fail_info}" if last_prefix_fail_info else ""
            raise ConcreteReplayFailure(
                f"[ERROR]: {name} concrete replay fails after init solving{replay_detail}",
                candidate_init=candidate_init,
            )

    raise ConcreteReplayFailure(f"[ERROR]: {name} concrete replay fails after init solving")


def replace_branch_jump(inst):
    """
    检查行首的8位十六进制数是否符合RISC-V分支指令的opcode(1100011),
    若符合则替换为00000263,并保留行格式.
    """
    # 匹配行首的8位十六进制数
    match = re.match(r"^\s*([0-9a-fA-F]{8})\b", inst)
    if not match:
        return inst

    hex_value = match.group(1)
    try:
        value = int(hex_value, 16)
        if (value & 0x7F) == 0x63:  # 0x63表示branch类型指令
            # 00000263表示beq x0, x0, 4
            new_inst = re.sub(r"" + hex_value, r"00000263", inst)
            return new_inst
        elif (value & 0x7F) == 0x6F:  # 0x6F表示j类型指令
            # 0040006f表示jal x0,4
            new_inst = re.sub(r"" + hex_value, r"" + r"0040006f", inst)
            return new_inst
        elif (value & 0x7F) == 0x67:  # 0x67表示jalr类型指令
            # 00402067表示jalr x0,4(x0)
            new_inst = re.sub(r"" + hex_value, r"" + r"00402067", inst)
            return new_inst
    except ValueError:
        pass

    return inst


def transform_for_profiling(filepath, output_path='', add_init: str = False, verbose: bool = False):
    def assemble_code(code: str, name: str, suffix: str = 'code'):
        """Output a file named {name}.code"""
        try:
            _write_profile_stage(name, f"assemble:{suffix}:compile")
            write_to_file(f'{OUTPUT_PATH / name}.S', code, append=False)
            run_cmd(f'{RISCV_GCC} {OUTPUT_PATH / name}.S -c -o {OUTPUT_PATH / name}.o')
            _write_profile_stage(name, f"assemble:{suffix}:objdump")
            output = run_cmd(f'{RISCV_OBJDUMP} -d {OUTPUT_PATH / name}.o')

            import re
            pattern = r'^\s*[0-9a-f]+:\s+(.*)'
            # pattern = r'^\s*[0-9a-f]+:\s+([0-9a-f]+)'
            codes = re.findall(pattern, output, re.MULTILINE)
            if codes and codes[-1].startswith('0000006f'):
                codes = codes[:-1]
            if codes:
                codes[-1] = replace_branch_jump(codes[-1])
            machine_code = '\n'.join(codes)
            _write_profile_stage(name, f"assemble:{suffix}:write")
            write_to_file(f'{OUTPUT_PATH / name}.{suffix}', machine_code, append=False)
            return machine_code
        except Exception as e:
            if not verbose:
                cleanup_resources(name)
            raise RuntimeError(f"Assemble code failed: {e}")

    def cleanup_resources(name):
        files_to_remove = [
            f"{OUTPUT_PATH / name}.S",
            f"{OUTPUT_PATH / name}.o",
            f"{OUTPUT_PATH / name}.code",
            f"{OUTPUT_PATH / name}.init",
            f"{OUTPUT_PATH / name}.exe"
        ]
        for file_path in files_to_remove:
            rm_file(file_path)

    # INFO(f'transform [{filepath}]')
    filepath = str(filepath)
    test_name = filepath.split('/')[-1].replace('.S', '')
    content = read_file(filepath) + '\n'
    failed = False
    error_msg = ""

    if output_path == '':
        output_path = f"{OUTPUT_PATH / test_name}"

    result = None
    try:
        # transform block
        _write_profile_stage(test_name, "transform:parse")
        prog = parse_program(content)
        for inst in prog.insts:
            if inst.get_addr() is XREG[0]:
                return f"SKIP: zero-base memory access at {inst.code}"
        constant_access = find_constant_nonstack_address_access(prog)
        if constant_access is not None:
            return f"SKIP: constant non-stack memory access at {constant_access.code}"
        # prog = zero_imm_for_block(prog)
        _write_profile_stage(test_name, "transform:legalize_branch")
        prog = legalize_jump_and_branch(prog)
        _write_profile_stage(test_name, "transform:remap_regs")
        prog = remap_regs_for_block(prog)
        _write_profile_stage(test_name, "transform:check_lui_auipc")
        if has_lui_auipc(prog):
            fixed_access = find_unmappable_fixed_address_access(prog)
            if fixed_access is not None:
                return f"SKIP: unmappable fixed address access at {fixed_access.code}"
            if os.environ.get("RVMCA_STRICT_LUI_AUIPC") == "1":
                return f"SKIP: unsupported lui/auipc block: {test_name}"
            prog = fix_lui_auipc_imm(prog)
        # if verbose:
        #     INFO(f'<Block>:\n{content}')
        #     INFO(f'<New Block>:\n{prog.code}')
        _write_profile_stage(test_name, "transform:init_states")
        try:
            init_insts = init_states_for_block(prog, name=test_name, verbose=verbose)
        except UnsupportedBlockError as e:
            return f"SKIP: {e}"
        except ConcreteReplayFailure as e:
            test_code = '\n'.join([inst.code for inst in prog.insts])
            if e.candidate_init:
                init_code = '\n'.join([inst.code for inst in e.candidate_init])
                write_to_file(f'{OUTPUT_PATH / test_name}.init.asm', init_code, append=False)
                assemble_code(init_code, test_name, suffix='init')
            write_to_file(f'{OUTPUT_PATH / test_name}.code.asm', test_code, append=False)
            assemble_code(test_code, test_name, suffix='code')
            raise
        _write_profile_stage(test_name, "transform:build_init_and_test_code")
        init_code = '\n'.join([inst.code for inst in init_insts])
        test_code = '\n'.join([inst.code for inst in prog.insts])
        write_to_file(f'{OUTPUT_PATH / test_name}.init.asm', init_code, append=False)
        write_to_file(f'{OUTPUT_PATH / test_name}.code.asm', test_code, append=False)

        if verbose:
            INFO('\n<New Block with init code>:')
            INFO('# init code')
            INFO(init_code)
            INFO('# test code')
            INFO(test_code)

        _write_profile_stage(test_name, "transform:assemble_init")
        assemble_code(init_code, test_name, suffix='init')  # test_name.init
        _write_profile_stage(test_name, "transform:assemble_code")
        assemble_code(test_code, test_name, suffix='code')  # test_name.code
        _write_profile_stage(test_name, "transform:pp_run")
        result = run_cmd(f"qemu-riscv64 {TOOLS_PATH / 'pp' / 'pp'} {output_path}.init {output_path}.code")

        if not result:
            _write_profile_stage(test_name, "transform:pp_failed_write_error")
            run_cmd(f"echo '# init code' > {output_path}.error")
            run_cmd(f"cat {OUTPUT_PATH / test_name}.init >> {output_path}.error")
            run_cmd(f"echo '\n\n# test code' >> {output_path}.error")
            run_cmd(f"cat {OUTPUT_PATH / test_name}.code >> {output_path}.error")
            run_cmd(f"echo '\n\nError: pp fails.' >> {output_path}.error")
        # rm_file(f"{OUTPUT_PATH / test_name}.code")
        # rm_file(f"{OUTPUT_PATH / test_name}.init")
        # else:
        # run_cmd(f"mv {OUTPUT_PATH / test_name}.code {output_path}.code")
        # run_cmd(f"mv {OUTPUT_PATH / test_name}.init {output_path}.init")
        assert result, "Error: pp fails."
        _write_profile_stage(test_name, "transform:done")
    except UnsupportedBlockError as e:
        return f"SKIP: {e}"
    except Exception as e:
        import traceback
        traceback.print_exc()
        error_msg = e
        failed = True
    finally:
        rm_file(f"{OUTPUT_PATH / test_name}.o")
        rm_file(f"{OUTPUT_PATH / test_name}.S")
        rm_file(f"{OUTPUT_PATH / test_name}.exe")
        if not failed:
            # INFO(f'Successfully!\n')
            pass
        # else:
        #     raise AssertionError(error_msg)
